-- Generated schema-only warehouse baseline. No production rows or credentials.
-- Import overrides/security/auth are applied before any API service starts.
CREATE EXTENSION IF NOT EXISTS http WITH SCHEMA public;
CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA public;
CREATE EXTENSION IF NOT EXISTS pgjwt WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA extensions;
CREATE OR REPLACE FUNCTION auth.jwt() RETURNS jsonb LANGUAGE sql STABLE AS $$
  SELECT COALESCE(NULLIF(current_setting('request.jwt.claims', true), ''), '{}')::jsonb;
$$;
SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;


CREATE SCHEMA IF NOT EXISTS public;


CREATE SCHEMA utils;


CREATE TYPE public.pricing_mode AS ENUM (
    'ONE_TIME',
    'MONTHLY'
);


CREATE TYPE public.user_role AS ENUM (
    'admin',
    'supervisor',
    'staff',
    'user',
    'customer'
);


CREATE FUNCTION public.acknowledge_voucher_drift(p_drift_id uuid, p_notes text DEFAULT NULL::text, p_acknowledged_by text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    UPDATE public.tally_drift_log
       SET acknowledged_at = now(),
           acknowledged_by = COALESCE(p_acknowledged_by, acknowledged_by),
           notes           = COALESCE(p_notes, notes)
     WHERE id = p_drift_id
       AND acknowledged_at IS NULL;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false,
            'error', 'drift entry not found or already acknowledged');
    END IF;

    RETURN jsonb_build_object('success', true);
END;
$$;


CREATE FUNCTION public.add_item_to_order(p_order_id uuid, p_grn_item_id uuid, p_quantity integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_user_id UUID;
      v_order_record RECORD;
      v_grn_item RECORD;
      v_new_item_id UUID;
      v_cart_items JSONB;
      v_order_no TEXT;
  BEGIN
      -- Get authenticated user
      SELECT id INTO v_user_id FROM user_profiles WHERE auth_user_id = auth.uid();
      IF v_user_id IS NULL THEN
          RETURN jsonb_build_object('success', false, 'message', 'User not authenticated');
      END IF;

      -- Validate order exists and check permissions
      SELECT o.*, c.name as customer_name
      INTO v_order_record
      FROM orders o
      JOIN customers c ON c.id = o.customer_id
      WHERE o.id = p_order_id;

      IF NOT FOUND THEN
          RETURN jsonb_build_object('success', false, 'message', 'Order not found');
      END IF;

      -- Check if order is in OPEN status (NEW: status validation)
      IF v_order_record.status != 'OPEN' THEN
          RETURN jsonb_build_object(
              'success', false,
              'message', 'Cannot add items to ' || v_order_record.status || ' orders',
              'error', jsonb_build_object('code', 'ORDER_NOT_OPEN')
          );
      END IF;

      -- Check permissions (FIX: corrected array membership check)
      IF NOT is_admin_or_supervisor() THEN
          IF NOT (v_order_record.customer_id = ANY(user_accessible_customers())) THEN
              RETURN jsonb_build_object('success', false, 'message', 'Access denied');
          END IF;
      END IF;

      -- Generate order_no if it's NULL or empty
      IF v_order_record.order_no IS NULL OR v_order_record.order_no = '' THEN
          v_order_no := 'ORD-' || TO_CHAR(CURRENT_DATE, 'YYYYMMDD') || '-' || SUBSTRING(p_order_id::text FROM 1 FOR 8);

          -- Update the order with the generated order_no
          UPDATE orders
          SET order_no = v_order_no
          WHERE id = p_order_id;
      ELSE
          v_order_no := v_order_record.order_no;
      END IF;

      -- Get GRN item details
      SELECT
          gt.*,
          g.gr_no,
          g.date as gr_date,
          g.customer_id,
          g.customer_name,
          g.gr_image_url
      INTO v_grn_item
      FROM goodsreceived_trl gt
      JOIN goodsreceived g ON g.id = gt.gr_id
      WHERE gt.id = p_grn_item_id;

      IF NOT FOUND THEN
          RETURN jsonb_build_object('success', false, 'message', 'GRN item not found');
      END IF;

      -- Check if item already exists in order
      IF EXISTS (
          SELECT 1 FROM order_items
          WHERE order_id = p_order_id AND grn_items_id = p_grn_item_id
      ) THEN
          RETURN jsonb_build_object('success', false, 'message', 'Item already exists in order');
      END IF;

      -- Check stock availability
      IF v_grn_item.stock < p_quantity THEN
          RETURN jsonb_build_object(
              'success', false,
              'message', format('Insufficient stock. Available: %s, Requested: %s', v_grn_item.stock, p_quantity)
          );
      END IF;

      -- Insert new order item
      INSERT INTO order_items (
          order_id,
          order_no,
          requested_quantity,
          grn_items_id,
          grn_items_item_id,
          grn_items_item_name,
          grn_items_package_mark,
          grn_items_packaging,
          grn_items_rack,
          grn_items_weight,
          grn_items_image_url,
          grns_id,
          grns_gr_no,
          grns_date,
          grns_customer_id,
          grns_customer_name,
          available_stock_at_order,
          current_stock,
          item_status,
          sort_order
      ) VALUES (
          p_order_id,
          v_order_no,
          p_quantity,
          p_grn_item_id,
          v_grn_item.item_id,
          v_grn_item.item_name,
          v_grn_item.package_mark,
          v_grn_item.packaging,
          v_grn_item.rack,
          v_grn_item.weight,
          v_grn_item.trl_img_url,
          v_grn_item.gr_id,
          v_grn_item.gr_no,
          v_grn_item.gr_date,
          v_grn_item.customer_id,
          v_grn_item.customer_name,
          v_grn_item.stock,
          v_grn_item.stock,
          'pending',
          COALESCE((SELECT MAX(sort_order) + 1 FROM order_items WHERE order_id = p_order_id), 1)
      ) RETURNING id INTO v_new_item_id;

      -- Get all cart items after addition
      SELECT jsonb_agg(
          jsonb_build_object(
              'item_id', grn_items_item_id,
              'item_name', grn_items_item_name,
              'quantity', requested_quantity,
              'grn_no', grns_gr_no,
              'package_mark', grn_items_package_mark
          ) ORDER BY sort_order
      ) INTO v_cart_items
      FROM order_items
      WHERE order_id = p_order_id;

      -- Update order with revision
      UPDATE orders
      SET
          revisions = revisions || jsonb_build_array(
              jsonb_build_object(
                  'at', NOW(),
                  'by', v_user_id,
                  'action', 'UPDATE',
                  'cart_items', COALESCE(v_cart_items, '[]'::jsonb),
                  'changes', jsonb_build_object(
                      'note', note,
                      'priority', priority,
                      'requested_dispatch_date', requested_dispatch_date
                  )
              )
          ),
          updated_at = NOW(),
          updated_by = v_user_id
      WHERE id = p_order_id;

      RETURN jsonb_build_object(
          'success', true,
          'message', 'Item added to order successfully',
          'data', jsonb_build_object(
              'order_item_id', v_new_item_id,
              'item_name', v_grn_item.item_name,
              'quantity', p_quantity,
              'order_no', v_order_no
          )
      );
  EXCEPTION
      WHEN OTHERS THEN
          RETURN jsonb_build_object(
              'success', false,
              'message', 'Error adding item: ' || SQLERRM
          );
  END;
$$;


CREATE FUNCTION public.assign_customer_to_user(target_user_mobile character varying, target_customer_id uuid, assigner_comment text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      target_user_id uuid;
      customer_name_val varchar(80);
      assigner_id uuid;
  BEGIN
      -- Check if current user is admin or supervisor
      IF NOT is_admin_or_supervisor() THEN
          RAISE EXCEPTION 'Only admins and supervisors can assign customers to users';
      END IF;

      -- Get target user profile ID by mobile (changed from email)
      SELECT id INTO target_user_id
      FROM user_profiles
      WHERE mobile = target_user_mobile AND active = true;

      IF target_user_id IS NULL THEN
          RAISE EXCEPTION 'User with mobile % not found or inactive', target_user_mobile;
      END IF;

      -- Get customer name
      SELECT name INTO customer_name_val
      FROM customers
      WHERE id = target_customer_id AND active = true;

      IF customer_name_val IS NULL THEN
          RAISE EXCEPTION 'Customer with ID % not found or inactive', target_customer_id;
      END IF;

      -- Get assigner ID
      SELECT id INTO assigner_id
      FROM user_profiles
      WHERE auth_user_id = auth.uid();

      -- Insert or update assignment
      INSERT INTO users_customers_new (
          user_profile_id,
          customer_id,
          customer_name,
          assigned_by,
          active
      ) VALUES (
          target_user_id,
          target_customer_id,
          customer_name_val,
          assigner_id,
          true
      )
      ON CONFLICT (user_profile_id, customer_id)
      DO UPDATE SET
          active = true,
          assigned_at = now(),
          assigned_by = assigner_id,
          customer_name = customer_name_val;

      RETURN true;
  END;
$$;


CREATE FUNCTION public.audit_trigger_func() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    INSERT INTO public.audit_log (table_name, action, user_id, old_data, new_data)
    VALUES (
        TG_TABLE_NAME,
        TG_OP,
        NULLIF(current_setting('request.jwt.claims', true)::json->>'sub', '')::UUID,
        CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN to_jsonb(OLD) ELSE NULL END,
        CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN to_jsonb(NEW) ELSE NULL END
    );
    RETURN COALESCE(NEW, OLD);
EXCEPTION
    WHEN OTHERS THEN
        -- Log warning but don't block the operation - audit failure shouldn't stop business operations
        RAISE WARNING 'audit_trigger_func failed for table % operation %: % - %', TG_TABLE_NAME, TG_OP, SQLSTATE, SQLERRM;
        RETURN COALESCE(NEW, OLD);
END;
$$;


CREATE FUNCTION public.auto_cleanup_expired_otps() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
  BEGIN
      -- Run cleanup every 100 OTP insertions
      IF (SELECT COUNT(*) FROM public.otp_verifications) % 100 = 0 THEN
          PERFORM public.cleanup_expired_otps();
      END IF;

      RETURN NEW;
  END;
  $$;


CREATE FUNCTION public.auto_generate_invoice_for_dispatch(p_dispatch_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
      DECLARE
          dispatch_record RECORD;
          grn_record RECORD;
          invoice_id UUID;
          invoice_number_str VARCHAR(20);
          invoice_number_int INTEGER;
          fin_year INTEGER;
          result JSONB;
          success_val TEXT;
          v_invoice_creation_time TIMESTAMPTZ;
          v_header_data JSONB;
          v_items_data JSONB;
          v_error_details JSONB;
          v_items_count INTEGER;
          v_duration_mode text;
      BEGIN
          SELECT * INTO dispatch_record FROM dispatch WHERE id = p_dispatch_id;
          IF NOT FOUND THEN
              RETURN jsonb_build_object('success', false, 'error', 'Dispatch record not found', 'error_code', 'DISPATCH_NOT_FOUND', 'dispatch_id', p_dispatch_id);
          END IF;

          SELECT gr.* INTO grn_record FROM goodsreceived gr JOIN dispatch_trl dt ON dt.gr_id = gr.id WHERE dt.disp_id = p_dispatch_id LIMIT 1;
          IF NOT FOUND THEN
              RETURN jsonb_build_object('success', false, 'error', 'No GRN record found for dispatch', 'error_code', 'GRN_NOT_FOUND', 'dispatch_id', p_dispatch_id);
          END IF;

          IF EXISTS (SELECT 1 FROM invoice WHERE gr_id = grn_record.id) THEN
              RETURN jsonb_build_object('success', false, 'error', 'Invoice already exists for this GRN', 'error_code', 'DUPLICATE_INVOICE', 'gr_no', grn_record.gr_no, 'gr_id', grn_record.id);
          END IF;

          -- Read duration_mode from GRN, default to 'legacy'
          v_duration_mode := COALESCE(grn_record.duration_mode, 'legacy');

          SELECT generate_invoice_data_for_grn_with_pricing(grn_record.id, v_duration_mode) INTO result;
          success_val := result->>'success';

          IF success_val != 'true' THEN
              v_error_details := jsonb_build_object('dispatch_id', p_dispatch_id, 'gr_id', grn_record.id, 'gr_no', grn_record.gr_no, 'customer_id', dispatch_record.customer_id, 'generation_error', result->>'error', 'generation_result', result);
              INSERT INTO auto_invoice_errors (customer_id, customer_name, gr_id, gr_no, gr_date, error_code, error_message, error_details)
              VALUES (dispatch_record.customer_id, dispatch_record.customer_name, grn_record.id, grn_record.gr_no, grn_record.date, 'PRICING_ERROR', COALESCE(result->>'error', 'Failed to generate invoice data'), v_error_details);
              RETURN jsonb_build_object('success', false, 'error', COALESCE(result->>'error', 'Failed to generate invoice data'), 'error_code', 'PRICING_ERROR', 'details', v_error_details);
          END IF;

          v_header_data := result->'invoice_data'->'header';
          v_items_data := result->'invoice_data'->'items';

          IF v_header_data IS NULL OR v_items_data IS NULL THEN
              v_error_details := jsonb_build_object('dispatch_id', p_dispatch_id, 'gr_id', grn_record.id, 'result_structure', jsonb_build_object('has_invoiceData', result ? 'invoice_data', 'has_header', result->'invoice_data' ? 'header', 'has_items', result->'invoice_data' ? 'items', 'header_data', v_header_data, 'items_count', jsonb_array_length(v_items_data)));
              INSERT INTO auto_invoice_errors (customer_id, customer_name, gr_id, gr_no, gr_date, error_code, error_message, error_details)
              VALUES (dispatch_record.customer_id, dispatch_record.customer_name, grn_record.id, grn_record.gr_no, grn_record.date, 'DATA_STRUCTURE_ERROR', 'Invalid invoice data structure', v_error_details);
              RETURN jsonb_build_object('success', false, 'error', 'Invalid invoice data structure', 'error_code', 'DATA_STRUCTURE_ERROR', 'details', v_error_details);
          END IF;

          invoice_number_str := v_header_data->>'invoice_number';
          invoice_number_int := (v_header_data->>'invoice_number_raw')::INTEGER;
          fin_year := SPLIT_PART(v_header_data->>'financial_year', '-', 1)::INTEGER;
          invoice_id := gen_random_uuid();
          v_invoice_creation_time := NOW();

          BEGIN
              INSERT INTO invoice (id, inv_fin_year, inv_no, gr_id, gr_no, customer_id, customer_name, inv_date, is_auto_generated, pricing_mode, duration_mode, labour, tax_amount, total, notes, created_by)
              VALUES (invoice_id, fin_year, invoice_number_int, grn_record.id, grn_record.gr_no, dispatch_record.customer_id, dispatch_record.customer_name, v_invoice_creation_time, true, grn_record.pricing_mode, v_duration_mode, 0, (v_header_data->>'total_tax')::NUMERIC(12,2), (v_header_data->>'grand_total')::NUMERIC(12,2), 'Auto-generated invoice for dispatch ' || dispatch_record.disp_no, NULL);
          EXCEPTION
              WHEN OTHERS THEN
                  v_error_details := jsonb_build_object('dispatch_id', p_dispatch_id, 'gr_id', grn_record.id, 'invoice_insert_error', SQLERRM, 'sqlstate', SQLSTATE, 'header_data', v_header_data);
                  INSERT INTO auto_invoice_errors (customer_id, customer_name, gr_id, gr_no, gr_date, error_code, error_message, error_details)
                  VALUES (dispatch_record.customer_id, dispatch_record.customer_name, grn_record.id, grn_record.gr_no, grn_record.date, 'INVOICE_INSERT_ERROR', 'Failed to insert invoice: ' || SQLERRM, v_error_details);
                  RETURN jsonb_build_object('success', false, 'error', 'Failed to insert invoice: ' || SQLERRM, 'error_code', 'INVOICE_INSERT_ERROR', 'details', v_error_details);
          END;

          UPDATE goodsreceived SET invoiced = true WHERE id = grn_record.id;

          BEGIN
              INSERT INTO invoice_trl (invoice_id, disp_trl_id, duration, no_of_days, charge, tax, labour_rate)
              SELECT
                  invoice_id,
                  (item->>'dispatch_trl_id')::uuid,
                  (item->>'duration_months')::double precision,
                  (item->>'billable_days')::integer,
                  (item->>'taxable_amount')::NUMERIC(12,2),
                  (item->>'tax_amount')::NUMERIC(12,2),
                  (item->>'labour_rate')::numeric(12,2)
              FROM jsonb_array_elements(v_items_data) AS item;

              GET DIAGNOSTICS v_items_count = ROW_COUNT;
          EXCEPTION
              WHEN OTHERS THEN
                  v_error_details := jsonb_build_object('dispatch_id', p_dispatch_id, 'gr_id', grn_record.id, 'invoice_id', invoice_id, 'items_insert_error', SQLERRM, 'sqlstate', SQLSTATE, 'items_data', v_items_data);
                  DELETE FROM invoice WHERE id = invoice_id;
                  UPDATE goodsreceived SET invoiced = false WHERE id = grn_record.id;
                  INSERT INTO auto_invoice_errors (customer_id, customer_name, gr_id, gr_no, gr_date, error_code, error_message, error_details)
                  VALUES (dispatch_record.customer_id, dispatch_record.customer_name, grn_record.id, grn_record.gr_no, grn_record.date, 'ITEMS_INSERT_ERROR', 'Failed to insert invoice items: ' || SQLERRM, v_error_details);
                  RETURN jsonb_build_object('success', false, 'error', 'Failed to insert invoice items: ' || SQLERRM, 'error_code', 'ITEMS_INSERT_ERROR', 'details', v_error_details);
          END;

          UPDATE auto_invoice_errors SET resolved_at = v_invoice_creation_time, resolved_invoice_id = invoice_id, error_details = COALESCE(error_details, '{}')::jsonb || jsonb_build_object('resolution_type', 'auto_invoice_generated', 'invoice_id', invoice_id, 'invoice_number', invoice_number_str) WHERE gr_id = grn_record.id AND resolved_at IS NULL;

          RETURN jsonb_build_object('success', true, 'invoice_id', invoice_id, 'invoice_number', invoice_number_str, 'gr_no', grn_record.gr_no, 'customer_name', dispatch_record.customer_name, 'items_count', v_items_count, 'duration_mode', v_duration_mode, 'function_version', 'auto_generate_v20260503_duration_mode');

      EXCEPTION WHEN OTHERS THEN
          RETURN jsonb_build_object('success', false, 'error', SQLERRM, 'error_code', SQLSTATE);
      END;
$$;


CREATE FUNCTION public.auto_update_item_status() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.item_status := CASE
        WHEN COALESCE(NEW.fulfilled_quantity, 0) >= NEW.requested_quantity THEN 'fulfilled'
        WHEN COALESCE(NEW.fulfilled_quantity, 0) > 0 THEN 'partially_fulfilled'
        ELSE 'pending'
    END;
    RETURN NEW;
END;
$$;


CREATE FUNCTION public.backfill_matched_receipts(p_since date DEFAULT NULL::date, p_batch_size integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_enqueued    INT := 0;
    v_skipped     INT := 0;
    v_errors      INT := 0;
    v_first_err   TEXT := NULL;
    v_total       INT := 0;
    v_row         RECORD;
    v_enq         JSONB;
BEGIN
    FOR v_row IN
        SELECT bsl.id, bsl.tran_date
        FROM public.bank_statement_lines bsl
        WHERE bsl.status = 'matched'
          AND bsl.tally_sync_queue_id IS NULL
          AND (p_since IS NULL OR bsl.tran_date >= p_since)
        ORDER BY bsl.tran_date ASC, bsl.id ASC
        LIMIT p_batch_size
    LOOP
        v_total := v_total + 1;

        BEGIN
            SELECT public.enqueue_receipt_voucher(v_row.id) INTO v_enq;

            IF (v_enq->>'success')::BOOLEAN = true THEN
                IF (v_enq->'data'->>'already_queued')::BOOLEAN IS TRUE THEN
                    v_skipped := v_skipped + 1;
                ELSE
                    v_enqueued := v_enqueued + 1;
                END IF;
            ELSE
                v_errors := v_errors + 1;
                v_first_err := COALESCE(v_first_err, v_enq->>'error');
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_errors := v_errors + 1;
            v_first_err := COALESCE(v_first_err, SQLERRM);
        END;
    END LOOP;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'enqueued',             v_enqueued,
            'skipped_already_queued', v_skipped,
            'error_count',          v_errors,
            'first_failure_reason', v_first_err,
            'total_processed',      v_total,
            'batch_size',           p_batch_size,
            'since',                p_since
        )
    );
END;
$$;


CREATE FUNCTION public.begin_tally_sync_attempt(p_queue_id uuid, p_voucher_number text, p_remote_id text, p_instance_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_prior_id          UUID;
    v_prior_voucher     TEXT;
    v_prior_remote      TEXT;
    v_prior_started_at  TIMESTAMPTZ;
    v_prior_instance    TEXT;
    v_attempt_id        UUID;
    v_entity_type       TEXT;
    v_entity_id         UUID;
BEGIN
    -- Resolve the queue row (also confirms it exists)
    SELECT entity_type, entity_id INTO v_entity_type, v_entity_id
      FROM public.tally_sync_queue WHERE id = p_queue_id;

    IF v_entity_type IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Queue item not found');
    END IF;

    -- Atomically close any prior open attempts for this queue item, capturing
    -- the most recent one so the middleware can verify Tally-side state.
    WITH supersede AS (
        UPDATE public.tally_sync_attempts
           SET completed_at = now(),
               outcome      = 'unknown',
               notes        = COALESCE(notes || E'\n', '') || 'superseded by new attempt at ' || now()::text
         WHERE queue_id = p_queue_id
           AND completed_at IS NULL
        RETURNING id, voucher_number, remote_id, started_at, instance_id
    )
    SELECT id, voucher_number, remote_id, started_at, instance_id
      INTO v_prior_id, v_prior_voucher, v_prior_remote, v_prior_started_at, v_prior_instance
      FROM supersede
     ORDER BY started_at DESC
     LIMIT 1;

    -- Open the new attempt
    INSERT INTO public.tally_sync_attempts
        (queue_id, entity_type, entity_id, voucher_number, remote_id, instance_id)
    VALUES
        (p_queue_id, v_entity_type, v_entity_id, p_voucher_number, p_remote_id, p_instance_id)
    RETURNING id INTO v_attempt_id;

    RETURN jsonb_build_object(
        'success',        true,
        'attempt_id',     v_attempt_id,
        'has_open_prior', v_prior_id IS NOT NULL,
        'prior_attempt', CASE WHEN v_prior_id IS NULL THEN NULL ELSE
            jsonb_build_object(
                'id',              v_prior_id,
                'voucher_number',  v_prior_voucher,
                'remote_id',       v_prior_remote,
                'started_at',      v_prior_started_at,
                'instance_id',     v_prior_instance
            )
        END
    );
END;
$$;


CREATE FUNCTION public.build_invoice_recalculation_rows(p_gr_id uuid, p_duration_mode text DEFAULT 'legacy'::text, p_invoice_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_duration_mode text;
    v_grn_date date;
    v_grn_customer_id uuid;
    v_grn_pricing_mode text;
    v_dispatch_rows jsonb[] := ARRAY[]::jsonb[];
    v_dispatch_record record;
    v_duration_record record;
    v_price_record item_storage_prices;
    v_unit_price numeric(12,2);
    v_labour_rate numeric(12,2);
    v_tax_percent numeric(5,2);
    v_storage_amount numeric(12,2);
    v_labour_amount numeric(12,2);
    v_base_amount numeric(12,2);
    v_tax_amount numeric(12,2);
    v_tax_total_basis numeric := 0;
    v_total_amount numeric(12,2);
    v_missing_prices text[] := ARRAY[]::text[];
    v_subtotal numeric(12,2) := 0;
    v_total_tax numeric(12,2) := 0;
    v_grand_total numeric(12,2) := 0;
    v_row_counter integer := 0;
BEGIN
    v_duration_mode := public.validate_invoice_duration_mode(p_duration_mode);

    SELECT date, customer_id, pricing_mode
    INTO v_grn_date, v_grn_customer_id, v_grn_pricing_mode
    FROM goodsreceived
    WHERE id = p_gr_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'GRN not found');
    END IF;

    FOR v_dispatch_record IN
        SELECT
            it.id as invoice_item_id,
            grt.id as grn_items_id,
            grt.item_id as grn_items_item_id,
            grt.item_name as grn_items_item_name,
            grt.qty as grn_items_original_qty,
            grt.stock as grn_items_current_stock,
            grt.packaging as grn_items_packaging,
            grt.package_mark as grn_items_package_mark,
            grt.rack as grn_items_rack,
            grt.weight as grn_items_weight,
            gr.pricing_mode as grn_items_pricing_mode,
            dt.id as dispatches_items_id,
            dt.disp_qty as dispatches_items_disp_qty,
            d.id as dispatches_id,
            d.disp_no as dispatches_no,
            d.disp_date as dispatches_date,
            d.registration as dispatches_vehicle,
            d.customer_name as dispatches_customer_name,
            i.name as items_catalog_name,
            i.description as items_description,
            i.packaging as items_packaging,
            (SELECT COALESCE(SUM(dt2.disp_qty), 0) FROM dispatch_trl dt2 WHERE dt2.gr_trl_id = grt.id) as grn_items_total_dispatched,
            it.charge as existing_charge,
            it.labour_rate as existing_labour_rate,
            it.tax as existing_tax
        FROM goodsreceived_trl grt
        JOIN dispatch_trl dt ON dt.gr_trl_id = grt.id
        JOIN dispatch d ON d.id = dt.disp_id
        JOIN goodsreceived gr ON gr.id = grt.gr_id
        LEFT JOIN items i ON i.id = grt.item_id
        LEFT JOIN invoice_trl it ON it.disp_trl_id = dt.id AND it.invoice_id = p_invoice_id
        WHERE grt.gr_id = p_gr_id
        ORDER BY grt.item_name, d.disp_date, dt.id
    LOOP
        v_row_counter := v_row_counter + 1;

        SELECT * INTO v_duration_record
        FROM public.calculate_invoice_duration(v_grn_date, v_dispatch_record.dispatches_date::date, v_duration_mode);

        v_price_record := find_storage_price(
            v_dispatch_record.grn_items_item_id,
            v_grn_customer_id,
            v_dispatch_record.grn_items_weight,
            v_grn_date,
            LOWER(v_grn_pricing_mode)
        );

        v_unit_price := COALESCE(v_dispatch_record.existing_charge, v_price_record.unit_price);
        v_labour_rate := COALESCE(v_dispatch_record.existing_labour_rate, v_price_record.labour_rate, 0);
        v_tax_percent := COALESCE(v_dispatch_record.existing_tax, v_price_record.tax_percent, 0);

        IF v_unit_price IS NULL THEN
            IF NOT (v_dispatch_record.grn_items_item_name = ANY(v_missing_prices)) THEN
                v_missing_prices := v_missing_prices || v_dispatch_record.grn_items_item_name;
            END IF;
        END IF;

        IF v_dispatch_record.grn_items_pricing_mode = 'ONE_TIME' THEN
            v_storage_amount := ROUND(COALESCE(v_unit_price, 0) * v_dispatch_record.dispatches_items_disp_qty, 2);
            v_labour_amount := 0;
        ELSE
            v_storage_amount := ROUND(COALESCE(v_unit_price, 0) * v_dispatch_record.dispatches_items_disp_qty * v_duration_record.duration, 2);
            v_labour_amount := ROUND(COALESCE(v_labour_rate, 0) * v_dispatch_record.dispatches_items_disp_qty, 2);
        END IF;

        v_base_amount := v_storage_amount + v_labour_amount;
        v_tax_amount := ROUND(v_base_amount * COALESCE(v_tax_percent, 0) / 100.0, 2);
        v_total_amount := v_base_amount + v_tax_amount;

        v_subtotal := v_subtotal + v_base_amount;
        v_tax_total_basis := v_tax_total_basis + (v_base_amount * COALESCE(v_tax_percent, 0) / 100.0);

        v_dispatch_rows := v_dispatch_rows || (
            jsonb_build_object(
                'id', v_dispatch_record.invoice_item_id,
                'invoice_item_id', v_dispatch_record.invoice_item_id,
                'row_number', v_row_counter,
                'rowNumber', v_row_counter,
                'disp_trl_id', v_dispatch_record.dispatches_items_id,
                'dispatch_item_id', v_dispatch_record.dispatches_items_id,
                'dispatches_items_id', v_dispatch_record.dispatches_items_id,
                'grn_item_id', v_dispatch_record.grn_items_id,
                'grn_items_id', v_dispatch_record.grn_items_id,
                'grn_items_item_id', v_dispatch_record.grn_items_item_id,
                'grn_items_item_name', v_dispatch_record.grn_items_item_name,
                'item_id', v_dispatch_record.grn_items_item_id,
                'item_name', v_dispatch_record.grn_items_item_name,
                'grn_items_original_qty', v_dispatch_record.grn_items_original_qty,
                'original_qty', v_dispatch_record.grn_items_original_qty,
                'grn_items_current_stock', v_dispatch_record.grn_items_current_stock,
                'current_stock', v_dispatch_record.grn_items_current_stock,
                'grn_items_packaging', v_dispatch_record.grn_items_packaging,
                'item_packaging', v_dispatch_record.grn_items_packaging,
                'grn_items_package_mark', v_dispatch_record.grn_items_package_mark,
                'package_mark', v_dispatch_record.grn_items_package_mark,
                'grn_items_rack', v_dispatch_record.grn_items_rack,
                'rack', v_dispatch_record.grn_items_rack,
                'grn_items_weight', v_dispatch_record.grn_items_weight,
                'weight', v_dispatch_record.grn_items_weight
            )
            ||
            jsonb_build_object(
                'grn_items_total_dispatched', v_dispatch_record.grn_items_total_dispatched,
                'total_dispatched', v_dispatch_record.grn_items_total_dispatched,
                'grn_items_pricing_mode', v_dispatch_record.grn_items_pricing_mode,
                'dispatches_items_disp_qty', v_dispatch_record.dispatches_items_disp_qty,
                'dispatch_qty', v_dispatch_record.dispatches_items_disp_qty,
                'qty', v_dispatch_record.dispatches_items_disp_qty,
                'dispatches_id', v_dispatch_record.dispatches_id,
                'dispatch_id', v_dispatch_record.dispatches_id,
                'dispatches_no', v_dispatch_record.dispatches_no,
                'dispatch_no', v_dispatch_record.dispatches_no,
                'dispatches_date', v_dispatch_record.dispatches_date,
                'dispatch_date', v_dispatch_record.dispatches_date,
                'dispatches_vehicle', v_dispatch_record.dispatches_vehicle,
                'dispatch_vehicle', v_dispatch_record.dispatches_vehicle,
                'dispatches_customer_name', v_dispatch_record.dispatches_customer_name,
                'dispatch_customer_name', v_dispatch_record.dispatches_customer_name,
                'items_catalog_name', v_dispatch_record.items_catalog_name,
                'catalog_name', v_dispatch_record.items_catalog_name,
                'items_description', v_dispatch_record.items_description,
                'item_description', v_dispatch_record.items_description,
                'items_packaging', v_dispatch_record.items_packaging,
                'catalog_packaging', v_dispatch_record.items_packaging,
                'grn_date', v_grn_date,
                'no_of_days', v_duration_record.no_of_days,
                'calculated_days', v_duration_record.no_of_days
            )
            ||
            jsonb_build_object(
                'billable_days', v_duration_record.billable_days,
                'duration', v_duration_record.duration,
                'calculated_duration', v_duration_record.duration,
                'duration_mode', v_duration_mode,
                'unit_price', v_unit_price,
                'charge', v_unit_price,
                'labour_rate', v_labour_rate,
                'tax_percent', v_tax_percent,
                'tax', v_tax_percent,
                'storage_amount', v_storage_amount,
                'labour_amount', v_labour_amount,
                'base_amount', v_base_amount,
                'amount', v_base_amount,
                'item_amount', v_base_amount,
                'tax_amount', v_tax_amount,
                'item_tax', v_tax_amount,
                'total_amount', v_total_amount,
                'item_total', v_total_amount,
                'missing_price', v_unit_price IS NULL,
                'duration_calculation_note', format('Duration calculated from GRN date (%s) to dispatch date (%s) using %s mode',
                    v_grn_date, v_dispatch_record.dispatches_date::date, v_duration_mode)
            )
        );
    END LOOP;

    v_total_tax := CEIL(v_tax_total_basis);
    v_grand_total := CEIL(v_subtotal + v_total_tax);

    RETURN jsonb_build_object(
        'success', true,
        'rows', v_dispatch_rows,
        'items', v_dispatch_rows,
        'duration_mode', v_duration_mode,
        'missing_items', v_missing_prices,
        'totals', jsonb_build_object(
            'subtotal', v_subtotal,
            'tax', v_total_tax,
            'total_tax', v_total_tax,
            'grand_total', v_grand_total,
            'total', v_grand_total,
            'total_rows', v_row_counter
        )
    );
END;
$$;


CREATE FUNCTION public.bulk_update_customers_priority_contact() RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    customer_record RECORD;
    updated_count INTEGER := 0;
    total_count INTEGER := 0;
    priority_contact TEXT;
    results JSONB := '[]'::JSONB;
BEGIN
    -- Loop through all customers
    FOR customer_record IN SELECT id, name FROM customers ORDER BY name
    LOOP
        total_count := total_count + 1;

        -- Get priority contact for this customer
        priority_contact := get_priority_contact_for_customer(customer_record.id);

        -- Update if priority contact is different from stored contact
        IF priority_contact IS NOT NULL THEN
            UPDATE customers
            SET contact = priority_contact
            WHERE id = customer_record.id
            AND (contact IS NULL OR contact <> priority_contact);

            IF FOUND THEN
                updated_count := updated_count + 1;
                results := results || jsonb_build_object(
                    'customer_id', customer_record.id,
                    'customer_name', customer_record.name,
                    'new_contact', priority_contact
                );
            END IF;
        END IF;
    END LOOP;

    RETURN jsonb_build_object(
        'success', true,
        'total_customers', total_count,
        'updated_customers', updated_count,
        'updated_list', results
    );
END;
$$;


CREATE FUNCTION public.calculate_invoice_duration(p_grn_date date, p_dispatch_date date, p_duration_mode text DEFAULT 'legacy'::text) RETURNS TABLE(no_of_days integer, billable_days integer, duration numeric)
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    v_duration_mode text;
BEGIN
    v_duration_mode := public.validate_invoice_duration_mode(p_duration_mode);

    no_of_days := (p_dispatch_date - p_grn_date)::integer
        + CASE WHEN v_duration_mode = 'standard' THEN 1 ELSE 0 END;
    billable_days := GREATEST(1, no_of_days);
    duration := GREATEST(1, CEIL(billable_days::numeric / 15.0) / 2.0);

    RETURN NEXT;
END;
$$;


CREATE FUNCTION public.cancel_dispatch_image_upload(p_image_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_id UUID;
    v_storage_path TEXT;
BEGIN
    -- 1. Authenticate user
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Authentication required',
            'code', 'AUTH_REQUIRED'
        );
    END IF;

    -- 2. Get storage path before deletion (only delete pending records)
    SELECT storage_path INTO v_storage_path
    FROM dispatch_images
    WHERE id = p_image_id
    AND status = 'pending';

    IF v_storage_path IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Pending upload not found',
            'code', 'NOT_FOUND'
        );
    END IF;

    -- 3. Delete the pending record
    DELETE FROM dispatch_images
    WHERE id = p_image_id
    AND status = 'pending';

    -- 4. Return success with storage_path for frontend to delete from storage
    RETURN jsonb_build_object(
        'success', true,
        'storage_path', v_storage_path,
        'message', 'Upload cancelled. Frontend should delete from storage.'
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', 'Unexpected error: ' || SQLERRM,
        'code', 'INTERNAL_ERROR'
    );
END;
$$;


