CREATE FUNCTION public.cancel_invoice(p_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_invoice_record RECORD;
      v_user_id UUID;
  BEGIN
      -- Check if user is admin
      IF NOT EXISTS(SELECT 1 FROM user_profiles WHERE auth_user_id = auth.uid() AND role = 'admin') THEN
          RETURN jsonb_build_object(
              'success', false,
              'error', 'Only administrators can cancel invoices'
          );
      END IF;

      -- Get current user
      SELECT id INTO v_user_id FROM user_profiles WHERE auth_user_id = auth.uid();

      -- Get invoice record
      SELECT * INTO v_invoice_record FROM invoice WHERE id = p_invoice_id;

      IF NOT FOUND THEN
          RETURN jsonb_build_object(
              'success', false,
              'error', 'Invoice not found'
          );
      END IF;

      -- Delete invoice trail records
      DELETE FROM invoice_trl WHERE invoice_id = p_invoice_id;

      -- Delete invoice
      DELETE FROM invoice WHERE id = p_invoice_id;

      -- Update GRN invoiced status
      UPDATE goodsreceived
      SET invoiced = false
      WHERE id = v_invoice_record.gr_id;

      RETURN jsonb_build_object(
          'success', true,
          'invoice_id', p_invoice_id,
          'message', 'Invoice cancelled successfully'
      );

  EXCEPTION
      WHEN OTHERS THEN
          RETURN jsonb_build_object(
              'success', false,
              'error', SQLERRM
          );
  END;
  $$;


CREATE FUNCTION public.cancel_invoice(p_invoice_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_gr_id UUID;
    v_invoice_no VARCHAR(20);
BEGIN
    -- Get invoice details
    SELECT gr_id, CONCAT(inv_fin_year, '/', inv_no) INTO v_gr_id, v_invoice_no
    FROM invoice
    WHERE id = p_invoice_id;

    IF v_gr_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Invoice not found'
        );
    END IF;

    -- Soft delete by updating notes
    UPDATE invoice
    SET notes = COALESCE(notes, '') || ' [CANCELLED: ' || COALESCE(p_reason, 'No reason provided') || ']'
    WHERE id = p_invoice_id;

    -- Reset GRN invoiced flag
    UPDATE goodsreceived SET invoiced = false WHERE id = v_gr_id;

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Invoice cancelled successfully',
        'invoice_no', v_invoice_no,
        'gr_id', v_gr_id
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', SQLERRM
    );
END;
$$;


CREATE FUNCTION public.cancel_order(p_order_id uuid, p_reason text, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_order RECORD;
BEGIN
    SELECT * INTO v_order FROM orders WHERE id = p_order_id;
    IF v_order IS NULL THEN
        RETURN utils.not_found_response('Order', p_order_id::text);
    END IF;

    IF v_order.status = 'cancelled' THEN
        RETURN utils.error_response('ORDER_ALREADY_CANCELLED', 'Order is already cancelled');
    END IF;

    IF v_order.status = 'fulfilled' THEN
        RETURN utils.error_response('ORDER_ALREADY_FULFILLED', 'Cannot cancel a fulfilled order');
    END IF;

    UPDATE orders SET status = 'cancelled', cancelled_at = NOW(), cancelled_by = COALESCE(p_user_id, auth.uid()), cancel_reason = p_reason, updated_at = NOW()
    WHERE id = p_order_id;

    RETURN utils.success_response(jsonb_build_object('order_id', p_order_id), 'Order cancelled successfully');
EXCEPTION
    WHEN OTHERS THEN
        RETURN utils.database_error_response('Failed to cancel order', SQLERRM, SQLSTATE);
END;
$$;


CREATE FUNCTION public.cancel_print_job(p_print_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_role VARCHAR(20);
    v_job_user_id UUID;
    v_cups_job_id INTEGER;
    v_job_status VARCHAR(20);
BEGIN
    SELECT role INTO v_user_role FROM public.user_profiles WHERE id = auth.uid();

    IF v_user_role IS NULL THEN
        RETURN utils.not_authenticated_response();
    END IF;

    SELECT user_id, cups_job_id, status INTO v_job_user_id, v_cups_job_id, v_job_status
    FROM public.print_jobs WHERE id = p_print_job_id;

    IF v_job_user_id IS NULL THEN
        RETURN utils.not_found_response('Print job', p_print_job_id::text);
    END IF;

    IF v_job_user_id != auth.uid() AND v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        RETURN utils.error_response('PERMISSION_DENIED', 'Permission denied. You can only cancel your own print jobs.');
    END IF;

    IF v_job_status IN ('completed', 'cancelled', 'failed') THEN
        RETURN utils.error_response('INVALID_STATUS', 'Cannot cancel job with status: ' || v_job_status);
    END IF;

    UPDATE public.print_jobs SET status = 'cancelled', completed_at = NOW(), updated_at = NOW() WHERE id = p_print_job_id;

    RETURN utils.success_response(
        jsonb_build_object(
            'print_job_id', p_print_job_id,
            'cups_job_id', v_cups_job_id,
            'note', 'Call manage-print-jobs Edge Function to cancel CUPS job: ' || v_cups_job_id
        ),
        'Print job marked as cancelled'
    );
END;
$$;


CREATE FUNCTION public.check_cart_restoration_history(p_order_no text DEFAULT NULL::text, p_dispatch_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    SELECT jsonb_agg(jsonb_build_object(
        'order_id', sub.order_id,
        'order_no', sub.order_no,
        'item_name', sub.item_name,
        'packing_type', sub.packing_type,
        'weight', sub.weight,
        'current_qty', sub.current_qty,
        'restoration_history', sub.restoration_history
    ))
    INTO v_result
    FROM (
        SELECT
            o.id as order_id,
            o.order_no,
            i.name as item_name,
            p.type as packing_type,
            o.weight,
            o.qty as current_qty,
            CASE
                WHEN jsonb_typeof(o.revisions) = 'array' THEN
                    (SELECT COALESCE(jsonb_agg(rev), '[]'::jsonb)
                     FROM jsonb_array_elements(o.revisions) rev
                     WHERE rev->>'action' IN ('quantity_reduced_for_dispatch', 'quantity_restored')
                     AND (p_dispatch_id IS NULL OR rev->>'dispatch_id' = p_dispatch_id::text))
                ELSE '[]'::jsonb
            END as restoration_history
        FROM orders o
        LEFT JOIN item i ON i.id = o.item_id
        LEFT JOIN packing p ON p.id = o.packing
        WHERE (p_order_no IS NULL OR o.order_no = p_order_no)
        AND EXISTS (
            SELECT 1
            FROM jsonb_array_elements(CASE
                WHEN jsonb_typeof(o.revisions) = 'array' THEN o.revisions
                ELSE '[]'::jsonb
            END) rev
            WHERE rev->>'action' IN ('quantity_reduced_for_dispatch', 'quantity_restored')
            AND (p_dispatch_id IS NULL OR rev->>'dispatch_id' = p_dispatch_id::text)
        )
        ORDER BY o.order_no, i.name
    ) sub;

    RETURN jsonb_build_object(
        'success', true,
        'data', COALESCE(v_result, '[]'::jsonb)
    );
END;
$$;


CREATE FUNCTION public.check_dispatch_exists(p_disp_no text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_dispatch RECORD;
BEGIN
    SELECT id, disp_no, customer_name, disp_date INTO v_dispatch FROM dispatch WHERE disp_no = p_disp_no AND deleted_at IS NULL LIMIT 1;
    IF v_dispatch IS NULL THEN
        RETURN utils.success_response(jsonb_build_object('exists', false));
    END IF;
    RETURN utils.success_response(jsonb_build_object(
        'exists', true, 'dispatch_id', v_dispatch.id, 'disp_no', v_dispatch.disp_no, 'customer_name', v_dispatch.customer_name, 'date', v_dispatch.disp_date
    ));
END;
$$;


CREATE FUNCTION public.check_grn_exists(p_gr_no text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_grn RECORD;
BEGIN
    SELECT id, gr_no, customer_name, date INTO v_grn FROM goodsreceived WHERE gr_no = p_gr_no AND deleted_at IS NULL LIMIT 1;
    IF v_grn IS NULL THEN
        RETURN utils.success_response(jsonb_build_object('exists', false));
    END IF;
    RETURN utils.success_response(jsonb_build_object(
        'exists', true, 'grn_id', v_grn.id, 'gr_no', v_grn.gr_no, 'customer_name', v_grn.customer_name, 'date', v_grn.date
    ));
END;
$$;


CREATE FUNCTION public.check_invoice_exists(p_inv_fin_year integer, p_inv_no integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_invoice RECORD;
BEGIN
    SELECT id, inv_no, inv_fin_year, customer_name, inv_date INTO v_invoice
    FROM invoice
    WHERE inv_fin_year = p_inv_fin_year
      AND inv_no = p_inv_no
      AND deleted_at IS NULL
    LIMIT 1;

    IF v_invoice IS NULL THEN
        RETURN utils.success_response(jsonb_build_object('exists', false));
    END IF;

    RETURN utils.success_response(jsonb_build_object(
        'exists', true,
        'invoice_id', v_invoice.id,
        'inv_no', v_invoice.inv_no,
        'inv_fin_year', v_invoice.inv_fin_year,
        'customer_name', v_invoice.customer_name,
        'inv_date', v_invoice.inv_date
    ));
END;
$$;


CREATE FUNCTION public.check_ip_rate_limit(p_ip_address inet) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_rate_limit RECORD;
    v_hourly_limit INTEGER := 100;
    v_current_hour TIMESTAMP WITH TIME ZONE;
BEGIN
    IF p_ip_address IS NULL THEN
        RETURN utils.success_response(
            jsonb_build_object('allowed', true, 'remaining', v_hourly_limit),
            'IP rate limit check passed (no IP provided)'
        );
    END IF;

    v_current_hour := DATE_TRUNC('hour', NOW());

    INSERT INTO public.ip_rate_limits (ip_address)
    VALUES (p_ip_address)
    ON CONFLICT (ip_address) DO NOTHING;

    SELECT * INTO v_rate_limit FROM public.ip_rate_limits WHERE ip_address = p_ip_address;

    IF v_rate_limit.last_reset_hour < v_current_hour THEN
        UPDATE public.ip_rate_limits
        SET hourly_count = 0, last_reset_hour = v_current_hour, updated_at = NOW()
        WHERE ip_address = p_ip_address;
        v_rate_limit.hourly_count := 0;
    END IF;

    IF v_rate_limit.hourly_count >= v_hourly_limit THEN
        RETURN utils.error_response('RATE_LIMIT_EXCEEDED', 'IP rate limit exceeded. Please try again later.',
            'Limit: ' || v_hourly_limit || ' requests per hour');
    END IF;

    UPDATE public.ip_rate_limits
    SET hourly_count = hourly_count + 1, updated_at = NOW()
    WHERE ip_address = p_ip_address;

    RETURN utils.success_response(
        jsonb_build_object('allowed', true, 'remaining', v_hourly_limit - v_rate_limit.hourly_count - 1),
        'IP rate limit check passed'
    );
EXCEPTION
    WHEN OTHERS THEN
        RETURN utils.database_error_response('IP rate limit check failed', SQLERRM, SQLSTATE);
END;
$$;


CREATE FUNCTION public.check_otp_rate_limit(p_phone_number character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_phone_formatted VARCHAR(15);
    v_rate_limit RECORD;
    v_hourly_limit INTEGER := 40;
    v_daily_limit INTEGER := 20;
    v_current_hour TIMESTAMP WITH TIME ZONE;
    v_current_day TIMESTAMP WITH TIME ZONE;
BEGIN
    v_phone_formatted := REGEXP_REPLACE(p_phone_number, '[^0-9]', '', 'g');
    IF LENGTH(v_phone_formatted) = 10 THEN
        v_phone_formatted := '91' || v_phone_formatted;
    END IF;

    v_current_hour := DATE_TRUNC('hour', NOW());
    v_current_day := DATE_TRUNC('day', NOW());

    INSERT INTO public.otp_rate_limits (phone_number)
    VALUES (v_phone_formatted)
    ON CONFLICT (phone_number) DO NOTHING;

    SELECT * INTO v_rate_limit FROM public.otp_rate_limits WHERE phone_number = v_phone_formatted;

    IF v_rate_limit.last_reset_hour < v_current_hour THEN
        UPDATE public.otp_rate_limits
        SET hourly_count = 0, last_reset_hour = v_current_hour, updated_at = NOW()
        WHERE phone_number = v_phone_formatted;
        v_rate_limit.hourly_count := 0;
    END IF;

    IF v_rate_limit.last_reset_day < v_current_day THEN
        UPDATE public.otp_rate_limits
        SET daily_count = 0, last_reset_day = v_current_day, hourly_count = 0,
            last_reset_hour = v_current_hour, updated_at = NOW()
        WHERE phone_number = v_phone_formatted;
        v_rate_limit.daily_count := 0;
        v_rate_limit.hourly_count := 0;
    END IF;

    IF v_rate_limit.hourly_count >= v_hourly_limit THEN
        RETURN utils.error_response('OTP_RATE_LIMIT', 'Hourly OTP limit exceeded. Please try again later.',
            jsonb_build_object('hourly_remaining', 0, 'daily_remaining', v_daily_limit - v_rate_limit.daily_count)::text);
    ELSIF v_rate_limit.daily_count >= v_daily_limit THEN
        RETURN utils.error_response('OTP_RATE_LIMIT', 'Daily OTP limit exceeded. Please try again tomorrow.',
            jsonb_build_object('hourly_remaining', 0, 'daily_remaining', 0)::text);
    END IF;

    UPDATE public.otp_rate_limits
    SET hourly_count = hourly_count + 1, daily_count = daily_count + 1, updated_at = NOW()
    WHERE phone_number = v_phone_formatted;

    RETURN utils.success_response(
        jsonb_build_object(
            'allowed', true,
            'hourly_remaining', v_hourly_limit - v_rate_limit.hourly_count - 1,
            'daily_remaining', v_daily_limit - v_rate_limit.daily_count - 1
        ),
        'Rate limit check passed'
    );
EXCEPTION
    WHEN OTHERS THEN
        RETURN utils.database_error_response('Rate limit check failed', SQLERRM, SQLSTATE);
END;
$$;


CREATE FUNCTION public.check_session_validity() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_id UUID;
    v_last_activity TIMESTAMPTZ;
    v_inactive_duration INTERVAL;
BEGIN
    SELECT id INTO v_user_id
    FROM user_profiles
    WHERE auth_user_id = auth.uid();

    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('valid', FALSE, 'error', 'Not authenticated');
    END IF;

    -- Get last activity
    SELECT last_activity_at INTO v_last_activity
    FROM user_session_activity
    WHERE user_id = v_user_id
    ORDER BY last_activity_at DESC
    LIMIT 1;

    IF v_last_activity IS NULL THEN
        -- First activity, session is valid
        RETURN jsonb_build_object('valid', TRUE, 'first_activity', TRUE);
    END IF;

    v_inactive_duration := NOW() - v_last_activity;

    -- Check 15-minute inactivity timeout
    IF v_inactive_duration > INTERVAL '15 minutes' THEN
        RETURN jsonb_build_object(
            'valid', FALSE,
            'error', 'Session expired due to inactivity',
            'last_activity', v_last_activity,
            'inactive_duration_seconds', EXTRACT(EPOCH FROM v_inactive_duration)::INTEGER,
            'requires_reauth', TRUE
        );
    END IF;

    RETURN jsonb_build_object(
        'valid', TRUE,
        'last_activity', v_last_activity,
        'inactive_duration_seconds', EXTRACT(EPOCH FROM v_inactive_duration)::INTEGER,
        'time_until_timeout_seconds', (900 - EXTRACT(EPOCH FROM v_inactive_duration))::INTEGER
    );
END;
$$;


CREATE FUNCTION public.check_stock_availability(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_profile_id UUID;
    v_order_customer_id UUID;
    v_accessible_customers UUID[];
    v_total_requested INTEGER := 0;
    v_total_fulfillable INTEGER := 0;
    v_can_fulfill_all BOOLEAN := TRUE;
    v_fulfillment_pct NUMERIC;
    v_items_result JSONB;
    v_dispatch_items JSONB;
BEGIN
    -- Get user profile ID
    SELECT id INTO v_user_profile_id
    FROM user_profiles
    WHERE auth_user_id = auth.uid();

    IF v_user_profile_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', null,
            'message', 'User not authenticated'
        );
    END IF;

    -- Get order customer ID
    SELECT customer_id INTO v_order_customer_id
    FROM orders
    WHERE id = p_order_id;

    IF v_order_customer_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', null,
            'message', 'Order not found'
        );
    END IF;

    -- Check access permissions
    IF NOT is_admin_or_supervisor() THEN
        v_accessible_customers := user_accessible_customers();
        IF v_order_customer_id != ALL(v_accessible_customers) THEN
            RETURN jsonb_build_object(
                'success', false,
                'data', null,
                'message', 'Access denied'
            );
        END IF;
    END IF;

    -- Get items with current stock information
    SELECT jsonb_agg(
        jsonb_build_object(
            'id', oi.id,
            'grn_item_id', oi.grn_items_id,
            'item_name', oi.grn_items_item_name,
            'package_mark', oi.grn_items_package_mark,
            'packaging', oi.grn_items_packaging,
            'rack', oi.grn_items_rack,
            'weight', oi.grn_items_weight,
            'requested_qty', oi.requested_quantity,
            'fulfilled_quantity', oi.fulfilled_quantity,
            'available_stock_at_order', oi.available_stock_at_order,
            'current_stock', grt.stock,
            'available_qty', LEAST(grt.stock, oi.requested_quantity),
            'status', CASE
                WHEN grt.stock >= oi.requested_quantity THEN 'available'
                WHEN grt.stock > 0 THEN 'partial'
                ELSE 'unavailable'
            END,
            'shortage_quantity', GREATEST(0, oi.requested_quantity - grt.stock),
            'item_status', oi.item_status,
            'sort_order', oi.sort_order
        )
        ORDER BY oi.sort_order, oi.created_at
    ) INTO v_items_result
    FROM order_items oi
    LEFT JOIN goodsreceived_trl grt ON grt.id = oi.grn_items_id
    WHERE oi.order_id = p_order_id;

    -- Calculate fulfillment statistics
    SELECT
        SUM(oi.requested_quantity),
        SUM(LEAST(grt.stock, oi.requested_quantity)),
        BOOL_AND(grt.stock >= oi.requested_quantity)
    INTO v_total_requested, v_total_fulfillable, v_can_fulfill_all
    FROM order_items oi
    LEFT JOIN goodsreceived_trl grt ON grt.id = oi.grn_items_id
    WHERE oi.order_id = p_order_id;

    -- Calculate fulfillment percentage
    IF v_total_requested > 0 THEN
        v_fulfillment_pct := ROUND((v_total_fulfillable::NUMERIC / v_total_requested::NUMERIC) * 100, 2);
    ELSE
        v_fulfillment_pct := 0;
    END IF;

    -- Prepare dispatch items (only items with available stock)
    SELECT jsonb_agg(
        jsonb_build_object(
            'grn_items_id', oi.grn_items_id,
            'grn_items_item_id', oi.grn_items_item_id,
            'grn_items_item_name', oi.grn_items_item_name,
            'grn_items_package_mark', oi.grn_items_package_mark,
            'grn_items_packaging', oi.grn_items_packaging,
            'grn_items_rack', oi.grn_items_rack,
            'grn_items_weight', oi.grn_items_weight,
            'grns_id', oi.grns_id,
            'grns_gr_no', oi.grns_gr_no,
            'grns_date', oi.grns_date,
            'requested_quantity', oi.requested_quantity,
            'dispatch_quantity', LEAST(grt.stock, oi.requested_quantity),
            'available_stock', grt.stock
        )
    ) INTO v_dispatch_items
    FROM order_items oi
    LEFT JOIN goodsreceived_trl grt ON grt.id = oi.grn_items_id
    WHERE oi.order_id = p_order_id
    AND grt.stock > 0;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'order_id', p_order_id,
            'can_fulfill_completely', COALESCE(v_can_fulfill_all, false),
            'fulfillment_percentage', COALESCE(v_fulfillment_pct, 0),
            'items', COALESCE(v_items_result, '[]'::jsonb),
            'prepared_dispatch_items', COALESCE(v_dispatch_items, '[]'::jsonb)
        )
    );
END;
$$;


CREATE FUNCTION public.claim_tally_sync_item(p_instance_id text, p_entity_type text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_item public.tally_sync_queue;
BEGIN
    SELECT * INTO v_item
    FROM public.tally_sync_queue
    WHERE status IN ('pending', 'retry')
      AND (locked_by IS NULL OR locked_at < now() - INTERVAL '5 minutes')
      AND (next_retry_at IS NULL OR next_retry_at <= now())
      AND (p_entity_type IS NULL OR entity_type = p_entity_type)
      AND (
        entity_type <> 'receipt'
        OR NOT EXISTS (
          SELECT 1
          FROM bank_statement_lines bsl
          WHERE bsl.id = entity_id
            AND bsl.editing = true
        )
      )
    ORDER BY priority ASC, created_at ASC
    LIMIT 1
    FOR UPDATE SKIP LOCKED;

    IF v_item.id IS NULL THEN
        RETURN NULL;
    END IF;

    UPDATE public.tally_sync_queue
    SET status = 'processing',
        locked_by = p_instance_id,
        locked_at = now(),
        updated_at = now()
    WHERE id = v_item.id;

    RETURN jsonb_build_object(
        'success', true,
        'data', to_jsonb(v_item)
    );
END;
$$;


CREATE FUNCTION public.claim_vouchers_to_verify(p_instance_id text, p_batch_size integer DEFAULT 500, p_entity_type text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
BEGIN
    CREATE TEMP TABLE IF NOT EXISTS _vv_batch (
        voucher_table_id UUID,
        entity_type      TEXT,
        entity_id        UUID,
        tally_voucher_id TEXT,
        voucher_number   TEXT,
        voucher_date     DATE,
        expected_amount  NUMERIC
    ) ON COMMIT DROP;
    TRUNCATE _vv_batch;

    INSERT INTO _vv_batch
    SELECT voucher_table_id, entity_type, entity_id, tally_voucher_id,
           voucher_number, voucher_date, expected_amount
    FROM (
        SELECT 'invoice'::text  AS entity_type,
               tv.id            AS voucher_table_id,
               tv.invoice_id    AS entity_id,
               tv.tally_voucher_id, tv.voucher_number, tv.voucher_date,
               tv.amount        AS expected_amount,
               tv.last_verified_at
        FROM public.tally_vouchers tv
        JOIN public.invoice i ON i.id = tv.invoice_id
        WHERE tv.tally_voucher_id IS NOT NULL
          AND i.deleted_at IS NULL
          AND (p_entity_type IS NULL OR p_entity_type = 'invoice')
        UNION ALL
        SELECT 'receipt'::text,
               trv.id,
               trv.bank_line_id,
               trv.tally_voucher_id, trv.voucher_number, trv.voucher_date,
               trv.amount_received,
               trv.last_verified_at
        FROM public.tally_receipt_vouchers trv
        JOIN public.bank_statement_lines bsl ON bsl.id = trv.bank_line_id
        WHERE trv.tally_voucher_id IS NOT NULL
          AND bsl.status <> 'skipped'
          AND (p_entity_type IS NULL OR p_entity_type = 'receipt')
    ) candidates
    ORDER BY last_verified_at NULLS FIRST, voucher_table_id
    LIMIT p_batch_size;

    UPDATE public.tally_vouchers SET last_verified_at = now()
      WHERE id IN (SELECT voucher_table_id FROM _vv_batch WHERE entity_type = 'invoice');
    UPDATE public.tally_receipt_vouchers SET last_verified_at = now()
      WHERE id IN (SELECT voucher_table_id FROM _vv_batch WHERE entity_type = 'receipt');

    SELECT jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'vouchers', COALESCE(jsonb_agg(jsonb_build_object(
                'voucher_table_id', voucher_table_id,
                'entity_type',      entity_type,
                'entity_id',        entity_id,
                'tally_voucher_id', tally_voucher_id,
                'voucher_number',   voucher_number,
                'voucher_date',     voucher_date,
                'expected_amount',  expected_amount
            )), '[]'::jsonb),
            'batch_size',  p_batch_size,
            'instance_id', p_instance_id,
            'claimed_at',  now()
        )
    ) INTO v_result
    FROM _vv_batch;

    RETURN v_result;
END;
$$;


CREATE FUNCTION public.cleanup_expired_idempotency_keys() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_deleted_count integer;
BEGIN
    DELETE FROM idempotency_keys
    WHERE expires_at < now()
    RETURNING 1 INTO v_deleted_count;

    -- Get actual count
    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;

    RETURN COALESCE(v_deleted_count, 0);
END;
$$;


CREATE FUNCTION public.cleanup_expired_otps() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_deleted_count INTEGER;
  BEGIN
      DELETE FROM public.otp_verifications
      WHERE expires_at < NOW() - INTERVAL '1 hour'  -- Keep for 1 hour after expiry for logging
      OR (verified = TRUE AND verified_at < NOW() - INTERVAL '24 hours'); -- Clean verified OTPs after 24 hours

      GET DIAGNOSTICS v_deleted_count = ROW_COUNT;

      RETURN v_deleted_count;
  END;
  $$;


CREATE FUNCTION public.cleanup_intrusion_events() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    DELETE FROM intrusion_events WHERE recorded_at < NOW() - INTERVAL '7 days';
END;
$$;


CREATE FUNCTION public.cleanup_old_audit_logs() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    partition_name TEXT;
    cutoff_date DATE := CURRENT_DATE - INTERVAL '1 year';
BEGIN
    -- Drop partitions older than 1 year
    FOR partition_name IN
        SELECT tablename FROM pg_tables
        WHERE schemaname = 'public'
        AND tablename LIKE 'audit_log_%'
        AND tablename < 'audit_log_' || TO_CHAR(cutoff_date, 'YYYY_MM')
    LOOP
        EXECUTE format('DROP TABLE IF EXISTS public.%I', partition_name);
        RAISE NOTICE 'Dropped partition: %', partition_name;
    END LOOP;
END;
$$;


CREATE FUNCTION public.cleanup_orphaned_grn_images(p_max_age_hours integer DEFAULT 1) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_deleted_count integer;
    v_deleted_paths jsonb;
BEGIN
    -- Find and delete stale pending records (older than p_max_age_hours)
    -- Return the storage paths so the caller can delete from storage

    WITH deleted AS (
        DELETE FROM grn_images
        WHERE status = 'pending'
        AND created_at < NOW() - (p_max_age_hours || ' hours')::interval
        RETURNING storage_path
    )
    SELECT
        COUNT(*),
        COALESCE(jsonb_agg(storage_path), '[]'::jsonb)
    INTO v_deleted_count, v_deleted_paths
    FROM deleted;

    RETURN jsonb_build_object(
        'success', true,
        'deleted_count', v_deleted_count,
        'storage_paths', v_deleted_paths,
        'message', 'Cleanup completed. Delete these paths from storage.'
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', 'Cleanup error: ' || SQLERRM,
        'code', 'CLEANUP_ERROR'
    );
END;
$$;


CREATE FUNCTION public.confirm_dispatch_image_upload(p_image_id uuid, p_upload_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_id UUID;
    v_record RECORD;
BEGIN
    -- 1. Authenticate user
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Authentication required',
            'code', 'AUTH_REQUIRED'
        );
    END IF;

    -- 2. Find the pending record with matching token
    SELECT * INTO v_record
    FROM dispatch_images
    WHERE id = p_image_id
    AND upload_token = p_upload_token
    AND status = 'pending';

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Upload not found, already confirmed, or invalid token',
            'code', 'NOT_FOUND'
        );
    END IF;

    -- 3. Update status to confirmed
    UPDATE dispatch_images
    SET status = 'confirmed',
        upload_token = NULL,  -- Clear token after use
        updated_at = NOW()
    WHERE id = p_image_id;

    -- 4. Return success
    RETURN jsonb_build_object(
        'success', true,
        'image_id', v_record.id,
        'storage_path', v_record.storage_path,
        'dispatch_id', v_record.dispatch_id,
        'status', 'confirmed'
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', 'Unexpected error: ' || SQLERRM,
        'code', 'INTERNAL_ERROR'
    );
END;
$$;


CREATE FUNCTION public.confirm_grn_image_upload(p_image_id uuid, p_upload_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_id uuid;
    v_record RECORD;
BEGIN
    -- 1. Authenticate user
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Authentication required',
            'code', 'AUTH_REQUIRED'
        );
    END IF;

    -- 2. Find the pending record with matching token
    SELECT * INTO v_record
    FROM grn_images
    WHERE id = p_image_id
    AND upload_token = p_upload_token
    AND status = 'pending';

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Upload not found, already confirmed, or invalid token',
            'code', 'NOT_FOUND'
        );
    END IF;

    -- 3. Update status to confirmed
    UPDATE grn_images
    SET status = 'confirmed',
        upload_token = NULL,  -- Clear token after use
        updated_at = NOW()
    WHERE id = p_image_id;

    -- 4. Return success
    RETURN jsonb_build_object(
        'success', true,
        'image_id', v_record.id,
        'storage_path', v_record.storage_path,
        'grn_id', v_record.grn_id,
        'status', 'confirmed'
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', 'Unexpected error: ' || SQLERRM,
        'code', 'INTERNAL_ERROR'
    );
END;
$$;


CREATE FUNCTION public.confirm_tally_sync_attempt(p_attempt_id uuid, p_outcome text, p_response_xml text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    IF p_outcome NOT IN ('success', 'failure', 'duplicate_detected', 'aborted') THEN
        RETURN jsonb_build_object('success', false,
            'error', 'p_outcome must be one of success/failure/duplicate_detected/aborted');
    END IF;

    UPDATE public.tally_sync_attempts
       SET completed_at = COALESCE(completed_at, now()),
           outcome      = p_outcome,
           response_xml = COALESCE(p_response_xml, response_xml),
           notes        = COALESCE(p_notes, notes)
     WHERE id = p_attempt_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Attempt not found');
    END IF;

    RETURN jsonb_build_object('success', true);
END;
$$;


CREATE FUNCTION public.constant_time_compare(a text, b text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result BOOLEAN := TRUE;
    v_len_a INTEGER := LENGTH(a);
    v_len_b INTEGER := LENGTH(b);
    v_max_len INTEGER;
    i INTEGER;
    v_char_a TEXT;
    v_char_b TEXT;
BEGIN
    -- Always compare lengths (but don't early exit)
    v_result := v_result AND (v_len_a = v_len_b);
    v_max_len := GREATEST(v_len_a, v_len_b);

    -- Always iterate through all characters (prevents early exit timing leak)
    FOR i IN 1..v_max_len LOOP
        -- Get characters (or null if out of bounds)
        v_char_a := CASE WHEN i <= v_len_a THEN SUBSTRING(a FROM i FOR 1) ELSE '' END;
        v_char_b := CASE WHEN i <= v_len_b THEN SUBSTRING(b FROM i FOR 1) ELSE '' END;

        -- Compare characters (always executes, never early exits)
        v_result := v_result AND (v_char_a = v_char_b);
    END LOOP;

    -- Final check to ensure strings are truly equal
    RETURN v_result AND (a = b);
END;
$$;


CREATE FUNCTION public.convert_below_lakh(num integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    result TEXT := '';
    n INTEGER := num;
BEGIN
    IF n >= 1000 THEN
        result := result || convert_below_thousand(floor(n / 1000)::integer) || ' Thousand ';
        n := n % 1000;
    END IF;

    result := result || convert_below_thousand(n);
    RETURN TRIM(result);
END;
$$;


CREATE FUNCTION public.convert_below_thousand(num integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    ones TEXT[] := ARRAY['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine',
                        'Ten', 'Eleven', 'Twelve', 'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen',
                        'Seventeen', 'Eighteen', 'Nineteen'];
    tens TEXT[] := ARRAY['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];
    result TEXT := '';
    n INTEGER := num;
BEGIN
    IF n = 0 THEN
        RETURN '';
    END IF;

    -- Handle Hundreds
    IF n >= 100 THEN
        result := result || ones[floor(n / 100)::integer + 1] || ' Hundred ';
        n := n % 100;
    END IF;

    -- Handle below 100
    IF n >= 20 THEN
        result := result || tens[floor(n / 10)::integer + 1];
        n := n % 10;
        IF n > 0 THEN
            result := result || ' ';
        END IF;
    END IF;

    IF n > 0 AND n < 20 THEN
        result := result || ones[n + 1];
    END IF;

    RETURN TRIM(result);
END;
$$;


CREATE FUNCTION public.convert_number_to_words(p_num integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    ones TEXT[] := ARRAY['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine',
                        'Ten', 'Eleven', 'Twelve', 'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen',
                        'Seventeen', 'Eighteen', 'Nineteen'];
    tens TEXT[] := ARRAY['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];
    result TEXT := '';
    num INTEGER := p_num;
BEGIN
    IF num = 0 THEN
        RETURN 'Zero only';
    END IF;

    -- Handle Crores (10,000,000)
    IF num >= 10000000 THEN
        result := result || convert_below_lakh(floor(num / 10000000)::integer) || ' Crore ';
        num := num % 10000000;
    END IF;

    -- Handle Lakhs (100,000)
    IF num >= 100000 THEN
        result := result || convert_below_lakh(floor(num / 100000)::integer) || ' Lakh ';
        num := num % 100000;
    END IF;

    -- Handle Thousands (1,000)
    IF num >= 1000 THEN
        result := result || convert_below_thousand(floor(num / 1000)::integer) || ' Thousand ';
        num := num % 1000;
    END IF;

    -- Handle below 1000
    result := result || convert_below_thousand(num);

    RETURN TRIM(result) || ' only';
END;
$$;


CREATE FUNCTION public.convert_order_to_dispatch(p_order_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_user_profile_id UUID;
    v_order_record orders%ROWTYPE;
    v_accessible_customers UUID[];
    v_dispatch_id UUID;
    v_dispatch_no TEXT;
    v_item_record order_items%ROWTYPE;
    v_current_stock INTEGER;
    v_dispatch_quantity INTEGER;
    v_total_fulfilled INTEGER := 0;
    v_total_requested INTEGER := 0;
    v_fulfilled_count INTEGER := 0;
    v_partial_count INTEGER := 0;
    v_failed_count INTEGER := 0;
    v_order_status TEXT;
    v_fulfillment_percentage NUMERIC;
BEGIN
    -- Get user profile ID
    SELECT id INTO v_user_profile_id
    FROM user_profiles
    WHERE auth_user_id = auth.uid();

    IF v_user_profile_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', null,
            'message', 'User not found',
            'error', jsonb_build_object('code', 'USER_NOT_FOUND', 'details', 'User profile not found')
        );
    END IF;

    -- Get order details
    SELECT * INTO v_order_record FROM orders WHERE id = p_order_id;

    IF v_order_record.id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', null,
            'message', 'Order not found',
            'error', jsonb_build_object('code', 'ORDER_NOT_FOUND', 'details', 'Order ID not found')
        );
    END IF;

    -- Check if order can be converted
    IF v_order_record.status NOT IN ('pending', 'partially_fulfilled') THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', null,
            'message', 'Only pending or partially fulfilled orders can be converted to dispatch',
            'error', jsonb_build_object('code', 'INVALID_STATUS', 'details', 'Order status: ' || v_order_record.status)
        );
    END IF;

    -- Check if order is already linked to a dispatch
    IF v_order_record.dispatch_id IS NOT NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', null,
            'message', 'Order is already linked to dispatch: ' || v_order_record.dispatch_no,
            'error', jsonb_build_object('code', 'ALREADY_DISPATCHED', 'details', 'Dispatch ID: ' || v_order_record.dispatch_id)
        );
    END IF;

    -- Check access permissions
    IF NOT is_admin_or_supervisor() THEN
        v_accessible_customers := user_accessible_customers();
        IF v_order_record.customer_id != ALL(v_accessible_customers) THEN
            RETURN jsonb_build_object(
                'success', false,
                'data', null,
                'message', 'Access denied to this order',
                'error', jsonb_build_object('code', 'ACCESS_DENIED', 'details', 'Customer not accessible')
            );
        END IF;
    END IF;

    -- Generate dispatch number
    SELECT 'D' || LPAD(COALESCE(MAX(CAST(SUBSTRING(disp_no FROM 2) AS INTEGER)), 0) + 1, 4, '0')
    INTO v_dispatch_no
    FROM dispatch
    WHERE disp_no ~ '^D[0-9]+$';

    -- Create dispatch record
    INSERT INTO dispatch (
        disp_no, disp_date, customer_id, customer_name, supervisor_id, supervisor_name,
        note, source_order_id, source_order_no, created_by, updated_by
    )
    VALUES (
        v_dispatch_no,
        now(),
        v_order_record.customer_id,
        v_order_record.customer_name,
        v_user_profile_id,
        (SELECT name FROM user_profiles WHERE id = v_user_profile_id),
        'Auto-generated from order: ' || v_order_record.order_no,
        v_order_record.id,
        v_order_record.order_no,
        v_user_profile_id,
        v_user_profile_id
    )
    RETURNING id INTO v_dispatch_id;

    -- Process each order item
    FOR v_item_record IN
        SELECT * FROM order_items WHERE order_id = p_order_id AND item_status = 'pending'
    LOOP
        -- Get current stock
        SELECT stock INTO v_current_stock
        FROM goodsreceived_trl
        WHERE id = v_item_record.grn_items_id;

        IF v_current_stock IS NULL THEN
            v_current_stock := 0;
        END IF;

        -- Calculate dispatch quantity
        v_dispatch_quantity := LEAST(v_current_stock,
            v_item_record.requested_quantity - v_item_record.fulfilled_quantity);

        v_total_requested := v_total_requested + v_item_record.requested_quantity;

        IF v_dispatch_quantity > 0 THEN
            -- Create dispatch item
            INSERT INTO dispatch_trl (
                disp_id, gr_id, gr_trl_id, item_id, item_name, packaging,
                qty, weight, rack, package_mark, trl_img_url
            )
            SELECT
                v_dispatch_id,
                v_item_record.grns_id,
                v_item_record.grn_items_id,
                v_item_record.grn_items_item_id,
                v_item_record.grn_items_item_name,
                v_item_record.grn_items_packaging,
                v_dispatch_quantity,
                v_item_record.grn_items_weight,
                v_item_record.grn_items_rack,
                v_item_record.grn_items_package_mark,
                v_item_record.grn_items_image_url;

            -- Update stock
            UPDATE goodsreceived_trl
            SET stock = stock - v_dispatch_quantity
            WHERE id = v_item_record.grn_items_id;

            -- Create stock movement record
            INSERT INTO stock_movements (
                gr_trl_id, movement_type, quantity, previous_stock, new_stock,
                dispatch_id, created_by, notes
            )
            VALUES (
                v_item_record.grn_items_id,
                'dispatch',
                -v_dispatch_quantity,
                v_current_stock,
                v_current_stock - v_dispatch_quantity,
                v_dispatch_id,
                v_user_profile_id,
                'Stock dispatched for order: ' || v_order_record.order_no
            );

            -- Update order item fulfillment
            UPDATE order_items
            SET
                fulfilled_quantity = fulfilled_quantity + v_dispatch_quantity,
                current_stock = v_current_stock - v_dispatch_quantity,
                item_status = CASE
                    WHEN fulfilled_quantity + v_dispatch_quantity >= requested_quantity THEN 'fulfilled'
                    WHEN fulfilled_quantity + v_dispatch_quantity > 0 THEN 'partially_fulfilled'
                    ELSE 'pending'
                END,
                updated_at = now()
            WHERE id = v_item_record.id;

            v_total_fulfilled := v_total_fulfilled + v_dispatch_quantity;

            IF v_dispatch_quantity >= (v_item_record.requested_quantity - v_item_record.fulfilled_quantity) THEN
                v_fulfilled_count := v_fulfilled_count + 1;
            ELSE
                v_partial_count := v_partial_count + 1;
            END IF;
        ELSE
            v_failed_count := v_failed_count + 1;
            UPDATE order_items
            SET item_status = 'out_of_stock', updated_at = now()
            WHERE id = v_item_record.id;
        END IF;
    END LOOP;

    -- Calculate order status
    IF v_total_fulfilled = 0 THEN
        v_order_status := 'pending';
    ELSIF v_total_fulfilled >= v_total_requested THEN
        v_order_status := 'fulfilled';
    ELSE
        v_order_status := 'partially_fulfilled';
    END IF;

    -- Update order with dispatch linkage
    UPDATE orders
    SET
        dispatch_id = v_dispatch_id,
        dispatch_no = v_dispatch_no,
        dispatch_created_at = now(),
        total_fulfilled_qty = v_total_fulfilled,
        status = v_order_status,
        updated_by = v_user_profile_id,
        updated_at = now()
    WHERE id = p_order_id;

    -- Update GRN out_of_stock flags
    UPDATE goodsreceived
    SET out_of_stock = TRUE
    WHERE id IN (
        SELECT DISTINCT grns_id FROM order_items WHERE order_id = p_order_id
    ) AND NOT EXISTS (
        SELECT 1 FROM goodsreceived_trl grt
        WHERE grt.gr_id = goodsreceived.id AND grt.stock > 0
    );

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'dispatch_id', v_dispatch_id,
            'dispatch_no', v_dispatch_no,
            'fulfilled_items', v_fulfilled_count,
            'partial_items', v_partial_count,
            'failed_items', v_failed_count
        ),
        'message', 'Order converted with ' || v_fulfilled_count || ' items fully fulfilled, ' || v_partial_count || ' partially'
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', null,
            'message', 'Conversion failed: ' || SQLERRM,
            'error', jsonb_build_object('code', 'CONVERSION_FAILED', 'details', SQLERRM)
        );
END;
$_$;


CREATE FUNCTION public.create_contra_voucher(p_date date, p_amount numeric, p_from_ledger text, p_to_ledger text, p_particulars text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_config         public.bank_reco_company_config;
    v_voucher_id     UUID;
    v_voucher_number TEXT;
    v_fy_start       INT;
    v_fy_label       TEXT;
    v_seq            BIGINT;
    v_enq            JSONB;
BEGIN
    IF p_amount IS NULL OR p_amount <= 0 THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'INVALID_AMOUNT',
            'error', 'Amount must be greater than zero');
    END IF;

    IF p_from_ledger IS NULL OR p_to_ledger IS NULL
       OR trim(p_from_ledger) = '' OR trim(p_to_ledger) = '' THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'LEDGER_REQUIRED',
            'error', 'Both from_ledger and to_ledger are required');
    END IF;

    IF p_from_ledger = p_to_ledger THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'LEDGER_SAME',
            'error', 'from_ledger and to_ledger must differ');
    END IF;

    SELECT * INTO v_config FROM public.bank_reco_company_config LIMIT 1;
    IF v_config.id IS NULL THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'MISSING_COMPANY_CONFIG',
            'error', 'No company config found');
    END IF;

    IF EXTRACT(MONTH FROM p_date) >= 4 THEN
        v_fy_start := EXTRACT(YEAR FROM p_date)::INT;
    ELSE
        v_fy_start := EXTRACT(YEAR FROM p_date)::INT - 1;
    END IF;
    v_fy_label := v_fy_start::TEXT || '-' || RIGHT((v_fy_start + 1)::TEXT, 2);

    INSERT INTO public.contra_voucher_counters (financial_year, next_seq)
    VALUES (v_fy_label, 2)
    ON CONFLICT (financial_year)
    DO UPDATE SET next_seq = contra_voucher_counters.next_seq + 1,
                  updated_at = now()
    RETURNING next_seq - 1 INTO v_seq;

    v_voucher_number := 'CTRA/' || v_fy_start::TEXT || '/' || lpad(v_seq::TEXT, 5, '0');

    INSERT INTO public.tally_contra_vouchers (
        voucher_number, voucher_date, from_ledger, to_ledger,
        amount, particulars, tally_company
    ) VALUES (
        v_voucher_number, p_date, p_from_ledger, p_to_ledger,
        p_amount, p_particulars, v_config.tally_company
    )
    RETURNING id INTO v_voucher_id;

    SELECT public.enqueue_contra_voucher(v_voucher_id) INTO v_enq;

    IF (v_enq->>'success')::boolean != true THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'ENQUEUE_FAILED',
            'error', 'Failed to enqueue contra: ' || (v_enq->>'error'));
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'voucher_id',     v_voucher_id,
            'voucher_number', v_voucher_number,
            'queue_id',       v_enq->'data'->>'queue_id'
        )
    );
END;
$$;


CREATE FUNCTION public.create_customer(p_name character varying, p_mobile character varying, p_email character varying DEFAULT NULL::character varying, p_address text DEFAULT NULL::text, p_city character varying DEFAULT NULL::character varying, p_state character varying DEFAULT NULL::character varying, p_pincode character varying DEFAULT NULL::character varying, p_gst_number character varying DEFAULT NULL::character varying, p_pan_number character varying DEFAULT NULL::character varying, p_contact_person character varying DEFAULT NULL::character varying, p_contact_mobile character varying DEFAULT NULL::character varying, p_contact_email character varying DEFAULT NULL::character varying, p_image_urls text[] DEFAULT NULL::text[], p_document_urls text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_customer_id UUID;
    v_image_count INTEGER;
    v_document_count INTEGER;
BEGIN
    -- Check permission: Admin/Supervisor only
    IF NOT is_admin_or_supervisor() THEN
        RETURN utils.permission_denied_response('admins and supervisors');
    END IF;

    -- Validate name
    IF p_name IS NULL OR TRIM(p_name) = '' THEN
        RETURN utils.validation_error_response('name', 'Customer name is required');
    END IF;

    -- Validate mobile format (but allow duplicates)
    IF p_mobile IS NULL OR NOT p_mobile ~ '^[0-9]{10,15}$' THEN
        RETURN utils.validation_error_response('mobile', 'Mobile number must be 10-15 digits');
    END IF;

    -- Count images and documents
    v_image_count := COALESCE(array_length(p_image_urls, 1), 0);
    v_document_count := COALESCE(array_length(p_document_urls, 1), 0);

    -- Insert customer with image_urls and document_urls stored directly in the table
    INSERT INTO customers (
        name, mobile, email, address, city, state, pincode,
        gst, pan, contact_person, contact_mobile, contact_email,
        image_urls, document_urls
    )
    VALUES (
        TRIM(p_name), p_mobile, p_email, p_address, p_city, p_state, p_pincode,
        p_gst_number, p_pan_number, p_contact_person, p_contact_mobile, p_contact_email,
        p_image_urls, p_document_urls
    )
    RETURNING id INTO v_customer_id;

    RETURN utils.success_response(
        jsonb_build_object(
            'customer_id', v_customer_id,
            'images_saved', v_image_count,
            'documents_saved', v_document_count
        ),
        'Customer created successfully'
    );

EXCEPTION
    WHEN unique_violation THEN
        RETURN utils.error_response('DUPLICATE_NAME', 'A customer with this name already exists');
    WHEN OTHERS THEN
        RETURN utils.database_error_response('Failed to create customer', SQLERRM, SQLSTATE);
END;
$_$;


CREATE FUNCTION public.create_dispatch_with_stock_check(p_dispatch_data jsonb, p_dispatch_items jsonb[], p_retry_count integer DEFAULT 0, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET jit TO 'off'
    AS $$
DECLARE
    v_validation_result JSONB;
BEGIN
    -- Step 1: Validate dispatch data
    v_validation_result := validate_dispatch_input(p_dispatch_data);

    IF NOT (v_validation_result->>'valid')::BOOLEAN THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'Invalid dispatch data',
            'validation_errors', v_validation_result->'errors'
        );
    END IF;

    -- Step 2: Validate dispatch items
    v_validation_result := validate_dispatch_items(p_dispatch_items);

    IF NOT (v_validation_result->>'valid')::BOOLEAN THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'Invalid dispatch items',
            'validation_errors', v_validation_result->'errors'
        );
    END IF;

    -- Step 3: Call internal function with idempotency key
    RETURN create_dispatch_with_stock_check_internal_3param(
        p_dispatch_data,
        p_dispatch_items,
        p_retry_count,
        p_idempotency_key
    );
END;
$$;


CREATE FUNCTION public.create_dispatch_with_stock_check(p_dispatch_data jsonb, p_dispatch_items jsonb[], p_generate_invoice boolean, p_retry_count integer DEFAULT 0, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET jit TO 'off'
    AS $$
DECLARE
    v_validation_result JSONB;
BEGIN
    -- Step 1: Validate dispatch data
    v_validation_result := validate_dispatch_input(p_dispatch_data);

    IF NOT (v_validation_result->>'valid')::BOOLEAN THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'Invalid dispatch data',
            'validation_errors', v_validation_result->'errors'
        );
    END IF;

    -- Step 2: Validate dispatch items
    v_validation_result := validate_dispatch_items(p_dispatch_items);

    IF NOT (v_validation_result->>'valid')::BOOLEAN THEN
