    );
END;
$$;


CREATE FUNCTION public.create_dispatch_with_stock_check_2arg_internal(p_dispatch_data jsonb, p_dispatch_items jsonb[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_dispatch_id uuid;
    v_user_id uuid;
    v_affected_gr_ids uuid[];
    v_insufficient_stock text;
    v_source_order_id uuid;
    v_source_order_no text;
    v_order_item_id uuid;
    v_disp_trl_id uuid;
BEGIN
    -- Check if user is admin or supervisor
    IF NOT is_admin_or_supervisor() THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Only administrators and supervisors can create dispatches'
        );
    END IF;

    -- Get current user
    SELECT id INTO v_user_id FROM user_profiles WHERE auth_user_id = auth.uid();

    -- Extract source order info from dispatch data
    v_source_order_id := NULLIF(TRIM(p_dispatch_data->>'source_order_id'), '')::uuid;
    v_source_order_no := NULLIF(TRIM(p_dispatch_data->>'source_order_no'), '');

    -- STEP 1: Lock all relevant GRN items first (no aggregation)
    PERFORM gt.id
    FROM unnest(p_dispatch_items) AS item
    JOIN goodsreceived_trl gt ON gt.id = (item->>'gr_trl_id')::uuid
    FOR UPDATE OF gt;

    -- STEP 2: Check stock availability (separate query, no FOR UPDATE)
    SELECT string_agg(
        gt.item_name || ' (Available: ' || gt.stock || ', Requested: ' || (item->>'disp_qty')::integer || ')',
        ', '
    )
    INTO v_insufficient_stock
    FROM unnest(p_dispatch_items) AS item
    JOIN goodsreceived_trl gt ON gt.id = (item->>'gr_trl_id')::uuid
    WHERE gt.stock < (item->>'disp_qty')::integer;

    IF v_insufficient_stock IS NOT NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Insufficient stock: ' || v_insufficient_stock
        );
    END IF;

    -- CREATE DISPATCH RECORD (now includes source_order_id and source_order_no)
    INSERT INTO dispatch (
        disp_no, disp_date, registration, customer_id,
        customer_name, supervisor_id, supervisor_name, note, created_by,
        source_order_id, source_order_no
    )
    SELECT
        p_dispatch_data->>'disp_no',
        COALESCE((p_dispatch_data->>'disp_date')::timestamptz, NOW()),
        p_dispatch_data->>'registration',
        (p_dispatch_data->>'customer_id')::uuid,
        p_dispatch_data->>'customer_name',
        (p_dispatch_data->>'supervisor_id')::uuid,
        p_dispatch_data->>'supervisor_name',
        p_dispatch_data->>'note',
        v_user_id,
        v_source_order_id,
        v_source_order_no
    RETURNING id INTO v_dispatch_id;

    -- BULK UPDATE STOCK
    UPDATE goodsreceived_trl gt
    SET stock = gt.stock - (item->>'disp_qty')::integer
    FROM unnest(p_dispatch_items) AS item
    WHERE gt.id = (item->>'gr_trl_id')::uuid;

    -- BULK INSERT DISPATCH ITEMS (with source_order_item_id if from order)
    INSERT INTO dispatch_trl (disp_id, gr_trl_id, gr_id, disp_qty, source_type, source_order_item_id, cart_quantity_consumed)
    SELECT
        v_dispatch_id,
        (item->>'gr_trl_id')::uuid,
        gt.gr_id,
        (item->>'disp_qty')::integer,
        CASE WHEN v_source_order_id IS NOT NULL THEN 'cart' ELSE 'direct' END,
        -- Find matching order_item by grn_items_id
        (SELECT oi.id FROM order_items oi
         WHERE oi.order_id = v_source_order_id
         AND oi.grn_items_id = (item->>'gr_trl_id')::uuid
         LIMIT 1),
        CASE WHEN v_source_order_id IS NOT NULL THEN (item->>'disp_qty')::integer ELSE 0 END
    FROM unnest(p_dispatch_items) AS item
    JOIN goodsreceived_trl gt ON gt.id = (item->>'gr_trl_id')::uuid;

    -- GET UNIQUE GR_IDS
    SELECT ARRAY(
        SELECT DISTINCT gt.gr_id
        FROM unnest(p_dispatch_items) AS item
        JOIN goodsreceived_trl gt ON gt.id = (item->>'gr_trl_id')::uuid
    ) INTO v_affected_gr_ids;

    -- BULK INSERT STOCK MOVEMENTS
    INSERT INTO stock_movements (
        gr_trl_id, movement_type, quantity,
        reference_id, reference_type,
        balance_before, balance_after, created_by
    )
    SELECT
        (item->>'gr_trl_id')::uuid,
        'dispatch',
        -(item->>'disp_qty')::integer,
        v_dispatch_id,
        'dispatch',
        gt.stock + (item->>'disp_qty')::integer,
        gt.stock,
        v_user_id
    FROM unnest(p_dispatch_items) AS item
    JOIN goodsreceived_trl gt ON gt.id = (item->>'gr_trl_id')::uuid;

    -- BULK UPDATE OUT_OF_STOCK STATUS
    UPDATE goodsreceived gr
    SET out_of_stock = NOT EXISTS (
        SELECT 1 FROM goodsreceived_trl grt
        WHERE grt.gr_id = gr.id AND grt.stock > 0
    )
    WHERE gr.id = ANY(v_affected_gr_ids);

    -- IF FROM ORDER: Update order items and clear the order
    IF v_source_order_id IS NOT NULL THEN
        -- Update order_items: set fulfilled_quantity and item_status
        UPDATE order_items oi
        SET
            fulfilled_quantity = oi.fulfilled_quantity + (item->>'disp_qty')::integer,
            current_stock = (SELECT stock FROM goodsreceived_trl WHERE id = oi.grn_items_id),
            item_status = CASE
                WHEN oi.fulfilled_quantity + (item->>'disp_qty')::integer >= oi.requested_quantity THEN 'fulfilled'
                WHEN oi.fulfilled_quantity + (item->>'disp_qty')::integer > 0 THEN 'partially_fulfilled'
                ELSE 'pending'
            END,
            updated_at = NOW()
        FROM unnest(p_dispatch_items) AS item
        WHERE oi.order_id = v_source_order_id
        AND oi.grn_items_id = (item->>'gr_trl_id')::uuid;

        -- Soft-delete the order (set deleted_at) since it's been converted to dispatch
        UPDATE orders
        SET
            deleted_at = NOW(),
            deleted_by = v_user_id,
            updated_at = NOW(),
            updated_by = v_user_id
        WHERE id = v_source_order_id;
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'dispatch_id', v_dispatch_id,
        'message', 'Dispatch created successfully',
        'source_order_cleared', v_source_order_id IS NOT NULL
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', SQLERRM,
            'error_code', SQLSTATE
        );
END;
$$;


CREATE FUNCTION public.create_dispatch_with_stock_check_internal(p_dispatch_data jsonb, p_dispatch_items jsonb[], p_generate_invoice boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    -- Delegate to the 4-param version with NULL idempotency key
    RETURN create_dispatch_with_stock_check_internal(
        p_dispatch_data,
        p_dispatch_items,
        p_generate_invoice,
        NULL  -- p_idempotency_key
    );
END;
$$;


CREATE FUNCTION public.create_dispatch_with_stock_check_internal(p_dispatch_data jsonb, p_dispatch_items jsonb[], p_generate_invoice boolean DEFAULT false, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_dispatch_id uuid;
    v_user_id uuid;
    v_affected_gr_ids uuid[];
    v_all_gr_ids uuid[];
    v_insufficient_stock text;
    v_dispatch_items_result jsonb[];
    v_invoice_data jsonb;
    v_gr_id uuid;
    v_grn_customer_id uuid;
    v_is_invoiceable boolean;
    v_single_invoice_data jsonb;
    v_source_order_id uuid;
    v_source_order_no text;  -- Added for auto-lookup
    v_item jsonb;
    v_gr_trl_id uuid;
    v_dispatched_qty integer;
    v_cart_id uuid;
    v_cart_item_id uuid;
    v_cart_current_qty integer;
    v_cart_fulfilled_qty integer;
    v_cart_new_qty integer;
    v_cached_response jsonb;
BEGIN
    -- Check idempotency key first
    IF p_idempotency_key IS NOT NULL THEN
        SELECT response INTO v_cached_response
        FROM idempotency_keys
        WHERE idempotency_key = p_idempotency_key AND created_at > NOW() - INTERVAL '24 hours';

        IF v_cached_response IS NOT NULL THEN
            RETURN v_cached_response || jsonb_build_object('from_cache', true);
        END IF;
    END IF;

    -- Check if user is admin or supervisor
    IF NOT is_admin_or_supervisor() THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Only administrators and supervisors can create dispatches'
        );
    END IF;

    -- Get current user
    SELECT id INTO v_user_id FROM user_profiles WHERE auth_user_id = auth.uid();

    -- Extract source_order_id if provided
    v_source_order_id := (p_dispatch_data->>'source_order_id')::uuid;

    -- Auto-lookup source_order_no from orders table if not provided
    IF v_source_order_id IS NOT NULL THEN
        v_source_order_no := COALESCE(
            p_dispatch_data->>'source_order_no',
            (SELECT order_no FROM orders WHERE id = v_source_order_id)
        );
    ELSE
        v_source_order_no := p_dispatch_data->>'source_order_no';
    END IF;

    -- STEP 1: Lock all relevant GRN items first (no aggregation)
    PERFORM gt.id
    FROM unnest(p_dispatch_items) AS item
    JOIN goodsreceived_trl gt ON gt.id = (item->>'gr_trl_id')::uuid
    FOR UPDATE OF gt;

    -- STEP 2: Check stock availability (separate query, no FOR UPDATE)
    SELECT string_agg(
        gt.item_name || ' (Available: ' || gt.stock || ', Requested: ' || (item->>'disp_qty')::integer || ')',
        ', '
    )
    INTO v_insufficient_stock
    FROM unnest(p_dispatch_items) AS item
    JOIN goodsreceived_trl gt ON gt.id = (item->>'gr_trl_id')::uuid
    WHERE gt.stock < (item->>'disp_qty')::integer;

    IF v_insufficient_stock IS NOT NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Insufficient stock: ' || v_insufficient_stock
        );
    END IF;

    -- CREATE DISPATCH RECORD
    INSERT INTO dispatch (
        disp_no, disp_date, registration, customer_id,
        customer_name, supervisor_id, supervisor_name, note,
        created_by, source_order_id, source_order_no
    ) VALUES (
        p_dispatch_data->>'disp_no',
        (p_dispatch_data->>'disp_date')::date::timestamptz,
        p_dispatch_data->>'registration',
        (p_dispatch_data->>'customer_id')::uuid,
        p_dispatch_data->>'customer_name',
        (p_dispatch_data->>'supervisor_id')::uuid,
        p_dispatch_data->>'supervisor_name',
        p_dispatch_data->>'note',
        v_user_id,
        v_source_order_id,
        v_source_order_no  -- Now uses auto-looked-up value
    ) RETURNING id INTO v_dispatch_id;

    -- BULK UPDATE STOCK
    UPDATE goodsreceived_trl gt
    SET stock = gt.stock - (item->>'disp_qty')::integer
    FROM unnest(p_dispatch_items) AS item
    WHERE gt.id = (item->>'gr_trl_id')::uuid;

    -- BULK INSERT DISPATCH ITEMS
    INSERT INTO dispatch_trl (gr_id, gr_trl_id, disp_id, disp_qty)
    SELECT
        gt.gr_id,
        (item->>'gr_trl_id')::uuid,
        v_dispatch_id,
        (item->>'disp_qty')::integer
    FROM unnest(p_dispatch_items) AS item
    JOIN goodsreceived_trl gt ON gt.id = (item->>'gr_trl_id')::uuid;

    -- GET UNIQUE GR_IDS
    SELECT ARRAY(
        SELECT DISTINCT gt.gr_id
        FROM unnest(p_dispatch_items) AS item
        JOIN goodsreceived_trl gt ON gt.id = (item->>'gr_trl_id')::uuid
    ) INTO v_affected_gr_ids;

    -- BULK INSERT STOCK MOVEMENTS
    INSERT INTO stock_movements (
        gr_trl_id, movement_type, quantity,
        reference_id, reference_type,
        balance_before, balance_after, created_by
    )
    SELECT
        (item->>'gr_trl_id')::uuid,
        'dispatch',
        (item->>'disp_qty')::integer,
        v_dispatch_id,
        'dispatch',
        gt.stock + (item->>'disp_qty')::integer,
        gt.stock,
        v_user_id
    FROM unnest(p_dispatch_items) AS item
    JOIN goodsreceived_trl gt ON gt.id = (item->>'gr_trl_id')::uuid;

    -- BULK UPDATE OUT_OF_STOCK STATUS
    UPDATE goodsreceived gr
    SET out_of_stock = NOT EXISTS (
        SELECT 1 FROM goodsreceived_trl grt
        WHERE grt.gr_id = gr.id AND grt.stock > 0
    )
    WHERE gr.id = ANY(v_affected_gr_ids);

    -- BUILD DISPATCH ITEMS RESPONSE
    SELECT ARRAY(
        SELECT jsonb_build_object(
            'id', dt.id,
            'gr_id', dt.gr_id,
            'gr_trl_id', dt.gr_trl_id,
            'disp_id', dt.disp_id,
            'disp_qty', dt.disp_qty,
            'item_name', COALESCE(i.name, grt.item_name),
            'packaging', grt.packaging,
            'rack', grt.rack,
            'package_mark', grt.package_mark,
            'weight', grt.weight,
            'remaining_stock', grt.stock
        )
        FROM dispatch_trl dt
        JOIN goodsreceived_trl grt ON grt.id = dt.gr_trl_id
        LEFT JOIN items i ON i.id = grt.item_id
        WHERE dt.disp_id = v_dispatch_id
    ) INTO v_dispatch_items_result;

    -- INVOICE GENERATION (if requested)
    IF p_generate_invoice THEN
        v_invoice_data := '{}'::jsonb;
        v_all_gr_ids := v_affected_gr_ids;

        FOREACH v_gr_id IN ARRAY v_all_gr_ids
        LOOP
            SELECT gr.customer_id, c.auto_invoice_generation
            INTO v_grn_customer_id, v_is_invoiceable
            FROM goodsreceived gr
            JOIN customers c ON c.id = gr.customer_id
            WHERE gr.id = v_gr_id;

            IF v_is_invoiceable THEN
                v_single_invoice_data := generate_invoice_data_for_grn_with_pricing(v_gr_id);
                IF (v_single_invoice_data->>'success')::boolean = true THEN
                    v_invoice_data := v_invoice_data || jsonb_build_object(v_gr_id::text, v_single_invoice_data);
                END IF;
            END IF;
        END LOOP;
    END IF;

    -- ORDER/CART HANDLING (PERSISTENT CART MODEL)
    IF v_source_order_id IS NOT NULL THEN
        -- FROM ORDER dispatch: Delete or reduce cart items, keep order OPEN
        FOREACH v_item IN ARRAY p_dispatch_items
        LOOP
            v_gr_trl_id := (v_item->>'gr_trl_id')::uuid;
            v_dispatched_qty := (v_item->>'disp_qty')::integer;

            SELECT id, requested_quantity
            INTO v_cart_item_id, v_cart_current_qty
            FROM order_items
            WHERE order_id = v_source_order_id AND grn_items_id = v_gr_trl_id
            LIMIT 1;

            IF v_cart_item_id IS NOT NULL THEN
                v_cart_new_qty := GREATEST(0, v_cart_current_qty - v_dispatched_qty);
                IF v_cart_new_qty = 0 THEN
                    DELETE FROM order_items WHERE id = v_cart_item_id;
                ELSE
                    UPDATE order_items
                    SET requested_quantity = v_cart_new_qty,
                        fulfilled_quantity = 0,
                        item_status = 'pending',
                        updated_at = NOW()
                    WHERE id = v_cart_item_id;
                END IF;
            END IF;
        END LOOP;

        UPDATE orders
        SET status = 'OPEN',
            updated_at = NOW(),
            updated_by = v_user_id
        WHERE id = v_source_order_id;
    ELSE
        -- DIRECT DISPATCH: Reduce cart quantities
        FOREACH v_item IN ARRAY p_dispatch_items
        LOOP
            v_gr_trl_id := (v_item->>'gr_trl_id')::uuid;
            v_dispatched_qty := (v_item->>'disp_qty')::integer;

            SELECT gr.customer_id INTO v_grn_customer_id
            FROM goodsreceived_trl grt
            JOIN goodsreceived gr ON gr.id = grt.gr_id
            WHERE grt.id = v_gr_trl_id;

            IF v_grn_customer_id IS NOT NULL THEN
                SELECT id INTO v_cart_id
                FROM orders
                WHERE customer_id = v_grn_customer_id AND status = 'OPEN' AND deleted_at IS NULL
                LIMIT 1;

                IF v_cart_id IS NOT NULL THEN
                    SELECT id, requested_quantity, fulfilled_quantity
                    INTO v_cart_item_id, v_cart_current_qty, v_cart_fulfilled_qty
                    FROM order_items
                    WHERE order_id = v_cart_id AND grn_items_id = v_gr_trl_id
                    LIMIT 1;

                    IF v_cart_item_id IS NOT NULL THEN
                        v_cart_new_qty := GREATEST(0, v_cart_current_qty - v_dispatched_qty);
                        IF v_cart_new_qty = 0 THEN
                            DELETE FROM order_items WHERE id = v_cart_item_id;
                        ELSE
                            UPDATE order_items
                            SET requested_quantity = v_cart_new_qty,
                                fulfilled_quantity = GREATEST(0, COALESCE(v_cart_fulfilled_qty, 0) - v_dispatched_qty)
                            WHERE id = v_cart_item_id;
                        END IF;
                    END IF;
                END IF;
            END IF;
        END LOOP;
    END IF;

    -- Build result
    v_cached_response := jsonb_build_object(
        'success', true,
        'dispatch_id', v_dispatch_id,
        'dispatch_items', to_jsonb(v_dispatch_items_result),
        'invoice_data', COALESCE(v_invoice_data, '{}'::jsonb),
        'message', 'Dispatch created successfully',
        'source_order_cleared', v_source_order_id IS NOT NULL
    );

    -- Cache the response if idempotency key provided
    IF p_idempotency_key IS NOT NULL THEN
        INSERT INTO idempotency_keys (idempotency_key, rpc_function, response, created_by)
        VALUES (p_idempotency_key, 'create_dispatch_with_stock_check', v_cached_response, v_user_id)
        ON CONFLICT (idempotency_key) DO UPDATE SET response = v_cached_response, created_at = NOW();
    END IF;

    RETURN v_cached_response;

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', SQLERRM,
            'error_code', SQLSTATE
        );
END;
$$;


CREATE FUNCTION public.create_dispatch_with_stock_check_internal_3param(p_dispatch_data jsonb, p_dispatch_items jsonb[], p_retry_count integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    -- REMOVED: SET TRANSACTION ISOLATION LEVEL SERIALIZABLE
    -- This was causing error 25001 because validation queries already ran
    -- Row-level locking (FOR UPDATE) in the 2arg function provides sufficient concurrency control

    SELECT create_dispatch_with_stock_check_2arg_internal(
        p_dispatch_data,
        p_dispatch_items
    ) INTO v_result;

    v_result := v_result || jsonb_build_object('retry_count', p_retry_count);
    RETURN v_result;

EXCEPTION
    WHEN serialization_failure OR deadlock_detected THEN
        -- Handle concurrency conflicts with retry
        IF p_retry_count < 3 THEN
            PERFORM pg_sleep(POWER(2, p_retry_count) * 0.1);
            RETURN create_dispatch_with_stock_check_internal_3param(
                p_dispatch_data,
                p_dispatch_items,
                p_retry_count + 1
            );
        ELSE
            RETURN jsonb_build_object(
                'success', false,
                'error', 'Transaction conflict: too many retries. Please try again.',
                'error_code', 'SERIALIZATION_FAILURE',
                'retry_count', p_retry_count
            );
        END IF;
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', SQLERRM,
            'error_code', SQLSTATE,
            'retry_count', p_retry_count
        );
END;
$$;


CREATE FUNCTION public.create_dispatch_with_stock_check_internal_3param(p_dispatch_data jsonb, p_dispatch_items jsonb[], p_retry_count integer DEFAULT 0, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    -- Call the internal implementation with idempotency key (invoice = false)
    SELECT create_dispatch_with_stock_check_internal(
        p_dispatch_data,
        p_dispatch_items,
        false,  -- p_generate_invoice
        p_idempotency_key
    ) INTO v_result;

    -- Add retry count to response
    v_result := v_result || jsonb_build_object('retry_count', p_retry_count);

    RETURN v_result;

EXCEPTION
    -- Handle concurrency conflicts with retry
    WHEN serialization_failure OR deadlock_detected THEN
        IF p_retry_count < 3 THEN
            -- Exponential backoff
            PERFORM pg_sleep(POWER(2, p_retry_count) * 0.1);
            -- Retry via the outer wrapper
            RETURN create_dispatch_with_stock_check(
                p_dispatch_data,
                p_dispatch_items,
                p_retry_count + 1,
                p_idempotency_key
            );
        ELSE
            RETURN jsonb_build_object(
                'success', false,
                'error', 'Transaction conflict: too many retries. Please try again.',
                'error_code', 'SERIALIZATION_FAILURE',
                'retry_count', p_retry_count
            );
        END IF;

    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', SQLERRM,
            'error_code', SQLSTATE,
            'retry_count', p_retry_count
        );
END;
$$;


