CREATE FUNCTION public.create_dispatch_with_stock_check_internal_4param(p_dispatch_data jsonb, p_dispatch_items jsonb[], p_generate_invoice boolean, p_retry_count integer DEFAULT 0, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
