CREATE FUNCTION public.create_first_admin(admin_mobile character varying, admin_name character varying, admin_display_name character varying DEFAULT NULL::character varying) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    new_profile_id uuid;
BEGIN
    INSERT INTO user_profiles (
        auth_user_id,
        name,
        display_name,
        mobile,
        role,
        active
    ) VALUES (
        gen_random_uuid(),
        admin_name,
        COALESCE(admin_display_name, admin_name),
        admin_mobile,
        'admin',
        true
    ) RETURNING id INTO new_profile_id;

    RAISE NOTICE 'Created admin user profile with ID: %', new_profile_id;
    RAISE NOTICE 'Mobile: %', admin_mobile;
    RAISE NOTICE 'IMPORTANT: User must log in through Supabase Auth to complete setup';

    RETURN new_profile_id;
EXCEPTION
    WHEN OTHERS THEN
        RAISE WARNING 'create_first_admin failed: % - %', SQLSTATE, SQLERRM;
        RETURN NULL;
END;
$$;


CREATE FUNCTION public.create_item(p_name character varying, p_packaging character varying DEFAULT NULL::character varying, p_description character varying DEFAULT NULL::character varying, p_active boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_new_id uuid;
    v_result jsonb;
BEGIN
    -- Security check
    IF NOT is_admin_or_supervisor() THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Access denied: Admin or supervisor role required'
        );
    END IF;

    -- Validate name
    IF p_name IS NULL OR TRIM(p_name) = '' THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Item name is required'
        );
    END IF;

    -- Check for duplicate name
    IF EXISTS (SELECT 1 FROM items WHERE LOWER(name) = LOWER(TRIM(p_name))) THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'An item with this name already exists'
        );
    END IF;

    -- Insert new item
    INSERT INTO items (name, packaging, description, active)
    VALUES (TRIM(p_name), NULLIF(TRIM(p_packaging), ''), NULLIF(TRIM(p_description), ''), p_active)
    RETURNING id INTO v_new_id;

    -- Return created item
    SELECT jsonb_build_object(
        'id', id,
        'name', name,
        'packaging', packaging,
        'description', description,
        'active', active
    ) INTO v_result
    FROM items
    WHERE id = v_new_id;

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Item created successfully',
        'data', v_result
    );
END;
$$;


CREATE FUNCTION public.create_item_storage_price(p_item_id uuid, p_weight_min numeric, p_weight_max numeric, p_labour_rate numeric, p_effective_from date, p_customer_id uuid DEFAULT NULL::uuid, p_unit_price_one_time numeric DEFAULT NULL::numeric, p_unit_price_monthly numeric DEFAULT NULL::numeric, p_tax_percent numeric DEFAULT 18, p_effective_to date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_role TEXT;
    v_user_profile_id UUID;
    v_new_id UUID;
    v_validation JSONB;
    v_result RECORD;
BEGIN
    -- Authorization: admin/supervisor only
    SELECT up.id, up.role INTO v_user_profile_id, v_user_role
    FROM user_profiles up WHERE up.auth_user_id = auth.uid();

    IF v_user_role IS NULL OR v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Permission denied');
    END IF;

    -- Validation 1: weight_max >= weight_min
    IF p_weight_max < p_weight_min THEN
        RETURN jsonb_build_object('success', false, 'error', 'weight_max must be >= weight_min');
    END IF;

    -- Validation 2: At least one price must be > 0
    IF COALESCE(p_unit_price_one_time, 0) <= 0 AND COALESCE(p_unit_price_monthly, 0) <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'At least one of unit_price_one_time or unit_price_monthly must be > 0');
    END IF;

    -- Validation 3: effective_to >= effective_from (if provided)
    IF p_effective_to IS NOT NULL AND p_effective_to < p_effective_from THEN
        RETURN jsonb_build_object('success', false, 'error', 'effective_to must be >= effective_from');
    END IF;

    -- Validation 4: Item must exist
    IF NOT EXISTS (SELECT 1 FROM items WHERE id = p_item_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Item not found');
    END IF;

    -- Validation 5: Customer must exist (if provided)
    IF p_customer_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM customers WHERE id = p_customer_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Customer not found');
    END IF;

    -- Validation 6: No overlapping date ranges (use existing helper)
    v_validation := validate_price_configuration(
        p_item_id,
        p_weight_min::integer,
        p_weight_max::integer,
        p_effective_from,
        p_customer_id,
        p_effective_to
    );

    IF NOT (v_validation->>'valid')::boolean THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', COALESCE(v_validation->>'error', v_validation->>'message', 'Overlapping price configuration exists')
        );
    END IF;

    -- Insert the new price record
    INSERT INTO item_storage_prices (
        item_id,
        customer_id,
        weight_min,
        weight_max,
        unit_price_one_time,
        unit_price_monthly,
        labour_rate,
        tax_percent,
        effective_from,
        effective_to,
        created_by
    ) VALUES (
        p_item_id,
        p_customer_id,
        p_weight_min::integer,
        p_weight_max::integer,
        COALESCE(p_unit_price_one_time, 0),
        COALESCE(p_unit_price_monthly, 0),
        p_labour_rate,
        p_tax_percent,
        p_effective_from,
        p_effective_to,
        v_user_profile_id
    )
    RETURNING id INTO v_new_id;

    -- Fetch the created record with joined data
    SELECT
        isp.id,
        isp.item_id,
        i.name as item_name,
        isp.customer_id,
        c.name as customer_name,
        isp.weight_min,
        isp.weight_max,
        isp.unit_price_one_time,
        isp.unit_price_monthly,
        isp.labour_rate,
        isp.tax_percent,
        isp.effective_from,
        isp.effective_to,
        isp.created_at,
        isp.created_by
    INTO v_result
    FROM item_storage_prices isp
    LEFT JOIN items i ON isp.item_id = i.id
    LEFT JOIN customers c ON isp.customer_id = c.id
    WHERE isp.id = v_new_id;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'id', v_result.id,
            'item_id', v_result.item_id,
            'item_name', v_result.item_name,
            'customer_id', v_result.customer_id,
            'customer_name', v_result.customer_name,
            'weight_min', v_result.weight_min,
            'weight_max', v_result.weight_max,
            'unit_price_one_time', v_result.unit_price_one_time,
            'unit_price_monthly', v_result.unit_price_monthly,
            'labour_rate', v_result.labour_rate,
            'tax_percent', v_result.tax_percent,
            'effective_from', v_result.effective_from,
            'effective_to', v_result.effective_to,
            'created_at', v_result.created_at,
            'created_by', v_result.created_by
        ),
        'message', 'Price created successfully'
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', 'Creation failed: ' || SQLERRM
    );
END;
$$;


CREATE FUNCTION public.create_item_storage_price(p_item_id uuid, p_price_type text, p_unit_price numeric, p_weight_min numeric, p_weight_max numeric, p_labour_rate numeric, p_effective_from date, p_customer_id uuid DEFAULT NULL::uuid, p_tax_percent numeric DEFAULT 18, p_effective_to date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_role TEXT;
    v_user_id UUID;
    v_new_id UUID;
    v_item_exists BOOLEAN;
    v_customer_exists BOOLEAN;
BEGIN
    -- Authorization: admin/supervisor only
    SELECT role, id INTO v_user_role, v_user_id
    FROM user_profiles WHERE auth_user_id = auth.uid();

    IF v_user_role IS NULL OR v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Permission denied');
    END IF;

    -- Validate price_type
    IF p_price_type NOT IN ('one_time', 'monthly') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invalid price_type. Must be ''one_time'' or ''monthly''');
    END IF;

    -- Validate weight range
    IF p_weight_max < p_weight_min THEN
        RETURN jsonb_build_object('success', false, 'error', 'weight_max must be >= weight_min');
    END IF;

    -- Validate unit_price
    IF p_unit_price IS NULL OR p_unit_price < 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'unit_price must be >= 0');
    END IF;

    -- Validate date range
    IF p_effective_to IS NOT NULL AND p_effective_to <= p_effective_from THEN
        RETURN jsonb_build_object('success', false, 'error', 'effective_to must be > effective_from');
    END IF;

    -- Check item exists
    SELECT EXISTS(SELECT 1 FROM items WHERE id = p_item_id) INTO v_item_exists;
    IF NOT v_item_exists THEN
        RETURN jsonb_build_object('success', false, 'error', 'Item not found');
    END IF;

    -- Check customer exists if provided
    IF p_customer_id IS NOT NULL THEN
        SELECT EXISTS(SELECT 1 FROM customers WHERE id = p_customer_id) INTO v_customer_exists;
        IF NOT v_customer_exists THEN
            RETURN jsonb_build_object('success', false, 'error', 'Customer not found');
        END IF;
    END IF;

    -- Insert the new price record
    INSERT INTO item_storage_prices (
        item_id, customer_id, price_type, unit_price,
        weight_min, weight_max, labour_rate, tax_percent,
        effective_from, effective_to, created_by,
        unit_price_one_time, unit_price_monthly  -- Keep old columns populated for backward compat
    ) VALUES (
        p_item_id, p_customer_id, p_price_type, p_unit_price,
        p_weight_min, p_weight_max, p_labour_rate, p_tax_percent,
        p_effective_from, p_effective_to, v_user_id,
        CASE WHEN p_price_type = 'one_time' THEN p_unit_price ELSE 0 END,
        CASE WHEN p_price_type = 'monthly' THEN p_unit_price ELSE 0 END
    )
    RETURNING id INTO v_new_id;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object('id', v_new_id),
        'message', 'Price created successfully'
    );

EXCEPTION
    WHEN unique_violation THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'A price with the same item, customer, weight range, price type and effective dates already exists'
        );
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', SQLERRM,
            'error_code', SQLSTATE
        );
END;
$$;


CREATE FUNCTION public.create_manual_receipt(p_date date, p_amount numeric, p_customer_id uuid, p_particulars text, p_tds_amount numeric DEFAULT 0, p_allocations jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_fy            INT;
    v_fy_hash       TEXT;
    v_stmt_id       UUID;
    v_line_no       INT;
    v_line_id       UUID;
    v_alloc_sum     NUMERIC(14,2);
    v_expected      NUMERIC(14,2);
    v_bill_ids      UUID[];
    v_inv_id        UUID;
    v_inv_customer  UUID;
    v_alloc         JSONB;
    v_enq           JSONB;
    v_cust_active   BOOLEAN;
    v_cust_deleted  TIMESTAMPTZ;
    v_inv_synced    BOOLEAN;
BEGIN
    IF p_amount IS NULL OR p_amount <= 0 THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'INVALID_AMOUNT',
            'error', 'Amount must be greater than zero');
    END IF;

    IF p_customer_id IS NULL THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'CUSTOMER_REQUIRED',
            'error', 'Customer is required');
    END IF;

    -- Pre-flight: customer must be active and not soft-deleted
    SELECT active, deleted_at INTO v_cust_active, v_cust_deleted
    FROM public.customers WHERE id = p_customer_id;

    IF v_cust_active IS NULL THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'CUSTOMER_NOT_FOUND',
            'error', format('Customer %s not found', p_customer_id));
    END IF;
    IF v_cust_deleted IS NOT NULL OR v_cust_active = false THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'CUSTOMER_INACTIVE',
            'error', 'Customer is inactive or deleted — cannot create receipt');
    END IF;

    IF EXTRACT(MONTH FROM p_date) >= 4 THEN
        v_fy := EXTRACT(YEAR FROM p_date)::INT;
    ELSE
        v_fy := EXTRACT(YEAR FROM p_date)::INT - 1;
    END IF;

    v_fy_hash := 'MANUAL-FY-' || v_fy::TEXT;

    SELECT id INTO v_stmt_id
    FROM public.bank_statements
    WHERE account_number = 'MANUAL'
      AND period_start = make_date(v_fy, 4, 1);

    IF NOT FOUND THEN
        INSERT INTO public.bank_statements (
            account_number, storage_path, file_hash,
            status, period_start, period_end,
            total_debit, total_credit, uploaded_at
        ) VALUES (
            'MANUAL', 'manual://receipts', v_fy_hash,
            'parsed', make_date(v_fy, 4, 1), make_date(v_fy + 1, 3, 31),
            0, 0, NOW()
        )
        RETURNING id INTO v_stmt_id;
    END IF;

    SELECT COALESCE(MAX(line_no), 0) + 1 INTO v_line_no
    FROM public.bank_statement_lines WHERE statement_id = v_stmt_id;

    v_bill_ids := ARRAY[]::UUID[];

    IF p_allocations IS NOT NULL AND jsonb_array_length(p_allocations) > 0 THEN
        SELECT COALESCE(SUM((a->>'amount')::NUMERIC(14,2)), 0)
        INTO v_alloc_sum FROM jsonb_array_elements(p_allocations) a;

        v_expected := p_amount + COALESCE(p_tds_amount, 0);
        IF v_alloc_sum - v_expected > 1.00 THEN
            RETURN jsonb_build_object('success', false,
                'error_code', 'ALLOCATION_MISMATCH',
                'error', format(
                    'Allocation sum (%s) cannot exceed amount (%s) + TDS (%s) = %s',
                    v_alloc_sum, p_amount, COALESCE(p_tds_amount, 0), v_expected
                ));
        END IF;

        FOR v_alloc IN SELECT * FROM jsonb_array_elements(p_allocations)
        LOOP
            v_inv_id := (v_alloc->>'invoice_id')::UUID;

            SELECT customer_id INTO v_inv_customer
            FROM public.invoice WHERE id = v_inv_id AND deleted_at IS NULL;

            IF v_inv_customer IS NULL THEN
                RETURN jsonb_build_object('success', false,
                    'error_code', 'INVOICE_NOT_FOUND',
                    'error', format('Invoice %s not found or deleted', v_inv_id));
            END IF;

            IF v_inv_customer != p_customer_id THEN
                RETURN jsonb_build_object('success', false,
                    'error_code', 'INVOICE_WRONG_CUSTOMER',
                    'error', format('Invoice %s does not belong to customer %s', v_inv_id, p_customer_id));
            END IF;

            -- Pre-flight: invoice must be synced to Tally before it can be allocated against
            SELECT (tally_voucher_id IS NOT NULL) INTO v_inv_synced
            FROM public.tally_vouchers WHERE invoice_id = v_inv_id LIMIT 1;

            IF v_inv_synced IS NULL OR v_inv_synced = false THEN
                RETURN jsonb_build_object('success', false,
                    'error_code', 'INVOICE_NOT_IN_TALLY',
                    'error', format('Invoice %s is not yet synced to Tally. Run the invoice backfill before allocating against this invoice.', v_inv_id));
            END IF;

            v_bill_ids := v_bill_ids || v_inv_id;
        END LOOP;
    END IF;

    INSERT INTO public.bank_statement_lines (
        statement_id, line_no, tran_date, particulars,
        credit, debit, status, match_kind,
        matched_customer_id, matched_allocations, tds_amount,
        matched_bill_ids, confirmed_at
    ) VALUES (
        v_stmt_id, v_line_no, p_date, COALESCE(p_particulars, 'Manual receipt'),
        p_amount, 0, 'matched', 'manual',
        p_customer_id,
        CASE WHEN jsonb_array_length(COALESCE(p_allocations, '[]'::JSONB)) > 0
             THEN p_allocations ELSE NULL END,
        COALESCE(p_tds_amount, 0),
        CASE WHEN array_length(v_bill_ids, 1) > 0 THEN v_bill_ids ELSE NULL END,
        NOW()
    )
    RETURNING id INTO v_line_id;

    SELECT public.enqueue_receipt_voucher(v_line_id) INTO v_enq;

    IF (v_enq->>'success')::BOOLEAN != true THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'ENQUEUE_FAILED',
            'error', 'Failed to enqueue voucher: ' || (v_enq->>'error'));
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'line_id', v_line_id,
            'voucher_number', v_enq->'data'->>'voucher_number',
            'queue_id', v_enq->'data'->>'queue_id'
        )
    );
END;
$$;


CREATE FUNCTION public.create_manual_receipt(p_date date, p_amount numeric, p_customer_id uuid, p_particulars text, p_tds_amount numeric DEFAULT 0, p_allocations jsonb DEFAULT NULL::jsonb, p_receipt_method text DEFAULT 'bank'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_fy            INT;
    v_fy_hash       TEXT;
    v_stmt_id       UUID;
    v_line_no       INT;
    v_line_id       UUID;
    v_alloc_sum     NUMERIC(14,2);
    v_expected      NUMERIC(14,2);
    v_bill_ids      UUID[];
    v_inv_id        UUID;
    v_inv_customer  UUID;
    v_alloc         JSONB;
    v_enq           JSONB;
    v_cust_active   BOOLEAN;
    v_cust_deleted  TIMESTAMPTZ;
    v_inv_synced    BOOLEAN;
BEGIN
    IF p_amount IS NULL OR p_amount <= 0 THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'INVALID_AMOUNT',
            'error', 'Amount must be greater than zero');
    END IF;

    IF p_customer_id IS NULL THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'CUSTOMER_REQUIRED',
            'error', 'Customer is required');
    END IF;

    IF p_receipt_method NOT IN ('bank', 'cash') THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'INVALID_RECEIPT_METHOD',
            'error', format('Invalid receipt_method "%s" — must be ''bank'' or ''cash''', p_receipt_method));
    END IF;

    SELECT active, deleted_at INTO v_cust_active, v_cust_deleted
    FROM public.customers WHERE id = p_customer_id;

    IF v_cust_active IS NULL THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'CUSTOMER_NOT_FOUND',
            'error', format('Customer %s not found', p_customer_id));
    END IF;
    IF v_cust_deleted IS NOT NULL OR v_cust_active = false THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'CUSTOMER_INACTIVE',
            'error', 'Customer is inactive or deleted — cannot create receipt');
    END IF;

    IF EXTRACT(MONTH FROM p_date) >= 4 THEN
        v_fy := EXTRACT(YEAR FROM p_date)::INT;
    ELSE
        v_fy := EXTRACT(YEAR FROM p_date)::INT - 1;
    END IF;

    v_fy_hash := 'MANUAL-FY-' || v_fy::TEXT;

    SELECT id INTO v_stmt_id
    FROM public.bank_statements
    WHERE account_number = 'MANUAL'
      AND period_start = make_date(v_fy, 4, 1);

    IF NOT FOUND THEN
        INSERT INTO public.bank_statements (
            account_number, storage_path, file_hash,
            status, period_start, period_end,
            total_debit, total_credit, uploaded_at
        ) VALUES (
            'MANUAL', 'manual://receipts', v_fy_hash,
            'parsed', make_date(v_fy, 4, 1), make_date(v_fy + 1, 3, 31),
            0, 0, NOW()
        )
        RETURNING id INTO v_stmt_id;
    END IF;

    SELECT COALESCE(MAX(line_no), 0) + 1 INTO v_line_no
    FROM public.bank_statement_lines WHERE statement_id = v_stmt_id;

    v_bill_ids := ARRAY[]::UUID[];

    IF p_allocations IS NOT NULL AND jsonb_array_length(p_allocations) > 0 THEN
        SELECT COALESCE(SUM((a->>'amount')::NUMERIC(14,2)), 0)
        INTO v_alloc_sum FROM jsonb_array_elements(p_allocations) a;

        v_expected := p_amount + COALESCE(p_tds_amount, 0);
        IF v_alloc_sum - v_expected > 1.00 THEN
            RETURN jsonb_build_object('success', false,
                'error_code', 'ALLOCATION_MISMATCH',
                'error', format(
                    'Allocation sum (%s) cannot exceed amount (%s) + TDS (%s) = %s',
                    v_alloc_sum, p_amount, COALESCE(p_tds_amount, 0), v_expected
                ));
        END IF;

        FOR v_alloc IN SELECT * FROM jsonb_array_elements(p_allocations)
        LOOP
            v_inv_id := (v_alloc->>'invoice_id')::UUID;

            SELECT customer_id INTO v_inv_customer
            FROM public.invoice WHERE id = v_inv_id AND deleted_at IS NULL;

            IF v_inv_customer IS NULL THEN
                RETURN jsonb_build_object('success', false,
                    'error_code', 'INVOICE_NOT_FOUND',
                    'error', format('Invoice %s not found or deleted', v_inv_id));
            END IF;

            IF v_inv_customer != p_customer_id THEN
                RETURN jsonb_build_object('success', false,
                    'error_code', 'INVOICE_WRONG_CUSTOMER',
                    'error', format('Invoice %s does not belong to customer %s', v_inv_id, p_customer_id));
            END IF;

            SELECT (tally_voucher_id IS NOT NULL) INTO v_inv_synced
            FROM public.tally_vouchers WHERE invoice_id = v_inv_id LIMIT 1;

            IF v_inv_synced IS NULL OR v_inv_synced = false THEN
                RETURN jsonb_build_object('success', false,
                    'error_code', 'INVOICE_NOT_IN_TALLY',
                    'error', format('Invoice %s is not yet synced to Tally. Run the invoice backfill before allocating against this invoice.', v_inv_id));
            END IF;

            v_bill_ids := v_bill_ids || v_inv_id;
        END LOOP;
    END IF;

    INSERT INTO public.bank_statement_lines (
        statement_id, line_no, tran_date, particulars,
        credit, debit, status, match_kind,
        matched_customer_id, matched_allocations, tds_amount,
        matched_bill_ids, confirmed_at, receipt_method
    ) VALUES (
        v_stmt_id, v_line_no, p_date, COALESCE(p_particulars, 'Manual receipt'),
        p_amount, 0, 'matched', 'manual',
        p_customer_id,
        CASE WHEN jsonb_array_length(COALESCE(p_allocations, '[]'::JSONB)) > 0
             THEN p_allocations ELSE NULL END,
        COALESCE(p_tds_amount, 0),
        CASE WHEN array_length(v_bill_ids, 1) > 0 THEN v_bill_ids ELSE NULL END,
        NOW(),
        p_receipt_method
    )
    RETURNING id INTO v_line_id;

    SELECT public.enqueue_receipt_voucher(v_line_id) INTO v_enq;

    IF (v_enq->>'success')::BOOLEAN != true THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'ENQUEUE_FAILED',
            'error', 'Failed to enqueue voucher: ' || (v_enq->>'error'));
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'line_id', v_line_id,
            'voucher_number', v_enq->'data'->>'voucher_number',
            'queue_id', v_enq->'data'->>'queue_id',
            'receipt_method', p_receipt_method
        )
    );
END;
$$;


CREATE FUNCTION public.create_order(p_order_data jsonb, p_items jsonb, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_order_id UUID;
    v_order_no TEXT;
    v_customer_id UUID;
    v_customer_name TEXT;
    v_user_profile_id UUID;
    v_item JSONB;
    v_current_stock INTEGER;
    v_total_requested INTEGER := 0;
    v_item_count INTEGER := 0;
    v_order_data_obj JSONB;
    v_items_array JSONB;
    v_order_item_id UUID;
BEGIN
    -- Get user profile ID
    SELECT id INTO v_user_profile_id
    FROM user_profiles
    WHERE auth_user_id = auth.uid();

    IF v_user_profile_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'User not found',
            'data', null
        );
    END IF;

    -- Handle case where p_order_data might be a JSON string
    IF jsonb_typeof(p_order_data) = 'string' THEN
        v_order_data_obj := (p_order_data#>>'{}')::JSONB;
    ELSE
        v_order_data_obj := p_order_data;
    END IF;

    -- Handle case where p_items might be a JSON string
    IF jsonb_typeof(p_items) = 'string' THEN
        v_items_array := (p_items#>>'{}')::JSONB;
    ELSE
        v_items_array := p_items;
    END IF;

    -- Extract customer info from order data
    v_customer_id := (v_order_data_obj->>'customer_id')::UUID;
    v_customer_name := v_order_data_obj->>'customer_name';

    -- Check if user has access to this customer
    IF NOT is_admin_or_supervisor() AND v_customer_id != ALL(user_accessible_customers()) THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Access denied to customer',
            'data', null
        );
    END IF;

    -- Generate order number
    v_order_no := generate_order_number();

    -- Calculate totals and validate stock
    FOR v_item IN SELECT * FROM jsonb_array_elements(v_items_array)
    LOOP
        v_total_requested := v_total_requested + (v_item->>'requested_quantity')::INTEGER;
        v_item_count := v_item_count + 1;

        -- Check stock availability
        SELECT stock INTO v_current_stock
        FROM goodsreceived_trl
        WHERE id = (v_item->>'grn_items_id')::UUID;

        IF v_current_stock IS NULL THEN
            RETURN jsonb_build_object(
                'success', false,
                'message', 'GRN item not found: ' || (v_item->>'grn_items_id'),
                'data', null
            );
        END IF;

        IF v_current_stock < (v_item->>'requested_quantity')::INTEGER THEN
            RETURN jsonb_build_object(
                'success', false,
                'message', 'Insufficient stock for GRN item: ' || (v_item->>'grn_items_id') ||
                    ' (Available: ' || v_current_stock || ', Requested: ' || (v_item->>'requested_quantity') || ')',
                'data', null
            );
        END IF;
    END LOOP;

    -- Create order
    INSERT INTO orders (
        order_no, order_date, requested_dispatch_date, status, priority,
        customer_id, customer_name, customer_email, customer_phone, note,
        total_requested_qty, item_count, created_by, updated_by
    )
    VALUES (
        v_order_no,
        (v_order_data_obj->>'order_date')::TIMESTAMP WITH TIME ZONE,
        (v_order_data_obj->>'requested_dispatch_date')::TIMESTAMP WITH TIME ZONE,
        'pending',
        COALESCE(v_order_data_obj->>'priority', 'normal'),
        v_customer_id,
        v_customer_name,
        v_order_data_obj->>'customer_email',
        v_order_data_obj->>'customer_phone',
        v_order_data_obj->>'note',
        v_total_requested,
        v_item_count,
        v_user_profile_id,
        v_user_profile_id
    )
    RETURNING id INTO v_order_id;

    -- Log order creation
    PERFORM log_order_change(
        p_order_id := v_order_id,
        p_order_item_id := NULL,
        p_action := 'order_created',
        p_details := jsonb_build_object(
            'order_no', v_order_no,
            'customer_name', v_customer_name,
            'total_items', v_item_count,
            'total_requested_qty', v_total_requested,
            'priority', COALESCE(v_order_data_obj->>'priority', 'normal'),
            'requested_dispatch_date', v_order_data_obj->>'requested_dispatch_date'
        ),
        p_changed_by := v_user_profile_id
    );

    -- Create order items
    FOR v_item IN SELECT * FROM jsonb_array_elements(v_items_array)
    LOOP
        INSERT INTO order_items (
            order_id, order_no, requested_quantity, grn_items_id, grn_items_item_id,
            grn_items_item_name, grn_items_package_mark, grn_items_packaging,
            grn_items_rack, grn_items_weight, grn_items_image_url,
            grns_id, grns_gr_no, grns_date, grns_customer_id, grns_customer_name,
            available_stock_at_order, current_stock, item_status, sort_order
        )
        SELECT
            v_order_id,
            v_order_no,
            (v_item->>'requested_quantity')::INTEGER,
            (v_item->>'grn_items_id')::UUID,
            grt.item_id,
            grt.item_name,
            grt.package_mark,
            grt.packaging,
            grt.rack,
            grt.weight,
            grt.trl_img_url,
            gr.id,
            gr.gr_no,
            gr.date,
            gr.customer_id,
            gr.customer_name,
            grt.stock,
            grt.stock,
            'pending',
            COALESCE((v_item->>'sort_order')::INTEGER, 0)
        FROM goodsreceived_trl grt
        INNER JOIN goodsreceived gr ON grt.gr_id = gr.id
        WHERE grt.id = (v_item->>'grn_items_id')::UUID
        RETURNING id INTO v_order_item_id;

        -- Log each item addition
        PERFORM log_order_change(
            p_order_id := v_order_id,
            p_order_item_id := v_order_item_id,
            p_action := 'item_added',
            p_details := jsonb_build_object(
                'item_name', (SELECT item_name FROM goodsreceived_trl WHERE id = (v_item->>'grn_items_id')::UUID),
                'requested_quantity', (v_item->>'requested_quantity')::INTEGER,
                'available_stock', v_current_stock,
                'reason', 'Item added during order creation'
            ),
            p_changed_by := v_user_profile_id
        );
    END LOOP;

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Order created successfully',
        'data', jsonb_build_object(
            'order_id', v_order_id,
            'order_no', v_order_no
        )
    );

EXCEPTION
    WHEN OTHERS THEN
        RAISE WARNING 'create_order failed: % - %', SQLSTATE, SQLERRM;
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Order creation failed: ' || SQLERRM,
            'data', null
        );
END;
$$;


CREATE FUNCTION public.deactivate_sensor(p_device_mac character varying, p_reason text DEFAULT 'User removed sensor'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_sensor_id UUID;
    v_sensor_name TEXT;
BEGIN
    -- Get sensor info
    SELECT id, device_name INTO v_sensor_id, v_sensor_name
    FROM sensor_devices
    WHERE mac_address = p_device_mac;

    IF v_sensor_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', null,
            'message', 'Sensor not found',
            'error', jsonb_build_object('code', 'SENSOR_NOT_FOUND')
        );
    END IF;

    -- Deactivate sensor in registry
    UPDATE sensor_devices
    SET
        active = FALSE,
        deactivated_at = NOW(),
        deactivation_reason = p_reason,
        updated_at = NOW()
    WHERE mac_address = p_device_mac;

    -- Log deactivation event
    INSERT INTO sensor_health_events (
        device_id,
        device_mac,
        device_name,
        event_type,
        severity,
        event_message,
        metadata
    ) VALUES (
        v_sensor_id,
        p_device_mac,
        v_sensor_name,
        'SENSOR_DEACTIVATED',
        'INFO',
        'Sensor removed from active monitoring: ' || p_reason,
        jsonb_build_object('reason', p_reason)
    );

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object('sensor_id', v_sensor_id),
        'message', 'Sensor deactivated successfully'
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', null,
            'message', SQLERRM,
            'error', jsonb_build_object('code', 'DATABASE_ERROR')
        );
END;
$$;


CREATE FUNCTION public.debug_auth_context() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_auth_uid UUID;
    v_jwt_claims TEXT;
    v_jwt_sub TEXT;
    v_user_profile RECORD;
BEGIN
    v_auth_uid := auth.uid();

    BEGIN
        v_jwt_claims := current_setting('request.jwt.claims', true);
    EXCEPTION WHEN OTHERS THEN
        v_jwt_claims := 'ERROR: ' || SQLERRM;
    END;

    BEGIN
        v_jwt_sub := current_setting('request.jwt.claim.sub', true);
    EXCEPTION WHEN OTHERS THEN
        v_jwt_sub := 'ERROR: ' || SQLERRM;
    END;

    SELECT * INTO v_user_profile FROM public.user_profiles WHERE auth_user_id = v_auth_uid;

    RETURN utils.success_response(
        jsonb_build_object(
            'auth_uid', v_auth_uid,
            'jwt_claims', v_jwt_claims,
            'jwt_sub', v_jwt_sub,
            'user_profile_found', (v_user_profile.id IS NOT NULL),
            'user_profile_id', v_user_profile.id,
            'user_name', v_user_profile.name,
            'user_role', v_user_profile.role
        )
    );
END;
$$;


CREATE FUNCTION public.debug_current_user_grn_access() RETURNS TABLE(auth_uid uuid, user_email character varying, user_role public.user_role, is_supervisor boolean, can_access_grn_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  BEGIN
      RETURN QUERY
      SELECT
          auth.uid() as auth_uid,
          up.email as user_email,
          up.role as user_role,
          is_admin_or_supervisor() as is_supervisor,
          (SELECT COUNT(*) FROM goodsreceived WHERE date >= '2024-01-01' AND date <= '2025-01-11') as can_access_grn_count
      FROM user_profiles up
      WHERE up.auth_user_id = auth.uid();
  END;
  $$;


CREATE FUNCTION public.debug_jwt_claims() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  BEGIN
      RETURN jsonb_build_object(
          'jwt_setting_available',
          CASE
              WHEN current_setting('request.jwt.claims', true) IS NOT NULL
              THEN true
              ELSE false
          END,
          'jwt_claims',
          COALESCE(current_setting('request.jwt.claims', true)::jsonb, '{}'::jsonb),
          'user_role_from_jwt',
          COALESCE(current_setting('request.jwt.claims', true)::jsonb->>'user_role', 'not_found')
      );
  END;
  $$;


CREATE FUNCTION public.debug_otp_verification(p_phone_number character varying, p_otp_code character varying) RETURNS TABLE(step_name text, result text, found_record boolean)
    LANGUAGE plpgsql
    AS $$
  DECLARE
      v_otp_record otp_verifications%ROWTYPE;
  BEGIN
      -- Step 1: Try to find OTP record
      RETURN QUERY SELECT 'Step 1: Looking for OTP'::text, 'Starting search'::text, false;

      SELECT * INTO v_otp_record
      FROM otp_verifications
      WHERE phone_number = p_phone_number
      AND otp_code = p_otp_code
      AND verified = false
      AND created_at > NOW() - INTERVAL '10 minutes'
      ORDER BY created_at DESC
      LIMIT 1;

      -- Step 2: Check if found
      IF FOUND THEN
          RETURN QUERY SELECT 'Step 2: Record found'::text, ('ID: ' || v_otp_record.id::text)::text, true;
          RETURN QUERY SELECT 'Step 3: Success'::text, 'OTP verification would succeed'::text, true;
      ELSE
          RETURN QUERY SELECT 'Step 2: Record NOT found'::text, 'No matching OTP record'::text, false;
      END IF;
  END;
  $$;


CREATE FUNCTION public.debug_search_customer_items_for_order(p_search_query text DEFAULT ''::text, p_customer_id uuid DEFAULT NULL::uuid, p_search_type text DEFAULT 'auto'::text, p_stock_filter_min integer DEFAULT 1, p_page_size integer DEFAULT 50, p_offset integer DEFAULT 0, p_catalog_id uuid DEFAULT NULL::uuid, p_weight_min numeric DEFAULT NULL::numeric, p_weight_max numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_search_type_final TEXT;
    v_weight_min_final DECIMAL;
    v_weight_max_final DECIMAL;
    v_accessible_customers UUID[];
    v_debug_info JSONB;
    v_customer_check INTEGER;
    v_items_before_weight INTEGER;
    v_items_after_weight INTEGER;
    v_is_admin BOOLEAN;
    v_sample_weights JSONB;
BEGIN
    -- Step 1: Authentication check
    v_is_admin := is_admin_or_supervisor();

    IF v_is_admin THEN
        -- Admin/Supervisor: all active customers
        IF p_customer_id IS NOT NULL THEN
            v_accessible_customers := ARRAY[p_customer_id];
        ELSE
            SELECT ARRAY(SELECT id FROM customers WHERE active = true AND deleted_at IS NULL) INTO v_accessible_customers;
        END IF;
    ELSE
        -- Customer role: only assigned customers
        SELECT user_accessible_customers() INTO v_accessible_customers;

        -- SECURITY FIX: Return error if no accessible customers
        IF v_accessible_customers IS NULL OR array_length(v_accessible_customers, 1) IS NULL THEN
            RETURN jsonb_build_object(
                'error', 'No accessible customers',
                'debug_info', jsonb_build_object(
                    'auth_status', 'failed',
                    'reason', 'User has no assigned customers'
                )
            );
        END IF;

        -- If p_customer_id provided, validate access
        IF p_customer_id IS NOT NULL THEN
            IF NOT (p_customer_id = ANY(v_accessible_customers)) THEN
                RETURN jsonb_build_object(
                    'error', 'Access denied to customer',
                    'debug_info', jsonb_build_object(
                        'auth_status', 'denied',
                        'reason', 'Customer not in accessible list'
                    )
                );
            END IF;
            v_accessible_customers := ARRAY[p_customer_id];
        END IF;
    END IF;

    -- Step 2: Search type detection
    IF p_search_type = 'weight_range' OR (p_weight_min IS NOT NULL AND p_weight_max IS NOT NULL) THEN
        v_search_type_final := 'weight_range';
        v_weight_min_final := COALESCE(p_weight_min, 0);
        v_weight_max_final := COALESCE(p_weight_max, 999999);
    ELSIF p_search_type = 'auto' AND p_search_query ~ '^[0-9]+\.?[0-9]*-[0-9]+\.?[0-9]*$' THEN
        v_search_type_final := 'weight_range';
        v_weight_min_final := split_part(p_search_query, '-', 1)::DECIMAL;
        v_weight_max_final := split_part(p_search_query, '-', 2)::DECIMAL;
    ELSE
        v_search_type_final := 'all';
    END IF;

    -- Step 3: Debug checks
    SELECT CASE WHEN p_customer_id = ANY(v_accessible_customers) THEN 1 ELSE 0 END
    INTO v_customer_check;

    -- Count items for this customer before weight filtering
    SELECT COUNT(*)
    INTO v_items_before_weight
    FROM goodsreceived_trl grt
    JOIN goodsreceived gr ON grt.gr_id = gr.id
    WHERE gr.customer_id = ANY(v_accessible_customers)
        AND gr.deleted_at IS NULL
        AND grt.stock >= p_stock_filter_min
        AND (p_customer_id IS NULL OR gr.customer_id = p_customer_id);

    -- Count items after weight filtering
    SELECT COUNT(*)
    INTO v_items_after_weight
    FROM goodsreceived_trl grt
    JOIN goodsreceived gr ON grt.gr_id = gr.id
    WHERE gr.customer_id = ANY(v_accessible_customers)
        AND gr.deleted_at IS NULL
        AND grt.stock >= p_stock_filter_min
        AND (p_customer_id IS NULL OR gr.customer_id = p_customer_id)
        AND (
            v_search_type_final = 'all'
            OR (v_search_type_final = 'weight_range'
                AND grt.weight >= v_weight_min_final
                AND grt.weight <= v_weight_max_final)
        );

    -- Get sample weights
    SELECT COALESCE(jsonb_agg(weight), '[]'::jsonb)
    INTO v_sample_weights
    FROM (
        SELECT DISTINCT grt.weight
        FROM goodsreceived_trl grt
        JOIN goodsreceived gr ON grt.gr_id = gr.id
        WHERE gr.customer_id = ANY(v_accessible_customers)
            AND gr.deleted_at IS NULL
            AND grt.stock >= p_stock_filter_min
            AND (p_customer_id IS NULL OR gr.customer_id = p_customer_id)
        ORDER BY grt.weight
        LIMIT 20
    ) weights;

    -- Build debug info
    v_debug_info := jsonb_build_object(
        'input_params', jsonb_build_object(
            'p_search_query', p_search_query,
            'p_customer_id', p_customer_id,
            'p_search_type', p_search_type,
            'p_stock_filter_min', p_stock_filter_min,
            'p_weight_min', p_weight_min,
            'p_weight_max', p_weight_max
        ),
        'auth_info', jsonb_build_object(
            'is_admin', v_is_admin,
            'accessible_customers_count', COALESCE(array_length(v_accessible_customers, 1), 0),
            'customer_in_list', v_customer_check = 1
        ),
        'search_info', jsonb_build_object(
            'final_search_type', v_search_type_final,
            'weight_min', v_weight_min_final,
            'weight_max', v_weight_max_final
        ),
        'counts', jsonb_build_object(
            'items_before_weight_filter', v_items_before_weight,
            'items_after_weight_filter', v_items_after_weight
        ),
        'sample_weights', v_sample_weights
    );

    RETURN v_debug_info;
END;
$_$;


CREATE FUNCTION public.debug_user_access(input_user_mobile character varying DEFAULT NULL::character varying) RETURNS TABLE(user_mobile character varying, user_role public.user_role, accessible_customers uuid[], customer_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      target_auth_id uuid;
  BEGIN
      -- If no mobile provided, use current user
      IF input_user_mobile IS NULL THEN
          target_auth_id := auth.uid();
      ELSE
          SELECT auth_user_id INTO target_auth_id
          FROM user_profiles
          WHERE mobile = input_user_mobile;  -- Changed from email
      END IF;

      RETURN QUERY
      SELECT
          up.mobile,  -- Changed from up.email
          up.role,
          CASE
              WHEN up.role IN ('admin', 'supervisor', 'staff') THEN
                  ARRAY(SELECT id FROM customers WHERE active = true)
              ELSE
                  ARRAY(SELECT uc.customer_id FROM users_customers_new uc WHERE uc.user_profile_id = up.id AND uc.active = true)
          END as accessible_customers,
          CASE
              WHEN up.role IN ('admin', 'supervisor', 'staff') THEN
                  (SELECT COUNT(*)::int FROM customers WHERE active = true)
              ELSE
                  (SELECT COUNT(*)::int FROM users_customers_new uc WHERE uc.user_profile_id = up.id AND uc.active = true)
          END as customer_count
      FROM user_profiles up
      WHERE up.auth_user_id = target_auth_id AND up.active = true;
  END;
$$;


CREATE FUNCTION public.delete_contra_voucher(p_voucher_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_voucher  public.tally_contra_vouchers;
    v_config   public.bank_reco_company_config;
    v_queue_id UUID;
BEGIN
    SELECT * INTO v_voucher FROM public.tally_contra_vouchers
    WHERE id = p_voucher_id FOR UPDATE;

    IF v_voucher.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Contra voucher not found');
    END IF;

    IF v_voucher.status = 'queued' THEN
        IF v_voucher.tally_sync_queue_id IS NOT NULL THEN
            UPDATE public.tally_contra_vouchers
            SET tally_sync_queue_id = NULL
            WHERE id = p_voucher_id;
            DELETE FROM public.tally_sync_queue WHERE id = v_voucher.tally_sync_queue_id;
        END IF;
        DELETE FROM public.tally_contra_vouchers WHERE id = p_voucher_id;

        RETURN jsonb_build_object('success', true, 'data',
            jsonb_build_object('voucher_id', p_voucher_id, 'deleted', true));
    END IF;

    SELECT * INTO v_config FROM public.bank_reco_company_config LIMIT 1;

    INSERT INTO public.tally_sync_queue (entity_type, entity_id, operation, payload)
    VALUES (
        'contra', p_voucher_id, 'delete',
        jsonb_build_object(
            'voucher_id',           p_voucher_id,
            'voucher_number',       v_voucher.voucher_number,
            'tally_voucher_id',     v_voucher.tally_voucher_id,
            'tally_company',        v_config.tally_company
        )
    ) RETURNING id INTO v_queue_id;

    UPDATE public.tally_contra_vouchers SET
        status              = 'queued',
        tally_sync_queue_id = v_queue_id,
        review_note         = format('delete queued at %s', now()::text)
    WHERE id = p_voucher_id;

    RETURN jsonb_build_object('success', true, 'data',
        jsonb_build_object('voucher_id', p_voucher_id, 'queue_id', v_queue_id, 'deleted', false));
END;
$$;


CREATE FUNCTION public.delete_dispatch_image(p_image_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_id UUID;
    v_user_profile_id UUID;
    v_storage_path TEXT;
BEGIN
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN RETURN utils.not_authenticated_response(); END IF;

    SELECT id INTO v_user_profile_id FROM user_profiles WHERE auth_user_id = v_user_id;
    IF v_user_profile_id IS NULL THEN RETURN utils.error_response('USER_PROFILE_NOT_FOUND', 'User profile not found.'); END IF;

    SELECT storage_path INTO v_storage_path FROM dispatch_images WHERE id = p_image_id;
    IF v_storage_path IS NULL THEN RETURN utils.not_found_response('Image', p_image_id::text); END IF;

    DELETE FROM dispatch_images WHERE id = p_image_id;
    IF NOT FOUND THEN RETURN utils.error_response('PERMISSION_DENIED', 'Permission denied or image not found'); END IF;

    RETURN utils.success_response(jsonb_build_object('storage_path', v_storage_path, 'deleted_by', v_user_profile_id), 'Image deleted successfully');
EXCEPTION
    WHEN OTHERS THEN RETURN utils.database_error_response('Failed to delete image', SQLERRM, SQLSTATE);
END;
$$;


CREATE FUNCTION public.delete_dispatch_with_order_cleanup(p_dispatch_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_profile_id UUID;
    v_dispatch_record dispatch%ROWTYPE;
    v_accessible_customers UUID[];
    v_linked_orders_count INTEGER;
    v_order_record RECORD;
    v_stock_updates jsonb := '[]'::jsonb;
    v_cart_restoration jsonb;
    v_item record;
    v_old_stock integer;
    v_new_stock integer;
    v_grn_items_restored INTEGER := 0;
    v_orders_updated INTEGER := 0;
    v_out_of_stock_reset INTEGER := 0;
    v_order_items_restored INTEGER := 0;
    v_order_items_recreated INTEGER := 0;
    v_debug_info jsonb := '[]'::jsonb;
    v_source_order_no TEXT;
    v_restored_items jsonb := '[]'::jsonb;
    v_cart_restoration_error TEXT := NULL;
    v_has_cart_items BOOLEAN := FALSE;
    v_invoice_count INTEGER := 0;  -- NEW: For invoice safeguard
BEGIN
    -- Get user profile ID
    SELECT id INTO v_user_profile_id
    FROM user_profiles
    WHERE auth_user_id = auth.uid();

    IF v_user_profile_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'User not found',
            'message', 'User not found'
        );
    END IF;

    -- Get dispatch details
    SELECT * INTO v_dispatch_record FROM dispatch WHERE id = p_dispatch_id;

    IF v_dispatch_record.id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Dispatch not found',
            'message', 'Dispatch not found'
        );
    END IF;

    -- Check access permissions
    IF NOT is_admin_or_supervisor() THEN
        v_accessible_customers := user_accessible_customers();
        IF NOT (v_dispatch_record.customer_id = ANY(v_accessible_customers)) THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'Access denied to this dispatch',
                'message', 'Access denied to this dispatch'
            );
        END IF;
    END IF;

    -- ⚠️ NEW: CRITICAL INVOICE SAFEGUARD
    -- Check if dispatch has any invoiced items
    SELECT COUNT(*) INTO v_invoice_count
    FROM invoice_trl it
    WHERE it.disp_trl_id IN (
        SELECT id FROM dispatch_trl WHERE disp_id = p_dispatch_id
    );

    IF v_invoice_count > 0 THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', format('Cannot delete dispatch %s: %s invoice items exist',
                           v_dispatch_record.disp_no, v_invoice_count),
            'message', 'Delete invoices first before deleting this dispatch',
            'dispatch_no', v_dispatch_record.disp_no,
            'dispatch_id', p_dispatch_id,
            'invoice_items_count', v_invoice_count,
            'instructions', 'You must delete all related invoices before this dispatch can be deleted',
            'blocking_reason', 'invoices_exist'
        );
    END IF;
    -- END NEW SAFEGUARD

    -- Collect information about items being restored BEFORE deletion
    FOR v_item IN
        SELECT
            dt.disp_qty,
            gt.item_name,
            gt.package_mark,
            gr.gr_no
        FROM dispatch_trl dt
        JOIN goodsreceived_trl gt ON gt.id = dt.gr_trl_id
        JOIN goodsreceived gr ON gr.id = gt.gr_id
        WHERE dt.disp_id = p_dispatch_id
    LOOP
        v_restored_items := v_restored_items || jsonb_build_object(
            'item_name', v_item.item_name,
            'package_mark', v_item.package_mark,
            'grn_no', v_item.gr_no,
            'quantity_restored', v_item.disp_qty
        );
    END LOOP;

    -- Get the source order number if we have a source order
    IF v_dispatch_record.source_order_id IS NOT NULL THEN
        -- Get order_no, or generate one if it's null/empty
        SELECT
            CASE
                WHEN order_no IS NULL OR order_no = '' THEN
                    'ORD-' || TO_CHAR(CURRENT_DATE, 'YYYYMMDD') || '-' || SUBSTRING(id::text FROM 1 FOR 8)
                ELSE
                    order_no
            END INTO v_source_order_no
        FROM orders
        WHERE id = v_dispatch_record.source_order_id;

        -- If we generated an order_no, update the order record
        UPDATE orders
        SET order_no = v_source_order_no
        WHERE id = v_dispatch_record.source_order_id
        AND (order_no IS NULL OR order_no = '');
    END IF;

    -- IMPROVED: Check if this dispatch has any cart-related items before attempting cart restoration
    IF v_dispatch_record.source_order_id IS NOT NULL THEN
        -- Check if there are any cart items to restore
        SELECT EXISTS (
            SELECT 1
            FROM dispatch_trl dt
            WHERE dt.disp_id = p_dispatch_id
            AND dt.source_type = 'cart'
            AND dt.source_order_item_id IS NOT NULL
            AND dt.cart_quantity_consumed > 0
        ) INTO v_has_cart_items;

        IF v_has_cart_items THEN
            BEGIN
                -- Try cart restoration for cart items
                v_cart_restoration := restore_cart_quantities_from_dispatch(p_dispatch_id);

                -- Check if cart restoration failed with an actual error
                IF v_cart_restoration IS NULL THEN
                    v_cart_restoration := jsonb_build_object(
                        'success', false,
                        'message', 'Cart restoration returned null - possible data integrity issue',
                        'updates_made', 0
                    );
                    v_cart_restoration_error := 'Cart restoration returned null';
                END IF;

            EXCEPTION
                WHEN others THEN
                    -- Capture the error but don't fail the entire operation
                    v_cart_restoration_error := SQLERRM;
                    v_cart_restoration := jsonb_build_object(
                        'success', false,
                        'error', SQLERRM,
                        'message', 'Cart restoration failed but continuing with dispatch deletion',
                        'updates_made', 0
                    );

                    -- Log the error for debugging but continue
                    v_debug_info := v_debug_info || jsonb_build_object(
                        'cart_restoration_error', SQLERRM,
                        'timestamp', NOW(),
                        'action', 'cart_restoration_failed_but_continuing'
                    );
            END;
        ELSE
            -- No cart items in this dispatch
            v_cart_restoration := jsonb_build_object(
                'success', true,
                'message', 'No cart items to restore - dispatch was created directly from order items',
                'updates_made', 0,
                'restoration_details', '[]'::jsonb
            );
        END IF;
    ELSE
        -- No source order, set default cart restoration result
        v_cart_restoration := jsonb_build_object(
            'success', true,
            'message', 'No cart quantities to restore - dispatch was not from an order',
            'updates_made', 0,
            'restoration_details', '[]'::jsonb
        );
    END IF;

    -- Restore stock for each dispatch item
    FOR v_item IN
        SELECT
            dt.*,
            gt.item_name,
            gt.packaging,
            gt.weight,
            gt.gr_id
        FROM dispatch_trl dt
        LEFT JOIN goodsreceived_trl gt ON gt.id = dt.gr_trl_id
        WHERE dt.disp_id = p_dispatch_id
    LOOP
        -- Get current stock from goodsreceived_trl
        SELECT stock INTO v_old_stock
        FROM goodsreceived_trl
        WHERE id = v_item.gr_trl_id;

        v_new_stock := LEAST((SELECT qty FROM goodsreceived_trl WHERE id = v_item.gr_trl_id), COALESCE(v_old_stock, 0) + v_item.disp_qty);

        -- Update stock in goodsreceived_trl
        UPDATE goodsreceived_trl
        SET
            stock = v_new_stock
        WHERE id = v_item.gr_trl_id;

        v_grn_items_restored := v_grn_items_restored + 1;

        -- Record the update
        v_stock_updates := v_stock_updates || jsonb_build_object(
            'gr_trl_id', v_item.gr_trl_id,
            'gr_id', v_item.gr_id,
            'item_name', v_item.item_name,
            'packaging', v_item.packaging,
            'weight', v_item.weight,
            'quantity_restored', v_item.disp_qty,
            'old_stock', v_old_stock,
            'new_stock', v_new_stock
        );
    END LOOP;

    -- Reset out_of_stock flag for GRNs that now have stock
    WITH grn_stock_status AS (
        SELECT
            gr.id,
            gr.out_of_stock as current_status,
            COALESCE(SUM(grt.stock), 0) as total_stock
        FROM goodsreceived gr
        INNER JOIN goodsreceived_trl grt ON grt.gr_id = gr.id
        WHERE gr.id IN (
            SELECT DISTINCT gt.gr_id
            FROM dispatch_trl dt
            JOIN goodsreceived_trl gt ON gt.id = dt.gr_trl_id
            WHERE dt.disp_id = p_dispatch_id
        )
        GROUP BY gr.id, gr.out_of_stock
    )
    UPDATE goodsreceived
    SET out_of_stock = FALSE
    FROM grn_stock_status
    WHERE goodsreceived.id = grn_stock_status.id
    AND grn_stock_status.current_status = TRUE
    AND grn_stock_status.total_stock > 0;

    -- Get count of rows affected
    GET DIAGNOSTICS v_out_of_stock_reset = ROW_COUNT;

    -- Check if there are linked orders - now just check source_order_id
    v_linked_orders_count := 0;
    IF v_dispatch_record.source_order_id IS NOT NULL THEN
        v_linked_orders_count := 1;

        -- For each dispatch item, restore or recreate order items
        FOR v_item IN
            SELECT
                dt.id as dispatch_trl_id,
                dt.gr_trl_id,
                dt.disp_qty,
                dt.source_type,
                dt.source_order_item_id,
                dt.cart_quantity_consumed,
                gt.item_name,
                gt.item_id,
                gt.package_mark,
                gt.packaging,
                gt.rack,
                gt.weight,
                gt.gr_id,
                gr.gr_no,
                gr.date as gr_date,
                gr.customer_id,
                gr.customer_name,
                gr.gr_image_url
            FROM dispatch_trl dt
            JOIN goodsreceived_trl gt ON gt.id = dt.gr_trl_id
            JOIN goodsreceived gr ON gr.id = gt.gr_id
            WHERE dt.disp_id = p_dispatch_id
        LOOP
            -- Check if order item exists
            IF EXISTS (
                SELECT 1 FROM order_items
                WHERE order_id = v_dispatch_record.source_order_id
                AND grn_items_id = v_item.gr_trl_id
            ) THEN
                -- FIXED: Update existing order item with proper constraint checking
                UPDATE order_items
                SET
                    fulfilled_quantity = LEAST(
                        requested_quantity,
                        GREATEST(0, fulfilled_quantity - v_item.disp_qty)
                    ),
                    item_status = CASE
                        WHEN GREATEST(0, fulfilled_quantity - v_item.disp_qty) = 0 THEN 'pending'
                        WHEN GREATEST(0, fulfilled_quantity - v_item.disp_qty) < requested_quantity THEN 'partially_fulfilled'
                        ELSE 'fulfilled'
                    END,
                    current_stock = (SELECT stock FROM goodsreceived_trl WHERE id = grn_items_id),
                    updated_at = now()
                WHERE order_id = v_dispatch_record.source_order_id
                AND grn_items_id = v_item.gr_trl_id;

                v_order_items_restored := v_order_items_restored + 1;
            ELSE
                -- Recreate the order item that was deleted during dispatch
                INSERT INTO order_items (
                    order_id,
                    order_no,
                    requested_quantity,
                    fulfilled_quantity,
                    grn_items_id,
                    grn_items_item_id,
                    grn_items_item_name,
                    grn_items_package_mark,
                    grn_items_packaging,
                    grn_items_rack,
                    grn_items_weight,
                    grn_items_image_url,
                    grns_id,
                    grns_gr_no,
                    grns_date,
                    grns_customer_id,
                    grns_customer_name,
                    available_stock_at_order,
                    current_stock,
                    item_status,
                    created_at,
                    updated_at
                ) VALUES (
                    v_dispatch_record.source_order_id,
                    v_source_order_no,
                    v_item.disp_qty,
                    v_item.disp_qty,
                    v_item.gr_trl_id,
                    v_item.item_id,
                    v_item.item_name,
                    v_item.package_mark,
                    v_item.packaging,
                    v_item.rack,
                    v_item.weight,
                    v_item.gr_image_url,
                    v_item.gr_id,
                    v_item.gr_no,
                    v_item.gr_date,
                    v_item.customer_id,
                    v_item.customer_name,
                    (SELECT stock FROM goodsreceived_trl WHERE id = v_item.gr_trl_id),
                    (SELECT stock FROM goodsreceived_trl WHERE id = v_item.gr_trl_id),
                    'fulfilled',
                    now(),
                    now()
                );

                v_order_items_recreated := v_order_items_recreated + 1;
            END IF;
        END LOOP;

        -- Add dispatch deletion to orders.revisions
        UPDATE orders
        SET
            revisions = COALESCE(revisions, '[]'::jsonb) || jsonb_build_array(
                jsonb_build_object(
                    'action', 'dispatch_deleted',
                    'timestamp', NOW(),
                    'by', v_user_profile_id,
                    'dispatch_id', v_dispatch_record.id,
                    'dispatch_no', v_dispatch_record.disp_no,
                    'restored_items', v_restored_items,
                    'total_quantity_restored', (
                        SELECT COALESCE(SUM(disp_qty), 0)
                        FROM dispatch_trl
                        WHERE disp_id = p_dispatch_id
                    ),
                    'cart_restoration_status', CASE
                        WHEN v_cart_restoration_error IS NOT NULL THEN 'failed'
                        WHEN NOT v_has_cart_items THEN 'not_applicable'
                        ELSE 'success'
                    END
                )
            )
        WHERE id = v_dispatch_record.source_order_id;

        -- Update order status to OPEN and clear soft-delete
        UPDATE orders
        SET
            status = 'OPEN',
            deleted_at = NULL,
            deleted_by = NULL,
            updated_by = v_user_profile_id,
            updated_at = now()
        WHERE id = v_dispatch_record.source_order_id;

        v_orders_updated := 1;
    END IF;

    -- Delete dispatch items
    DELETE FROM dispatch_trl WHERE disp_id = p_dispatch_id;

    -- Delete dispatch
    DELETE FROM dispatch WHERE id = p_dispatch_id;

    -- Return comprehensive result
    RETURN jsonb_build_object(
        'success', true,
        'message', format('Dispatch %s deleted successfully. %s linked order(s) reset, %s order items restored/recreated, %s GRN items restored, %s out_of_stock flags reset.',
                         v_dispatch_record.disp_no,
                         v_linked_orders_count,
                         v_order_items_restored + v_order_items_recreated + COALESCE((v_cart_restoration->>'updates_made')::integer, 0),
                         v_grn_items_restored,
                         v_out_of_stock_reset),
        'dispatch_id', p_dispatch_id,
        'dispatch_no', v_dispatch_record.disp_no,
        'customer_id', v_dispatch_record.customer_id,
        'customer_name', v_dispatch_record.customer_name,
        'stock_updates', v_stock_updates,
        'cart_restoration', v_cart_restoration,
        'order_restoration', jsonb_build_object(
            'items_updated', v_order_items_restored,
            'items_recreated', v_order_items_recreated,
            'cart_items_restored', COALESCE((v_cart_restoration->>'updates_made')::integer, 0),
            'total_items_restored', v_order_items_restored + v_order_items_recreated + COALESCE((v_cart_restoration->>'updates_made')::integer, 0)
        ),
        'statistics', jsonb_build_object(
            'orders_updated', v_orders_updated,
            'grn_items_restored', v_grn_items_restored,
            'out_of_stock_flags_reset', v_out_of_stock_reset,
            'linked_orders_count', v_linked_orders_count,
            'order_items_restored', v_order_items_restored + v_order_items_recreated + COALESCE((v_cart_restoration->>'updates_made')::integer, 0),
            'dispatch_had_cart_items', v_has_cart_items
        ),
        'timestamp', CURRENT_TIMESTAMP,
        'deleted_by', v_user_profile_id
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', SQLERRM,
            'message', 'Database error occurred',
            'dispatch_id', p_dispatch_id,
            'debug_info', v_debug_info
        );
END;
$$;


CREATE FUNCTION public.delete_dispatch_with_stock_restore(p_dispatch_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_item RECORD;
    v_user_id uuid;
    v_items_restored integer := 0;
    v_linked_orders_count integer := 0;
    v_order_record RECORD;
    v_source_order_id uuid;
BEGIN
    -- Check if user is admin or supervisor
    IF NOT is_admin_or_supervisor() THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Only administrators and supervisors can delete dispatches'
        );
    END IF;

    -- Set context for RLS policies
    PERFORM set_config('app.in_stock_function', 'true', true);

    -- Get current user
    SELECT id INTO v_user_id FROM user_profiles WHERE auth_user_id = auth.uid();

    -- Check if dispatch exists and get source_order_id
    SELECT source_order_id INTO v_source_order_id
    FROM dispatch WHERE id = p_dispatch_id;

    IF v_source_order_id IS NULL AND NOT EXISTS (SELECT 1 FROM dispatch WHERE id = p_dispatch_id) THEN
        RAISE EXCEPTION 'Dispatch not found';
    END IF;

    -- RESTORE SOURCE ORDER (if dispatch was created from order)
    IF v_source_order_id IS NOT NULL THEN
        -- Clear the soft-delete on the source order
        UPDATE orders
        SET
            deleted_at = NULL,
            deleted_by = NULL,
            updated_at = NOW(),
            updated_by = v_user_id
        WHERE id = v_source_order_id;

        v_linked_orders_count := 1;
    END IF;

    -- Also check for orders linked via dispatch_id (legacy support)
    SELECT COUNT(*) INTO v_linked_orders_count
    FROM orders
    WHERE dispatch_id = p_dispatch_id;

    IF v_linked_orders_count > 0 THEN
        FOR v_order_record IN
            SELECT * FROM orders WHERE dispatch_id = p_dispatch_id
        LOOP
            UPDATE order_items
            SET
                fulfilled_quantity = GREATEST(0, fulfilled_quantity - COALESCE(dt.disp_qty, 0)),
                item_status = CASE
                    WHEN GREATEST(0, fulfilled_quantity - COALESCE(dt.disp_qty, 0)) = 0 THEN 'pending'
                    WHEN GREATEST(0, fulfilled_quantity - COALESCE(dt.disp_qty, 0)) < requested_quantity THEN 'partially_fulfilled'
                    ELSE 'fulfilled'
                END,
                current_stock = (SELECT stock FROM goodsreceived_trl WHERE id = order_items.grn_items_id),
                updated_at = now()
            FROM dispatch_trl dt
            WHERE order_items.order_id = v_order_record.id
            AND order_items.grn_items_id = dt.gr_trl_id
            AND dt.disp_id = p_dispatch_id;

            UPDATE orders
            SET
                total_fulfilled_qty = (
                    SELECT COALESCE(SUM(fulfilled_quantity), 0)
                    FROM order_items
                    WHERE order_id = v_order_record.id
                ),
                status = 'OPEN',
                dispatch_id = NULL,
                dispatch_no = NULL,
                dispatch_created_at = NULL,
                updated_by = v_user_id,
                updated_at = now()
            WHERE id = v_order_record.id;
        END LOOP;
    END IF;

    -- Process each item and restore stock
    FOR v_item IN
        SELECT dt.id, dt.gr_trl_id, dt.disp_qty, gt.stock, gt.item_name, gt.gr_id
        FROM dispatch_trl dt
        JOIN goodsreceived_trl gt ON gt.id = dt.gr_trl_id
        WHERE dt.disp_id = p_dispatch_id
        FOR UPDATE OF gt
    LOOP
        UPDATE goodsreceived_trl
        SET stock = LEAST(qty, stock + v_item.disp_qty)
        WHERE id = v_item.gr_trl_id;

        PERFORM update_grn_out_of_stock_status(v_item.gr_id);

        INSERT INTO stock_movements (
            gr_trl_id, movement_type, quantity,
            reference_id, reference_type,
            balance_before, balance_after, created_by,
            notes
        )
        VALUES (
            v_item.gr_trl_id,
            'return',
            v_item.disp_qty,
            p_dispatch_id,
            'dispatch_delete',
            v_item.stock,
            v_item.stock + v_item.disp_qty,
            v_user_id,
            format('Stock restored due to dispatch deletion. Item: %s', v_item.item_name)
        );

        v_items_restored := v_items_restored + 1;
    END LOOP;

    -- Delete dispatch items and main dispatch
    DELETE FROM dispatch_trl WHERE disp_id = p_dispatch_id;
    DELETE FROM dispatch WHERE id = p_dispatch_id;

    RETURN jsonb_build_object(
        'success', true,
        'message', format('Dispatch deleted, %s items restored to stock', v_items_restored) ||
                  CASE WHEN v_source_order_id IS NOT NULL THEN ', source order restored' ELSE '' END,
        'items_restored', v_items_restored,
        'source_order_restored', v_source_order_id IS NOT NULL,
        'source_order_id', v_source_order_id
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', SQLERRM
        );
END;
$$;


CREATE FUNCTION public.delete_dispatch_with_stock_restore(p_dispatch_id uuid, p_retry_count integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    -- Delegate to the 1-arg version
    RETURN delete_dispatch_with_stock_restore(p_dispatch_id);
END;
$$;


CREATE FUNCTION public.delete_grn_image(p_image_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_id UUID;
    v_user_profile_id UUID;
    v_storage_path TEXT;
BEGIN
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN RETURN utils.not_authenticated_response(); END IF;

    SELECT id INTO v_user_profile_id FROM user_profiles WHERE auth_user_id = v_user_id;
    IF v_user_profile_id IS NULL THEN RETURN utils.error_response('USER_PROFILE_NOT_FOUND', 'User profile not found.'); END IF;

    SELECT storage_path INTO v_storage_path FROM grn_images WHERE id = p_image_id;
    IF v_storage_path IS NULL THEN RETURN utils.not_found_response('Image', p_image_id::text); END IF;

    DELETE FROM grn_images WHERE id = p_image_id;
    IF NOT FOUND THEN RETURN utils.error_response('PERMISSION_DENIED', 'Permission denied or image not found'); END IF;

    RETURN utils.success_response(jsonb_build_object('storage_path', v_storage_path, 'deleted_by', v_user_profile_id), 'Image deleted successfully');
EXCEPTION
    WHEN OTHERS THEN RETURN utils.database_error_response('Failed to delete image', SQLERRM, SQLSTATE);
END;
$$;


CREATE FUNCTION public.delete_grn_safe(p_grn_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
      DECLARE
          v_user_id uuid;
          v_user_role text;
          v_grn_record RECORD;
          v_dependency_check RECORD;
          v_items_deleted int := 0;
          v_movements_deleted int := 0;
          v_images_deleted int := 0;
          v_errors_deleted int := 0;
          v_order_items_deleted int := 0;
      BEGIN
          -- Authentication and authorization
          v_user_id := auth.uid();
          IF v_user_id IS NULL THEN
              RETURN jsonb_build_object(
                  'success', false,
                  'error', 'Authentication required'
              );
          END IF;

          -- Get user role
          SELECT role INTO v_user_role
          FROM user_profiles
          WHERE auth_user_id = v_user_id;

          -- Only admin and supervisor can delete GRNs
          IF v_user_role NOT IN ('admin', 'supervisor') THEN
              RETURN jsonb_build_object(
                  'success', false,
                  'error', 'Only administrators and supervisors can delete GRNs'
              );
          END IF;

          -- Check if GRN exists and get info
          SELECT gr.*, c.name as customer_name
          INTO v_grn_record
          FROM goodsreceived gr
          LEFT JOIN customers c ON c.id = gr.customer_id
          WHERE gr.id = p_grn_id;

          IF NOT FOUND THEN
              RETURN jsonb_build_object(
                  'success', false,
                  'error', 'GRN not found'
              );
          END IF;

          -- ❌ STRICT DEPENDENCY CHECKS - Block deletion if dispatches or invoices exist
          SELECT
              COUNT(DISTINCT dt.id) as dispatches,
              COUNT(DISTINCT it.id) as invoiced_dispatches,
              COUNT(DISTINCT sm.id) as stock_movements,
              COUNT(DISTINCT gi.id) as images,
              COUNT(DISTINCT aie.id) as auto_invoice_errors,
              COUNT(DISTINCT oi.id) as order_items
          INTO v_dependency_check
          FROM goodsreceived gr
          LEFT JOIN goodsreceived_trl grt ON grt.gr_id = gr.id
          LEFT JOIN dispatch_trl dt ON dt.gr_id = gr.id
          LEFT JOIN invoice_trl it ON it.disp_trl_id = dt.id
          LEFT JOIN stock_movements sm ON sm.gr_trl_id = grt.id
          LEFT JOIN grn_images gi ON gi.grn_id = gr.id
          LEFT JOIN auto_invoice_errors aie ON aie.gr_id = gr.id
          LEFT JOIN order_items oi ON (oi.grns_id = gr.id OR oi.grn_items_id = grt.id)
          WHERE gr.id = p_grn_id;

          -- ❌ Block if ANY invoices exist
          IF v_dependency_check.invoiced_dispatches > 0 THEN
              RETURN jsonb_build_object(
                  'success', false,
                  'error', format('Cannot delete GRN %s: %s dispatch items have been invoiced. Delete invoices first.',
                                v_grn_record.gr_no, v_dependency_check.invoiced_dispatches),
                  'blocking_dependencies', jsonb_build_object(
                      'invoiced_dispatches', v_dependency_check.invoiced_dispatches,
                      'total_dispatches', v_dependency_check.dispatches
                  ),
                  'grn_info', jsonb_build_object(
                      'gr_no', v_grn_record.gr_no,
                      'customer_name', COALESCE(v_grn_record.customer_name, 'Unknown'),
                      'date', v_grn_record.date
                  ),
                  'instructions', 'Delete all invoices and dispatches manually before deleting this GRN'
              );
          END IF;

          -- ❌ Block if ANY dispatches exist
          IF v_dependency_check.dispatches > 0 THEN
              RETURN jsonb_build_object(
                  'success', false,
                  'error', format('Cannot delete GRN %s: %s dispatch items exist. Delete dispatches first.',
                                v_grn_record.gr_no, v_dependency_check.dispatches),
                  'blocking_dependencies', jsonb_build_object(
                      'dispatches', v_dependency_check.dispatches
                  ),
                  'grn_info', jsonb_build_object(
                      'gr_no', v_grn_record.gr_no,
                      'customer_name', COALESCE(v_grn_record.customer_name, 'Unknown'),
                      'date', v_grn_record.date
                  ),
                  'instructions', 'Delete all dispatches manually before deleting this GRN'
              );
          END IF;

          -- ✅ SAFE DELETION PROCESS - Handle dependencies in correct order

          -- 1. Delete order_items that reference this GRN (FIXES YOUR FK CONSTRAINT ERROR)
          DELETE FROM order_items
          WHERE grns_id = p_grn_id
          OR grn_items_id IN (
              SELECT id FROM goodsreceived_trl WHERE gr_id = p_grn_id
          );
          GET DIAGNOSTICS v_order_items_deleted = ROW_COUNT;

          -- 2. Delete stock movements
          DELETE FROM stock_movements
          WHERE gr_trl_id IN (
              SELECT id FROM goodsreceived_trl WHERE gr_id = p_grn_id
          );
          GET DIAGNOSTICS v_movements_deleted = ROW_COUNT;

          -- 3. Delete auto invoice errors (safe dependency)
          DELETE FROM auto_invoice_errors
          WHERE gr_id = p_grn_id;
          GET DIAGNOSTICS v_errors_deleted = ROW_COUNT;

          -- 4. Delete GRN images (safe dependency)
          DELETE FROM grn_images
          WHERE grn_id = p_grn_id;
          GET DIAGNOSTICS v_images_deleted = ROW_COUNT;

          -- 5. Delete GRN items (goodsreceived_trl)
          DELETE FROM goodsreceived_trl
          WHERE gr_id = p_grn_id;
          GET DIAGNOSTICS v_items_deleted = ROW_COUNT;

          -- 6. Finally, delete the main GRN record
          DELETE FROM goodsreceived
          WHERE id = p_grn_id;

          RETURN jsonb_build_object(
              'success', true,
              'message', format('GRN %s deleted successfully', v_grn_record.gr_no),
              'grn_info', jsonb_build_object(
                  'gr_no', v_grn_record.gr_no,
                  'customer_name', COALESCE(v_grn_record.customer_name, 'Unknown'),
                  'date', v_grn_record.date
              ),
              'deleted_counts', jsonb_build_object(
                  'grn_items', v_items_deleted,
                  'order_items', v_order_items_deleted,
                  'stock_movements', v_movements_deleted,
                  'images', v_images_deleted,
                  'auto_invoice_errors', v_errors_deleted
              ),
              'deletion_type', 'safe_with_order_cleanup',
              'note', CASE
                  WHEN v_order_items_deleted > 0 THEN
                      format('Removed %s order items that referenced this GRN', v_order_items_deleted)
                  ELSE
                      'No order items were referencing this GRN'
              END
          );

      EXCEPTION
          WHEN OTHERS THEN
              RETURN jsonb_build_object(
                  'success', false,
                  'error', 'Deletion failed: ' || SQLERRM,
                  'grn_info', jsonb_build_object(
                      'gr_no', COALESCE(v_grn_record.gr_no, 'unknown'),
                      'customer_name', COALESCE(v_grn_record.customer_name, 'unknown')
                  )
              );
      END;
  $$;


CREATE FUNCTION public.delete_invoice(p_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_gr_id UUID;
BEGIN
    -- Get GR ID before deleting
    SELECT gr_id INTO v_gr_id FROM invoice WHERE id = p_invoice_id;

    IF v_gr_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Invoice not found'
        );
    END IF;

    -- Delete invoice items (CASCADE should handle this, but explicit is safer)
    DELETE FROM invoice_trl WHERE invoice_id = p_invoice_id;

    -- Delete invoice
    DELETE FROM invoice WHERE id = p_invoice_id;

    -- Reset GRN invoiced flag
    UPDATE goodsreceived SET invoiced = false WHERE id = v_gr_id;

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Invoice deleted successfully',
        'gr_id', v_gr_id
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', SQLERRM
    );
END;
$$;


CREATE FUNCTION public.delete_item_safe(p_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_item_name text;
    v_grn_count integer;
    v_order_count integer;
    v_pricing_count integer;
BEGIN
    -- Security check
    IF NOT is_admin_or_supervisor() THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Access denied: Admin or supervisor role required'
        );
    END IF;

    -- Check if item exists
    SELECT name INTO v_item_name FROM items WHERE id = p_item_id;

    IF v_item_name IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Item not found'
        );
    END IF;

    -- Check for references in GRN items
    SELECT COUNT(*) INTO v_grn_count
    FROM goodsreceived_trl
    WHERE item_id = p_item_id;

    -- Check for references in order items
    SELECT COUNT(*) INTO v_order_count
    FROM order_items
    WHERE grn_items_item_id = p_item_id;

    -- Check for pricing records (these can be auto-deleted)
    SELECT COUNT(*) INTO v_pricing_count
    FROM item_storage_prices
    WHERE item_id = p_item_id;

    -- If referenced in GRN or Orders, cannot delete
    IF v_grn_count > 0 OR v_order_count > 0 THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', format('Cannot delete item "%s": It is referenced in existing records', v_item_name),
            'references', jsonb_build_object(
                'grn_items_count', v_grn_count,
                'order_items_count', v_order_count,
                'pricing_count', v_pricing_count
            )
        );
    END IF;

    -- Delete pricing records first (if any)
    IF v_pricing_count > 0 THEN
        DELETE FROM item_storage_prices WHERE item_id = p_item_id;
    END IF;

    -- Delete the item
    DELETE FROM items WHERE id = p_item_id;

    RETURN jsonb_build_object(
        'success', true,
        'message', format('Item "%s" deleted successfully', v_item_name),
        'deleted_pricing_records', v_pricing_count
    );
END;
$$;


CREATE FUNCTION public.delete_item_storage_price(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_role TEXT;
    v_existing RECORD;
BEGIN
    -- Authorization: admin/supervisor only
    SELECT role INTO v_user_role FROM user_profiles WHERE auth_user_id = auth.uid();
    IF v_user_role IS NULL OR v_user_role NOT IN ('admin', 'supervisor') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Permission denied');
    END IF;

    -- Check if record exists
    SELECT isp.id, i.name as item_name, c.name as customer_name
    INTO v_existing
    FROM item_storage_prices isp
    LEFT JOIN items i ON isp.item_id = i.id
    LEFT JOIN customers c ON isp.customer_id = c.id
    WHERE isp.id = p_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Price record not found');
    END IF;

    -- Delete the record
    DELETE FROM item_storage_prices WHERE id = p_id;

    RETURN jsonb_build_object(
        'success', true,
        'message', format('Price deleted successfully (Item: %s, Customer: %s)',
            COALESCE(v_existing.item_name, 'Unknown'),
            COALESCE(v_existing.customer_name, 'Default'))
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', 'Delete failed: ' || SQLERRM
    );
END;
$$;


CREATE FUNCTION public.delete_manual_receipt(p_line_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_line             public.bank_statement_lines;
    v_voucher_number   text;
    v_tally_voucher_id text;
    v_queue_id         uuid;
    v_config           public.bank_reco_company_config;
    v_payments_deleted integer := 0;
BEGIN
    SELECT * INTO v_line FROM public.bank_statement_lines WHERE id = p_line_id FOR UPDATE;
    IF v_line.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Receipt not found');
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM public.bank_statements bs
        WHERE bs.id = v_line.statement_id AND bs.account_number = 'MANUAL'
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Not a manual receipt');
    END IF;

    IF v_line.status = 'queued' THEN
        RETURN jsonb_build_object('success', false,
            'error', 'Receipt is pending Tally sync — wait for it to complete first');
    END IF;
    IF v_line.status = 'skipped' THEN
        RETURN jsonb_build_object('success', false, 'error', 'Receipt is already deleted');
    END IF;

    IF v_line.status = 'reconciled' THEN
        SELECT voucher_number, tally_voucher_id
        INTO v_voucher_number, v_tally_voucher_id
        FROM public.tally_receipt_vouchers WHERE bank_line_id = p_line_id;

        SELECT * INTO v_config FROM public.bank_reco_company_config LIMIT 1;

        INSERT INTO public.tally_sync_queue (entity_type, entity_id, operation, payload)
        VALUES (
            'receipt', p_line_id, 'delete',
            jsonb_build_object(
                'voucher_number',   v_voucher_number,
                'tally_voucher_id', v_tally_voucher_id,
                'tally_company',    v_config.tally_company
            )
        ) RETURNING id INTO v_queue_id;

        UPDATE public.bank_statement_lines SET
            status              = 'skipped',
            review_note         = format('deleted at %s', now()::text),
            tally_sync_queue_id = v_queue_id
        WHERE id = p_line_id;

        -- G14: remove the payment rows spawned by save_tally_receipt_voucher
        -- (payment_no = voucher_number || '-' || alloc_idx) so customer
        -- balance views don't double-count after deletion.
        IF v_voucher_number IS NOT NULL THEN
            DELETE FROM public.payments
             WHERE payment_no LIKE v_voucher_number || '-%';
            GET DIAGNOSTICS v_payments_deleted = ROW_COUNT;
        END IF;

        RETURN jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'queue_id',         v_queue_id,
                'payments_deleted', v_payments_deleted
            )
        );
    END IF;

    -- matched (or any other non-reconciled, non-queued): simple soft-delete, no Tally action,
    -- no payment rows to clean (they're only created on reconcile/save).
    UPDATE public.bank_statement_lines SET
        status      = 'skipped',
        review_note = format('deleted at %s', now()::text)
    WHERE id = p_line_id;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object('queue_id', null, 'payments_deleted', 0)
    );
END;
$$;


CREATE FUNCTION public.delete_resolved_auto_invoice_errors(p_error_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_deleted_count INTEGER := 0;
    v_user_role TEXT;
    v_error_id UUID;
    v_error_record RECORD;
    v_results JSONB := '[]'::JSONB;
    v_result JSONB;
BEGIN
    -- Check if user is a supervisor
    SELECT role INTO v_user_role
    FROM user_profiles
    WHERE auth_user_id = auth.uid();

    IF v_user_role IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'User not found',
            'deleted_count', 0
        );
    END IF;

    IF v_user_role <> 'supervisor' THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Only supervisors can delete auto-invoice errors',
            'deleted_count', 0
        );
    END IF;

    -- Process each error ID
    FOREACH v_error_id IN ARRAY p_error_ids
    LOOP
        -- Get the error record first
        SELECT * INTO v_error_record
        FROM auto_invoice_errors
        WHERE id = v_error_id;

        IF NOT FOUND THEN
            v_result := jsonb_build_object(
                'id', v_error_id,
                'success', false,
                'error', 'Error record not found'
            );
        ELSIF v_error_record.resolved_at IS NULL THEN
            v_result := jsonb_build_object(
                'id', v_error_id,
                'success', false,
                'error', 'Cannot delete unresolved error'
            );
        ELSE
            -- Delete the resolved error
            DELETE FROM auto_invoice_errors
            WHERE id = v_error_id;

            IF FOUND THEN
                v_deleted_count := v_deleted_count + 1;
                v_result := jsonb_build_object(
                    'id', v_error_id,
                    'success', true,
                    'customer_name', v_error_record.customer_name,
                    'resolved_at', v_error_record.resolved_at
                );
            ELSE
                v_result := jsonb_build_object(
                    'id', v_error_id,
                    'success', false,
                    'error', 'Failed to delete error'
                );
            END IF;
        END IF;

        v_results := v_results || v_result;
    END LOOP;

    RETURN jsonb_build_object(
        'success', v_deleted_count > 0,
        'deleted_count', v_deleted_count,
        'total_requested', array_length(p_error_ids, 1),
        'results', v_results
    );
END;
$$;


CREATE FUNCTION public.delete_user_account() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
    v_auth_uid uuid;
    v_user_profile_id uuid;
    v_deleted_sessions int;
    v_deleted_assignments int;
    v_deleted_activity int;
    v_anon_mobile text;
BEGIN
    -- 1. Verify caller is authenticated
    v_auth_uid := auth.uid();

    IF v_auth_uid IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Authentication required'
        );
    END IF;

    -- 2. Get the user_profile_id
    SELECT id INTO v_user_profile_id
    FROM public.user_profiles
    WHERE auth_user_id = v_auth_uid;

    IF v_user_profile_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'User profile not found'
        );
    END IF;

    -- 3. Delete customer assignments for this user
    DELETE FROM public.users_customers_new
    WHERE user_profile_id = v_user_profile_id;
    GET DIAGNOSTICS v_deleted_assignments = ROW_COUNT;

    -- 4. Delete session activity records
    DELETE FROM public.user_session_activity
    WHERE user_id = v_user_profile_id;
    GET DIAGNOSTICS v_deleted_activity = ROW_COUNT;

    -- 5. Delete all active auth sessions for this user
    DELETE FROM auth.sessions
    WHERE user_id = v_auth_uid;
    GET DIAGNOSTICS v_deleted_sessions = ROW_COUNT;

    -- 6. Delete refresh tokens (user_id is varchar in this table)
    DELETE FROM auth.refresh_tokens
    WHERE user_id = v_auth_uid::text;

    -- 7. Delete MFA factors if any
    DELETE FROM auth.mfa_factors
    WHERE user_id = v_auth_uid;

    -- 8. Anonymize user_profile (can't delete due to FK constraints from historical records)
    -- Generate unique anonymized mobile using first 8 chars of UUID (fits in varchar(15))
    v_anon_mobile := 'DEL' || replace(left(v_user_profile_id::text, 12), '-', '');

    UPDATE public.user_profiles
    SET
        name = 'Deleted User',
        display_name = 'Deleted User',
        mobile = v_anon_mobile,
        mobile_verified = false,
        mobile_verified_at = NULL,
        active = false,
        updated_at = now()
    WHERE id = v_user_profile_id;

    -- 9. Delete identities
    DELETE FROM auth.identities
    WHERE user_id = v_auth_uid;

    -- 10. Delete one-time tokens
    DELETE FROM auth.one_time_tokens
    WHERE user_id = v_auth_uid;

    -- 11. Finally delete from auth.users
    DELETE FROM auth.users
    WHERE id = v_auth_uid;

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Account deleted',
        'details', jsonb_build_object(
            'sessions_revoked', v_deleted_sessions,
            'assignments_removed', v_deleted_assignments,
            'activity_records_removed', v_deleted_activity
        )
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', SQLERRM
        );
END;
$$;


CREATE FUNCTION public.enable_dispatch_triggers() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    -- Enable GRN triggers (only the ones that exist)
    IF EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'trg_mark_stock_mvs_dirty_grn' AND tgrelid = 'goodsreceived_trl'::regclass) THEN
        ALTER TABLE goodsreceived_trl ENABLE TRIGGER trg_mark_stock_mvs_dirty_grn;
    END IF;

    -- Enable dispatch triggers (only the ones that exist)
    IF EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'trg_mark_dispatch_mvs_dirty' AND tgrelid = 'dispatch_trl'::regclass) THEN
        ALTER TABLE dispatch_trl ENABLE TRIGGER trg_mark_dispatch_mvs_dirty;
    END IF;

    -- Enable invoice triggers (only the ones that exist)
    IF EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'trg_mv_invoice_list_refresh_on_inv' AND tgrelid = 'invoice'::regclass) THEN
        ALTER TABLE invoice ENABLE TRIGGER trg_mv_invoice_list_refresh_on_inv;
    END IF;

    IF EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'trg_mv_invoice_list_refresh_on_inv_trl' AND tgrelid = 'invoice_trl'::regclass) THEN
        ALTER TABLE invoice_trl ENABLE TRIGGER trg_mv_invoice_list_refresh_on_inv_trl;
    END IF;
END;
$$;


CREATE FUNCTION public.enqueue_contra_voucher(p_voucher_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_voucher   public.tally_contra_vouchers;
    v_queue_id  UUID;
BEGIN
    SELECT * INTO v_voucher
    FROM public.tally_contra_vouchers
    WHERE id = p_voucher_id;

    IF v_voucher.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Contra voucher not found');
    END IF;

    IF v_voucher.tally_sync_queue_id IS NOT NULL THEN
        RETURN jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'queue_id',       v_voucher.tally_sync_queue_id,
                'voucher_number', v_voucher.voucher_number,
                'already_queued', true
            )
        );
    END IF;

    INSERT INTO public.tally_sync_queue (
        entity_type, entity_id, operation, payload
    ) VALUES (
        'contra',
        p_voucher_id,
        'create',
        jsonb_build_object(
            'voucher_id',     p_voucher_id,
            'voucher_number', v_voucher.voucher_number,
            'voucher_date',   v_voucher.voucher_date,
            'from_ledger',    v_voucher.from_ledger,
            'to_ledger',      v_voucher.to_ledger,
            'amount',         v_voucher.amount,
            'particulars',    COALESCE(v_voucher.particulars, ''),
            'tally_company',  v_voucher.tally_company
        )
    )
    RETURNING id INTO v_queue_id;

    UPDATE public.tally_contra_vouchers
    SET tally_sync_queue_id = v_queue_id
    WHERE id = p_voucher_id;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'queue_id',       v_queue_id,
            'voucher_number', v_voucher.voucher_number,
            'already_queued', false
        )
    );
END;
$$;


CREATE FUNCTION public.get_tally_company() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
    SELECT tally_company FROM public.bank_reco_company_config LIMIT 1;
$$;


CREATE FUNCTION public.enqueue_historical_invoices(p_fin_year integer DEFAULT NULL::integer, p_batch_size integer DEFAULT 100, p_priority integer DEFAULT 8, p_tally_company text DEFAULT public.get_tally_company()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_enqueued   INT := 0;
    v_skipped    INT := 0;
    v_total      INT := 0;
    v_inv        RECORD;
BEGIN
    FOR v_inv IN
        SELECT i.id, i.inv_no, i.inv_fin_year, i.customer_id
        FROM public.invoice i
        LEFT JOIN public.tally_vouchers tv
            ON tv.invoice_id = i.id AND tv.tally_company = p_tally_company
        LEFT JOIN public.tally_sync_queue tsq
            ON tsq.entity_type = 'invoice' AND tsq.entity_id = i.id
        WHERE i.deleted_at IS NULL
          AND tv.id IS NULL
          AND tsq.id IS NULL
          AND (p_fin_year IS NULL OR i.inv_fin_year = p_fin_year)
        ORDER BY i.inv_fin_year ASC, i.inv_no ASC
        LIMIT p_batch_size
    LOOP
        v_total := v_total + 1;

        INSERT INTO public.tally_sync_queue (
            entity_type, entity_id, operation, priority, payload
        ) VALUES (
            'invoice',
            v_inv.id,
            'create',
            p_priority,
            jsonb_build_object(
                'invoice_id',   v_inv.id,
                'inv_no',       v_inv.inv_no,
                'inv_fin_year', v_inv.inv_fin_year,
                'customer_id',  v_inv.customer_id,
                'source',       'historical_backfill'
            )
        )
        ON CONFLICT (entity_type, entity_id)
            WHERE status IN ('pending', 'retry')
        DO NOTHING;

        IF FOUND THEN
            v_enqueued := v_enqueued + 1;
        ELSE
            v_skipped := v_skipped + 1;
        END IF;
    END LOOP;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'enqueued',               v_enqueued,
            'skipped_already_queued', v_skipped,
            'total_eligible',         v_total,
            'fin_year_filter',        p_fin_year,
            'batch_size',             p_batch_size
        )
    );
END;
$$;


CREATE FUNCTION public.enqueue_historical_invoices(p_fin_year integer DEFAULT NULL::integer, p_batch_size integer DEFAULT 100, p_priority integer DEFAULT 8, p_tally_company text DEFAULT public.get_tally_company(), p_force boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_unstuck  INT := 0;
    v_reset    INT := 0;
    v_enqueued INT := 0;
    v_skipped  INT := 0;
    v_total    INT := 0;
    v_inv      RECORD;
BEGIN
    -- 1. Unstick processing items locked > 10 minutes
    UPDATE public.tally_sync_queue
    SET status        = 'pending',
        locked_by     = NULL,
        locked_at     = NULL,
        next_retry_at = NULL,
        updated_at    = now()
    WHERE entity_type = 'invoice'
      AND status = 'processing'
      AND locked_at < now() - INTERVAL '10 minutes';
    GET DIAGNOSTICS v_unstuck = ROW_COUNT;

    -- 2. Reset dead_letter, failed, and exhausted retry items back to pending
    UPDATE public.tally_sync_queue
    SET status        = 'pending',
        retry_count   = 0,
        error_message = NULL,
        next_retry_at = NULL,
        locked_by     = NULL,
        locked_at     = NULL,
        updated_at    = now()
    WHERE entity_type = 'invoice'
      AND (
            status IN ('dead_letter', 'failed')
         OR (status = 'retry' AND retry_count >= max_retries)
      );
    GET DIAGNOSTICS v_reset = ROW_COUNT;

    -- 3. Enqueue missing (delta) or everything (force)
    FOR v_inv IN
        SELECT i.id, i.inv_no, i.inv_fin_year, i.customer_id
        FROM public.invoice i
        LEFT JOIN public.tally_vouchers tv
            ON tv.invoice_id = i.id
           AND tv.tally_company = p_tally_company
           AND NOT p_force
        WHERE i.deleted_at IS NULL
          AND tv.id IS NULL
          AND NOT EXISTS (
              SELECT 1 FROM public.tally_sync_queue tsq
              WHERE tsq.entity_type = 'invoice'
                AND tsq.entity_id = i.id
                AND tsq.status IN ('pending', 'retry', 'processing')
          )
          AND (p_fin_year IS NULL OR i.inv_fin_year = p_fin_year)
        ORDER BY i.inv_fin_year ASC, i.inv_no ASC
        LIMIT p_batch_size
    LOOP
        v_total := v_total + 1;

        INSERT INTO public.tally_sync_queue (
            entity_type, entity_id, operation, priority, payload
        ) VALUES (
            'invoice',
            v_inv.id,
            'create',
            p_priority,
            jsonb_build_object(
                'invoice_id',   v_inv.id,
                'inv_no',       v_inv.inv_no,
                'inv_fin_year', v_inv.inv_fin_year,
                'customer_id',  v_inv.customer_id,
                'source',       'historical_backfill'
            )
        )
        ON CONFLICT (entity_type, entity_id)
            WHERE status IN ('pending', 'retry')
        DO NOTHING;

        IF FOUND THEN
            v_enqueued := v_enqueued + 1;
        ELSE
            v_skipped := v_skipped + 1;
        END IF;
    END LOOP;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'unstuck',                v_unstuck,
            'reset',                  v_reset,
            'enqueued',               v_enqueued,
            'skipped_already_queued', v_skipped,
            'total_eligible',         v_total,
            'fin_year_filter',        p_fin_year,
            'batch_size',             p_batch_size,
            'force',                  p_force
        )
    );
END;
$$;


CREATE FUNCTION public.enqueue_historical_receipts(p_fin_year text DEFAULT NULL::text, p_batch_size integer DEFAULT 100, p_priority integer DEFAULT 8) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_enqueued   INT := 0;
    v_skipped    INT := 0;
    v_total      INT := 0;
    v_rec        RECORD;
    v_config     public.bank_reco_company_config;
    v_queue_id   uuid;
BEGIN
    SELECT * INTO v_config FROM public.bank_reco_company_config LIMIT 1;

    FOR v_rec IN
        SELECT bsl.id                   AS line_id,
               bsl.matched_customer_id,
               bsl.tds_amount,
               bsl.credit,
               bsl.matched_allocations,
               trv.voucher_number
        FROM public.bank_statement_lines bsl
        JOIN public.tally_receipt_vouchers trv ON trv.bank_line_id = bsl.id
        WHERE bsl.status = 'reconciled'
          AND (p_fin_year IS NULL OR trv.voucher_number LIKE 'RCP/' || p_fin_year || '/%')
          -- Skip receipts already active in the queue
          AND NOT EXISTS (
              SELECT 1 FROM public.tally_sync_queue tsq
              WHERE tsq.entity_type = 'receipt'
                AND tsq.entity_id = bsl.id
                AND tsq.status IN ('pending', 'retry', 'processing')
          )
        ORDER BY trv.voucher_number ASC
        LIMIT p_batch_size
    LOOP
        v_total := v_total + 1;

        -- Clear tally_voucher_id so middleware treats this as a fresh create,
        -- not an update. The middleware uses REMOTEID-based dedup on the Tally
        -- side to avoid actual duplicates if the voucher survived partial loss.
        UPDATE public.tally_receipt_vouchers
        SET tally_voucher_id = NULL
        WHERE bank_line_id = v_rec.line_id;

        INSERT INTO public.tally_sync_queue (
            entity_type, entity_id, operation, priority, payload
        ) VALUES (
            'receipt',
            v_rec.line_id,
            'create',
            p_priority,
            jsonb_build_object(
                'line_id',             v_rec.line_id,
                'customer_id',         v_rec.matched_customer_id,
                'voucher_number',      v_rec.voucher_number,
                'bank_account_ledger', v_config.bank_account_ledger,
                'tds_ledger',          v_config.tds_194c_ledger,
                'allocations',         v_rec.matched_allocations,
                'tds_amount',          v_rec.tds_amount,
                'credit_amount',       v_rec.credit,
                'source',              'historical_backfill'
            )
        )
        ON CONFLICT (entity_type, entity_id)
            WHERE status IN ('pending', 'retry')
        DO NOTHING
        RETURNING id INTO v_queue_id;

        IF v_queue_id IS NOT NULL THEN
            UPDATE public.bank_statement_lines SET
                status              = 'queued',
                tally_sync_queue_id = v_queue_id,
                review_note         = format('bulk-resynced at %s', now()::text)
            WHERE id = v_rec.line_id;

            v_enqueued := v_enqueued + 1;
        ELSE
            -- Race condition: another process enqueued between our pre-filter and INSERT
            v_skipped := v_skipped + 1;
        END IF;
    END LOOP;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'enqueued',               v_enqueued,
            'skipped_already_queued', v_skipped,
            'total_eligible',         v_total,
            'fin_year_filter',        p_fin_year,
            'batch_size',             p_batch_size
        )
    );
END;
$$;


CREATE FUNCTION public.enqueue_historical_receipts(p_fin_year text DEFAULT NULL::text, p_batch_size integer DEFAULT 100, p_priority integer DEFAULT 8, p_force boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_unstuck   INT := 0;
    v_reset     INT := 0;
    v_enqueued  INT := 0;
    v_skipped   INT := 0;
    v_total     INT := 0;
    v_rec       RECORD;
    v_config    public.bank_reco_company_config;
    v_queue_id  uuid;
BEGIN
    SELECT * INTO v_config FROM public.bank_reco_company_config LIMIT 1;

    -- 1. Unstick stuck processing receipts
    UPDATE public.tally_sync_queue
    SET status        = 'pending',
        locked_by     = NULL,
        locked_at     = NULL,
        next_retry_at = NULL,
        updated_at    = now()
    WHERE entity_type = 'receipt'
      AND status = 'processing'
      AND locked_at < now() - INTERVAL '10 minutes';
    GET DIAGNOSTICS v_unstuck = ROW_COUNT;

    -- 2. Reset dead_letter, failed, and exhausted retry receipts back to pending,
    --    and bring the bank_statement_lines badge along with them.
    WITH reset_q AS (
        UPDATE public.tally_sync_queue
        SET status        = 'pending',
            retry_count   = 0,
            error_message = NULL,
            next_retry_at = NULL,
            locked_by     = NULL,
            locked_at     = NULL,
            updated_at    = now()
        WHERE entity_type = 'receipt'
          AND (
                status IN ('dead_letter', 'failed')
             OR (status = 'retry' AND retry_count >= max_retries)
          )
        RETURNING entity_id
    ), bsl_synced AS (
        UPDATE public.bank_statement_lines bsl
        SET status = 'queued'
        FROM reset_q
        WHERE bsl.id = reset_q.entity_id
        RETURNING 1
    )
    SELECT COUNT(*) INTO v_reset FROM reset_q;

    -- 3. Enqueue receipts (delta or force)
    FOR v_rec IN
        SELECT bsl.id AS line_id,
               bsl.matched_customer_id,
               bsl.tds_amount,
               bsl.credit,
               bsl.matched_allocations,
               trv.voucher_number
        FROM public.bank_statement_lines bsl
        JOIN public.tally_receipt_vouchers trv ON trv.bank_line_id = bsl.id
        WHERE bsl.status = 'reconciled'
          AND (p_fin_year IS NULL OR trv.voucher_number LIKE 'RCP/' || p_fin_year || '/%')
          AND (p_force OR trv.tally_voucher_id IS NULL)
          AND NOT EXISTS (
              SELECT 1 FROM public.tally_sync_queue tsq
              WHERE tsq.entity_type = 'receipt'
                AND tsq.entity_id = bsl.id
                AND tsq.status IN ('pending', 'retry', 'processing')
          )
        ORDER BY trv.voucher_number ASC
        LIMIT p_batch_size
    LOOP
        v_total := v_total + 1;

        IF p_force THEN
            UPDATE public.tally_receipt_vouchers
            SET tally_voucher_id = NULL
            WHERE bank_line_id = v_rec.line_id;
        END IF;

        INSERT INTO public.tally_sync_queue (
            entity_type, entity_id, operation, priority, payload
        ) VALUES (
            'receipt',
            v_rec.line_id,
            'create',
            p_priority,
            jsonb_build_object(
                'line_id',             v_rec.line_id,
                'customer_id',         v_rec.matched_customer_id,
                'voucher_number',      v_rec.voucher_number,
                'bank_account_ledger', v_config.bank_account_ledger,
                'tds_ledger',          v_config.tds_194c_ledger,
                'allocations',         v_rec.matched_allocations,
                'tds_amount',          v_rec.tds_amount,
                'credit_amount',       v_rec.credit,
                'source',              'historical_backfill'
            )
        )
        ON CONFLICT (entity_type, entity_id)
            WHERE status IN ('pending', 'retry')
        DO NOTHING
        RETURNING id INTO v_queue_id;

        IF v_queue_id IS NOT NULL THEN
            UPDATE public.bank_statement_lines SET
                status              = 'queued',
                tally_sync_queue_id = v_queue_id,
                review_note         = format('bulk-resynced at %s', now()::text)
            WHERE id = v_rec.line_id;
            v_enqueued := v_enqueued + 1;
        ELSE
            v_skipped := v_skipped + 1;
        END IF;
    END LOOP;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'unstuck',                v_unstuck,
            'reset',                  v_reset,
            'enqueued',               v_enqueued,
            'skipped_already_queued', v_skipped,
            'total_eligible',         v_total,
            'fin_year_filter',        p_fin_year,
            'batch_size',             p_batch_size,
            'force',                  p_force
        )
    );
END;
$$;


CREATE FUNCTION public.enqueue_receipt_voucher(p_line_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_line           public.bank_statement_lines;
    v_queue_id       UUID;
    v_voucher_number TEXT;
    v_fy_start       INT;
    v_fy_label       TEXT;
    v_seq            BIGINT;
    v_config         public.bank_reco_company_config;
    v_ledger         TEXT;
BEGIN
    SELECT * INTO v_line
    FROM public.bank_statement_lines
    WHERE id = p_line_id;

    IF v_line.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Line not found');
    END IF;

    IF v_line.status = 'queued' AND v_line.tally_sync_queue_id IS NOT NULL THEN
        SELECT voucher_number INTO v_voucher_number
        FROM public.tally_receipt_vouchers
        WHERE bank_line_id = p_line_id;

        RETURN jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'queue_id', v_line.tally_sync_queue_id,
                'voucher_number', v_voucher_number,
                'already_queued', true
            )
        );
    END IF;

    IF v_line.status != 'matched' THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', format('Line status is "%s", must be "matched"', v_line.status)
        );
    END IF;

    SELECT * INTO v_config FROM public.bank_reco_company_config LIMIT 1;

    IF v_config.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'No company config found');
    END IF;

    -- Ledger routing: cash receipts use the Cash ledger; bank receipts use the
    -- configured bank account ledger.
    v_ledger := CASE
        WHEN v_line.receipt_method = 'cash' THEN v_config.cash_receipt_ledger
        ELSE v_config.bank_account_ledger
    END;

    IF EXTRACT(MONTH FROM v_line.tran_date) >= 4 THEN
        v_fy_start := EXTRACT(YEAR FROM v_line.tran_date)::INT;
    ELSE
        v_fy_start := EXTRACT(YEAR FROM v_line.tran_date)::INT - 1;
    END IF;
    v_fy_label := v_fy_start::TEXT || '-' || RIGHT((v_fy_start + 1)::TEXT, 2);

    INSERT INTO public.receipt_voucher_counters (financial_year, next_seq)
    VALUES (v_fy_label, 2)
    ON CONFLICT (financial_year)
    DO UPDATE SET next_seq = receipt_voucher_counters.next_seq + 1
    RETURNING next_seq - 1 INTO v_seq;

    v_voucher_number := 'RCP/' || v_fy_start::TEXT || '/' || lpad(v_seq::TEXT, 5, '0');

    INSERT INTO public.tally_sync_queue (
        entity_type, entity_id, operation, payload
    ) VALUES (
        'receipt',
        p_line_id,
        'create',
        jsonb_build_object(
            'line_id', p_line_id,
            'customer_id', v_line.matched_customer_id,
            'voucher_number', v_voucher_number,
            'bank_account_ledger', v_ledger,
            'tds_ledger', v_config.tds_194c_ledger,
            'allocations', v_line.matched_allocations,
            'tds_amount', v_line.tds_amount,
            'credit_amount', v_line.credit,
            'receipt_method', v_line.receipt_method
        )
    )
    RETURNING id INTO v_queue_id;

    UPDATE public.bank_statement_lines
    SET status = 'queued',
        tally_sync_queue_id = v_queue_id
    WHERE id = p_line_id;

    INSERT INTO public.tally_receipt_vouchers (
        bank_line_id, voucher_number, voucher_date, customer_id,
        bank_account_ledger, amount_received, tds_amount,
        tally_company, allocations
    ) VALUES (
        p_line_id,
        v_voucher_number,
        v_line.tran_date,
        v_line.matched_customer_id,
        v_ledger,
        v_line.credit,
        COALESCE(v_line.tds_amount, 0),
        v_config.tally_company,
        COALESCE(v_line.matched_allocations, '[]'::JSONB)
    )
    ON CONFLICT (bank_line_id) DO NOTHING;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'queue_id', v_queue_id,
            'voucher_number', v_voucher_number,
            'already_queued', false
        )
    );
END;
$$;


CREATE FUNCTION public.enqueue_tally_invoice_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    IF NEW.deleted_at IS NULL THEN
        -- Active invoice: enqueue create/update with coalescing
        INSERT INTO public.tally_sync_queue (entity_type, entity_id, operation, payload)
        VALUES (
            'invoice',
            NEW.id,
            CASE WHEN TG_OP = 'INSERT' THEN 'create' ELSE 'update' END,
            jsonb_build_object(
                'invoice_id', NEW.id,
                'inv_no', NEW.inv_no,
                'inv_fin_year', NEW.inv_fin_year,
                'customer_id', NEW.customer_id,
                'snapshot_version', NEW.xmin::text
            )
        )
        ON CONFLICT (entity_type, entity_id) WHERE status IN ('pending', 'retry')
        DO UPDATE SET
            operation = EXCLUDED.operation,
            payload = EXCLUDED.payload,
            updated_at = now();

        -- Notify middleware (fire-and-forget)
        PERFORM pg_notify('tally_sync', jsonb_build_object(
            'entity_type', 'invoice',
            'entity_id', NEW.id,
            'operation', CASE WHEN TG_OP = 'INSERT' THEN 'create' ELSE 'update' END
        )::text);
    ELSE
        -- Soft-deleted: enqueue delete (only when newly soft-deleted)
        IF OLD.deleted_at IS NULL THEN
            INSERT INTO public.tally_sync_queue (entity_type, entity_id, operation, priority, payload)
            VALUES (
                'invoice',
                NEW.id,
                'delete',
                1,
                jsonb_build_object(
                    'invoice_id', NEW.id,
                    'inv_no', NEW.inv_no,
                    'inv_fin_year', NEW.inv_fin_year,
                    'customer_id', NEW.customer_id,
                    'deleted_at', NEW.deleted_at,
                    'deleted_by', NEW.deleted_by
                )
            )
            ON CONFLICT (entity_type, entity_id) WHERE status IN ('pending', 'retry')
            DO UPDATE SET
                operation = 'delete',
                priority = 1,
                payload = EXCLUDED.payload,
                updated_at = now();

            PERFORM pg_notify('tally_sync', jsonb_build_object(
                'entity_type', 'invoice',
                'entity_id', NEW.id,
                'operation', 'delete'
            )::text);
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


CREATE FUNCTION public.ensure_default_pricing_for_all_items(p_unit_price numeric DEFAULT 91.50, p_labour_rate numeric DEFAULT 45.00, p_tax_percent numeric DEFAULT 18.00) RETURNS TABLE(item_id uuid, item_name text, price_type text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    INSERT INTO item_storage_prices (
        item_id, customer_id, weight_min, weight_max,
        unit_price, unit_price_one_time, unit_price_monthly,
        labour_rate, tax_percent, price_type, effective_from
    )
    SELECT i.id, NULL, 0, 9999, p_unit_price, p_unit_price, p_unit_price,
        p_labour_rate, p_tax_percent, 'monthly', CURRENT_DATE
    FROM items i
    WHERE i.active = true
    AND NOT EXISTS (
        SELECT 1 FROM item_storage_prices isp
        WHERE isp.item_id = i.id AND isp.customer_id IS NULL AND isp.price_type = 'monthly'
    )
    RETURNING item_storage_prices.item_id,
        (SELECT name FROM items WHERE id = item_storage_prices.item_id), 'monthly'::text;

    RETURN QUERY
    INSERT INTO item_storage_prices (
        item_id, customer_id, weight_min, weight_max,
        unit_price, unit_price_one_time, unit_price_monthly,
        labour_rate, tax_percent, price_type, effective_from
    )
    SELECT i.id, NULL, 0, 9999, p_unit_price, p_unit_price, p_unit_price,
        p_labour_rate, p_tax_percent, 'one_time', CURRENT_DATE
    FROM items i
    WHERE i.active = true
    AND NOT EXISTS (
        SELECT 1 FROM item_storage_prices isp
        WHERE isp.item_id = i.id AND isp.customer_id IS NULL AND isp.price_type = 'one_time'
    )
    RETURNING item_storage_prices.item_id,
        (SELECT name FROM items WHERE id = item_storage_prices.item_id), 'one_time'::text;
EXCEPTION
    WHEN OTHERS THEN
        RAISE WARNING 'ensure_default_pricing_for_all_items failed: % - %', SQLSTATE, SQLERRM;
        -- Return empty result set on error
        RETURN;
END;
$$;


CREATE FUNCTION public.find_or_create_item_storage_price(p_item_id uuid, p_customer_id uuid, p_weight numeric, p_price_type text, p_default_unit_price numeric DEFAULT 0, p_default_labour_rate numeric DEFAULT 0, p_default_tax_percent numeric DEFAULT 18, p_default_weight_min numeric DEFAULT 0, p_default_weight_max numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_user_id UUID;
    v_user_phone TEXT;
    v_user_role TEXT;
    v_profile_id UUID;
    v_existing_price RECORD;
    v_new_price_id UUID;
    v_item_name TEXT;
    v_customer_name TEXT;
    v_result jsonb;
    v_weight_max_value INTEGER;
BEGIN
    -- Get current user
    v_user_id := auth.uid();

    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', NULL,
            'message', 'Authentication required'
        );
    END IF;

    -- Get phone from auth.users, then lookup role via phone in user_profiles
    SELECT phone INTO v_user_phone
    FROM auth.users
    WHERE id = v_user_id;

    SELECT id, role INTO v_profile_id, v_user_role
    FROM user_profiles
    WHERE mobile = v_user_phone;

    IF v_user_role IS NULL OR v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', NULL,
            'message', 'Only admin or supervisor can manage pricing'
        );
    END IF;

    -- Validate price_type
    IF lower(p_price_type) NOT IN ('one_time', 'monthly') THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', NULL,
            'message', 'price_type must be ''one_time'' or ''monthly'''
        );
    END IF;

    -- Validate item exists
    SELECT name INTO v_item_name
    FROM items
    WHERE id = p_item_id;

    IF v_item_name IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', NULL,
            'message', 'Item not found'
        );
    END IF;

    -- Validate customer exists
    SELECT name INTO v_customer_name
    FROM customers
    WHERE id = p_customer_id;

    IF v_customer_name IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', NULL,
            'message', 'Customer not found'
        );
    END IF;

    -- Try to find existing pricing
    SELECT
        isp.id,
        isp.item_id,
        isp.customer_id,
        isp.price_type,
        isp.unit_price,
        isp.weight_min,
        isp.weight_max,
        isp.labour_rate,
        isp.tax_percent,
        isp.effective_from,
        isp.effective_to
    INTO v_existing_price
    FROM item_storage_prices isp
    WHERE isp.item_id = p_item_id
      AND isp.customer_id = p_customer_id
      AND isp.price_type = lower(p_price_type)
      AND isp.weight_min <= p_weight
      AND isp.weight_max >= p_weight
      AND isp.effective_from <= CURRENT_DATE
      AND (isp.effective_to IS NULL OR isp.effective_to >= CURRENT_DATE)
    ORDER BY (isp.weight_max - isp.weight_min) ASC  -- most specific range first
    LIMIT 1;

    IF v_existing_price.id IS NOT NULL THEN
        -- Found existing pricing, return it
        RETURN jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'id', v_existing_price.id,
                'item_id', v_existing_price.item_id,
                'item_name', v_item_name,
                'customer_id', v_existing_price.customer_id,
                'customer_name', v_customer_name,
                'price_type', v_existing_price.price_type,
                'unit_price', v_existing_price.unit_price,
                'weight_min', v_existing_price.weight_min,
                'weight_max', v_existing_price.weight_max,
                'labour_rate', v_existing_price.labour_rate,
                'tax_percent', v_existing_price.tax_percent,
                'effective_from', v_existing_price.effective_from,
                'effective_to', v_existing_price.effective_to,
                'was_created', false
            ),
            'message', NULL
        );
    END IF;

    -- No existing pricing found, create new one
    -- Calculate weight_max: use provided default or fall back to p_weight
    v_weight_max_value := COALESCE(p_default_weight_max, p_weight)::INTEGER;

    INSERT INTO item_storage_prices (
        item_id,
        customer_id,
        price_type,
        unit_price,
        unit_price_one_time,
        unit_price_monthly,
        weight_min,
        weight_max,
        labour_rate,
        tax_percent,
        effective_from,
        effective_to,
        created_by
    )
    VALUES (
        p_item_id,
        p_customer_id,
        lower(p_price_type),
        COALESCE(p_default_unit_price, 0),
        CASE WHEN lower(p_price_type) = 'one_time' THEN COALESCE(p_default_unit_price, 0) ELSE 0 END,
        CASE WHEN lower(p_price_type) = 'monthly' THEN COALESCE(p_default_unit_price, 0) ELSE 0 END,
        COALESCE(p_default_weight_min, 0)::INTEGER,
        v_weight_max_value,
        COALESCE(p_default_labour_rate, 0),
        COALESCE(p_default_tax_percent, 18),
        CURRENT_DATE,
        NULL,  -- no expiry
        v_profile_id
    )
    RETURNING id INTO v_new_price_id;

    -- Return newly created pricing
    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'id', v_new_price_id,
            'item_id', p_item_id,
            'item_name', v_item_name,
            'customer_id', p_customer_id,
            'customer_name', v_customer_name,
            'price_type', lower(p_price_type),
            'unit_price', COALESCE(p_default_unit_price, 0),
            'weight_min', COALESCE(p_default_weight_min, 0)::INTEGER,
            'weight_max', v_weight_max_value,
            'labour_rate', COALESCE(p_default_labour_rate, 0),
            'tax_percent', COALESCE(p_default_tax_percent, 18),
            'effective_from', CURRENT_DATE,
            'effective_to', NULL,
            'was_created', true
        ),
        'message', NULL
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', NULL,
            'message', SQLERRM
        );
END;
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;


CREATE TABLE public.item_storage_prices (
    id uuid DEFAULT extensions.uuid_generate_v1() NOT NULL,
    item_id uuid NOT NULL,
    customer_id uuid,
    weight_min integer NOT NULL,
    weight_max integer NOT NULL,
    labour_rate numeric(12,2) NOT NULL,
    tax_percent numeric(5,2) NOT NULL,
    effective_from date DEFAULT CURRENT_DATE NOT NULL,
    effective_to date,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    unit_price_one_time numeric(12,2) NOT NULL,
    unit_price_monthly numeric(12,2) NOT NULL,
    price_type text NOT NULL,
    unit_price numeric(12,2) NOT NULL,
    CONSTRAINT dates_valid CHECK (((effective_to IS NULL) OR (effective_from < effective_to))),
    CONSTRAINT labour_rate_positive CHECK ((labour_rate >= (0)::numeric)),
    CONSTRAINT price_type_valid CHECK ((price_type = ANY (ARRAY['one_time'::text, 'monthly'::text]))),
    CONSTRAINT tax_percent_valid CHECK (((tax_percent >= (0)::numeric) AND (tax_percent <= (100)::numeric))),
    CONSTRAINT unit_price_monthly_positive CHECK (((unit_price_monthly IS NULL) OR (unit_price_monthly >= (0)::numeric))),
    CONSTRAINT unit_price_one_time_positive CHECK (((unit_price_one_time IS NULL) OR (unit_price_one_time >= (0)::numeric))),
    CONSTRAINT unit_price_positive CHECK ((unit_price >= (0)::numeric)),
    CONSTRAINT weight_range_valid CHECK ((weight_min <= weight_max))
);


CREATE FUNCTION public.find_storage_price(p_item_id uuid, p_customer_id uuid, p_weight integer, p_dispatch_date date, p_price_type text DEFAULT 'monthly'::text) RETURNS public.item_storage_prices
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_price_record item_storage_prices;
    v_normalized_price_type text;
BEGIN
    -- Normalize price_type (handle 'MONTHLY' -> 'monthly', 'ONE_TIME' -> 'one_time')
    v_normalized_price_type := LOWER(REPLACE(COALESCE(p_price_type, 'monthly'), '_', '_'));
    IF v_normalized_price_type = 'one-time' THEN
        v_normalized_price_type := 'one_time';
    END IF;

    -- Default to monthly if invalid
    IF v_normalized_price_type NOT IN ('one_time', 'monthly') THEN
        v_normalized_price_type := 'monthly';
    END IF;

    SELECT * INTO v_price_record
    FROM item_storage_prices isp
    WHERE isp.item_id = p_item_id
      AND isp.price_type = v_normalized_price_type
      AND isp.weight_min <= p_weight
      AND p_weight <= isp.weight_max
      AND isp.effective_from <= p_dispatch_date
      AND (isp.effective_to IS NULL OR p_dispatch_date <= isp.effective_to)
      AND (
          -- Customer-specific price
          isp.customer_id = p_customer_id
          OR
          -- Default price (when no customer-specific price exists)
          (isp.customer_id IS NULL AND NOT EXISTS (
              SELECT 1
              FROM item_storage_prices isp2
              WHERE isp2.item_id = p_item_id
                AND isp2.price_type = v_normalized_price_type
                AND isp2.customer_id = p_customer_id
                AND isp2.weight_min <= p_weight
                AND p_weight <= isp2.weight_max
                AND isp2.effective_from <= p_dispatch_date
                AND (isp2.effective_to IS NULL OR p_dispatch_date <= isp2.effective_to)
          ))
      )
    ORDER BY
        (isp.customer_id IS NULL),            -- 1. Customer-specific first (false sorts before true)
        (isp.weight_max - isp.weight_min),    -- 2. More specific weight range first (smaller range = more specific)
        isp.effective_from DESC               -- 3. Most recent effective date first
    LIMIT 1;

    RETURN v_price_record;
END;
$$;


CREATE FUNCTION public.find_storage_price_table(p_item_id uuid, p_weight integer, p_dispatch_date date, p_customer_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, item_id uuid, customer_id uuid, weight_min integer, weight_max integer, unit_price_one_time numeric, unit_price_monthly numeric, labour_rate numeric, tax_percent numeric, effective_from date, effective_to date)
    LANGUAGE plpgsql
    AS $$
  BEGIN
      -- First try customer-specific pricing
      IF p_customer_id IS NOT NULL THEN
          RETURN QUERY
          SELECT
              isp.id,
              isp.item_id,
              isp.customer_id,
              isp.weight_min,
              isp.weight_max,
              isp.unit_price_one_time,
              isp.unit_price_monthly,
              isp.labour_rate,
              isp.tax_percent,
              isp.effective_from,
              isp.effective_to
          FROM item_storage_prices isp
          WHERE isp.item_id = p_item_id
            AND isp.customer_id = p_customer_id
            AND p_weight >= isp.weight_min
            AND p_weight <= isp.weight_max  -- Changed < to <=
            AND isp.effective_from <= p_dispatch_date
            AND (isp.effective_to IS NULL OR isp.effective_to > p_dispatch_date)
          ORDER BY (isp.weight_max - isp.weight_min), isp.effective_from DESC  -- Most specific range first
          LIMIT 1;

          -- If customer-specific pricing found, return it
          IF FOUND THEN
              RETURN;
          END IF;
      END IF;

      -- Fallback to default pricing (customer_id IS NULL)
      RETURN QUERY
      SELECT
          isp.id,
          isp.item_id,
          isp.customer_id,
          isp.weight_min,
          isp.weight_max,
          isp.unit_price_one_time,
          isp.unit_price_monthly,
          isp.labour_rate,
          isp.tax_percent,
          isp.effective_from,
          isp.effective_to
      FROM item_storage_prices isp
      WHERE isp.item_id = p_item_id
        AND isp.customer_id IS NULL
        AND p_weight >= isp.weight_min
        AND p_weight <= isp.weight_max  -- Changed < to <=
        AND isp.effective_from <= p_dispatch_date
        AND (isp.effective_to IS NULL OR isp.effective_to > p_dispatch_date)
      ORDER BY (isp.weight_max - isp.weight_min), isp.effective_from DESC  -- Most specific range first
      LIMIT 1;
  END;
  $$;


CREATE FUNCTION public.fix_orphaned_invoice_flags() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    DECLARE
        v_fixed_count INTEGER := 0;
        v_orphaned_grns JSONB;
    BEGIN
        -- Collect list of orphaned GRNs before fixing
        SELECT jsonb_agg(
            jsonb_build_object(
                'gr_no', gr.gr_no,
                'gr_id', gr.id,
                'customer_name', gr.customer_name,
                'date', gr.date
            )
        )
        INTO v_orphaned_grns
        FROM goodsreceived gr
        LEFT JOIN invoice inv ON gr.id = inv.gr_id
        WHERE gr.invoiced = true
        GROUP BY gr.id, gr.gr_no, gr.customer_name, gr.date, gr.invoiced
        HAVING COUNT(inv.id) = 0;

        -- Fix orphaned GRN invoiced flags
        UPDATE goodsreceived gr
        SET invoiced = false
        WHERE gr.invoiced = true
        AND NOT EXISTS (
            SELECT 1 FROM invoice inv
            WHERE inv.gr_id = gr.id
        );

        -- Get count of fixed records
        GET DIAGNOSTICS v_fixed_count = ROW_COUNT;

        -- Return result
        RETURN jsonb_build_object(
            'success', true,
            'fixed_count', v_fixed_count,
            'orphaned_grns', COALESCE(v_orphaned_grns, '[]'::jsonb),
            'message', format('Fixed %s orphaned invoice flags', v_fixed_count)
        );

    EXCEPTION
        WHEN OTHERS THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'Failed to fix orphaned flags: ' || SQLERRM,
                'sqlstate', SQLSTATE
            );
    END;
$$;


CREATE FUNCTION public.generate_invoice_data_for_grn(p_gr_id uuid, p_duration_mode text DEFAULT 'legacy'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_duration_mode text;
    v_grn_exists boolean;
    v_is_invoiceable boolean;
    v_user_role text;
    v_user_customer_ids uuid[];
    v_current_year text;
    v_fin_year integer;
    v_next_invoice_no text;
    v_header_data jsonb;
    v_recalculation jsonb;
BEGIN
    v_duration_mode := public.validate_invoice_duration_mode(p_duration_mode);

    SELECT role INTO v_user_role FROM user_profiles
    WHERE auth_user_id = auth.uid();

    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') AND auth.uid() IS NOT NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Only administrators and supervisors can generate invoice data'
        );
    END IF;

    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
        FROM user_customers
        WHERE user_id = (SELECT id FROM user_profiles WHERE auth_user_id = auth.uid());
    END IF;

    SELECT
        EXISTS(SELECT 1 FROM goodsreceived WHERE id = p_gr_id),
        EXISTS(
            SELECT 1 FROM goodsreceived
            WHERE id = p_gr_id
            AND invoiced = false
            AND NOT EXISTS(SELECT 1 FROM goodsreceived_trl WHERE gr_id = p_gr_id AND stock > 0)
        )
    INTO v_grn_exists, v_is_invoiceable;

    IF NOT v_grn_exists THEN
        RETURN jsonb_build_object('success', false, 'error', 'GRN not found');
    END IF;

    IF NOT v_is_invoiceable THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'GRN is not ready for invoicing (must be completely dispatched and not already invoiced)'
        );
    END IF;

    IF EXTRACT(MONTH FROM CURRENT_DATE) >= 4 THEN
        v_current_year := EXTRACT(YEAR FROM CURRENT_DATE)::text || '-' ||
                         (EXTRACT(YEAR FROM CURRENT_DATE) + 1)::text;
    ELSE
        v_current_year := (EXTRACT(YEAR FROM CURRENT_DATE) - 1)::text || '-' ||
                         EXTRACT(YEAR FROM CURRENT_DATE)::text;
    END IF;

    v_fin_year := SPLIT_PART(v_current_year, '-', 1)::integer;

    SELECT 'INV-' || v_current_year || '-' ||
           LPAD((COUNT(*) + 1)::text, 4, '0')
    INTO v_next_invoice_no
    FROM invoice
    WHERE inv_fin_year = v_fin_year;

    SELECT jsonb_build_object(
        'invoice_number', v_next_invoice_no,
        'invoice_date', CURRENT_DATE,
        'financial_year', v_current_year,
        'duration_mode', v_duration_mode,
        'grn_id', gr.id,
        'grn_no', gr.gr_no,
        'grn_date', gr.date,
        'grn_registration', gr.registration,
        'grn_note', gr.note,
        'grn_leon', gr.leon,
        'grn_image_url', gr.gr_image_url,
        'grn_gr_image_url', gr.gr_image_url,
        'customer_id', gr.customer_id,
        'customer_name', c.name,
        'customer_address', c.address,
        'customer_city', c.city,
        'customer_state', c.state,
        'customer_pincode', c.pincode,
        'customer_phone', c.mobile,
        'customer_email', c.email,
        'customer_gstin', c.gst,
        'grn_customer_id', gr.customer_id,
        'grn_customer_name', c.name,
        'supervisor_id', gr.supervisor_id,
        'supervisor_name', COALESCE(sp.name, ''),
        'supervisor_phone', CAST(NULL AS text),
        'sender_id', gr.sender_id,
        'sender_name', COALESCE(se.name, ''),
        'sender_phone', CAST(NULL AS text),
        'total_items', (SELECT COUNT(*) FROM goodsreceived_trl grt WHERE grt.gr_id = gr.id),
        'total_original_quantity', (SELECT COALESCE(SUM(grt.qty), 0) FROM goodsreceived_trl grt WHERE grt.gr_id = gr.id),
        'total_dispatched_quantity', (
            SELECT COALESCE(SUM(dt.disp_qty), 0)
            FROM goodsreceived_trl grt
            JOIN dispatch_trl dt ON dt.gr_trl_id = grt.id
            WHERE grt.gr_id = gr.id
        ),
        'grn_created_by', gr.created_by,
        'grn_updated_by', gr.updated_by,
        'grn_created_at', gr.created_at,
        'grn_updated_at', gr.updated_at
    ) INTO v_header_data
    FROM goodsreceived gr
    JOIN customers c ON c.id = gr.customer_id
    LEFT JOIN user_profiles sp ON sp.id = gr.supervisor_id
    LEFT JOIN user_profiles se ON se.id = gr.sender_id
    WHERE gr.id = p_gr_id;

    v_recalculation := public.build_invoice_recalculation_rows(p_gr_id, v_duration_mode, NULL);

    IF NOT COALESCE((v_recalculation->>'success')::boolean, false) THEN
        RETURN v_recalculation;
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'header', v_header_data,
        'rows', v_recalculation->'rows',
        'items', v_recalculation->'items',
        'totals', v_recalculation->'totals',
        'data', jsonb_build_object(
            'header', v_header_data,
            'rows', v_recalculation->'rows',
            'items', v_recalculation->'items',
            'total_rows', COALESCE((v_recalculation->'totals'->>'total_rows')::integer, 0),
            'totals', v_recalculation->'totals'
        ),
        'message', 'Invoice data generated successfully'
    );
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', null,
            'message', 'Error generating invoice data: ' || SQLERRM
        );
END;
$$;


CREATE FUNCTION public.generate_invoice_data_for_grn_with_pricing(p_gr_id uuid, p_duration_mode text DEFAULT 'legacy'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    RETURN public.generate_invoice_data_for_grn(p_gr_id, p_duration_mode);
END;
$$;


CREATE FUNCTION public.generate_order_number() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    next_num INTEGER;
BEGIN
    UPDATE order_number_counter
    SET value = value + 1
    WHERE id = 'order_number'
    RETURNING value INTO next_num;

    IF next_num IS NULL THEN
        INSERT INTO order_number_counter (id, value) VALUES ('order_number', 1);
        next_num := 1;
    END IF;

    RETURN 'ORD' || LPAD(next_num::TEXT, 3, '0');
EXCEPTION
    WHEN OTHERS THEN
        RAISE WARNING 'generate_order_number failed: % - %', SQLSTATE, SQLERRM;
        RETURN NULL;
END;
$$;


CREATE FUNCTION public.generate_secure_otp() RETURNS character varying
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    SELECT LPAD((abs(hashtext(gen_random_uuid()::TEXT)) % 1000000)::TEXT, 6, '0');
$$;


CREATE FUNCTION public.generate_sequential_uuid() RETURNS uuid
    LANGUAGE plpgsql
    AS $$
  BEGIN
      -- This generates a time-ordered UUID similar to your original pattern
      RETURN uuid_generate_v1mc();
  END;
  $$;


CREATE FUNCTION public.generate_time_first_uuid() RETURNS uuid
    LANGUAGE plpgsql
    AS $$
  DECLARE
      time_part text;
      random_bytes bytea;
      result text;
  BEGIN
      -- Get timestamp and add random component for first part variation
      time_part := lpad(to_hex((extract(epoch from clock_timestamp()) * 1000 + (random() * 1000)::int)::bigint), 8, '0');

      -- Generate 8 random bytes (16 hex chars) for the rest
      random_bytes := gen_random_bytes(8);

      -- Format as proper UUID: xxxxxxxx-xxxx-4xxx-bxxx-xxxxxxxxxxxx (32 total hex chars)
      result :=
          substring(time_part from 1 for 8) || '-' ||
          substring(encode(random_bytes, 'hex') from 1 for 4) || '-' ||
          '4' || substring(encode(random_bytes, 'hex') from 5 for 3) || '-' ||
          'b' || substring(encode(random_bytes, 'hex') from 8 for 3) || '-' ||
          substring(encode(random_bytes, 'hex') from 11 for 12);

      RETURN result::uuid;
  END;
  $$;


CREATE FUNCTION public.get_active_sessions(p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_id UUID;
    v_sessions JSONB;
BEGIN
    -- Use provided user_id or current user
    IF p_user_id IS NOT NULL THEN
        v_user_id := p_user_id;
    ELSE
        SELECT id INTO v_user_id FROM user_profiles WHERE auth_user_id = auth.uid();
    END IF;

    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('success', FALSE, 'error', 'User not found');
    END IF;

    -- Get active sessions (last 1 hour)
    SELECT jsonb_agg(jsonb_build_object(
        'session_id', auth_session_id,
        'last_activity', last_activity_at,
        'inactive_duration_seconds', EXTRACT(EPOCH FROM (NOW() - last_activity_at))::INTEGER,
        'ip_address', ip_address,
        'user_agent', user_agent,
        'activity_type', activity_type
    ))
    INTO v_sessions
    FROM (
        SELECT DISTINCT ON (auth_session_id)
            auth_session_id,
            last_activity_at,
            ip_address,
            user_agent,
            activity_type
        FROM user_session_activity
        WHERE user_id = v_user_id
        AND last_activity_at > NOW() - INTERVAL '1 hour'
        ORDER BY auth_session_id, last_activity_at DESC
    ) active_sessions;

    RETURN jsonb_build_object(
        'success', TRUE,
        'user_id', v_user_id,
        'sessions', COALESCE(v_sessions, '[]'::JSONB)
    );
END;
$$;


CREATE FUNCTION public.get_all_customer_activity_summary(p_from_date date, p_to_date date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET jit TO 'off'
    AS $$
DECLARE
    v_user_id uuid;
    v_user_role text;
    v_user_customer_ids uuid[];
    v_result jsonb;
    v_summary jsonb;
    v_customers jsonb;
BEGIN
    -- Get caller's role
    IF auth.uid() IS NOT NULL THEN
        SELECT id, role INTO v_user_id, v_user_role
        FROM user_profiles
        WHERE auth_user_id = auth.uid();
    END IF;

    -- Access control
    IF v_user_role IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Authentication required'
        );
    END IF;

    -- Get user's accessible customers if not staff
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
        FROM users_customers_new
        WHERE user_profile_id = v_user_id;
    END IF;

    WITH customer_stock AS (
        -- Current stock per customer (no date filter - current snapshot)
        SELECT
            gr.customer_id,
            SUM(grt.stock) as current_stock
        FROM goodsreceived gr
        JOIN goodsreceived_trl grt ON grt.gr_id = gr.id
        WHERE gr.deleted_at IS NULL AND grt.stock > 0
        GROUP BY gr.customer_id
    ),
    customer_grns AS (
        -- GRN counts in date range
        SELECT
            customer_id,
            COUNT(*) as total_grns
        FROM goodsreceived
        WHERE deleted_at IS NULL
            AND date::date BETWEEN p_from_date AND p_to_date
        GROUP BY customer_id
    ),
    customer_dispatches AS (
        -- Dispatch counts in date range
        SELECT
            customer_id,
            COUNT(*) as total_dispatches
        FROM dispatch
        WHERE deleted_at IS NULL
            AND disp_date::date BETWEEN p_from_date AND p_to_date
        GROUP BY customer_id
    ),
    customer_invoices AS (
        -- Invoice totals in date range
        SELECT
            customer_id,
            SUM(COALESCE(total, 0) + COALESCE(labour, 0) + COALESCE(tax_amount, 0) - COALESCE(discount, 0)) as total_invoice_amount
        FROM invoice
        WHERE deleted_at IS NULL
            AND inv_date::date BETWEEN p_from_date AND p_to_date
        GROUP BY customer_id
    ),
    last_activity AS (
        -- Most recent activity per customer (within date range)
        SELECT DISTINCT ON (customer_id)
            customer_id,
            activity_date as last_activity_date,
            activity_type as last_activity_type
        FROM (
            SELECT customer_id, date as activity_date, 'grn' as activity_type
            FROM goodsreceived
            WHERE deleted_at IS NULL AND date::date BETWEEN p_from_date AND p_to_date
            UNION ALL
            SELECT customer_id, disp_date as activity_date, 'dispatch' as activity_type
            FROM dispatch
            WHERE deleted_at IS NULL AND disp_date::date BETWEEN p_from_date AND p_to_date
        ) activities
        ORDER BY customer_id, activity_date DESC
    ),
    customer_data AS (
        SELECT
            c.id as customer_id,
            c.name as customer_name,
            c.city as customer_city,
            COALESCE(cs.current_stock, 0) as current_stock,
            COALESCE(cg.total_grns, 0) as total_grns,
            COALESCE(cd.total_dispatches, 0) as total_dispatches,
            COALESCE(ci.total_invoice_amount, 0) as total_invoice_amount,
            la.last_activity_date,
            la.last_activity_type
        FROM customers c
        LEFT JOIN customer_stock cs ON c.id = cs.customer_id
        LEFT JOIN customer_grns cg ON c.id = cg.customer_id
        LEFT JOIN customer_dispatches cd ON c.id = cd.customer_id
        LEFT JOIN customer_invoices ci ON c.id = ci.customer_id
        LEFT JOIN last_activity la ON c.id = la.customer_id
        WHERE c.deleted_at IS NULL
            AND c.active = true
            -- Filter by user's accessible customers if not staff
            AND (v_user_role IN ('admin', 'supervisor', 'staff') OR c.id = ANY(v_user_customer_ids))
            -- Only include customers with some activity or stock
            AND (
                COALESCE(cs.current_stock, 0) > 0
                OR COALESCE(cg.total_grns, 0) > 0
                OR COALESCE(cd.total_dispatches, 0) > 0
                OR COALESCE(ci.total_invoice_amount, 0) > 0
            )
    )
    SELECT
        jsonb_build_object(
            'total_customers', COUNT(*),
            'total_current_stock', COALESCE(SUM(current_stock), 0),
            'total_grns', COALESCE(SUM(total_grns), 0),
            'total_dispatches', COALESCE(SUM(total_dispatches), 0),
            'total_invoice_amount', COALESCE(SUM(total_invoice_amount), 0)
        ),
        COALESCE(jsonb_agg(
            jsonb_build_object(
                'customer_id', customer_id,
                'customer_name', customer_name,
                'customer_city', customer_city,
                'current_stock', current_stock,
                'total_grns', total_grns,
                'total_dispatches', total_dispatches,
                'total_invoice_amount', total_invoice_amount,
                'last_activity_date', last_activity_date,
                'last_activity_type', last_activity_type
            ) ORDER BY current_stock DESC
        ), '[]'::jsonb)
    INTO v_summary, v_customers
    FROM customer_data;

    v_result := jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'summary', v_summary,
            'customers', v_customers
        ),
        'metadata', jsonb_build_object(
            'retrieved_at', NOW(),
            'from_date', p_from_date,
            'to_date', p_to_date
        )
    );

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Failed to retrieve customer activity summary: ' || SQLERRM,
            'error_code', SQLSTATE
        );
END;
$$;


CREATE FUNCTION public.get_all_dispatch_activity(p_from_date date DEFAULT ((CURRENT_DATE - '7 days'::interval))::date, p_to_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result JSONB;
    v_user_id UUID;
    v_user_role TEXT;
    v_user_customer_ids UUID[];
BEGIN
    -- Get caller's user profile and role
    IF auth.uid() IS NOT NULL THEN
        SELECT id, role INTO v_user_id, v_user_role
        FROM user_profiles
        WHERE auth_user_id = auth.uid() AND active = true;
    END IF;

    -- Authentication required
    IF v_user_role IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Authentication required',
            'summary', NULL,
            'dispatches', '[]'::jsonb
        );
    END IF;

    -- Get user's accessible customers if not admin/supervisor
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
        FROM users_customers_new
        WHERE user_profile_id = v_user_id;

        -- If no customers assigned, return empty
        IF v_user_customer_ids IS NULL OR array_length(v_user_customer_ids, 1) IS NULL THEN
            RETURN jsonb_build_object(
                'success', true,
                'summary', jsonb_build_object(
                    'total_dispatches', 0,
                    'total_customers', 0,
                    'total_quantity', 0,
                    'from_date', p_from_date,
                    'to_date', p_to_date
                ),
                'by_customer', '[]'::jsonb,
                'by_date', '[]'::jsonb
            );
        END IF;
    END IF;

    SELECT jsonb_build_object(
        'success', true,
        'summary', (
            SELECT jsonb_build_object(
                'total_dispatches', COUNT(DISTINCT d.id),
                'total_customers', COUNT(DISTINCT d.customer_id),
                'total_quantity', COALESCE(SUM(dt.disp_qty), 0),
                'from_date', p_from_date,
                'to_date', p_to_date
            )
            FROM dispatch d
            JOIN dispatch_trl dt ON dt.disp_id = d.id
            WHERE d.deleted_at IS NULL
              AND d.disp_date >= p_from_date
              AND d.disp_date <= p_to_date
              AND (v_user_role IN ('admin', 'supervisor', 'staff') OR d.customer_id = ANY(v_user_customer_ids))
        ),
        'by_customer', COALESCE((
            SELECT jsonb_agg(customer_data ORDER BY customer_data->>'total_qty' DESC)
            FROM (
                SELECT jsonb_build_object(
                    'customer_id', c.id,
                    'customer_name', c.name,
                    'dispatch_count', COUNT(DISTINCT d.id),
                    'total_qty', SUM(dt.disp_qty),
                    'latest_dispatch', MAX(d.disp_date)::date
                ) AS customer_data
                FROM customers c
                JOIN dispatch d ON d.customer_id = c.id AND d.deleted_at IS NULL
                JOIN dispatch_trl dt ON dt.disp_id = d.id
                WHERE d.disp_date >= p_from_date AND d.disp_date <= p_to_date
                  AND (v_user_role IN ('admin', 'supervisor', 'staff') OR c.id = ANY(v_user_customer_ids))
                GROUP BY c.id, c.name
            ) AS customers_agg
        ), '[]'::jsonb),
        'by_date', COALESCE((
            SELECT jsonb_agg(date_data ORDER BY date_data->>'date' DESC)
            FROM (
                SELECT jsonb_build_object(
                    'date', d.disp_date::date,
                    'dispatch_count', COUNT(DISTINCT d.id),
                    'total_qty', SUM(dt.disp_qty),
                    'customer_count', COUNT(DISTINCT d.customer_id)
                ) AS date_data
                FROM dispatch d
                JOIN dispatch_trl dt ON dt.disp_id = d.id
                WHERE d.deleted_at IS NULL
                  AND d.disp_date >= p_from_date
                  AND d.disp_date <= p_to_date
                  AND (v_user_role IN ('admin', 'supervisor', 'staff') OR d.customer_id = ANY(v_user_customer_ids))
                GROUP BY d.disp_date::date
            ) AS dates_agg
        ), '[]'::jsonb)
    ) INTO v_result;

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Failed to retrieve dispatch activity: ' || SQLERRM,
            'summary', NULL,
            'dispatches', '[]'::jsonb
        );
END;
$$;


CREATE FUNCTION public.get_all_dispatch_items(p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_filters jsonb DEFAULT '{}'::jsonb, p_sort_by text DEFAULT 'date'::text, p_sort_order text DEFAULT 'desc'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
    DECLARE
        v_result jsonb;
        v_total_count integer;
        v_total_dispatch_qty bigint;
        v_total_dispatches integer;
        v_items jsonb;
        v_user_role text;
        v_user_customer_ids uuid[];
        v_sort_column text;
        v_order_direction text;
    BEGIN
        -- Security: Get user role and accessible customers
        SELECT role INTO v_user_role FROM user_profiles
        WHERE auth_user_id = auth.uid();

        -- If user is not admin/supervisor, get their assigned customers
        IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
            v_user_customer_ids := user_accessible_customers();

            -- If no accessible customers, return empty result
            IF v_user_customer_ids IS NULL OR array_length(v_user_customer_ids, 1) IS NULL THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'data', null,
                    'message', 'Access denied: No accessible customers found'
                );
            END IF;
        END IF;

        -- Security: Validate sort column (whitelist approach - snake_case)
        IF p_sort_by NOT IN ('date', 'disp_no', 'customer_name', 'item_name', 'disp_qty') THEN
            RAISE EXCEPTION 'Invalid sort column: %. Allowed values: date, disp_no, customer_name, item_name, disp_qty', p_sort_by;
        END IF;

        -- Security: Validate sort order
        IF UPPER(p_sort_order) NOT IN ('ASC', 'DESC') THEN
            RAISE EXCEPTION 'Invalid sort order: %. Allowed values: ASC, DESC', p_sort_order;
        END IF;

        -- Map validated sort column to actual column reference
        v_sort_column := CASE p_sort_by
            WHEN 'date' THEN 'd.disp_date'
            WHEN 'disp_no' THEN 'd.disp_no'
            WHEN 'customer_name' THEN 'd.customer_name'
            WHEN 'item_name' THEN 'grt.item_name'
            WHEN 'disp_qty' THEN 'dt.disp_qty'
        END;

        v_order_direction := UPPER(p_sort_order);

        -- Validate limit and offset
        IF p_limit < 1 OR p_limit > 1000 THEN
            p_limit := 20;
        END IF;

        IF p_offset < 0 THEN
            p_offset := 0;
        END IF;

        -- Get total count for pagination (snake_case filter keys)
        SELECT COUNT(*) INTO v_total_count
        FROM dispatch_trl dt
        JOIN dispatch d ON dt.disp_id = d.id
        JOIN goodsreceived_trl grt ON dt.gr_trl_id = grt.id
        WHERE (v_user_role IN ('admin', 'supervisor', 'staff') OR d.customer_id = ANY(v_user_customer_ids))
        AND (p_date_from IS NULL OR p_date_to IS NULL OR d.disp_date BETWEEN p_date_from AND p_date_to)
        AND (NOT p_filters ? 'item_name' OR p_filters->>'item_name' = '' OR grt.item_name ILIKE '%' || (p_filters->>'item_name') || '%')
        AND (NOT p_filters ? 'disp_no' OR p_filters->>'disp_no' = '' OR d.disp_no ILIKE '%' || (p_filters->>'disp_no') || '%')
        AND (NOT p_filters ? 'customer_name' OR p_filters->>'customer_name' = '' OR d.customer_name ILIKE '%' || (p_filters->>'customer_name') || '%')
        AND (NOT p_filters ? 'package_mark' OR p_filters->>'package_mark' = '' OR grt.package_mark ILIKE '%' || (p_filters->>'package_mark') || '%')
        AND (NOT p_filters ? 'rack' OR p_filters->>'rack' = '' OR grt.rack ILIKE '%' || (p_filters->>'rack') || '%');

        -- Get aggregations
        SELECT
            COALESCE(SUM(dt.disp_qty), 0),
            COUNT(DISTINCT d.id)
        INTO v_total_dispatch_qty, v_total_dispatches
        FROM dispatch_trl dt
        JOIN dispatch d ON dt.disp_id = d.id
        JOIN goodsreceived_trl grt ON dt.gr_trl_id = grt.id
        WHERE (v_user_role IN ('admin', 'supervisor', 'staff') OR d.customer_id = ANY(v_user_customer_ids))
        AND (p_date_from IS NULL OR p_date_to IS NULL OR d.disp_date BETWEEN p_date_from AND p_date_to)
        AND (NOT p_filters ? 'item_name' OR p_filters->>'item_name' = '' OR grt.item_name ILIKE '%' || (p_filters->>'item_name') || '%')
        AND (NOT p_filters ? 'disp_no' OR p_filters->>'disp_no' = '' OR d.disp_no ILIKE '%' || (p_filters->>'disp_no') || '%')
        AND (NOT p_filters ? 'customer_name' OR p_filters->>'customer_name' = '' OR d.customer_name ILIKE '%' || (p_filters->>'customer_name') || '%')
        AND (NOT p_filters ? 'package_mark' OR p_filters->>'package_mark' = '' OR grt.package_mark ILIKE '%' || (p_filters->>'package_mark') || '%')
        AND (NOT p_filters ? 'rack' OR p_filters->>'rack' = '' OR grt.rack ILIKE '%' || (p_filters->>'rack') || '%');

        -- Get paginated items with dynamic sort (snake_case response keys)
        EXECUTE format('
            SELECT jsonb_agg(
                jsonb_build_object(
                    ''id'', dt.id,
                    ''dispatch_id'', d.id,
                    ''disp_no'', d.disp_no,
                    ''disp_date'', d.disp_date,
                    ''customer_name'', d.customer_name,
                    ''customer_id'', d.customer_id,
                    ''supervisor_name'', d.supervisor_name,
                    ''supervisor_id'', d.supervisor_id,
                    ''registration'', d.registration,
                    ''note'', d.note,
                    ''disp_image_url'', d.disp_image_url,
                    ''source_order_id'', d.source_order_id,
                    ''source_order_no'', d.source_order_no,
                    ''disp_qty'', dt.disp_qty,
                    ''grn_id'', grt.gr_id,
                    ''grn_item_id'', grt.id,
                    ''item_name'', grt.item_name,
                    ''item_id'', grt.item_id,
                    ''original_qty'', grt.qty,
                    ''current_stock'', grt.stock,
                    ''weight'', grt.weight,
                    ''rack'', grt.rack,
                    ''package_mark'', grt.package_mark,
                    ''packaging'', grt.packaging,
                    ''trl_img_url'', grt.trl_img_url,
                    ''pricing_mode'', gr.pricing_mode,
                    ''grn_no'', gr.gr_no,
                    ''grn_date'', gr.date,
                    ''created_at'', d.created_at,
                    ''updated_at'', d.updated_at
                ) ORDER BY %s %s
            )
            FROM dispatch_trl dt
            JOIN dispatch d ON dt.disp_id = d.id
            JOIN goodsreceived_trl grt ON dt.gr_trl_id = grt.id
            JOIN goodsreceived gr ON grt.gr_id = gr.id
            WHERE ($1 IN (''admin'', ''supervisor'') OR d.customer_id = ANY($2))
            AND ($3 IS NULL OR $4 IS NULL OR d.disp_date BETWEEN $3 AND $4)
            AND (NOT $5 ? ''item_name'' OR $5->>''item_name'' = '''' OR grt.item_name ILIKE ''%%'' || ($5->>''item_name'') || ''%%'')
            AND (NOT $5 ? ''disp_no'' OR $5->>''disp_no'' = '''' OR d.disp_no ILIKE ''%%'' || ($5->>''disp_no'') || ''%%'')
            AND (NOT $5 ? ''customer_name'' OR $5->>''customer_name'' = '''' OR d.customer_name ILIKE ''%%'' || ($5->>''customer_name'') || ''%%'')
            AND (NOT $5 ? ''package_mark'' OR $5->>''package_mark'' = '''' OR grt.package_mark ILIKE ''%%'' || ($5->>''package_mark'') || ''%%'')
            AND (NOT $5 ? ''rack'' OR $5->>''rack'' = '''' OR grt.rack ILIKE ''%%'' || ($5->>''rack'') || ''%%'')
            LIMIT $6 OFFSET $7',
            v_sort_column, v_order_direction
        )
        INTO v_items
        USING v_user_role, v_user_customer_ids, p_date_from, p_date_to, p_filters, p_limit, p_offset;

        -- Build result (snake_case aggregation keys)
        v_result := jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'items', COALESCE(v_items, '[]'::jsonb),
                'pagination', jsonb_build_object(
                    'total', v_total_count,
                    'limit', p_limit,
                    'offset', p_offset,
                    'has_more', (p_offset + p_limit) < v_total_count
                ),
                'aggregations', jsonb_build_object(
                    'total_dispatch_qty', v_total_dispatch_qty,
                    'total_dispatches', v_total_dispatches
                ),
                'applied_filters', p_filters,
                'sort', jsonb_build_object(
                    'column', p_sort_by,
                    'order', p_sort_order
                )
            ),
            'message', null
        );

        RETURN v_result;
    END;
$_$;


CREATE FUNCTION public.get_all_grn_activity(p_from_date date DEFAULT ((CURRENT_DATE - '7 days'::interval))::date, p_to_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result JSONB;
    v_user_id UUID;
    v_user_role TEXT;
    v_user_customer_ids UUID[];
BEGIN
    -- Get caller's user profile and role
    IF auth.uid() IS NOT NULL THEN
        SELECT id, role INTO v_user_id, v_user_role
        FROM user_profiles
        WHERE auth_user_id = auth.uid() AND active = true;
    END IF;

    -- Authentication required
    IF v_user_role IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Authentication required',
            'summary', NULL,
            'grns', '[]'::jsonb
        );
    END IF;

    -- Get user's accessible customers if not admin/supervisor
    IF v_user_role NOT IN ('admin', 'supervisor', 'service_role') THEN
        SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
        FROM users_customers_new
        WHERE user_profile_id = v_user_id;

        -- If no customers assigned, return empty
        IF v_user_customer_ids IS NULL OR array_length(v_user_customer_ids, 1) IS NULL THEN
            RETURN jsonb_build_object(
                'success', true,
                'summary', jsonb_build_object(
                    'total_grns', 0,
                    'total_customers', 0,
                    'total_quantity', 0,
                    'total_weight', 0,
                    'from_date', p_from_date,
                    'to_date', p_to_date
                ),
                'by_customer', '[]'::jsonb,
                'by_date', '[]'::jsonb
            );
        END IF;
    END IF;

    SELECT jsonb_build_object(
        'success', true,
        'summary', (
            SELECT jsonb_build_object(
                'total_grns', COUNT(DISTINCT g.id),
                'total_customers', COUNT(DISTINCT g.customer_id),
                'total_quantity', COALESCE(SUM(gt.qty), 0),
                'total_weight', COALESCE(SUM(gt.weight::numeric * gt.qty), 0),
                'from_date', p_from_date,
                'to_date', p_to_date
            )
            FROM goodsreceived g
            JOIN goodsreceived_trl gt ON gt.gr_id = g.id
            WHERE g.deleted_at IS NULL
              AND g.date >= p_from_date
              AND g.date <= p_to_date
              AND (v_user_role IN ('admin', 'supervisor', 'service_role') OR g.customer_id = ANY(v_user_customer_ids))
        ),
        'by_customer', COALESCE((
            SELECT jsonb_agg(customer_data ORDER BY customer_data->>'total_qty' DESC)
            FROM (
                SELECT jsonb_build_object(
                    'customer_id', c.id,
                    'customer_name', c.name,
                    'grn_count', COUNT(DISTINCT g.id),
                    'total_qty', SUM(gt.qty),
                    'total_weight', SUM(gt.weight::numeric * gt.qty),
                    'latest_grn', MAX(g.date)::date
                ) AS customer_data
                FROM customers c
                JOIN goodsreceived g ON g.customer_id = c.id AND g.deleted_at IS NULL
                JOIN goodsreceived_trl gt ON gt.gr_id = g.id
                WHERE g.date >= p_from_date AND g.date <= p_to_date
                  AND (v_user_role IN ('admin', 'supervisor', 'service_role') OR c.id = ANY(v_user_customer_ids))
                GROUP BY c.id, c.name
            ) AS customers_agg
        ), '[]'::jsonb),
        'by_date', COALESCE((
            SELECT jsonb_agg(date_data ORDER BY date_data->>'date' DESC)
            FROM (
                SELECT jsonb_build_object(
                    'date', g.date::date,
                    'grn_count', COUNT(DISTINCT g.id),
                    'total_qty', SUM(gt.qty),
                    'customer_count', COUNT(DISTINCT g.customer_id)
                ) AS date_data
                FROM goodsreceived g
                JOIN goodsreceived_trl gt ON gt.gr_id = g.id
                WHERE g.deleted_at IS NULL
                  AND g.date >= p_from_date
                  AND g.date <= p_to_date
                  AND (v_user_role IN ('admin', 'supervisor', 'service_role') OR g.customer_id = ANY(v_user_customer_ids))
                GROUP BY g.date::date
            ) AS dates_agg
        ), '[]'::jsonb)
    ) INTO v_result;

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Failed to retrieve GRN activity: ' || SQLERRM,
            'summary', NULL,
            'grns', '[]'::jsonb
        );
END;
$$;


CREATE FUNCTION public.get_all_grn_items(p_catalog_id uuid DEFAULT NULL::uuid, p_grn_id uuid DEFAULT NULL::uuid, p_in_stock_only boolean DEFAULT NULL::boolean, p_search_query text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_id UUID;
    v_accessible_customers UUID[];
    v_result JSONB;
    v_total_count INTEGER;
BEGIN
    -- Get authenticated user
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Authentication required';
    END IF;

    -- Get accessible customers based on role
    IF is_admin_or_supervisor() THEN
        SELECT ARRAY(SELECT id FROM customers) INTO v_accessible_customers;
    ELSE
        SELECT user_accessible_customers() INTO v_accessible_customers;
    END IF;

    -- Get total count from MV (FAST - no joins!)
    SELECT COUNT(*) INTO v_total_count
    FROM mv_grn_list m
    WHERE m.customer_id = ANY(v_accessible_customers)
      AND (p_grn_id IS NULL OR m.grn_id = p_grn_id)
      AND (p_in_stock_only IS NULL OR
           (p_in_stock_only = true AND m.stock > 0) OR
           (p_in_stock_only = false))
      AND (p_search_query IS NULL OR
           m.item_name ILIKE '%' || p_search_query || '%' OR
           m.item_name_detail ILIKE '%' || p_search_query || '%' OR
           m.package_mark ILIKE '%' || p_search_query || '%' OR
           m.gr_no ILIKE '%' || p_search_query || '%');

    -- Build result from MV (FAST - pre-denormalized!)
    SELECT jsonb_agg(
        jsonb_build_object(
            'id', m.grn_item_id,
            'grn_id', m.grn_id,
            'item_id', m.item_id,
            'stock', m.stock,
            'package_mark', m.package_mark,
            'packaging', m.packaging,
            'rack', m.rack,
            'weight', m.weight,
            'qty', m.qty,
            'image_url', m.image_url,
            'item_name', m.item_name,
            'grns_id', m.grn_id,
            'gr_no', m.gr_no,
            'grn_date', m.grn_date,
            'customer_id', m.customer_id,
            'customer_name', m.customer_name,
            'registration', m.registration,
            'created_at', m.created_at,
            'updated_at', m.updated_at,
            'customer', jsonb_build_object(
                'id', m.customer_id,
                'name', m.customer_name_detail,
                'city', m.customer_city,
                'mobile', m.customer_mobile,
                'email', m.customer_email
            ),
            'item', jsonb_build_object(
                'id', m.item_id,
                'name', m.item_name_detail,
                'description', m.item_description,
                'active', m.item_active
            )
        )
    ) INTO v_result
    FROM (
        SELECT *
        FROM mv_grn_list m
        WHERE m.customer_id = ANY(v_accessible_customers)
          AND (p_grn_id IS NULL OR m.grn_id = p_grn_id)
          AND (p_in_stock_only IS NULL OR
               (p_in_stock_only = true AND m.stock > 0) OR
               (p_in_stock_only = false))
          AND (p_search_query IS NULL OR
               m.item_name ILIKE '%' || p_search_query || '%' OR
               m.item_name_detail ILIKE '%' || p_search_query || '%' OR
               m.package_mark ILIKE '%' || p_search_query || '%' OR
               m.gr_no ILIKE '%' || p_search_query || '%')
        ORDER BY m.created_at DESC
        LIMIT p_limit OFFSET p_offset
    ) m;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'items', COALESCE(v_result, '[]'::jsonb),
            'total_count', v_total_count,
            'has_more', v_total_count > (p_offset + p_limit)
        )
    );
END;
$$;


CREATE FUNCTION public.get_all_grn_items(p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_filters jsonb DEFAULT '{}'::jsonb, p_sort_by text DEFAULT 'date'::text, p_sort_order text DEFAULT 'desc'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result jsonb;
    v_user_role text;
    v_user_customer_ids uuid[];
    v_sort_column text;
    v_order_direction text;
    v_filter_customer_ids uuid[];
    v_filter_item_ids uuid[];
    v_filter_grn_ids uuid[];
    v_stock_status text;
    v_weight_min integer;
    v_weight_max integer;
    v_package_mark text;
    v_grn_no_from text;
    v_grn_no_to text;
    v_where_conditions text[];
    v_sql text;
BEGIN
    -- Security: Get user role and accessible customers
    SELECT role INTO v_user_role FROM user_profiles
    WHERE auth_user_id = auth.uid();

    -- If user is not admin/supervisor, get their assigned customers
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        v_user_customer_ids := user_accessible_customers();

        IF v_user_customer_ids IS NULL OR array_length(v_user_customer_ids, 1) IS NULL THEN
            RETURN jsonb_build_object(
                'success', false,
                'data', null,
                'message', 'Access denied: No accessible customers found'
            );
        END IF;
    END IF;

    -- Extract filters (snake_case only)
    IF p_filters ? 'customer_ids' AND jsonb_array_length(p_filters->'customer_ids') > 0 THEN
        SELECT array_agg(elem::text::uuid)
        INTO v_filter_customer_ids
        FROM jsonb_array_elements_text(p_filters->'customer_ids') elem;
    END IF;

    IF p_filters ? 'item_ids' AND jsonb_array_length(p_filters->'item_ids') > 0 THEN
        SELECT array_agg(elem::text::uuid)
        INTO v_filter_item_ids
        FROM jsonb_array_elements_text(p_filters->'item_ids') elem;
    END IF;

    IF p_filters ? 'grn_ids' AND jsonb_array_length(p_filters->'grn_ids') > 0 THEN
        SELECT array_agg(elem::text::uuid)
        INTO v_filter_grn_ids
        FROM jsonb_array_elements_text(p_filters->'grn_ids') elem;
    END IF;

    -- Extract stock_status filter
    IF p_filters ? 'stock_status' THEN
        v_stock_status := p_filters->>'stock_status';
    END IF;

    -- Extract weight filters (snake_case)
    IF p_filters ? 'weight_min' THEN
        v_weight_min := (p_filters->>'weight_min')::integer;
    END IF;

    IF p_filters ? 'weight_max' THEN
        v_weight_max := (p_filters->>'weight_max')::integer;
    END IF;

    -- Extract package mark filter (snake_case)
    IF p_filters ? 'package_mark' THEN
        v_package_mark := TRIM(p_filters->>'package_mark');
    END IF;

    -- Extract GRN number range filters (snake_case)
    IF p_filters ? 'gr_no_from' THEN
        v_grn_no_from := TRIM(p_filters->>'gr_no_from');
    END IF;

    IF p_filters ? 'gr_no_to' THEN
        v_grn_no_to := TRIM(p_filters->>'gr_no_to');
    END IF;

    -- Validate and set sort parameters
    v_sort_column := CASE
        WHEN p_sort_by = 'date' THEN 'gr.date'
        WHEN p_sort_by = 'gr_no' THEN '(CASE WHEN SUBSTRING(gr.gr_no FROM 1 FOR 1) >= ''X'' THEN ASCII(SUBSTRING(gr.gr_no FROM 1 FOR 1)) - ASCII(''X'') ELSE ASCII(SUBSTRING(gr.gr_no FROM 1 FOR 1)) - ASCII(''A'') + 3 END * 10000 + COALESCE(CAST(NULLIF(SUBSTRING(gr.gr_no FROM 2), '''') AS INTEGER), 0))'
        WHEN p_sort_by = 'customer_name' THEN 'gr.customer_name'
        WHEN p_sort_by = 'item_name' THEN 'grt.item_name'
        WHEN p_sort_by = 'qty' THEN 'grt.qty'
        WHEN p_sort_by = 'stock' THEN 'grt.stock'
        WHEN p_sort_by = 'weight' THEN 'grt.weight'
        WHEN p_sort_by = 'package_mark' THEN 'grt.package_mark'
        ELSE 'gr.date'
    END;

    v_order_direction := CASE
        WHEN UPPER(p_sort_order) = 'ASC' THEN 'ASC'
        ELSE 'DESC'
    END;

    -- Build WHERE conditions
    v_where_conditions := ARRAY['1=1'];

    -- Date filters
    IF p_date_from IS NOT NULL THEN
        v_where_conditions := array_append(v_where_conditions,
            format('gr.date >= %L', p_date_from));
    END IF;

    IF p_date_to IS NOT NULL THEN
        v_where_conditions := array_append(v_where_conditions,
            format('gr.date <= %L', p_date_to));
    END IF;

    -- Role-based customer access
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        v_where_conditions := array_append(v_where_conditions,
            format('gr.customer_id = ANY(%L::uuid[])', v_user_customer_ids));
    END IF;

    -- Customer filter
    IF v_filter_customer_ids IS NOT NULL THEN
        v_where_conditions := array_append(v_where_conditions,
            format('gr.customer_id = ANY(%L::uuid[])', v_filter_customer_ids));
    END IF;

    -- Item filter
    IF v_filter_item_ids IS NOT NULL THEN
        v_where_conditions := array_append(v_where_conditions,
            format('grt.item_id = ANY(%L::uuid[])', v_filter_item_ids));
    END IF;

    -- GRN filter
    IF v_filter_grn_ids IS NOT NULL THEN
        v_where_conditions := array_append(v_where_conditions,
            format('gr.id = ANY(%L::uuid[])', v_filter_grn_ids));
    END IF;

    -- Stock status filter
    IF v_stock_status = 'out_of_stock' THEN
        v_where_conditions := array_append(v_where_conditions, 'grt.stock = 0');
    ELSIF v_stock_status = 'in_stock' THEN
        v_where_conditions := array_append(v_where_conditions, 'grt.stock > 0');
    END IF;

    -- Weight filters
    IF v_weight_min IS NOT NULL AND v_weight_max IS NOT NULL THEN
        v_where_conditions := array_append(v_where_conditions,
            format('grt.weight BETWEEN %s AND %s', v_weight_min, v_weight_max));
    ELSIF v_weight_min IS NOT NULL THEN
        v_where_conditions := array_append(v_where_conditions,
            format('grt.weight >= %s', v_weight_min));
    ELSIF v_weight_max IS NOT NULL THEN
        v_where_conditions := array_append(v_where_conditions,
            format('grt.weight <= %s', v_weight_max));
    END IF;

    -- Package mark filter
    IF v_package_mark IS NOT NULL AND LENGTH(v_package_mark) > 0 THEN
        v_where_conditions := array_append(v_where_conditions,
            format('LOWER(COALESCE(grt.package_mark, '''')) LIKE LOWER(%L)', '%' || v_package_mark || '%'));
    END IF;

    -- GRN number range filters
    IF v_grn_no_from IS NOT NULL AND LENGTH(v_grn_no_from) > 0 AND
       v_grn_no_to IS NOT NULL AND LENGTH(v_grn_no_to) > 0 THEN
        v_where_conditions := array_append(v_where_conditions,
            format('gr.gr_no BETWEEN %L AND %L', v_grn_no_from, v_grn_no_to));
    ELSIF v_grn_no_from IS NOT NULL AND LENGTH(v_grn_no_from) > 0 THEN
        v_where_conditions := array_append(v_where_conditions,
            format('gr.gr_no >= %L', v_grn_no_from));
    ELSIF v_grn_no_to IS NOT NULL AND LENGTH(v_grn_no_to) > 0 THEN
        v_where_conditions := array_append(v_where_conditions,
            format('gr.gr_no <= %L', v_grn_no_to));
    END IF;

    -- Build and execute main query
    v_sql := format('
        WITH filtered_grn_items AS (
            SELECT
                gr.id,
                gr.gr_no,
                gr.date,
                gr.customer_name,
                gr.supervisor_name,
                gr.registration,
                gr.out_of_stock,
                gr.invoiced,
                gr.note,
                grt.id as grn_item_id,
                grt.item_name,
                grt.packaging,
                grt.qty,
                grt.stock,
                grt.weight,
                grt.rack,
                grt.package_mark,
                grt.trl_img_url,
                ROW_NUMBER() OVER (ORDER BY %s %s) as row_num
            FROM goodsreceived gr
            JOIN goodsreceived_trl grt ON gr.id = grt.gr_id
            WHERE %s
        ),
        paginated_items AS (
            SELECT *
            FROM filtered_grn_items
            WHERE row_num BETWEEN %s AND %s
        ),
        aggregates AS (
            SELECT
                COUNT(*) as total_count,
                COALESCE(SUM(qty), 0) as total_qty,
                COALESCE(SUM(stock), 0) as total_stock,
                COALESCE(SUM(weight), 0) as total_weight
            FROM filtered_grn_items
        )
        SELECT jsonb_build_object(
            ''success'', true,
            ''data'', COALESCE(
                (SELECT jsonb_agg(
                    jsonb_build_object(
                        ''id'', id,
                        ''gr_no'', gr_no,
                        ''date'', date,
                        ''customer_name'', customer_name,
                        ''supervisor_name'', supervisor_name,
                        ''registration'', registration,
                        ''out_of_stock'', out_of_stock,
                        ''invoiced'', invoiced,
                        ''note'', note,
                        ''grn_item_id'', grn_item_id,
                        ''item_name'', item_name,
                        ''packaging'', packaging,
                        ''qty'', qty,
                        ''stock'', stock,
                        ''weight'', weight,
                        ''rack'', rack,
                        ''package_mark'', package_mark,
                        ''trl_img_url'', trl_img_url
                    )
                ) FROM paginated_items),
                ''[]''::jsonb
            ),
            ''pagination'', jsonb_build_object(
                ''total_count'', (SELECT total_count FROM aggregates),
                ''limit'', %s,
                ''offset'', %s
            ),
            ''aggregates'', jsonb_build_object(
                ''total_qty'', (SELECT total_qty FROM aggregates),
                ''total_stock'', (SELECT total_stock FROM aggregates),
                ''total_weight'', (SELECT total_weight FROM aggregates)
            )
        ) as result
    ',
    v_sort_column,
    v_order_direction,
    array_to_string(v_where_conditions, ' AND '),
    p_offset + 1,
    p_offset + p_limit,
    p_limit,
    p_offset
    );

    -- Execute the query
    EXECUTE v_sql INTO v_result;

    RETURN v_result;
END;
$$;


CREATE FUNCTION public.get_all_stock_summary() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result JSONB;
    v_user_id UUID;
    v_user_role TEXT;
    v_user_customer_ids UUID[];
BEGIN
    -- Get caller's user profile and role
    IF auth.uid() IS NOT NULL THEN
        SELECT id, role INTO v_user_id, v_user_role
        FROM user_profiles
        WHERE auth_user_id = auth.uid() AND active = true;
    END IF;

    -- Authentication required
    IF v_user_role IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Authentication required',
            'summary', NULL,
            'customers', '[]'::jsonb
        );
    END IF;

    -- Get user's accessible customers if not admin/supervisor
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
        FROM users_customers_new
        WHERE user_profile_id = v_user_id;

        -- If no customers assigned, return empty
        IF v_user_customer_ids IS NULL OR array_length(v_user_customer_ids, 1) IS NULL THEN
            RETURN jsonb_build_object(
                'success', true,
                'summary', jsonb_build_object(
                    'total_customers_with_stock', 0,
                    'total_items', 0,
                    'total_quantity', 0,
                    'total_weight_kg', 0,
                    'oldest_stock_date', NULL,
                    'grn_count', 0
                ),
                'customers', '[]'::jsonb
            );
        END IF;
    END IF;

    SELECT jsonb_build_object(
        'success', true,
        'summary', (
            SELECT jsonb_build_object(
                'total_customers_with_stock', COUNT(DISTINCT g.customer_id),
                'total_items', COUNT(DISTINCT gt.item_id),
                'total_quantity', COALESCE(SUM(gt.stock), 0),
                'total_weight_kg', COALESCE(SUM(gt.weight::numeric * gt.stock), 0),
                'oldest_stock_date', MIN(g.date)::date,
                'grn_count', COUNT(DISTINCT g.id)
            )
            FROM goodsreceived g
            JOIN goodsreceived_trl gt ON gt.gr_id = g.id
            WHERE g.deleted_at IS NULL
                AND gt.stock > 0
                AND (v_user_role IN ('admin', 'supervisor', 'staff') OR g.customer_id = ANY(v_user_customer_ids))
        ),
        'customers', COALESCE((
            SELECT jsonb_agg(customer_data ORDER BY customer_data->>'total_stock' DESC)
            FROM (
                SELECT jsonb_build_object(
                    'customer_id', c.id,
                    'customer_name', c.name,
                    'total_stock', SUM(gt.stock),
                    'total_weight', SUM(gt.weight::numeric * gt.stock),
                    'item_count', COUNT(DISTINCT gt.item_id),
                    'grn_count', COUNT(DISTINCT g.id),
                    'oldest_date', MIN(g.date)::date,
                    'latest_date', MAX(g.date)::date
                ) AS customer_data
                FROM customers c
                JOIN goodsreceived g ON g.customer_id = c.id AND g.deleted_at IS NULL
                JOIN goodsreceived_trl gt ON gt.gr_id = g.id
                WHERE c.active = true
                    AND gt.stock > 0
                    AND (v_user_role IN ('admin', 'supervisor', 'staff') OR c.id = ANY(v_user_customer_ids))
                GROUP BY c.id, c.name
            ) AS customers_agg
        ), '[]'::jsonb)
    ) INTO v_result;

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Failed to retrieve stock summary: ' || SQLERRM,
            'summary', NULL,
            'customers', '[]'::jsonb
        );
END;
$$;


CREATE FUNCTION public.get_auto_invoice_error_stats(p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_total_errors INTEGER;
      v_resolved_errors INTEGER;
      v_pending_errors INTEGER;
      v_error_by_type JSONB;
      v_error_by_customer JSONB;
      v_retry_stats JSONB;
      v_result JSONB;
  BEGIN
      -- Set default date range if not provided
      p_date_from := COALESCE(p_date_from, CURRENT_DATE - INTERVAL '30 days');
      p_date_to := COALESCE(p_date_to, CURRENT_DATE);

      -- Total errors
      SELECT COUNT(*) INTO v_total_errors
      FROM auto_invoice_errors
      WHERE created_at::DATE BETWEEN p_date_from AND p_date_to;

      -- Resolved errors
      SELECT COUNT(*) INTO v_resolved_errors
      FROM auto_invoice_errors
      WHERE created_at::DATE BETWEEN p_date_from AND p_date_to
      AND resolved_at IS NOT NULL;

      -- Pending errors
      v_pending_errors := v_total_errors - v_resolved_errors;

      -- Error by type
      SELECT jsonb_object_agg(error_code, error_count) INTO v_error_by_type
      FROM (
          SELECT error_code, COUNT(*) as error_count
          FROM auto_invoice_errors
          WHERE created_at::DATE BETWEEN p_date_from AND p_date_to
          GROUP BY error_code
      ) error_types;

      -- Error by customer
      SELECT jsonb_agg(customer_errors) INTO v_error_by_customer
      FROM (
          SELECT jsonb_build_object(
              'customer_id', customer_id,
              'customer_name', customer_name,
              'error_count', COUNT(*)
          ) as customer_errors
          FROM auto_invoice_errors
          WHERE created_at::DATE BETWEEN p_date_from AND p_date_to
          GROUP BY customer_id, customer_name
          ORDER BY COUNT(*) DESC
          LIMIT 10
      ) top_customers;

      -- Retry statistics
      SELECT jsonb_build_object(
          'avg_retry_count', ROUND(AVG(retry_count), 2),
          'max_retry_count', MAX(retry_count),
          'success_after_retry', COUNT(*) FILTER (WHERE retry_count > 0 AND resolved_at IS NOT NULL)
      ) INTO v_retry_stats
      FROM auto_invoice_errors
      WHERE created_at::DATE BETWEEN p_date_from AND p_date_to;

      -- Build result
      v_result := jsonb_build_object(
          'total_errors', v_total_errors,
          'resolved_errors', v_resolved_errors,
          'pending_errors', v_pending_errors,
          'error_by_type', COALESCE(v_error_by_type, '{}'::jsonb),
          'error_by_customer', COALESCE(v_error_by_customer, '[]'::jsonb),
          'retry_statistics', v_retry_stats,
          'date_range', jsonb_build_object(
              'from', p_date_from,
              'to', p_date_to
          )
      );

      RETURN v_result;
  END;
  $$;


CREATE FUNCTION public.get_available_stock(p_gr_trl_id uuid) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
      SELECT stock
      FROM goodsreceived_trl
      WHERE id = p_gr_trl_id;
  $$;


CREATE FUNCTION public.get_cart_dispatches(p_cart_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    WITH dispatch_summary AS (
        SELECT
            d.id,
            d.disp_no,
            d.disp_date,
            d.supervisor_name,
            d.created_at,
            COUNT(dt.id) as item_count,
            COALESCE(SUM(dt.disp_qty), 0) as total_quantity
        FROM dispatch d
        LEFT JOIN dispatch_trl dt ON dt.disp_id = d.id
        WHERE d.source_order_id = p_cart_id
        GROUP BY d.id, d.disp_no, d.disp_date, d.supervisor_name, d.created_at
    )
    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'dispatch_id', ds.id,
                'dispatch_no', ds.disp_no,
                'dispatch_date', ds.disp_date,
                'supervisor_name', ds.supervisor_name,
                'item_count', ds.item_count::INTEGER,
                'total_quantity', ds.total_quantity::INTEGER,
                'created_at', ds.created_at
            ) ORDER BY ds.created_at DESC
        ),
        '[]'::jsonb
    ) INTO v_result
    FROM dispatch_summary ds;

    RETURN utils.success_response(v_result);
END;
$$;


CREATE FUNCTION public.get_contra_for_edit(p_voucher_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_voucher public.tally_contra_vouchers;
BEGIN
    SELECT * INTO v_voucher FROM public.tally_contra_vouchers WHERE id = p_voucher_id;
    IF v_voucher.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Contra voucher not found');
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'voucher_id',       v_voucher.id,
            'voucher_number',   v_voucher.voucher_number,
            'voucher_date',     v_voucher.voucher_date,
            'from_ledger',      v_voucher.from_ledger,
            'to_ledger',        v_voucher.to_ledger,
            'amount',           v_voucher.amount,
            'particulars',      v_voucher.particulars,
            'status',           v_voucher.status
        )
    );
END;
$$;


CREATE FUNCTION public.get_current_user_profile() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_profile jsonb;
BEGIN
    SELECT jsonb_build_object(
        'id', p.id,
        'name', p.name,
        'display_name', p.display_name,
        'email', p.email,
        'mobile', p.mobile,
        'role', p.role::text,
        'auth_user_id', p.auth_user_id,
        'active', p.active,
        'mobile_verified', p.mobile_verified,
        'created_at', p.created_at,
        'updated_at', p.updated_at
    )
    INTO v_profile
    FROM user_profiles p
    WHERE p.auth_user_id = auth.uid() AND p.active = true;

    IF v_profile IS NULL THEN
        RETURN utils.not_authenticated_response();
    END IF;

    RETURN utils.success_response(v_profile, NULL);
END;
$$;


CREATE FUNCTION public.get_current_user_profile_id() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_id uuid;
BEGIN
    SELECT id INTO v_id
    FROM user_profiles
    WHERE auth_user_id = auth.uid()
    AND active = true
    LIMIT 1;

    RETURN v_id;
END;
$$;


CREATE FUNCTION public.get_current_user_role() RETURNS public.user_role
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_role user_role;
BEGIN
    SELECT role INTO v_role
    FROM user_profiles
    WHERE auth_user_id = auth.uid()
    AND active = true
    LIMIT 1;

    RETURN v_role;
END;
$$;


CREATE FUNCTION public.get_customer_activity_detail(p_customer_uuid uuid, p_from_date date, p_to_date date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET jit TO 'off'
    AS $$
DECLARE
    v_user_id uuid;
    v_user_role text;
    v_user_customer_ids uuid[];
    v_customer_name text;
    v_customer_city text;
    v_result jsonb;
    v_summary jsonb;
    v_monthly_trends jsonb;
    v_recent_grns jsonb;
    v_recent_dispatches jsonb;
    v_recent_invoices jsonb;
    v_top_stock_items jsonb;
    v_by_bucket jsonb;
BEGIN
    -- Validate customer_uuid is provided
    IF p_customer_uuid IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Customer UUID is required'
        );
    END IF;

    -- Get caller's role
    IF auth.uid() IS NOT NULL THEN
        SELECT id, role INTO v_user_id, v_user_role
        FROM user_profiles
        WHERE auth_user_id = auth.uid();
    END IF;

    -- Access control
    IF v_user_role IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Authentication required'
        );
    END IF;

    -- Non-admin/supervisor can only view their own customers
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
        FROM users_customers_new
        WHERE user_profile_id = v_user_id;

        IF v_user_customer_ids IS NULL OR NOT (p_customer_uuid = ANY(v_user_customer_ids)) THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'Access denied: You do not have permission to view this customer''s data'
            );
        END IF;
    END IF;

    -- Get customer info
    SELECT name, city INTO v_customer_name, v_customer_city
    FROM customers
    WHERE id = p_customer_uuid AND deleted_at IS NULL;

    IF v_customer_name IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Customer not found'
        );
    END IF;

    -- Calculate summary metrics
    WITH current_stock_data AS (
        SELECT
            SUM(grt.stock) as current_stock,
            -- Weighted average stock age
            CASE WHEN SUM(grt.stock) > 0 THEN
                ROUND(SUM(grt.stock * (CURRENT_DATE - gr.date::date)) / SUM(grt.stock))
            ELSE 0 END as average_stock_age_days
        FROM goodsreceived gr
        JOIN goodsreceived_trl grt ON grt.gr_id = gr.id
        WHERE gr.customer_id = p_customer_uuid
            AND gr.deleted_at IS NULL
            AND grt.stock > 0
    ),
    grn_data AS (
        SELECT
            COUNT(DISTINCT gr.id) as total_grns,
            COALESCE(SUM(grt.qty), 0) as total_grn_quantity
        FROM goodsreceived gr
        JOIN goodsreceived_trl grt ON grt.gr_id = gr.id
        WHERE gr.customer_id = p_customer_uuid
            AND gr.deleted_at IS NULL
            AND gr.date::date BETWEEN p_from_date AND p_to_date
    ),
    dispatch_data AS (
        SELECT
            COUNT(DISTINCT d.id) as total_dispatches,
            COALESCE(SUM(dt.disp_qty), 0) as total_dispatch_quantity
        FROM dispatch d
        JOIN dispatch_trl dt ON dt.disp_id = d.id
        WHERE d.customer_id = p_customer_uuid
            AND d.deleted_at IS NULL
            AND d.disp_date::date BETWEEN p_from_date AND p_to_date
    ),
    invoice_data AS (
        SELECT
            COALESCE(SUM(COALESCE(total, 0) + COALESCE(labour, 0) + COALESCE(tax_amount, 0) - COALESCE(discount, 0)), 0) as total_invoice_amount
        FROM invoice
        WHERE customer_id = p_customer_uuid
            AND deleted_at IS NULL
            AND inv_date::date BETWEEN p_from_date AND p_to_date
    ),
    payment_data AS (
        SELECT
            COALESCE(SUM(p.amount), 0) as total_paid_amount
        FROM payments p
        JOIN invoice i ON p.invoice_id = i.id
        WHERE i.customer_id = p_customer_uuid
            AND i.deleted_at IS NULL
            AND i.inv_date::date BETWEEN p_from_date AND p_to_date
    )
    SELECT jsonb_build_object(
        'current_stock', COALESCE(cs.current_stock, 0),
        'total_grns', COALESCE(gd.total_grns, 0),
        'total_grn_quantity', COALESCE(gd.total_grn_quantity, 0),
        'total_dispatches', COALESCE(dd.total_dispatches, 0),
        'total_dispatch_quantity', COALESCE(dd.total_dispatch_quantity, 0),
        'total_invoice_amount', COALESCE(id.total_invoice_amount, 0),
        'total_paid_amount', COALESCE(pd.total_paid_amount, 0),
        'total_pending_amount', COALESCE(id.total_invoice_amount, 0) - COALESCE(pd.total_paid_amount, 0),
        'average_stock_age_days', COALESCE(cs.average_stock_age_days, 0)
    ) INTO v_summary
    FROM current_stock_data cs
    CROSS JOIN grn_data gd
    CROSS JOIN dispatch_data dd
    CROSS JOIN invoice_data id
    CROSS JOIN payment_data pd;

    -- Monthly trends
    WITH months AS (
        SELECT generate_series(
            DATE_TRUNC('month', p_from_date::timestamp),
            DATE_TRUNC('month', p_to_date::timestamp),
            '1 month'::interval
        )::date as month_start
    ),
    grn_monthly AS (
        SELECT
            DATE_TRUNC('month', gr.date)::date as month_start,
            COUNT(DISTINCT gr.id) as grn_count,
            COALESCE(SUM(grt.qty), 0) as grn_quantity
        FROM goodsreceived gr
        JOIN goodsreceived_trl grt ON grt.gr_id = gr.id
        WHERE gr.customer_id = p_customer_uuid
            AND gr.deleted_at IS NULL
            AND gr.date::date BETWEEN p_from_date AND p_to_date
        GROUP BY DATE_TRUNC('month', gr.date)
    ),
    dispatch_monthly AS (
        SELECT
            DATE_TRUNC('month', d.disp_date)::date as month_start,
            COUNT(DISTINCT d.id) as dispatch_count,
            COALESCE(SUM(dt.disp_qty), 0) as dispatch_quantity
        FROM dispatch d
        JOIN dispatch_trl dt ON dt.disp_id = d.id
        WHERE d.customer_id = p_customer_uuid
            AND d.deleted_at IS NULL
            AND d.disp_date::date BETWEEN p_from_date AND p_to_date
        GROUP BY DATE_TRUNC('month', d.disp_date)
    ),
    invoice_monthly AS (
        SELECT
            DATE_TRUNC('month', inv_date)::date as month_start,
            COALESCE(SUM(COALESCE(total, 0) + COALESCE(labour, 0) + COALESCE(tax_amount, 0) - COALESCE(discount, 0)), 0) as invoice_amount
        FROM invoice
        WHERE customer_id = p_customer_uuid
            AND deleted_at IS NULL
            AND inv_date::date BETWEEN p_from_date AND p_to_date
        GROUP BY DATE_TRUNC('month', inv_date)
    ),
    -- Stock level at end of each month (cumulative GRN - cumulative Dispatch up to month end)
    stock_monthly AS (
        SELECT
            m.month_start,
            (
                SELECT COALESCE(SUM(grt.qty), 0)
                FROM goodsreceived gr
                JOIN goodsreceived_trl grt ON grt.gr_id = gr.id
                WHERE gr.customer_id = p_customer_uuid
                    AND gr.deleted_at IS NULL
                    AND gr.date::date <= (m.month_start + INTERVAL '1 month - 1 day')::date
            ) - (
                SELECT COALESCE(SUM(dt.disp_qty), 0)
                FROM dispatch d
                JOIN dispatch_trl dt ON dt.disp_id = d.id
                WHERE d.customer_id = p_customer_uuid
                    AND d.deleted_at IS NULL
                    AND d.disp_date::date <= (m.month_start + INTERVAL '1 month - 1 day')::date
            ) as stock_level_end
        FROM months m
    )
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'month', TO_CHAR(m.month_start, 'YYYY-MM'),
            'grn_count', COALESCE(gm.grn_count, 0),
            'grn_quantity', COALESCE(gm.grn_quantity, 0),
            'dispatch_count', COALESCE(dm.dispatch_count, 0),
            'dispatch_quantity', COALESCE(dm.dispatch_quantity, 0),
            'invoice_amount', COALESCE(im.invoice_amount, 0),
            'stock_level_end', COALESCE(sm.stock_level_end, 0)
        ) ORDER BY m.month_start
    ), '[]'::jsonb) INTO v_monthly_trends
    FROM months m
    LEFT JOIN grn_monthly gm ON m.month_start = gm.month_start
    LEFT JOIN dispatch_monthly dm ON m.month_start = dm.month_start
    LEFT JOIN invoice_monthly im ON m.month_start = im.month_start
    LEFT JOIN stock_monthly sm ON m.month_start = sm.month_start;

    -- Recent GRNs (last 5)
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'grn_id', grn_id,
            'gr_no', gr_no,
            'grn_date', grn_date,
            'total_qty', total_qty,
            'current_stock', current_stock,
            'is_invoiced', is_invoiced
        ) ORDER BY grn_date DESC
    ), '[]'::jsonb) INTO v_recent_grns
    FROM (
        SELECT
            gr.id as grn_id,
            gr.gr_no,
            gr.date as grn_date,
            COALESCE(SUM(grt.qty), 0) as total_qty,
            COALESCE(SUM(grt.stock), 0) as current_stock,
            EXISTS (SELECT 1 FROM invoice i WHERE i.gr_id = gr.id AND i.deleted_at IS NULL) as is_invoiced
        FROM goodsreceived gr
        LEFT JOIN goodsreceived_trl grt ON grt.gr_id = gr.id
        WHERE gr.customer_id = p_customer_uuid
            AND gr.deleted_at IS NULL
        GROUP BY gr.id, gr.gr_no, gr.date
        ORDER BY gr.date DESC
        LIMIT 5
    ) recent;

    -- Recent Dispatches (last 5)
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'dispatch_id', dispatch_id,
            'dispatch_no', dispatch_no,
            'dispatch_date', dispatch_date,
            'total_qty', total_qty,
            'supervisor_name', supervisor_name
        ) ORDER BY dispatch_date DESC
    ), '[]'::jsonb) INTO v_recent_dispatches
    FROM (
        SELECT
            d.id as dispatch_id,
            d.disp_no as dispatch_no,
            d.disp_date as dispatch_date,
            COALESCE(SUM(dt.disp_qty), 0) as total_qty,
            d.supervisor_name
        FROM dispatch d
        LEFT JOIN dispatch_trl dt ON dt.disp_id = d.id
        WHERE d.customer_id = p_customer_uuid
            AND d.deleted_at IS NULL
        GROUP BY d.id, d.disp_no, d.disp_date, d.supervisor_name
        ORDER BY d.disp_date DESC
        LIMIT 5
    ) recent;

    -- Recent Invoices (last 5)
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'invoice_id', invoice_id,
            'invoice_number', invoice_number,
            'invoice_date', invoice_date,
            'net_total', net_total,
            'status', status
        ) ORDER BY invoice_date DESC
    ), '[]'::jsonb) INTO v_recent_invoices
    FROM (
        SELECT
            i.id as invoice_id,
            i.inv_fin_year::text || '-' || LPAD(i.inv_no::text, 4, '0') as invoice_number,
            i.inv_date as invoice_date,
            COALESCE(i.total, 0) + COALESCE(i.labour, 0) + COALESCE(i.tax_amount, 0) - COALESCE(i.discount, 0) as net_total,
            CASE WHEN EXISTS (SELECT 1 FROM payments p WHERE p.invoice_id = i.id) THEN 'paid' ELSE 'pending' END as status
        FROM invoice i
        WHERE i.customer_id = p_customer_uuid
            AND i.deleted_at IS NULL
        ORDER BY i.inv_date DESC
        LIMIT 5
    ) recent;

    -- Top Stock Items (top 5 by current stock)
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'item_name', item_name,
            'total_stock', total_stock,
            'grn_count', grn_count
        ) ORDER BY total_stock DESC
    ), '[]'::jsonb) INTO v_top_stock_items
    FROM (
        SELECT
            grt.item_name,
            SUM(grt.stock) as total_stock,
            COUNT(DISTINCT gr.id) as grn_count
        FROM goodsreceived gr
        JOIN goodsreceived_trl grt ON grt.gr_id = gr.id
        WHERE gr.customer_id = p_customer_uuid
            AND gr.deleted_at IS NULL
            AND grt.stock > 0
        GROUP BY grt.item_name
        ORDER BY total_stock DESC
        LIMIT 5
    ) top_items;

    -- Aging distribution by bucket
    WITH aging_data AS (
        SELECT
            grt.stock as current_stock,
            (CURRENT_DATE - gr.date::date) as aging_days,
            CASE
                WHEN (CURRENT_DATE - gr.date::date) <= 120 THEN '0-120'
                WHEN (CURRENT_DATE - gr.date::date) <= 240 THEN '121-240'
                WHEN (CURRENT_DATE - gr.date::date) <= 364 THEN '241-364'
                ELSE '364+'
            END as aging_bucket
        FROM goodsreceived gr
        JOIN goodsreceived_trl grt ON grt.gr_id = gr.id
        WHERE gr.customer_id = p_customer_uuid
            AND gr.deleted_at IS NULL
            AND grt.stock > 0
    )
    SELECT jsonb_build_object(
        '0-120', jsonb_build_object(
            'item_count', COUNT(*) FILTER (WHERE aging_bucket = '0-120'),
            'total_quantity', COALESCE(SUM(current_stock) FILTER (WHERE aging_bucket = '0-120'), 0),
            'percentage', CASE WHEN SUM(current_stock) > 0
                THEN ROUND(SUM(current_stock) FILTER (WHERE aging_bucket = '0-120') * 100.0 / SUM(current_stock), 1)
                ELSE 0 END
        ),
        '121-240', jsonb_build_object(
            'item_count', COUNT(*) FILTER (WHERE aging_bucket = '121-240'),
            'total_quantity', COALESCE(SUM(current_stock) FILTER (WHERE aging_bucket = '121-240'), 0),
            'percentage', CASE WHEN SUM(current_stock) > 0
                THEN ROUND(SUM(current_stock) FILTER (WHERE aging_bucket = '121-240') * 100.0 / SUM(current_stock), 1)
                ELSE 0 END
        ),
        '241-364', jsonb_build_object(
            'item_count', COUNT(*) FILTER (WHERE aging_bucket = '241-364'),
            'total_quantity', COALESCE(SUM(current_stock) FILTER (WHERE aging_bucket = '241-364'), 0),
            'percentage', CASE WHEN SUM(current_stock) > 0
                THEN ROUND(SUM(current_stock) FILTER (WHERE aging_bucket = '241-364') * 100.0 / SUM(current_stock), 1)
                ELSE 0 END
        ),
        '364+', jsonb_build_object(
            'item_count', COUNT(*) FILTER (WHERE aging_bucket = '364+'),
            'total_quantity', COALESCE(SUM(current_stock) FILTER (WHERE aging_bucket = '364+'), 0),
            'percentage', CASE WHEN SUM(current_stock) > 0
                THEN ROUND(SUM(current_stock) FILTER (WHERE aging_bucket = '364+') * 100.0 / SUM(current_stock), 1)
                ELSE 0 END
        )
    ) INTO v_by_bucket
    FROM aging_data;

    -- Build final result
    v_result := jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'customer_id', p_customer_uuid,
            'customer_name', v_customer_name,
            'customer_city', v_customer_city,
            'summary', v_summary,
            'monthly_trends', v_monthly_trends,
            'recent_grns', v_recent_grns,
            'recent_dispatches', v_recent_dispatches,
            'top_stock_items', v_top_stock_items,
            'recent_invoices', v_recent_invoices,
            'by_bucket', v_by_bucket
        ),
        'metadata', jsonb_build_object(
            'retrieved_at', NOW(),
            'customer_id', p_customer_uuid,
            'from_date', p_from_date,
            'to_date', p_to_date
        )
    );

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Failed to retrieve customer activity detail: ' || SQLERRM,
            'error_code', SQLSTATE
        );
END;
$$;


CREATE FUNCTION public.get_customer_dispatch_activity(p_customer_uuid uuid, p_from_date date, p_to_date date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result JSONB;
    v_user_role TEXT;
BEGIN
    -- Get user role from JWT claims
    v_user_role := COALESCE(
        (current_setting('request.jwt.claims', true)::jsonb ->> 'user_role'),
        (current_setting('request.jwt.claims', true)::jsonb -> 'user_metadata' ->> 'role')
    );

    -- Check access: admin/supervisor can access all, others only assigned customers
    IF v_user_role NOT IN ('admin', 'supervisor', 'service_role') THEN
        IF NOT EXISTS (
            SELECT 1 FROM unnest(user_accessible_customers()) AS uc(id)
            WHERE uc.id = p_customer_uuid
        ) THEN
            RETURN jsonb_build_object(
                'error', 'Access denied: customer not accessible',
                'summary', NULL,
                'dispatches', '[]'::jsonb
            );
        END IF;
    END IF;

    SELECT jsonb_build_object(
        'summary', (
            SELECT jsonb_build_object(
                'total_dispatches', COUNT(DISTINCT d.id),
                'total_quantity', COALESCE(SUM(dt.disp_qty), 0),
                -- Fixed: weight is per unit, so total = weight × disp_qty
                'total_weight', COALESCE(SUM(gt.weight::numeric * dt.disp_qty), 0)
            )
            FROM dispatch d
            JOIN dispatch_trl dt ON dt.disp_id = d.id
            JOIN goodsreceived_trl gt ON gt.id = dt.gr_trl_id
            WHERE d.customer_id = p_customer_uuid
              AND d.deleted_at IS NULL
              AND d.disp_date::date >= p_from_date
              AND d.disp_date::date <= p_to_date
        ),
        'dispatches', COALESCE((
            SELECT jsonb_agg(dispatch_data ORDER BY dispatch_data->>'disp_date' DESC)
            FROM (
                SELECT jsonb_build_object(
                    'disp_no', d.disp_no,
                    'disp_date', d.disp_date::date,
                    'supervisor_name', d.supervisor_name,
                    'total_qty', (
                        SELECT SUM(dt2.disp_qty)
                        FROM dispatch_trl dt2
                        WHERE dt2.disp_id = d.id
                    ),
                    'items', (
                        SELECT jsonb_agg(
                            jsonb_build_object(
                                'item_name', gt.item_name,
                                'qty', dt.disp_qty,
                                'source_grn', g.gr_no,
                                'source_grn_id', g.id,
                                'orig_qty', gt.qty,
                                'package_mark', gt.package_mark,
                                'rack', gt.rack
                            ) ORDER BY gt.item_name
                        )
                        FROM dispatch_trl dt
                        JOIN goodsreceived_trl gt ON gt.id = dt.gr_trl_id
                        JOIN goodsreceived g ON g.id = dt.gr_id
                        WHERE dt.disp_id = d.id
                    )
                ) AS dispatch_data
                FROM dispatch d
                WHERE d.customer_id = p_customer_uuid
                  AND d.deleted_at IS NULL
                  AND d.disp_date::date >= p_from_date
                  AND d.disp_date::date <= p_to_date
            ) AS dispatches_agg
        ), '[]'::jsonb)
    ) INTO v_result;

    RETURN v_result;
END;
$$;


CREATE FUNCTION public.get_customer_dispatch_items(p_customer_id uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_filters jsonb DEFAULT '{}'::jsonb, p_sort_by text DEFAULT 'grn_gr_no'::text, p_sort_order text DEFAULT 'asc'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result jsonb;
    v_total_count integer;
    v_total_initial_qty bigint;
    v_total_dispatch_qty bigint;
    v_total_weight bigint;
    v_items jsonb;
    v_user_role text;
    v_user_customer_ids uuid[];
    v_order_direction text;
BEGIN
    -- Security: Get user role and verify access
    SELECT role INTO v_user_role FROM user_profiles
    WHERE auth_user_id = auth.uid();

    -- If user is not admin/supervisor, check customer access
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
        FROM users_customers_new
        WHERE user_profile_id = (SELECT id FROM user_profiles WHERE auth_user_id = auth.uid());

        -- Verify the requested customer is in their assigned list
        IF v_user_customer_ids IS NULL OR NOT (p_customer_id = ANY(v_user_customer_ids)) THEN
            RETURN jsonb_build_object(
                'success', false,
                'data', null,
                'message', 'Access denied: You do not have permission to access this customer''s data'
            );
        END IF;
    END IF;

    -- Set order direction
    v_order_direction := CASE WHEN lower(p_sort_order) = 'desc' THEN 'DESC' ELSE 'ASC' END;

    -- Get total count for pagination (snake_case filter keys)
    SELECT COUNT(*) INTO v_total_count
    FROM dispatch_trl dt
    JOIN dispatch d ON dt.disp_id = d.id
    JOIN goodsreceived_trl grt ON dt.gr_trl_id = grt.id
    JOIN goodsreceived gr ON grt.gr_id = gr.id
    WHERE gr.customer_id = p_customer_id
    AND (p_date_from IS NULL OR p_date_to IS NULL OR d.disp_date BETWEEN p_date_from AND p_date_to)
    AND (NOT p_filters ? 'item_name' OR p_filters->>'item_name' = '' OR grt.item_name ILIKE '%' || (p_filters->>'item_name') || '%')
    AND (NOT p_filters ? 'gr_no' OR p_filters->>'gr_no' = '' OR gr.gr_no ILIKE '%' || (p_filters->>'gr_no') || '%')
    AND (NOT p_filters ? 'disp_no' OR p_filters->>'disp_no' = '' OR d.disp_no ILIKE '%' || (p_filters->>'disp_no') || '%')
    AND (NOT p_filters ? 'package_mark' OR p_filters->>'package_mark' = '' OR grt.package_mark ILIKE '%' || (p_filters->>'package_mark') || '%')
    AND (NOT p_filters ? 'qty_min' OR (p_filters->>'qty_min')::integer IS NULL
         OR grt.qty >= (p_filters->>'qty_min')::integer)
    AND (NOT p_filters ? 'qty_max' OR (p_filters->>'qty_max')::integer IS NULL
         OR grt.qty <= (p_filters->>'qty_max')::integer)
    AND (NOT p_filters ? 'disp_qty_min' OR (p_filters->>'disp_qty_min')::integer IS NULL
         OR dt.disp_qty >= (p_filters->>'disp_qty_min')::integer)
    AND (NOT p_filters ? 'disp_qty_max' OR (p_filters->>'disp_qty_max')::integer IS NULL
         OR dt.disp_qty <= (p_filters->>'disp_qty_max')::integer);

    -- Get aggregations
    SELECT
        COALESCE(SUM(grt.qty), 0),
        COALESCE(SUM(dt.disp_qty), 0),
        COALESCE(SUM(grt.weight * dt.disp_qty), 0)
    INTO
        v_total_initial_qty,
        v_total_dispatch_qty,
        v_total_weight
    FROM dispatch_trl dt
    JOIN dispatch d ON dt.disp_id = d.id
    JOIN goodsreceived_trl grt ON dt.gr_trl_id = grt.id
    JOIN goodsreceived gr ON grt.gr_id = gr.id
    WHERE gr.customer_id = p_customer_id
    AND (p_date_from IS NULL OR p_date_to IS NULL OR d.disp_date BETWEEN p_date_from AND p_date_to)
    AND (NOT p_filters ? 'item_name' OR p_filters->>'item_name' = '' OR grt.item_name ILIKE '%' || (p_filters->>'item_name') || '%')
    AND (NOT p_filters ? 'gr_no' OR p_filters->>'gr_no' = '' OR gr.gr_no ILIKE '%' || (p_filters->>'gr_no') || '%')
    AND (NOT p_filters ? 'disp_no' OR p_filters->>'disp_no' = '' OR d.disp_no ILIKE '%' || (p_filters->>'disp_no') || '%')
    AND (NOT p_filters ? 'package_mark' OR p_filters->>'package_mark' = '' OR grt.package_mark ILIKE '%' || (p_filters->>'package_mark') || '%')
    AND (NOT p_filters ? 'qty_min' OR (p_filters->>'qty_min')::integer IS NULL
         OR grt.qty >= (p_filters->>'qty_min')::integer)
    AND (NOT p_filters ? 'qty_max' OR (p_filters->>'qty_max')::integer IS NULL
         OR grt.qty <= (p_filters->>'qty_max')::integer)
    AND (NOT p_filters ? 'disp_qty_min' OR (p_filters->>'disp_qty_min')::integer IS NULL
         OR dt.disp_qty >= (p_filters->>'disp_qty_min')::integer)
    AND (NOT p_filters ? 'disp_qty_max' OR (p_filters->>'disp_qty_max')::integer IS NULL
         OR dt.disp_qty <= (p_filters->>'disp_qty_max')::integer);

    -- Get paginated items with dynamic sorting (snake_case sort keys and response keys)
    SELECT COALESCE(jsonb_agg(item_row ORDER BY
        CASE WHEN p_sort_by = 'grn_gr_no' AND v_order_direction = 'ASC' THEN grns_gr_no END ASC,
        CASE WHEN p_sort_by = 'grn_gr_no' AND v_order_direction = 'DESC' THEN grns_gr_no END DESC,
        CASE WHEN p_sort_by = 'grn_date' AND v_order_direction = 'ASC' THEN grns_date END ASC,
        CASE WHEN p_sort_by = 'grn_date' AND v_order_direction = 'DESC' THEN grns_date END DESC,
        CASE WHEN p_sort_by = 'item_name' AND v_order_direction = 'ASC' THEN grt_item_name END ASC,
        CASE WHEN p_sort_by = 'item_name' AND v_order_direction = 'DESC' THEN grt_item_name END DESC,
        CASE WHEN p_sort_by = 'disp_no' AND v_order_direction = 'ASC' THEN disp_no END ASC,
        CASE WHEN p_sort_by = 'disp_no' AND v_order_direction = 'DESC' THEN disp_no END DESC,
        CASE WHEN p_sort_by = 'disp_date' AND v_order_direction = 'ASC' THEN disp_date END ASC,
        CASE WHEN p_sort_by = 'disp_date' AND v_order_direction = 'DESC' THEN disp_date END DESC,
        CASE WHEN p_sort_by = 'qty' AND v_order_direction = 'ASC' THEN grt_qty END ASC,
        CASE WHEN p_sort_by = 'qty' AND v_order_direction = 'DESC' THEN grt_qty END DESC,
        CASE WHEN p_sort_by = 'disp_qty' AND v_order_direction = 'ASC' THEN disp_qty END ASC,
        CASE WHEN p_sort_by = 'disp_qty' AND v_order_direction = 'DESC' THEN disp_qty END DESC
    ), '[]'::jsonb)
    INTO v_items
    FROM (
        SELECT
            jsonb_build_object(
                'dispatch_id', d.id,
                'disp_no', d.disp_no,
                'disp_date', d.disp_date,
                'disp_qty', dt.disp_qty,
                'grn_id', gr.id,
                'gr_no', gr.gr_no,
                'grn_date', gr.date,
                'grn_item_id', grt.id,
                'item_id', grt.item_id,
                'item_name', grt.item_name,
                'qty', grt.qty,
                'stock', grt.stock,
                'weight', grt.weight,
                'packaging', grt.packaging,
                'package_mark', grt.package_mark,
                'rack', grt.rack
            ) as item_row,
            gr.gr_no as grns_gr_no,
            gr.date as grns_date,
            grt.item_name as grt_item_name,
            d.disp_no as disp_no,
            d.disp_date as disp_date,
            grt.qty as grt_qty,
            dt.disp_qty as disp_qty
        FROM dispatch_trl dt
        JOIN dispatch d ON dt.disp_id = d.id
        JOIN goodsreceived_trl grt ON dt.gr_trl_id = grt.id
        JOIN goodsreceived gr ON grt.gr_id = gr.id
        WHERE gr.customer_id = p_customer_id
        AND (p_date_from IS NULL OR p_date_to IS NULL OR d.disp_date BETWEEN p_date_from AND p_date_to)
        AND (NOT p_filters ? 'item_name' OR p_filters->>'item_name' = '' OR grt.item_name ILIKE '%' || (p_filters->>'item_name') || '%')
        AND (NOT p_filters ? 'gr_no' OR p_filters->>'gr_no' = '' OR gr.gr_no ILIKE '%' || (p_filters->>'gr_no') || '%')
        AND (NOT p_filters ? 'disp_no' OR p_filters->>'disp_no' = '' OR d.disp_no ILIKE '%' || (p_filters->>'disp_no') || '%')
        AND (NOT p_filters ? 'package_mark' OR p_filters->>'package_mark' = '' OR grt.package_mark ILIKE '%' || (p_filters->>'package_mark') || '%')
        AND (NOT p_filters ? 'qty_min' OR (p_filters->>'qty_min')::integer IS NULL
             OR grt.qty >= (p_filters->>'qty_min')::integer)
        AND (NOT p_filters ? 'qty_max' OR (p_filters->>'qty_max')::integer IS NULL
             OR grt.qty <= (p_filters->>'qty_max')::integer)
        AND (NOT p_filters ? 'disp_qty_min' OR (p_filters->>'disp_qty_min')::integer IS NULL
             OR dt.disp_qty >= (p_filters->>'disp_qty_min')::integer)
        AND (NOT p_filters ? 'disp_qty_max' OR (p_filters->>'disp_qty_max')::integer IS NULL
             OR dt.disp_qty <= (p_filters->>'disp_qty_max')::integer)
        LIMIT p_limit OFFSET p_offset
    ) sub;

    -- Build final result (snake_case keys)
    v_result := jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'items', v_items,
            'pagination', jsonb_build_object(
                'total_count', v_total_count,
                'limit', p_limit,
                'offset', p_offset,
                'has_more', (p_offset + p_limit) < v_total_count
            ),
            'aggregations', jsonb_build_object(
                'total_initial_qty', v_total_initial_qty,
                'total_dispatch_qty', v_total_dispatch_qty,
                'total_weight', v_total_weight,
                'record_count', v_total_count
            )
        ),
        'message', null
    );

    RETURN v_result;
END;
$$;


CREATE FUNCTION public.get_customer_grn_activity(p_customer_uuid uuid DEFAULT NULL::uuid, p_from_date date DEFAULT NULL::date, p_to_date date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET jit TO 'off'
    AS $$
DECLARE
    v_user_id uuid;
    v_user_role text;
    v_user_customer_ids uuid[];
    v_from_date date;
    v_to_date date;
    v_result jsonb;
    v_summary jsonb;
    v_grns jsonb;
    v_by_customer jsonb;
BEGIN
    -- Get caller's role
    IF auth.uid() IS NOT NULL THEN
        SELECT id, role INTO v_user_id, v_user_role
        FROM user_profiles
        WHERE auth_user_id = auth.uid();
    END IF;

    -- Access control
    IF v_user_role IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Authentication required'
        );
    END IF;

    -- Non-admin/supervisor can only view their own customers
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        IF p_customer_uuid IS NULL THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'PERMISSION_DENIED: Customer UUID required for non-staff users'
            );
        END IF;

        -- Check if user has access to this customer
        SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
        FROM users_customers_new
        WHERE user_profile_id = v_user_id;

        IF v_user_customer_ids IS NULL OR NOT (p_customer_uuid = ANY(v_user_customer_ids)) THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'Access denied: You do not have permission to view this customer''s data'
            );
        END IF;
    END IF;

    -- Set date defaults
    v_from_date := COALESCE(p_from_date, CURRENT_DATE - INTERVAL '10 days');
    v_to_date := COALESCE(p_to_date, CURRENT_DATE);

    -- Single customer view
    IF p_customer_uuid IS NOT NULL THEN
        WITH grn_data AS (
            SELECT
                gr.id as grn_id,
                gr.gr_no,
                gr.date as grn_date,
                gr.registration,
                gr.sender_name,
                up.name as supervisor_name,
                gr.note
            FROM goodsreceived gr
            LEFT JOIN user_profiles up ON gr.supervisor_id = up.id
            WHERE gr.customer_id = p_customer_uuid
                AND gr.deleted_at IS NULL
                AND gr.date BETWEEN v_from_date AND v_to_date
        ),
        grn_items AS (
            SELECT
                grt.gr_id,
                jsonb_agg(
                    jsonb_build_object(
                        'item_name', grt.item_name,
                        'packaging', grt.packaging,
                        'quantity', grt.qty,
                        'current_stock', grt.stock,
                        'dispatched_qty', grt.qty - grt.stock,
                        'weight', grt.weight,
                        'rack', grt.rack,
                        'package_mark', grt.package_mark
                    )
                ) as items,
                COUNT(*) as item_count,
                SUM(grt.qty) as total_qty,
                SUM(grt.weight) as total_weight
            FROM goodsreceived_trl grt
            GROUP BY grt.gr_id
        ),
        invoice_status AS (
            SELECT
                i.gr_id,
                jsonb_build_object(
                    'is_invoiced', true,
                    'invoice_id', i.id,
                    'invoice_number', i.inv_fin_year::text || '-' || i.inv_no::text
                ) as status
            FROM invoice i
            WHERE i.deleted_at IS NULL
        ),
        dispatch_summary AS (
            SELECT
                dt.gr_trl_id,
                SUM(dt.disp_qty) as total_dispatched,
                COUNT(DISTINCT d.id) as dispatch_count,
                MAX(d.disp_date) as last_dispatch_date
            FROM dispatch_trl dt
            JOIN dispatch d ON dt.disp_id = d.id
            WHERE d.deleted_at IS NULL
            GROUP BY dt.gr_trl_id
        ),
        grn_dispatch_summary AS (
            SELECT
                grt.gr_id,
                COALESCE(SUM(ds.total_dispatched), 0) as total_dispatched,
                SUM(grt.stock) as current_stock,
                MAX(COALESCE(ds.dispatch_count, 0)) as dispatch_count,
                MAX(ds.last_dispatch_date) as last_dispatch_date,
                CASE WHEN SUM(grt.stock) = 0 THEN true ELSE false END as is_fully_dispatched
            FROM goodsreceived_trl grt
            LEFT JOIN dispatch_summary ds ON grt.id = ds.gr_trl_id
            GROUP BY grt.gr_id
        ),
        image_counts AS (
            SELECT
                grn_id,
                COUNT(*) as image_count
            FROM grn_images
            GROUP BY grn_id
        ),
        grn_full AS (
            SELECT
                gd.grn_id,
                gd.gr_no,
                gd.grn_date,
                gd.registration,
                gd.sender_name,
                gd.supervisor_name,
                gd.note,
                COALESCE(gi.item_count, 0) as total_items,
                COALESCE(gi.total_qty, 0) as total_qty,
                COALESCE(gi.total_weight, 0) as total_weight,
                COALESCE(ic.image_count, 0) as image_count,
                COALESCE(inv.status, jsonb_build_object('is_invoiced', false, 'invoice_id', null, 'invoice_number', null)) as invoice_status,
                jsonb_build_object(
                    'total_dispatched', COALESCE(gds.total_dispatched, 0),
                    'current_stock', COALESCE(gds.current_stock, 0),
                    'dispatch_count', COALESCE(gds.dispatch_count, 0),
                    'last_dispatch_date', gds.last_dispatch_date,
                    'is_fully_dispatched', COALESCE(gds.is_fully_dispatched, false)
                ) as dispatch_summary,
                COALESCE(gi.items, '[]'::jsonb) as items
            FROM grn_data gd
            LEFT JOIN grn_items gi ON gd.grn_id = gi.gr_id
            LEFT JOIN invoice_status inv ON gd.grn_id = inv.gr_id
            LEFT JOIN grn_dispatch_summary gds ON gd.grn_id = gds.gr_id
            LEFT JOIN image_counts ic ON gd.grn_id = ic.grn_id
        )
        SELECT
            jsonb_build_object(
                'total_grns', COUNT(*),
                'total_items', COALESCE(SUM(total_items), 0),
                'total_quantity', COALESCE(SUM(total_qty), 0),
                'total_weight_kg', COALESCE(SUM(total_weight), 0),
                'total_invoiced_grns', COUNT(*) FILTER (WHERE (invoice_status->>'is_invoiced')::boolean = true),
                'total_images', COALESCE(SUM(image_count), 0)
            ),
            COALESCE(jsonb_agg(
                jsonb_build_object(
                    'grn_id', grn_id,
                    'gr_no', gr_no,
                    'grn_date', grn_date,
                    'registration', registration,
                    'sender_name', sender_name,
                    'supervisor_name', supervisor_name,
                    'note', note,
                    'total_items', total_items,
                    'total_qty', total_qty,
                    'total_weight', total_weight,
                    'image_count', image_count,
                    'invoice_status', invoice_status,
                    'dispatch_summary', dispatch_summary,
                    'items', items
                ) ORDER BY grn_date DESC
            ), '[]'::jsonb)
        INTO v_summary, v_grns
        FROM grn_full;

        v_result := jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'summary', v_summary,
                'grns', v_grns
            ),
            'metadata', jsonb_build_object(
                'retrieved_at', NOW(),
                'customer_id', p_customer_uuid,
                'from_date', v_from_date,
                'to_date', v_to_date
            )
        );

    -- All customers view (staff only)
    ELSE
        WITH grn_data AS (
            SELECT
                gr.id as grn_id,
                gr.customer_id,
                c.name as customer_name,
                gr.date as grn_date
            FROM goodsreceived gr
            JOIN customers c ON gr.customer_id = c.id
            WHERE gr.deleted_at IS NULL
                AND gr.date BETWEEN v_from_date AND v_to_date
        ),
        grn_items AS (
            SELECT
                grt.gr_id,
                SUM(grt.qty) as total_qty,
                SUM(grt.weight) as total_weight
            FROM goodsreceived_trl grt
            GROUP BY grt.gr_id
        ),
        customer_aggregates AS (
            SELECT
                gd.customer_id,
                gd.customer_name,
                COUNT(DISTINCT gd.grn_id) as grn_count,
                COALESCE(SUM(gi.total_qty), 0) as total_quantity,
                COALESCE(SUM(gi.total_weight), 0) as total_weight,
                MAX(gd.grn_date) as latest_grn_date
            FROM grn_data gd
            LEFT JOIN grn_items gi ON gd.grn_id = gi.gr_id
            GROUP BY gd.customer_id, gd.customer_name
        )
        SELECT
            jsonb_build_object(
                'total_grns', (SELECT COUNT(DISTINCT grn_id) FROM grn_data),
                'total_customers', (SELECT COUNT(DISTINCT customer_id) FROM grn_data),
                'total_items', COALESCE((SELECT SUM(gi.total_qty) FROM grn_data gd LEFT JOIN grn_items gi ON gd.grn_id = gi.gr_id), 0),
                'total_quantity', COALESCE((SELECT SUM(gi.total_qty) FROM grn_data gd LEFT JOIN grn_items gi ON gd.grn_id = gi.gr_id), 0),
                'total_weight_kg', COALESCE((SELECT SUM(gi.total_weight) FROM grn_data gd LEFT JOIN grn_items gi ON gd.grn_id = gi.gr_id), 0)
            ),
            COALESCE((
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'customer_id', customer_id,
                        'customer_name', customer_name,
                        'grn_count', grn_count,
                        'total_quantity', total_quantity,
                        'total_weight', total_weight,
                        'latest_grn_date', latest_grn_date
                    ) ORDER BY grn_count DESC
                )
                FROM customer_aggregates
            ), '[]'::jsonb)
        INTO v_summary, v_by_customer;

        v_result := jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'summary', v_summary,
                'by_customer', v_by_customer
            ),
            'metadata', jsonb_build_object(
                'retrieved_at', NOW(),
                'from_date', v_from_date,
                'to_date', v_to_date
            )
        );
    END IF;

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Failed to retrieve GRN activity: ' || SQLERRM,
            'error_code', SQLSTATE
        );
END;
$$;


CREATE FUNCTION public.get_customer_grn_items(p_customer_id uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_filters jsonb DEFAULT '{}'::jsonb, p_sort_by text DEFAULT 'date'::text, p_sort_order text DEFAULT 'desc'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_result jsonb;
      v_total_count integer;
      v_total_qty bigint;
      v_total_stock bigint;
      v_items jsonb;
      v_user_role text;
      v_user_customer_ids uuid[];
  BEGIN
      -- Security: Get user role and verify access
      SELECT role INTO v_user_role FROM user_profiles
      WHERE auth_user_id = auth.uid();

      -- If user is not admin/supervisor, check customer access
      IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
          SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
          FROM users_customers_new
          WHERE user_profile_id = (SELECT id FROM user_profiles WHERE auth_user_id = auth.uid());

          -- Verify the requested customer is in their assigned list
          IF v_user_customer_ids IS NULL OR NOT (p_customer_id = ANY(v_user_customer_ids)) THEN
              RETURN jsonb_build_object(
                  'success', false,
                  'data', null,
                  'message', 'Access denied: You do not have permission to access this customer''s data'
              );
          END IF;
      END IF;

      -- Get total count for pagination
      SELECT COUNT(*) INTO v_total_count
      FROM goodsreceived_trl grt
      JOIN goodsreceived gr ON grt.gr_id = gr.id
      WHERE gr.customer_id = p_customer_id
      AND (p_date_from IS NULL OR p_date_to IS NULL OR gr.date BETWEEN p_date_from AND p_date_to)
      AND (NOT p_filters ? 'item_name' OR p_filters->>'item_name' = '' OR grt.item_name ILIKE '%' || (p_filters->>'item_name') || '%')
      AND (NOT p_filters ? 'gr_no' OR p_filters->>'gr_no' = '' OR gr.gr_no ILIKE '%' || (p_filters->>'gr_no') || '%')
      AND (NOT p_filters ? 'package_mark' OR p_filters->>'package_mark' = '' OR grt.package_mark ILIKE '%' || (p_filters->>'package_mark') || '%')
      AND (NOT p_filters ? 'rack' OR p_filters->>'rack' = '' OR grt.rack ILIKE '%' || (p_filters->>'rack') || '%');

      -- Get aggregations
      SELECT
          COALESCE(SUM(grt.qty), 0),
          COALESCE(SUM(grt.stock), 0)
      INTO v_total_qty, v_total_stock
      FROM goodsreceived_trl grt
      JOIN goodsreceived gr ON grt.gr_id = gr.id
      WHERE gr.customer_id = p_customer_id
      AND (p_date_from IS NULL OR p_date_to IS NULL OR gr.date BETWEEN p_date_from AND p_date_to)
      AND (NOT p_filters ? 'item_name' OR p_filters->>'item_name' = '' OR grt.item_name ILIKE '%' || (p_filters->>'item_name') || '%')
      AND (NOT p_filters ? 'gr_no' OR p_filters->>'gr_no' = '' OR gr.gr_no ILIKE '%' || (p_filters->>'gr_no') || '%')
      AND (NOT p_filters ? 'package_mark' OR p_filters->>'package_mark' = '' OR grt.package_mark ILIKE '%' || (p_filters->>'package_mark') || '%')
      AND (NOT p_filters ? 'rack' OR p_filters->>'rack' = '' OR grt.rack ILIKE '%' || (p_filters->>'rack') || '%');

      -- Get main data
      SELECT jsonb_agg(
          jsonb_build_object(
              'id', sub.grt_id,
              'grn_id', sub.gr_id,
              'gr_no', sub.gr_no,
              'item_id', sub.item_id,
              'item_name', sub.item_name,
              'qty', sub.qty,
              'stock', sub.stock,
              'weight', sub.weight,
              'rack', sub.rack,
              'package_mark', sub.package_mark,
              'packaging', sub.packaging,
              'date', sub.date,
              'grns_id', sub.grns_id,
              'grns_gr_no', sub.grns_gr_no,
              'grns_date', sub.grns_date,
              'customer_name', sub.customer_name,
              'customer_id', sub.customer_id,
              'registration', sub.registration,
              'supervisor_name', sub.supervisor_name,
              'sender_name', sub.sender_name,
              'invoiced', sub.invoiced,
              'leon', sub.leon,
              'out_of_stock', sub.out_of_stock,
              'note', sub.note,
              'image_url', sub.gr_image_url
          )
      ) INTO v_items
      FROM (
          SELECT
              grt.id as grt_id,
              grt.gr_id,
              grt.item_id,
              grt.item_name,
              grt.qty,
              grt.stock,
              grt.weight,
              grt.rack,
              grt.package_mark,
              grt.packaging,
              gr.id as grns_id,
              gr.gr_no,
              gr.date,
              gr.customer_name,
              gr.customer_id,
              gr.registration,
              gr.supervisor_name,
              gr.sender_name,
              gr.invoiced,
              gr.leon,
              gr.out_of_stock,
              gr.note,
              gr.gr_image_url,
              gr.gr_no as grns_gr_no,
              gr.date as grns_date
          FROM goodsreceived_trl grt
          JOIN goodsreceived gr ON grt.gr_id = gr.id
          WHERE gr.customer_id = p_customer_id
          AND (p_date_from IS NULL OR p_date_to IS NULL OR gr.date BETWEEN p_date_from AND p_date_to)
          AND (NOT p_filters ? 'item_name' OR p_filters->>'item_name' = '' OR grt.item_name ILIKE '%' || (p_filters->>'item_name') || '%')
          AND (NOT p_filters ? 'gr_no' OR p_filters->>'gr_no' = '' OR gr.gr_no ILIKE '%' || (p_filters->>'gr_no') || '%')
          AND (NOT p_filters ? 'package_mark' OR p_filters->>'package_mark' = '' OR grt.package_mark ILIKE '%' || (p_filters->>'package_mark') || '%')
          AND (NOT p_filters ? 'rack' OR p_filters->>'rack' = '' OR grt.rack ILIKE '%' || (p_filters->>'rack') || '%')
          ORDER BY
              CASE WHEN p_sort_by = 'date' AND p_sort_order = 'desc' THEN gr.date END DESC,
              CASE WHEN p_sort_by = 'date' AND p_sort_order = 'asc' THEN gr.date END ASC,
              CASE WHEN p_sort_by = 'gr_no' AND p_sort_order = 'desc' THEN gr.gr_no END DESC,
              CASE WHEN p_sort_by = 'gr_no' AND p_sort_order = 'asc' THEN gr.gr_no END ASC,
              CASE WHEN p_sort_by = 'item_name' AND p_sort_order = 'desc' THEN grt.item_name END DESC,
              CASE WHEN p_sort_by = 'item_name' AND p_sort_order = 'asc' THEN grt.item_name END ASC,
              CASE WHEN p_sort_by = 'qty' AND p_sort_order = 'desc' THEN grt.qty END DESC,
              CASE WHEN p_sort_by = 'qty' AND p_sort_order = 'asc' THEN grt.qty END ASC,
              CASE WHEN p_sort_by = 'stock' AND p_sort_order = 'desc' THEN grt.stock END DESC,
              CASE WHEN p_sort_by = 'stock' AND p_sort_order = 'asc' THEN grt.stock END ASC,
              gr.date DESC
          LIMIT p_limit OFFSET p_offset
      ) sub;

      -- Build final result
      v_result := jsonb_build_object(
          'success', true,
          'data', jsonb_build_object(
              'items', COALESCE(v_items, '[]'::jsonb),
              'pagination', jsonb_build_object(
                  'total', v_total_count,
                  'has_more', (p_offset + p_limit) < v_total_count
              ),
              'aggregations', jsonb_build_object(
                  'total_qty', v_total_qty,
                  'total_stock', v_total_stock,
                  'total_count', v_total_count
              )
          ),
          'message', 'GRN items retrieved successfully'
      );

      RETURN v_result;

  EXCEPTION
      WHEN OTHERS THEN
          RETURN jsonb_build_object(
              'success', false,
              'data', NULL,
              'message', 'Error retrieving GRN items: ' || SQLERRM
          );
  END;
  $$;


CREATE FUNCTION public.get_customer_grns_with_stock_dispatch_sorted(p_customer_id uuid, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_role text;
    v_user_customer_ids uuid[];
    v_is_superuser boolean;
    v_result jsonb;
BEGIN
    -- Validate required parameter
    IF p_customer_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', null,
            'message', 'p_customer_id is required'
        );
    END IF;

    -- Normalize pagination
    IF p_limit IS NULL OR p_limit < 1 THEN
        p_limit := 20;
    ELSIF p_limit > 100 THEN
        p_limit := 100;
    END IF;

    IF p_offset IS NULL OR p_offset < 0 THEN
        p_offset := 0;
    END IF;

    -- Check if running as superuser (for testing)
    SELECT current_user = 'postgres' INTO v_is_superuser;

    -- Security: Get user role (skip if superuser)
    IF NOT v_is_superuser THEN
        SELECT role INTO v_user_role FROM user_profiles
        WHERE auth_user_id = auth.uid();

        -- If user is not admin/supervisor, verify customer access
        IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
            v_user_customer_ids := user_accessible_customers();

            -- Check if user has access to this customer
            IF NOT (p_customer_id = ANY(v_user_customer_ids)) THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'data', null,
                    'message', 'Access denied'
                );
            END IF;
        END IF;
    END IF;

    -- Get GRNs with stock sorted by last dispatch
    SELECT jsonb_agg(row_data ORDER BY (row_data->>'last_dispatch_date') DESC NULLS LAST, (row_data->>'grn_date') DESC)
    INTO v_result
    FROM (
        SELECT jsonb_build_object(
            'grn_id', gs.id,
            'gr_no', gs.gr_no,
            'grn_date', gs.date,
            'customer_name', gs.customer_name,
            'total_stock', gs.total_stock,
            'item_count', gs.item_count,
            'last_dispatch_date', (
                SELECT MAX(d.disp_date)
                FROM dispatch_trl dt
                JOIN dispatch d ON dt.disp_id = d.id AND d.deleted_at IS NULL
                WHERE dt.gr_id = gs.id
            )
        ) as row_data
        FROM (
            SELECT
                gr.id,
                gr.gr_no,
                gr.date,
                gr.customer_name,
                SUM(grt.stock)::INTEGER as total_stock,
                COUNT(grt.id)::INTEGER as item_count
            FROM goodsreceived gr
            JOIN goodsreceived_trl grt ON gr.id = grt.gr_id AND grt.stock > 0
            WHERE gr.customer_id = p_customer_id
              AND gr.deleted_at IS NULL
            GROUP BY gr.id, gr.gr_no, gr.date, gr.customer_name
        ) gs
        LIMIT p_limit
        OFFSET p_offset
    ) sub;

    RETURN jsonb_build_object(
        'success', true,
        'data', COALESCE(v_result, '[]'::jsonb)
    );
END;
$$;


CREATE FUNCTION public.get_customer_invoice_summary(p_customer_uuid uuid DEFAULT NULL::uuid, p_from_date date DEFAULT NULL::date, p_to_date date DEFAULT NULL::date, p_financial_year integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET jit TO 'off'
    AS $$
DECLARE
    v_user_id uuid;
    v_user_role text;
    v_user_customer_ids uuid[];
    v_from_date date;
    v_to_date date;
    v_result jsonb;
    v_summary jsonb;
    v_invoices jsonb;
    v_by_month jsonb;
    v_by_customer jsonb;
BEGIN
    -- Get caller's role
    IF auth.uid() IS NOT NULL THEN
        SELECT id, role INTO v_user_id, v_user_role
        FROM user_profiles
        WHERE auth_user_id = auth.uid();
    END IF;

    -- Access control
    IF v_user_role IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Authentication required'
        );
    END IF;

    -- Non-admin/supervisor: get accessible customers
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
        FROM users_customers_new
        WHERE user_profile_id = v_user_id;

        -- If no customers assigned, return empty
        IF v_user_customer_ids IS NULL OR array_length(v_user_customer_ids, 1) IS NULL THEN
            RETURN jsonb_build_object(
                'success', true,
                'data', jsonb_build_object(
                    'summary', jsonb_build_object(
                        'total_invoices', 0,
                        'total_amount', 0,
                        'net_amount', 0
                    ),
                    'invoices', '[]'::jsonb,
                    'by_month', '[]'::jsonb
                ),
                'metadata', jsonb_build_object('retrieved_at', NOW())
            );
        END IF;

        -- If specific customer requested, verify access
        IF p_customer_uuid IS NOT NULL AND NOT (p_customer_uuid = ANY(v_user_customer_ids)) THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'Access denied: You do not have permission to view this customer''s data'
            );
        END IF;
    END IF;

    -- Set date defaults
    v_from_date := COALESCE(p_from_date, CURRENT_DATE - INTERVAL '30 days');
    v_to_date := COALESCE(p_to_date, CURRENT_DATE);

    -- Single customer view
    IF p_customer_uuid IS NOT NULL THEN
        WITH invoice_data AS (
            SELECT
                i.id as invoice_id,
                i.inv_fin_year::text || '-' || LPAD(i.inv_no::text, 4, '0') as invoice_number,
                i.inv_fin_year,
                i.inv_no,
                i.inv_date,
                i.gr_id,
                gr.gr_no as grn_ref,
                i.total,
                i.labour,
                i.discount,
                i.tax_amount,
                (COALESCE(i.total, 0) + COALESCE(i.labour, 0) + COALESCE(i.tax_amount, 0) - COALESCE(i.discount, 0)) as net_total,
                i.notes
            FROM invoice i
            LEFT JOIN goodsreceived gr ON i.gr_id = gr.id
            WHERE i.customer_id = p_customer_uuid
                AND i.deleted_at IS NULL
                AND (p_financial_year IS NULL OR i.inv_fin_year = p_financial_year)
                AND i.inv_date BETWEEN v_from_date AND v_to_date
        ),
        invoice_items AS (
            SELECT
                it.invoice_id,
                COUNT(*) as item_count,
                SUM(it.duration) as total_quantity,
                jsonb_agg(
                    jsonb_build_object(
                        'item_id', grt.item_id,
                        'item_name', grt.item_name,
                        'packaging', grt.packaging,
                        'quantity', it.duration,
                        'rate', CASE WHEN it.duration > 0 THEN ROUND(it.charge / it.duration, 2) ELSE 0 END,
                        'no_of_days', it.no_of_days,
                        'charge', it.charge,
                        'labour_rate', it.labour_rate,
                        'labour_amount', ROUND(it.labour_rate * it.duration, 2),
                        'tax_percent', CASE WHEN it.charge > 0 THEN ROUND((it.tax / it.charge) * 100, 0) ELSE 0 END,
                        'tax_amount', it.tax,
                        'line_total', COALESCE(it.charge, 0) + COALESCE(it.tax, 0) + ROUND(COALESCE(it.labour_rate, 0) * COALESCE(it.duration, 0), 2),
                        'grn_item_ref', jsonb_build_object(
                            'gr_no', gr.gr_no,
                            'rack', grt.rack,
                            'package_mark', grt.package_mark
                        )
                    )
                ) as line_items
            FROM invoice_trl it
            JOIN dispatch_trl dt ON it.disp_trl_id = dt.id
            JOIN goodsreceived_trl grt ON dt.gr_trl_id = grt.id
            JOIN goodsreceived gr ON grt.gr_id = gr.id
            GROUP BY it.invoice_id
        ),
        payment_status AS (
            SELECT
                p.invoice_id,
                jsonb_build_object(
                    'status', 'paid',
                    'paid_date', p.payment_date,
                    'payment_ref', COALESCE(p.cheque_no, p.online_ref, p.payment_no),
                    'amount', p.amount,
                    'payment_mode', p.payment_mode
                ) as status
            FROM payments p
            WHERE p.invoice_id IS NOT NULL
        ),
        invoices_full AS (
            SELECT
                id.invoice_id,
                id.invoice_number,
                id.inv_fin_year::text || '-' || (id.inv_fin_year + 1)::text as financial_year,
                id.inv_date as invoice_date,
                id.gr_id as grn_id,
                id.grn_ref,
                id.total,
                id.labour,
                id.discount,
                id.tax_amount,
                id.net_total,
                COALESCE(ii.item_count, 0) as item_count,
                COALESCE(ii.total_quantity, 0) as total_quantity,
                id.notes,
                COALESCE(ps.status, jsonb_build_object('status', 'pending', 'paid_date', null, 'payment_ref', null)) as payment_status,
                COALESCE(ii.line_items, '[]'::jsonb) as line_items
            FROM invoice_data id
            LEFT JOIN invoice_items ii ON id.invoice_id = ii.invoice_id
            LEFT JOIN payment_status ps ON id.invoice_id = ps.invoice_id
        ),
        monthly_breakdown AS (
            SELECT
                TO_CHAR(invoice_date, 'YYYY-MM') as month,
                COUNT(*) as invoice_count,
                SUM(total) as total_amount,
                SUM(CASE WHEN (payment_status->>'status') = 'paid' THEN net_total ELSE 0 END) as paid_amount,
                SUM(CASE WHEN (payment_status->>'status') = 'pending' THEN net_total ELSE 0 END) as pending_amount
            FROM invoices_full
            GROUP BY TO_CHAR(invoice_date, 'YYYY-MM')
            ORDER BY month DESC
        )
        SELECT
            jsonb_build_object(
                'total_invoices', (SELECT COUNT(*) FROM invoices_full),
                'total_amount', COALESCE((SELECT SUM(total) FROM invoices_full), 0),
                'total_labour', COALESCE((SELECT SUM(labour) FROM invoices_full), 0),
                'total_tax', COALESCE((SELECT SUM(tax_amount) FROM invoices_full), 0),
                'total_discount', COALESCE((SELECT SUM(discount) FROM invoices_full), 0),
                'net_amount', COALESCE((SELECT SUM(net_total) FROM invoices_full), 0),
                'paid_count', (SELECT COUNT(*) FROM invoices_full WHERE (payment_status->>'status') = 'paid'),
                'pending_count', (SELECT COUNT(*) FROM invoices_full WHERE (payment_status->>'status') = 'pending'),
                'paid_amount', COALESCE((SELECT SUM(net_total) FROM invoices_full WHERE (payment_status->>'status') = 'paid'), 0),
                'pending_amount', COALESCE((SELECT SUM(net_total) FROM invoices_full WHERE (payment_status->>'status') = 'pending'), 0)
            ),
            COALESCE((
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'invoice_id', invoice_id,
                        'invoice_number', invoice_number,
                        'invoice_date', invoice_date,
                        'financial_year', financial_year,
                        'grn_ref', grn_ref,
                        'grn_id', grn_id,
                        'total', total,
                        'labour', labour,
                        'discount', discount,
                        'tax_amount', tax_amount,
                        'net_total', net_total,
                        'item_count', item_count,
                        'total_quantity', total_quantity,
                        'notes', notes,
                        'payment_status', payment_status,
                        'line_items', line_items
                    ) ORDER BY invoice_date DESC, invoice_number DESC
                )
                FROM invoices_full
            ), '[]'::jsonb),
            COALESCE((
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'month', month,
                        'invoice_count', invoice_count,
                        'total_amount', total_amount,
                        'paid_amount', paid_amount,
                        'pending_amount', pending_amount
                    )
                )
                FROM monthly_breakdown
            ), '[]'::jsonb)
        INTO v_summary, v_invoices, v_by_month;

        v_result := jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'summary', v_summary,
                'invoices', v_invoices,
                'by_month', v_by_month
            ),
            'metadata', jsonb_build_object(
                'retrieved_at', NOW(),
                'customer_id', p_customer_uuid,
                'from_date', v_from_date,
                'to_date', v_to_date,
                'financial_year', p_financial_year
            )
        );

    -- All customers view (filtered by accessible customers for non-staff)
    ELSE
        WITH invoice_data AS (
            SELECT
                i.id as invoice_id,
                i.customer_id,
                c.name as customer_name,
                i.inv_date,
                i.total,
                i.labour,
                i.discount,
                i.tax_amount,
                (COALESCE(i.total, 0) + COALESCE(i.labour, 0) + COALESCE(i.tax_amount, 0) - COALESCE(i.discount, 0)) as net_total
            FROM invoice i
            JOIN customers c ON i.customer_id = c.id
            WHERE i.deleted_at IS NULL
                AND (p_financial_year IS NULL OR i.inv_fin_year = p_financial_year)
                AND i.inv_date BETWEEN v_from_date AND v_to_date
                AND (v_user_role IN ('admin', 'supervisor', 'staff') OR i.customer_id = ANY(v_user_customer_ids))
        ),
        customer_aggregates AS (
            SELECT
                customer_id,
                customer_name,
                COUNT(*) as invoice_count,
                SUM(total) as total_amount,
                SUM(net_total) as net_amount,
                MAX(inv_date) as latest_invoice_date
            FROM invoice_data
            GROUP BY customer_id, customer_name
        ),
        monthly_breakdown AS (
            SELECT
                TO_CHAR(inv_date, 'YYYY-MM') as month,
                COUNT(*) as invoice_count,
                SUM(total) as total_amount
            FROM invoice_data
            GROUP BY TO_CHAR(inv_date, 'YYYY-MM')
            ORDER BY month DESC
        )
        SELECT
            jsonb_build_object(
                'total_invoices', (SELECT COUNT(*) FROM invoice_data),
                'total_customers', (SELECT COUNT(DISTINCT customer_id) FROM invoice_data),
                'total_amount', COALESCE((SELECT SUM(total) FROM invoice_data), 0),
                'total_tax', COALESCE((SELECT SUM(tax_amount) FROM invoice_data), 0),
                'net_amount', COALESCE((SELECT SUM(net_total) FROM invoice_data), 0)
            ),
            COALESCE((
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'customer_id', customer_id,
                        'customer_name', customer_name,
                        'invoice_count', invoice_count,
                        'total_amount', total_amount,
                        'net_amount', net_amount,
                        'latest_invoice_date', latest_invoice_date
                    ) ORDER BY total_amount DESC
                )
                FROM customer_aggregates
            ), '[]'::jsonb),
            COALESCE((
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'month', month,
                        'invoice_count', invoice_count,
                        'total_amount', total_amount
                    )
                )
                FROM monthly_breakdown
            ), '[]'::jsonb)
        INTO v_summary, v_by_customer, v_by_month;

        v_result := jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'summary', v_summary,
                'by_customer', v_by_customer,
                'by_month', v_by_month
            ),
            'metadata', jsonb_build_object(
                'retrieved_at', NOW(),
                'from_date', v_from_date,
                'to_date', v_to_date,
                'financial_year', p_financial_year
            )
        );
    END IF;

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Failed to retrieve invoice summary: ' || SQLERRM,
            'error_code', SQLSTATE
        );
END;
$$;


CREATE FUNCTION public.get_customer_invoices(p_customer_id uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_filters jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    DECLARE
        v_result jsonb;
        v_total_amount numeric;
        v_total_tax numeric;
        v_total_discount numeric;
        v_total_labour numeric;
        v_invoice_count integer;
        v_invoices jsonb;
        v_user_role text;
        v_user_customer_ids uuid[];
    BEGIN
        -- Security: Get user role and verify access
        SELECT role INTO v_user_role FROM user_profiles
        WHERE auth_user_id = auth.uid();

        -- If user is not admin/supervisor, check customer access
        IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
            SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
            FROM users_customers_new
            WHERE user_profile_id = (SELECT id FROM user_profiles WHERE auth_user_id = auth.uid());

            -- Verify the requested customer is in their assigned list
            IF v_user_customer_ids IS NULL OR NOT (p_customer_id = ANY(v_user_customer_ids)) THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'data', null,
                    'message', 'Access denied: You do not have permission to access this customer''s data'
                );
            END IF;
        END IF;

        -- Get aggregations (snake_case filter keys)
        SELECT
            COALESCE(SUM(i.total), 0),
            COALESCE(SUM(i.tax_amount), 0),
            COALESCE(SUM(i.discount), 0),
            COALESCE(SUM(i.labour), 0),
            COUNT(*)
        INTO v_total_amount, v_total_tax, v_total_discount, v_total_labour, v_invoice_count
        FROM invoice i
        WHERE i.customer_id = p_customer_id
        AND (p_date_from IS NULL OR p_date_to IS NULL OR i.inv_date BETWEEN p_date_from AND p_date_to)
        AND (NOT p_filters ? 'gr_no' OR p_filters->>'gr_no' = '' OR i.gr_no ILIKE '%' || (p_filters->>'gr_no') || '%')
        AND (NOT p_filters ? 'invoice_no' OR p_filters->>'invoice_no' = '' OR CONCAT(i.inv_fin_year, '-', i.inv_no) ILIKE '%' || (p_filters->>'invoice_no') || '%');

        -- Get main data (snake_case response keys)
        SELECT jsonb_agg(
            jsonb_build_object(
                'id', sub.id,
                'invoice_no', sub.invoice_no,
                'invoice_date', sub.inv_date,
                'amount', sub.total,
                'customer_name', sub.customer_name,
                'grn_id', sub.gr_id,
                'grn_no', sub.gr_no,
                'discount', sub.discount,
                'labour', sub.labour,
                'tax_amount', sub.tax_amount,
                'total', sub.total
            )
        ) INTO v_invoices
        FROM (
            SELECT
                i.id,
                CONCAT(i.inv_fin_year, '-', i.inv_no) as invoice_no,
                i.inv_date,
                i.total,
                i.customer_name,
                i.gr_id,
                i.gr_no,
                i.discount,
                i.labour,
                i.tax_amount
            FROM invoice i
            WHERE i.customer_id = p_customer_id
            AND (p_date_from IS NULL OR p_date_to IS NULL OR i.inv_date BETWEEN p_date_from AND p_date_to)
            AND (NOT p_filters ? 'gr_no' OR p_filters->>'gr_no' = '' OR i.gr_no ILIKE '%' || (p_filters->>'gr_no') || '%')
            AND (NOT p_filters ? 'invoice_no' OR p_filters->>'invoice_no' = '' OR CONCAT(i.inv_fin_year, '-', i.inv_no) ILIKE '%' || (p_filters->>'invoice_no') || '%')
            ORDER BY i.inv_date DESC
        ) sub;

        -- Build final result (snake_case aggregation keys)
        v_result := jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'invoices', COALESCE(v_invoices, '[]'::jsonb),
                'aggregations', jsonb_build_object(
                    'total_amount', v_total_amount,
                    'total_tax', v_total_tax,
                    'total_discount', v_total_discount,
                    'total_labour', v_total_labour,
                    'invoice_count', v_invoice_count
                )
            ),
            'message', 'Customer invoices retrieved successfully'
        );

        RETURN v_result;

    EXCEPTION
        WHEN OTHERS THEN
            RETURN jsonb_build_object(
                'success', false,
                'data', NULL,
                'message', 'Error retrieving customer invoices: ' || SQLERRM
            );
    END;
$$;


CREATE FUNCTION public.get_customer_items_for_order_selection(p_customer_id uuid, p_page_size integer DEFAULT 500, p_offset integer DEFAULT 0, p_search_term text DEFAULT NULL::text, p_stock_filter_min integer DEFAULT 1) RETURNS TABLE(grn_item_id uuid, grn_id uuid, gr_no character varying, item_id uuid, item_name character varying, package_mark character varying, packaging character varying, rack character varying, stock integer, qty integer, weight integer, image_url character varying, customer_id uuid, customer_name character varying, date timestamp with time zone, grns_id uuid, grns_gr_no character varying, grns_date timestamp with time zone, grns_customer_name character varying, grns_customer_id uuid, grns_registration character varying, grns_supervisor_name character varying, grns_sender_name character varying, grns_invoiced boolean, grns_leon boolean, grns_out_of_stock boolean, grns_note character varying, grns_image_url character varying, total_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_user_profile_id UUID;
      v_accessible_customers UUID[];
      v_total_count INTEGER;
  BEGIN
      -- Get user profile ID
      SELECT id INTO v_user_profile_id
      FROM user_profiles
      WHERE auth_user_id = auth.uid();

      IF v_user_profile_id IS NULL THEN
          RETURN;
      END IF;

      -- Check customer access permissions
      IF NOT is_admin_or_supervisor() THEN
          v_accessible_customers := user_accessible_customers();
          IF p_customer_id != ALL(v_accessible_customers) THEN
              RETURN;
          END IF;
      END IF;

      -- Get total count for pagination
      SELECT COUNT(*) INTO v_total_count
      FROM goodsreceived_trl grt
      INNER JOIN goodsreceived gr ON grt.gr_id = gr.id
      WHERE gr.customer_id = p_customer_id
      AND grt.stock >= p_stock_filter_min
      AND (p_search_term IS NULL OR
           grt.item_name ILIKE '%' || p_search_term || '%' OR
           grt.package_mark ILIKE '%' || p_search_term || '%' OR
           grt.packaging ILIKE '%' || p_search_term || '%' OR
           grt.rack ILIKE '%' || p_search_term || '%');

      -- Return paginated results
      RETURN QUERY
      SELECT
          -- GRN Item Core Fields
          grt.id as grn_item_id,
          grt.gr_id as grn_id,
          gr.gr_no,
          grt.item_id,
          grt.item_name,
          grt.package_mark,
          grt.packaging,
          grt.rack,
          grt.stock,
          grt.qty,
          grt.weight,
          grt.trl_img_url as image_url,

          -- Customer fields (from joined goodsreceived)
          gr.customer_id,
          gr.customer_name,

          -- Date field (from joined goodsreceived)
          gr.date,

          -- GRN Header Fields (all from goodsreceived join)
          gr.id as grns_id,
          gr.gr_no as grns_gr_no,
          gr.date as grns_date,
          gr.customer_name as grns_customer_name,
          gr.customer_id as grns_customer_id,
          gr.registration as grns_registration,
          gr.supervisor_name as grns_supervisor_name,
          gr.sender_name as grns_sender_name,
          gr.invoiced as grns_invoiced,
          gr.leon as grns_leon,
          gr.out_of_stock as grns_out_of_stock,
          gr.note as grns_note,
          gr.gr_image_url as grns_image_url,

          -- Pagination
          v_total_count as total_count

      FROM goodsreceived_trl grt
      INNER JOIN goodsreceived gr ON grt.gr_id = gr.id
      WHERE gr.customer_id = p_customer_id
      AND grt.stock >= p_stock_filter_min
      AND (p_search_term IS NULL OR
           grt.item_name ILIKE '%' || p_search_term || '%' OR
           grt.package_mark ILIKE '%' || p_search_term || '%' OR
           grt.packaging ILIKE '%' || p_search_term || '%' OR
           grt.rack ILIKE '%' || p_search_term || '%')
      ORDER BY grt.item_name ASC, grt.weight ASC, gr.date ASC
      LIMIT p_page_size OFFSET p_offset;
  END;
  $$;


CREATE FUNCTION public.get_customer_items_for_order_selection(p_customer_id uuid, p_page_size integer DEFAULT 500, p_offset integer DEFAULT 0, p_search_term text DEFAULT NULL::text, p_stock_filter_min integer DEFAULT 1, p_grn_no_filter character varying DEFAULT NULL::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_items jsonb;
    v_total_count bigint;
BEGIN
    WITH filtered_items AS (
        SELECT
            gt.id as grn_item_id,
            gr.id as grn_id,
            gr.gr_no,
            i.id as item_id,
            i.name as item_name,
            gt.package_mark,
            i.packaging,
            gt.rack,
            gt.stock,
            gt.qty,
            gt.weight,
            (SELECT storage_path FROM grn_images gi WHERE gi.grn_id = gr.id LIMIT 1) as image_url,
            gr.customer_id,
            c.name as customer_name,
            gr.date
        FROM goodsreceived_trl gt
        JOIN goodsreceived gr ON gt.gr_id = gr.id
        JOIN items i ON gt.item_id = i.id
        JOIN customers c ON gr.customer_id = c.id
        WHERE gr.customer_id = p_customer_id
          AND gt.stock >= p_stock_filter_min
          AND gr.deleted_at IS NULL
          AND (p_search_term IS NULL OR i.name ILIKE '%' || p_search_term || '%')
          AND (p_grn_no_filter IS NULL OR gr.gr_no ILIKE '%' || p_grn_no_filter || '%')
        ORDER BY gr.date DESC, i.name
        LIMIT p_page_size OFFSET p_offset
    )
    SELECT COALESCE(jsonb_agg(row_to_json(fi)::jsonb), '[]'::jsonb)
    INTO v_items
    FROM filtered_items fi;

    SELECT COUNT(*) INTO v_total_count
    FROM goodsreceived_trl gt
    JOIN goodsreceived gr ON gt.gr_id = gr.id
    WHERE gr.customer_id = p_customer_id
      AND gt.stock >= p_stock_filter_min
      AND gr.deleted_at IS NULL
      AND (p_search_term IS NULL OR EXISTS(SELECT 1 FROM items i WHERE i.id = gt.item_id AND i.name ILIKE '%' || p_search_term || '%'))
      AND (p_grn_no_filter IS NULL OR gr.gr_no ILIKE '%' || p_grn_no_filter || '%');

    RETURN utils.success_response_paginated(v_items, v_total_count, p_page_size, p_offset);
EXCEPTION
    WHEN OTHERS THEN
        RETURN utils.database_error_response('Failed to get customer items for order', SQLERRM, SQLSTATE);
END;
$$;


CREATE FUNCTION public.get_customer_stock_analysis(p_customer_id uuid, p_date_filter timestamp with time zone DEFAULT NULL::timestamp with time zone, p_item_filter jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result jsonb;
    v_total_grn_qty bigint;
    v_total_dispatch_qty bigint;
    v_total_calculated_stock bigint;
    v_item_count integer;
    v_items jsonb;
    v_user_role text;
    v_user_customer_ids uuid[];
    v_items_with_negative_stock integer;
BEGIN
    -- Security: Get user role and verify access
    SELECT role INTO v_user_role FROM user_profiles
    WHERE auth_user_id = auth.uid();

    -- If user is not admin/supervisor, check customer access
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
        FROM users_customers_new
        WHERE user_profile_id = (SELECT id FROM user_profiles WHERE auth_user_id = auth.uid());

        -- Verify the requested customer is in their assigned list
        IF v_user_customer_ids IS NULL OR NOT (p_customer_id = ANY(v_user_customer_ids)) THEN
            RETURN jsonb_build_object(
                'success', false,
                'data', null,
                'message', 'Access denied: You do not have permission to access this customer''s data'
            );
        END IF;
    END IF;

    -- Time-traveling inventory calculation
    WITH grn_data AS (
        -- Sum all GRN quantities up to the specified date
        SELECT
            grt.item_id,
            SUM(grt.qty) as total_grn_qty
        FROM goodsreceived_trl grt
        JOIN goodsreceived gr ON grt.gr_id = gr.id
        WHERE gr.customer_id = p_customer_id
        AND (p_date_filter IS NULL OR gr.date <= p_date_filter)
        GROUP BY grt.item_id
    ),
    dispatch_data AS (
        -- Sum all dispatch quantities up to the specified date
        -- CRITICAL: Use dispatch date, not GRN date
        SELECT
            grt.item_id,
            SUM(dt.disp_qty) as total_dispatch_qty
        FROM dispatch_trl dt
        JOIN goodsreceived_trl grt ON dt.gr_trl_id = grt.id
        JOIN dispatch d ON dt.disp_id = d.id
        JOIN goodsreceived gr ON grt.gr_id = gr.id
        WHERE gr.customer_id = p_customer_id
        AND (p_date_filter IS NULL OR d.disp_date <= p_date_filter)
        GROUP BY grt.item_id
    ),
    stock_calculation AS (
        -- Calculate stock as GRN minus Dispatch for each item
        SELECT
            i.id as item_id,
            i.name as item_name,
            i.packaging,
            i.description,
            COALESCE(grn.total_grn_qty, 0) as grn_qty,
            COALESCE(disp.total_dispatch_qty, 0) as dispatch_qty,
            COALESCE(grn.total_grn_qty, 0) - COALESCE(disp.total_dispatch_qty, 0) as calculated_stock
        FROM items i
        LEFT JOIN grn_data grn ON i.id = grn.item_id
        LEFT JOIN dispatch_data disp ON i.id = disp.item_id
        WHERE i.active = true
        AND (grn.item_id IS NOT NULL OR disp.item_id IS NOT NULL)
        AND (NOT p_item_filter ? 'item_name' OR p_item_filter->>'item_name' = ''
             OR i.name ILIKE '%' || (p_item_filter->>'item_name') || '%')
        AND (NOT p_item_filter ? 'item_id' OR p_item_filter->>'item_id' = ''
             OR i.id = (p_item_filter->>'item_id')::uuid)
    )
    -- Final aggregation and result building
    SELECT
        jsonb_agg(
            jsonb_build_object(
                'item_id', sc.item_id,
                'item_name', sc.item_name,
                'packaging', sc.packaging,
                'description', sc.description,
                'total_grn_qty', sc.grn_qty,
                'total_dispatch_qty', sc.dispatch_qty,
                'calculated_stock', sc.calculated_stock,
                'has_negative_stock', sc.calculated_stock < 0,
                -- Include date context in response
                'as_of_date', COALESCE(p_date_filter, NOW())
            ) ORDER BY sc.item_name
        ),
        COALESCE(SUM(sc.grn_qty), 0),
        COALESCE(SUM(sc.dispatch_qty), 0),
        COALESCE(SUM(sc.calculated_stock), 0),
        COUNT(*),
        COUNT(*) FILTER (WHERE sc.calculated_stock < 0)
    INTO v_items, v_total_grn_qty, v_total_dispatch_qty, v_total_calculated_stock, v_item_count, v_items_with_negative_stock
    FROM stock_calculation sc;

    -- Build final result
    v_result := jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'items', COALESCE(v_items, '[]'::jsonb),
            'aggregations', jsonb_build_object(
                'total_grn_qty', v_total_grn_qty,
                'total_dispatch_qty', v_total_dispatch_qty,
                'calculated_stock', v_total_calculated_stock,
                'item_count', v_item_count,
                'items_with_negative_stock', v_items_with_negative_stock,
                'as_of_date', COALESCE(p_date_filter, NOW()),
                'has_data_integrity_issues', v_items_with_negative_stock > 0
            )
        ),
        'message', CASE
            WHEN p_date_filter IS NOT NULL THEN
                'Historical stock analysis as of ' || to_char(p_date_filter, 'YYYY-MM-DD') || ' retrieved successfully'
            ELSE
                'Current stock analysis retrieved successfully'
        END
    );

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', NULL,
            'message', 'Error retrieving customer stock analysis: ' || SQLERRM
        );
END;
$$;


CREATE FUNCTION public.get_customer_stock_analysis(p_customer_id uuid, p_date_filter timestamp with time zone DEFAULT NULL::timestamp with time zone, p_item_filter jsonb DEFAULT '{}'::jsonb, p_in_stock_only boolean DEFAULT NULL::boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result jsonb;
    v_total_grn_qty bigint;
    v_total_dispatch_qty bigint;
    v_total_calculated_stock bigint;
    v_item_count integer;
    v_items jsonb;
    v_user_role text;
    v_user_customer_ids uuid[];
    v_items_with_negative_stock integer;
BEGIN
    -- Security: Get user role and verify access
    SELECT role INTO v_user_role FROM user_profiles
    WHERE auth_user_id = auth.uid();

    -- If user is not admin/supervisor, check customer access
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
        FROM users_customers_new
        WHERE user_profile_id = (SELECT id FROM user_profiles WHERE auth_user_id = auth.uid());

        -- Verify the requested customer is in their assigned list
        IF v_user_customer_ids IS NULL OR NOT (p_customer_id = ANY(v_user_customer_ids)) THEN
            RETURN jsonb_build_object(
                'success', false,
                'data', null,
                'message', 'Access denied: You do not have permission to access this customer''s data'
            );
        END IF;
    END IF;

    -- Time-traveling inventory calculation
    WITH grn_data AS (
        -- Sum all GRN quantities up to the specified date
        SELECT
            grt.item_id,
            SUM(grt.qty) as total_grn_qty
        FROM goodsreceived_trl grt
        JOIN goodsreceived gr ON grt.gr_id = gr.id
        WHERE gr.customer_id = p_customer_id
        AND (p_date_filter IS NULL OR gr.date <= p_date_filter)
        GROUP BY grt.item_id
    ),
    dispatch_data AS (
        -- Sum all dispatch quantities up to the specified date
        -- CRITICAL: Use dispatch date, not GRN date
        SELECT
            grt.item_id,
            SUM(dt.disp_qty) as total_dispatch_qty
        FROM dispatch_trl dt
        JOIN goodsreceived_trl grt ON dt.gr_trl_id = grt.id
        JOIN dispatch d ON dt.disp_id = d.id
        JOIN goodsreceived gr ON grt.gr_id = gr.id
        WHERE gr.customer_id = p_customer_id
        AND (p_date_filter IS NULL OR d.disp_date <= p_date_filter)
        GROUP BY grt.item_id
    ),
    stock_calculation AS (
        -- Calculate stock as GRN minus Dispatch for each item
        SELECT
            i.id as item_id,
            i.name as item_name,
            i.packaging,
            i.description,
            COALESCE(grn.total_grn_qty, 0) as grn_qty,
            COALESCE(disp.total_dispatch_qty, 0) as dispatch_qty,
            COALESCE(grn.total_grn_qty, 0) - COALESCE(disp.total_dispatch_qty, 0) as calculated_stock
        FROM items i
        LEFT JOIN grn_data grn ON i.id = grn.item_id
        LEFT JOIN dispatch_data disp ON i.id = disp.item_id
        WHERE i.active = true
        AND (grn.item_id IS NOT NULL OR disp.item_id IS NOT NULL)
        AND (NOT p_item_filter ? 'item_name' OR p_item_filter->>'item_name' = ''
             OR i.name ILIKE '%' || (p_item_filter->>'item_name') || '%')
        AND (NOT p_item_filter ? 'item_id' OR p_item_filter->>'item_id' = ''
             OR i.id = (p_item_filter->>'item_id')::uuid)
        -- NEW: In-stock filter
        AND (p_in_stock_only IS NULL OR
             (p_in_stock_only = true AND
              COALESCE(grn.total_grn_qty, 0) - COALESCE(disp.total_dispatch_qty, 0) > 0) OR
             (p_in_stock_only = false))
    )
    -- Final aggregation and result building
    SELECT
        jsonb_agg(
            jsonb_build_object(
                'item_id', sc.item_id,
                'item_name', sc.item_name,
                'packaging', sc.packaging,
                'description', sc.description,
                'total_grn_qty', sc.grn_qty,
                'total_dispatch_qty', sc.dispatch_qty,
                'calculated_stock', sc.calculated_stock,
                'has_negative_stock', sc.calculated_stock < 0,
                -- Include date context in response
                'as_of_date', COALESCE(p_date_filter, NOW())
            ) ORDER BY sc.item_name
        ),
        COALESCE(SUM(sc.grn_qty), 0),
        COALESCE(SUM(sc.dispatch_qty), 0),
        COALESCE(SUM(sc.calculated_stock), 0),
        COUNT(*),
        COUNT(*) FILTER (WHERE sc.calculated_stock < 0)
    INTO v_items, v_total_grn_qty, v_total_dispatch_qty, v_total_calculated_stock, v_item_count, v_items_with_negative_stock
    FROM stock_calculation sc;

    -- Build final result
    v_result := jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'items', COALESCE(v_items, '[]'::jsonb),
            'aggregations', jsonb_build_object(
                'total_grn_qty', v_total_grn_qty,
                'total_dispatch_qty', v_total_dispatch_qty,
                'calculated_stock', v_total_calculated_stock,
                'item_count', v_item_count,
                'items_with_negative_stock', v_items_with_negative_stock,
                'as_of_date', COALESCE(p_date_filter, NOW()),
                'has_data_integrity_issues', v_items_with_negative_stock > 0
            )
        ),
        'message', CASE
            WHEN p_date_filter IS NOT NULL THEN
                'Historical stock analysis as of ' || to_char(p_date_filter, 'YYYY-MM-DD') || ' retrieved successfully'
            ELSE
                'Current stock analysis retrieved successfully'
        END
    );

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', NULL,
            'message', 'Error retrieving customer stock analysis: ' || SQLERRM
        );
END;
$$;


CREATE FUNCTION public.get_customer_stock_analysis_v2(p_customer_id uuid, p_date_filter timestamp with time zone DEFAULT NULL::timestamp with time zone, p_item_filter jsonb DEFAULT '{}'::jsonb, p_in_stock_only boolean DEFAULT NULL::boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result jsonb;
    v_total_grn_qty bigint;
    v_total_dispatch_qty bigint;
    v_total_calculated_stock bigint;
    v_item_count integer;
    v_items jsonb;
    v_user_role text;
    v_user_customer_ids uuid[];
    v_items_with_negative_stock integer;
BEGIN
    -- Security: Get user role and verify access
    SELECT role INTO v_user_role FROM user_profiles
    WHERE auth_user_id = auth.uid();

    -- If user is not admin/supervisor, check customer access
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
        FROM users_customers_new
        WHERE user_profile_id = (SELECT id FROM user_profiles WHERE auth_user_id = auth.uid());

        -- Verify the requested customer is in their assigned list
        IF v_user_customer_ids IS NULL OR NOT (p_customer_id = ANY(v_user_customer_ids)) THEN
            RETURN jsonb_build_object(
                'success', false,
                'data', null,
                'message', 'Access denied: You do not have permission to access this customer''s data'
            );
        END IF;
    END IF;

    -- NEW LOGIC: GRN receipt-level filtering
    -- Step 1: Identify GRN items with remaining stock
    WITH grn_items_with_stock AS (
        SELECT
            grt.id as gr_trl_id,
            grt.item_id,
            grt.qty as grn_qty,
            grt.stock as remaining_stock,
            gr.date as grn_date
        FROM goodsreceived_trl grt
        JOIN goodsreceived gr ON grt.gr_id = gr.id
        WHERE gr.customer_id = p_customer_id
        AND (p_date_filter IS NULL OR gr.date <= p_date_filter)
        AND grt.stock > 0  -- KEY: Only GRN items with remaining stock
    ),
    -- Step 2: Aggregate GRN quantities ONLY from items with stock
    grn_data AS (
        SELECT
            item_id,
            SUM(grn_qty) as total_grn_qty,
            SUM(remaining_stock) as total_remaining_stock
        FROM grn_items_with_stock
        GROUP BY item_id
    ),
    -- Step 3: Calculate dispatches ONLY from those GRN items
    dispatch_data AS (
        SELECT
            gws.item_id,
            SUM(dt.disp_qty) as total_dispatch_qty
        FROM dispatch_trl dt
        JOIN grn_items_with_stock gws ON dt.gr_trl_id = gws.gr_trl_id
        JOIN dispatch d ON dt.disp_id = d.id
        WHERE (p_date_filter IS NULL OR d.disp_date <= p_date_filter)
        GROUP BY gws.item_id
    ),
    -- Step 4: Calculate stock based on filtered data
    stock_calculation AS (
        SELECT
            i.id as item_id,
            i.name as item_name,
            i.packaging,
            i.description,
            COALESCE(grn.total_grn_qty, 0) as grn_qty,
            COALESCE(disp.total_dispatch_qty, 0) as dispatch_qty,
            -- Use the pre-calculated stock from goodsreceived_trl for accuracy
            COALESCE(grn.total_remaining_stock, 0) as calculated_stock
        FROM items i
        INNER JOIN grn_data grn ON i.id = grn.item_id  -- INNER JOIN since we only want items with stock
        LEFT JOIN dispatch_data disp ON i.id = disp.item_id
        WHERE i.active = true
        AND (NOT p_item_filter ? 'item_name' OR p_item_filter->>'item_name' = ''
             OR i.name ILIKE '%' || (p_item_filter->>'item_name') || '%')
        AND (NOT p_item_filter ? 'item_id' OR p_item_filter->>'item_id' = ''
             OR i.id = (p_item_filter->>'item_id')::uuid)
        -- Apply in_stock_only filter
        AND (p_in_stock_only IS NULL OR
             (p_in_stock_only = true AND COALESCE(grn.total_remaining_stock, 0) > 0) OR
             (p_in_stock_only = false))
    )
    -- Final aggregation and result building
    SELECT
        jsonb_agg(
            jsonb_build_object(
                'item_id', sc.item_id,
                'item_name', sc.item_name,
                'packaging', sc.packaging,
                'description', sc.description,
                'total_grn_qty', sc.grn_qty,
                'total_dispatch_qty', sc.dispatch_qty,
                'calculated_stock', sc.calculated_stock,
                'has_negative_stock', sc.calculated_stock < 0,
                'as_of_date', COALESCE(p_date_filter, NOW())
            ) ORDER BY sc.item_name
        ),
        COALESCE(SUM(sc.grn_qty), 0),
        COALESCE(SUM(sc.dispatch_qty), 0),
        COALESCE(SUM(sc.calculated_stock), 0),
        COUNT(*),
        COUNT(*) FILTER (WHERE sc.calculated_stock < 0)
    INTO v_items, v_total_grn_qty, v_total_dispatch_qty, v_total_calculated_stock, v_item_count, v_items_with_negative_stock
    FROM stock_calculation sc;

    -- Build final result
    v_result := jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'items', COALESCE(v_items, '[]'::jsonb),
            'aggregations', jsonb_build_object(
                'total_grn_qty', v_total_grn_qty,
                'total_dispatch_qty', v_total_dispatch_qty,
                'calculated_stock', v_total_calculated_stock,
                'item_count', v_item_count,
                'items_with_negative_stock', v_items_with_negative_stock,
                'as_of_date', COALESCE(p_date_filter, NOW()),
                'has_data_integrity_issues', v_items_with_negative_stock > 0,
                'version', 'v2_grn_level_filtering'  -- Version identifier
            )
        ),
        'message', CASE
            WHEN p_date_filter IS NOT NULL THEN
                'Historical stock analysis (v2 - GRN-level) as of ' || to_char(p_date_filter, 'YYYY-MM-DD') || ' retrieved successfully'
            ELSE
                'Current stock analysis (v2 - GRN-level) retrieved successfully'
        END
    );

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', NULL,
            'message', 'Error retrieving customer stock analysis v2: ' || SQLERRM
        );
END;
$$;


CREATE FUNCTION public.get_customer_stock_movements(p_customer_id uuid, p_date_from timestamp with time zone, p_date_to timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    BEGIN
        RETURN jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'customer_id', p_customer_id,
                'period', jsonb_build_object(
                    'from', p_date_from,
                    'to', p_date_to
                ),
                'movements', (
                    SELECT jsonb_build_object(
                        'receipts', COALESCE(SUM(CASE WHEN t.type = 'GRN' THEN t.qty ELSE 0 END), 0),
                        'issues', COALESCE(SUM(CASE WHEN t.type = 'DISPATCH' THEN t.qty ELSE 0 END), 0),
                        'net_movement', COALESCE(SUM(CASE
                            WHEN t.type = 'GRN' THEN t.qty
                            ELSE -t.qty
                        END), 0)
                    )
                    FROM (
                        SELECT 'GRN' as type, SUM(grt.qty) as qty
                        FROM goodsreceived gr
                        JOIN goodsreceived_trl grt ON gr.id = grt.gr_id
                        WHERE gr.customer_id = p_customer_id
                        AND gr.date BETWEEN p_date_from AND p_date_to

                        UNION ALL

                        SELECT 'DISPATCH' as type, SUM(dt.disp_qty) as qty
                        FROM dispatch d
                        JOIN dispatch_trl dt ON d.id = dt.disp_id
                        JOIN goodsreceived_trl grt ON dt.gr_trl_id = grt.id
                        JOIN goodsreceived gr ON grt.gr_id = gr.id
                        WHERE gr.customer_id = p_customer_id
                        AND d.disp_date BETWEEN p_date_from AND p_date_to
                    ) t
                )
            )
        );
    END;
    $$;


CREATE FUNCTION public.get_customer_stock_summary(p_customer_uuid uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result JSONB;
    v_user_role TEXT;
BEGIN
    -- Get user role from JWT claims
    v_user_role := COALESCE(
        (current_setting('request.jwt.claims', true)::jsonb ->> 'user_role'),
        (current_setting('request.jwt.claims', true)::jsonb -> 'user_metadata' ->> 'role')
    );

    -- Check access: admin/supervisor can access all, others only assigned customers
    IF v_user_role NOT IN ('admin', 'supervisor', 'service_role') THEN
        IF NOT EXISTS (
            SELECT 1 FROM unnest(user_accessible_customers()) AS uc(id)
            WHERE uc.id = p_customer_uuid
        ) THEN
            RETURN jsonb_build_object(
                'error', 'Access denied: customer not accessible',
                'summary', NULL,
                'items', '[]'::jsonb,
                'out_of_stock_items', '[]'::jsonb
            );
        END IF;
    END IF;

    SELECT jsonb_build_object(
        'summary', (
            SELECT jsonb_build_object(
                'total_items', COUNT(DISTINCT gt.item_id),
                'total_quantity', COALESCE(SUM(gt.stock), 0),
                'total_weight_kg', COALESCE(SUM(gt.weight::numeric * gt.stock), 0),
                'oldest_stock_date', MIN(g.date)::date,
                'grn_count', COUNT(DISTINCT g.id),
                'grn_count_empty', (
                    SELECT COUNT(DISTINCT g2.id)
                    FROM goodsreceived g2
                    WHERE g2.customer_id = p_customer_uuid
                      AND g2.deleted_at IS NULL
                      AND NOT EXISTS (
                          SELECT 1 FROM goodsreceived_trl gt2
                          WHERE gt2.gr_id = g2.id AND gt2.stock > 0
                      )
                ),
                -- Last GRN entry date and number
                'last_grn_date', (
                    SELECT MAX(g3.date)::date
                    FROM goodsreceived g3
                    WHERE g3.customer_id = p_customer_uuid
                      AND g3.deleted_at IS NULL
                ),
                'last_grn_no', (
                    SELECT g3.gr_no
                    FROM goodsreceived g3
                    WHERE g3.customer_id = p_customer_uuid
                      AND g3.deleted_at IS NULL
                    ORDER BY g3.date DESC, g3.created_at DESC
                    LIMIT 1
                ),
                -- Last Dispatch entry date and number
                'last_dispatch_date', (
                    SELECT MAX(d.disp_date)::date
                    FROM dispatch d
                    WHERE d.customer_id = p_customer_uuid
                      AND d.deleted_at IS NULL
                ),
                'last_dispatch_no', (
                    SELECT d.disp_no
                    FROM dispatch d
                    WHERE d.customer_id = p_customer_uuid
                      AND d.deleted_at IS NULL
                    ORDER BY d.disp_date DESC, d.created_at DESC
                    LIMIT 1
                )
            )
            FROM goodsreceived g
            JOIN goodsreceived_trl gt ON gt.gr_id = g.id
            WHERE g.customer_id = p_customer_uuid
              AND g.deleted_at IS NULL
              AND gt.stock > 0
        ),
        -- Group by item_id and item_name ONLY (not packaging) to avoid duplicates
        'items', COALESCE((
            SELECT jsonb_agg(item_data ORDER BY item_data->>'item_name')
            FROM (
                SELECT jsonb_build_object(
                    'item_id', gt.item_id,
                    'item_name', gt.item_name,
                    'packaging', NULL,  -- Will show individual packaging in GRN details
                    'total_stock', SUM(gt.stock),
                    'total_weight', SUM(gt.weight::numeric * gt.stock),
                    'grn_count', COUNT(DISTINCT g.id),
                    'grns', (
                        SELECT jsonb_agg(
                            jsonb_build_object(
                                'grn_id', g2.id,
                                'gr_no', g2.gr_no,
                                'date', g2.date::date,
                                'orig_qty', gt2.qty,
                                'stock', gt2.stock,
                                'item_weight', gt2.weight,
                                'rack', gt2.rack,
                                'packaging', gt2.packaging,
                                'package_mark', gt2.package_mark
                            ) ORDER BY g2.date DESC
                        )
                        FROM goodsreceived g2
                        JOIN goodsreceived_trl gt2 ON gt2.gr_id = g2.id
                        WHERE g2.customer_id = p_customer_uuid
                          AND g2.deleted_at IS NULL
                          AND gt2.item_id = gt.item_id
                          AND gt2.stock > 0
                    )
                ) AS item_data
                FROM goodsreceived g
                JOIN goodsreceived_trl gt ON gt.gr_id = g.id
                WHERE g.customer_id = p_customer_uuid
                  AND g.deleted_at IS NULL
                  AND gt.stock > 0
                GROUP BY gt.item_id, gt.item_name  -- Removed packaging from GROUP BY
            ) AS items_agg
        ), '[]'::jsonb),
        -- out_of_stock_items - items where stock = 0, emptied within last 360 days
        'out_of_stock_items', COALESCE((
            SELECT jsonb_agg(item_data ORDER BY item_data->>'item_name')
            FROM (
                SELECT jsonb_build_object(
                    'item_id', gt.item_id,
                    'item_name', gt.item_name,
                    'packaging', NULL,
                    'grn_count', COUNT(DISTINCT g.id),
                    'grns', (
                        SELECT jsonb_agg(
                            jsonb_build_object(
                                'grn_id', g2.id,
                                'gr_no', g2.gr_no,
                                'date', g2.date::date,
                                'orig_qty', gt2.qty,
                                'stock', gt2.stock,
                                'item_weight', gt2.weight,
                                'rack', gt2.rack,
                                'packaging', gt2.packaging,
                                'package_mark', gt2.package_mark,
                                'emptied_date', (
                                    SELECT MAX(sm.created_at)::date
                                    FROM stock_movements sm
                                    WHERE sm.gr_trl_id = gt2.id
                                      AND sm.balance_after = 0
                                )
                            ) ORDER BY (
                                SELECT MAX(sm.created_at)
                                FROM stock_movements sm
                                WHERE sm.gr_trl_id = gt2.id
                                  AND sm.balance_after = 0
                            ) DESC NULLS LAST
                        )
                        FROM goodsreceived g2
                        JOIN goodsreceived_trl gt2 ON gt2.gr_id = g2.id
                        WHERE g2.customer_id = p_customer_uuid
                          AND g2.deleted_at IS NULL
                          AND gt2.item_id = gt.item_id
                          AND gt2.stock = 0
                          AND gt2.qty > 0
                          -- 360-day filter via stock_movements
                          AND EXISTS (
                              SELECT 1 FROM stock_movements sm
                              WHERE sm.gr_trl_id = gt2.id
                                AND sm.balance_after = 0
                                AND sm.created_at >= NOW() - INTERVAL '360 days'
                          )
                    )
                ) AS item_data
                FROM goodsreceived g
                JOIN goodsreceived_trl gt ON gt.gr_id = g.id
                WHERE g.customer_id = p_customer_uuid
                  AND g.deleted_at IS NULL
                  AND gt.stock = 0
                  AND gt.qty > 0
                  -- 360-day filter
                  AND EXISTS (
                      SELECT 1 FROM stock_movements sm
                      WHERE sm.gr_trl_id = gt.id
                        AND sm.balance_after = 0
                        AND sm.created_at >= NOW() - INTERVAL '360 days'
                  )
                GROUP BY gt.item_id, gt.item_name  -- Removed packaging from GROUP BY
            ) AS items_agg
        ), '[]'::jsonb)
    ) INTO v_result;

    RETURN v_result;
END;
$$;


CREATE FUNCTION public.get_customer_with_priority_contact(p_customer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_customer RECORD;
    v_priority_contact text;
    v_contact_source text;
BEGIN
    SELECT * INTO v_customer FROM customers WHERE id = p_customer_id;

    IF v_customer IS NULL THEN
        RETURN utils.not_found_response('Customer', p_customer_id::text);
    END IF;

    -- Determine priority contact (contact_mobile > telephone1 > telephone2 > mobile)
    IF v_customer.contact_mobile IS NOT NULL AND v_customer.contact_mobile != '' THEN
        v_priority_contact := v_customer.contact_mobile;
        v_contact_source := 'contact_mobile';
    ELSIF v_customer.telephone1 IS NOT NULL AND v_customer.telephone1 != '' THEN
        v_priority_contact := v_customer.telephone1;
        v_contact_source := 'telephone1';
    ELSIF v_customer.telephone2 IS NOT NULL AND v_customer.telephone2 != '' THEN
        v_priority_contact := v_customer.telephone2;
        v_contact_source := 'telephone2';
    ELSE
        v_priority_contact := v_customer.mobile;
        v_contact_source := 'mobile';
    END IF;

    RETURN utils.success_response(
        jsonb_build_object(
            'id', v_customer.id,
            'name', v_customer.name,
            'mobile', v_customer.mobile,
            'telephone1', v_customer.telephone1,
            'telephone2', v_customer.telephone2,
            'email', v_customer.email,
            'stored_contact', v_customer.contact_mobile,
            'priority_contact', v_priority_contact,
            'contact_source', v_contact_source
        )
    );
END;
$$;


CREATE FUNCTION public.get_customers_with_stock(p_search_query text DEFAULT NULL::text, p_as_of_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_financial_year integer DEFAULT NULL::integer, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_as_of_date TIMESTAMP WITH TIME ZONE;
      v_fy_start_date TIMESTAMP WITH TIME ZONE;
      v_fy_end_date TIMESTAMP WITH TIME ZONE;
      v_total_count INTEGER;
      v_result JSONB;
      v_customers JSONB;
  BEGIN
      -- Set default as_of_date to current timestamp
      v_as_of_date := COALESCE(p_as_of_date, NOW());

      -- Handle financial year filtering
      IF p_financial_year IS NOT NULL THEN
          SELECT start_date, end_date
          INTO v_fy_start_date, v_fy_end_date
          FROM get_financial_year_dates(p_financial_year);

          -- If as_of_date is beyond FY end, cap it at FY end
          IF v_as_of_date > v_fy_end_date THEN
              v_as_of_date := v_fy_end_date;
          END IF;
      END IF;

      -- Get total count and customers in one query
      WITH accessible_customers AS (
          SELECT unnest(user_accessible_customers()) as customer_id
      ),
      customer_stock AS (
          SELECT
              c.id,
              c.name,
              c.mobile,
              c.email,
              c.address,
              c.active,

              -- Calculate total GRN quantity up to as_of_date
              COALESCE(SUM(
                  CASE
                      WHEN gr.date <= v_as_of_date
                           AND (p_financial_year IS NULL OR gr.date >= v_fy_start_date)
                      THEN grt.qty
                      ELSE 0
                  END
              ), 0) as total_grn_qty,

              -- Calculate total dispatch quantity up to as_of_date
              COALESCE(SUM(
                  CASE
                      WHEN d.disp_date <= v_as_of_date
                           AND (p_financial_year IS NULL OR d.disp_date >= v_fy_start_date)
                      THEN dt.disp_qty
                      ELSE 0
                  END
              ), 0) as total_dispatch_qty,

              -- Current stock position = Total GRN - Total Dispatch
              COALESCE(SUM(
                  CASE
                      WHEN gr.date <= v_as_of_date
                           AND (p_financial_year IS NULL OR gr.date >= v_fy_start_date)
                      THEN grt.qty
                      ELSE 0
                  END
              ), 0) - COALESCE(SUM(
                  CASE
                      WHEN d.disp_date <= v_as_of_date
                           AND (p_financial_year IS NULL OR d.disp_date >= v_fy_start_date)
                      THEN dt.disp_qty
                      ELSE 0
                  END
              ), 0) as current_stock_qty,

              -- Count of unique items
              COUNT(DISTINCT
                  CASE
                      WHEN gr.date <= v_as_of_date
                           AND (p_financial_year IS NULL OR gr.date >= v_fy_start_date)
                      THEN grt.item_id
                  END
              ) as unique_items_count,

              -- Latest GRN date
              MAX(
                  CASE
                      WHEN gr.date <= v_as_of_date
                           AND (p_financial_year IS NULL OR gr.date >= v_fy_start_date)
                      THEN gr.date
                  END
              ) as latest_grn_date,

              -- Latest dispatch date
              MAX(
                  CASE
                      WHEN d.disp_date <= v_as_of_date
                           AND (p_financial_year IS NULL OR d.disp_date >= v_fy_start_date)
                      THEN d.disp_date
                  END
              ) as latest_dispatch_date

          FROM accessible_customers ac
          JOIN customers c ON c.id = ac.customer_id
          LEFT JOIN goodsreceived gr ON gr.customer_id = c.id
          LEFT JOIN goodsreceived_trl grt ON grt.gr_id = gr.id
          LEFT JOIN dispatch d ON d.customer_id = c.id
          LEFT JOIN dispatch_trl dt ON dt.disp_id = d.id

          WHERE c.active = true
          GROUP BY c.id, c.name, c.mobile, c.email, c.address, c.active
      ),
      filtered_customers AS (
          SELECT *
          FROM customer_stock cs
          WHERE
              -- Apply search filter if provided
              (p_search_query IS NULL OR (
                  cs.name ILIKE '%' || p_search_query || '%' OR
                  cs.mobile ILIKE '%' || p_search_query || '%' OR
                  cs.email ILIKE '%' || p_search_query || '%'
              ))
              -- Only show customers with stock activity
              AND (cs.total_grn_qty > 0 OR cs.total_dispatch_qty > 0)
          ORDER BY cs.current_stock_qty DESC, cs.name
      ),
      paginated_customers AS (
          SELECT *, COUNT(*) OVER() as total_count
          FROM filtered_customers
          LIMIT p_limit OFFSET p_offset
      )
      SELECT
          jsonb_agg(
              jsonb_build_object(
                  'customer_id', pc.id,
                  'customer_name', pc.name,
                  'mobile', pc.mobile,
                  'email', pc.email,
                  'address', pc.address,
                  'current_stock_qty', pc.current_stock_qty,
                  'total_grn_qty', pc.total_grn_qty,
                  'total_dispatch_qty', pc.total_dispatch_qty,
                  'unique_items_count', pc.unique_items_count,
                  'latest_grn_date', pc.latest_grn_date,
                  'latest_dispatch_date', pc.latest_dispatch_date
              )
          ),
          COALESCE(MAX(pc.total_count), 0)
      INTO v_customers, v_total_count
      FROM paginated_customers pc;

      -- Build final result
      v_result := jsonb_build_object(
          'success', true,
          'customers', COALESCE(v_customers, '[]'::jsonb),
          'pagination', jsonb_build_object(
              'total_count', v_total_count,
              'limit', p_limit,
              'offset', p_offset,
              'has_more', (p_offset + p_limit) < v_total_count
          ),
          'metadata', jsonb_build_object(
              'as_of_date', v_as_of_date,
              'financial_year', p_financial_year,
              'calculation_method', 'position_based',
              'description', 'Stock calculated as cumulative position: Total GRNs - Total Dispatches up to as_of_date'
          )
      );

      RETURN v_result;

  EXCEPTION WHEN OTHERS THEN
      RETURN jsonb_build_object(
          'success', false,
          'error', SQLERRM,
          'error_code', SQLSTATE
      );
  END;
  $$;


CREATE FUNCTION public.get_dispatch_autocomplete(p_search_query text, p_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_result jsonb;
      v_user_role text;
      v_user_customer_ids uuid[];
      v_search_pattern text;
      v_dispatches jsonb;
      v_customers jsonb;
      v_items jsonb;
  BEGIN
      -- Security: Get user role and accessible customers
      SELECT role INTO v_user_role FROM user_profiles
      WHERE auth_user_id = auth.uid();

      -- If user is not admin/supervisor, get their assigned customers
      IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
          v_user_customer_ids := user_accessible_customers();

          -- If no accessible customers, return empty result
          IF v_user_customer_ids IS NULL OR array_length(v_user_customer_ids, 1) IS NULL THEN
              RETURN jsonb_build_object(
                  'success', false,
                  'data', null,
                  'message', 'Access denied: No accessible customers found'
              );
          END IF;
      END IF;

      -- Validate minimum query length
      IF LENGTH(TRIM(p_search_query)) < 2 THEN
          RETURN jsonb_build_object(
              'success', false,
              'data', null,
              'message', 'Search query must be at least 2 characters'
          );
      END IF;

      -- Prepare search pattern (case-insensitive)
      v_search_pattern := '%' || LOWER(TRIM(p_search_query)) || '%';

      -- Validate limit
      IF p_limit < 1 OR p_limit > 50 THEN
          p_limit := 10;
      END IF;

      -- Get matching dispatches (ordered by date, recent first)
      SELECT jsonb_agg(
          jsonb_build_object(
              'value', LOWER(dispatch_data.disp_no),
              'label', dispatch_data.disp_no,
              'type', 'dispatch',
              'count', 1,
              'metadata', jsonb_build_object(
                  'dispatch_id', dispatch_data.id,
                  'disp_no', dispatch_data.disp_no,
                  'disp_date', dispatch_data.disp_date,
                  'customer_name', dispatch_data.customer_name,
                  'supervisor_name', dispatch_data.supervisor_name,
                  'total_items', dispatch_data.total_items,
                  'total_qty', dispatch_data.total_qty,
                  'registration', dispatch_data.registration
              )
          )
          ORDER BY dispatch_data.disp_date DESC
      ) INTO v_dispatches
      FROM (
          SELECT DISTINCT
              d.id,
              d.disp_no,
              d.disp_date,
              d.customer_name,
              d.supervisor_name,
              d.registration,
              COUNT(DISTINCT dt.gr_trl_id) as total_items,
              COALESCE(SUM(dt.disp_qty), 0) as total_qty
          FROM dispatch d
          LEFT JOIN dispatch_trl dt ON d.id = dt.disp_id
          WHERE LOWER(d.disp_no) LIKE v_search_pattern
          AND (v_user_role IN ('admin', 'supervisor', 'staff') OR d.customer_id = ANY(v_user_customer_ids))
          GROUP BY d.id, d.disp_no, d.disp_date, d.customer_name, d.supervisor_name, d.registration
          ORDER BY d.disp_date DESC
          LIMIT p_limit
      ) dispatch_data;

      -- Get matching customers (ordered by last dispatch date)
      SELECT jsonb_agg(
          jsonb_build_object(
              'value', LOWER(REGEXP_REPLACE(customer_data.customer_name, '[^a-zA-Z0-9]+', '-', 'g')),
              'label', customer_data.customer_name,
              'type', 'customer',
              'count', customer_data.dispatch_count,
              'metadata', jsonb_build_object(
                  'customer_id', customer_data.customer_id,
                  'last_dispatch_date', customer_data.last_dispatch_date,
                  'total_dispatches', customer_data.dispatch_count,
                  'total_dispatched_qty', customer_data.total_dispatched_qty
              )
          )
          ORDER BY customer_data.last_dispatch_date DESC NULLS LAST
      ) INTO v_customers
      FROM (
          SELECT DISTINCT
              d.customer_id,
              d.customer_name,
              COUNT(d.id) as dispatch_count,
              MAX(d.disp_date) as last_dispatch_date,
              COALESCE(SUM(dt_sum.total_qty), 0) as total_dispatched_qty
          FROM dispatch d
          LEFT JOIN (
              SELECT
                  dt.disp_id,
                  SUM(dt.disp_qty) as total_qty
              FROM dispatch_trl dt
              GROUP BY dt.disp_id
          ) dt_sum ON d.id = dt_sum.disp_id
          WHERE LOWER(d.customer_name) LIKE v_search_pattern
          AND (v_user_role IN ('admin', 'supervisor', 'staff') OR d.customer_id = ANY(v_user_customer_ids))
          GROUP BY d.customer_id, d.customer_name
          ORDER BY last_dispatch_date DESC NULLS LAST
          LIMIT p_limit
      ) customer_data;

      -- Get matching items (ordered by dispatch frequency)
      SELECT jsonb_agg(
          jsonb_build_object(
              'value', LOWER(REGEXP_REPLACE(item_data.item_name, '[^a-zA-Z0-9]+', '-', 'g')),
              'label', item_data.item_name,
              'type', 'item',
              'count', item_data.dispatch_count,
              'metadata', jsonb_build_object(
                  'item_id', item_data.item_id,
                  'total_dispatched_qty', item_data.total_dispatched_qty,
                  'total_dispatches', item_data.dispatch_count,
                  'last_dispatch_date', item_data.last_dispatch_date
              )
          )
          ORDER BY item_data.dispatch_count DESC
      ) INTO v_items
      FROM (
          SELECT
              grt.item_id,
              grt.item_name,
              COUNT(DISTINCT d.id) as dispatch_count,
              COALESCE(SUM(dt.disp_qty), 0) as total_dispatched_qty,
              MAX(d.disp_date) as last_dispatch_date
          FROM goodsreceived_trl grt
          JOIN dispatch_trl dt ON grt.id = dt.gr_trl_id
          JOIN dispatch d ON dt.disp_id = d.id
          WHERE LOWER(grt.item_name) LIKE v_search_pattern
          AND (v_user_role IN ('admin', 'supervisor', 'staff') OR d.customer_id = ANY(v_user_customer_ids))
          GROUP BY grt.item_id, grt.item_name
          ORDER BY dispatch_count DESC, last_dispatch_date DESC
          LIMIT p_limit
      ) item_data;

      -- Build final response
      RETURN jsonb_build_object(
          'success', true,
          'message', 'Dispatch autocomplete results retrieved successfully',
          'data', jsonb_build_object(
              'dispatches', COALESCE(v_dispatches, '[]'::jsonb),
              'customers', COALESCE(v_customers, '[]'::jsonb),
              'items', COALESCE(v_items, '[]'::jsonb),
              'summary', jsonb_build_object(
                  'total_results', (
                      COALESCE(jsonb_array_length(v_dispatches), 0) +
                      COALESCE(jsonb_array_length(v_customers), 0) +
                      COALESCE(jsonb_array_length(v_items), 0)
                  ),
                  'dispatch_count', COALESCE(jsonb_array_length(v_dispatches), 0),
                  'customer_count', COALESCE(jsonb_array_length(v_customers), 0),
                  'item_count', COALESCE(jsonb_array_length(v_items), 0)
              ),
              'query', TRIM(p_search_query),
              'limit', p_limit
          )
      );

  EXCEPTION
      WHEN OTHERS THEN
          RETURN jsonb_build_object(
              'success', false,
              'data', null,
              'message', 'Error retrieving dispatch autocomplete: ' || SQLERRM
          );
  END;
  $$;


CREATE FUNCTION public.get_dispatch_cart_linkage_summary(p_cart_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_result jsonb;
BEGIN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'dispatch_id', d.id, 'dispatch_no', d.disp_no, 'source_order_id', d.source_order_id,
        'order_no', o.order_no, 'total_items_from_cart', (SELECT COUNT(*) FROM dispatch_trl WHERE disp_id = d.id),
        'total_quantity_consumed', (SELECT COALESCE(SUM(disp_qty), 0) FROM dispatch_trl WHERE disp_id = d.id),
        'dispatch_date', d.disp_date::date, 'dispatch_deleted', d.deleted_at IS NOT NULL
    )), '[]'::jsonb) INTO v_result
    FROM dispatch d
    LEFT JOIN orders o ON d.source_order_id = o.id
    WHERE d.source_order_id = p_cart_id;
    RETURN utils.success_response(v_result);
EXCEPTION WHEN OTHERS THEN RETURN utils.database_error_response('Failed to get dispatch cart linkage', SQLERRM, SQLSTATE);
END;
$$;


CREATE FUNCTION public.get_dispatch_details(p_dispatch_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    DECLARE
        v_user_id uuid;
        v_role text;
        v_result jsonb;
    BEGIN
        v_user_id := auth.uid();

        SELECT role INTO v_role
        FROM user_profiles
        WHERE auth_user_id = v_user_id;

        SELECT jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'dispatch', jsonb_build_object(
                    'id', d.id,
                    'disp_no', d.disp_no,
                    'disp_date', d.disp_date,
                    'registration', d.registration,
                    'note', d.note,
                    'disp_image_url', d.disp_image_url,
                    'source_order_id', d.source_order_id,
                    'source_order_no', d.source_order_no,
                    'created_at', d.created_at,
                    'updated_at', d.updated_at,

                    'images', COALESCE(
                        (
                            SELECT jsonb_agg(
                                jsonb_build_object(
                                    'id', di.id,
                                    'storage_path', di.storage_path,
                                    'original_filename', di.original_filename,
                                    'file_size', di.file_size,
                                    'mime_type', di.mime_type,
                                    'display_order', di.display_order,
                                    'created_at', di.created_at
                                )
                                ORDER BY di.display_order, di.created_at
                            )
                            FROM dispatch_images di
                            WHERE di.dispatch_id = d.id
                            AND di.status = 'confirmed'
                        ),
                        '[]'::jsonb
                    ),

                    'customer_details', CASE
                        WHEN c.id IS NOT NULL THEN jsonb_build_object(
                            'id', c.id,
                            'name', c.name,
                            'first_name', c."firstName",
                            'last_name', c."lastName",
                            'gst', c.gst,
                            'mobile', c.mobile,
                            'address', c.address,
                            'city', c.city,
                            'state', c.state,
                            'pincode', c.pincode,
                            'email', c.email,
                            'active', c.active,
                            'auto_invoice_generation', c.auto_invoice_generation
                        )
                        ELSE null
                    END,

                    'supervisor_details', CASE
                        WHEN u.id IS NOT NULL THEN jsonb_build_object(
                            'id', u.id,
                            'name', u.name,
                            'mobile', u.mobile,
                            'role', u.role,
                            'display_name', u.display_name
                        )
                        ELSE null
                    END,

                    'items', COALESCE(
                        (
                            SELECT jsonb_agg(
                                jsonb_build_object(
                                    'id', dt.id,
                                    'disp_qty', dt.disp_qty,
                                    'grn_id', dt.gr_id,
                                    'grn_item_id', dt.gr_trl_id,

                                    'grn_item_details', CASE
                                        WHEN grt.id IS NOT NULL THEN jsonb_build_object(
                                            'id', grt.id,
                                            'qty', grt.qty,
                                            'stock', grt.stock,
                                            'weight', grt.weight,
                                            'rack', grt.rack,
                                            'package_mark', grt.package_mark,
                                            'item_name', grt.item_name,
                                            'packaging', grt.packaging,
                                            'pricing_mode', gr.pricing_mode,
                                            'trl_img_url', grt.trl_img_url
                                        )
                                        ELSE null
                                    END,

                                    'grn_details', CASE
                                        WHEN gr.id IS NOT NULL THEN jsonb_build_object(
                                            'id', gr.id,
                                            'gr_no', gr.gr_no,
                                            'date', gr.date,
                                            'registration', gr.registration,
                                            'customer_name', gr.customer_name,
                                            'supervisor_name', gr.supervisor_name,
                                            'sender_name', gr.sender_name,
                                            'invoiced', gr.invoiced,
                                            'out_of_stock', gr.out_of_stock
                                        )
                                        ELSE null
                                    END,

                                    'item_details', CASE
                                        WHEN i.id IS NOT NULL THEN jsonb_build_object(
                                            'id', i.id,
                                            'name', i.name,
                                            'packaging', i.packaging,
                                            'description', i.description,
                                            'active', i.active
                                        )
                                        ELSE null
                                    END,

                                    'invoice_details', CASE
                                        WHEN it.id IS NOT NULL THEN jsonb_build_object(
                                            'invoice_trl_id', it.id,
                                            'invoice_id', it.invoice_id,
                                            'duration', it.duration,
                                            'no_of_days', it.no_of_days,
                                            'charge', it.charge,
                                            'tax', it.tax,
                                            'labour_rate', it.labour_rate,
                                            'invoice_no', inv.inv_no,
                                            'invoice_date', inv.inv_date,
                                            'total', inv.total
                                        )
                                        ELSE null
                                    END
                                )
                                ORDER BY dt.id
                            )
                            FROM dispatch_trl dt
                            LEFT JOIN goodsreceived_trl grt ON dt.gr_trl_id = grt.id
                            LEFT JOIN goodsreceived gr ON dt.gr_id = gr.id
                            LEFT JOIN items i ON grt.item_id = i.id
                            LEFT JOIN invoice_trl it ON dt.id = it.disp_trl_id
                            LEFT JOIN invoice inv ON it.invoice_id = inv.id
                            WHERE dt.disp_id = d.id
                        ),
                        '[]'::jsonb
                    ),

                    'statistics', (
                        SELECT jsonb_build_object(
                            'total_items', COUNT(DISTINCT dt.gr_trl_id),
                            'total_dispatched_qty', COALESCE(SUM(dt.disp_qty), 0),
                            'unique_grns', COUNT(DISTINCT dt.gr_id),
                            'total_invoiced_items', COUNT(DISTINCT it.id),
                            'total_invoice_amount', COALESCE(SUM(it.charge * it.duration), 0),
                            'avg_duration', COALESCE(AVG(it.duration), 0),
                            'avg_no_of_days', COALESCE(AVG(it.no_of_days), 0)
                        )
                        FROM dispatch_trl dt
                        LEFT JOIN invoice_trl it ON dt.id = it.disp_trl_id
                        WHERE dt.disp_id = d.id
                    ),

                    'grns_summary', (
                        SELECT jsonb_build_object(
                            'total_grns', COUNT(DISTINCT gr.id),
                            'grn_numbers', COALESCE(
                                jsonb_agg(
                                    DISTINCT gr.gr_no
                                    ORDER BY gr.gr_no
                                ) FILTER (WHERE gr.gr_no IS NOT NULL),
                                '[]'::jsonb
                            )
                        )
                        FROM dispatch_trl dt
                        JOIN goodsreceived gr ON dt.gr_id = gr.id
                        WHERE dt.disp_id = d.id
                    ),

                    'invoices_summary', (
                        SELECT jsonb_build_object(
                            'total_invoices', COUNT(DISTINCT inv.id),
                            'total_amount', COALESCE(SUM(inv.total), 0),
                            'invoice_numbers', COALESCE(
                                jsonb_agg(
                                    DISTINCT inv.inv_no
                                    ORDER BY inv.inv_no
                                ) FILTER (WHERE inv.inv_no IS NOT NULL),
                                '[]'::jsonb
                            )
                        )
                        FROM dispatch_trl dt
                        JOIN invoice_trl it ON dt.id = it.disp_trl_id
                        JOIN invoice inv ON it.invoice_id = inv.id
                        WHERE dt.disp_id = d.id
                    )
                )
            ),
            'message', 'Dispatch details retrieved successfully'
        ) INTO v_result
        FROM dispatch d
        LEFT JOIN customers c ON d.customer_id = c.id
        LEFT JOIN user_profiles u ON d.supervisor_id = u.id
        WHERE d.id = p_dispatch_id
        AND (
            v_role IN ('admin', 'supervisor', 'staff') OR
            d.customer_id IN (
                SELECT customer_id FROM users_customers_new
                WHERE user_profile_id = (SELECT id FROM user_profiles WHERE auth_user_id = v_user_id)
            )
        );

        IF v_result IS NULL THEN
            RETURN jsonb_build_object(
                'success', false,
                'data', null,
                'message', 'Dispatch not found or access denied'
            );
        END IF;

        RETURN v_result;

    EXCEPTION
        WHEN OTHERS THEN
            RETURN jsonb_build_object(
                'success', false,
                'data', null,
                'message', 'Error retrieving dispatch details: ' || SQLERRM
            );
    END;
    $$;


CREATE FUNCTION public.get_dispatch_list(p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_filters jsonb DEFAULT '{}'::jsonb, p_sort_by text DEFAULT 'disp_date'::text, p_sort_order text DEFAULT 'desc'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_role text;
    v_user_customer_ids uuid[];
    v_result jsonb;
    v_dispatches jsonb;
    v_total_count bigint;
    v_customer_filter text;
    v_disp_no_filter text;
    v_supervisor_filter text;
    v_grn_filter text;
    v_item_filter text;
    v_is_admin boolean;
BEGIN
    IF auth.uid() IS NULL THEN
        v_is_admin := true;
    ELSE
        SELECT role INTO v_user_role FROM user_profiles WHERE auth_user_id = auth.uid();
        v_is_admin := (v_user_role IN ('admin', 'supervisor', 'staff'));
    END IF;

    IF NOT v_is_admin THEN
        v_user_customer_ids := user_accessible_customers();
        IF v_user_customer_ids IS NULL OR array_length(v_user_customer_ids, 1) IS NULL THEN
            RETURN jsonb_build_object(
                'success', false,
                'message', 'Access denied: No accessible customers found',
                'data', null
            );
        END IF;
    END IF;

    IF p_limit < 1 OR p_limit > 1000 THEN p_limit := 20; END IF;
    IF p_offset < 0 THEN p_offset := 0; END IF;

    -- Extract filters (snake_case only)
    v_customer_filter := NULLIF(TRIM(p_filters->>'customer_name'), '');
    v_disp_no_filter := NULLIF(TRIM(p_filters->>'disp_no'), '');
    v_supervisor_filter := NULLIF(TRIM(p_filters->>'supervisor_name'), '');
    v_grn_filter := NULLIF(TRIM(p_filters->>'grn_no'), '');
    v_item_filter := NULLIF(TRIM(p_filters->>'item_name'), '');

    -- Get total count from MV
    SELECT COUNT(*) INTO v_total_count
    FROM mv_dispatch_list m
    WHERE (p_date_from IS NULL OR m.disp_date >= p_date_from)
      AND (p_date_to IS NULL OR m.disp_date <= p_date_to)
      AND (v_is_admin OR m.customer_id = ANY(v_user_customer_ids))
      AND (v_customer_filter IS NULL OR m.customer_name ILIKE '%' || v_customer_filter || '%')
      AND (v_disp_no_filter IS NULL OR m.disp_no ILIKE v_disp_no_filter || '%')
      AND (v_supervisor_filter IS NULL OR m.supervisor_name ILIKE '%' || v_supervisor_filter || '%')
      AND (v_grn_filter IS NULL OR m.grn_numbers && ARRAY[v_grn_filter] OR EXISTS (
           SELECT 1 FROM unnest(m.grn_numbers) AS gn WHERE gn ILIKE v_grn_filter || '%'))
      AND (v_item_filter IS NULL OR EXISTS (
           SELECT 1 FROM jsonb_array_elements(m.items_jsonb) AS item
           WHERE item->>'item_name' ILIKE '%' || v_item_filter || '%'));

    -- Get paginated results from MV with snake_case output
    SELECT jsonb_agg(
        jsonb_build_object(
            'id', m.dispatch_id,
            'dispatch_id', m.dispatch_id,
            'disp_no', m.disp_no,
            'disp_date', m.disp_date,
            'customer_name', m.customer_name,
            'customer_id', m.customer_id,
            'supervisor_name', m.supervisor_name,
            'supervisor_id', m.supervisor_id,
            'registration', m.registration,
            'note', m.note,
            'total_items', m.total_items,
            'total_qty', m.total_qty,
            'total_weight', m.total_weight,
            'unique_grns', m.unique_grns,
            'grn_numbers', m.grn_numbers,
            'items', m.items_jsonb,
            'source_order_id', m.source_order_id,
            'source_order_no', m.source_order_no,
            'created_at', m.created_at,
            'updated_at', m.updated_at
        )
    ) INTO v_dispatches
    FROM (
        SELECT *
        FROM mv_dispatch_list m
        WHERE (p_date_from IS NULL OR m.disp_date >= p_date_from)
          AND (p_date_to IS NULL OR m.disp_date <= p_date_to)
          AND (v_is_admin OR m.customer_id = ANY(v_user_customer_ids))
          AND (v_customer_filter IS NULL OR m.customer_name ILIKE '%' || v_customer_filter || '%')
          AND (v_disp_no_filter IS NULL OR m.disp_no ILIKE v_disp_no_filter || '%')
          AND (v_supervisor_filter IS NULL OR m.supervisor_name ILIKE '%' || v_supervisor_filter || '%')
          AND (v_grn_filter IS NULL OR m.grn_numbers && ARRAY[v_grn_filter] OR EXISTS (
               SELECT 1 FROM unnest(m.grn_numbers) AS gn WHERE gn ILIKE v_grn_filter || '%'))
          AND (v_item_filter IS NULL OR EXISTS (
               SELECT 1 FROM jsonb_array_elements(m.items_jsonb) AS item
               WHERE item->>'item_name' ILIKE '%' || v_item_filter || '%'))
        ORDER BY
            CASE WHEN p_sort_by = 'disp_date' AND UPPER(p_sort_order) = 'DESC' THEN m.disp_date END DESC NULLS LAST,
            CASE WHEN p_sort_by = 'disp_date' AND UPPER(p_sort_order) = 'ASC' THEN m.disp_date END ASC NULLS LAST,
            CASE WHEN p_sort_by = 'disp_no' AND UPPER(p_sort_order) = 'DESC' THEN m.disp_no END DESC NULLS LAST,
            CASE WHEN p_sort_by = 'disp_no' AND UPPER(p_sort_order) = 'ASC' THEN m.disp_no END ASC NULLS LAST,
            CASE WHEN p_sort_by = 'customer_name' AND UPPER(p_sort_order) = 'DESC' THEN m.customer_name END DESC NULLS LAST,
            CASE WHEN p_sort_by = 'customer_name' AND UPPER(p_sort_order) = 'ASC' THEN m.customer_name END ASC NULLS LAST,
            CASE WHEN p_sort_by = 'supervisor_name' AND UPPER(p_sort_order) = 'DESC' THEN m.supervisor_name END DESC NULLS LAST,
            CASE WHEN p_sort_by = 'supervisor_name' AND UPPER(p_sort_order) = 'ASC' THEN m.supervisor_name END ASC NULLS LAST,
            m.disp_date DESC NULLS LAST
        LIMIT p_limit
        OFFSET p_offset
    ) m;

    RETURN jsonb_build_object(
        'success', true,
        'data', COALESCE(v_dispatches, '[]'::jsonb),
        'pagination', jsonb_build_object(
            'total_count', v_total_count,
            'limit', p_limit,
            'offset', p_offset,
            'has_more', (p_offset + p_limit) < v_total_count
        ),
        'message', null
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Error retrieving dispatch list: ' || SQLERRM,
            'data', null
        );
END;
$$;


CREATE FUNCTION public.get_dispatch_list_original(p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_filters jsonb DEFAULT '{}'::jsonb, p_sort_by text DEFAULT 'disp_date'::text, p_sort_order text DEFAULT 'desc'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    -- Just call the old function
    RETURN get_dispatch_list(p_date_from, p_date_to, p_filters, p_sort_by, p_sort_order, p_limit, p_offset);
END;
$$;


CREATE FUNCTION public.get_dispatch_list_with_items(p_customer_id uuid DEFAULT NULL::uuid, p_filters jsonb DEFAULT '{}'::jsonb, p_sort_by text DEFAULT 'dispatch_date'::text, p_sort_order text DEFAULT 'desc'::text, p_page integer DEFAULT 1, p_limit integer DEFAULT 10, p_include_items boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_offset integer;
    v_total_count bigint;
    v_query text;
    v_data jsonb;
    v_disp_no_filter text;
    v_order_by text;
    v_qty_min integer;
    v_qty_max integer;
    v_disp_qty_min integer;
    v_disp_qty_max integer;
    v_user_role text;
    v_user_customer_ids uuid[];
    v_customer_filter text;
    v_disp_no_from text;
    v_disp_no_to text;
    v_disp_no_range_filter text;
    v_filter_customer_ids uuid[];
    v_filter_item_ids uuid[];
    v_item_ids_filter text;
BEGIN
    SELECT role INTO v_user_role FROM user_profiles WHERE auth_user_id = auth.uid();

    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        v_user_customer_ids := user_accessible_customers();
        IF v_user_customer_ids IS NULL OR array_length(v_user_customer_ids, 1) IS NULL THEN
            RETURN jsonb_build_object(
                'success', false,
                'message', 'Access denied: No accessible customers found',
                'data', jsonb_build_object(
                    'dispatches', '[]'::jsonb,
                    'total_count', 0,
                    'current_page', p_page,
                    'total_pages', 0,
                    'limit', p_limit
                )
            );
        END IF;
    END IF;

    v_offset := (p_page - 1) * p_limit;

    -- Extract quantity filters (snake_case)
    v_qty_min := (p_filters->>'qty_min')::integer;
    v_qty_max := (p_filters->>'qty_max')::integer;
    v_disp_qty_min := (p_filters->>'disp_qty_min')::integer;
    v_disp_qty_max := (p_filters->>'disp_qty_max')::integer;

    -- Extract customer_ids array filter
    IF p_filters ? 'customer_ids' AND jsonb_typeof(p_filters->'customer_ids') = 'array'
       AND jsonb_array_length(p_filters->'customer_ids') > 0 THEN
        SELECT array_agg(elem::text::uuid)
        INTO v_filter_customer_ids
        FROM jsonb_array_elements_text(p_filters->'customer_ids') AS elem;
    END IF;

    -- Extract item_ids array filter
    IF p_filters ? 'item_ids' AND jsonb_typeof(p_filters->'item_ids') = 'array'
       AND jsonb_array_length(p_filters->'item_ids') > 0 THEN
        SELECT array_agg(elem::text::uuid)
        INTO v_filter_item_ids
        FROM jsonb_array_elements_text(p_filters->'item_ids') AS elem;
    END IF;

    -- Extract dispatch number range filters (snake_case only)
    IF p_filters ? 'disp_no_from' THEN
        v_disp_no_from := p_filters->>'disp_no_from';
        v_disp_no_from := LTRIM(TRIM(v_disp_no_from), '#');
    END IF;

    IF p_filters ? 'disp_no_to' THEN
        v_disp_no_to := p_filters->>'disp_no_to';
        v_disp_no_to := LTRIM(TRIM(v_disp_no_to), '#');
    END IF;

    -- Build customer filter based on role and parameters
    IF v_user_role IN ('admin', 'supervisor', 'staff') THEN
        -- Admin/supervisor: use customer_ids array if provided, else single p_customer_id
        IF v_filter_customer_ids IS NOT NULL AND array_length(v_filter_customer_ids, 1) > 0 THEN
            v_customer_filter := format(' AND d.customer_id = ANY(%L::uuid[])', v_filter_customer_ids);
        ELSIF p_customer_id IS NOT NULL THEN
            v_customer_filter := format(' AND d.customer_id = %L', p_customer_id);
        ELSE
            v_customer_filter := '';
        END IF;
    ELSE
        -- Non-admin: filter by customer_ids intersected with accessible customers
        IF v_filter_customer_ids IS NOT NULL AND array_length(v_filter_customer_ids, 1) > 0 THEN
            -- Intersect requested customer_ids with user's accessible customers
            SELECT array_agg(cid)
            INTO v_filter_customer_ids
            FROM unnest(v_filter_customer_ids) AS cid
            WHERE cid = ANY(v_user_customer_ids);

            IF v_filter_customer_ids IS NULL OR array_length(v_filter_customer_ids, 1) IS NULL THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'message', 'Access denied: None of the requested customers are accessible',
                    'data', jsonb_build_object(
                        'dispatches', '[]'::jsonb,
                        'total_count', 0,
                        'current_page', p_page,
                        'total_pages', 0,
                        'limit', p_limit
                    )
                );
            END IF;
            v_customer_filter := format(' AND d.customer_id = ANY(%L::uuid[])', v_filter_customer_ids);
        ELSIF p_customer_id IS NOT NULL THEN
            IF p_customer_id = ANY(v_user_customer_ids) THEN
                v_customer_filter := format(' AND d.customer_id = %L', p_customer_id);
            ELSE
                RETURN jsonb_build_object(
                    'success', false,
                    'message', 'Access denied: Customer not accessible',
                    'data', jsonb_build_object(
                        'dispatches', '[]'::jsonb,
                        'total_count', 0,
                        'current_page', p_page,
                        'total_pages', 0,
                        'limit', p_limit
                    )
                );
            END IF;
        ELSE
            v_customer_filter := format(' AND d.customer_id = ANY(%L::uuid[])', v_user_customer_ids);
        END IF;
    END IF;

    -- Build item_ids filter
    IF v_filter_item_ids IS NOT NULL AND array_length(v_filter_item_ids, 1) > 0 THEN
        v_item_ids_filter := format(' AND EXISTS (SELECT 1 FROM dispatch_trl dt_item JOIN goodsreceived_trl grt_item ON dt_item.gr_trl_id = grt_item.id WHERE dt_item.disp_id = d.id AND grt_item.item_id = ANY(%L::uuid[]))', v_filter_item_ids);
    ELSE
        v_item_ids_filter := '';
    END IF;

    -- Check if disp_no filter is present
    IF p_filters ? 'disp_no' AND p_filters->>'disp_no' IS NOT NULL AND p_filters->>'disp_no' != '' THEN
        v_disp_no_filter := format(' AND d.disp_no ILIKE %L', p_filters->>'disp_no' || '%');
        v_order_by := '(CASE WHEN SUBSTRING(disp_no FROM 1 FOR 3) = ''CLR''
              THEN ASCII(''I'') - ASCII(''A'') + 1
              ELSE ASCII(SUBSTRING(disp_no FROM 1 FOR 1)) - ASCII(''A'')
         END * 100000 + COALESCE(CAST(NULLIF(REGEXP_REPLACE(disp_no, ''[^0-9]'', '''', ''g''), '''') AS INTEGER), 0)) DESC NULLS LAST';
    ELSE
        v_disp_no_filter := '';
        v_order_by := CASE
            WHEN p_sort_by = 'dispatch_date' THEN
                'disp_date ' || CASE WHEN LOWER(p_sort_order) = 'asc' THEN 'ASC' ELSE 'DESC' END ||
                ' NULLS LAST, (CASE WHEN SUBSTRING(disp_no FROM 1 FOR 3) = ''CLR''
                      THEN ASCII(''I'') - ASCII(''A'') + 1
                      ELSE ASCII(SUBSTRING(disp_no FROM 1 FOR 1)) - ASCII(''A'')
                 END * 100000 + COALESCE(CAST(NULLIF(REGEXP_REPLACE(disp_no, ''[^0-9]'', '''', ''g''), '''') AS INTEGER), 0)) DESC NULLS LAST'
            WHEN p_sort_by = 'disp_no' THEN
                '(CASE WHEN SUBSTRING(disp_no FROM 1 FOR 3) = ''CLR''
                      THEN ASCII(''I'') - ASCII(''A'') + 1
                      ELSE ASCII(SUBSTRING(disp_no FROM 1 FOR 1)) - ASCII(''A'')
                 END * 100000 + COALESCE(CAST(NULLIF(REGEXP_REPLACE(disp_no, ''[^0-9]'', '''', ''g''), '''') AS INTEGER), 0)) ' ||
                CASE WHEN LOWER(p_sort_order) = 'asc' THEN 'ASC' ELSE 'DESC' END || ' NULLS LAST'
            WHEN p_sort_by = 'customer_name' THEN
                'customer_name ' || CASE WHEN LOWER(p_sort_order) = 'asc' THEN 'ASC' ELSE 'DESC' END ||
                ' NULLS LAST, disp_date DESC NULLS LAST'
            ELSE
                'disp_date DESC NULLS LAST'
        END;
    END IF;

    -- Build dispatch number range filter
    IF v_disp_no_from IS NOT NULL AND LENGTH(v_disp_no_from) > 0 AND
       v_disp_no_to IS NOT NULL AND LENGTH(v_disp_no_to) > 0 THEN
        v_disp_no_range_filter := format(' AND d.disp_no BETWEEN %L AND %L', v_disp_no_from, v_disp_no_to);
    ELSIF v_disp_no_from IS NOT NULL AND LENGTH(v_disp_no_from) > 0 THEN
        v_disp_no_range_filter := format(' AND d.disp_no >= %L', v_disp_no_from);
    ELSIF v_disp_no_to IS NOT NULL AND LENGTH(v_disp_no_to) > 0 THEN
        v_disp_no_range_filter := format(' AND d.disp_no <= %L', v_disp_no_to);
    ELSE
        v_disp_no_range_filter := '';
    END IF;

    -- Build the main query (snake_case response keys)
    v_query := format($query$
        WITH filtered_dispatches AS (
            SELECT d.id, d.disp_no, d.disp_date, d.customer_id, d.customer_name,
                d.registration, d.created_at, d.updated_at, d.created_by, d.updated_by, d.note
            FROM dispatch d
            WHERE 1=1 %s %s %s %s %s %s %s %s %s %s
        ),
        dispatch_items AS (
            SELECT dt.disp_id, %s as items,
                SUM(dt.disp_qty) as total_qty,
                SUM(dt.disp_qty * grt.weight) as total_weight,
                COUNT(DISTINCT grt.item_id) as item_count
            FROM dispatch_trl dt
            JOIN goodsreceived_trl grt ON dt.gr_trl_id = grt.id
            JOIN goodsreceived gr ON grt.gr_id = gr.id
            WHERE dt.disp_id IN (SELECT id FROM filtered_dispatches)
            GROUP BY dt.disp_id
        ),
        dispatch_aggregates AS (
            SELECT fd.*, COALESCE(di.total_qty, 0) as total_qty,
                COALESCE(di.total_weight, 0) as total_weight,
                COALESCE(di.item_count, 0) as item_count, di.items
            FROM filtered_dispatches fd
            LEFT JOIN dispatch_items di ON fd.id = di.disp_id
        ),
        paginated_results AS (
            SELECT * FROM dispatch_aggregates ORDER BY %s LIMIT %s OFFSET %s
        )
        SELECT jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'dispatches', COALESCE(jsonb_agg(
                    jsonb_build_object(
                        'id', pr.id,
                        'disp_no', pr.disp_no,
                        'dispatch_date', pr.disp_date,
                        'customer_id', pr.customer_id,
                        'customer_name', pr.customer_name,
                        'registration', pr.registration,
                        'total_qty', pr.total_qty,
                        'total_weight', pr.total_weight,
                        'item_count', pr.item_count,
                        'items', pr.items,
                        'notes', pr.note,
                        'created_at', pr.created_at,
                        'updated_at', pr.updated_at,
                        'created_by', pr.created_by,
                        'updated_by', pr.updated_by
                    ) ORDER BY %s
                ), '[]'::jsonb),
                'total_count', (SELECT COUNT(*) FROM filtered_dispatches),
                'current_page', %s,
                'total_pages', CEIL((SELECT COUNT(*)::numeric FROM filtered_dispatches) / %s::numeric),
                'limit', %s
            )
        ) as result
        FROM paginated_results pr
    $query$,
        v_customer_filter, v_disp_no_filter, v_disp_no_range_filter,
        CASE WHEN p_filters ? 'date_from' AND p_filters->>'date_from' IS NOT NULL
            THEN format(' AND d.disp_date >= %L::date', p_filters->>'date_from') ELSE '' END,
        CASE WHEN p_filters ? 'date_to' AND p_filters->>'date_to' IS NOT NULL
            THEN format(' AND d.disp_date <= %L::date', p_filters->>'date_to') ELSE '' END,
        CASE WHEN p_filters ? 'created_date_from' AND p_filters->>'created_date_from' IS NOT NULL
            THEN format(' AND d.created_at >= %L::timestamptz', p_filters->>'created_date_from') ELSE '' END,
        CASE WHEN p_filters ? 'created_date_to' AND p_filters->>'created_date_to' IS NOT NULL
            THEN format(' AND d.created_at <= %L::timestamptz', p_filters->>'created_date_to') ELSE '' END,
        CASE WHEN v_qty_min IS NOT NULL OR v_qty_max IS NOT NULL THEN
            format(' AND EXISTS (SELECT 1 FROM dispatch_trl dt2 JOIN goodsreceived_trl grt2 ON dt2.gr_trl_id = grt2.id WHERE dt2.disp_id = d.id AND grt2.qty >= %s AND grt2.qty <= %s)',
            COALESCE(v_qty_min, 0), COALESCE(v_qty_max, 999999999)) ELSE '' END,
        CASE WHEN v_disp_qty_min IS NOT NULL OR v_disp_qty_max IS NOT NULL THEN
            format(' AND EXISTS (SELECT 1 FROM dispatch_trl dt3 WHERE dt3.disp_id = d.id AND dt3.disp_qty >= %s AND dt3.disp_qty <= %s)',
            COALESCE(v_disp_qty_min, 0), COALESCE(v_disp_qty_max, 999999999)) ELSE '' END,
        v_item_ids_filter,
        CASE WHEN p_include_items THEN
            'jsonb_agg(jsonb_build_object(
                ''item_id'', grt.item_id, ''item_name'', grt.item_name, ''disp_qty'', dt.disp_qty,
                ''weight'', grt.weight, ''gr_no'', gr.gr_no, ''grn_qty'', grt.qty,
                ''grn_item_id'', grt.id, ''package_mark'', grt.package_mark, ''rack'', grt.rack
            ) ORDER BY grt.item_name)'
        ELSE 'NULL::jsonb' END,
        v_order_by, p_limit, v_offset, v_order_by, p_page, p_limit, p_limit
    );

    EXECUTE v_query INTO v_data;
    RETURN v_data;
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'An error occurred: ' || SQLERRM,
            'data', jsonb_build_object(
                'dispatches', '[]'::jsonb,
                'total_count', 0,
                'current_page', p_page,
                'total_pages', 0,
                'limit', p_limit
            )
        );
END;
$_$;


CREATE FUNCTION public.get_dispatch_range_for_print(start_disp_no text, end_disp_no text, limit_count integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    WITH dispatch_data AS (
        SELECT
            d.id as dispatch_id,
            d.disp_no,
            TO_CHAR(d.disp_date, 'YYYY-MM-DD') as formatted_date,
            d.registration,
            d.customer_id::TEXT,
            d.customer_name,
            d.supervisor_id::TEXT,
            d.supervisor_name,
            d.note,
            d.disp_image_url,
            d.source_order_id,
            o.order_no as source_order_no
        FROM dispatch d
        LEFT JOIN orders o ON o.id = d.source_order_id
        WHERE d.disp_no >= start_disp_no
          AND d.disp_no <= end_disp_no
        ORDER BY d.disp_no
        LIMIT limit_count
    ),
    dispatch_with_customer AS (
        SELECT
            dd.*,
            CASE WHEN c.id IS NOT NULL THEN
                jsonb_build_object(
                    'id', c.id::TEXT,
                    'first_name', c."firstName",
                    'last_name', c."lastName",
                    'address', c.address,
                    'city', c.city,
                    'mobile', c.mobile
                )
            ELSE NULL
            END as customer_data
        FROM dispatch_data dd
        LEFT JOIN customers c ON c.id = dd.customer_id::UUID
    ),
    dispatch_items_with_grn AS (
        SELECT
            dwc.*,
            dt.id as dispatch_trl_id,
            dt.disp_qty,
            gr.id as gr_id,
            gr.gr_no,
            TO_CHAR(gr.date, 'YYYY-MM-DD') as gr_date,
            gr.customer_id as gr_customer_id,
            gr.customer_name as gr_customer_name,
            gr.registration as gr_registration,
            gr.gr_image_url as gr_image_url,
            COALESCE(gr.invoiced, FALSE) as gr_invoiced,
            COALESCE(gr.leon, FALSE) as gr_leon,
            gr.note as gr_note,
            COALESCE(gr.out_of_stock, FALSE) as gr_out_of_stock,
            gr.sender_id as gr_sender_id,
            gr.sender_name as gr_sender_name,
            gr.supervisor_id as gr_supervisor_id,
            gr.supervisor_name as gr_supervisor_name,
            grt.id as grt_id,
            grt.item_id as grt_item_id,
            grt.item_name as grt_item_name,
            grt.packaging as grt_packaging,
            grt.qty as grt_qty,
            grt.stock as grt_stock,
            grt.weight as grt_weight,
            grt.rack as grt_rack,
            grt.package_mark as grt_package_mark,
            grt.trl_img_url as grt_trl_img_url,
            ROW_NUMBER() OVER (PARTITION BY dwc.dispatch_id ORDER BY dt.id) as sr_no
        FROM dispatch_with_customer dwc
        LEFT JOIN dispatch_trl dt ON dt.disp_id = dwc.dispatch_id
        LEFT JOIN goodsreceived gr ON gr.id = dt.gr_id
        LEFT JOIN goodsreceived_trl grt ON grt.id = dt.gr_trl_id
    ),
    dispatch_with_items AS (
        SELECT
            diwg.dispatch_id,
            diwg.disp_no,
            diwg.formatted_date,
            diwg.registration,
            diwg.customer_id,
            diwg.customer_name,
            diwg.supervisor_id,
            diwg.supervisor_name,
            diwg.note,
            diwg.disp_image_url,
            diwg.source_order_id,
            diwg.source_order_no,
            diwg.customer_data,
            jsonb_agg(
                CASE WHEN diwg.dispatch_trl_id IS NOT NULL THEN
                    jsonb_build_object(
                        'id', diwg.dispatch_trl_id::TEXT,
                        'dispatch_id', diwg.dispatch_id::TEXT,
                        'disp_no', diwg.disp_no,
                        'disp_quantity', COALESCE(diwg.disp_qty, 0),
                        'grn_items_id', diwg.grt_id::TEXT,
                        'grn_items_image_url', diwg.grt_trl_img_url,
                        'grn_items_item_id', diwg.grt_item_id::TEXT,
                        'grn_items_item_name', diwg.grt_item_name,
                        'grn_items_package_mark', diwg.grt_package_mark,
                        'grn_items_packaging', diwg.grt_packaging,
                        'grn_items_quantity', COALESCE(diwg.grt_qty, 0),
                        'grn_items_rack', diwg.grt_rack,
                        'grn_items_stock', COALESCE(diwg.grt_stock, 0),
                        'grn_items_weight', COALESCE(diwg.grt_weight, 0),
                        'grns_id', diwg.gr_id::TEXT,
                        'grns_gr_no', diwg.gr_no,
                        'grns_date', diwg.gr_date,
                        'grns_customer_id', diwg.gr_customer_id::TEXT,
                        'grns_customer_name', diwg.gr_customer_name,
                        'grns_registration', diwg.gr_registration,
                        'grns_image_url', diwg.gr_image_url,
                        'grns_invoiced', diwg.gr_invoiced,
                        'grns_leon', diwg.gr_leon,
                        'grns_note', diwg.gr_note,
                        'grns_out_of_stock', diwg.gr_out_of_stock,
                        'grns_sender_id', diwg.gr_sender_id::TEXT,
                        'grns_sender_name', diwg.gr_sender_name,
                        'grns_supervisor_id', diwg.gr_supervisor_id::TEXT,
                        'grns_supervisor_name', diwg.gr_supervisor_name,
                        'sr_no', diwg.sr_no
                    )
                ELSE NULL
                END
                ORDER BY diwg.sr_no
            ) FILTER (WHERE diwg.dispatch_trl_id IS NOT NULL) as items_data,
            SUM(COALESCE(diwg.disp_qty, 0)) as total_quantity
        FROM dispatch_items_with_grn diwg
        GROUP BY
            diwg.dispatch_id, diwg.disp_no, diwg.formatted_date, diwg.registration,
            diwg.customer_id, diwg.customer_name, diwg.supervisor_id, diwg.supervisor_name,
            diwg.note, diwg.disp_image_url, diwg.source_order_id, diwg.source_order_no, diwg.customer_data
    ),
    final_result AS (
        SELECT jsonb_agg(
            jsonb_build_object(
                'id', dwi.dispatch_id,
                'disp_no', dwi.disp_no,
                'disp_date', dwi.formatted_date,
                'registration', dwi.registration,
                'customer_id', dwi.customer_id,
                'customer_name', dwi.customer_name,
                'supervisor_id', dwi.supervisor_id,
                'supervisor_name', dwi.supervisor_name,
                'note', dwi.note,
                'image_url', dwi.disp_image_url,
                'source_order_id', dwi.source_order_id,
                'source_order_no', dwi.source_order_no,
                'customer', dwi.customer_data,
                'items', COALESCE(dwi.items_data, '[]'::jsonb),
                'total_qty', COALESCE(dwi.total_quantity, 0)::INTEGER,
                'total_qty_in_words', convert_number_to_words(COALESCE(dwi.total_quantity, 0)::INTEGER)
            ) ORDER BY dwi.disp_no
        ) as data
        FROM dispatch_with_items dwi
    )
    SELECT COALESCE(data, '[]'::jsonb) INTO v_result FROM final_result;

    RETURN utils.success_response(v_result, NULL);
END;
$$;


CREATE FUNCTION public.get_financial_year_dates(p_year integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_year integer; v_start date; v_end date;
BEGIN
    v_year := COALESCE(p_year, CASE WHEN EXTRACT(MONTH FROM NOW()) >= 4 THEN EXTRACT(YEAR FROM NOW()) ELSE EXTRACT(YEAR FROM NOW()) - 1 END);
    v_start := make_date(v_year, 4, 1);
    v_end := make_date(v_year + 1, 3, 31);
    RETURN utils.success_response(jsonb_build_object('start_date', v_start, 'end_date', v_end, 'financial_year', v_year));
EXCEPTION WHEN OTHERS THEN RETURN utils.database_error_response('Failed to get financial year dates', SQLERRM, SQLSTATE);
END;
$$;


CREATE FUNCTION public.get_grn_autocomplete(p_search_query text, p_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_result jsonb;
      v_user_role text;
      v_user_customer_ids uuid[];
      v_search_pattern text;
      v_items jsonb;
      v_customers jsonb;
      v_grn_numbers jsonb;
  BEGIN
      -- Security: Get user role and accessible customers
      SELECT role INTO v_user_role FROM user_profiles
      WHERE auth_user_id = auth.uid();

      -- If user is not admin/supervisor, get their assigned customers
      IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
          v_user_customer_ids := user_accessible_customers();

          -- If no accessible customers, return empty result
          IF v_user_customer_ids IS NULL OR array_length(v_user_customer_ids, 1) IS NULL THEN
              RETURN jsonb_build_object(
                  'success', false,
                  'data', null,
                  'message', 'Access denied: No accessible customers found'
              );
          END IF;
      END IF;

      -- Prepare search pattern (case-insensitive)
      v_search_pattern := '%' || LOWER(TRIM(p_search_query)) || '%';

      -- Validate limit
      IF p_limit < 1 OR p_limit > 50 THEN
          p_limit := 10;
      END IF;

      -- Get matching items (ordered by usage frequency)
      SELECT jsonb_agg(
          jsonb_build_object(
              'value', item_data.item_name,
              'label', item_data.item_name,
              'type', 'item',
              'count', item_data.usage_count,
              'metadata', jsonb_build_object(
                  'item_id', item_data.item_id,
                  'total_qty', item_data.total_qty,
                  'total_stock', item_data.total_stock
              )
          ) ORDER BY item_data.usage_count DESC, item_data.item_name
      ) INTO v_items
      FROM (
          SELECT DISTINCT
              grt.item_name,
              grt.item_id,
              COUNT(*) OVER (PARTITION BY grt.item_name) as usage_count,
              SUM(grt.qty) OVER (PARTITION BY grt.item_name) as total_qty,
              SUM(grt.stock) OVER (PARTITION BY grt.item_name) as total_stock
          FROM goodsreceived_trl grt
          JOIN goodsreceived gr ON grt.gr_id = gr.id
          WHERE LOWER(grt.item_name) LIKE v_search_pattern
          AND (v_user_role IN ('admin', 'supervisor', 'staff') OR gr.customer_id = ANY(v_user_customer_ids))
          LIMIT p_limit
      ) item_data;

      -- Get matching customers (ordered by GRN count)
      SELECT jsonb_agg(
          jsonb_build_object(
              'value', customer_data.customer_name,
              'label', customer_data.customer_name || ' (' || customer_data.grn_count || ' GRNs)',
              'type', 'customer',
              'count', customer_data.grn_count,
              'metadata', jsonb_build_object(
                  'customer_id', customer_data.customer_id,
                  'last_grn_date', customer_data.last_grn_date
              )
          ) ORDER BY customer_data.grn_count DESC, customer_data.customer_name
      ) INTO v_customers
      FROM (
          SELECT DISTINCT
              c.id as customer_id,
              c.name as customer_name,
              COUNT(DISTINCT gr.id) as grn_count,
              MAX(gr.date) as last_grn_date
          FROM customers c
          LEFT JOIN goodsreceived gr ON c.id = gr.customer_id
          WHERE LOWER(c.name) LIKE v_search_pattern
          AND (v_user_role IN ('admin', 'supervisor', 'staff') OR c.id = ANY(v_user_customer_ids))
          GROUP BY c.id, c.name
          LIMIT p_limit
      ) customer_data;

      -- Get matching GRN numbers (ordered by date desc)
      SELECT jsonb_agg(
          jsonb_build_object(
              'value', grn_data.gr_no,
              'label', grn_data.gr_no || ' - ' || grn_data.customer_name || ' (' || TO_CHAR(grn_data.date, 'DD/MM/YYYY') || ')',
              'type', 'grn',
              'count', 1,
              'metadata', jsonb_build_object(
                  'grn_id', grn_data.id,
                  'customer_name', grn_data.customer_name,
                  'date', grn_data.date,
                  'item_count', grn_data.item_count,
                  'invoiced', grn_data.invoiced
              )
          ) ORDER BY grn_data.date DESC
      ) INTO v_grn_numbers
      FROM (
          SELECT DISTINCT
              gr.id,
              gr.gr_no,
              gr.customer_name,
              gr.date,
              gr.invoiced,
              COUNT(grt.id) as item_count
          FROM goodsreceived gr
          LEFT JOIN goodsreceived_trl grt ON gr.id = grt.gr_id
          WHERE LOWER(gr.gr_no) LIKE v_search_pattern
          AND (v_user_role IN ('admin', 'supervisor', 'staff') OR gr.customer_id = ANY(v_user_customer_ids))
          GROUP BY gr.id, gr.gr_no, gr.customer_name, gr.date, gr.invoiced
          LIMIT p_limit
      ) grn_data;

      -- Build result with grouped sections
      v_result := jsonb_build_object(
          'success', true,
          'data', jsonb_build_object(
              'items', COALESCE(v_items, '[]'::jsonb),
              'customers', COALESCE(v_customers, '[]'::jsonb),
              'grn_numbers', COALESCE(v_grn_numbers, '[]'::jsonb),
              'summary', jsonb_build_object(
                  'total_results',
                      COALESCE(jsonb_array_length(v_items), 0) +
                      COALESCE(jsonb_array_length(v_customers), 0) +
                      COALESCE(jsonb_array_length(v_grn_numbers), 0),
                  'item_count', COALESCE(jsonb_array_length(v_items), 0),
                  'customer_count', COALESCE(jsonb_array_length(v_customers), 0),
                  'grn_count', COALESCE(jsonb_array_length(v_grn_numbers), 0)
              ),
              'query', p_search_query,
              'limit', p_limit
          ),
          'message', 'Autocomplete results retrieved successfully'
      );

      RETURN v_result;

  EXCEPTION
      WHEN OTHERS THEN
          RETURN jsonb_build_object(
              'success', false,
              'data', null,
              'message', 'Error retrieving autocomplete results: ' || SQLERRM,
              'error', jsonb_build_object(
                  'code', SQLSTATE,
                  'message', SQLERRM
              )
          );
  END;
  $$;


CREATE FUNCTION public.get_grn_by_number(p_gr_no_pattern text, p_limit integer DEFAULT 1) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    SELECT COALESCE(jsonb_agg(grn_data), '[]'::jsonb)
    INTO v_result
    FROM (
        SELECT jsonb_build_object(
            'id', gr.id,
            'gr_no', gr.gr_no,
            'registration', gr.registration,
            'date', gr.date,
            'customer_id', gr.customer_id,
            'customer_name', gr.customer_name,
            'supervisor_id', gr.supervisor_id,
            'supervisor_name', gr.supervisor_name,
            'note', gr.note,
            'leon', gr.leon,
            'out_of_stock', gr.out_of_stock,
            'invoiced', gr.invoiced,
            'pricing_mode', gr.pricing_mode,
            'created_at', gr.created_at,
            'updated_at', gr.updated_at,
            'items', (
                SELECT COALESCE(jsonb_agg(jsonb_build_object(
                    'id', gt.id, 'item_id', gt.item_id, 'item_name', i.name,
                    'qty', gt.qty, 'stock', gt.stock, 'weight', gt.weight,
                    'package_mark', gt.package_mark, 'packaging', i.packaging, 'rack', gt.rack
                )), '[]'::jsonb)
                FROM goodsreceived_trl gt
                JOIN items i ON gt.item_id = i.id
                WHERE gt.gr_id = gr.id
            )
        ) as grn_data
        FROM goodsreceived gr
        WHERE gr.gr_no ILIKE p_gr_no_pattern || '%'
          AND gr.deleted_at IS NULL
        ORDER BY gr.date DESC
        LIMIT p_limit
    ) sub;

    RETURN utils.success_response(v_result);
EXCEPTION
    WHEN OTHERS THEN
        RETURN utils.database_error_response('Failed to get GRN by number', SQLERRM, SQLSTATE);
END;
$$;


CREATE FUNCTION public.get_grn_details(p_grn_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    DECLARE
        v_user_id uuid;
        v_role text;
        v_result jsonb;
    BEGIN
        v_user_id := auth.uid();

        SELECT role INTO v_role
        FROM user_profiles
        WHERE auth_user_id = v_user_id;

        SELECT jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'grn', jsonb_build_object(
                    'id', gr.id,
                    'gr_no', gr.gr_no,
                    'date', gr.date,
                    'registration', gr.registration,
                    'note', gr.note,
                    'gr_image_url', gr.gr_image_url,
                    'invoiced', COALESCE(gr.invoiced, false),
                    'leon', COALESCE(gr.leon, false),
                    'out_of_stock', COALESCE(gr.out_of_stock, false),
                    'pricing_mode', gr.pricing_mode,
                    'duration_mode', gr.duration_mode,
                    'created_at', gr.created_at,
                    'updated_at', gr.updated_at,

                    'header_images', COALESCE(
                        (
                            SELECT jsonb_agg(
                                jsonb_build_object(
                                    'id', gi.id,
                                    'storage_path', gi.storage_path,
                                    'image_url', gi.storage_path,
                                    'original_filename', gi.original_filename,
                                    'file_size', gi.file_size,
                                    'mime_type', gi.mime_type,
                                    'display_order', gi.display_order,
                                    'uploaded_by', gi.uploaded_by,
                                    'created_at', gi.created_at
                                )
                                ORDER BY gi.display_order, gi.created_at
                            )
                            FROM grn_images gi
                            WHERE gi.grn_id = gr.id
                            AND gi.image_type = 'header'
                        ),
                        '[]'::jsonb
                    ),

                    'customer_details', CASE
                        WHEN c.id IS NOT NULL THEN jsonb_build_object(
                            'id', c.id,
                            'name', c.name,
                            'first_name', c."firstName",
                            'last_name', c."lastName",
                            'gst', c.gst,
                            'mobile', c.mobile,
                            'address', c.address,
                            'city', c.city,
                            'state', c.state,
                            'pincode', c.pincode,
                            'email', c.email,
                            'active', c.active,
                            'auto_invoice_generation', c.auto_invoice_generation
                        )
                        ELSE null
                    END,

                    'supervisor_details', CASE
                        WHEN u.id IS NOT NULL THEN jsonb_build_object(
                            'id', u.id,
                            'name', u.name,
                            'mobile', u.mobile,
                            'role', u.role,
                            'display_name', u.display_name
                        )
                        ELSE null
                    END,

                    'sender_details', jsonb_build_object(
                        'id', gr.sender_id,
                        'name', gr.sender_name
                    ),

                    'items', COALESCE(
                        (
                            SELECT jsonb_agg(
                                jsonb_build_object(
                                    'id', grt.id,
                                    'qty', grt.qty,
                                    'stock', grt.stock,
                                    'weight', grt.weight,
                                    'rack', grt.rack,
                                    'package_mark', grt.package_mark,
                                    'item_name', grt.item_name,
                                    'packaging', grt.packaging,
                                    'pricing_mode', gr.pricing_mode,
                                    'trl_img_url', grt.trl_img_url,
                                    'item_images', COALESCE(
                                        (
                                            SELECT jsonb_agg(
                                                jsonb_build_object(
                                                    'id', gi2.id,
                                                    'storage_path', gi2.storage_path,
                                                    'image_url', gi2.storage_path,
                                                    'original_filename', gi2.original_filename,
                                                    'file_size', gi2.file_size,
                                                    'mime_type', gi2.mime_type,
                                                    'display_order', gi2.display_order,
                                                    'uploaded_by', gi2.uploaded_by,
                                                    'created_at', gi2.created_at
                                                )
                                                ORDER BY gi2.display_order, gi2.created_at
                                            )
                                            FROM grn_images gi2
                                            WHERE gi2.grn_id = gr.id
                                            AND gi2.grn_item_id = grt.id
                                            AND gi2.image_type = 'item'
                                        ),
                                        '[]'::jsonb
                                    ),
                                    'item_details', CASE
                                        WHEN i.id IS NOT NULL THEN jsonb_build_object(
                                            'id', i.id,
                                            'name', i.name,
                                            'packaging', i.packaging,
                                            'description', i.description,
                                            'active', i.active
                                        )
                                        ELSE null
                                    END
                                )
                                ORDER BY grt.id
                            )
                            FROM goodsreceived_trl grt
                            LEFT JOIN items i ON grt.item_id = i.id
                            WHERE grt.gr_id = gr.id
                        ),
                        '[]'::jsonb
                    ),

                    'statistics', (
                        SELECT jsonb_build_object(
                            'total_items', COUNT(DISTINCT grt.item_id),
                            'total_qty', COALESCE(SUM(grt.qty), 0),
                            'total_stock', COALESCE(SUM(grt.stock), 0),
                            'total_weight', COALESCE(SUM(grt.weight), 0),
                            'total_dispatched', COALESCE(
                                (
                                    SELECT SUM(dt.disp_qty)
                                    FROM dispatch_trl dt
                                    WHERE dt.gr_trl_id IN (
                                        SELECT id FROM goodsreceived_trl
                                        WHERE gr_id = gr.id
                                    )
                                ), 0
                            ),
                            'has_out_of_stock', EXISTS(
                                SELECT 1 FROM goodsreceived_trl
                                WHERE gr_id = gr.id AND stock <= 0
                            )
                        )
                        FROM goodsreceived_trl grt
                        WHERE grt.gr_id = gr.id
                    ),

                    'invoices_summary', (
                        SELECT jsonb_build_object(
                            'total_invoices', COUNT(DISTINCT inv.id),
                            'total_amount', COALESCE(SUM(inv.total), 0),
                            'invoice_numbers', COALESCE(
                                jsonb_agg(
                                    DISTINCT inv.inv_no
                                    ORDER BY inv.inv_no
                                ) FILTER (WHERE inv.inv_no IS NOT NULL),
                                '[]'::jsonb
                            )
                        )
                        FROM invoice inv
                        WHERE inv.gr_id = gr.id
                    ),

                    'dispatches_summary', (
                        SELECT jsonb_build_object(
                            'total_dispatches', COUNT(DISTINCT d.id),
                            'dispatch_numbers', COALESCE(
                                jsonb_agg(
                                    DISTINCT d.disp_no
                                    ORDER BY d.disp_no
                                ) FILTER (WHERE d.disp_no IS NOT NULL),
                                '[]'::jsonb
                            )
                        )
                        FROM dispatch d
                        WHERE EXISTS (
                            SELECT 1
                            FROM dispatch_trl dt
                            JOIN goodsreceived_trl grt ON dt.gr_trl_id = grt.id
                            WHERE grt.gr_id = gr.id
                            AND dt.disp_id = d.id
                        )
                    )
                )
            ),
            'message', 'GRN details retrieved successfully'
        ) INTO v_result
        FROM goodsreceived gr
        LEFT JOIN customers c ON gr.customer_id = c.id
        LEFT JOIN user_profiles u ON gr.supervisor_id = u.id
        WHERE gr.id = p_grn_id
        AND (
            v_role IN ('admin', 'supervisor', 'staff') OR
            gr.customer_id IN (
                SELECT customer_id FROM users_customers_new
                WHERE user_profile_id = (SELECT id FROM user_profiles WHERE auth_user_id = v_user_id)
            )
        );

        IF v_result IS NULL THEN
            RETURN jsonb_build_object(
                'success', false,
                'data', null,
                'message', 'GRN not found or access denied'
            );
        END IF;

        RETURN v_result;

    EXCEPTION
        WHEN OTHERS THEN
            RETURN jsonb_build_object(
                'success', false,
                'data', null,
                'message', 'Error retrieving GRN details: ' || SQLERRM
            );
    END;
    $$;


CREATE FUNCTION public.get_grn_invoices(p_grn_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_user_role text;
      v_user_customer_ids uuid[];
      v_has_access boolean := false;
      v_invoices jsonb;
      v_summary jsonb;
      v_result jsonb;
  BEGIN
      -- Get user role and customer access
      SELECT role INTO v_user_role FROM user_profiles
      WHERE auth_user_id = auth.uid();

      -- Get user's accessible customers (for non-admin users)
      IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
          SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
          FROM user_customers
          WHERE user_id = (SELECT id FROM user_profiles WHERE auth_user_id = auth.uid());
      END IF;

      -- Validate GRN ID
      IF p_grn_id IS NULL THEN
          RETURN jsonb_build_object(
              'success', false,
              'error', 'GRN ID is required',
              'code', 'INVALID_PARAMETERS'
          );
      END IF;

      -- Check user access to this GRN
      SELECT EXISTS(
          SELECT 1 FROM goodsreceived gr
          WHERE gr.id = p_grn_id
          AND (v_user_role IN ('admin', 'supervisor', 'staff') OR
               (v_user_customer_ids IS NOT NULL AND gr.customer_id = ANY(v_user_customer_ids)))
      ) INTO v_has_access;

      IF NOT v_has_access THEN
          RETURN jsonb_build_object(
              'success', false,
              'error', 'GRN not found or access denied',
              'code', 'ACCESS_DENIED'
          );
      END IF;

      -- Get invoices for this GRN (NO GROUP BY needed here)
      SELECT jsonb_agg(
          jsonb_build_object(
              'id', inv.id,
              'invoice_no', CONCAT('INV-', inv.inv_fin_year, '-', inv.inv_fin_year + 1, '-', LPAD(inv.inv_no::text, 4, '0')),
              'invoice_date', inv.inv_date,
              'amount', inv.total - COALESCE(inv.discount, 0) - COALESCE(inv.labour, 0) - COALESCE(inv.tax_amount, 0),
              'customer_name', inv.customer_name,
              'grn_id', inv.gr_id,
              'grn_no', inv.gr_no,
              'status', 'pending',
              'discount', inv.discount,
              'labour', inv.labour,
              'tax_amount', inv.tax_amount,
              'total', inv.total,
              'one_time_charge', inv.one_time_charge
          ) ORDER BY inv.inv_date DESC
      ) INTO v_invoices
      FROM invoice inv
      WHERE inv.gr_id = p_grn_id;

      -- Generate summary (separate query for aggregation)
      SELECT jsonb_build_object(
          'total_invoices', COUNT(*),
          'total_amount', COALESCE(SUM(inv.total), 0),
          'paid_amount', 0,
          'pending_amount', COALESCE(SUM(inv.total), 0)
      ) INTO v_summary
      FROM invoice inv
      WHERE inv.gr_id = p_grn_id;

      -- Build response
      v_result := jsonb_build_object(
          'success', true,
          'data', jsonb_build_object(
              'invoices', COALESCE(v_invoices, '[]'::jsonb),
              'summary', v_summary
          ),
          'message', 'GRN invoices retrieved successfully'
      );

      RETURN v_result;

  EXCEPTION
      WHEN OTHERS THEN
          RETURN jsonb_build_object(
              'success', false,
              'error', 'Failed to get GRN invoices: ' || SQLERRM,
              'code', 'DATABASE_ERROR'
          );
  END;
  $$;


CREATE FUNCTION public.get_grn_item_dispatches(p_grn_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_user_role text;
      v_user_customer_ids uuid[];
      v_has_access boolean := false;
      v_dispatches jsonb;
      v_summary jsonb;
      v_result jsonb;
  BEGIN
      -- Get user role and customer access
      SELECT role INTO v_user_role FROM user_profiles
      WHERE auth_user_id = auth.uid();

      -- Get user's accessible customers (for non-admin users)
      IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
          SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
          FROM user_customers
          WHERE user_id = (SELECT id FROM user_profiles WHERE auth_user_id = auth.uid());
      END IF;

      -- Validate GRN item ID
      IF p_grn_item_id IS NULL THEN
          RETURN jsonb_build_object(
              'success', false,
              'error', 'GRN item ID is required',
              'code', 'INVALID_PARAMETERS'
          );
      END IF;

      -- Check user access to this GRN item
      SELECT EXISTS(
          SELECT 1 FROM goodsreceived_trl grt
          JOIN goodsreceived gr ON grt.gr_id = gr.id
          WHERE grt.id = p_grn_item_id
          AND (v_user_role IN ('admin', 'supervisor', 'staff') OR
               (v_user_customer_ids IS NOT NULL AND gr.customer_id = ANY(v_user_customer_ids)))
      ) INTO v_has_access;

      IF NOT v_has_access THEN
          RETURN jsonb_build_object(
              'success', false,
              'error', 'GRN item not found or access denied',
              'code', 'ACCESS_DENIED'
          );
      END IF;

      -- Get dispatches for this GRN item (snake_case field names)
      SELECT jsonb_agg(
          jsonb_build_object(
              'id', dt.id,
              'dispatch_id', dt.disp_id,
              'disp_no', d.disp_no,
              'disp_quantity', dt.disp_qty,
              'disp_date', d.disp_date,
              'customer_name', d.customer_name,
              'registration', d.registration,
              'supervisor_name', d.supervisor_name,
              'note', d.note
          ) ORDER BY d.disp_date DESC
      ) INTO v_dispatches
      FROM dispatch_trl dt
      JOIN dispatch d ON dt.disp_id = d.id
      WHERE dt.gr_trl_id = p_grn_item_id;

      -- Generate summary (snake_case field names)
      WITH item_info AS (
          SELECT grt.stock, grt.qty
          FROM goodsreceived_trl grt
          WHERE grt.id = p_grn_item_id
      )
      SELECT jsonb_build_object(
          'total_dispatches', COUNT(dt.id),
          'total_dispatched_qty', COALESCE(SUM(dt.disp_qty), 0),
          'remaining_stock', (SELECT stock FROM item_info)
      ) INTO v_summary
      FROM dispatch_trl dt
      WHERE dt.gr_trl_id = p_grn_item_id;

      -- Build response
      v_result := jsonb_build_object(
          'success', true,
          'data', jsonb_build_object(
              'dispatches', COALESCE(v_dispatches, '[]'::jsonb),
              'summary', v_summary
          ),
          'message', 'GRN item dispatches retrieved successfully'
      );

      RETURN v_result;

  EXCEPTION
      WHEN OTHERS THEN
          RETURN jsonb_build_object(
              'success', false,
              'error', 'Failed to get GRN item dispatches: ' || SQLERRM,
              'code', 'DATABASE_ERROR'
          );
  END;
  $$;


CREATE FUNCTION public.get_grn_items(p_grn_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_user_role text;
      v_user_customer_ids uuid[];
      v_has_access boolean := false;
      v_items jsonb;
      v_summary jsonb;
      v_result jsonb;
  BEGIN
      -- Get user role and customer access
      SELECT role INTO v_user_role FROM user_profiles
      WHERE auth_user_id = auth.uid();

      -- Get user's accessible customers (for non-admin users)
      IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
          SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
          FROM user_customers
          WHERE user_id = (SELECT id FROM user_profiles WHERE auth_user_id = auth.uid());
      END IF;

      -- Validate GRN ID
      IF p_grn_id IS NULL THEN
          RETURN jsonb_build_object(
              'success', false,
              'error', 'GRN ID is required',
              'code', 'INVALID_PARAMETERS'
          );
      END IF;

      -- Check user access to this GRN
      SELECT EXISTS(
          SELECT 1 FROM goodsreceived gr
          WHERE gr.id = p_grn_id
          AND (v_user_role IN ('admin', 'supervisor', 'staff') OR
               (v_user_customer_ids IS NOT NULL AND gr.customer_id = ANY(v_user_customer_ids)))
      ) INTO v_has_access;

      IF NOT v_has_access THEN
          RETURN jsonb_build_object(
              'success', false,
              'error', 'GRN not found or access denied',
              'code', 'ACCESS_DENIED'
          );
      END IF;

      -- Get GRN items (snake_case field names)
      SELECT jsonb_agg(
          jsonb_build_object(
              'id', grt.id,
              'item_id', grt.item_id,
              'item_name', grt.item_name,
              'qty', grt.qty,
              'stock', grt.stock,
              'weight', grt.weight,
              'rack', grt.rack,
              'package_mark', grt.package_mark,
              'packaging', grt.packaging,
              'grn_id', grt.gr_id,
              'grn_no', gr.gr_no,
              'trl_img_url', grt.trl_img_url
          ) ORDER BY grt.item_name
      ) INTO v_items
      FROM goodsreceived_trl grt
      JOIN goodsreceived gr ON grt.gr_id = gr.id
      WHERE grt.gr_id = p_grn_id;

      -- Generate summary (snake_case field names)
      SELECT jsonb_build_object(
          'total_items', COUNT(*),
          'total_qty', COALESCE(SUM(grt.qty), 0),
          'total_weight', COALESCE(SUM(grt.weight), 0),
          'total_stock', COALESCE(SUM(grt.stock), 0)
      ) INTO v_summary
      FROM goodsreceived_trl grt
      WHERE grt.gr_id = p_grn_id;

      -- Build response
      v_result := jsonb_build_object(
          'success', true,
          'data', jsonb_build_object(
              'items', COALESCE(v_items, '[]'::jsonb),
              'summary', v_summary
          ),
          'message', 'GRN items retrieved successfully'
      );

      RETURN v_result;

  EXCEPTION
      WHEN OTHERS THEN
          RETURN jsonb_build_object(
              'success', false,
              'error', 'Failed to get GRN items: ' || SQLERRM,
              'code', 'DATABASE_ERROR'
          );
  END;
  $$;


CREATE FUNCTION public.get_grn_items_by_id(p_grn_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_items jsonb;
BEGIN
    IF NOT EXISTS(SELECT 1 FROM goodsreceived WHERE id = p_grn_id) THEN
        RETURN utils.not_found_response('GRN', p_grn_id::text);
    END IF;

    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'id', gt.id,
                'gr_id', gt.gr_id,
                'item_id', gt.item_id,
                'item_name', i.name,
                'qty', gt.qty,
                'stock', gt.stock,
                'weight', gt.weight,
                'package_mark', gt.package_mark,
                'packaging', i.packaging,
                'rack', gt.rack,
                'trl_img_url', gt.trl_img_url
            )
        ),
        '[]'::jsonb
    ) INTO v_items
    FROM goodsreceived_trl gt
    JOIN items i ON gt.item_id = i.id
    WHERE gt.gr_id = p_grn_id;

    RETURN utils.success_response(v_items);
EXCEPTION
    WHEN OTHERS THEN
        RETURN utils.database_error_response('Failed to get GRN items', SQLERRM, SQLSTATE);
END;
$$;


CREATE FUNCTION public.get_grn_list(p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_sort_by text DEFAULT 'date'::text, p_sort_order text DEFAULT 'desc'::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_filters jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$

DECLARE
    v_user_role text;
    v_user_customer_ids uuid[];
    v_order_direction text;
    v_result jsonb;
    v_where_clauses text[] := ARRAY[]::text[];
    v_sql text;
    v_order_clause text;
    v_grn_search text;
BEGIN
    -- Validate and normalize p_limit
    IF p_limit IS NULL OR p_limit < 1 THEN
        p_limit := 50;
    ELSIF p_limit > 200 THEN
        p_limit := 200;
    END IF;

    -- Validate and normalize p_offset
    IF p_offset IS NULL OR p_offset < 0 THEN
        p_offset := 0;
    END IF;

    -- Validate sort_by
    IF p_sort_by NOT IN ('date', 'gr_no', 'customer', 'qty', 'stock', 'weight') THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Invalid sort field',
            'data', null,
            'error', jsonb_build_object(
                'code', 'INVALID_SORT_FIELD',
                'details', 'Sort field must be one of: date, gr_no, customer, qty, stock, weight'
            )
        );
    END IF;

    -- Validate sort_order
    IF p_sort_order NOT IN ('asc', 'desc') THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Invalid sort order',
            'data', null,
            'error', jsonb_build_object(
                'code', 'INVALID_SORT_ORDER',
                'details', 'Sort order must be asc or desc'
            )
        );
    END IF;

    -- Validate date range
    IF p_date_from IS NOT NULL AND p_date_to IS NOT NULL AND p_date_from > p_date_to THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Date range invalid',
            'data', null,
            'error', jsonb_build_object(
                'code', 'INVALID_DATE_RANGE',
                'details', 'Date from must be before or equal to date to'
            )
        );
    END IF;

    -- Get user role and accessible customers for security
    SELECT role INTO v_user_role FROM user_profiles
    WHERE auth_user_id = auth.uid();

    -- If user is not admin/supervisor, get their assigned customers
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        v_user_customer_ids := user_accessible_customers();

        IF v_user_customer_ids IS NULL OR array_length(v_user_customer_ids, 1) IS NULL THEN
            RETURN jsonb_build_object(
                'success', false,
                'message', 'Access denied: No accessible customers found',
                'data', null
            );
        END IF;
    END IF;

    -- Build WHERE clauses for filters
    -- Date filters
    IF p_date_from IS NOT NULL THEN
        v_where_clauses := array_append(v_where_clauses, format('gr.date >= %L', p_date_from));
    END IF;

    IF p_date_to IS NOT NULL THEN
        v_where_clauses := array_append(v_where_clauses, format('gr.date <= %L', p_date_to));
    END IF;

    -- Security filter
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        v_where_clauses := array_append(v_where_clauses,
            format('gr.customer_id = ANY(ARRAY[%s]::uuid[])',
                (SELECT string_agg(quote_literal(id::text), ',') FROM unnest(v_user_customer_ids) id)
            )
        );
    END IF;

    -- FIXED: GRN number PREFIX search - Accept both 'gr_no' (documented) and 'search_grn_no' (legacy)
    v_grn_search := COALESCE(
        trim(p_filters->>'gr_no'),
        trim(p_filters->>'search_grn_no')
    );

    IF v_grn_search IS NOT NULL AND v_grn_search != '' THEN
        v_where_clauses := array_append(v_where_clauses,
            format('gr.gr_no ILIKE %L', v_grn_search || '%')  -- PREFIX matching for autocomplete
        );
    END IF;

    -- Customer name search filter (CONTAINS is fine for names)
    IF p_filters ? 'search_customer' AND (p_filters->>'search_customer') IS NOT NULL AND trim(p_filters->>'search_customer') != '' THEN
        v_where_clauses := array_append(v_where_clauses,
            format('gr.customer_name ILIKE %L', '%' || trim(p_filters->>'search_customer') || '%')
        );
    END IF;

    -- Customer IDs filter
    IF p_filters ? 'customer_ids' AND jsonb_array_length(p_filters->'customer_ids') > 0 THEN
        v_where_clauses := array_append(v_where_clauses,
            format('gr.customer_id = ANY(ARRAY[%s]::uuid[])',
                (SELECT string_agg(quote_literal(value::text), ',')
                 FROM jsonb_array_elements_text(p_filters->'customer_ids') value)
            )
        );
    END IF;

    -- GRN IDs filter
    IF p_filters ? 'grn_ids' AND jsonb_array_length(p_filters->'grn_ids') > 0 THEN
        v_where_clauses := array_append(v_where_clauses,
            format('gr.id = ANY(ARRAY[%s]::uuid[])',
                (SELECT string_agg(quote_literal(value::text), ',')
                 FROM jsonb_array_elements_text(p_filters->'grn_ids') value)
            )
        );
    END IF;

    -- Invoiced filter
    IF p_filters ? 'invoiced' THEN
        v_where_clauses := array_append(v_where_clauses,
            format('gr.invoiced = %L', (p_filters->>'invoiced')::boolean)
        );
    END IF;

    -- Out of stock filter
    IF p_filters ? 'out_of_stock' THEN
        IF (p_filters->>'out_of_stock')::boolean THEN
            v_where_clauses := array_append(v_where_clauses,
                'NOT EXISTS (SELECT 1 FROM goodsreceived_trl WHERE gr_id = gr.id AND stock > 0)'
            );
        END IF;
    END IF;

    -- Supervisor IDs filter
    IF p_filters ? 'supervisor_ids' AND jsonb_array_length(p_filters->'supervisor_ids') > 0 THEN
        v_where_clauses := array_append(v_where_clauses,
            format('gr.supervisor_id = ANY(ARRAY[%s]::uuid[])',
                (SELECT string_agg(quote_literal(value::text), ',')
                 FROM jsonb_array_elements_text(p_filters->'supervisor_ids') value)
            )
        );
    END IF;

    -- Build ORDER BY clause
    v_order_direction := UPPER(p_sort_order);

    v_order_clause := CASE p_sort_by
        WHEN 'date' THEN format('ga.date %s', v_order_direction)
        WHEN 'gr_no' THEN format(
            '(CASE WHEN SUBSTRING(ga.gr_no FROM 1 FOR 1) >= ''X''
                  THEN ASCII(SUBSTRING(ga.gr_no FROM 1 FOR 1)) - ASCII(''X'')
                  ELSE ASCII(SUBSTRING(ga.gr_no FROM 1 FOR 1)) - ASCII(''A'') + 3
             END * 10000 + COALESCE(CAST(NULLIF(SUBSTRING(ga.gr_no FROM 2), '''') AS INTEGER), 0)) %s',
            v_order_direction)
        WHEN 'customer' THEN format('ga.customer_name %s', v_order_direction)
        WHEN 'qty' THEN format('ga.total_qty %s', v_order_direction)
        WHEN 'stock' THEN format('ga.total_stock %s', v_order_direction)
        WHEN 'weight' THEN format('ga.total_weight %s', v_order_direction)
        ELSE format('ga.date %s', v_order_direction)
    END;

    -- Build dynamic SQL query
    v_sql := format('
        WITH filtered_grns AS (
            SELECT gr.*
            FROM goodsreceived gr
            %s
        ),
        grn_aggregates AS (
            SELECT
                fg.id,
                fg.gr_no,
                fg.date,
                fg.customer_name,
                fg.customer_id,
                fg.supervisor_name,
                fg.supervisor_id,
                fg.invoiced,
                COALESCE(SUM(trl.qty), 0) AS total_qty,
                COALESCE(SUM(trl.stock), 0) AS total_stock,
                COALESCE(SUM(trl.weight * trl.stock), 0) AS total_weight,
                COUNT(trl.id) AS items_count
            FROM filtered_grns fg
            LEFT JOIN goodsreceived_trl trl ON fg.id = trl.gr_id
            GROUP BY fg.id, fg.gr_no, fg.date, fg.customer_name, fg.customer_id,
                     fg.supervisor_name, fg.supervisor_id, fg.invoiced
        )
        SELECT
            jsonb_build_object(
                ''grns'', (
                    SELECT COALESCE(jsonb_agg(grn_data), ''[]''::jsonb)
                    FROM (
                        SELECT
                            jsonb_build_object(
                                ''id'', ga.id,
                                ''gr_no'', ga.gr_no,
                                ''date'', ga.date,
                                ''customer_name'', ga.customer_name,
                                ''customer_id'', ga.customer_id,
                                ''supervisor_name'', ga.supervisor_name,
                                ''supervisor_id'', ga.supervisor_id,
                                ''invoiced'', ga.invoiced,
                                ''items_count'', ga.items_count,
                                ''total_qty'', ga.total_qty,
                                ''total_stock'', ga.total_stock,
                                ''total_weight'', ga.total_weight
                            ) AS grn_data
                        FROM grn_aggregates ga
                        ORDER BY %s
                        LIMIT %s OFFSET %s
                    ) grns_list
                ),
                ''pagination'', jsonb_build_object(
                    ''total_count'', (SELECT COUNT(*) FROM filtered_grns),
                    ''limit'', %s,
                    ''offset'', %s,
                    ''has_more'', (SELECT COUNT(*) FROM filtered_grns) > (%s + %s)
                ),
                ''summary'', jsonb_build_object(
                    ''total_grns'', (SELECT COUNT(*) FROM filtered_grns),
                    ''total_items'', (SELECT COALESCE(SUM(items_count), 0) FROM grn_aggregates),
                    ''total_qty'', (SELECT COALESCE(SUM(total_qty), 0) FROM grn_aggregates),
                    ''total_stock'', (SELECT COALESCE(SUM(total_stock), 0) FROM grn_aggregates),
                    ''total_weight'', (SELECT COALESCE(SUM(total_weight), 0) FROM grn_aggregates)
                ),
                ''filters_applied'', %L
            ) AS result
    ',
        CASE
            WHEN array_length(v_where_clauses, 1) > 0
            THEN 'WHERE ' || array_to_string(v_where_clauses, ' AND ')
            ELSE ''
        END,
        v_order_clause,
        p_limit,
        p_offset,
        p_limit,
        p_offset,
        p_offset,
        p_limit,
        p_filters::text
    );

    -- Execute dynamic query
    EXECUTE v_sql INTO v_result;

    -- Return success response
    RETURN jsonb_build_object(
        'success', true,
        'message', 'GRN list retrieved successfully',
        'data', v_result
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'message', 'Failed to retrieve GRN list',
        'data', null,
        'error', jsonb_build_object(
            'code', 'DATABASE_ERROR',
            'details', SQLERRM
        )
    );
END;

$$;


CREATE FUNCTION public.get_grn_prefixes_with_stock(p_customer_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object('prefix', prefix, 'grn_count', grn_count)
        ),
        '[]'::jsonb
    ) INTO v_result
    FROM (
        SELECT LEFT(gr.gr_no, 1) as prefix, COUNT(DISTINCT gr.id)::integer as grn_count
        FROM goodsreceived gr
        JOIN goodsreceived_trl gt ON gr.id = gt.gr_id
        WHERE gr.deleted_at IS NULL
          AND gt.stock > 0
          AND (p_customer_id IS NULL OR gr.customer_id = p_customer_id)
        GROUP BY LEFT(gr.gr_no, 1)
        ORDER BY prefix
    ) sub;

    RETURN utils.success_response(v_result);
EXCEPTION
    WHEN OTHERS THEN
        RETURN utils.database_error_response('Failed to get GRN prefixes', SQLERRM, SQLSTATE);
END;
$$;


CREATE FUNCTION public.get_grn_range_for_print(start_gr_no text, end_gr_no text, limit_count integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result jsonb;
    units TEXT[] := ARRAY['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten', 'Eleven', 'Twelve',
        'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen', 'Seventeen', 'Eighteen', 'Nineteen'];
    tens TEXT[] := ARRAY['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];
BEGIN
    WITH grn_data AS (
        SELECT
            gr.id as grn_id,
            gr.gr_no,
            TO_CHAR(gr.date, 'YYYY-MM-DD') as formatted_date,
            gr.registration,
            gr.customer_id::TEXT,
            gr.customer_name,
            gr.sender_id::TEXT,
            gr.sender_name,
            gr.supervisor_id::TEXT,
            gr.supervisor_name,
            gr.note,
            COALESCE(gr.leon, FALSE) as leon,
            COALESCE(gr.out_of_stock, FALSE) as out_of_stock,
            COALESCE(gr.invoiced, FALSE) as invoiced,
            gr.gr_image_url
        FROM goodsreceived gr
        WHERE gr.gr_no >= start_gr_no
          AND gr.gr_no <= end_gr_no
        ORDER BY gr.gr_no
        LIMIT limit_count
    ),
    grn_with_customer AS (
        SELECT
            gd.*,
            CASE WHEN c.id IS NOT NULL THEN
                jsonb_build_object(
                    'id', c.id::TEXT,
                    'first_name', c."firstName",
                    'last_name', c."lastName",
                    'address', c.address,
                    'city', c.city,
                    'mobile', c.mobile
                )
            ELSE NULL
            END as customer_data
        FROM grn_data gd
        LEFT JOIN customers c ON c.id = gd.customer_id::UUID
    ),
    trl_with_sr_no AS (
        SELECT
            gt.gr_id,
            gt.id as trl_id,
            gt.item_id,
            gt.item_name,
            gt.packaging,
            gt.qty,
            gt.stock,
            gt.weight,
            gt.rack,
            gt.package_mark,
            gt.trl_img_url,
            ROW_NUMBER() OVER (PARTITION BY gt.gr_id ORDER BY gt.id) as sr_no
        FROM goodsreceived_trl gt
        WHERE gt.gr_id IN (SELECT grn_id FROM grn_data)
    ),
    grn_with_trl AS (
        SELECT
            gwc.*,
            jsonb_agg(
                jsonb_build_object(
                    'id', tws.trl_id::TEXT,
                    'item_id', tws.item_id::TEXT,
                    'item_name', tws.item_name,
                    'packaging', tws.packaging,
                    'qty', COALESCE(tws.qty, 0),
                    'stock', COALESCE(tws.stock, 0),
                    'weight', COALESCE(tws.weight, 0),
                    'rack', tws.rack,
                    'package_mark', tws.package_mark,
                    'trl_img_url', tws.trl_img_url,
                    'sr_no', tws.sr_no
                ) ORDER BY tws.sr_no
            ) as trl_data,
            SUM(COALESCE(tws.qty, 0)) as total_quantity
        FROM grn_with_customer gwc
        LEFT JOIN trl_with_sr_no tws ON tws.gr_id = gwc.grn_id
        GROUP BY
            gwc.grn_id, gwc.gr_no, gwc.formatted_date, gwc.registration,
            gwc.customer_id, gwc.customer_name, gwc.sender_id, gwc.sender_name,
            gwc.supervisor_id, gwc.supervisor_name, gwc.note, gwc.leon,
            gwc.out_of_stock, gwc.invoiced, gwc.gr_image_url, gwc.customer_data
    ),
    final_result AS (
        SELECT jsonb_agg(
            jsonb_build_object(
                'id', gwt.grn_id,
                'gr_no', gwt.gr_no,
                'date', gwt.formatted_date,
                'registration', gwt.registration,
                'customer_id', gwt.customer_id,
                'customer_name', gwt.customer_name,
                'sender_id', gwt.sender_id,
                'sender_name', gwt.sender_name,
                'supervisor_id', gwt.supervisor_id,
                'supervisor_name', gwt.supervisor_name,
                'note', gwt.note,
                'leon', gwt.leon,
                'out_of_stock', gwt.out_of_stock,
                'invoiced', gwt.invoiced,
                'gr_image_url', gwt.gr_image_url,
                'customer', gwt.customer_data,
                'trl', gwt.trl_data,
                'total_qty', COALESCE(gwt.total_quantity, 0)::INTEGER,
                'total_qty_in_words', convert_number_to_words(COALESCE(gwt.total_quantity, 0)::INTEGER)
            ) ORDER BY gwt.gr_no
        ) as data
        FROM grn_with_trl gwt
    )
    SELECT COALESCE(data, '[]'::jsonb) INTO v_result FROM final_result;

    RETURN utils.success_response(v_result, NULL);
END;
$$;


CREATE FUNCTION public.get_grn_summary(p_gr_no_pattern text, p_limit integer DEFAULT 1) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_result JSONB;
BEGIN
    SELECT json_agg(result)::jsonb INTO v_result
    FROM (
        SELECT
            gr.id,
            gr.gr_no,
            gr.date,
            gr.customer_name,
            (SELECT COUNT(*) FROM goodsreceived_trl WHERE gr_id = gr.id) as item_count,
            (SELECT SUM(weight) FROM goodsreceived_trl WHERE gr_id = gr.id) as total_weight,
            (SELECT SUM(stock) FROM goodsreceived_trl WHERE gr_id = gr.id) as total_stock,
            (
                SELECT json_agg(
                    json_build_object(
                        'qty', qty,
                        'stock', stock,
                        'weight', weight
                    )
                )
                FROM goodsreceived_trl
                WHERE gr_id = gr.id
            ) as items
        FROM goodsreceived gr
        WHERE gr.gr_no ILIKE p_gr_no_pattern
        ORDER BY gr.date DESC, gr.gr_no DESC
        LIMIT p_limit
    ) result;

    RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


CREATE FUNCTION public.get_invoice_data(p_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    DECLARE
        v_user_role text;
        v_user_id uuid;
        v_invoice_header record;
        v_invoice_items jsonb[];
        v_item_record record;
        v_result jsonb;
    BEGIN
        SELECT id, role INTO v_user_id, v_user_role
        FROM user_profiles
        WHERE auth_user_id = auth.uid();

        IF v_user_role NOT IN ('admin', 'supervisor', 'staff') AND auth.uid() IS NOT NULL THEN
            IF NOT EXISTS (
                SELECT 1 FROM invoice i
                JOIN users_customers_new ucn ON ucn.customer_id = i.customer_id
                WHERE i.id = p_invoice_id
                AND ucn.user_profile_id = v_user_id
            ) THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'error', 'Access denied to this invoice'
                );
            END IF;
        END IF;

        SELECT
            i.id as invoice_id,
            i.inv_no as invoice_number,
            i.inv_date as invoice_date,
            i.inv_fin_year,
            i.inv_fin_year || '-' || (i.inv_fin_year + 1) as financial_year,
            i.gr_id,
            i.gr_no,
            i.customer_id,
            i.customer_name as invoice_customer_name,
            i.inv_name,
            i.one_time_charge,
            i.labour,
            i.tax_amount,
            i.total,
            i.discount,
            i.is_auto_generated,
            i.pricing_mode,
            COALESCE(i.duration_mode, 'legacy') as duration_mode,
            i.notes,
            i.created_by,

            c.address as customer_address,
            c.city as customer_city,
            c."firstName" as customer_firstName,
            c."lastName" as customer_lastName,
            c.mobile as customer_mobile,
            c.name as customer_name,
            c.pincode as customer_pincode,
            c.state as customer_state,
            c.telephone1 as customer_telephone1,
            c.telephone2 as customer_telephone2,
            c.gst as customer_gst,
            c.email as customer_email,
            c.active as customer_active,
            c.contact as customer_contact,
            c.pan as customer_pan,
            c.auto_invoice_generation as customer_auto_invoice_generation,
            c.created_at as customer_created_at,
            c.updated_at as customer_updated_at,

            gr.id as grn_id,
            gr.gr_no as grn_number,
            gr.registration as grn_registration,
            gr.date as grn_date,
            gr.sender_id as grn_sender_id,
            gr.sender_name as grn_sender_name,
            gr.customer_id as grn_customer_id,
            gr.customer_name as grn_customer_name,
            gr.supervisor_id as grn_supervisor_id,
            gr.supervisor_name as grn_supervisor_name,
            gr.note as grn_note,
            gr.leon as grn_leon,
            gr.out_of_stock as grn_out_of_stock,
            gr.invoiced as grn_invoiced,
            gr.gr_image_url,
            gr.created_by as grn_created_by,
            gr.updated_by as grn_updated_by,
            gr.created_at as grn_created_at,
            gr.updated_at as grn_updated_at,
            gr.pricing_mode as grn_pricing_mode,

            cb.name as created_by_name,
            cb.display_name as created_by_display_name,
            cb.role as created_by_role

        INTO v_invoice_header
        FROM invoice i
        JOIN customers c ON c.id = i.customer_id
        JOIN goodsreceived gr ON gr.id = i.gr_id
        LEFT JOIN user_profiles cb ON cb.id = i.created_by
        WHERE i.id = p_invoice_id;

        IF NOT FOUND THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'Invoice not found'
            );
        END IF;

        v_invoice_items := ARRAY[]::jsonb[];

        FOR v_item_record IN
            SELECT
                it.id as item_id,
                it.invoice_id,
                it.disp_trl_id,
                it.duration,
                it.no_of_days,
                it.charge,
                it.tax,
                it.labour_rate,

                dt.id as dispatch_item_id,
                dt.gr_id as dispatch_gr_id,
                dt.gr_trl_id as dispatch_gr_trl_id,
                dt.disp_id as dispatch_disp_id,
                dt.disp_qty as dispatch_quantity,

                d.disp_no as dispatch_no,
                d.disp_date as dispatch_date,

                grt.id as grn_item_id,
                grt.gr_id as grn_item_gr_id,
                grt.item_id as grn_item_item_id,
                grt.item_name as grn_item_name,
                grt.packaging as grn_item_packaging,
                grt.qty as grn_original_quantity,
                grt.stock as grn_current_stock,
                grt.weight as grn_weight,
                grt.rack as grn_rack,
                grt.package_mark as grn_package_mark,
                grt.trl_img_url as grn_item_image_url,
                gr.pricing_mode as grn_item_pricing_mode,

                items.id as catalog_id,
                items.name as catalog_name,
                items.packaging as catalog_packaging,
                items.description as catalog_description,
                items.active as catalog_active

            FROM invoice_trl it
            LEFT JOIN dispatch_trl dt ON dt.id = it.disp_trl_id
            LEFT JOIN dispatch d ON d.id = dt.disp_id
            LEFT JOIN goodsreceived_trl grt ON grt.id = dt.gr_trl_id
            LEFT JOIN goodsreceived gr ON gr.id = grt.gr_id
            LEFT JOIN items ON items.id = grt.item_id
            WHERE it.invoice_id = p_invoice_id
            ORDER BY it.id
        LOOP
            v_invoice_items := v_invoice_items || jsonb_build_object(
                'item_id', v_item_record.item_id,
                'invoice_id', v_item_record.invoice_id,
                'disp_trl_id', v_item_record.disp_trl_id,
                'duration', v_item_record.duration,
                'no_of_days', v_item_record.no_of_days,
                'charge', v_item_record.charge,
                'tax', v_item_record.tax,
                'labour_rate', v_item_record.labour_rate,

                'dispatch', jsonb_build_object(
                    'id', v_item_record.dispatch_item_id,
                    'gr_id', v_item_record.dispatch_gr_id,
                    'gr_trl_id', v_item_record.dispatch_gr_trl_id,
                    'disp_id', v_item_record.dispatch_disp_id,
                    'quantity', v_item_record.dispatch_quantity,
                    'disp_no', v_item_record.dispatch_no,
                    'disp_date', v_item_record.dispatch_date
                ),

                'grn_item', jsonb_build_object(
                    'id', v_item_record.grn_item_id,
                    'gr_id', v_item_record.grn_item_gr_id,
                    'item_id', v_item_record.grn_item_item_id,
                    'name', v_item_record.grn_item_name,
                    'packaging', v_item_record.grn_item_packaging,
                    'original_quantity', v_item_record.grn_original_quantity,
                    'current_stock', v_item_record.grn_current_stock,
                    'weight', v_item_record.grn_weight,
                    'rack', v_item_record.grn_rack,
                    'package_mark', v_item_record.grn_package_mark,
                    'image_url', v_item_record.grn_item_image_url,
                    'pricing_mode', v_item_record.grn_item_pricing_mode
                ),

                'catalog', jsonb_build_object(
                    'id', v_item_record.catalog_id,
                    'name', v_item_record.catalog_name,
                    'packaging', v_item_record.catalog_packaging,
                    'description', v_item_record.catalog_description,
                    'active', v_item_record.catalog_active
                )
            );
        END LOOP;

        v_result := jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'header', jsonb_build_object(
                    'invoice_id', v_invoice_header.invoice_id,
                    'invoice_number', v_invoice_header.invoice_number,
                    'invoice_date', v_invoice_header.invoice_date,
                    'inv_fin_year', v_invoice_header.inv_fin_year,
                    'financial_year', v_invoice_header.financial_year,
                    'gr_id', v_invoice_header.gr_id,
                    'gr_no', v_invoice_header.gr_no,
                    'customer_id', v_invoice_header.customer_id,
                    'invoice_customer_name', v_invoice_header.invoice_customer_name,
                    'inv_name', v_invoice_header.inv_name,
                    'one_time_charge', v_invoice_header.one_time_charge,
                    'labour', v_invoice_header.labour,
                    'tax_amount', v_invoice_header.tax_amount,
                    'total', v_invoice_header.total,
                    'discount', v_invoice_header.discount,
                    'is_auto_generated', v_invoice_header.is_auto_generated,
                    'pricing_mode', v_invoice_header.pricing_mode,
                    'duration_mode', v_invoice_header.duration_mode,
                    'notes', v_invoice_header.notes,
                    'created_by', v_invoice_header.created_by,

                    'customer', jsonb_build_object(
                        'id', v_invoice_header.customer_id,
                        'name', v_invoice_header.customer_name,
                        'first_name', v_invoice_header.customer_firstName,
                        'last_name', v_invoice_header.customer_lastName,
                        'address', v_invoice_header.customer_address,
                        'city', v_invoice_header.customer_city,
                        'mobile', v_invoice_header.customer_mobile,
                        'pincode', v_invoice_header.customer_pincode,
                        'state', v_invoice_header.customer_state,
                        'telephone1', v_invoice_header.customer_telephone1,
                        'telephone2', v_invoice_header.customer_telephone2,
                        'gst', v_invoice_header.customer_gst,
                        'email', v_invoice_header.customer_email,
                        'active', v_invoice_header.customer_active,
                        'contact', v_invoice_header.customer_contact,
                        'pan', v_invoice_header.customer_pan,
                        'auto_invoice_generation', v_invoice_header.customer_auto_invoice_generation,
                        'created_at', v_invoice_header.customer_created_at,
                        'updated_at', v_invoice_header.customer_updated_at
                    ),

                    'grn', jsonb_build_object(
                        'id', v_invoice_header.grn_id,
                        'gr_no', v_invoice_header.grn_number,
                        'registration', v_invoice_header.grn_registration,
                        'date', v_invoice_header.grn_date,
                        'sender_id', v_invoice_header.grn_sender_id,
                        'sender_name', v_invoice_header.grn_sender_name,
                        'customer_id', v_invoice_header.grn_customer_id,
                        'customer_name', v_invoice_header.grn_customer_name,
                        'supervisor_id', v_invoice_header.grn_supervisor_id,
                        'supervisor_name', v_invoice_header.grn_supervisor_name,
                        'note', v_invoice_header.grn_note,
                        'leon', v_invoice_header.grn_leon,
                        'out_of_stock', v_invoice_header.grn_out_of_stock,
                        'invoiced', v_invoice_header.grn_invoiced,
                        'image_url', v_invoice_header.gr_image_url,
                        'created_by', v_invoice_header.grn_created_by,
                        'updated_by', v_invoice_header.grn_updated_by,
                        'created_at', v_invoice_header.grn_created_at,
                        'updated_at', v_invoice_header.grn_updated_at,
                        'pricing_mode', v_invoice_header.grn_pricing_mode
                    ),

                    'created_by_info', jsonb_build_object(
                        'id', v_invoice_header.created_by,
                        'name', v_invoice_header.created_by_name,
                        'display_name', v_invoice_header.created_by_display_name,
                        'role', v_invoice_header.created_by_role
                    )
                ),
                'items', v_invoice_items
            )
        );

        RETURN v_result;

    EXCEPTION
        WHEN OTHERS THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'Error retrieving invoice data: ' || SQLERRM
            );
    END;
    $$;


CREATE FUNCTION public.get_invoice_detail(p_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_invoice_header jsonb;
    v_invoice_items jsonb;
BEGIN
    SELECT jsonb_build_object(
        'id', i.id, 'inv_fin_year', i.inv_fin_year, 'inv_no', i.inv_no,
        'gr_id', i.gr_id, 'gr_no', i.gr_no, 'customer_id', i.customer_id,
        'customer_name', i.customer_name, 'inv_date', i.inv_date,
        'labour', i.labour, 'tax_amount', i.tax_amount, 'total', i.total,
        'discount', i.discount, 'one_time_charge', i.one_time_charge,
        'is_auto_generated', i.is_auto_generated, 'pricing_mode', i.pricing_mode,
        'duration_mode', COALESCE(i.duration_mode, 'legacy'),
        'notes', i.notes, 'created_by', i.created_by
    ) INTO v_invoice_header FROM invoice i WHERE i.id = p_invoice_id;

    IF v_invoice_header IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invoice not found');
    END IF;

    SELECT jsonb_agg(
        jsonb_build_object(
            'id', it.id,
            'invoice_id', it.invoice_id,
            'disp_trl_id', it.disp_trl_id,
            'duration', it.duration,
            'no_of_days', it.no_of_days,
            'charge', it.charge,
            'tax', it.tax,
            'labour_rate', it.labour_rate,
            'item_name', gt.item_name,
            'grn_item_id', gt.id,
            'grn_date', gr.date,
            'qty', dt.disp_qty,
            'dispatch_no', d.disp_no,
            'dispatch_date', d.disp_date,
            'weight', gt.weight,
            'grn_original_qty', gt.qty,
            'package_mark', gt.package_mark
        )
    ) INTO v_invoice_items
    FROM invoice_trl it
    JOIN dispatch_trl dt ON it.disp_trl_id = dt.id
    JOIN dispatch d ON dt.disp_id = d.id
    JOIN goodsreceived_trl gt ON dt.gr_trl_id = gt.id
    JOIN goodsreceived gr ON gr.id = gt.gr_id
    WHERE it.invoice_id = p_invoice_id;

    RETURN jsonb_build_object('success', true, 'invoice', v_invoice_header, 'items', COALESCE(v_invoice_items, '[]'::jsonb));
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


CREATE FUNCTION public.get_invoice_details(p_inv_no integer, p_fin_year integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_id uuid;
    v_role text;
    v_result jsonb;
    v_target_fin_year INTEGER;
BEGIN
    v_user_id := auth.uid();

    SELECT role INTO v_role
    FROM user_profiles
    WHERE auth_user_id = v_user_id;

    -- Default to current financial year if not specified
    v_target_fin_year := COALESCE(p_fin_year, EXTRACT(YEAR FROM CURRENT_DATE)::INTEGER);

    SELECT jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'invoice', jsonb_build_object(
                'id', i.id,
                'inv_no', i.inv_no,
                'inv_no_str', 'INV' || LPAD(i.inv_no::TEXT, 3, '0'),
                'inv_fin_year', i.inv_fin_year,
                'inv_date', i.inv_date,
                'inv_name', i.inv_name,
                'gr_id', i.gr_id,
                'gr_no', i.gr_no,
                'pricing_mode', i.pricing_mode,
                'one_time_charge', COALESCE(i.one_time_charge, false),
                'labour', COALESCE(i.labour, 0),
                'discount', COALESCE(i.discount, 0),
                'tax_amount', COALESCE(i.tax_amount, 0),
                'total', COALESCE(i.total, 0),
                'notes', i.notes,
                'is_auto_generated', COALESCE(i.is_auto_generated, false),
                'created_at', i.created_at,
                'updated_at', i.updated_at,

                -- Customer details
                'customer_details', CASE
                    WHEN c.id IS NOT NULL THEN jsonb_build_object(
                        'id', c.id,
                        'name', c.name,
                        'first_name', c."firstName",
                        'last_name', c."lastName",
                        'gst', c.gst,
                        'mobile', c.mobile,
                        'address', c.address,
                        'city', c.city,
                        'state', c.state,
                        'pincode', c.pincode,
                        'email', c.email,
                        'active', c.active
                    )
                    ELSE null
                END,

                -- Invoice line items with full details
                'items', COALESCE(
                    (
                        SELECT jsonb_agg(
                            jsonb_build_object(
                                'id', it.id,
                                'duration', COALESCE(it.duration, 0),
                                'no_of_days', COALESCE(it.no_of_days, 0),
                                'charge', COALESCE(it.charge, 0),
                                'tax', COALESCE(it.tax, 0),
                                'labour_rate', COALESCE(it.labour_rate, 0),
                                'item_total', COALESCE(it.charge * it.duration, 0),
                                'labour_amount', COALESCE(it.labour_rate * grt.weight, 0),

                                -- Dispatch details
                                'dispatch_details', CASE
                                    WHEN dt.id IS NOT NULL THEN jsonb_build_object(
                                        'disp_trl_id', dt.id,
                                        'disp_id', dt.disp_id,
                                        'disp_qty', COALESCE(dt.disp_qty, 0),
                                        'disp_no', d.disp_no,
                                        'disp_date', d.disp_date
                                    )
                                    ELSE null
                                END,

                                -- GRN Item details
                                'grn_item_details', CASE
                                    WHEN grt.id IS NOT NULL THEN jsonb_build_object(
                                        'id', grt.id,
                                        'item_name', grt.item_name,
                                        'packaging', grt.packaging,
                                        'qty', grt.qty,
                                        'stock', grt.stock,
                                        'weight', grt.weight,
                                        'rack', grt.rack,
                                        'package_mark', grt.package_mark
                                    )
                                    ELSE null
                                END,

                                -- GRN header details
                                'grn_details', CASE
                                    WHEN gr.id IS NOT NULL THEN jsonb_build_object(
                                        'gr_no', gr.gr_no,
                                        'date', gr.date,
                                        'customer_name', gr.customer_name
                                    )
                                    ELSE null
                                END
                            )
                            ORDER BY grt.item_name, it.id
                        )
                        FROM invoice_trl it
                        LEFT JOIN dispatch_trl dt ON it.disp_trl_id = dt.id
                        LEFT JOIN dispatch d ON dt.disp_id = d.id
                        LEFT JOIN goodsreceived_trl grt ON dt.gr_trl_id = grt.id
                        LEFT JOIN goodsreceived gr ON dt.gr_id = gr.id
                        WHERE it.invoice_id = i.id
                    ),
                    '[]'::jsonb
                ),

                -- Statistics
                'statistics', (
                    SELECT jsonb_build_object(
                        'total_items', COUNT(DISTINCT it.id),
                        'total_disp_qty', COALESCE(SUM(dt.disp_qty), 0),
                        'total_grn_qty', COALESCE(SUM(grt.qty), 0),
                        'total_weight', COALESCE(SUM(grt.weight), 0),
                        'total_item_charges', COALESCE(SUM(it.charge * it.duration), 0),
                        'total_labour_amount', COALESCE(SUM(it.labour_rate * grt.weight), 0),
                        'avg_duration', ROUND(COALESCE(AVG(it.duration), 0)::numeric, 2),
                        'avg_no_of_days', ROUND(COALESCE(AVG(it.no_of_days), 0)::numeric, 0)
                    )
                    FROM invoice_trl it
                    LEFT JOIN dispatch_trl dt ON it.disp_trl_id = dt.id
                    LEFT JOIN goodsreceived_trl grt ON dt.gr_trl_id = grt.id
                    WHERE it.invoice_id = i.id
                ),

                -- Amount in words
                'amount_in_words', (
                    SELECT
                        'Rupees ' ||
                        CASE
                            WHEN floor(COALESCE(i.total, 0)) >= 10000000 THEN
                                (SELECT convert_number_to_words(floor(floor(COALESCE(i.total, 0)) / 10000000)::integer)) || ' Crore '
                            ELSE ''
                        END ||
                        CASE
                            WHEN floor(COALESCE(i.total, 0)) % 10000000 >= 100000 THEN
                                (SELECT convert_number_to_words(floor((floor(COALESCE(i.total, 0)) % 10000000) / 100000)::integer)) || ' Lakh '
                            ELSE ''
                        END ||
                        CASE
                            WHEN floor(COALESCE(i.total, 0)) % 100000 >= 1000 THEN
                                (SELECT convert_number_to_words(floor((floor(COALESCE(i.total, 0)) % 100000) / 1000)::integer)) || ' Thousand '
                            ELSE ''
                        END ||
                        CASE
                            WHEN floor(COALESCE(i.total, 0)) % 1000 > 0 THEN
                                (SELECT convert_number_to_words(floor(floor(COALESCE(i.total, 0)) % 1000)::integer))
                            WHEN floor(COALESCE(i.total, 0)) = 0 THEN 'Zero'
                            ELSE ''
                        END ||
                        ' Only'
                )
            )
        ),
        'message', 'Invoice details retrieved successfully'
    ) INTO v_result
    FROM invoice i
    LEFT JOIN customers c ON i.customer_id = c.id
    WHERE i.inv_no = p_inv_no
    AND i.inv_fin_year = v_target_fin_year
    AND (
        v_role IN ('admin', 'supervisor', 'staff') OR
        i.customer_id IN (
            SELECT customer_id FROM users_customers_new
            WHERE user_profile_id = (SELECT id FROM user_profiles WHERE auth_user_id = v_user_id)
        )
    );

    IF v_result IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', null,
            'message', 'Invoice not found or access denied'
        );
    END IF;

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', null,
            'message', 'Error retrieving invoice: ' || SQLERRM
        );
END;
$$;


CREATE FUNCTION public.get_invoice_for_tally_sync(p_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
    v_items  JSONB;
    v_ledger_name TEXT;
BEGIN
    SELECT tlm.tally_ledger_name INTO v_ledger_name
    FROM public.invoice inv
    JOIN public.tally_ledger_map tlm ON tlm.customer_id = inv.customer_id
    WHERE inv.id = p_invoice_id
    LIMIT 1;

    SELECT jsonb_build_object(
        'invoice_id', inv.id,
        'inv_no', inv.inv_no,
        'inv_fin_year', inv.inv_fin_year,
        'inv_date', inv.inv_date,
        'customer_id', inv.customer_id,
        'customer_name', inv.customer_name,
        'tally_ledger_name', COALESCE(v_ledger_name, inv.customer_name),
        'ledger_exists', v_ledger_name IS NOT NULL,
        'gr_id', inv.gr_id,
        'gr_no', inv.gr_no,
        'total', COALESCE(inv.total, 0)::NUMERIC(12,2),
        'tax_amount', COALESCE(inv.tax_amount, 0)::NUMERIC(12,2),
        'labour', COALESCE(inv.labour, 0)::NUMERIC(12,2),
        'discount', COALESCE(inv.discount, 0)::NUMERIC(12,2),
        'discount_treatment', 'synthetic_reconciliation_artifact',
        'tally_revenue_amount', (
            COALESCE(inv.total, 0) - COALESCE(inv.tax_amount, 0) - COALESCE(inv.labour, 0)
        )::NUMERIC(12,2),
        'notes', inv.notes,
        'duration_mode', COALESCE(inv.duration_mode, 'legacy'),
        'deleted_at', inv.deleted_at,
        'customer_gst', c.gst,
        'customer_state', c.state,
        'customer_pan', c.pan,
        'customer_address', c.address,
        'customer_city', c.city,
        'customer_pincode', c.pincode,
        'customer_mobile', c.mobile,
        'customer_email', c.email,
        'customer_contact_person', c.contact_person,
        'customer_contact_mobile', c.contact_mobile,
        'customer_telephone1', c.telephone1
    ) INTO v_result
    FROM public.invoice inv
    JOIN public.customers c ON c.id = inv.customer_id
    WHERE inv.id = p_invoice_id;

    IF v_result IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invoice not found');
    END IF;

    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'invoice_trl_id', it.id,
            'disp_trl_id',    it.disp_trl_id,
            'duration',       it.duration,
            'no_of_days',     it.no_of_days,
            'charge',         it.charge,
            'tax',            it.tax,
            'labour_rate',    it.labour_rate,
            'disp_qty',       dt.disp_qty,
            'dispatch_date',  d.disp_date,
            'dispatch_no',    d.disp_no,
            'gr_trl_id',      grt.id,
            'item_name',      COALESCE(i.name, grt.item_name),
            'item_qty',       grt.qty,
            'item_weight',    grt.weight,
            'item_packaging', grt.packaging,
            'grn_date',       gr.date
        ) ORDER BY grt.item_name, d.disp_date
    ), '[]'::jsonb) INTO v_items
    FROM public.invoice_trl it
    JOIN public.dispatch_trl dt ON dt.id = it.disp_trl_id
    JOIN public.dispatch d ON d.id = dt.disp_id
    JOIN public.goodsreceived_trl grt ON grt.id = dt.gr_trl_id
    JOIN public.goodsreceived gr ON gr.id = grt.gr_id
    LEFT JOIN public.items i ON i.id = grt.item_id
    WHERE it.invoice_id = p_invoice_id;

    RETURN jsonb_build_object(
        'success', true,
        'data', v_result || jsonb_build_object('items', v_items)
    );
END;
$$;


CREATE FUNCTION public.get_invoice_form_data(grid uuid, p_duration_mode text DEFAULT 'legacy'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    RETURN public.generate_invoice_data_for_grn(grid, p_duration_mode);
END;
$$;


CREATE FUNCTION public.get_invoice_items_detailed(p_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_items jsonb;
BEGIN
    IF NOT EXISTS(SELECT 1 FROM invoice WHERE id = p_invoice_id) THEN
        RETURN utils.not_found_response('Invoice', p_invoice_id::text);
    END IF;
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', it.id, 'disp_trl_id', it.disp_trl_id, 'item_name', it.item_name,
        'duration', it.duration, 'no_of_days', it.no_of_days, 'charge', it.charge,
        'tax', it.tax, 'labour_rate', it.labour_rate, 'total_amount', it.charge + COALESCE(it.tax, 0)
    )), '[]'::jsonb) INTO v_items FROM invoice_trl it WHERE it.inv_id = p_invoice_id;
    RETURN utils.success_response(v_items);
EXCEPTION WHEN OTHERS THEN RETURN utils.database_error_response('Failed to get invoice items', SQLERRM, SQLSTATE);
END;
$$;


CREATE FUNCTION public.get_invoice_range_for_print(start_inv_no_str text, end_inv_no_str text, inv_fin_year integer DEFAULT NULL::integer, limit_count integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_result jsonb;
    start_inv_no integer;
    end_inv_no integer;
    target_fin_year integer;
BEGIN
    start_inv_no := CASE
        WHEN start_inv_no_str ~ '^[0-9]+$' THEN start_inv_no_str::integer
        ELSE REGEXP_REPLACE(start_inv_no_str, '[^0-9]', '', 'g')::integer
    END;

    end_inv_no := CASE
        WHEN end_inv_no_str ~ '^[0-9]+$' THEN end_inv_no_str::integer
        ELSE REGEXP_REPLACE(end_inv_no_str, '[^0-9]', '', 'g')::integer
    END;

    target_fin_year := COALESCE(get_invoice_range_for_print.inv_fin_year, EXTRACT(YEAR FROM CURRENT_DATE)::integer);

    WITH invoice_data AS (
        SELECT
            i.id as invoice_id,
            i.inv_fin_year,
            i.inv_no,
            'INV' || LPAD(i.inv_no::text, 3, '0') as inv_no_str,
            i.gr_id,
            i.gr_no,
            i.customer_id,
            i.customer_name,
            i.inv_name,
            TO_CHAR(i.inv_date, 'YYYY-MM-DD') as formatted_inv_date,
            COALESCE(i.one_time_charge, false) as one_time_charge,
            COALESCE(i.duration_mode, 'legacy') as duration_mode,
            COALESCE(i.labour, 0)::double precision as labour,
            COALESCE(i.tax_amount, 0)::double precision as tax_amount,
            COALESCE(i.total, 0)::double precision as total,
            COALESCE(i.discount, 0)::double precision as discount,
            i.created_by
        FROM invoice i
        WHERE i.inv_no >= start_inv_no
          AND i.inv_no <= end_inv_no
          AND (get_invoice_range_for_print.inv_fin_year IS NULL OR i.inv_fin_year = target_fin_year)
        ORDER BY i.inv_fin_year, i.inv_no
        LIMIT get_invoice_range_for_print.limit_count
    ),
    invoice_with_customer AS (
        SELECT id.*, c.address, c.city, c.mobile, c.gst as gstin
        FROM invoice_data id
        LEFT JOIN customers c ON c.id = id.customer_id::uuid
    ),
    invoice_with_items AS (
        SELECT
            iwc.*,
            jsonb_agg(
                jsonb_build_object(
                    'id', it.id::text,
                    'invoice_id', it.invoice_id::text,
                    'duration_mode', iwc.duration_mode,
                    'charge', COALESCE(it.charge, 0),
                    'dispatches_items_disp_qty', COALESCE(dt.disp_qty, 0),
                    'dispatches_items_id', dt.id::text,
                    'dispatches_customer_id', d.customer_id::text,
                    'dispatches_customer_name', d.customer_name,
                    'dispatches_date', TO_CHAR(d.disp_date, 'YYYY-MM-DD'),
                    'dispatches_id', d.id::text,
                    'dispatches_image_url', d.disp_image_url,
                    'dispatches_no', d.disp_no,
                    'dispatches_note', d.note,
                    'dispatches_registration', d.registration,
                    'dispatches_supervisor_id', d.supervisor_id::text,
                    'dispatches_supervisor_name', d.supervisor_name,
                    'duration', COALESCE(it.duration, 0),
                    'grn_items_id', grt.id::text,
                    'grn_items_image_url', grt.trl_img_url,
                    'grn_items_item_id', grt.item_id::text,
                    'grn_items_item_name', grt.item_name,
                    'grn_items_package_mark', grt.package_mark,
                    'grn_items_packaging', grt.packaging,
                    'grn_items_quantity', COALESCE(grt.qty, 0),
                    'grn_items_rack', grt.rack,
                    'grn_items_stock', COALESCE(grt.stock, 0),
                    'grn_items_weight', COALESCE(grt.weight, 0),
                    'grns_customer_id', gr.customer_id::text,
                    'grns_customer_name', gr.customer_name,
                    'grns_date', TO_CHAR(gr.date, 'YYYY-MM-DD'),
                    'grns_gr_no', gr.gr_no,
                    'grns_id', gr.id::text,
                    'grns_image_url', gr.gr_image_url,
                    'grns_invoiced', COALESCE(gr.invoiced, false),
                    'grns_leon', COALESCE(gr.leon, false),
                    'grns_note', gr.note,
                    'grns_out_of_stock', COALESCE(gr.out_of_stock, false),
                    'grns_registration', gr.registration,
                    'grns_sender_id', gr.sender_id::text,
                    'grns_sender_name', gr.sender_name,
                    'grns_supervisor_id', gr.supervisor_id::text,
                    'grns_supervisor_name', gr.supervisor_name,
                    'inv_fin_year', iwc.inv_fin_year,
                    'inv_no', iwc.inv_no,
                    'no_of_days', COALESCE(it.no_of_days, 0),
                    'tax', COALESCE(it.tax, 0),
                    'inv_item_charge', COALESCE(it.charge, 0)
                ) ORDER BY it.id
            ) FILTER (WHERE it.id IS NOT NULL) as trl_data,
            SUM(COALESCE(it.charge, 0))::double precision as total_inv_item_charges,
            SUM(COALESCE(dt.disp_qty, 0))::integer as total_disp_qty,
            SUM(COALESCE(grt.qty, 0))::integer as total_gr_qty
        FROM invoice_with_customer iwc
        LEFT JOIN invoice_trl it ON it.invoice_id = iwc.invoice_id
        LEFT JOIN dispatch_trl dt ON dt.id = it.disp_trl_id
        LEFT JOIN dispatch d ON d.id = dt.disp_id
        LEFT JOIN goodsreceived_trl grt ON grt.id = dt.gr_trl_id
        LEFT JOIN goodsreceived gr ON gr.id = grt.gr_id
        GROUP BY
            iwc.invoice_id, iwc.inv_fin_year, iwc.inv_no, iwc.inv_no_str, iwc.gr_id, iwc.gr_no,
            iwc.customer_id, iwc.customer_name, iwc.inv_name, iwc.formatted_inv_date,
            iwc.one_time_charge, iwc.duration_mode, iwc.labour, iwc.tax_amount, iwc.total, iwc.discount,
            iwc.address, iwc.city, iwc.mobile, iwc.gstin, iwc.created_by
    ),
    final_result AS (
        SELECT jsonb_agg(
            jsonb_build_object(
                'id', iwi.invoice_id,
                'created_by', iwi.created_by,
                'customer_id', iwi.customer_id,
                'customer_name', iwi.customer_name,
                'gr_id', iwi.gr_id,
                'gr_no', iwi.gr_no,
                'inv_date', iwi.formatted_inv_date,
                'inv_fin_year', iwi.inv_fin_year,
                'inv_name', iwi.inv_name,
                'inv_no', iwi.inv_no,
                'inv_no_str', iwi.inv_no_str,
                'duration_mode', iwi.duration_mode,
                'labour', iwi.labour,
                'discount', iwi.discount,
                'one_time_charge', iwi.one_time_charge,
                'tax_amount', iwi.tax_amount,
                'total', iwi.total,
                'address', iwi.address,
                'city', iwi.city,
                'mobile', iwi.mobile,
                'gstin', iwi.gstin,
                'trl', COALESCE(iwi.trl_data, '[]'::jsonb),
                'inwords', convert_number_to_words(COALESCE(iwi.total, 0)::integer),
                'total_inv_item_charges', COALESCE(iwi.total_inv_item_charges, 0),
                'total_disp_qty', COALESCE(iwi.total_disp_qty, 0),
                'total_gr_qty', COALESCE(iwi.total_gr_qty, 0),
                'total_labour_amount', COALESCE(iwi.labour * iwi.total_disp_qty, 0)
            ) ORDER BY iwi.inv_fin_year, iwi.inv_no
        ) as data
        FROM invoice_with_items iwi
    )
    SELECT COALESCE(data, '[]'::jsonb) INTO v_result FROM final_result;

    RETURN utils.success_response(v_result, NULL);
END;
$_$;


CREATE FUNCTION public.get_invoiceable_grns(p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS TABLE(grn_id uuid, gr_no character varying, gr_date timestamp with time zone, customer_id uuid, customer_name character varying, supervisor_id uuid, supervisor_name character varying, sender_id uuid, sender_name character varying, registration character varying, note character varying, leon boolean, gr_image_url character varying, created_by uuid, updated_by uuid, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  BEGIN
      RETURN QUERY
      SELECT
          g.id as grn_id,
          g.gr_no,
          g.date as gr_date,
          g.customer_id,
          g.customer_name,
          g.supervisor_id,
          g.supervisor_name,
          g.sender_id,
          g.sender_name,
          g.registration,
          g.note,
          g.leon,
          g.gr_image_url,
          g.created_by,
          g.updated_by,
          g.created_at,
          g.updated_at
      FROM goodsreceived g
      WHERE g.out_of_stock = true
        AND g.invoiced = false
        AND (
          -- If not authenticated (superuser), show all
          auth.uid() IS NULL
          OR
          -- If authenticated, apply access control
          g.customer_id = ANY (
            CASE
              WHEN is_admin_or_supervisor() THEN
                (SELECT array_agg(customers.id) FROM customers)
              ELSE
                user_accessible_customers()
            END
          )
        )
      ORDER BY g.date DESC, g.created_at DESC
      LIMIT p_limit
      OFFSET p_offset;
  END;
  $$;


CREATE FUNCTION public.get_invoiceable_grns(p_limit integer DEFAULT 100, p_offset integer DEFAULT 0, p_search_grn_no text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_grns jsonb;
    v_total_count bigint;
BEGIN
    SELECT COALESCE(jsonb_agg(grn_data), '[]'::jsonb)
    INTO v_grns
    FROM (
        SELECT jsonb_build_object(
            'grn_id', gr.id,
            'gr_no', gr.gr_no,
            'gr_date', gr.date,
            'customer_id', gr.customer_id,
            'customer_name', gr.customer_name,
            'supervisor_id', gr.supervisor_id,
            'supervisor_name', gr.supervisor_name,
            'sender_id', gr.sender_id,
            'sender_name', gr.sender_name,
            'registration', gr.registration,
            'note', gr.note,
            'leon', gr.leon,
            'gr_image_url', (SELECT storage_path FROM grn_images WHERE grn_id = gr.id AND image_type = 'header' LIMIT 1),
            'created_by', gr.created_by,
            'updated_by', gr.updated_by,
            'created_at', gr.created_at,
            'updated_at', gr.updated_at
        ) as grn_data
        FROM goodsreceived gr
        WHERE gr.deleted_at IS NULL
          AND gr.out_of_stock = true
          AND gr.invoiced = false
          AND (p_search_grn_no IS NULL OR gr.gr_no ILIKE '%' || p_search_grn_no || '%')
        ORDER BY gr.date DESC
        LIMIT p_limit OFFSET p_offset
    ) sub;

    SELECT COUNT(*) INTO v_total_count
    FROM goodsreceived gr
    WHERE gr.deleted_at IS NULL
      AND gr.out_of_stock = true
      AND gr.invoiced = false
      AND (p_search_grn_no IS NULL OR gr.gr_no ILIKE '%' || p_search_grn_no || '%');

    RETURN utils.success_response_paginated(v_grns, v_total_count, p_limit, p_offset);
EXCEPTION
    WHEN OTHERS THEN
        RETURN utils.database_error_response('Failed to get invoiceable GRNs', SQLERRM, SQLSTATE);
END;
$$;


CREATE FUNCTION public.get_invoices_list(p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_customer_id uuid DEFAULT NULL::uuid, p_financial_year integer DEFAULT NULL::integer, p_search_invoice_no text DEFAULT NULL::text, p_search_grn_no text DEFAULT NULL::text, p_sort_field text DEFAULT 'inv_date'::text, p_sort_direction text DEFAULT 'desc'::text, p_inv_no_from integer DEFAULT NULL::integer, p_inv_no_to integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result jsonb;
    v_user_role text;
    v_user_id uuid;
    v_accessible_customers UUID[];
    v_total_count integer;
BEGIN
    -- Get user role if authenticated
    IF auth.uid() IS NOT NULL THEN
        SELECT id, role INTO v_user_id, v_user_role
        FROM user_profiles
        WHERE auth_user_id = auth.uid();

        IF v_user_role IN ('admin', 'supervisor', 'staff') THEN
            SELECT ARRAY(SELECT id FROM customers WHERE active = true) INTO v_accessible_customers;
        ELSE
            SELECT user_accessible_customers() INTO v_accessible_customers;
        END IF;
    ELSE
        v_accessible_customers := ARRAY[]::UUID[];
    END IF;

    -- Get total count from MV (FAST - no joins!)
    SELECT COUNT(*) INTO v_total_count
    FROM mv_invoice_list m
    WHERE m.customer_id = ANY(v_accessible_customers)
        AND (p_customer_id IS NULL OR m.customer_id = p_customer_id)
        AND (p_financial_year IS NULL OR m.inv_fin_year = p_financial_year)
        AND (p_search_invoice_no IS NULL OR p_search_invoice_no = '' OR m.inv_no::text ILIKE '%' || p_search_invoice_no || '%')
        AND (p_search_grn_no IS NULL OR p_search_grn_no = '' OR m.gr_no ILIKE '%' || p_search_grn_no || '%')
        AND (p_inv_no_from IS NULL OR m.inv_no >= p_inv_no_from)
        AND (p_inv_no_to IS NULL OR m.inv_no <= p_inv_no_to);

    -- Build result from MV (FAST - pre-denormalized!)
    SELECT jsonb_build_object(
        'success', true,
        'data', COALESCE(jsonb_agg(
            jsonb_build_object(
                'invoice_id', m.invoice_id,
                'invoice_number', m.inv_no,
                'invoice_date', m.inv_date,
                'inv_fin_year', m.inv_fin_year,
                'financial_year', m.financial_year_display,
                'inv_name', m.inv_name,
                'invoice_pricing_mode', m.pricing_mode,
                'notes', m.notes,
                'is_auto_generated', m.is_auto_generated,
                'total', m.total,
                'discount', m.discount,
                'labour', m.labour,
                'tax_amount', m.tax_amount,
                'one_time_charge', m.one_time_charge,
                'created_by', m.created_by,
                'total_qty', m.total_qty,
                'customer', jsonb_build_object(
                    'id', m.customer_id,
                    'name', m.customer_name,
                    'city', m.customer_city,
                    'address', m.customer_address,
                    'phone', m.customer_phone,
                    'email', m.customer_email,
                    'gst', m.customer_gst,
                    'active', m.customer_active
                ),
                'grn', jsonb_build_object(
                    'id', m.grn_id,
                    'gr_no', m.gr_no,
                    'registration', m.grn_registration,
                    'date', m.grn_date,
                    'sender_id', m.grn_sender_id,
                    'sender_name', m.grn_sender_name,
                    'supervisor_id', m.grn_supervisor_id,
                    'supervisor_name', m.grn_supervisor_name,
                    'customer_id', m.grn_customer_id,
                    'customer_name', m.grn_customer_name
                )
            )
        ), '[]'::jsonb),
        'pagination', jsonb_build_object(
            'total_count', v_total_count,
            'has_more', (p_offset + p_limit) < v_total_count
        )
    ) INTO v_result
    FROM (
        SELECT *
        FROM mv_invoice_list m
        WHERE m.customer_id = ANY(v_accessible_customers)
            AND (p_customer_id IS NULL OR m.customer_id = p_customer_id)
            AND (p_financial_year IS NULL OR m.inv_fin_year = p_financial_year)
            AND (p_search_invoice_no IS NULL OR p_search_invoice_no = '' OR m.inv_no::text ILIKE '%' || p_search_invoice_no || '%')
            AND (p_search_grn_no IS NULL OR p_search_grn_no = '' OR m.gr_no ILIKE '%' || p_search_grn_no || '%')
            AND (p_inv_no_from IS NULL OR m.inv_no >= p_inv_no_from)
            AND (p_inv_no_to IS NULL OR m.inv_no <= p_inv_no_to)
        ORDER BY
            -- inv_date sorting with secondary sort by inv_no DESC
            CASE WHEN p_sort_field = 'inv_date' AND p_sort_direction = 'desc' THEN m.inv_date END DESC,
            CASE WHEN p_sort_field = 'inv_date' AND p_sort_direction = 'asc' THEN m.inv_date END ASC,
            CASE WHEN p_sort_field = 'inv_date' THEN m.inv_no END DESC,
            -- inv_no sorting (invoice number)
            CASE WHEN p_sort_field = 'inv_no' AND p_sort_direction = 'desc' THEN m.inv_no END DESC,
            CASE WHEN p_sort_field = 'inv_no' AND p_sort_direction = 'asc' THEN m.inv_no END ASC,
            -- invoice_number alias (same as inv_no)
            CASE WHEN p_sort_field = 'invoice_number' AND p_sort_direction = 'desc' THEN m.inv_no END DESC,
            CASE WHEN p_sort_field = 'invoice_number' AND p_sort_direction = 'asc' THEN m.inv_no END ASC,
            -- customer_name sorting with secondary sort by inv_date DESC, inv_no DESC
            CASE WHEN p_sort_field = 'customer_name' AND p_sort_direction = 'desc' THEN m.customer_name END DESC,
            CASE WHEN p_sort_field = 'customer_name' AND p_sort_direction = 'asc' THEN m.customer_name END ASC,
            CASE WHEN p_sort_field = 'customer_name' THEN m.inv_date END DESC,
            CASE WHEN p_sort_field = 'customer_name' THEN m.inv_no END DESC,
            -- grn_number / gr_no sorting
            CASE WHEN p_sort_field IN ('grn_number', 'gr_no') AND p_sort_direction = 'desc' THEN m.gr_no END DESC,
            CASE WHEN p_sort_field IN ('grn_number', 'gr_no') AND p_sort_direction = 'asc' THEN m.gr_no END ASC,
            -- total sorting
            CASE WHEN p_sort_field = 'total' AND p_sort_direction = 'desc' THEN m.total END DESC,
            CASE WHEN p_sort_field = 'total' AND p_sort_direction = 'asc' THEN m.total END ASC,
            -- financial_year sorting with secondary sort by inv_no DESC
            CASE WHEN p_sort_field = 'financial_year' AND p_sort_direction = 'desc' THEN m.inv_fin_year END DESC,
            CASE WHEN p_sort_field = 'financial_year' AND p_sort_direction = 'asc' THEN m.inv_fin_year END ASC,
            CASE WHEN p_sort_field = 'financial_year' THEN m.inv_no END DESC,
            -- Default fallback: inv_date DESC, inv_no DESC
            m.inv_date DESC,
            m.inv_no DESC
        LIMIT p_limit OFFSET p_offset
    ) m;

    RETURN v_result;
END;
$$;


CREATE FUNCTION public.get_item(p_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    SELECT jsonb_build_object(
        'id', id,
        'name', name,
        'packaging', packaging,
        'description', description,
        'active', active
    ) INTO v_result
    FROM items
    WHERE id = p_item_id;

    IF v_result IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Item not found'
        );
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'data', v_result
    );
END;
$$;


CREATE FUNCTION public.get_item_dispatch_records(p_item_id uuid, p_filters jsonb DEFAULT '{}'::jsonb, p_sort_by text DEFAULT 'grn_date'::text, p_sort_order text DEFAULT 'desc'::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_calculate_totals boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_user_role text;
      v_user_id uuid;
      v_customer_ids uuid[];
      v_sort_field text;
      v_sort_direction text;
      v_total_count integer;
      v_records jsonb;
      v_totals jsonb := NULL;
  BEGIN
      v_user_id := auth.uid();
      SELECT role INTO v_user_role FROM user_profiles WHERE auth_user_id = v_user_id;

      IF v_user_role IS NULL THEN
          RAISE EXCEPTION 'Access denied: User not found';
      END IF;

      IF v_user_role IN ('admin', 'supervisor', 'staff') THEN
          v_customer_ids := ARRAY(SELECT id FROM customers WHERE active = true);
      ELSE
          v_customer_ids := ARRAY(
              SELECT DISTINCT customer_id
              FROM users_customers_new
              WHERE user_profile_id = (SELECT id FROM user_profiles WHERE auth_user_id = v_user_id)
              AND active = true
          );
      END IF;

      v_sort_field := COALESCE(p_sort_by, 'grn_date');
      v_sort_direction := UPPER(COALESCE(p_sort_order, 'DESC'));

      -- Get total count (snake_case filter keys)
      SELECT COUNT(*)
      INTO v_total_count
      FROM dispatch_trl dt
      JOIN goodsreceived_trl gt ON dt.gr_trl_id = gt.id
      JOIN goodsreceived gr ON gt.gr_id = gr.id
      JOIN dispatch d ON dt.disp_id = d.id
      WHERE gt.item_id = p_item_id
      AND gr.customer_id = ANY(v_customer_ids)
      AND (NOT p_filters ? 'customer_id' OR gr.customer_id = (p_filters->>'customer_id')::uuid)
      AND (NOT p_filters ? 'disp_date_from' OR p_filters->>'disp_date_from' = ''
           OR d.disp_date >= (p_filters->>'disp_date_from')::timestamptz)
      AND (NOT p_filters ? 'disp_date_to' OR p_filters->>'disp_date_to' = ''
           OR d.disp_date <= (p_filters->>'disp_date_to')::timestamptz);

      -- Get records (snake_case response keys)
      WITH dispatch_records AS (
          SELECT
              dt.id,
              dt.disp_id as dispatch_id,
              dt.disp_qty as qty,
              d.disp_date as dispatch_date,
              d.disp_no,
              gr.id as grn_id,
              gr.date as grn_date,
              gr.gr_no,
              gr.customer_id,
              gr.customer_name,
              gr.sender_name as vendor_name,
              gr.invoiced,
              gt.id as grn_item_id,
              gt.qty as grn_qty,
              gt.item_name,
              gt.weight,
              gt.package_mark,
              gt.packaging,
              gt.rack
          FROM dispatch_trl dt
          JOIN goodsreceived_trl gt ON dt.gr_trl_id = gt.id
          JOIN goodsreceived gr ON gt.gr_id = gr.id
          JOIN dispatch d ON dt.disp_id = d.id
          WHERE gt.item_id = p_item_id
          AND gr.customer_id = ANY(v_customer_ids)
          AND (NOT p_filters ? 'customer_id' OR gr.customer_id = (p_filters->>'customer_id')::uuid)
          AND (NOT p_filters ? 'disp_date_from' OR p_filters->>'disp_date_from' = ''
               OR d.disp_date >= (p_filters->>'disp_date_from')::timestamptz)
          AND (NOT p_filters ? 'disp_date_to' OR p_filters->>'disp_date_to' = ''
               OR d.disp_date <= (p_filters->>'disp_date_to')::timestamptz)
      ),
      sorted_items AS (
          SELECT * FROM dispatch_records
          ORDER BY
              CASE WHEN v_sort_field = 'disp_no' AND v_sort_direction = 'ASC' THEN disp_no END ASC NULLS LAST,
              CASE WHEN v_sort_field = 'disp_no' AND v_sort_direction = 'DESC' THEN disp_no END DESC NULLS LAST,
              CASE WHEN v_sort_field = 'customer_name' AND v_sort_direction = 'ASC' THEN customer_name END ASC NULLS LAST,
              CASE WHEN v_sort_field = 'customer_name' AND v_sort_direction = 'DESC' THEN customer_name END DESC NULLS LAST,
              CASE WHEN v_sort_field = 'gr_no' AND v_sort_direction = 'ASC' THEN gr_no END ASC NULLS LAST,
              CASE WHEN v_sort_field = 'gr_no' AND v_sort_direction = 'DESC' THEN gr_no END DESC NULLS LAST,
              CASE WHEN v_sort_field = 'item_name' AND v_sort_direction = 'ASC' THEN item_name END ASC NULLS LAST,
              CASE WHEN v_sort_field = 'item_name' AND v_sort_direction = 'DESC' THEN item_name END DESC NULLS LAST,
              CASE WHEN v_sort_field = 'grn_date' AND v_sort_direction = 'ASC' THEN grn_date END ASC NULLS LAST,
              CASE WHEN v_sort_field = 'grn_date' AND v_sort_direction = 'DESC' THEN grn_date END DESC NULLS LAST,
              CASE WHEN v_sort_field = 'dispatch_date' AND v_sort_direction = 'ASC' THEN dispatch_date END ASC NULLS LAST,
              CASE WHEN v_sort_field = 'dispatch_date' AND v_sort_direction = 'DESC' THEN dispatch_date END DESC NULLS LAST,
              CASE WHEN v_sort_field = 'qty' AND v_sort_direction = 'ASC' THEN qty END ASC NULLS LAST,
              CASE WHEN v_sort_field = 'qty' AND v_sort_direction = 'DESC' THEN qty END DESC NULLS LAST,
              grn_date DESC
          LIMIT p_limit OFFSET p_offset
      )
      SELECT jsonb_agg(
          jsonb_build_object(
              'id', id,
              'dispatch_id', dispatch_id,
              'dispatch_date', dispatch_date,
              'disp_no', disp_no,
              'qty', qty,
              'grn_id', grn_id,
              'grn_date', grn_date,
              'gr_no', gr_no,
              'customer_id', customer_id,
              'customer_name', customer_name,
              'vendor_name', vendor_name,
              'invoiced', invoiced,
              'grn_item_id', grn_item_id,
              'grn_qty', grn_qty,
              'item_name', item_name,
              'weight', weight,
              'package_mark', package_mark,
              'packaging', packaging,
              'rack', rack
          )
      ) INTO v_records
      FROM sorted_items;

      IF p_calculate_totals THEN
          SELECT jsonb_build_object(
              'total_dispatch_qty', COALESCE(SUM(dt.disp_qty), 0),
              'total_grn_qty', COALESCE(SUM(gt.qty), 0),
              'total_weight', COALESCE(SUM(gt.weight), 0)
          ) INTO v_totals
          FROM dispatch_trl dt
          JOIN goodsreceived_trl gt ON dt.gr_trl_id = gt.id
          JOIN goodsreceived gr ON gt.gr_id = gr.id
          JOIN dispatch d ON dt.disp_id = d.id
          WHERE gt.item_id = p_item_id
          AND gr.customer_id = ANY(v_customer_ids)
          AND (NOT p_filters ? 'customer_id' OR gr.customer_id = (p_filters->>'customer_id')::uuid)
          AND (NOT p_filters ? 'disp_date_from' OR p_filters->>'disp_date_from' = ''
               OR d.disp_date >= (p_filters->>'disp_date_from')::timestamptz)
          AND (NOT p_filters ? 'disp_date_to' OR p_filters->>'disp_date_to' = ''
               OR d.disp_date <= (p_filters->>'disp_date_to')::timestamptz);
      END IF;

      RETURN jsonb_build_object(
          'data', COALESCE(v_records, '[]'::jsonb),
          'total_count', v_total_count,
          'totals', v_totals
      );

  EXCEPTION
      WHEN OTHERS THEN
          RAISE EXCEPTION 'Error retrieving item dispatch records: %', SQLERRM;
  END;
$$;


CREATE FUNCTION public.get_item_grn_records(p_item_id uuid, p_filters jsonb DEFAULT '{}'::jsonb, p_sort_by text DEFAULT 'gr_no'::text, p_sort_order text DEFAULT 'asc'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result jsonb;
    v_total_count integer;
    v_items jsonb;
    v_user_role text;
    v_user_customer_ids uuid[];
    v_filters_clean jsonb;
    v_sort_by_clean text;
    v_sort_order_clean text;
BEGIN
    SELECT role INTO v_user_role FROM user_profiles WHERE auth.uid() = auth_user_id;

    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
        FROM users_customers_new
        WHERE user_profile_id = (SELECT id FROM user_profiles WHERE auth_user_id = auth.uid());
    END IF;

    IF p_item_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'data', null, 'message', 'Item ID is required');
    END IF;

    v_filters_clean := COALESCE(p_filters, '{}'::jsonb);
    v_sort_by_clean := COALESCE(p_sort_by, 'gr_no');
    v_sort_order_clean := CASE WHEN LOWER(COALESCE(p_sort_order, 'asc')) = 'desc' THEN 'DESC' ELSE 'ASC' END;

    -- Normalize sort column to snake_case
    v_sort_by_clean := CASE v_sort_by_clean
        WHEN 'gr_no' THEN 'gr_no'
        WHEN 'customer_name' THEN 'customer_name'
        WHEN 'grns_customerName' THEN 'customer_name'
        WHEN 'item_name' THEN 'item_name'
        WHEN 'package_mark' THEN 'package_mark'
        WHEN 'created_at' THEN 'created_at'
        WHEN 'updated_at' THEN 'updated_at'
        ELSE v_sort_by_clean
    END;

    -- Get total count (snake_case filter keys)
    WITH base_data AS (
        SELECT 1
        FROM goodsreceived_trl grt
        JOIN goodsreceived gr ON grt.gr_id = gr.id
        WHERE grt.item_id = p_item_id
        AND (v_user_role IN ('admin', 'supervisor', 'staff') OR (v_user_customer_ids IS NOT NULL AND gr.customer_id = ANY(v_user_customer_ids)))
        AND (NOT v_filters_clean ? 'date_from' OR v_filters_clean->>'date_from' = '' OR gr.date >= (v_filters_clean->>'date_from')::date::timestamptz)
        AND (NOT v_filters_clean ? 'date_to' OR v_filters_clean->>'date_to' = '' OR gr.date <= (v_filters_clean->>'date_to')::date::timestamptz)
        AND (NOT v_filters_clean ? 'customer_name' OR v_filters_clean->>'customer_name' = '' OR gr.customer_name ILIKE '%' || (v_filters_clean->>'customer_name') || '%')
        AND (NOT v_filters_clean ? 'gr_no' OR v_filters_clean->>'gr_no' = '' OR gr.gr_no ILIKE '%' || (v_filters_clean->>'gr_no') || '%')
        AND (NOT v_filters_clean ? 'qty' OR v_filters_clean->>'qty' = '' OR grt.qty = (v_filters_clean->>'qty')::integer)
        AND (NOT v_filters_clean ? 'qty_from' OR v_filters_clean->>'qty_from' = '' OR grt.qty >= (v_filters_clean->>'qty_from')::integer)
        AND (NOT v_filters_clean ? 'qty_to' OR v_filters_clean->>'qty_to' = '' OR grt.qty <= (v_filters_clean->>'qty_to')::integer)
        AND (NOT v_filters_clean ? 'stock' OR v_filters_clean->>'stock' = '' OR grt.stock = (v_filters_clean->>'stock')::integer)
        AND (NOT v_filters_clean ? 'stock_from' OR v_filters_clean->>'stock_from' = '' OR grt.stock >= (v_filters_clean->>'stock_from')::integer)
        AND (NOT v_filters_clean ? 'stock_to' OR v_filters_clean->>'stock_to' = '' OR grt.stock <= (v_filters_clean->>'stock_to')::integer)
        AND (NOT v_filters_clean ? 'weight' OR v_filters_clean->>'weight' = '' OR grt.weight = (v_filters_clean->>'weight')::integer)
        AND (NOT v_filters_clean ? 'weight_from' OR v_filters_clean->>'weight_from' = '' OR grt.weight >= (v_filters_clean->>'weight_from')::integer)
        AND (NOT v_filters_clean ? 'weight_to' OR v_filters_clean->>'weight_to' = '' OR grt.weight <= (v_filters_clean->>'weight_to')::integer)
        AND (NOT v_filters_clean ? 'package_mark' OR v_filters_clean->>'package_mark' = '' OR grt.package_mark ILIKE '%' || (v_filters_clean->>'package_mark') || '%')
        AND (NOT v_filters_clean ? 'rack' OR v_filters_clean->>'rack' = '' OR grt.rack ILIKE '%' || (v_filters_clean->>'rack') || '%')
    )
    SELECT COUNT(*) INTO v_total_count FROM base_data;

    -- Get paginated data with STABLE sort
    WITH filtered_grn_items AS (
        SELECT grt.id, grt.item_id, grt.item_name, grt.qty, grt.stock, grt.weight,
            grt.rack, grt.package_mark, grt.packaging, grt.trl_img_url, grt.gr_id,
            gr.id as grns_id, gr.gr_no, gr.date,
            gr.customer_id as grns_customer_id, gr.customer_name as grns_customer_name,
            gr.registration as grns_registration, gr.supervisor_name as grns_supervisor_name,
            gr.sender_name as grns_sender_name, gr.invoiced as grns_invoiced,
            gr.leon as grns_leon, gr.out_of_stock as grns_out_of_stock,
            gr.note as grns_note, gr.gr_image_url as grns_image_url,
            gr.created_at, gr.updated_at
        FROM goodsreceived_trl grt
        JOIN goodsreceived gr ON grt.gr_id = gr.id
        WHERE grt.item_id = p_item_id
        AND (v_user_role IN ('admin', 'supervisor', 'staff') OR (v_user_customer_ids IS NOT NULL AND gr.customer_id = ANY(v_user_customer_ids)))
        AND (NOT v_filters_clean ? 'date_from' OR v_filters_clean->>'date_from' = '' OR gr.date >= (v_filters_clean->>'date_from')::date::timestamptz)
        AND (NOT v_filters_clean ? 'date_to' OR v_filters_clean->>'date_to' = '' OR gr.date <= (v_filters_clean->>'date_to')::date::timestamptz)
        AND (NOT v_filters_clean ? 'customer_name' OR v_filters_clean->>'customer_name' = '' OR gr.customer_name ILIKE '%' || (v_filters_clean->>'customer_name') || '%')
        AND (NOT v_filters_clean ? 'gr_no' OR v_filters_clean->>'gr_no' = '' OR gr.gr_no ILIKE '%' || (v_filters_clean->>'gr_no') || '%')
        AND (NOT v_filters_clean ? 'qty' OR v_filters_clean->>'qty' = '' OR grt.qty = (v_filters_clean->>'qty')::integer)
        AND (NOT v_filters_clean ? 'qty_from' OR v_filters_clean->>'qty_from' = '' OR grt.qty >= (v_filters_clean->>'qty_from')::integer)
        AND (NOT v_filters_clean ? 'qty_to' OR v_filters_clean->>'qty_to' = '' OR grt.qty <= (v_filters_clean->>'qty_to')::integer)
        AND (NOT v_filters_clean ? 'stock' OR v_filters_clean->>'stock' = '' OR grt.stock = (v_filters_clean->>'stock')::integer)
        AND (NOT v_filters_clean ? 'stock_from' OR v_filters_clean->>'stock_from' = '' OR grt.stock >= (v_filters_clean->>'stock_from')::integer)
        AND (NOT v_filters_clean ? 'stock_to' OR v_filters_clean->>'stock_to' = '' OR grt.stock <= (v_filters_clean->>'stock_to')::integer)
        AND (NOT v_filters_clean ? 'weight' OR v_filters_clean->>'weight' = '' OR grt.weight = (v_filters_clean->>'weight')::integer)
        AND (NOT v_filters_clean ? 'weight_from' OR v_filters_clean->>'weight_from' = '' OR grt.weight >= (v_filters_clean->>'weight_from')::integer)
        AND (NOT v_filters_clean ? 'weight_to' OR v_filters_clean->>'weight_to' = '' OR grt.weight <= (v_filters_clean->>'weight_to')::integer)
        AND (NOT v_filters_clean ? 'package_mark' OR v_filters_clean->>'package_mark' = '' OR grt.package_mark ILIKE '%' || (v_filters_clean->>'package_mark') || '%')
        AND (NOT v_filters_clean ? 'rack' OR v_filters_clean->>'rack' = '' OR grt.rack ILIKE '%' || (v_filters_clean->>'rack') || '%')
        ORDER BY
            CASE WHEN v_sort_by_clean = 'customer_name' AND v_sort_order_clean = 'ASC' THEN gr.customer_name END ASC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'customer_name' AND v_sort_order_clean = 'DESC' THEN gr.customer_name END DESC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'gr_no' AND v_sort_order_clean = 'ASC' THEN gr.gr_no END ASC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'gr_no' AND v_sort_order_clean = 'DESC' THEN gr.gr_no END DESC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'date' AND v_sort_order_clean = 'ASC' THEN gr.date::text END ASC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'date' AND v_sort_order_clean = 'DESC' THEN gr.date::text END DESC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'item_name' AND v_sort_order_clean = 'ASC' THEN grt.item_name END ASC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'item_name' AND v_sort_order_clean = 'DESC' THEN grt.item_name END DESC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'qty' AND v_sort_order_clean = 'ASC' THEN grt.qty END ASC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'qty' AND v_sort_order_clean = 'DESC' THEN grt.qty END DESC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'stock' AND v_sort_order_clean = 'ASC' THEN grt.stock END ASC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'stock' AND v_sort_order_clean = 'DESC' THEN grt.stock END DESC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'weight' AND v_sort_order_clean = 'ASC' THEN grt.weight END ASC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'weight' AND v_sort_order_clean = 'DESC' THEN grt.weight END DESC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'rack' AND v_sort_order_clean = 'ASC' THEN grt.rack END ASC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'rack' AND v_sort_order_clean = 'DESC' THEN grt.rack END DESC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'package_mark' AND v_sort_order_clean = 'ASC' THEN grt.package_mark END ASC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'package_mark' AND v_sort_order_clean = 'DESC' THEN grt.package_mark END DESC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'created_at' AND v_sort_order_clean = 'ASC' THEN gr.created_at::text END ASC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'created_at' AND v_sort_order_clean = 'DESC' THEN gr.created_at::text END DESC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'updated_at' AND v_sort_order_clean = 'ASC' THEN gr.updated_at::text END ASC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'updated_at' AND v_sort_order_clean = 'DESC' THEN gr.updated_at::text END DESC NULLS LAST,
            grt.id ASC
        LIMIT p_limit OFFSET p_offset
    )
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', id, 'item_id', item_id, 'item_name', item_name, 'qty', qty, 'stock', stock, 'weight', weight,
        'rack', rack, 'package_mark', package_mark, 'packaging', packaging, 'trl_img_url', trl_img_url,
        'gr_id', gr_id, 'grn_id', grns_id, 'gr_no', gr_no, 'grn_date', date,
        'customer_id', grns_customer_id, 'customer_name', grns_customer_name,
        'registration', grns_registration, 'supervisor_name', grns_supervisor_name,
        'sender_name', grns_sender_name, 'invoiced', grns_invoiced,
        'leon', grns_leon, 'out_of_stock', grns_out_of_stock,
        'note', grns_note, 'image_url', grns_image_url,
        'created_at', created_at, 'updated_at', updated_at
    )), '[]'::jsonb) INTO v_items FROM filtered_grn_items;

    v_result := jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'items', v_items, 'total_count', v_total_count,
            'page_size', p_limit, 'page_offset', p_offset,
            'sort_by', v_sort_by_clean, 'sort_order', v_sort_order_clean
        ),
        'message', 'GRN records retrieved successfully'
    );

    RETURN v_result;
END;
$$;


CREATE FUNCTION public.get_item_pricing_config(p_item_id uuid, p_customer_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    SELECT jsonb_build_object(
        'success', true,
        'data', COALESCE(jsonb_agg(jsonb_build_object(
            'id', isp.id,
            'item_id', isp.item_id,
            'customer_id', isp.customer_id,
            'weight_min', isp.weight_min,
            'weight_max', isp.weight_max,
            'unit_price_one_time', isp.unit_price_one_time,
            'unit_price_monthly', isp.unit_price_monthly,
            'labour_rate', isp.labour_rate,
            'tax_percent', isp.tax_percent,
            'effective_from', isp.effective_from,
            'effective_to', isp.effective_to,
            'is_customer_specific', (isp.customer_id IS NOT NULL)
        ) ORDER BY
            CASE WHEN isp.customer_id IS NOT NULL THEN 1 ELSE 2 END,
            isp.weight_min ASC,
            isp.effective_from DESC
        ), '[]'::jsonb),
        'message', null
    ) INTO v_result
    FROM item_storage_prices isp
    WHERE isp.item_id = p_item_id
      AND (p_customer_id IS NULL OR isp.customer_id = p_customer_id OR isp.customer_id IS NULL)
      AND (isp.effective_to IS NULL OR isp.effective_to > CURRENT_DATE);

    RETURN v_result;
END;
$$;


CREATE FUNCTION public.get_item_stock_analysis(p_as_of_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_item_filter jsonb DEFAULT '{}'::jsonb, p_customer_filter jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_result jsonb;
      v_total_grn_qty bigint;
      v_total_dispatch_qty bigint;
      v_total_calculated_stock bigint;
      v_item_count integer;
      v_items jsonb;
      v_user_role text;
      v_items_with_negative_stock integer;
      v_item_filter_clean jsonb;
      v_customer_filter_clean jsonb;
  BEGIN
      -- Security: Only admin/supervisor can access this function
      SELECT role INTO v_user_role FROM user_profiles
      WHERE auth_user_id = auth.uid();

      -- Restrict access to admin/supervisor only
      IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
          RETURN jsonb_build_object(
              'success', false,
              'data', null,
              'message', 'Access denied: Only administrators and supervisors can access item stock analysis across all customers'
          );
      END IF;

      -- Handle NULL filters by converting to empty JSONB
      v_item_filter_clean := COALESCE(p_item_filter, '{}'::jsonb);
      v_customer_filter_clean := COALESCE(p_customer_filter, '{}'::jsonb);

      -- Time-traveling inventory calculation across ALL customers
      WITH grn_data AS (
          -- Sum all GRN quantities up to the specified date across all customers
          SELECT
              grt.item_id,
              SUM(grt.qty) as total_grn_qty
          FROM goodsreceived_trl grt
          JOIN goodsreceived gr ON grt.gr_id = gr.id
          WHERE (p_as_of_date IS NULL OR gr.date <= p_as_of_date)
          AND (NOT v_customer_filter_clean ? 'customer_id' OR v_customer_filter_clean->>'customer_id' = ''
               OR gr.customer_id = (v_customer_filter_clean->>'customer_id')::uuid)
          AND (NOT v_customer_filter_clean ? 'customer_name' OR v_customer_filter_clean->>'customer_name' = ''
               OR gr.customer_name ILIKE '%' || (v_customer_filter_clean->>'customer_name') || '%')
          GROUP BY grt.item_id
      ),
      dispatch_data AS (
          -- Sum all dispatch quantities up to the specified date across all customers
          -- CRITICAL: Use dispatch date, not GRN date
          SELECT
              grt.item_id,
              SUM(dt.disp_qty) as total_dispatch_qty
          FROM dispatch_trl dt
          JOIN goodsreceived_trl grt ON dt.gr_trl_id = grt.id
          JOIN dispatch d ON dt.disp_id = d.id
          JOIN goodsreceived gr ON grt.gr_id = gr.id
          WHERE (p_as_of_date IS NULL OR d.disp_date <= p_as_of_date)
          AND (NOT v_customer_filter_clean ? 'customer_id' OR v_customer_filter_clean->>'customer_id' = ''
               OR gr.customer_id = (v_customer_filter_clean->>'customer_id')::uuid)
          AND (NOT v_customer_filter_clean ? 'customer_name' OR v_customer_filter_clean->>'customer_name' = ''
               OR gr.customer_name ILIKE '%' || (v_customer_filter_clean->>'customer_name') || '%')
          GROUP BY grt.item_id
      ),
      stock_calculation AS (
          -- Calculate total stock across all customers for each item
          SELECT
              i.id as item_id,
              i.name as item_name,
              i.packaging,
              i.description,
              COALESCE(grn.total_grn_qty, 0) as grn_qty,
              COALESCE(disp.total_dispatch_qty, 0) as dispatch_qty,
              COALESCE(grn.total_grn_qty, 0) - COALESCE(disp.total_dispatch_qty, 0) as calculated_stock
          FROM items i
          LEFT JOIN grn_data grn ON i.id = grn.item_id
          LEFT JOIN dispatch_data disp ON i.id = disp.item_id
          WHERE i.active = true
          AND (grn.item_id IS NOT NULL OR disp.item_id IS NOT NULL)
          AND (NOT v_item_filter_clean ? 'item_name' OR v_item_filter_clean->>'item_name' = ''
               OR i.name ILIKE '%' || (v_item_filter_clean->>'item_name') || '%')
          AND (NOT v_item_filter_clean ? 'item_id' OR v_item_filter_clean->>'item_id' = ''
               OR i.id = (v_item_filter_clean->>'item_id')::uuid)
      )
      -- Final aggregation and result building
      SELECT
          jsonb_agg(
              jsonb_build_object(
                  'item_id', sc.item_id,
                  'item_name', sc.item_name,
                  'packaging', sc.packaging,
                  'description', sc.description,
                  'grn_qty', sc.grn_qty,
                  'dispatch_qty', sc.dispatch_qty,
                  'stock', sc.calculated_stock,
                  'has_negative_stock', sc.calculated_stock < 0,
                  'as_of_date', COALESCE(p_as_of_date, NOW())
              ) ORDER BY sc.item_name
          ),
          COALESCE(SUM(sc.grn_qty), 0),
          COALESCE(SUM(sc.dispatch_qty), 0),
          COALESCE(SUM(sc.calculated_stock), 0),
          COUNT(*),
          COUNT(*) FILTER (WHERE sc.calculated_stock < 0)
      INTO v_items, v_total_grn_qty, v_total_dispatch_qty, v_total_calculated_stock, v_item_count, v_items_with_negative_stock
      FROM stock_calculation sc;

      -- Build final result
      v_result := jsonb_build_object(
          'success', true,
          'data', jsonb_build_object(
              'items', COALESCE(v_items, '[]'::jsonb),
              'aggregations', jsonb_build_object(
                  'total_grn_qty', v_total_grn_qty,
                  'total_dispatch_qty', v_total_dispatch_qty,
                  'total_stock', v_total_calculated_stock,
                  'item_count', v_item_count,
                  'items_with_negative_stock', v_items_with_negative_stock,
                  'as_of_date', COALESCE(p_as_of_date, NOW()),
                  'has_data_integrity_issues', v_items_with_negative_stock > 0
              )
          ),
          'message', CASE
              WHEN p_as_of_date IS NOT NULL THEN
                  'Historical item stock analysis across all customers as of ' || to_char(p_as_of_date, 'YYYY-MM-DD') || ' retrieved
  successfully'
              ELSE
                  'Current item stock analysis across all customers retrieved successfully'
          END
      );

      RETURN v_result;

  EXCEPTION
      WHEN OTHERS THEN
          RETURN jsonb_build_object(
              'success', false,
              'data', NULL,
              'message', 'Error retrieving item stock analysis: ' || SQLERRM
          );
  END;
  $$;


CREATE FUNCTION public.get_item_storage_prices(p_filters jsonb DEFAULT '{}'::jsonb, p_sort_by text DEFAULT 'item_name'::text, p_sort_order text DEFAULT 'asc'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_role TEXT;
    v_user_customer_ids UUID[];
    v_where_clauses TEXT[] := ARRAY['1=1'];
    v_order_by TEXT;
    v_data JSONB;
    v_total INTEGER;
    v_item_ids UUID[];
    v_customer_ids UUID[];
    v_include_expired BOOLEAN;
    v_price_type TEXT;
BEGIN
    -- Authorization: Allow all authenticated users
    SELECT role INTO v_user_role FROM user_profiles WHERE auth_user_id = auth.uid();
    IF v_user_role IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Authentication required');
    END IF;

    -- For non-admin/supervisor users, auto-filter to their accessible customers
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        SELECT ARRAY(
            SELECT uc.customer_id
            FROM users_customers_new uc
            JOIN user_profiles up ON up.id = uc.user_profile_id
            WHERE up.auth_user_id = auth.uid() AND uc.active = true
        ) INTO v_user_customer_ids;

        IF v_user_customer_ids IS NULL OR array_length(v_user_customer_ids, 1) IS NULL THEN
            v_where_clauses := array_append(v_where_clauses, 'isp.customer_id IS NULL');
        ELSE
            v_where_clauses := array_append(v_where_clauses,
                format('(isp.customer_id IS NULL OR isp.customer_id = ANY(%L::uuid[]))', v_user_customer_ids));
        END IF;
    END IF;

    -- Item IDs filter
    IF p_filters ? 'item_ids' AND jsonb_array_length(p_filters->'item_ids') > 0 THEN
        SELECT array_agg(x::uuid) INTO v_item_ids
        FROM jsonb_array_elements_text(p_filters->'item_ids') x;
        v_where_clauses := array_append(v_where_clauses, format('isp.item_id = ANY(%L::uuid[])', v_item_ids));
    END IF;

    -- Customer IDs filter
    IF p_filters ? 'customer_ids' THEN
        IF jsonb_array_length(p_filters->'customer_ids') > 0 THEN
            SELECT array_agg(x::uuid) INTO v_customer_ids
            FROM jsonb_array_elements_text(p_filters->'customer_ids') x;
            v_where_clauses := array_append(v_where_clauses, format('isp.customer_id = ANY(%L::uuid[])', v_customer_ids));
        ELSE
            v_where_clauses := array_append(v_where_clauses, 'isp.customer_id IS NULL');
        END IF;
    END IF;

    -- Price type filter (NEW)
    IF p_filters ? 'price_type' THEN
        v_price_type := p_filters->>'price_type';
        IF v_price_type IN ('one_time', 'monthly') THEN
            v_where_clauses := array_append(v_where_clauses, format('isp.price_type = %L', v_price_type));
        END IF;
    END IF;

    -- Weight range filters
    IF p_filters ? 'weight_min' THEN
        v_where_clauses := array_append(v_where_clauses, format('isp.weight_max >= %s', (p_filters->>'weight_min')::numeric));
    END IF;
    IF p_filters ? 'weight_max' THEN
        v_where_clauses := array_append(v_where_clauses, format('isp.weight_min <= %s', (p_filters->>'weight_max')::numeric));
    END IF;

    -- Date range filters
    IF p_filters ? 'effective_from' THEN
        v_where_clauses := array_append(v_where_clauses, format('isp.effective_from >= %L::date', p_filters->>'effective_from'));
    END IF;
    IF p_filters ? 'effective_to' THEN
        v_where_clauses := array_append(v_where_clauses, format('(isp.effective_to IS NULL OR isp.effective_to <= %L::date)', p_filters->>'effective_to'));
    END IF;

    -- Include expired filter
    v_include_expired := COALESCE((p_filters->>'include_expired')::boolean, false);
    IF NOT v_include_expired THEN
        v_where_clauses := array_append(v_where_clauses, '(isp.effective_to IS NULL OR isp.effective_to >= CURRENT_DATE)');
    END IF;

    -- Build ORDER BY clause
    v_order_by := CASE p_sort_by
        WHEN 'item_name' THEN 'i.name'
        WHEN 'customer_name' THEN 'c.name'
        WHEN 'price_type' THEN 'isp.price_type'
        WHEN 'unit_price' THEN 'isp.unit_price'
        WHEN 'weight_min' THEN 'isp.weight_min'
        WHEN 'weight_max' THEN 'isp.weight_max'
        WHEN 'effective_from' THEN 'isp.effective_from'
        WHEN 'effective_to' THEN 'isp.effective_to'
        WHEN 'created_at' THEN 'isp.created_at'
        ELSE 'i.name'
    END || ' ' || CASE WHEN LOWER(p_sort_order) = 'desc' THEN 'DESC' ELSE 'ASC' END || ' NULLS LAST';

    -- Add secondary sort
    IF p_sort_by NOT IN ('item_name', 'price_type') THEN
        v_order_by := v_order_by || ', i.name ASC NULLS LAST, isp.price_type ASC';
    ELSIF p_sort_by = 'item_name' THEN
        v_order_by := v_order_by || ', isp.price_type ASC, isp.effective_from DESC NULLS LAST';
    ELSIF p_sort_by = 'price_type' THEN
        v_order_by := v_order_by || ', i.name ASC NULLS LAST';
    END IF;

    -- Get total count
    EXECUTE format(
        'SELECT COUNT(*) FROM item_storage_prices isp
         LEFT JOIN items i ON isp.item_id = i.id
         LEFT JOIN customers c ON isp.customer_id = c.id
         WHERE %s',
        array_to_string(v_where_clauses, ' AND ')
    ) INTO v_total;

    -- Get data with new schema fields
    EXECUTE format(
        'SELECT COALESCE(jsonb_agg(row_data), ''[]''::jsonb)
         FROM (
             SELECT jsonb_build_object(
                 ''id'', isp.id,
                 ''item_id'', isp.item_id,
                 ''item_name'', i.name,
                 ''customer_id'', isp.customer_id,
                 ''customer_name'', c.name,
                 ''price_type'', isp.price_type,
                 ''unit_price'', isp.unit_price,
                 ''weight_min'', isp.weight_min,
                 ''weight_max'', isp.weight_max,
                 ''labour_rate'', isp.labour_rate,
                 ''tax_percent'', isp.tax_percent,
                 ''effective_from'', isp.effective_from,
                 ''effective_to'', isp.effective_to,
                 ''created_at'', isp.created_at,
                 ''created_by'', isp.created_by
             ) as row_data
             FROM item_storage_prices isp
             LEFT JOIN items i ON isp.item_id = i.id
             LEFT JOIN customers c ON isp.customer_id = c.id
             WHERE %s
             ORDER BY %s
             LIMIT %s OFFSET %s
         ) sub',
        array_to_string(v_where_clauses, ' AND '),
        v_order_by,
        p_limit,
        p_offset
    ) INTO v_data;

    RETURN jsonb_build_object(
        'success', true,
        'data', v_data,
        'pagination', jsonb_build_object(
            'total', v_total,
            'limit', p_limit,
            'offset', p_offset,
            'has_more', (p_offset + p_limit) < v_total
        )
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', SQLERRM,
        'error_code', SQLSTATE
    );
END;
$$;


CREATE FUNCTION public.get_item_wise_stock_list(p_customer_id uuid DEFAULT NULL::uuid, p_search_query text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_accessible_customers UUID[];
    v_results JSONB;
    v_total_count INTEGER;
    v_is_admin BOOLEAN;
BEGIN
    -- Determine accessible customers
    v_is_admin := is_admin_or_supervisor();

    IF v_is_admin THEN
        -- Admin/Supervisor: all customers (unless p_customer_id specified)
        IF p_customer_id IS NOT NULL THEN
            v_accessible_customers := ARRAY[p_customer_id];
        ELSE
            SELECT ARRAY_AGG(id) INTO v_accessible_customers
            FROM customers WHERE active = true AND deleted_at IS NULL;
        END IF;
    ELSE
        -- Customer role: only assigned customers
        SELECT user_accessible_customers() INTO v_accessible_customers;

        -- SECURITY FIX: Return empty result if no accessible customers (instead of all customers)
        IF COALESCE(array_length(v_accessible_customers, 1), 0) = 0 THEN
            RETURN jsonb_build_object(
                'success', true,
                'data', jsonb_build_object(
                    'items', '[]'::jsonb,
                    'total_count', 0
                )
            );
        END IF;

        IF p_customer_id IS NOT NULL THEN
            IF NOT (p_customer_id = ANY(v_accessible_customers)) THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'error', 'Access denied to customer'
                );
            END IF;
            v_accessible_customers := ARRAY[p_customer_id];
        END IF;
    END IF;

    -- Handle empty customers
    IF COALESCE(array_length(v_accessible_customers, 1), 0) = 0 THEN
        RETURN jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'items', '[]'::jsonb,
                'total_count', 0
            )
        );
    END IF;

    -- Get total count of unique items with stock
    SELECT COUNT(*) INTO v_total_count
    FROM (
        SELECT grt.item_id
        FROM goodsreceived_trl grt
        JOIN goodsreceived gr ON gr.id = grt.gr_id
        WHERE gr.customer_id = ANY(v_accessible_customers)
          AND gr.deleted_at IS NULL
          AND grt.stock > 0
          AND (p_search_query IS NULL OR grt.item_name ILIKE '%' || p_search_query || '%')
        GROUP BY grt.item_id
        HAVING SUM(grt.stock) > 0
    ) AS unique_items;

    -- Build aggregated results grouped by item_id
    SELECT COALESCE(jsonb_agg(item_row ORDER BY item_row->>'item_name'), '[]'::jsonb)
    INTO v_results
    FROM (
        SELECT jsonb_build_object(
            'item_id', grt.item_id,
            'item_name', MAX(grt.item_name),
            'packaging', MAX(grt.packaging),
            'total_qty', SUM(grt.qty)::INTEGER,
            'total_stock', SUM(grt.stock)::INTEGER,
            'grn_count', COUNT(DISTINCT grt.gr_id)::INTEGER
        ) AS item_row
        FROM goodsreceived_trl grt
        JOIN goodsreceived gr ON gr.id = grt.gr_id
        WHERE gr.customer_id = ANY(v_accessible_customers)
          AND gr.deleted_at IS NULL
          AND grt.stock > 0
          AND (p_search_query IS NULL OR grt.item_name ILIKE '%' || p_search_query || '%')
        GROUP BY grt.item_id
        HAVING SUM(grt.stock) > 0
        ORDER BY MAX(grt.item_name) ASC
        LIMIT p_limit
        OFFSET p_offset
    ) AS aggregated;

    -- Return with expected structure
    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'items', v_results,
            'total_count', v_total_count
        )
    );
END;
$$;


CREATE FUNCTION public.get_items(p_search_query text DEFAULT NULL::text, p_active_only boolean DEFAULT true, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result jsonb;
    v_total_count integer;
BEGIN
    -- Get total count
    SELECT COUNT(*) INTO v_total_count
    FROM items
    WHERE (p_active_only = false OR active = true)
      AND (p_search_query IS NULL OR
           name ILIKE '%' || p_search_query || '%' OR
           description ILIKE '%' || p_search_query || '%');

    -- Get items
    SELECT jsonb_agg(
        jsonb_build_object(
            'id', id,
            'name', name,
            'packaging', packaging,
            'description', description,
            'active', active
        ) ORDER BY name
    ) INTO v_result
    FROM (
        SELECT id, name, packaging, description, active
        FROM items
        WHERE (p_active_only = false OR active = true)
          AND (p_search_query IS NULL OR
               name ILIKE '%' || p_search_query || '%' OR
               description ILIKE '%' || p_search_query || '%')
        ORDER BY name
        LIMIT p_limit OFFSET p_offset
    ) sub;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'items', COALESCE(v_result, '[]'::jsonb),
            'total_count', v_total_count,
            'limit', p_limit,
            'offset', p_offset
        )
    );
END;
$$;


CREATE FUNCTION public.get_jwt_secret() RETURNS text
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
      SELECT secret_value
      FROM public.jwt_config
      WHERE secret_name = 'supabase_jwt_secret'
      AND is_active = true
      LIMIT 1;
  $$;


CREATE FUNCTION public.get_next_dispatch_number() RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_max_no TEXT;
    v_next_no TEXT;
    v_num INTEGER;
BEGIN
    -- Get the highest dispatch number (index-only scan, very fast)
    SELECT disp_no INTO v_max_no
    FROM dispatch
    ORDER BY disp_no DESC
    LIMIT 1;

    -- If no dispatches exist, start from I1
    IF v_max_no IS NULL THEN
        RETURN 'I1';
    END IF;

    -- Extract numeric part and increment
    -- Format: I followed by number (e.g., I4817)
    v_num := CAST(SUBSTRING(v_max_no FROM 2) AS INTEGER) + 1;
    v_next_no := 'I' || v_num::TEXT;

    RETURN v_next_no;
END;
$$;


CREATE FUNCTION public.get_next_grn_number() RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_latest_grn TEXT;
    v_prefix CHAR(1);
    v_num INTEGER;
    v_next_prefix CHAR(1);
BEGIN
    -- Find the most recently created GRN (by time, not alphabetical order)
    SELECT gr_no INTO v_latest_grn
    FROM goodsreceived
    ORDER BY created_at DESC, gr_no DESC
    LIMIT 1;

    IF v_latest_grn IS NULL THEN
        RETURN 'A0001';
    END IF;

    v_prefix := LEFT(v_latest_grn, 1);
    v_num := CAST(SUBSTRING(v_latest_grn FROM 2) AS INTEGER);

    -- Find the actual max number within the current prefix series
    SELECT COALESCE(MAX(CAST(SUBSTRING(gr_no FROM 2) AS INTEGER)), 0)
    INTO v_num
    FROM goodsreceived
    WHERE LEFT(gr_no, 1) = v_prefix;

    IF v_num >= 1000 THEN
        -- Advance to next letter: A→B→...→Z→A
        IF v_prefix = 'Z' THEN
            v_next_prefix := 'A';
        ELSE
            v_next_prefix := CHR(ASCII(v_prefix) + 1);
        END IF;
        RETURN v_next_prefix || '0001';
    ELSE
        RETURN v_prefix || LPAD((v_num + 1)::TEXT, 4, '0');
    END IF;
END;
$$;


CREATE FUNCTION public.get_next_invoice_number() RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_max_no INTEGER;
    v_next_no INTEGER;
BEGIN
    SELECT MAX(inv_no) INTO v_max_no
    FROM invoice;

    IF v_max_no IS NULL THEN
        RETURN '1';
    END IF;

    v_next_no := v_max_no + 1;

    RETURN v_next_no::TEXT;
END;
$$;


CREATE FUNCTION public.get_next_invoice_number_with_year() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_next_no integer; v_fin_year integer;
BEGIN
    SELECT CASE WHEN EXTRACT(MONTH FROM NOW()) >= 4 THEN EXTRACT(YEAR FROM NOW()) ELSE EXTRACT(YEAR FROM NOW()) - 1 END INTO v_fin_year;
    SELECT COALESCE(MAX(inv_no), 0) + 1 INTO v_next_no FROM invoice WHERE inv_fin_year = v_fin_year;
    RETURN utils.success_response(jsonb_build_object(
        'next_invoice_number', v_next_no::varchar,
        'financial_year', v_fin_year,
        'full_invoice_number', v_fin_year || '/' || v_next_no
    ));
EXCEPTION WHEN OTHERS THEN RETURN utils.database_error_response('Failed to get next invoice number', SQLERRM, SQLSTATE);
END;
$$;


CREATE FUNCTION public.get_open_invoices_for_customer(p_customer_id uuid, p_payment_date date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
BEGIN
    SELECT COALESCE(jsonb_agg(row_data ORDER BY inv_date DESC), '[]'::JSONB)
    INTO v_result
    FROM (
        SELECT jsonb_build_object(
            'invoice_id', i.id,
            'inv_no', i.inv_no,
            'inv_fin_year', i.inv_fin_year,
            'bill_ref', 'GCS/' || i.inv_fin_year || '/' || i.inv_no,
            'inv_date', i.inv_date,
            'total', i.total,
            'paid', COALESCE(p_sum.paid, 0),
            'outstanding', i.total - COALESCE(p_sum.paid, 0)
        ) AS row_data,
        i.inv_date
        FROM public.invoice i
        LEFT JOIN (
            SELECT invoice_id, SUM(amount) AS paid
            FROM public.payments
            WHERE invoice_id IS NOT NULL
            GROUP BY invoice_id
        ) p_sum ON p_sum.invoice_id = i.id
        WHERE i.customer_id = p_customer_id
          AND i.deleted_at IS NULL
          AND i.total > 0
          AND i.total - COALESCE(p_sum.paid, 0) > 0.50
          AND (
            p_payment_date IS NULL
            OR i.inv_date BETWEEN (p_payment_date - INTERVAL '8 months') AND p_payment_date
          )
    ) sub;

    RETURN jsonb_build_object(
        'success', true,
        'data', v_result
    );
END;
$$;


CREATE FUNCTION public.get_operations_dashboard(p_from_date date, p_to_date date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result JSONB;
    v_user_role TEXT;
BEGIN
    -- Get user role from JWT claims
    v_user_role := COALESCE(
        (current_setting('request.jwt.claims', true)::jsonb ->> 'user_role'),
        (current_setting('request.jwt.claims', true)::jsonb -> 'user_metadata' ->> 'role')
    );

    -- Only admin/supervisor/service_role can access operations dashboard
    IF v_user_role NOT IN ('admin', 'supervisor', 'service_role') THEN
        RETURN jsonb_build_object(
            'error', 'Access denied: admin or supervisor role required',
            'kpis', NULL,
            'trends', NULL,
            'recent_activity', '[]'::jsonb
        );
    END IF;

    SELECT jsonb_build_object(
        'kpis', jsonb_build_object(
            'total_grns', (
                SELECT COUNT(*)
                FROM goodsreceived
                WHERE deleted_at IS NULL
                  AND date::date >= p_from_date
                  AND date::date <= p_to_date
            ),
            'total_dispatches', (
                SELECT COUNT(*)
                FROM dispatch
                WHERE deleted_at IS NULL
                  AND disp_date::date >= p_from_date
                  AND disp_date::date <= p_to_date
            ),
            'pending_orders', (
                SELECT COUNT(*)
                FROM orders
                WHERE deleted_at IS NULL
                  AND status = 'OPEN'
                  AND is_ignored = false
            ),
            'active_customers', (
                SELECT COUNT(DISTINCT g.customer_id)
                FROM goodsreceived g
                JOIN goodsreceived_trl gt ON gt.gr_id = g.id
                WHERE g.deleted_at IS NULL
                  AND gt.stock > 0
            ),
            'total_stock_qty', (
                SELECT COALESCE(SUM(gt.stock), 0)
                FROM goodsreceived g
                JOIN goodsreceived_trl gt ON gt.gr_id = g.id
                WHERE g.deleted_at IS NULL
                  AND gt.stock > 0
            ),
            -- Fixed: weight is per unit, so total = weight × stock
            'total_stock_weight', (
                SELECT COALESCE(SUM(gt.weight::numeric * gt.stock), 0)
                FROM goodsreceived g
                JOIN goodsreceived_trl gt ON gt.gr_id = g.id
                WHERE g.deleted_at IS NULL
                  AND gt.stock > 0
            )
        ),
        'trends', jsonb_build_object(
            'grn_daily', COALESCE((
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'date', grn_date,
                        'count', grn_count
                    ) ORDER BY grn_date
                )
                FROM (
                    SELECT date::date AS grn_date, COUNT(*) AS grn_count
                    FROM goodsreceived
                    WHERE deleted_at IS NULL
                      AND date::date >= p_from_date
                      AND date::date <= p_to_date
                    GROUP BY date::date
                ) AS daily_grns
            ), '[]'::jsonb),
            'dispatch_daily', COALESCE((
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'date', disp_date,
                        'count', disp_count
                    ) ORDER BY disp_date
                )
                FROM (
                    SELECT disp_date::date AS disp_date, COUNT(*) AS disp_count
                    FROM dispatch
                    WHERE deleted_at IS NULL
                      AND disp_date::date >= p_from_date
                      AND disp_date::date <= p_to_date
                    GROUP BY disp_date::date
                ) AS daily_dispatches
            ), '[]'::jsonb)
        ),
        'recent_activity', COALESCE((
            SELECT jsonb_agg(activity ORDER BY activity->>'time' DESC)
            FROM (
                (SELECT jsonb_build_object(
                    'type', 'grn',
                    'ref', gr_no,
                    'customer', customer_name,
                    'time', created_at
                ) AS activity
                FROM goodsreceived
                WHERE deleted_at IS NULL
                ORDER BY created_at DESC
                LIMIT 10)

                UNION ALL

                (SELECT jsonb_build_object(
                    'type', 'dispatch',
                    'ref', disp_no,
                    'customer', customer_name,
                    'time', created_at
                ) AS activity
                FROM dispatch
                WHERE deleted_at IS NULL
                ORDER BY created_at DESC
                LIMIT 10)
            ) AS combined_activity
        ), '[]'::jsonb)
    ) INTO v_result;

    RETURN v_result;
END;
$$;


CREATE FUNCTION public.get_or_create_cart(p_customer_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_cart_id UUID;
      v_customer_record RECORD;
      v_user_id UUID;
  BEGIN
      -- Get current user
      SELECT id INTO v_user_id
      FROM user_profiles
      WHERE auth_user_id = auth.uid();

      -- Get customer details
      SELECT id, name, email, mobile
      INTO v_customer_record
      FROM customers
      WHERE id = p_customer_id;

      IF NOT FOUND THEN
          RAISE EXCEPTION 'Customer not found: %', p_customer_id;
      END IF;

      -- Check if cart exists (regardless of status)
      SELECT id INTO v_cart_id
      FROM orders
      WHERE customer_id = p_customer_id
        AND deleted_at IS NULL;

      IF FOUND THEN
          -- Cart exists - ensure it's OPEN (reset if DISPATCHED)
          UPDATE orders
          SET status = 'OPEN',
              updated_at = NOW(),
              updated_by = v_user_id
          WHERE id = v_cart_id
            AND status = 'DISPATCHED';
      ELSE
          -- No cart exists - create new OPEN cart
          INSERT INTO orders (
              customer_id,
              customer_name,
              customer_email,
              customer_phone,
              order_date,
              requested_dispatch_date,
              status,
              priority,
              created_by,
              updated_by
          ) VALUES (
              p_customer_id,
              v_customer_record.name,
              v_customer_record.email,
              v_customer_record.mobile,
              NOW(),
              NOW() + INTERVAL '7 days',
              'OPEN',
              'normal',
              v_user_id,
              v_user_id
          )
          RETURNING id INTO v_cart_id;
      END IF;

      RETURN v_cart_id;
  END;
$$;


CREATE FUNCTION public.get_order_change_log(p_order_id uuid DEFAULT NULL::uuid, p_customer_id uuid DEFAULT NULL::uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_user_id uuid DEFAULT NULL::uuid, p_change_type text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
      DECLARE
          v_user_role TEXT;
          v_accessible_customers UUID[];
          v_result JSONB;
      BEGIN
          -- Security: Get user role and accessible customers
          SELECT role INTO v_user_role FROM user_profiles WHERE auth_user_id = auth.uid();

          IF NOT is_admin_or_supervisor() THEN
              v_accessible_customers := user_accessible_customers();
              IF v_accessible_customers IS NULL OR array_length(v_accessible_customers, 1) IS NULL THEN
                  RETURN jsonb_build_object(
                      'success', false,
                      'message', 'Access denied: No accessible customers',
                      'data', null
                  );
              END IF;
          END IF;

          -- Build comprehensive change log focusing on quantity changes and dispatch events
          WITH
          -- Step 1: Build one flat, ordered stream of all item events
          item_events AS (
              -- Manual UPDATEs
              SELECT
                  o.id                                 AS order_id,
                  o.order_no,
                  o.customer_id,
                  o.customer_name,
                  (r.value->>'at')::timestamptz        AS ts,
                  'UPDATE'                             AS action,
                  ci.value->>'item_id'                 AS item_id,
                  ci.value->>'grn_no'                  AS grn_no,
                  ci.value->>'item_name'               AS item_name,
                  ci.value->>'package_mark'            AS package_mark,
                  (ci.value->>'quantity')::int         AS qty_after_event,
                  CASE
                      WHEN r.value->>'by' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                      THEN (r.value->>'by')::uuid
                      ELSE NULL
                  END as changed_by,
                  NULL::uuid as dispatch_id,
                  NULL::text as dispatch_no,
                  ci.value as full_item_data
              FROM   orders o
              CROSS  JOIN LATERAL jsonb_array_elements(o.revisions) r
              CROSS  JOIN LATERAL jsonb_array_elements(r.value->'cart_items') ci
              WHERE  r.value->>'action' = 'UPDATE'

              UNION ALL

              -- OLD-format auto_quantity_reduction (with cart_items)
              SELECT
                  o.id,
                  o.order_no,
                  o.customer_id,
                  o.customer_name,
                  (r.value->>'at')::timestamptz,
                  'DISPATCH_REDUCTION',
                  ci.value->>'item_id',
                  ci.value->>'grn_no',
                  ci.value->>'item_name',
                  ci.value->>'package_mark',
                  (r.value->>'new_quantity')::int,
                  CASE
                      WHEN r.value->>'by' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                      THEN (r.value->>'by')::uuid
                      ELSE NULL
                  END,
                  (r.value->>'dispatch_id')::uuid,
                  r.value->>'dispatch_no',
                  ci.value
              FROM   orders o
              CROSS  JOIN LATERAL jsonb_array_elements(o.revisions) r
              CROSS  JOIN LATERAL jsonb_array_elements(r.value->'cart_items') ci
              WHERE  r.value->>'action' = 'auto_quantity_reduction'
                AND  r.value ? 'cart_items'

              UNION ALL

              -- NEW-format auto_quantity_reduction (with grn_item_id)
              SELECT
                  o.id,
                  o.order_no,
                  o.customer_id,
                  o.customer_name,
                  COALESCE((r.value->>'timestamp')::timestamptz,
                           (r.value->>'at')::timestamptz),
                  'DISPATCH_REDUCTION',
                  gt.id::text,
                  gr.gr_no,
                  gt.item_name,
                  gt.package_mark,
                  (r.value->>'new_quantity')::int,
                  d.supervisor_id,
                  (r.value->>'dispatch_id')::uuid,
                  r.value->>'dispatch_no',
                  jsonb_build_object(
                      'item_id', gt.id::text,
                      'grn_no', gr.gr_no,
                      'item_name', gt.item_name,
                      'package_mark', gt.package_mark
                  )
              FROM   orders o
              CROSS  JOIN LATERAL jsonb_array_elements(o.revisions) r
              LEFT JOIN goodsreceived_trl gt ON gt.id = (r.value->>'grn_item_id')::uuid
              LEFT JOIN goodsreceived     gr ON gr.id = gt.gr_id
              LEFT JOIN dispatch d ON d.id = (r.value->>'dispatch_id')::uuid
              WHERE  r.value->>'action' = 'auto_quantity_reduction'
                AND  NOT (r.value ? 'cart_items')
                AND  r.value ? 'grn_item_id'
          ),

          -- Step 2: Calculate previous quantity using lag() with composite key
          item_events_with_prev AS (
              SELECT *,
                     lag(qty_after_event) OVER (
                         PARTITION BY order_id, item_key
                         ORDER BY ts
                     ) AS prev_qty
              FROM (
                  SELECT *,
                         (grn_no || '|' || COALESCE(package_mark,'') || '|' || item_name) AS item_key
                  FROM item_events
              ) x
          ),

          -- Step 3: Format quantity changes for display
          quantity_changes AS (
              SELECT
                  'order_level' AS change_category,
                  CASE
                      WHEN action = 'UPDATE'
                           THEN 'quantity_changed'
                      ELSE 'quantity_reduced_by_dispatch'
                  END           AS change_type,
                  order_id,
                  order_no,
                  customer_id,
                  customer_name,
                  NULL::UUID as order_item_id,
                  CASE
                      WHEN action = 'UPDATE'
                           THEN 'Quantity changed: ' || item_name
                      ELSE 'Dispatch reduced quantity: ' || item_name
                  END as item_name,
                  grn_no,
                  package_mark,
                  jsonb_build_object(
                      'action', CASE
                          WHEN action = 'UPDATE' THEN 'quantity_changed'
                          ELSE 'quantity_reduced_by_dispatch'
                      END,
                      'grn_details', jsonb_build_object(
                          'grn_no', grn_no,
                          'grn_qty', COALESCE(
                              (SELECT qty FROM goodsreceived_trl gt
                               JOIN goodsreceived g ON g.id = gt.gr_id
                               WHERE g.gr_no = grn_no
                               AND gt.item_name = item_name
                               AND COALESCE(gt.package_mark, '') = COALESCE(package_mark, '')
                               LIMIT 1), 0
                          ),
                         'grn_quantity', COALESCE(
                             (SELECT qty FROM goodsreceived_trl gt
                              JOIN goodsreceived g ON g.id = gt.gr_id
                              WHERE g.gr_no = grn_no
                              AND gt.item_name = item_name
                              AND COALESCE(gt.package_mark, '') = COALESCE(package_mark, '')
                              LIMIT 1), 0
                         ),
                          'grn_item_name', item_name,
                          'grn_item_rack', COALESCE(
                              (SELECT rack FROM goodsreceived_trl gt
                               JOIN goodsreceived g ON g.id = gt.gr_id
                               WHERE g.gr_no = grn_no
                               AND gt.item_name = item_name
                               AND COALESCE(gt.package_mark, '') = COALESCE(package_mark, '')
                               LIMIT 1), ''
                          ),
                          'grn_item_weight', COALESCE(
                              (SELECT weight FROM goodsreceived_trl gt
                               JOIN goodsreceived g ON g.id = gt.gr_id
                               WHERE g.gr_no = grn_no
                               AND gt.item_name = item_name
                               AND COALESCE(gt.package_mark, '') = COALESCE(package_mark, '')
                               LIMIT 1), 0
                          ),
                          'grn_item_packaging', COALESCE(
                              (SELECT packaging FROM goodsreceived_trl gt
                               JOIN goodsreceived g ON g.id = gt.gr_id
                               WHERE g.gr_no = grn_no
                               AND gt.item_name = item_name
                               AND COALESCE(gt.package_mark, '') = COALESCE(package_mark, '')
                               LIMIT 1), ''
                          ),
                          'grn_item_package_mark', package_mark
                      ),
                      'quantity_change', jsonb_build_object(
                          'change_type', CASE
                              WHEN prev_qty IS NULL THEN 'added'
                              WHEN qty_after_event = 0 THEN 'removed'
                              WHEN qty_after_event > COALESCE(prev_qty, 0) THEN 'increased'
                              WHEN qty_after_event < COALESCE(prev_qty, 0) THEN 'decreased'
                              ELSE 'changed'
                          END,
                          'previous_quantity', COALESCE(prev_qty, 0),
                          'new_quantity', qty_after_event,
                          'change_amount', qty_after_event - COALESCE(prev_qty, 0)
                      ),
                      'dispatch_id', dispatch_id,
                      'dispatch_no', dispatch_no,
                      'dispatch_impact', CASE
                          WHEN action = 'DISPATCH_REDUCTION' THEN
                              jsonb_build_object(
                                  'previous_quantity', COALESCE(prev_qty, 0),
                                  'new_quantity', qty_after_event,
                                  'dispatched_quantity', COALESCE(prev_qty, 0) - qty_after_event
                              )
                          ELSE NULL
                      END
                  ) AS change_details,
                  ts AS change_timestamp,
                  changed_by as changed_by_id,
                  up.name as changed_by_name,
                  up.display_name as changed_by_display_name,
                  CASE WHEN action='DISPATCH_REDUCTION' THEN 2 ELSE 1 END AS sort_priority
              FROM   item_events_with_prev
              LEFT JOIN user_profiles up ON up.id = changed_by
              WHERE (p_order_id IS NULL OR order_id = p_order_id)
              AND (p_customer_id IS NULL OR customer_id = p_customer_id)
              AND (p_user_id IS NULL OR changed_by = p_user_id)
              AND (p_date_from IS NULL OR ts >= p_date_from)
              AND (p_date_to IS NULL OR ts <= p_date_to)
              AND (p_change_type IS NULL OR
                   (p_change_type = 'quantity_changed' AND action = 'UPDATE') OR
                   (p_change_type = 'quantity_reduced_by_dispatch' AND action = 'DISPATCH_REDUCTION'))
              AND (v_user_role IN ('admin', 'supervisor', 'staff') OR customer_id = ANY(v_accessible_customers))

              UNION ALL

              -- Process dispatch deletion entries - INDIVIDUAL ENTRIES PER RESTORED ITEM
              SELECT DISTINCT
                  'order_level' as change_category,
                  'dispatch_deleted' as change_type,
                  o.id as order_id,
                  o.order_no,
                  o.customer_id,
                  o.customer_name,
                  NULL::UUID as order_item_id,
                  'Dispatch deleted: ' || (ri.value->>'item_name') ||
                  ' from ' || (ri.value->>'grn_no') ||
                  ' (restored ' || (ri.value->>'quantity_restored') || ' units)' as item_name,
                  ri.value->>'grn_no' as grn_no,
                  ri.value->>'package_mark' as package_mark,
                  jsonb_build_object(
                      'action', 'dispatch_deleted',
                      'dispatch_id', r.value->>'dispatch_id',
                      'dispatch_no', r.value->>'dispatch_no',
                      'grn_details', jsonb_build_object(
                          'grn_no', ri.value->>'grn_no',
                          'grn_qty', COALESCE(
                              (SELECT qty FROM goodsreceived_trl gt
                               JOIN goodsreceived g ON g.id = gt.gr_id
                               WHERE g.gr_no = ri.value->>'grn_no'
                               AND gt.item_name = ri.value->>'item_name'
                               AND COALESCE(gt.package_mark, '') = COALESCE(ri.value->>'package_mark', '')
                               LIMIT 1), 0
                          ),
                         'grn_quantity', COALESCE(
                             (SELECT qty FROM goodsreceived_trl gt
                              JOIN goodsreceived g ON g.id = gt.gr_id
                              WHERE g.gr_no = ri.value->>'grn_no'
                              AND gt.item_name = ri.value->>'item_name'
                              AND COALESCE(gt.package_mark, '') = COALESCE(ri.value->>'package_mark', '')
                              LIMIT 1), 0
                         ),
                          'grn_item_name', ri.value->>'item_name',
                          'grn_item_rack', COALESCE(
                              (SELECT rack FROM goodsreceived_trl gt
                               JOIN goodsreceived g ON g.id = gt.gr_id
                               WHERE g.gr_no = ri.value->>'grn_no'
                               AND gt.item_name = ri.value->>'item_name'
                               AND COALESCE(gt.package_mark, '') = COALESCE(ri.value->>'package_mark', '')
                               LIMIT 1), ''
                          ),
                          'grn_item_weight', COALESCE(
                              (SELECT weight FROM goodsreceived_trl gt
                               JOIN goodsreceived g ON g.id = gt.gr_id
                               WHERE g.gr_no = ri.value->>'grn_no'
                               AND gt.item_name = ri.value->>'item_name'
                               AND COALESCE(gt.package_mark, '') = COALESCE(ri.value->>'package_mark', '')
                               LIMIT 1), 0
                          ),
                          'grn_item_packaging', COALESCE(
                              (SELECT packaging FROM goodsreceived_trl gt
                               JOIN goodsreceived g ON g.id = gt.gr_id
                               WHERE g.gr_no = ri.value->>'grn_no'
                               AND gt.item_name = ri.value->>'item_name'
                               AND COALESCE(gt.package_mark, '') = COALESCE(ri.value->>'package_mark', '')
                               LIMIT 1), ''
                          ),
                          'grn_item_package_mark', ri.value->>'package_mark'
                      ),
                      'restoration_details', jsonb_build_object(
                          'quantity_restored', (ri.value->>'quantity_restored')::INT,
                          'dispatch_deleted', r.value->>'dispatch_no'
                      )
                  ) as change_details,
                  (r.value->>'timestamp')::TIMESTAMP WITH TIME ZONE as change_timestamp,
                  CASE
                      WHEN r.value->>'by' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                      THEN (r.value->>'by')::uuid
                      ELSE NULL
                  END as changed_by_id,
                  up.name as changed_by_name,
                  up.display_name as changed_by_display_name,
                  4 as sort_priority
              FROM orders o
              CROSS JOIN LATERAL jsonb_array_elements(o.revisions) r
              CROSS JOIN LATERAL jsonb_array_elements(r.value->'restored_items') ri
              LEFT JOIN user_profiles up ON up.id = CASE
                  WHEN r.value->>'by' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                  THEN (r.value->>'by')::uuid
                  ELSE NULL
              END
              WHERE r.value->>'action' = 'dispatch_deleted'
              AND (p_order_id IS NULL OR o.id = p_order_id)
              AND (p_customer_id IS NULL OR o.customer_id = p_customer_id)
              AND (p_user_id IS NULL OR CASE
                  WHEN r.value->>'by' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                  THEN (r.value->>'by')::uuid
                  ELSE NULL
              END = p_user_id)
              AND (p_date_from IS NULL OR (r.value->>'timestamp')::TIMESTAMP WITH TIME ZONE >= p_date_from)
              AND (p_date_to IS NULL OR (r.value->>'timestamp')::TIMESTAMP WITH TIME ZONE <= p_date_to)
              AND (p_change_type IS NULL OR p_change_type = 'dispatch_deleted')
              AND (v_user_role IN ('admin', 'supervisor', 'staff') OR o.customer_id = ANY(v_accessible_customers))
          ),

          -- Enhanced order item changes from revisions field with GRN quantity
          order_item_changes AS (
              SELECT
                  'item_level' as change_category,
                  COALESCE(revision_entry.value->>'action', 'unknown') as change_type,
                  oi.order_id,
                  oi.order_no,
                  o.customer_id,
                  o.customer_name,
                  oi.id as order_item_id,
                  oi.grn_items_item_name as item_name,
                  oi.grns_gr_no as grn_no,
                  oi.grn_items_package_mark as package_mark,
                  -- Enhanced change details with GRN quantity included
                  jsonb_build_object(
                      'action', revision_entry.value->>'action',
                      'item_details', jsonb_build_object(
                          'item_name', oi.grn_items_item_name,
                          'grn_no', oi.grns_gr_no,
                          'package_mark', oi.grn_items_package_mark,
                          'rack', oi.grn_items_rack,
                          'weight', oi.grn_items_weight,
                          'packaging', oi.grn_items_packaging,
                          -- Add GRN quantity with multiple field names for compatibility
                          'grn_qty', COALESCE(grt.qty, 0),
                          'grn_quantity', COALESCE(grt.qty, 0),
                          'original_quantity', COALESCE(grt.qty, 0),
                          'qty', COALESCE(grt.qty, 0)
                      ),
                      'quantity_change', CASE
                          WHEN revision_entry.value ? 'previous_qty' AND revision_entry.value ? 'new_qty' THEN
                              jsonb_build_object(
                                  'previous_quantity', revision_entry.value->'previous_qty',
                                  'new_quantity', revision_entry.value->'new_qty',
                                  'change_amount', (revision_entry.value->>'new_qty')::INTEGER -
      (revision_entry.value->>'previous_qty')::INTEGER
                              )
                          WHEN revision_entry.value ? 'requested_quantity' THEN
                              jsonb_build_object(
                                  'quantity', revision_entry.value->'requested_quantity'
                              )
                          ELSE NULL
                      END,
                      'stock_info', CASE
                          WHEN revision_entry.value ? 'available_stock' THEN
                              jsonb_build_object(
                                  'available_stock', revision_entry.value->'available_stock',
                                  'stock_at_time', revision_entry.value->'available_stock'
                              )
                          ELSE NULL
                      END,
                      'reason', revision_entry.value->>'reason',
                      'additional_details', revision_entry.value->'details'
                  ) as change_details,
                  (revision_entry.value->>'timestamp')::TIMESTAMP WITH TIME ZONE as change_timestamp,
                  CASE
                      WHEN revision_entry.value->>'changed_by' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                      THEN (revision_entry.value->>'changed_by')::uuid
                      ELSE NULL
                  END as changed_by_id,
                  up.name as changed_by_name,
                  up.display_name as changed_by_display_name,
                  2 as sort_priority
              FROM order_items oi
              JOIN orders o ON o.id = oi.order_id
              -- JOIN with goodsreceived_trl to get the original GRN quantity
              LEFT JOIN goodsreceived_trl grt ON grt.id = oi.grn_items_id
              LEFT JOIN LATERAL jsonb_array_elements(oi.revisions) AS revision_entry(value) ON true
              LEFT JOIN user_profiles up ON up.id = CASE
                  WHEN revision_entry.value->>'changed_by' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                  THEN (revision_entry.value->>'changed_by')::uuid
                  ELSE NULL
              END
              WHERE (p_order_id IS NULL OR oi.order_id = p_order_id)
              AND (p_customer_id IS NULL OR o.customer_id = p_customer_id)
              AND (p_user_id IS NULL OR CASE
                  WHEN revision_entry.value->>'changed_by' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                  THEN (revision_entry.value->>'changed_by')::uuid
                  ELSE NULL
              END = p_user_id)
              AND (p_date_from IS NULL OR (revision_entry.value->>'timestamp')::TIMESTAMP WITH TIME ZONE >= p_date_from)
              AND (p_date_to IS NULL OR (revision_entry.value->>'timestamp')::TIMESTAMP WITH TIME ZONE <= p_date_to)
              AND (p_change_type IS NULL OR p_change_type = 'item_level' OR p_change_type = revision_entry.value->>'action')
              AND (v_user_role IN ('admin', 'supervisor', 'staff') OR o.customer_id = ANY(v_accessible_customers))
              AND oi.revisions IS NOT NULL
              AND jsonb_array_length(oi.revisions) > 0
          ),

          -- Add dispatch-related changes
          dispatch_changes AS (
              SELECT
                  'dispatch_level' as change_category,
                  'dispatch_created' as change_type,
                  d.source_order_id as order_id,
                  d.source_order_no as order_no,
                  d.customer_id,
                  d.customer_name,
                  NULL::UUID as order_item_id,
                  'Dispatch created: ' || d.disp_no as item_name,
                  NULL as grn_no,
                  NULL as package_mark,
                  jsonb_build_object(
                      'action', 'dispatch_created',
                      'dispatch_details', jsonb_build_object(
                          'dispatch_id', d.id,
                          'dispatch_no', d.disp_no,
                          'registration', d.registration,
                          'supervisor_name', d.supervisor_name,
                          'grn_items', (
                              SELECT jsonb_agg(
                                  jsonb_build_object(
                                      'grn_no', gr.gr_no,
                                      'grn_qty', gt.qty,
                                      'grn_quantity', gt.qty,
                                      'grn_item_name', gt.item_name,
                                      'grn_item_package_mark', gt.package_mark,
                                      'grn_item_rack', gt.rack,
                                      'grn_item_weight', gt.weight,
                                      'grn_item_packaging', gt.packaging,
                                      'dispatch_qty', dt.disp_qty
                                  ) ORDER BY gt.item_name
                              )
                              FROM dispatch_trl dt
                              JOIN goodsreceived_trl gt ON gt.id = dt.gr_trl_id
                              JOIN goodsreceived gr ON gr.id = gt.gr_id
                              WHERE dt.disp_id = d.id
                          )
                      ),
                      'dispatch_summary', jsonb_build_object(
                          'total_items', (SELECT COUNT(*) FROM dispatch_trl dt WHERE dt.disp_id = d.id),
                          'total_quantity', (SELECT COALESCE(SUM(dt.disp_qty), 0) FROM dispatch_trl dt WHERE dt.disp_id = d.id)
                      )
                  ) as change_details,
                  d.created_at as change_timestamp,
                  d.supervisor_id as changed_by_id,
                  up.name as changed_by_name,
                  up.display_name as changed_by_display_name,
                  3 as sort_priority
              FROM dispatch d
              LEFT JOIN user_profiles up ON up.id = d.supervisor_id
              WHERE d.source_order_id IS NOT NULL
              AND (p_order_id IS NULL OR d.source_order_id = p_order_id)
              AND (p_customer_id IS NULL OR d.customer_id = p_customer_id)
              AND (p_user_id IS NULL OR d.supervisor_id = p_user_id)
              AND (p_date_from IS NULL OR d.created_at >= p_date_from)
              AND (p_date_to IS NULL OR d.created_at <= p_date_to)
              AND (p_change_type IS NULL OR p_change_type = 'dispatch_level')
              AND (v_user_role IN ('admin', 'supervisor', 'staff') OR d.customer_id = ANY(COALESCE(v_accessible_customers, '{}'::uuid[])))
          ),

          -- Combine all changes
          all_changes AS (
              SELECT * FROM quantity_changes
              UNION ALL
              SELECT * FROM order_item_changes
              UNION ALL
              SELECT * FROM dispatch_changes
          ),

          -- Get paginated results
          paginated_changes AS (
              SELECT *
              FROM all_changes
              ORDER BY change_timestamp DESC, sort_priority ASC
              LIMIT p_limit OFFSET p_offset
          ),

          -- Build final response
          change_log AS (
              SELECT jsonb_agg(
                  jsonb_build_object(
                      'change_category', change_category,
                      'change_type', change_type,
                      'order_id', order_id,
                      'order_no', order_no,
                      'customer_id', customer_id,
                      'customer_name', customer_name,
                      'order_item_id', order_item_id,
                      'item_name', item_name,
                      'grn_no', grn_no,
                      'package_mark', package_mark,
                      'change_details', change_details,
                      'change_timestamp', change_timestamp,
                      'changed_by_id', changed_by_id,
                      'changed_by_name', changed_by_name,
                      'changed_by_display_name', changed_by_display_name,
                      'formatted_timestamp', to_char(change_timestamp, 'DD-MM-YYYY HH24:MI:SS'),
                      'relative_time', CASE
                          WHEN change_timestamp > NOW() - INTERVAL '1 minute' THEN 'Just now'
                          WHEN change_timestamp > NOW() - INTERVAL '1 hour' THEN
                              extract(epoch from (NOW() - change_timestamp))::integer / 60 || ' minutes ago'
                          WHEN change_timestamp > NOW() - INTERVAL '1 day' THEN
                              extract(hour from (NOW() - change_timestamp))::integer || ' hours ago'
                          WHEN change_timestamp > NOW() - INTERVAL '7 days' THEN
                              extract(day from (NOW() - change_timestamp))::integer || ' days ago'
                          ELSE to_char(change_timestamp, 'DD Mon YYYY')
                      END
                  )
                  ORDER BY change_timestamp DESC, sort_priority ASC
              ) as changes
              FROM paginated_changes
          )

          SELECT jsonb_build_object(
              'success', true,
              'data', jsonb_build_object(
                  'changes', COALESCE(cl.changes, '[]'::jsonb),
                  'total_count', (SELECT COUNT(*) FROM all_changes),
                  'has_more', (p_offset + p_limit) < (SELECT COUNT(*) FROM all_changes)
              ),
              'message', 'Order change log retrieved successfully'
          ) INTO v_result
          FROM change_log cl;

          RETURN v_result;

      EXCEPTION
          WHEN OTHERS THEN
              RETURN jsonb_build_object(
                  'success', false,
                  'data', null,
                  'message', 'Error retrieving order change log: ' || SQLERRM
              );
      END;
      $_$;


CREATE FUNCTION public.get_order_item_change_summary(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_result JSONB;
  BEGIN
      -- Get comprehensive summary of all changes per item
      WITH item_changes AS (
          SELECT
              oi.id,
              oi.grn_items_item_name,
              oi.requested_quantity,
              oi.fulfilled_quantity,
              oi.created_at,
              oi.updated_at,
              jsonb_array_length(COALESCE(oi.revisions, '[]'::jsonb)) as total_changes,
              -- Extract specific change types
              (
                  SELECT COUNT(*)
                  FROM jsonb_array_elements(COALESCE(oi.revisions, '[]'::jsonb)) AS rev
                  WHERE rev->>'action' = 'quantity_updated'
              ) as quantity_changes,
              (
                  SELECT COUNT(*)
                  FROM jsonb_array_elements(COALESCE(oi.revisions, '[]'::jsonb)) AS rev
                  WHERE rev->>'action' = 'item_added'
              ) as additions,
              (
                  SELECT COUNT(*)
                  FROM jsonb_array_elements(COALESCE(oi.revisions, '[]'::jsonb)) AS rev
                  WHERE rev->>'action' = 'item_removed'
              ) as removals,
              -- Get last change details
              (
                  SELECT rev
                  FROM jsonb_array_elements(COALESCE(oi.revisions, '[]'::jsonb)) AS rev
                  ORDER BY (rev->>'timestamp')::TIMESTAMP WITH TIME ZONE DESC
                  LIMIT 1
              ) as last_change
          FROM order_items oi
          WHERE oi.order_id = p_order_id
      )

      SELECT jsonb_build_object(
          'success', true,
          'data', jsonb_build_object(
              'order_id', p_order_id,
              'items', jsonb_agg(
                  jsonb_build_object(
                      'item_id', ic.id,
                      'item_name', ic.grn_items_item_name,
                      'current_requested_qty', ic.requested_quantity,
                      'current_fulfilled_qty', ic.fulfilled_quantity,
                      'total_changes', ic.total_changes,
                      'quantity_changes', ic.quantity_changes,
                      'additions', ic.additions,
                      'removals', ic.removals,
                      'last_change', ic.last_change,
                      'created_at', ic.created_at,
                      'updated_at', ic.updated_at
                  )
              ),
              'summary', jsonb_build_object(
                  'total_items', COUNT(*),
                  'items_with_changes', COUNT(*) FILTER (WHERE ic.total_changes > 0),
                  'total_changes_across_all_items', COALESCE(SUM(ic.total_changes), 0)
              )
          ),
          'message', 'Order item change summary retrieved successfully'
      ) INTO v_result
      FROM item_changes ic;

      RETURN v_result;
  END;
  $$;


CREATE FUNCTION public.get_order_list(p_filters jsonb DEFAULT '[]'::jsonb, p_sort_field text DEFAULT 'created_at'::text, p_sort_direction text DEFAULT 'DESC'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_orders jsonb;
    v_total_count bigint;
BEGIN
    -- Get orders with filters
    WITH filtered_orders AS (
        SELECT o.*, c.name as customer_name
        FROM orders o
        LEFT JOIN customers c ON o.customer_id = c.id
        WHERE o.deleted_at IS NULL
        ORDER BY
            CASE WHEN p_sort_direction = 'ASC' THEN o.created_at END ASC,
            CASE WHEN p_sort_direction = 'DESC' THEN o.created_at END DESC
        LIMIT p_limit OFFSET p_offset
    )
    SELECT COALESCE(jsonb_agg(row_to_json(fo)::jsonb), '[]'::jsonb), COUNT(*) OVER()
    INTO v_orders, v_total_count
    FROM filtered_orders fo;

    SELECT COUNT(*) INTO v_total_count FROM orders WHERE deleted_at IS NULL;

    RETURN utils.success_response_paginated(v_orders, COALESCE(v_total_count, 0), p_limit, p_offset);
EXCEPTION
    WHEN OTHERS THEN
        RETURN utils.database_error_response('Failed to get order list', SQLERRM, SQLSTATE);
END;
$$;


CREATE FUNCTION public.get_order_queue(p_limit integer DEFAULT 20, p_offset integer DEFAULT 0, p_sort_field text DEFAULT 'requested_dispatch_date'::text, p_sort_direction text DEFAULT 'ASC'::text, p_filters jsonb DEFAULT '[]'::jsonb, p_include_ignored boolean DEFAULT false, p_queue_view text DEFAULT 'pending'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_accessible_customers UUID[];
    v_base_where TEXT;
    v_filter_where TEXT := '';
    v_orders_result JSONB;
    v_total BIGINT;
    v_aggregations JSONB;
    v_filter JSONB;
    v_filters_array JSONB;
    v_sort_column TEXT;
    v_allowed_sort_columns TEXT[] := ARRAY['requested_dispatch_date', 'order_date', 'created_at', 'priority', 'order_no', 'customer_name', 'order_date', 'order_no', 'requested_dispatch_date', 'customer_name'];
BEGIN
    -- Validate sort column
    IF p_sort_field = ANY(v_allowed_sort_columns) THEN
        CASE p_sort_field
            WHEN 'order_date' THEN v_sort_column := 'order_date';
            WHEN 'order_no' THEN v_sort_column := 'order_no';
            WHEN 'requested_dispatch_date' THEN v_sort_column := 'requested_dispatch_date';
            WHEN 'customer_name' THEN v_sort_column := 'customer_name';
            ELSE v_sort_column := p_sort_field;
        END CASE;
    ELSE
        v_sort_column := 'requested_dispatch_date';
    END IF;

    IF UPPER(p_sort_direction) NOT IN ('ASC', 'DESC') THEN
        p_sort_direction := 'ASC';
    END IF;

    -- Get accessible customers for non-admin users
    IF NOT is_admin_or_supervisor() THEN
        v_accessible_customers := ARRAY(SELECT customer_id FROM user_customer_access WHERE user_id = auth.uid());
        v_base_where := 'o.customer_id = ANY($3)';
    ELSE
        v_base_where := '1=1';
    END IF;

    -- Handle filters array
    v_filters_array := COALESCE(p_filters, '[]'::jsonb);
    IF jsonb_typeof(v_filters_array) != 'array' THEN
        v_filters_array := '[]'::jsonb;
    END IF;

    -- Build queue view filter
    CASE p_queue_view
        WHEN 'pending' THEN
            v_filter_where := format(' AND o.status = %L', 'pending');
            IF NOT p_include_ignored THEN v_filter_where := v_filter_where || ' AND o.is_ignored = false'; END IF;
        WHEN 'partially_fulfilled' THEN
            v_filter_where := format(' AND o.status = %L', 'partially_fulfilled');
            IF NOT p_include_ignored THEN v_filter_where := v_filter_where || ' AND o.is_ignored = false'; END IF;
        WHEN 'active' THEN
            v_filter_where := format(' AND o.status IN (%L, %L)', 'pending', 'partially_fulfilled');
            IF NOT p_include_ignored THEN v_filter_where := v_filter_where || ' AND o.is_ignored = false'; END IF;
        WHEN 'fulfilled' THEN v_filter_where := format(' AND o.status = %L', 'fulfilled');
        WHEN 'cancelled' THEN v_filter_where := format(' AND o.status = %L', 'cancelled');
        WHEN 'ignored' THEN v_filter_where := ' AND o.is_ignored = true';
        WHEN 'overdue' THEN
            v_filter_where := format(' AND o.requested_dispatch_date < now() AND o.status IN (%L, %L)', 'pending', 'partially_fulfilled');
            IF NOT p_include_ignored THEN v_filter_where := v_filter_where || ' AND o.is_ignored = false'; END IF;
        ELSE v_filter_where := '';
    END CASE;

    -- Build dynamic filters
    FOR v_filter IN SELECT * FROM jsonb_array_elements(v_filters_array)
    LOOP
        IF v_filter->>'field' = 'status' THEN
            v_filter_where := v_filter_where || format(' AND o.status = %L', v_filter->>'value');
        ELSIF v_filter->>'field' = 'priority' THEN
            v_filter_where := v_filter_where || format(' AND o.priority = %L', v_filter->>'value');
        ELSIF v_filter->>'field' IN ('customer_name', 'customer_name') THEN
            v_filter_where := v_filter_where || format(' AND o.customer_name ILIKE %L', '%' || (v_filter->>'value') || '%');
        ELSIF v_filter->>'field' IN ('order_no', 'order_no') THEN
            v_filter_where := v_filter_where || format(' AND o.order_no ILIKE %L', '%' || (v_filter->>'value') || '%');
        ELSIF v_filter->>'field' IN ('is_ignored', 'is_ignored') THEN
            v_filter_where := v_filter_where || format(' AND o.is_ignored = %L', (v_filter->>'value')::BOOLEAN);
        ELSIF v_filter->>'field' IN ('date_from', 'date_from') THEN
            v_filter_where := v_filter_where || format(' AND o.order_date >= %L::timestamp', v_filter->>'value');
        ELSIF v_filter->>'field' IN ('date_to', 'date_to') THEN
            v_filter_where := v_filter_where || format(' AND o.order_date <= %L::timestamp', v_filter->>'value');
        END IF;
    END LOOP;

    -- Get total count
    IF NOT is_admin_or_supervisor() THEN
        EXECUTE format('SELECT COUNT(*) FROM orders o WHERE %s%s', v_base_where, v_filter_where)
        USING v_accessible_customers INTO v_total;
    ELSE
        EXECUTE format('SELECT COUNT(*) FROM orders o WHERE %s%s', v_base_where, v_filter_where)
        INTO v_total;
    END IF;

    -- Get aggregations
    IF NOT is_admin_or_supervisor() THEN
        EXECUTE format('
            SELECT jsonb_build_object(
                ''pending_count'', COUNT(*) FILTER (WHERE o.status = ''pending'' AND NOT o.is_ignored),
                ''partially_fulfilled_count'', COUNT(*) FILTER (WHERE o.status = ''partially_fulfilled'' AND NOT o.is_ignored),
                ''fulfilled_count'', COUNT(*) FILTER (WHERE o.status = ''fulfilled''),
                ''cancelled_count'', COUNT(*) FILTER (WHERE o.status = ''cancelled''),
                ''ignored_count'', COUNT(*) FILTER (WHERE o.is_ignored),
                ''overdue_count'', COUNT(*) FILTER (WHERE o.requested_dispatch_date < now() AND o.status IN (''pending'', ''partially_fulfilled'') AND NOT o.is_ignored)
            ) FROM orders o WHERE %s', v_base_where)
        USING v_accessible_customers INTO v_aggregations;
    ELSE
        EXECUTE '
            SELECT jsonb_build_object(
                ''pending_count'', COUNT(*) FILTER (WHERE o.status = ''pending'' AND NOT o.is_ignored),
                ''partially_fulfilled_count'', COUNT(*) FILTER (WHERE o.status = ''partially_fulfilled'' AND NOT o.is_ignored),
                ''fulfilled_count'', COUNT(*) FILTER (WHERE o.status = ''fulfilled''),
                ''cancelled_count'', COUNT(*) FILTER (WHERE o.status = ''cancelled''),
                ''ignored_count'', COUNT(*) FILTER (WHERE o.is_ignored),
                ''overdue_count'', COUNT(*) FILTER (WHERE o.requested_dispatch_date < now() AND o.status IN (''pending'', ''partially_fulfilled'') AND NOT o.is_ignored)
            ) FROM orders o'
        INTO v_aggregations;
    END IF;

    -- Get orders
    IF NOT is_admin_or_supervisor() THEN
        EXECUTE format('
            SELECT jsonb_agg(sub.order_data)
            FROM (
                SELECT jsonb_build_object(
                    ''id'', o.id, ''order_no'', o.order_no, ''order_date'', o.order_date,
                    ''requested_dispatch_date'', o.requested_dispatch_date, ''status'', o.status,
                    ''priority'', o.priority, ''customer_id'', o.customer_id, ''customer_name'', o.customer_name,
                    ''customer_email'', o.customer_email, ''customer_phone'', o.customer_phone, ''note'', o.note,
                    ''total_requested_qty'', o.total_requested_qty, ''total_fulfilled_qty'', o.total_fulfilled_qty,
                    ''item_count'', o.item_count, ''dispatch_id'', o.dispatch_id, ''dispatch_no'', o.dispatch_no,
                    ''dispatch_created_at'', o.dispatch_created_at, ''is_ignored'', o.is_ignored,
                    ''ignored_at'', o.ignored_at, ''ignored_by'', o.ignored_by, ''ignored_reason'', o.ignored_reason,
                    ''cancelled_at'', o.cancelled_at, ''cancelled_by'', o.cancelled_by,
                    ''cancellation_reason'', o.cancellation_reason, ''created_at'', o.created_at,
                    ''updated_at'', o.updated_at, ''created_by'', o.created_by, ''updated_by'', o.updated_by,
                    ''is_overdue'', (o.requested_dispatch_date < now() AND o.status IN (''pending'', ''partially_fulfilled''))
                ) as order_data
                FROM orders o WHERE %s%s ORDER BY o.%I %s, o.order_date ASC LIMIT $1 OFFSET $2
            ) sub', v_base_where, v_filter_where, v_sort_column, p_sort_direction)
        USING p_limit, p_offset, v_accessible_customers INTO v_orders_result;
    ELSE
        EXECUTE format('
            SELECT jsonb_agg(sub.order_data)
            FROM (
                SELECT jsonb_build_object(
                    ''id'', o.id, ''order_no'', o.order_no, ''order_date'', o.order_date,
                    ''requested_dispatch_date'', o.requested_dispatch_date, ''status'', o.status,
                    ''priority'', o.priority, ''customer_id'', o.customer_id, ''customer_name'', o.customer_name,
                    ''customer_email'', o.customer_email, ''customer_phone'', o.customer_phone, ''note'', o.note,
                    ''total_requested_qty'', o.total_requested_qty, ''total_fulfilled_qty'', o.total_fulfilled_qty,
                    ''item_count'', o.item_count, ''dispatch_id'', o.dispatch_id, ''dispatch_no'', o.dispatch_no,
                    ''dispatch_created_at'', o.dispatch_created_at, ''is_ignored'', o.is_ignored,
                    ''ignored_at'', o.ignored_at, ''ignored_by'', o.ignored_by, ''ignored_reason'', o.ignored_reason,
                    ''cancelled_at'', o.cancelled_at, ''cancelled_by'', o.cancelled_by,
                    ''cancellation_reason'', o.cancellation_reason, ''created_at'', o.created_at,
                    ''updated_at'', o.updated_at, ''created_by'', o.created_by, ''updated_by'', o.updated_by,
                    ''is_overdue'', (o.requested_dispatch_date < now() AND o.status IN (''pending'', ''partially_fulfilled''))
                ) as order_data
                FROM orders o WHERE %s%s ORDER BY o.%I %s, o.order_date ASC LIMIT $1 OFFSET $2
            ) sub', v_base_where, v_filter_where, v_sort_column, p_sort_direction)
        USING p_limit, p_offset INTO v_orders_result;
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'orders', COALESCE(v_orders_result, '[]'::jsonb),
            'aggregations', COALESCE(v_aggregations, '{}'::jsonb)
        ),
        'pagination', jsonb_build_object(
            'total_count', COALESCE(v_total, 0),
            'limit', p_limit,
            'offset', p_offset,
            'has_more', COALESCE(v_total, 0) > (p_offset + p_limit)
        )
    );
END;
$_$;


CREATE FUNCTION public.get_order_stats(p_customer_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_stats RECORD;
BEGIN
    SELECT
        COUNT(*)::integer as total_orders,
        COUNT(*) FILTER (WHERE status = 'pending')::integer as pending_orders,
        COUNT(*) FILTER (WHERE status = 'fulfilled')::integer as fulfilled_orders,
        COUNT(*) FILTER (WHERE status = 'partially_fulfilled')::integer as partially_fulfilled_orders,
        COUNT(*) FILTER (WHERE status = 'cancelled')::integer as cancelled_orders,
        COUNT(*) FILTER (WHERE is_ignored = true)::integer as ignored_orders
    INTO v_stats
    FROM orders
    WHERE deleted_at IS NULL
      AND (p_customer_id IS NULL OR customer_id = p_customer_id);

    RETURN utils.success_response(
        jsonb_build_object(
            'total_orders', v_stats.total_orders,
            'pending_orders', v_stats.pending_orders,
            'fulfilled_orders', v_stats.fulfilled_orders,
            'partially_fulfilled_orders', v_stats.partially_fulfilled_orders,
            'cancelled_orders', v_stats.cancelled_orders,
            'ignored_orders', v_stats.ignored_orders
        )
    );
EXCEPTION
    WHEN OTHERS THEN
        RETURN utils.database_error_response('Failed to get order stats', SQLERRM, SQLSTATE);
END;
$$;


CREATE FUNCTION public.get_order_with_items(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_profile_id UUID;
    v_order_customer_id UUID;
    v_accessible_customers UUID[];
    v_total_requested_qty INTEGER;
    v_total_fulfilled_qty INTEGER;
    v_item_count INTEGER;
    v_dispatch_info RECORD;
    v_order_data jsonb;
    v_items jsonb;
BEGIN
    -- Get user profile ID
    SELECT id INTO v_user_profile_id
    FROM user_profiles
    WHERE auth_user_id = auth.uid();

    IF v_user_profile_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', null,
            'message', 'User not authenticated',
            'error', jsonb_build_object('code', 'NOT_AUTHENTICATED')
        );
    END IF;

    -- Get order customer ID
    SELECT customer_id INTO v_order_customer_id
    FROM orders
    WHERE id = p_order_id;

    IF v_order_customer_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', null,
            'message', 'Order not found',
            'error', jsonb_build_object('code', 'ORDER_NOT_FOUND')
        );
    END IF;

    -- Check access permissions
    IF NOT is_admin_or_supervisor() THEN
        v_accessible_customers := user_accessible_customers();
        IF v_order_customer_id != ALL(v_accessible_customers) THEN
            RETURN jsonb_build_object(
                'success', false,
                'data', null,
                'message', 'Access denied to this order',
                'error', jsonb_build_object('code', 'PERMISSION_DENIED')
            );
        END IF;
    END IF;

    -- Calculate aggregated values from order_items
    SELECT
        COALESCE(SUM(oi.requested_quantity), 0),
        COALESCE(SUM(oi.fulfilled_quantity), 0),
        COUNT(*)
    INTO v_total_requested_qty, v_total_fulfilled_qty, v_item_count
    FROM order_items oi
    WHERE oi.order_id = p_order_id;

    -- Get dispatch information if exists
    SELECT d.id, d.disp_no, d.created_at
    INTO v_dispatch_info
    FROM dispatch d
    WHERE d.source_order_id = p_order_id
    LIMIT 1;

    -- Get order data with calculated values and user names
    SELECT jsonb_build_object(
        'id', o.id,
        'order_no', o.order_no,
        'order_date', o.order_date,
        'requested_dispatch_date', o.requested_dispatch_date,
        'status', o.status,
        'priority', o.priority,
        'customer_id', o.customer_id,
        'customer_name', o.customer_name,
        'customer_email', o.customer_email,
        'customer_phone', o.customer_phone,
        'note', o.note,
        'total_requested_qty', v_total_requested_qty,
        'total_fulfilled_qty', v_total_fulfilled_qty,
        'item_count', v_item_count,
        'dispatch_id', v_dispatch_info.id,
        'dispatch_no', v_dispatch_info.disp_no,
        'dispatch_created_at', v_dispatch_info.created_at,
        'is_ignored', o.is_ignored,
        'ignored_at', o.ignored_at,
        'ignored_by', o.ignored_by,
        'ignored_reason', o.ignored_reason,
        'cancelled_at', o.cancelled_at,
        'cancelled_by', o.cancelled_by,
        'cancellation_reason', o.cancellation_reason,
        'created_at', o.created_at,
        'updated_at', o.updated_at,
        'created_by', o.created_by,
        'updated_by', o.updated_by,
        'updated_by_name', up.name,
        'updated_by_display_name', up.display_name
    ) INTO v_order_data
    FROM orders o
    LEFT JOIN user_profiles up ON up.id = o.updated_by
    WHERE o.id = p_order_id;

    -- Get order items with grn_items_qty added
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'id', oi.id,
            'order_id', oi.order_id,
            'order_no', oi.order_no,
            'requested_quantity', oi.requested_quantity,
            'fulfilled_quantity', oi.fulfilled_quantity,
            'grn_items_id', oi.grn_items_id,
            'grn_items_item_id', oi.grn_items_item_id,
            'grn_items_item_name', oi.grn_items_item_name,
            'grn_items_package_mark', oi.grn_items_package_mark,
            'grn_items_packaging', oi.grn_items_packaging,
            'grn_items_rack', oi.grn_items_rack,
            'grn_items_weight', oi.grn_items_weight,
            'grn_items_image_url', oi.grn_items_image_url,
            'grn_items_qty', COALESCE(grt.qty, 0),
            'grns_id', oi.grns_id,
            'grns_gr_no', oi.grns_gr_no,
            'grns_date', oi.grns_date,
            'grns_customer_id', oi.grns_customer_id,
            'grns_customer_name', oi.grns_customer_name,
            'available_stock_at_order', oi.available_stock_at_order,
            'current_stock', COALESCE(grt.stock, oi.current_stock),
            'item_status', oi.item_status,
            'sort_order', oi.sort_order,
            'created_at', oi.created_at,
            'updated_at', oi.updated_at
        )
        ORDER BY oi.sort_order, oi.created_at
    ), '[]'::jsonb) INTO v_items
    FROM order_items oi
    LEFT JOIN goodsreceived_trl grt ON grt.id = oi.grn_items_id
    WHERE oi.order_id = p_order_id;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'order_data', v_order_data,
            'items', v_items
        ),
        'message', null
    );
END;
$$;


CREATE FUNCTION public.get_orders_list(p_customer_id uuid DEFAULT NULL::uuid, p_customer_name text DEFAULT NULL::text, p_has_items boolean DEFAULT NULL::boolean, p_user_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_id UUID;
    v_user_profile RECORD;
    v_accessible_customers UUID[];
    v_orders JSONB;
    v_total_count INTEGER;
    v_has_more BOOLEAN;
BEGIN
    -- Get user ID (use provided or current session)
    v_user_id := COALESCE(p_user_id, auth.uid());

    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Authentication required';
    END IF;

    -- Get user profile
    SELECT * INTO v_user_profile
    FROM user_profiles WHERE auth_user_id = v_user_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'User profile not found';
    END IF;

    -- Get accessible customers based on role
    IF is_admin_or_supervisor() THEN
        SELECT ARRAY(SELECT id FROM customers) INTO v_accessible_customers;
    ELSE
        SELECT user_accessible_customers() INTO v_accessible_customers;
    END IF;

    -- Get total count from MV (FAST - no GROUP BY!)
    SELECT COUNT(*) INTO v_total_count
    FROM mv_orders_list m
    WHERE m.customer_id = ANY(v_accessible_customers)
      AND (p_customer_id IS NULL OR m.customer_id = p_customer_id)
      AND (p_customer_name IS NULL OR m.customer_name_detail ILIKE '%' || p_customer_name || '%')
      AND (p_has_items IS NULL OR
           (p_has_items = true AND m.total_items > 0) OR
           (p_has_items = false AND m.total_items = 0));

    v_has_more := v_total_count > (p_offset + p_limit);

    -- Get paginated results from MV (FAST - pre-aggregated!)
    SELECT jsonb_agg(
        jsonb_build_object(
            'id', m.order_id,
            'customer_id', m.customer_id,
            'customer', jsonb_build_object(
                'id', m.customer_id,
                'name', m.customer_name_detail,
                'city', m.customer_city,
                'mobile', m.customer_mobile
            ),
            'status', m.status,
            'updated_by', m.updated_by,
            'updated_by_name', COALESCE(m.updated_by_display_name, m.updated_by_name),
            'item_count', m.total_items,
            'quantity_sum', m.total_quantity,
            'items', m.items_jsonb,
            'created_at', m.created_at,
            'updated_at', m.updated_at,
            -- Add dispatch info for sorting empty orders
            'dispatch_id', m.dispatch_id,
            'dispatch_no', m.dispatch_no,
            'dispatch_created_at', m.dispatch_created_at
        )
    ) INTO v_orders
    FROM (
        SELECT *
        FROM mv_orders_list m
        WHERE m.customer_id = ANY(v_accessible_customers)
          AND (p_customer_id IS NULL OR m.customer_id = p_customer_id)
          AND (p_customer_name IS NULL OR m.customer_name_detail ILIKE '%' || p_customer_name || '%')
          AND (p_has_items IS NULL OR
               (p_has_items = true AND m.total_items > 0) OR
               (p_has_items = false AND m.total_items = 0))
        ORDER BY
            -- Empty orders (total_items = 0) sorted by dispatch_created_at DESC
            -- Active orders (total_items > 0) sorted by updated_at DESC
            CASE WHEN m.total_items = 0 THEN m.dispatch_created_at ELSE m.updated_at END DESC NULLS LAST,
            m.created_at DESC
        LIMIT p_limit OFFSET p_offset
    ) m;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'orders', COALESCE(v_orders, '[]'::jsonb),
            'pagination', jsonb_build_object(
                'total_count', v_total_count,
                'has_more', v_has_more,
                'limit', p_limit,
                'offset', p_offset
            )
        )
    );
END;
$$;


CREATE FUNCTION public.get_otp_stats(p_phone_number character varying DEFAULT NULL::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    WITH phone_stats AS (
        SELECT
            ov.phone_number,
            COUNT(*) as total_sent,
            COUNT(*) FILTER (WHERE msg91_status = 'success') as successful_sent,
            COUNT(*) FILTER (WHERE verified = TRUE) as verified_count,
            COUNT(*) FILTER (WHERE delivery_status IN ('fallback', 'test', 'test_mode')) as fallback_count,
            MAX(created_at) as last_sent
        FROM public.otp_verifications ov
        WHERE (p_phone_number IS NULL OR ov.phone_number = p_phone_number)
        GROUP BY ov.phone_number
    )
    SELECT jsonb_build_object(
        'success', true,
        'data', COALESCE(jsonb_agg(jsonb_build_object(
            'phone_number', ps.phone_number,
            'total_sent', ps.total_sent,
            'successful_sent', ps.successful_sent,
            'verified_count', ps.verified_count,
            'fallback_count', ps.fallback_count,
            'hourly_usage', COALESCE(rl.hourly_count, 0),
            'daily_usage', COALESCE(rl.daily_count, 0),
            'last_sent', ps.last_sent
        ) ORDER BY ps.last_sent DESC), '[]'::jsonb),
        'message', null
    ) INTO v_result
    FROM phone_stats ps
    LEFT JOIN public.otp_rate_limits rl ON ps.phone_number = rl.phone_number;

    RETURN COALESCE(v_result, jsonb_build_object('success', true, 'data', '[]'::jsonb, 'message', null));
END;
$$;


CREATE FUNCTION public.get_print_jobs(p_limit integer DEFAULT 50, p_job_type text DEFAULT NULL::text, p_status text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_role VARCHAR(20);
    v_user_profile_id UUID;
    v_auth_uid UUID;
    v_result jsonb;
BEGIN
    v_auth_uid := auth.uid();

    -- Get current user's profile ID and role
    SELECT up.id, up.role
    INTO v_user_profile_id, v_user_role
    FROM public.user_profiles up
    WHERE up.auth_user_id = v_auth_uid;

    -- If user is not found, return error
    IF v_user_role IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', null,
            'message', 'User not authenticated',
            'error', jsonb_build_object('code', 'NOT_AUTHENTICATED')
        );
    END IF;

    -- Return jobs based on role and filters
    SELECT jsonb_build_object(
        'success', true,
        'data', COALESCE(jsonb_agg(jsonb_build_object(
            'id', pj.id,
            'cups_job_id', pj.cups_job_id,
            'job_type', pj.job_type,
            'document_range_start', pj.document_range_start,
            'document_range_end', pj.document_range_end,
            'document_count', pj.document_count,
            'user_id', pj.user_id,
            'user_name', pj.user_name,
            'status', pj.status,
            'error_message', pj.error_message,
            'content_size', pj.content_size,
            'printer_name', pj.printer_name,
            'submitted_at', pj.submitted_at,
            'completed_at', pj.completed_at,
            'created_at', pj.created_at,
            'updated_at', pj.updated_at
        ) ORDER BY pj.submitted_at DESC), '[]'::jsonb),
        'message', null
    ) INTO v_result
    FROM public.print_jobs pj
    WHERE
        (v_user_role IN ('admin', 'supervisor', 'staff') OR pj.user_id = v_auth_uid)
        AND (p_job_type IS NULL OR pj.job_type = p_job_type)
        AND (p_status IS NULL OR pj.status = p_status)
    LIMIT p_limit;

    RETURN v_result;
END;
$$;


CREATE FUNCTION public.get_priority_contact_for_customer(p_customer_id uuid) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    auth_phone TEXT;
    customer_mobile TEXT;
    customer_telephone1 TEXT;
BEGIN
    -- Get customer's own contact info
    SELECT mobile, telephone1 INTO customer_mobile, customer_telephone1
    FROM customers
    WHERE id = p_customer_id;

    -- Try to get auth phone from creator
    SELECT au.phone INTO auth_phone
    FROM customers c
    JOIN user_profiles up ON c.created_by = up.id
    JOIN auth.users au ON up.auth_user_id = au.id
    WHERE c.id = p_customer_id
    AND au.phone IS NOT NULL;

    -- If no creator auth phone, try assigned user
    IF auth_phone IS NULL THEN
        SELECT au.phone INTO auth_phone
        FROM users_customers_new ucn
        JOIN user_profiles up ON ucn.user_profile_id = up.id
        JOIN auth.users au ON up.auth_user_id = au.id
        WHERE ucn.customer_id = p_customer_id
        AND ucn.active = true
        AND au.phone IS NOT NULL
        ORDER BY ucn.assigned_at DESC
        LIMIT 1;
    END IF;

    -- Return priority contact
    RETURN COALESCE(auth_phone, customer_mobile, customer_telephone1);
END;
$$;


CREATE FUNCTION public.get_receipt_for_edit(p_line_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_line               public.bank_statement_lines;
    v_voucher_number     text;
    v_customer_name      text;
    v_alloc              jsonb;
    v_inv_id             uuid;
    v_inv_data           jsonb;
    v_alloc_result       jsonb := '[]'::jsonb;
BEGIN
    SELECT * INTO v_line FROM public.bank_statement_lines WHERE id = p_line_id;
    IF v_line.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Receipt not found');
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM public.bank_statements bs
        WHERE bs.id = v_line.statement_id AND bs.account_number = 'MANUAL'
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Not a manual receipt');
    END IF;

    SELECT voucher_number INTO v_voucher_number
    FROM public.tally_receipt_vouchers WHERE bank_line_id = p_line_id;

    SELECT name INTO v_customer_name
    FROM public.customers WHERE id = v_line.matched_customer_id;

    FOR v_alloc IN SELECT * FROM jsonb_array_elements(COALESCE(v_line.matched_allocations, '[]'::jsonb))
    LOOP
        v_inv_id := (v_alloc->>'invoice_id')::uuid;
        SELECT jsonb_build_object(
            'invoice_id',        i.id,
            'inv_no',            i.inv_no,
            'inv_fin_year',      i.inv_fin_year,
            'bill_ref',          'GCS/' || i.inv_fin_year || '/' || i.inv_no,
            'inv_date',          i.inv_date,
            'invoice_total',     i.total,
            'outstanding_today', i.total - COALESCE(p_sum.paid, 0),
            'allocated_amount',  (v_alloc->>'amount')::numeric
        )
        INTO v_inv_data
        FROM public.invoice i
        LEFT JOIN (
            SELECT invoice_id, SUM(amount) AS paid
            FROM public.payments WHERE invoice_id IS NOT NULL GROUP BY invoice_id
        ) p_sum ON p_sum.invoice_id = i.id
        WHERE i.id = v_inv_id;

        IF v_inv_data IS NOT NULL THEN
            v_alloc_result := v_alloc_result || jsonb_build_array(v_inv_data);
        END IF;
    END LOOP;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'line_id',         v_line.id,
            'tran_date',       v_line.tran_date,
            'amount',          v_line.credit,
            'tds_amount',      v_line.tds_amount,
            'particulars',     v_line.particulars,
            'customer_id',     v_line.matched_customer_id,
            'customer_name',   v_customer_name,
            'status',          v_line.status,
            'voucher_number',  v_voucher_number,
            'receipt_method',  v_line.receipt_method,
            'allocations',     v_alloc_result
        )
    );
END;
$$;


CREATE FUNCTION public.get_receipt_for_tally_sync(p_line_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result       JSONB;
    v_allocations  JSONB;
    v_ledger_name  TEXT;
    v_ledger_exists BOOLEAN;
    v_config       public.bank_reco_company_config;
    v_voucher      public.tally_receipt_vouchers;
    v_line         public.bank_statement_lines;
BEGIN
    -- Get line
    SELECT * INTO v_line
    FROM public.bank_statement_lines
    WHERE id = p_line_id;

    IF v_line.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Line not found');
    END IF;

    -- Get voucher record
    SELECT * INTO v_voucher
    FROM public.tally_receipt_vouchers
    WHERE bank_line_id = p_line_id;

    IF v_voucher.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Receipt voucher not found');
    END IF;

    -- Get company config
    SELECT * INTO v_config
    FROM public.bank_reco_company_config
    WHERE tally_company = v_voucher.tally_company;

    -- Get Tally ledger name for customer
    SELECT tlm.tally_ledger_name INTO v_ledger_name
    FROM public.tally_ledger_map tlm
    WHERE tlm.customer_id = v_line.matched_customer_id
    LIMIT 1;

    v_ledger_exists := v_ledger_name IS NOT NULL;

    -- Fallback to customer name if no ledger mapping
    IF v_ledger_name IS NULL THEN
        SELECT COALESCE(c.name, c.contact_person)
        INTO v_ledger_name
        FROM public.customers c
        WHERE c.id = v_line.matched_customer_id;
    END IF;

    -- Enrich allocations with bill_ref from invoice table
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'invoice_id', a->>'invoice_id',
            'bill_ref', 'GCS/' || inv.inv_fin_year || '/' || inv.inv_no,
            'amount', (a->>'amount')::NUMERIC(14,2)
        )
    ), '[]'::JSONB) INTO v_allocations
    FROM jsonb_array_elements(COALESCE(v_line.matched_allocations, '[]'::JSONB)) a
    LEFT JOIN public.invoice inv ON inv.id = (a->>'invoice_id')::UUID;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'line_id', p_line_id,
            'voucher_number', v_voucher.voucher_number,
            'voucher_date', v_voucher.voucher_date,
            'customer_id', v_line.matched_customer_id,
            'tally_ledger_name', v_ledger_name,
            'ledger_exists', v_ledger_exists,
            'bank_account_ledger', v_config.bank_account_ledger,
            'amount_received', v_voucher.amount_received,
            'tds_amount', v_voucher.tds_amount,
            'tds_ledger', CASE WHEN v_voucher.tds_amount > 0 THEN v_config.tds_194c_ledger ELSE NULL END,
            'narration', v_line.particulars,
            'allocations', v_allocations
        )
    );
END;
$$;


CREATE FUNCTION public.get_recent_auto_invoice_errors(p_limit integer DEFAULT 50, p_only_unresolved boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result jsonb;
    v_total_count integer;
BEGIN
    -- Get total count
    SELECT COUNT(*) INTO v_total_count
    FROM auto_invoice_errors aie
    WHERE (NOT p_only_unresolved OR aie.resolved_at IS NULL);

    -- Build response
    SELECT jsonb_build_object(
        'success', true,
        'data', COALESCE(jsonb_agg(jsonb_build_object(
            'id', aie.id,
            'customer_id', aie.customer_id,
            'customer_name', aie.customer_name,
            'gr_id', aie.gr_id,
            'gr_no', aie.gr_no,
            'gr_date', aie.gr_date,
            'error_code', aie.error_code,
            'error_message', aie.error_message,
            'error_details', aie.error_details,
            'retry_count', aie.retry_count,
            'created_at', aie.created_at,
            'resolved_at', aie.resolved_at,
            'resolved_invoice_id', aie.resolved_invoice_id
        ) ORDER BY aie.created_at DESC), '[]'::jsonb),
        'pagination', jsonb_build_object(
            'total_count', v_total_count,
            'limit', p_limit,
            'offset', 0,
            'has_more', v_total_count > p_limit
        ),
        'message', null
    ) INTO v_result
    FROM auto_invoice_errors aie
    WHERE (NOT p_only_unresolved OR aie.resolved_at IS NULL)
    LIMIT p_limit;

    RETURN v_result;
END;
$$;


CREATE FUNCTION public.get_recent_dispatched_orders(p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_role TEXT;
    v_result jsonb;
    v_total_count INTEGER;
BEGIN
    -- Access control: Only admin/supervisor/staff
    v_user_role := COALESCE(
        (current_setting('request.jwt.claims', true)::jsonb ->> 'user_role'),
        (SELECT role::text FROM user_profiles WHERE auth_user_id = auth.uid())
    );

    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Access denied: requires admin/supervisor/staff role'
        );
    END IF;

    -- Get total count
    SELECT COUNT(*) INTO v_total_count
    FROM dispatch d
    WHERE d.source_order_id IS NOT NULL
      AND d.deleted_at IS NULL;

    -- Get dispatched orders with items
    SELECT jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'dispatches', COALESCE(jsonb_agg(row_data), '[]'::jsonb),
            'total_count', v_total_count,
            'has_more', (p_offset + p_limit) < v_total_count
        )
    ) INTO v_result
    FROM (
        SELECT jsonb_build_object(
            'dispatch_id', d.id,
            'disp_no', d.disp_no,
            'disp_date', d.disp_date,
            'customer_id', d.customer_id,
            'customer_name', d.customer_name,
            'order_id', d.source_order_id,
            'order_no', d.source_order_no,
            'item_count', (SELECT COUNT(*) FROM dispatch_trl WHERE disp_id = d.id),
            'total_qty', (SELECT COALESCE(SUM(disp_qty), 0) FROM dispatch_trl WHERE disp_id = d.id),
            'registration', d.registration,
            'created_at', d.created_at,
            'created_by_name', up.name,
            'items', (
                SELECT COALESCE(jsonb_agg(jsonb_build_object(
                    'item_name', COALESCE(i.name, grt.item_name),
                    'disp_qty', dt.disp_qty,
                    'rack', grt.rack,
                    'package_mark', grt.package_mark,
                    'gr_no', gr.gr_no,
                    'weight', grt.weight
                )), '[]'::jsonb)
                FROM dispatch_trl dt
                JOIN goodsreceived_trl grt ON grt.id = dt.gr_trl_id
                JOIN goodsreceived gr ON gr.id = dt.gr_id
                LEFT JOIN items i ON i.id = grt.item_id
                WHERE dt.disp_id = d.id
            )
        ) as row_data
        FROM dispatch d
        LEFT JOIN user_profiles up ON up.id = d.created_by
        WHERE d.source_order_id IS NOT NULL
          AND d.deleted_at IS NULL
        ORDER BY d.created_at DESC
        LIMIT p_limit OFFSET p_offset
    ) sub;

    RETURN v_result;
END;
$$;


CREATE FUNCTION public.get_sensor_devices(p_active_only boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_devices JSONB;
BEGIN
    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'id', id,
                'device_name', device_name,
                'mac_address', mac_address,
                'location', location,
                'active', active,
                'last_reading_at', last_reading_at,
                'created_at', created_at
            ) ORDER BY device_name
        ),
        '[]'::jsonb
    )
    INTO v_devices
    FROM sensor_devices
    WHERE (NOT p_active_only OR active = true);

    RETURN jsonb_build_object(
        'success', true,
        'devices', v_devices
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', SQLERRM
    );
END;
$$;


CREATE FUNCTION public.get_sensor_health_dashboard() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_stats RECORD;
BEGIN
    SELECT
        COUNT(*) FILTER (WHERE is_active = true) as total_active_sensors,
        COUNT(*) FILTER (WHERE is_active = false) as total_inactive_sensors,
        COUNT(*) FILTER (WHERE health_status = 'healthy') as online_sensors,
        COUNT(*) FILTER (WHERE health_status = 'offline') as offline_sensors,
        COUNT(*) FILTER (WHERE health_status = 'stale') as stale_sensors,
        COUNT(*) FILTER (WHERE health_status IS NULL) as unknown_status_sensors,
        COUNT(*) FILTER (WHERE battery_status = 'low') as low_battery_count,
        COUNT(*) FILTER (WHERE battery_status = 'critical') as critical_battery_count,
        COUNT(*) FILTER (WHERE consecutive_failures > 0) as sensors_with_failures,
        MAX(last_reading_at) as most_recent_reading,
        MIN(last_reading_at) as oldest_sensor_reading
    INTO v_stats FROM sensors;
    RETURN utils.success_response(row_to_json(v_stats)::jsonb);
EXCEPTION WHEN OTHERS THEN RETURN utils.database_error_response('Failed to get sensor dashboard', SQLERRM, SQLSTATE);
END;
$$;


CREATE FUNCTION public.get_sensor_history(p_device_id uuid, p_days_back integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_device RECORD;
    v_from_date TIMESTAMPTZ;
    v_to_date TIMESTAMPTZ;
    v_interval TEXT;
    v_interval_seconds INTEGER;
    v_readings JSONB;
    v_summary JSONB;
    v_raw_count INTEGER;
BEGIN
    -- Validate p_days_back
    IF p_days_back NOT IN (7, 14, 30, 90, 365) THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Invalid period. Must be one of: 7, 14, 30, 90, 365 days',
            'error_code', 'INVALID_PERIOD'
        );
    END IF;

    -- Get device info
    SELECT id, device_name, location, active
    INTO v_device
    FROM sensor_devices
    WHERE id = p_device_id;

    IF v_device.id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Device not found',
            'error_code', 'DEVICE_NOT_FOUND'
        );
    END IF;

    -- Calculate date range
    v_to_date := NOW();
    v_from_date := v_to_date - (p_days_back || ' days')::INTERVAL;

    -- Determine aggregation interval
    v_interval := CASE p_days_back
        WHEN 7 THEN '1 hour'
        WHEN 14 THEN '2 hours'
        WHEN 30 THEN '4 hours'
        WHEN 90 THEN '1 day'
        WHEN 365 THEN '1 week'
    END;

    -- Interval in seconds for time bucketing
    v_interval_seconds := CASE p_days_back
        WHEN 7 THEN 3600          -- 1 hour
        WHEN 14 THEN 7200         -- 2 hours
        WHEN 30 THEN 14400        -- 4 hours
        WHEN 90 THEN 86400        -- 1 day
        WHEN 365 THEN 604800      -- 1 week
    END;

    -- Get aggregated readings using time bucketing
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'timestamp', bucket,
            'temperature', ROUND(avg_temp::NUMERIC, 2),
            'humidity', ROUND(avg_hum::NUMERIC, 2)
        ) ORDER BY bucket ASC
    ), '[]'::jsonb)
    INTO v_readings
    FROM (
        SELECT
            to_timestamp(
                floor(extract(epoch FROM recorded_at) / v_interval_seconds) * v_interval_seconds
            ) AS bucket,
            AVG(temperature) AS avg_temp,
            AVG(humidity) AS avg_hum
        FROM sensor_readings
        WHERE device_id = p_device_id
          AND recorded_at >= v_from_date
          AND recorded_at <= v_to_date
        GROUP BY bucket
        ORDER BY bucket ASC
    ) AS bucketed;

    -- Get summary statistics and raw count
    SELECT
        jsonb_build_object(
            'avg_temperature', ROUND(AVG(temperature)::NUMERIC, 2),
            'min_temperature', ROUND(MIN(temperature)::NUMERIC, 2),
            'max_temperature', ROUND(MAX(temperature)::NUMERIC, 2),
            'avg_humidity', ROUND(AVG(humidity)::NUMERIC, 2),
            'min_humidity', ROUND(MIN(humidity)::NUMERIC, 2),
            'max_humidity', ROUND(MAX(humidity)::NUMERIC, 2),
            'total_readings', jsonb_array_length(v_readings)
        ),
        COUNT(*)::INTEGER
    INTO v_summary, v_raw_count
    FROM sensor_readings
    WHERE device_id = p_device_id
      AND recorded_at >= v_from_date
      AND recorded_at <= v_to_date;

    -- Handle no data case
    IF v_raw_count = 0 THEN
        v_summary := jsonb_build_object(
            'avg_temperature', null,
            'min_temperature', null,
            'max_temperature', null,
            'avg_humidity', null,
            'min_humidity', null,
            'max_humidity', null,
            'total_readings', 0
        );
    END IF;

    -- Return response
    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'device_id', p_device_id,
            'device_name', v_device.device_name,
            'location', v_device.location,
            'period_days', p_days_back,
            'aggregation_interval', v_interval,
            'readings', v_readings,
            'summary', v_summary
        ),
        'metadata', jsonb_build_object(
            'from_date', v_from_date::DATE,
            'to_date', v_to_date::DATE,
            'raw_reading_count', v_raw_count
        )
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Failed to retrieve sensor history: ' || SQLERRM,
            'error_code', SQLSTATE
        );
END;
$$;


CREATE FUNCTION public.get_sensor_latest() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_latest JSONB;
BEGIN
    -- Get latest reading for each device
    WITH latest_readings AS (
        SELECT DISTINCT ON (sr.device_id)
            sr.device_id,
            sd.device_name,
            sd.mac_address,
            sd.location,
            sd.active,
            sr.temperature,
            sr.humidity,
            sr.recorded_at
        FROM sensor_readings sr
        JOIN sensor_devices sd ON sd.id = sr.device_id
        WHERE sd.active = true
        ORDER BY sr.device_id, sr.recorded_at DESC
    )
    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'device_id', device_id,
                'device_name', device_name,
                'mac_address', mac_address,
                'location', location,
                'temperature', temperature,
                'humidity', humidity,
                'recorded_at', recorded_at
            ) ORDER BY device_name
        ),
        '[]'::jsonb
    )
    INTO v_latest
    FROM latest_readings;

    RETURN jsonb_build_object(
        'success', true,
        'devices', v_latest
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', SQLERRM
    );
END;
$$;


CREATE FUNCTION public.get_sensor_polling_data(p_since_timestamp timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result JSONB;
    v_devices JSONB;
    v_new_readings JSONB;
    v_dashboard JSONB;
    v_poll_timestamp TIMESTAMPTZ;
BEGIN
    v_poll_timestamp := NOW();

    -- Get all active devices with COMBINED latest readings
    SELECT COALESCE(json_agg(device_data), '[]'::json)::jsonb INTO v_devices
    FROM (
        SELECT
            d.id,
            d.device_name,
            d.mac_address,
            d.location,
            d.active,
            d.health_status,
            d.battery_status,
            d.connectivity_status,
            d.is_stale,
            d.last_reading_at,
            d.staleness_threshold_minutes,
            d.consecutive_failures,
            latest.temperature AS latest_temperature,
            latest.humidity AS latest_humidity,
            latest.reading_timestamp AS latest_reading_timestamp,
            latest.earliest_reading_at
        FROM sensor_devices d
        LEFT JOIN LATERAL (
            SELECT
                -- Get most recent REAL temperature (exclude 0 when it's paired with humidity > 0)
                (SELECT r2.temperature FROM sensor_readings r2
                 WHERE r2.device_id = d.id
                 AND r2.temperature IS NOT NULL
                 AND NOT (r2.temperature = 0 AND r2.humidity > 0)  -- Exclude humidity-only readings
                 ORDER BY r2.recorded_at DESC LIMIT 1) AS temperature,
                -- Get most recent humidity
                (SELECT r3.humidity FROM sensor_readings r3
                 WHERE r3.device_id = d.id
                 AND r3.humidity IS NOT NULL
                 AND r3.humidity > 0
                 ORDER BY r3.recorded_at DESC LIMIT 1) AS humidity,
                -- Get most recent timestamp
                (SELECT MAX(r4.recorded_at) FROM sensor_readings r4
                 WHERE r4.device_id = d.id) AS reading_timestamp,
                -- Get earliest reading timestamp (for history period calculation)
                (SELECT MIN(r5.recorded_at) FROM sensor_readings r5
                 WHERE r5.device_id = d.id) AS earliest_reading_at
        ) latest ON true
        WHERE d.active = true
        ORDER BY d.device_name
    ) device_data;

    -- Get new readings since last poll
    IF p_since_timestamp IS NOT NULL THEN
        SELECT COALESCE(json_agg(reading_data), '[]'::json)::jsonb INTO v_new_readings
        FROM (
            SELECT
                r.device_id,
                d.device_name,
                d.mac_address,
                -- Return temperature only if it's a real reading
                CASE WHEN r.temperature = 0 AND r.humidity > 0 THEN NULL ELSE r.temperature END as temperature,
                r.humidity,
                r.recorded_at
            FROM sensor_readings r
            INNER JOIN sensor_devices d ON d.id = r.device_id
            WHERE r.recorded_at > p_since_timestamp
              AND d.active = true
            ORDER BY r.recorded_at DESC
        ) reading_data;
    ELSE
        v_new_readings := '[]'::jsonb;
    END IF;

    -- Get dashboard summary
    SELECT jsonb_build_object(
        'total_active_sensors', total_active_sensors,
        'online_sensors', online_sensors,
        'offline_sensors', offline_sensors,
        'stale_sensors', stale_sensors,
        'low_battery_count', low_battery_count,
        'critical_battery_count', critical_battery_count,
        'sensors_with_failures', sensors_with_failures,
        'most_recent_sync', most_recent_sync
    ) INTO v_dashboard
    FROM sensor_health_dashboard;

    v_result := jsonb_build_object(
        'success', true,
        'poll_timestamp', v_poll_timestamp,
        'devices', v_devices,
        'new_readings', v_new_readings,
        'dashboard', v_dashboard
    );

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', SQLERRM,
            'poll_timestamp', NOW()
        );
END;
$$;


CREATE FUNCTION public.get_sensor_readings(p_device_id uuid DEFAULT NULL::uuid, p_start_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 1000, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_readings JSONB;
    v_total_count INTEGER;
BEGIN
    -- Get readings with filters
    WITH filtered_readings AS (
        SELECT
            sr.id,
            sr.device_id,
            sd.device_name,
            sd.location,
            sr.temperature,
            sr.humidity,
            sr.recorded_at
        FROM sensor_readings sr
        JOIN sensor_devices sd ON sd.id = sr.device_id
        WHERE
            (p_device_id IS NULL OR sr.device_id = p_device_id)
            AND (p_start_time IS NULL OR sr.recorded_at >= p_start_time)
            AND (p_end_time IS NULL OR sr.recorded_at <= p_end_time)
        ORDER BY sr.recorded_at DESC
    ),
    paginated_readings AS (
        SELECT *, COUNT(*) OVER() as total_count
        FROM filtered_readings
        LIMIT p_limit OFFSET p_offset
    )
    SELECT
        jsonb_agg(
            jsonb_build_object(
                'id', id,
                'device_id', device_id,
                'device_name', device_name,
                'location', location,
                'temperature', temperature,
                'humidity', humidity,
                'recorded_at', recorded_at
            )
        ),
        COALESCE(MAX(total_count), 0)
    INTO v_readings, v_total_count
    FROM paginated_readings;

    RETURN jsonb_build_object(
        'success', true,
        'readings', COALESCE(v_readings, '[]'::jsonb),
        'pagination', jsonb_build_object(
            'total_count', v_total_count,
            'limit', p_limit,
            'offset', p_offset,
            'has_more', (p_offset + p_limit) < v_total_count
        )
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', SQLERRM
    );
END;
$$;


CREATE FUNCTION public.get_sensor_statistics(p_device_id uuid, p_period character varying DEFAULT 'hour'::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_stats JSONB;
    v_start_time TIMESTAMP WITH TIME ZONE;
BEGIN
    -- Calculate start time based on period
    v_start_time := CASE p_period
        WHEN 'hour' THEN NOW() - INTERVAL '1 hour'
        WHEN 'day' THEN NOW() - INTERVAL '1 day'
        WHEN 'week' THEN NOW() - INTERVAL '7 days'
        WHEN 'month' THEN NOW() - INTERVAL '30 days'
        ELSE NOW() - INTERVAL '1 day'
    END;

    -- Calculate statistics
    SELECT jsonb_build_object(
        'device_id', p_device_id,
        'period', p_period,
        'start_time', v_start_time,
        'end_time', NOW(),
        'temperature', jsonb_build_object(
            'avg', ROUND(AVG(temperature)::numeric, 2),
            'min', MIN(temperature),
            'max', MAX(temperature),
            'current', (SELECT temperature FROM sensor_readings
                        WHERE device_id = p_device_id
                        ORDER BY recorded_at DESC LIMIT 1)
        ),
        'humidity', jsonb_build_object(
            'avg', ROUND(AVG(humidity)::numeric, 2),
            'min', MIN(humidity),
            'max', MAX(humidity),
            'current', (SELECT humidity FROM sensor_readings
                        WHERE device_id = p_device_id
                        ORDER BY recorded_at DESC LIMIT 1)
        ),
        'reading_count', COUNT(*)
    )
    INTO v_stats
    FROM sensor_readings
    WHERE device_id = p_device_id
      AND recorded_at >= v_start_time;

    RETURN jsonb_build_object(
        'success', true,
        'statistics', v_stats
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', SQLERRM
    );
END;
$$;


CREATE FUNCTION public.get_service_credentials(p_service_name character varying) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    SELECT credentials
    FROM public.secrets_vault
    WHERE service_name = p_service_name
    AND is_active = true
    LIMIT 1;
$$;


CREATE FUNCTION public.get_stock_aging_report(p_customer_uuid uuid DEFAULT NULL::uuid, p_aging_buckets integer[] DEFAULT ARRAY[120, 240, 364]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET jit TO 'off'
    AS $$
DECLARE
    v_user_id uuid;
    v_user_role text;
    v_user_customer_ids uuid[];
    v_bucket_1 integer;
    v_bucket_2 integer;
    v_bucket_3 integer;
    v_result jsonb;
    v_summary jsonb;
    v_by_bucket jsonb;
    v_items jsonb;
    v_by_customer jsonb;
BEGIN
    -- Get caller's role
    IF auth.uid() IS NOT NULL THEN
        SELECT id, role INTO v_user_id, v_user_role
        FROM user_profiles
        WHERE auth_user_id = auth.uid();
    END IF;

    -- Access control
    IF v_user_role IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Authentication required'
        );
    END IF;

    -- Non-admin/supervisor: get accessible customers
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
        FROM users_customers_new
        WHERE user_profile_id = v_user_id;

        -- If no customers assigned, return empty
        IF v_user_customer_ids IS NULL OR array_length(v_user_customer_ids, 1) IS NULL THEN
            RETURN jsonb_build_object(
                'success', true,
                'data', jsonb_build_object(
                    'summary', jsonb_build_object(
                        'total_items', 0,
                        'total_quantity', 0,
                        'oldest_stock_days', 0
                    ),
                    'by_bucket', '{}'::jsonb,
                    'items', '[]'::jsonb
                ),
                'metadata', jsonb_build_object('retrieved_at', NOW())
            );
        END IF;

        -- If specific customer requested, verify access
        IF p_customer_uuid IS NOT NULL AND NOT (p_customer_uuid = ANY(v_user_customer_ids)) THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'Access denied: You do not have permission to view this customer''s data'
            );
        END IF;
    END IF;

    -- Set aging bucket thresholds
    v_bucket_1 := COALESCE(p_aging_buckets[1], 120);
    v_bucket_2 := COALESCE(p_aging_buckets[2], 240);
    v_bucket_3 := COALESCE(p_aging_buckets[3], 364);

    -- Single customer view
    IF p_customer_uuid IS NOT NULL THEN
        WITH stock_items AS (
            SELECT
                grt.id as grn_item_id,
                gr.id as grn_id,
                gr.gr_no,
                gr.customer_id,
                gr.date as grn_date,
                grt.item_name,
                grt.packaging,
                grt.stock as current_stock,
                grt.qty as original_qty,
                grt.weight,
                grt.rack,
                grt.package_mark,
                (CURRENT_DATE - gr.date::date) as aging_days,
                CASE
                    WHEN (CURRENT_DATE - gr.date::date) <= v_bucket_1 THEN '0-' || v_bucket_1::text
                    WHEN (CURRENT_DATE - gr.date::date) <= v_bucket_2 THEN (v_bucket_1 + 1)::text || '-' || v_bucket_2::text
                    WHEN (CURRENT_DATE - gr.date::date) <= v_bucket_3 THEN (v_bucket_2 + 1)::text || '-' || v_bucket_3::text
                    ELSE v_bucket_3::text || '+'
                END as aging_bucket
            FROM goodsreceived_trl grt
            JOIN goodsreceived gr ON grt.gr_id = gr.id
            WHERE gr.customer_id = p_customer_uuid
                AND gr.deleted_at IS NULL
                AND grt.stock > 0
        ),
        dispatch_info AS (
            SELECT
                dt.gr_trl_id,
                SUM(dt.disp_qty) as total_dispatched,
                COUNT(DISTINCT d.id) as dispatch_count,
                MAX(d.disp_date) as last_dispatch_date
            FROM dispatch_trl dt
            JOIN dispatch d ON dt.disp_id = d.id
            WHERE d.deleted_at IS NULL
            GROUP BY dt.gr_trl_id
        ),
        items_with_dispatch AS (
            SELECT
                si.*,
                COALESCE(di.total_dispatched, 0) as total_dispatched,
                COALESCE(di.dispatch_count, 0) as dispatch_count,
                di.last_dispatch_date,
                CASE WHEN di.last_dispatch_date IS NOT NULL
                    THEN (CURRENT_DATE - di.last_dispatch_date::date)
                    ELSE NULL
                END as days_since_last_dispatch,
                CASE WHEN COALESCE(di.dispatch_count, 0) > 0
                    THEN ((di.last_dispatch_date::date - si.grn_date::date) / di.dispatch_count)
                    ELSE NULL
                END as avg_days_between_dispatches
            FROM stock_items si
            LEFT JOIN dispatch_info di ON si.grn_item_id = di.gr_trl_id
        )
        SELECT
            jsonb_build_object(
                'total_items', COUNT(*),
                'total_quantity', COALESCE(SUM(current_stock), 0),
                'total_weight_kg', COALESCE(SUM(weight), 0),
                'oldest_stock_days', COALESCE(MAX(aging_days), 0),
                'average_age_days', COALESCE(ROUND(AVG(aging_days)), 0),
                'items_over_365_days', COUNT(*) FILTER (WHERE aging_days > 365),
                'qty_over_365_days', COALESCE(SUM(current_stock) FILTER (WHERE aging_days > 365), 0),
                'avg_dispatch_velocity_days', COALESCE(ROUND(AVG(avg_days_between_dispatches)), NULL),
                'items_no_recent_dispatch', COUNT(*) FILTER (WHERE days_since_last_dispatch > 30 OR dispatch_count = 0)
            ),
            jsonb_build_object(
                '0-' || v_bucket_1::text, jsonb_build_object(
                    'item_count', COUNT(*) FILTER (WHERE aging_bucket = '0-' || v_bucket_1::text),
                    'total_quantity', COALESCE(SUM(current_stock) FILTER (WHERE aging_bucket = '0-' || v_bucket_1::text), 0),
                    'total_weight', COALESCE(SUM(weight) FILTER (WHERE aging_bucket = '0-' || v_bucket_1::text), 0),
                    'percentage', CASE WHEN COUNT(*) > 0
                        THEN ROUND(COUNT(*) FILTER (WHERE aging_bucket = '0-' || v_bucket_1::text) * 100.0 / COUNT(*), 1)
                        ELSE 0
                    END
                ),
                (v_bucket_1 + 1)::text || '-' || v_bucket_2::text, jsonb_build_object(
                    'item_count', COUNT(*) FILTER (WHERE aging_bucket = (v_bucket_1 + 1)::text || '-' || v_bucket_2::text),
                    'total_quantity', COALESCE(SUM(current_stock) FILTER (WHERE aging_bucket = (v_bucket_1 + 1)::text || '-' || v_bucket_2::text), 0),
                    'total_weight', COALESCE(SUM(weight) FILTER (WHERE aging_bucket = (v_bucket_1 + 1)::text || '-' || v_bucket_2::text), 0),
                    'percentage', CASE WHEN COUNT(*) > 0
                        THEN ROUND(COUNT(*) FILTER (WHERE aging_bucket = (v_bucket_1 + 1)::text || '-' || v_bucket_2::text) * 100.0 / COUNT(*), 1)
                        ELSE 0
                    END
                ),
                (v_bucket_2 + 1)::text || '-' || v_bucket_3::text, jsonb_build_object(
                    'item_count', COUNT(*) FILTER (WHERE aging_bucket = (v_bucket_2 + 1)::text || '-' || v_bucket_3::text),
                    'total_quantity', COALESCE(SUM(current_stock) FILTER (WHERE aging_bucket = (v_bucket_2 + 1)::text || '-' || v_bucket_3::text), 0),
                    'total_weight', COALESCE(SUM(weight) FILTER (WHERE aging_bucket = (v_bucket_2 + 1)::text || '-' || v_bucket_3::text), 0),
                    'percentage', CASE WHEN COUNT(*) > 0
                        THEN ROUND(COUNT(*) FILTER (WHERE aging_bucket = (v_bucket_2 + 1)::text || '-' || v_bucket_3::text) * 100.0 / COUNT(*), 1)
                        ELSE 0
                    END
                ),
                v_bucket_3::text || '+', jsonb_build_object(
                    'item_count', COUNT(*) FILTER (WHERE aging_bucket = v_bucket_3::text || '+'),
                    'total_quantity', COALESCE(SUM(current_stock) FILTER (WHERE aging_bucket = v_bucket_3::text || '+'), 0),
                    'total_weight', COALESCE(SUM(weight) FILTER (WHERE aging_bucket = v_bucket_3::text || '+'), 0),
                    'percentage', CASE WHEN COUNT(*) > 0
                        THEN ROUND(COUNT(*) FILTER (WHERE aging_bucket = v_bucket_3::text || '+') * 100.0 / COUNT(*), 1)
                        ELSE 0
                    END
                )
            ),
            COALESCE(jsonb_agg(
                jsonb_build_object(
                    'grn_id', grn_id,
                    'gr_no', gr_no,
                    'item_name', item_name,
                    'packaging', packaging,
                    'current_stock', current_stock,
                    'original_qty', original_qty,
                    'weight', weight,
                    'rack', rack,
                    'package_mark', package_mark,
                    'grn_date', grn_date,
                    'aging_days', aging_days,
                    'aging_bucket', aging_bucket,
                    'dispatch_info', jsonb_build_object(
                        'total_dispatched', total_dispatched,
                        'dispatch_count', dispatch_count,
                        'last_dispatch_date', last_dispatch_date,
                        'days_since_last_dispatch', days_since_last_dispatch,
                        'avg_days_between_dispatches', avg_days_between_dispatches
                    )
                ) ORDER BY aging_days DESC
            ), '[]'::jsonb)
        INTO v_summary, v_by_bucket, v_items
        FROM items_with_dispatch;

        v_result := jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'summary', v_summary,
                'by_bucket', v_by_bucket,
                'items', v_items
            ),
            'metadata', jsonb_build_object(
                'retrieved_at', NOW(),
                'customer_id', p_customer_uuid,
                'aging_buckets', p_aging_buckets
            )
        );

    -- All customers view (filtered by accessible customers for non-staff)
    ELSE
        WITH stock_items AS (
            SELECT
                grt.id as grn_item_id,
                gr.id as grn_id,
                gr.customer_id,
                c.name as customer_name,
                gr.date as grn_date,
                grt.stock as current_stock,
                grt.weight,
                (CURRENT_DATE - gr.date::date) as aging_days,
                CASE
                    WHEN (CURRENT_DATE - gr.date::date) <= v_bucket_1 THEN '0-' || v_bucket_1::text
                    WHEN (CURRENT_DATE - gr.date::date) <= v_bucket_2 THEN (v_bucket_1 + 1)::text || '-' || v_bucket_2::text
                    WHEN (CURRENT_DATE - gr.date::date) <= v_bucket_3 THEN (v_bucket_2 + 1)::text || '-' || v_bucket_3::text
                    ELSE v_bucket_3::text || '+'
                END as aging_bucket
            FROM goodsreceived_trl grt
            JOIN goodsreceived gr ON grt.gr_id = gr.id
            JOIN customers c ON gr.customer_id = c.id
            WHERE gr.deleted_at IS NULL
                AND grt.stock > 0
                AND (v_user_role IN ('admin', 'supervisor', 'staff') OR gr.customer_id = ANY(v_user_customer_ids))
        ),
        customer_aggregates AS (
            SELECT
                customer_id,
                customer_name,
                SUM(current_stock) as total_stock,
                ROUND(AVG(aging_days)) as average_age_days,
                MAX(aging_days) as oldest_stock_days,
                COUNT(*) FILTER (WHERE aging_days > 365) as items_over_365_days,
                SUM(current_stock) FILTER (WHERE aging_bucket = '0-' || v_bucket_1::text) as bucket_1_qty,
                SUM(current_stock) FILTER (WHERE aging_bucket = (v_bucket_1 + 1)::text || '-' || v_bucket_2::text) as bucket_2_qty,
                SUM(current_stock) FILTER (WHERE aging_bucket = (v_bucket_2 + 1)::text || '-' || v_bucket_3::text) as bucket_3_qty,
                SUM(current_stock) FILTER (WHERE aging_bucket = v_bucket_3::text || '+') as bucket_4_qty
            FROM stock_items
            GROUP BY customer_id, customer_name
        )
        SELECT
            jsonb_build_object(
                'total_customers', (SELECT COUNT(DISTINCT customer_id) FROM stock_items),
                'total_items', (SELECT COUNT(*) FROM stock_items),
                'total_quantity', COALESCE((SELECT SUM(current_stock) FROM stock_items), 0),
                'oldest_stock_days', COALESCE((SELECT MAX(aging_days) FROM stock_items), 0),
                'average_age_days', COALESCE((SELECT ROUND(AVG(aging_days)) FROM stock_items), 0),
                'items_over_365_days', (SELECT COUNT(*) FROM stock_items WHERE aging_days > 365),
                'qty_over_365_days', COALESCE((SELECT SUM(current_stock) FROM stock_items WHERE aging_days > 365), 0)
            ),
            jsonb_build_object(
                '0-' || v_bucket_1::text, jsonb_build_object(
                    'item_count', (SELECT COUNT(*) FROM stock_items WHERE aging_bucket = '0-' || v_bucket_1::text),
                    'total_quantity', COALESCE((SELECT SUM(current_stock) FROM stock_items WHERE aging_bucket = '0-' || v_bucket_1::text), 0),
                    'percentage', CASE WHEN (SELECT COUNT(*) FROM stock_items) > 0
                        THEN ROUND((SELECT COUNT(*) FROM stock_items WHERE aging_bucket = '0-' || v_bucket_1::text) * 100.0 / (SELECT COUNT(*) FROM stock_items), 1)
                        ELSE 0
                    END
                ),
                (v_bucket_1 + 1)::text || '-' || v_bucket_2::text, jsonb_build_object(
                    'item_count', (SELECT COUNT(*) FROM stock_items WHERE aging_bucket = (v_bucket_1 + 1)::text || '-' || v_bucket_2::text),
                    'total_quantity', COALESCE((SELECT SUM(current_stock) FROM stock_items WHERE aging_bucket = (v_bucket_1 + 1)::text || '-' || v_bucket_2::text), 0),
                    'percentage', CASE WHEN (SELECT COUNT(*) FROM stock_items) > 0
                        THEN ROUND((SELECT COUNT(*) FROM stock_items WHERE aging_bucket = (v_bucket_1 + 1)::text || '-' || v_bucket_2::text) * 100.0 / (SELECT COUNT(*) FROM stock_items), 1)
                        ELSE 0
                    END
                ),
                (v_bucket_2 + 1)::text || '-' || v_bucket_3::text, jsonb_build_object(
                    'item_count', (SELECT COUNT(*) FROM stock_items WHERE aging_bucket = (v_bucket_2 + 1)::text || '-' || v_bucket_3::text),
                    'total_quantity', COALESCE((SELECT SUM(current_stock) FROM stock_items WHERE aging_bucket = (v_bucket_2 + 1)::text || '-' || v_bucket_3::text), 0),
                    'percentage', CASE WHEN (SELECT COUNT(*) FROM stock_items) > 0
                        THEN ROUND((SELECT COUNT(*) FROM stock_items WHERE aging_bucket = (v_bucket_2 + 1)::text || '-' || v_bucket_3::text) * 100.0 / (SELECT COUNT(*) FROM stock_items), 1)
                        ELSE 0
                    END
                ),
                v_bucket_3::text || '+', jsonb_build_object(
                    'item_count', (SELECT COUNT(*) FROM stock_items WHERE aging_bucket = v_bucket_3::text || '+'),
                    'total_quantity', COALESCE((SELECT SUM(current_stock) FROM stock_items WHERE aging_bucket = v_bucket_3::text || '+'), 0),
                    'percentage', CASE WHEN (SELECT COUNT(*) FROM stock_items) > 0
                        THEN ROUND((SELECT COUNT(*) FROM stock_items WHERE aging_bucket = v_bucket_3::text || '+') * 100.0 / (SELECT COUNT(*) FROM stock_items), 1)
                        ELSE 0
                    END
                )
            ),
            COALESCE((
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'customer_id', customer_id,
                        'customer_name', customer_name,
                        'total_stock', total_stock,
                        'average_age_days', average_age_days,
                        'oldest_stock_days', oldest_stock_days,
                        'items_over_365_days', items_over_365_days,
                        'aging_distribution', jsonb_build_object(
                            '0-' || v_bucket_1::text, COALESCE(bucket_1_qty, 0),
                            (v_bucket_1 + 1)::text || '-' || v_bucket_2::text, COALESCE(bucket_2_qty, 0),
                            (v_bucket_2 + 1)::text || '-' || v_bucket_3::text, COALESCE(bucket_3_qty, 0),
                            v_bucket_3::text || '+', COALESCE(bucket_4_qty, 0)
                        )
                    ) ORDER BY average_age_days DESC
                )
                FROM customer_aggregates
            ), '[]'::jsonb)
        INTO v_summary, v_by_bucket, v_by_customer;

        v_result := jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'summary', v_summary,
                'by_bucket', v_by_bucket,
                'by_customer', v_by_customer
            ),
            'metadata', jsonb_build_object(
                'retrieved_at', NOW(),
                'aging_buckets', p_aging_buckets
            )
        );
    END IF;

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Failed to retrieve stock aging report: ' || SQLERRM,
            'error_code', SQLSTATE
        );
END;
$$;


CREATE FUNCTION public.get_supervisors(search_query text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_supervisors jsonb;
BEGIN
    SELECT COALESCE(jsonb_agg(sub.supervisor ORDER BY sub.name), '[]'::jsonb)
    INTO v_supervisors
    FROM (
        SELECT jsonb_build_object('id', id, 'name', name, 'phone', mobile) as supervisor, name
        FROM user_profiles
        WHERE role IN ('admin', 'supervisor', 'staff')
          AND (search_query = '' OR name ILIKE '%' || search_query || '%')
        ORDER BY name
    ) sub;
    RETURN utils.success_response(v_supervisors);
EXCEPTION WHEN OTHERS THEN RETURN utils.database_error_response('Failed to get supervisors', SQLERRM, SQLSTATE);
END;
$$;


CREATE FUNCTION public.get_tally_ledger_map(p_customer_id uuid DEFAULT NULL::uuid, p_tally_company character varying DEFAULT public.get_tally_company()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RETURN jsonb_build_object(
        'success', true,
        'data', COALESCE((
            SELECT jsonb_agg(to_jsonb(tlm))
            FROM public.tally_ledger_map tlm
            WHERE (p_customer_id IS NULL OR tlm.customer_id = p_customer_id)
              AND tlm.tally_company = p_tally_company
        ), '[]'::jsonb)
    );
END;
$$;


CREATE FUNCTION public.get_tally_sync_dashboard() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result          JSONB;
    v_by_entity       JSONB;
    v_dead_letters    JSONB;
    v_drift           JSONB;
    v_alerts          JSONB := '[]'::jsonb;
    v_mw_row          public.tally_middleware_status;
    v_last_log_at     TIMESTAMPTZ;
    v_dl_count        INT  := 0;
    v_drift_count     INT  := 0;
    v_stale_retry_cnt INT  := 0;
    v_mw_stale        BOOLEAN := false;
    v_fallback_active BOOLEAN := false;
    v_in_flight       INT := 0;
    v_last_confirmed  TIMESTAMPTZ;

    v_nv_invoice      INT := 0;
    v_nv_receipt      INT := 0;
    v_oldest_unv_at   TIMESTAMPTZ;
    v_last_drift_run  TIMESTAMPTZ;
    v_oldest_unv_hr   NUMERIC;
BEGIN
    -- Queue counts
    WITH latest AS (
        SELECT DISTINCT ON (entity_type, entity_id)
            entity_type, entity_id, status, updated_at, completed_at, created_at
        FROM public.tally_sync_queue
        ORDER BY entity_type, entity_id, updated_at DESC
    )
    SELECT jsonb_build_object(
        'pending_count',    COUNT(*) FILTER (WHERE status = 'pending'),
        'processing_count', COUNT(*) FILTER (WHERE status = 'processing'),
        'retry_count',      COUNT(*) FILTER (WHERE status = 'retry'),
        'confirmed_count',  COUNT(*) FILTER (WHERE status = 'confirmed'),
        'failed_count',     COUNT(*) FILTER (WHERE status = 'failed'),
        'dead_letter_count',COUNT(*) FILTER (WHERE status = 'dead_letter'),
        'total_count',      COUNT(*),
        'last_confirmed_at',MAX(completed_at) FILTER (WHERE status = 'confirmed'),
        'last_failed_at',   MAX(updated_at)   FILTER (WHERE status IN ('failed', 'dead_letter')),
        'oldest_pending',   MIN(created_at)   FILTER (WHERE status IN ('pending', 'retry'))
    ) INTO v_result
    FROM latest;

    v_dl_count       := COALESCE((v_result->>'dead_letter_count')::int, 0);
    v_in_flight      := COALESCE((v_result->>'pending_count')::int, 0)
                      + COALESCE((v_result->>'retry_count')::int, 0);
    v_last_confirmed := (v_result->>'last_confirmed_at')::timestamptz;

    -- Per-entity breakdown
    WITH latest AS (
        SELECT DISTINCT ON (entity_type, entity_id)
            entity_type, entity_id, status
        FROM public.tally_sync_queue
        ORDER BY entity_type, entity_id, updated_at DESC
    )
    SELECT jsonb_object_agg(entity_type, counts) INTO v_by_entity
    FROM (
        SELECT
            entity_type,
            jsonb_build_object(
                'pending',    COUNT(*) FILTER (WHERE status = 'pending'),
                'processing', COUNT(*) FILTER (WHERE status = 'processing'),
                'retry',      COUNT(*) FILTER (WHERE status = 'retry'),
                'confirmed',  COUNT(*) FILTER (WHERE status = 'confirmed'),
                'failed',     COUNT(*) FILTER (WHERE status = 'failed'),
                'dead_letter',COUNT(*) FILTER (WHERE status = 'dead_letter')
            ) AS counts
        FROM latest
        GROUP BY entity_type
    ) sub;

    -- Dead-letter breakdown
    WITH latest_dl AS (
        SELECT DISTINCT ON (entity_type, entity_id)
            entity_type, entity_id, error_message, error_details, updated_at
        FROM public.tally_sync_queue
        ORDER BY entity_type, entity_id, updated_at DESC
    ), dl_active AS (
        SELECT entity_type, entity_id, error_message, error_details, updated_at
        FROM public.tally_sync_queue q
        WHERE status = 'dead_letter'
          AND (entity_type, entity_id) IN (SELECT entity_type, entity_id FROM latest_dl)
    ), grouped AS (
        SELECT
            entity_type,
            COALESCE(NULLIF(error_message, ''), '(no error message)') AS error_message,
            COALESCE(error_details->>'error_class', 'unclassified') AS error_class,
            COUNT(DISTINCT entity_id) AS cnt,
            MIN(updated_at) AS first_seen,
            MAX(updated_at) AS last_seen
        FROM dl_active
        GROUP BY 1, 2, 3
    )
    SELECT jsonb_build_object(
        'total',  COALESCE(SUM(cnt), 0),
        'groups', COALESCE(jsonb_agg(
            jsonb_build_object(
                'entity_type',   entity_type,
                'error_message', error_message,
                'error_class',   error_class,
                'count',         cnt,
                'first_seen',    first_seen,
                'last_seen',     last_seen
            ) ORDER BY last_seen DESC
        ), '[]'::jsonb)
    ) INTO v_dead_letters
    FROM grouped;

    -- ------------------------------------------------------------------
    -- Never-verified counts + last drift run + oldest unverified
    -- ------------------------------------------------------------------
    SELECT COUNT(*) INTO v_nv_invoice
    FROM public.tally_vouchers
    WHERE tally_voucher_id IS NOT NULL AND last_verified_at IS NULL;

    SELECT COUNT(*) INTO v_nv_receipt
    FROM public.tally_receipt_vouchers trv
    JOIN public.bank_statement_lines bsl ON bsl.id = trv.bank_line_id
    WHERE trv.tally_voucher_id IS NOT NULL
      AND trv.last_verified_at IS NULL
      AND bsl.status <> 'skipped';

    SELECT GREATEST(
        (SELECT MAX(last_verified_at) FROM public.tally_vouchers),
        (SELECT MAX(last_verified_at) FROM public.tally_receipt_vouchers)
    ) INTO v_last_drift_run;

    -- Oldest unverified row (excluding NULLs to express the gap as an age, not infinity)
    SELECT LEAST(
        (SELECT MIN(last_verified_at) FROM public.tally_vouchers WHERE last_verified_at IS NOT NULL),
        (SELECT MIN(last_verified_at) FROM public.tally_receipt_vouchers WHERE last_verified_at IS NOT NULL)
    ) INTO v_oldest_unv_at;

    IF v_oldest_unv_at IS NOT NULL THEN
        v_oldest_unv_hr := ROUND(EXTRACT(EPOCH FROM (now() - v_oldest_unv_at)) / 3600.0, 1);
    END IF;

    -- Drift block
    SELECT jsonb_build_object(
        'unack_count', (SELECT COUNT(*) FROM public.tally_drift_log WHERE acknowledged_at IS NULL),
        'groups', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'entity_type',   entity_type,
                'outcome',       outcome,
                'count',         cnt,
                'last_detected', last_detected
            ) ORDER BY last_detected DESC)
            FROM (
                SELECT entity_type, outcome,
                       COUNT(*) AS cnt,
                       MAX(detected_at) AS last_detected
                FROM public.tally_drift_log
                WHERE acknowledged_at IS NULL
                GROUP BY entity_type, outcome
            ) g
        ), '[]'::jsonb),
        'items', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'id',               i.id,
                'entity_type',      i.entity_type,
                'voucher_number',   i.voucher_number,
                'tally_voucher_id', i.tally_voucher_id,
                'outcome',          i.outcome,
                'detected_at',      i.detected_at,
                'expected',         i.expected,
                'actual',           i.actual
            ) ORDER BY i.detected_at DESC)
            FROM (
                SELECT id, entity_type, voucher_number, tally_voucher_id, outcome,
                       detected_at, expected, actual
                FROM public.tally_drift_log
                WHERE acknowledged_at IS NULL
                ORDER BY detected_at DESC
                LIMIT 50
            ) i
        ), '[]'::jsonb),
        'never_verified', jsonb_build_object(
            'invoice', v_nv_invoice,
            'receipt', v_nv_receipt,
            'total',   v_nv_invoice + v_nv_receipt
        ),
        'last_drift_run_at',        v_last_drift_run,
        'oldest_unverified_age_hours', v_oldest_unv_hr
    ) INTO v_drift;

    v_drift_count := COALESCE((v_drift->>'unack_count')::int, 0);

    -- Middleware heartbeat
    SELECT * INTO v_mw_row FROM public.tally_middleware_status WHERE id = 1;

    SELECT MAX(created_at) INTO v_last_log_at
    FROM public.tally_sync_log
    WHERE created_at > now() - INTERVAL '10 minutes';
    v_fallback_active := v_last_log_at IS NOT NULL;
    v_mw_stale := v_mw_row.updated_at IS NULL OR v_mw_row.updated_at < now() - INTERVAL '5 minutes';

    SELECT COUNT(*) INTO v_stale_retry_cnt
    FROM public.tally_sync_queue
    WHERE status = 'retry'
      AND next_retry_at IS NOT NULL
      AND next_retry_at < now() - INTERVAL '1 hour';

    -- Alerts (existing)
    IF v_mw_stale AND NOT v_fallback_active THEN
        v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
            'code',   'middleware_offline',
            'level',  'critical',
            'title',  'Tally middleware offline',
            'detail', 'No heartbeat or queue activity in the last 5 minutes.',
            'since',  v_mw_row.updated_at
        ));
    ELSIF NOT v_mw_stale AND NOT v_mw_row.tally_reachable THEN
        v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
            'code',   'middleware_tally_unreachable',
            'level',  'warning',
            'title',  'TallyPrime unreachable',
            'detail', 'Middleware is running but cannot reach TallyPrime. Check that TallyPrime is open on the Windows host.',
            'since',  v_mw_row.last_check
        ));
    ELSIF NOT v_mw_stale AND v_mw_row.tally_reachable AND NOT v_mw_row.company_open THEN
        v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
            'code',   'middleware_company_not_open',
            'level',  'warning',
            'title',  'Tally company not open',
            'detail', 'TallyPrime is running but company ' || COALESCE(v_mw_row.company, '?') || ' is not the active company.',
            'since',  v_mw_row.last_check
        ));
    END IF;

    IF v_dl_count > 0 THEN
        v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
            'code',   'dead_letter_pending',
            'level',  'warning',
            'title',  v_dl_count || ' items in dead-letter',
            'detail', 'Open the resync panel to see grouped errors and operator actions.',
            'count',  v_dl_count
        ));
    END IF;

    IF v_drift_count > 0 THEN
        v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
            'code',   'drift_detected',
            'level',  'warning',
            'title',  v_drift_count || ' voucher(s) drifted from Tally',
            'detail', 'Confirmed vouchers no longer match what is in Tally. Review the drift banner.',
            'count',  v_drift_count
        ));
    END IF;

    IF v_stale_retry_cnt > 0 THEN
        v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
            'code',   'stale_retry',
            'level',  'warning',
            'title',  v_stale_retry_cnt || ' retry item(s) overdue > 1 hour',
            'detail', 'Items are eligible to retry but the middleware is not draining them. Click "All Invoices"/"All Receipts" to reset.',
            'count',  v_stale_retry_cnt
        ));
    END IF;

    IF v_in_flight > 0
       AND (v_last_confirmed IS NULL OR v_last_confirmed < now() - INTERVAL '1 hour') THEN
        v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
            'code',   'confirmed_silence',
            'level',  'info',
            'title',  'Queue not draining',
            'detail', 'No confirmations in the last hour while ' || v_in_flight || ' item(s) are waiting. Could be a slow Tally — keep an eye on it.',
            'since',  v_last_confirmed
        ));
    END IF;

    -- NEW: drift_check_stale alert
    --   Fires if no drift run in the last 24h OR > 100 never-verified rows.
    IF (v_last_drift_run IS NULL OR v_last_drift_run < now() - INTERVAL '24 hours')
       OR (v_nv_invoice + v_nv_receipt) > 100 THEN
        v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
            'code',   'drift_check_stale',
            'level',  'warning',
            'title',  CASE WHEN v_last_drift_run IS NULL THEN 'Drift verification has never run'
                           ELSE 'Drift verification stale > 24h' END,
            'detail', 'Middleware is not running claim_vouchers_to_verify on schedule. '
                      || (v_nv_invoice + v_nv_receipt) || ' voucher(s) never verified.',
            'count',  v_nv_invoice + v_nv_receipt,
            'since',  v_last_drift_run
        ));
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'data', v_result
            || jsonb_build_object('by_entity',    COALESCE(v_by_entity, '{}'::jsonb))
            || jsonb_build_object('dead_letters', COALESCE(v_dead_letters, jsonb_build_object('total', 0, 'groups', '[]'::jsonb)))
            || jsonb_build_object('drift',        COALESCE(v_drift, jsonb_build_object('unack_count', 0, 'groups', '[]'::jsonb, 'items', '[]'::jsonb)))
            || jsonb_build_object('alerts',       v_alerts)
            || jsonb_build_object('middleware', jsonb_build_object(
                'is_ready',        v_mw_row.is_ready,
                'tally_reachable', v_mw_row.tally_reachable,
                'company_open',    v_mw_row.company_open,
                'company',         v_mw_row.company,
                'last_check',      v_mw_row.last_check,
                'updated_at',      v_mw_row.updated_at,
                'fallback_active', v_fallback_active,
                'last_activity_at',v_last_log_at
            ))
    );
END;
$$;


CREATE FUNCTION public.get_tally_sync_queue(p_status text DEFAULT NULL::text, p_entity_type text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RETURN jsonb_build_object(
        'success', true,
        'data', COALESCE((
            SELECT jsonb_agg(to_jsonb(q))
            FROM (
                SELECT *
                FROM public.tally_sync_queue
                WHERE (p_status IS NULL OR status = p_status)
                  AND (p_entity_type IS NULL OR entity_type = p_entity_type)
                ORDER BY priority ASC, created_at ASC
                LIMIT p_limit OFFSET p_offset
            ) q
        ), '[]'::jsonb)
    );
END;
$$;


CREATE FUNCTION public.get_unhealthy_sensors() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_sensors jsonb;
BEGIN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'device_id', id, 'device_name', device_name, 'mac_address', mac_address, 'location', location,
        'health_status', health_status, 'connectivity_status', connectivity_status, 'battery_status', battery_status,
        'is_stale', (last_reading_at < NOW() - INTERVAL '1 hour'), 'consecutive_failures', consecutive_failures,
        'last_reading_at', last_reading_at, 'last_alert_at', last_alert_at
    )), '[]'::jsonb) INTO v_sensors FROM sensors
    WHERE is_active = true AND (health_status != 'healthy' OR consecutive_failures > 0 OR battery_status IN ('low', 'critical'));
    RETURN utils.success_response(v_sensors);
EXCEPTION WHEN OTHERS THEN RETURN utils.database_error_response('Failed to get unhealthy sensors', SQLERRM, SQLSTATE);
END;
$$;


CREATE FUNCTION public.get_unresolved_auto_invoice_error_count() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    RETURN (
        SELECT COUNT(*)
        FROM auto_invoice_errors
        WHERE resolved_at IS NULL
    );
END;
$$;


CREATE FUNCTION public.get_user_details(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_auth_uid UUID;
    v_caller_id UUID;
    v_caller_role user_role;
    v_target_user jsonb;
    v_target_role user_role;
    v_assigned_customers jsonb;
    v_assigned_count INTEGER;
BEGIN
    -- Cache auth.uid()
    v_auth_uid := auth.uid();

    -- Get caller's profile
    SELECT id, role INTO v_caller_id, v_caller_role
    FROM user_profiles
    WHERE auth_user_id = v_auth_uid AND active = true;

    -- Authorization: must be admin or supervisor
    IF v_caller_role IS NULL OR v_caller_role NOT IN ('admin', 'supervisor') THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'PERMISSION_DENIED',
            'message', 'Only administrators and supervisors can view user details'
        );
    END IF;

    -- Validate user_id
    IF p_user_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'INVALID_INPUT',
            'message', 'User ID is required'
        );
    END IF;

    -- Get target user's role first to check permissions
    SELECT role INTO v_target_role
    FROM user_profiles
    WHERE id = p_user_id;

    IF v_target_role IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'NOT_FOUND',
            'message', 'User not found'
        );
    END IF;

    -- Supervisors cannot view admin user details
    IF v_caller_role = 'supervisor' AND v_target_role = 'admin' THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'PERMISSION_DENIED',
            'message', 'Supervisors cannot view admin user details'
        );
    END IF;

    -- Get user details with assigned customer count
    SELECT jsonb_build_object(
        'id', up.id,
        'auth_user_id', up.auth_user_id,
        'name', up.name,
        'display_name', up.display_name,
        'mobile', up.mobile,
        'role', up.role,
        'active', up.active,
        'created_at', up.created_at,
        'updated_at', up.updated_at,
        'mobile_verified', up.mobile_verified,
        'mobile_verified_at', up.mobile_verified_at,
        'assigned_customers_count', COALESCE(
            (SELECT COUNT(*) FROM users_customers_new uc
             WHERE uc.user_profile_id = up.id AND uc.active = true), 0
        )
    ) INTO v_target_user
    FROM user_profiles up
    WHERE up.id = p_user_id;

    -- Get assigned customers with details
    SELECT jsonb_agg(
        jsonb_build_object(
            'customer_id', c.id,
            'customer_name', c.name,
            'customer_mobile', c.mobile,
            'customer_city', c.city,
            'assigned_at', uc.assigned_at,
            'assigned_by_name', (
                SELECT name FROM user_profiles WHERE id = uc.assigned_by
            )
        ) ORDER BY uc.assigned_at DESC
    ) INTO v_assigned_customers
    FROM users_customers_new uc
    JOIN customers c ON c.id = uc.customer_id
    WHERE uc.user_profile_id = p_user_id AND uc.active = true;

    RETURN jsonb_build_object(
        'success', true,
        'user', v_target_user,
        'assigned_customers', COALESCE(v_assigned_customers, '[]'::jsonb)
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'INTERNAL_ERROR',
            'message', 'Failed to retrieve user details: ' || SQLERRM
        );
END;
$$;


CREATE FUNCTION public.get_user_profile_id(p_auth_user_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  BEGIN
      RETURN (SELECT id FROM user_profiles WHERE auth_user_id = p_auth_user_id);
  END;
  $$;


CREATE FUNCTION public.get_users_list(p_search_query text DEFAULT ''::text, p_role_filter public.user_role[] DEFAULT NULL::public.user_role[], p_active_filter boolean DEFAULT NULL::boolean, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_auth_uid UUID;
    v_caller_id UUID;
    v_caller_role user_role;
    v_search TEXT;
    v_total_count INTEGER;
    v_users jsonb;
BEGIN
    -- Cache auth.uid()
    v_auth_uid := auth.uid();

    -- Get caller's profile
    SELECT id, role INTO v_caller_id, v_caller_role
    FROM user_profiles
    WHERE auth_user_id = v_auth_uid AND active = true;

    -- Authorization: must be admin or supervisor
    IF v_caller_role IS NULL OR v_caller_role NOT IN ('admin', 'supervisor') THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'PERMISSION_DENIED',
            'message', 'Only administrators and supervisors can view user list'
        );
    END IF;

    -- Validate and normalize p_limit
    IF p_limit IS NULL OR p_limit < 1 THEN
        p_limit := 20;
    ELSIF p_limit > 100 THEN
        p_limit := 100;
    END IF;

    -- Validate p_offset
    IF p_offset IS NULL OR p_offset < 0 THEN
        p_offset := 0;
    END IF;

    -- Normalize search query
    v_search := TRIM(COALESCE(p_search_query, ''));

    -- Get total count
    SELECT COUNT(*) INTO v_total_count
    FROM user_profiles up
    WHERE
        -- Search filter
        (v_search = '' OR up.name ILIKE '%' || v_search || '%' OR up.mobile ILIKE '%' || v_search || '%')
        -- Role filter
        AND (p_role_filter IS NULL OR up.role = ANY(p_role_filter))
        -- Active filter
        AND (p_active_filter IS NULL OR up.active = p_active_filter)
        -- Supervisors cannot see admin users
        AND (v_caller_role = 'admin' OR up.role != 'admin');

    -- Get users with assigned customer count (fixed: use subquery for pagination)
    SELECT jsonb_agg(
        jsonb_build_object(
            'id', sub.id,
            'auth_user_id', sub.auth_user_id,
            'name', sub.name,
            'display_name', sub.display_name,
            'mobile', sub.mobile,
            'role', sub.role,
            'active', sub.active,
            'created_at', sub.created_at,
            'updated_at', sub.updated_at,
            'assigned_customers_count', COALESCE(
                (SELECT COUNT(*) FROM users_customers_new uc
                 WHERE uc.user_profile_id = sub.id AND uc.active = true), 0
            )
        ) ORDER BY sub.name ASC
    ) INTO v_users
    FROM (
        SELECT id, auth_user_id, name, display_name, mobile, role, active, created_at, updated_at
        FROM user_profiles up
        WHERE
            -- Search filter
            (v_search = '' OR up.name ILIKE '%' || v_search || '%' OR up.mobile ILIKE '%' || v_search || '%')
            -- Role filter
            AND (p_role_filter IS NULL OR up.role = ANY(p_role_filter))
            -- Active filter
            AND (p_active_filter IS NULL OR up.active = p_active_filter)
            -- Supervisors cannot see admin users
            AND (v_caller_role = 'admin' OR up.role != 'admin')
        ORDER BY name ASC
        LIMIT p_limit OFFSET p_offset
    ) sub;

    RETURN jsonb_build_object(
        'success', true,
        'users', COALESCE(v_users, '[]'::jsonb),
        'pagination', jsonb_build_object(
            'total_count', v_total_count,
            'limit', p_limit,
            'offset', p_offset,
            'has_more', (p_offset + p_limit) < v_total_count
        )
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'INTERNAL_ERROR',
            'message', 'Failed to retrieve users list: ' || SQLERRM
        );
END;
$$;


CREATE FUNCTION public.get_vehicle_suggestions(p_prefix text DEFAULT NULL::text, p_limit integer DEFAULT 5, p_customer_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
    v_normalized_prefix TEXT;
    v_cutoff_date TIMESTAMPTZ;
BEGIN
    -- Normalize prefix
    v_normalized_prefix := UPPER(TRIM(COALESCE(p_prefix, '')));

    -- Calculate 120 days ago
    v_cutoff_date := NOW() - INTERVAL '120 days';

    -- If customer_id provided, get their frequently used vehicles first
    IF p_customer_id IS NOT NULL THEN
        WITH customer_registrations AS (
            SELECT registration
            FROM goodsreceived
            WHERE registration IS NOT NULL
              AND registration != ''
              AND deleted_at IS NULL
              AND date >= v_cutoff_date
              AND customer_id = p_customer_id

            UNION ALL

            SELECT registration
            FROM dispatch
            WHERE registration IS NOT NULL
              AND registration != ''
              AND deleted_at IS NULL
              AND disp_date >= v_cutoff_date
              AND customer_id = p_customer_id
        ),
        counted AS (
            SELECT
                registration,
                COUNT(*) AS usage_count
            FROM customer_registrations
            WHERE (v_normalized_prefix = '' OR UPPER(registration) LIKE (v_normalized_prefix || '%'))
            GROUP BY registration
        ),
        ranked AS (
            SELECT registration, usage_count
            FROM counted
            ORDER BY usage_count DESC, registration ASC
            LIMIT p_limit
        )
        SELECT jsonb_build_object(
            'suggestions',
            COALESCE(jsonb_agg(
                jsonb_build_object(
                    'registration', registration,
                    'usage_count', usage_count
                )
            ), '[]'::jsonb)
        )
        INTO v_result
        FROM ranked;

        -- If customer has suggestions, return them
        IF jsonb_array_length(v_result->'suggestions') > 0 THEN
            RETURN v_result;
        END IF;
    END IF;

    -- Fallback: return popular registrations across all customers
    WITH all_registrations AS (
        SELECT registration
        FROM goodsreceived
        WHERE registration IS NOT NULL
          AND registration != ''
          AND deleted_at IS NULL
          AND date >= v_cutoff_date

        UNION ALL

        SELECT registration
        FROM dispatch
        WHERE registration IS NOT NULL
          AND registration != ''
          AND deleted_at IS NULL
          AND disp_date >= v_cutoff_date
    ),
    counted AS (
        SELECT
            registration,
            COUNT(*) AS usage_count
        FROM all_registrations
        WHERE (v_normalized_prefix = '' OR UPPER(registration) LIKE (v_normalized_prefix || '%'))
        GROUP BY registration
        HAVING COUNT(*) >= 2
    ),
    ranked AS (
        SELECT registration, usage_count
        FROM counted
        ORDER BY usage_count DESC, registration ASC
        LIMIT p_limit
    )
    SELECT jsonb_build_object(
        'suggestions',
        COALESCE(jsonb_agg(
            jsonb_build_object(
                'registration', registration,
                'usage_count', usage_count
            )
        ), '[]'::jsonb)
    )
    INTO v_result
    FROM ranked;

    RETURN v_result;
END;
$$;


CREATE FUNCTION public.guard_bank_reco_company_config_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF (SELECT count(*) FROM public.bank_reco_company_config) <= 1 THEN
        RAISE EXCEPTION 'Cannot delete the only bank_reco_company_config row — receipt RPCs depend on it'
            USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN OLD;
END;
$$;


CREATE FUNCTION public.handle_receipt_queue_dead_letter() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.entity_type = 'receipt'
       AND NEW.status = 'dead_letter'
       AND OLD.status IS DISTINCT FROM 'dead_letter'
    THEN
        UPDATE public.bank_statement_lines
        SET status = 'failed',
            review_note = CASE
                WHEN review_note IS NULL OR review_note = ''
                    THEN format('sync_failed at %s: %s', now()::text, COALESCE(NEW.error_message,'unknown'))
                ELSE review_note || format(' | sync_failed at %s: %s', now()::text, COALESCE(NEW.error_message,'unknown'))
            END
        WHERE tally_sync_queue_id = NEW.id
          AND status = 'queued';
    END IF;
    RETURN NEW;
END;
$$;


CREATE FUNCTION public.has_role(required_role public.user_role) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  BEGIN
      RETURN EXISTS (
          SELECT 1 FROM user_profiles
          WHERE auth_user_id = auth.uid()
          AND role = required_role
          AND active = true
      );
  END;
  $$;


CREATE FUNCTION public.ignore_order(p_order_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_user_id UUID;
      v_order_no TEXT;
      v_current_status TEXT;
  BEGIN
      -- Get user ID
      SELECT id INTO v_user_id FROM user_profiles WHERE auth_user_id = auth.uid();

      -- Get order details
      SELECT order_no, status INTO v_order_no, v_current_status
      FROM orders WHERE id = p_order_id;

      IF NOT FOUND THEN
          RETURN jsonb_build_object('success', false, 'message', 'Order not found');
      END IF;

      -- Log order ignore
      PERFORM log_order_change(
          p_order_id := p_order_id,
          p_order_item_id := NULL,
          p_action := 'order_ignored',
          p_details := jsonb_build_object(
              'order_no', v_order_no,
              'previous_status', v_current_status,
              'ignore_reason', COALESCE(p_reason, 'No reason provided')
          ),
          p_changed_by := v_user_id
      );

      -- Update order
      UPDATE orders SET
          is_ignored = TRUE,
          ignored_at = NOW(),
          ignored_by = v_user_id,
          ignored_reason = p_reason,
          updated_at = NOW(),
          updated_by = v_user_id
      WHERE id = p_order_id;

      RETURN jsonb_build_object('success', true, 'message', 'Order ignored successfully');
  END;
  $$;


CREATE FUNCTION public.ignore_order(p_order_id uuid, p_reason text, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM orders WHERE id = p_order_id) THEN
        RETURN utils.not_found_response('Order', p_order_id::text);
    END IF;

    UPDATE orders SET status = 'ignored', ignore_reason = p_reason, ignored_at = NOW(), ignored_by = p_user_id, updated_at = NOW()
    WHERE id = p_order_id;

    RETURN utils.success_response(jsonb_build_object('order_id', p_order_id), 'Order ignored successfully');
EXCEPTION
    WHEN OTHERS THEN
        RETURN utils.database_error_response('Failed to ignore order', SQLERRM, SQLSTATE);
END;
$$;



