CREATE FUNCTION public.link_supabase_auth_user(user_mobile character varying, supabase_auth_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      profile_id uuid;
  BEGIN
      -- Update the user_profile with the real Supabase auth ID
      UPDATE user_profiles
      SET auth_user_id = supabase_auth_id,
          updated_at = now()
      WHERE mobile = user_mobile  -- Changed from email
      RETURNING id INTO profile_id;

      IF profile_id IS NULL THEN
          RAISE EXCEPTION 'No user profile found for mobile: %', user_mobile;  -- Changed message
      END IF;

      RAISE NOTICE 'Linked user profile % to Supabase auth user %', profile_id, supabase_auth_id;
      RETURN true;
  END;
$$;


