CREATE FUNCTION public.monitor_print_jobs() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  stuck_job RECORD;
BEGIN
  -- Find jobs that have been "printing" for more than 10 minutes
  -- These are likely completed but CUPS already purged them
  FOR stuck_job IN
    SELECT id, cups_job_id, created_at
    FROM print_jobs
    WHERE status = 'printing'
      AND created_at < NOW() - INTERVAL '10 minutes'
  LOOP
    -- Update to completed status
    UPDATE print_jobs
    SET
      status = 'completed',
      completed_at = NOW(),
      updated_at = NOW(),
      error_message = 'Auto-completed by monitor (job exceeded 10 minute threshold)'
    WHERE id = stuck_job.id;

    RAISE NOTICE 'Auto-completed stuck print job % (CUPS job %)', stuck_job.id, stuck_job.cups_job_id;
  END LOOP;
END;
$$;


CREATE FUNCTION public.pause_tally_sync(p_entity_type text DEFAULT NULL::text, p_reason text DEFAULT 'manually paused'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_paused INT;
    v_sentinel TIMESTAMPTZ := '2099-01-01 00:00:00+00'::timestamptz;
BEGIN
    UPDATE public.tally_sync_queue
    SET status        = 'retry',
        next_retry_at = v_sentinel,
        locked_by     = NULL,
        locked_at     = NULL,
        error_message = p_reason || ' at ' || now()::text,
        updated_at    = now()
    WHERE status IN ('pending', 'processing')
      AND (p_entity_type IS NULL OR entity_type = p_entity_type);

    GET DIAGNOSTICS v_paused = ROW_COUNT;

    RETURN jsonb_build_object(
        'success',     true,
        'paused_rows', v_paused,
        'entity_type', COALESCE(p_entity_type, 'all'),
        'reason',      p_reason,
        'sentinel_at', v_sentinel,
        'paused_at',   now()
    );
END;
$$;


CREATE FUNCTION public.phone_auth_login(p_phone_number character varying, p_otp_code character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_verification_result jsonb;
    v_user_profile RECORD;
    v_phone_formatted VARCHAR(15);
    v_user_id UUID;
    v_auth_user_id UUID;
BEGIN
    -- Format phone number
    v_phone_formatted := REGEXP_REPLACE(p_phone_number, '[^0-9]', '', 'g');
    IF LENGTH(v_phone_formatted) = 10 THEN
        v_phone_formatted := '91' || v_phone_formatted;
    END IF;

    -- Verify OTP first
    v_verification_result := verify_otp(v_phone_formatted, p_otp_code, 'login');

    IF NOT (v_verification_result->>'success')::boolean THEN
        RETURN v_verification_result;
    END IF;

    -- Extract user_id from verification result
    v_auth_user_id := (v_verification_result->'data'->>'user_id')::uuid;

    -- If user doesn't exist, they need to register first
    IF v_auth_user_id IS NULL THEN
        RETURN utils.error_response(
            'USER_NOT_REGISTERED',
            'Phone number verified but user not registered. Please complete registration first.',
            jsonb_build_object(
                'phone_verified', true,
                'customer_exists', (v_verification_result->'data'->>'phone_verified')::boolean,
                'is_new_user', true
            )::text
        );
    END IF;

    -- Get user profile information
    SELECT up.id, up.name, up.display_name, up.email, up.role
    INTO v_user_profile
    FROM public.user_profiles up
    WHERE up.auth_user_id = v_auth_user_id;

    -- Update mobile verification status
    UPDATE public.user_profiles
    SET mobile = v_phone_formatted, mobile_verified = TRUE, mobile_verified_at = NOW()
    WHERE auth_user_id = v_auth_user_id;

    -- Also update auth.users phone confirmation
    UPDATE auth.users
    SET phone = v_phone_formatted, phone_confirmed_at = NOW()
    WHERE id = v_auth_user_id;

    RETURN utils.success_response(
        jsonb_build_object(
            'user_id', v_user_profile.id,
            'auth_user_id', v_auth_user_id,
            'user_profile', jsonb_build_object(
                'name', v_user_profile.name,
                'display_name', v_user_profile.display_name,
                'email', v_user_profile.email,
                'role', v_user_profile.role,
                'mobile', v_phone_formatted,
                'mobile_verified', true,
                'customer_exists', (v_verification_result->'data'->>'phone_verified')::boolean
            ),
            'is_new_user', false
        ),
        'Login successful'
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN utils.database_error_response('Error during phone login', SQLERRM, SQLSTATE);
END;
$$;


CREATE FUNCTION public.reactivate_order(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_user_id UUID;
      v_order_no TEXT;
  BEGIN
      -- Get user ID
      SELECT id INTO v_user_id FROM user_profiles WHERE auth_user_id = auth.uid();

      -- Get order number
      SELECT order_no INTO v_order_no FROM orders WHERE id = p_order_id;

      IF NOT FOUND THEN
          RETURN jsonb_build_object('success', false, 'message', 'Order not found');
      END IF;

      -- Log order reactivation
      PERFORM log_order_change(
          p_order_id := p_order_id,
          p_order_item_id := NULL,
          p_action := 'order_reactivated',
          p_details := jsonb_build_object(
              'order_no', v_order_no,
              'reason', 'Order brought back to active queue'
          ),
          p_changed_by := v_user_id
      );

      -- Update order
      UPDATE orders SET
          is_ignored = FALSE,
          ignored_at = NULL,
          ignored_by = NULL,
          ignored_reason = NULL,
          updated_at = NOW(),
          updated_by = v_user_id
      WHERE id = p_order_id;

      RETURN jsonb_build_object('success', true, 'message', 'Order reactivated successfully');
  END;
  $$;


CREATE FUNCTION public.reactivate_order(p_order_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM orders WHERE id = p_order_id) THEN
        RETURN utils.not_found_response('Order', p_order_id::text);
    END IF;

    UPDATE orders SET status = 'pending', ignore_reason = NULL, ignored_at = NULL, ignored_by = NULL, updated_at = NOW()
    WHERE id = p_order_id;

    RETURN utils.success_response(jsonb_build_object('order_id', p_order_id), 'Order reactivated successfully');
EXCEPTION
    WHEN OTHERS THEN
        RETURN utils.database_error_response('Failed to reactivate order', SQLERRM, SQLSTATE);
END;
$$;


CREATE FUNCTION public.recalculate_invoice_items(p_invoice_id uuid, p_duration_mode text DEFAULT 'legacy'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_duration_mode text;
    v_invoice record;
    v_recalculation jsonb;
BEGIN
    v_duration_mode := public.validate_invoice_duration_mode(p_duration_mode);

    SELECT id, gr_id, COALESCE(duration_mode, 'legacy') as duration_mode
    INTO v_invoice
    FROM invoice
    WHERE id = p_invoice_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invoice not found');
    END IF;

    v_recalculation := public.build_invoice_recalculation_rows(v_invoice.gr_id, v_duration_mode, p_invoice_id);

    IF NOT COALESCE((v_recalculation->>'success')::boolean, false) THEN
        RETURN v_recalculation;
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'invoice_id', p_invoice_id,
        'duration_mode', v_duration_mode,
        'rows', v_recalculation->'rows',
        'items', v_recalculation->'items',
        'totals', v_recalculation->'totals',
        'data', jsonb_build_object(
            'duration_mode', v_duration_mode,
            'rows', v_recalculation->'rows',
            'items', v_recalculation->'items',
            'totals', v_recalculation->'totals'
        ),
        'message', 'Invoice items recalculated successfully'
    );
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object('success', false, 'error', SQLERRM, 'error_code', SQLSTATE);
END;
$$;


CREATE FUNCTION public.record_sensor_health_status(p_device_mac character varying, p_health_status character varying, p_connectivity_status character varying, p_battery_level numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_sensor_id uuid; v_event_id uuid;
BEGIN
    SELECT id INTO v_sensor_id FROM sensors WHERE mac_address = p_device_mac;
    IF v_sensor_id IS NULL THEN
        RETURN utils.not_found_response('Sensor', p_device_mac);
    END IF;
    UPDATE sensors SET health_status = p_health_status, connectivity_status = p_connectivity_status, battery_level = COALESCE(p_battery_level, battery_level), updated_at = NOW() WHERE id = v_sensor_id;
    INSERT INTO sensor_health_events (sensor_id, health_status, connectivity_status) VALUES (v_sensor_id, p_health_status, p_connectivity_status) RETURNING id INTO v_event_id;
    RETURN utils.success_response(jsonb_build_object('device_id', v_sensor_id, 'event_id', v_event_id), 'Health status recorded');
EXCEPTION WHEN OTHERS THEN RETURN utils.database_error_response('Failed to record sensor health', SQLERRM, SQLSTATE);
END;
$$;


CREATE FUNCTION public.record_sensor_reading(p_device_mac character varying, p_temperature numeric, p_humidity numeric, p_device_name character varying DEFAULT NULL::character varying, p_location character varying DEFAULT NULL::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_device_id UUID;
    v_reading_id UUID;
BEGIN
    -- Find or create device by MAC address
    SELECT id INTO v_device_id
    FROM sensor_devices
    WHERE mac_address = p_device_mac;

    IF v_device_id IS NULL THEN
        -- Create new device
        INSERT INTO sensor_devices (device_name, mac_address, location)
        VALUES (
            COALESCE(p_device_name, 'Sensor ' || p_device_mac),
            p_device_mac,
            p_location
        )
        RETURNING id INTO v_device_id;
    ELSE
        -- Update last_reading_at AND reset staleness if device was stale
        UPDATE sensor_devices
        SET
            last_reading_at = NOW(),
            -- Reset staleness when fresh reading arrives
            is_stale = FALSE,
            connectivity_status = 'ONLINE',
            health_status = CASE
                WHEN is_stale = TRUE OR connectivity_status = 'STALE' THEN 'healthy'
                ELSE health_status
            END,
            consecutive_failures = 0
        WHERE id = v_device_id;
    END IF;

    -- Insert reading
    INSERT INTO sensor_readings (device_id, temperature, humidity, recorded_at)
    VALUES (v_device_id, p_temperature, p_humidity, NOW())
    RETURNING id INTO v_reading_id;

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Reading recorded successfully',
        'device_id', v_device_id,
        'reading_id', v_reading_id
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', SQLERRM,
        'error_code', SQLSTATE
    );
END;
$$;


CREATE FUNCTION public.record_voucher_verification(p_voucher_table_id uuid, p_entity_type text, p_outcome text, p_actual jsonb DEFAULT NULL::jsonb, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_entity_id      UUID;
    v_tally_id       TEXT;
    v_voucher_no     TEXT;
    v_expected       JSONB;
    v_source_deleted BOOLEAN := false;
    v_outcome        TEXT;
BEGIN
    IF p_outcome NOT IN ('exists', 'missing', 'changed') THEN
        RETURN jsonb_build_object('success', false,
            'error', 'p_outcome must be one of exists/missing/changed');
    END IF;

    IF p_outcome = 'exists' THEN
        RETURN jsonb_build_object('success', true, 'recorded', false);
    END IF;

    IF p_entity_type = 'invoice' THEN
        SELECT invoice_id, tally_voucher_id, voucher_number,
               jsonb_build_object('amount', amount, 'voucher_date', voucher_date,
                                  'tally_company', tally_company)
        INTO v_entity_id, v_tally_id, v_voucher_no, v_expected
        FROM public.tally_vouchers WHERE id = p_voucher_table_id;

        IF v_entity_id IS NOT NULL THEN
            SELECT (deleted_at IS NOT NULL) INTO v_source_deleted
            FROM public.invoice WHERE id = v_entity_id;
        END IF;
    ELSIF p_entity_type = 'receipt' THEN
        SELECT bank_line_id, tally_voucher_id, voucher_number,
               jsonb_build_object('amount', amount_received, 'voucher_date', voucher_date,
                                  'tally_company', tally_company)
        INTO v_entity_id, v_tally_id, v_voucher_no, v_expected
        FROM public.tally_receipt_vouchers WHERE id = p_voucher_table_id;

        IF v_entity_id IS NOT NULL THEN
            SELECT (status = 'skipped') INTO v_source_deleted
            FROM public.bank_statement_lines WHERE id = v_entity_id;
        END IF;
    ELSE
        RETURN jsonb_build_object('success', false, 'error', 'p_entity_type must be invoice or receipt');
    END IF;

    IF v_entity_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'voucher not found');
    END IF;

    -- If the source has been deleted/skipped, rewrite the outcome so dashboards
    -- can distinguish "real drift" from "expected absence after delete".
    v_outcome := CASE WHEN v_source_deleted THEN 'source_deleted' ELSE p_outcome END;

    INSERT INTO public.tally_drift_log
        (entity_type, entity_id, voucher_table_id, tally_voucher_id, voucher_number,
         outcome, expected, actual, notes)
    VALUES
        (p_entity_type, v_entity_id, p_voucher_table_id, v_tally_id, v_voucher_no,
         v_outcome, v_expected, p_actual, p_notes);

    RETURN jsonb_build_object('success', true, 'recorded', true, 'outcome', v_outcome);
END;
$$;


