CREATE FUNCTION public.refresh_dirty_mvs() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    r RECORD;
BEGIN
    -- Process each dirty MV
    FOR r IN
        SELECT mv_name FROM mv_refresh_queue
        WHERE needs_refresh = TRUE
        ORDER BY last_marked_dirty ASC  -- Oldest first
    LOOP
        BEGIN
            -- Mark as processing (prevents re-entry)
            UPDATE mv_refresh_queue
            SET needs_refresh = FALSE, last_refresh = NOW()
            WHERE mv_name = r.mv_name;

            -- Refresh the MV
            EXECUTE format('REFRESH MATERIALIZED VIEW CONCURRENTLY %I', r.mv_name);

            RAISE NOTICE 'Refreshed: %', r.mv_name;
        EXCEPTION WHEN OTHERS THEN
            -- On error, try non-concurrent refresh
            BEGIN
                EXECUTE format('REFRESH MATERIALIZED VIEW %I', r.mv_name);
                RAISE NOTICE 'Refreshed (non-concurrent): %', r.mv_name;
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'Failed to refresh %: %', r.mv_name, SQLERRM;
            END;
        END;
    END LOOP;
END;
$$;


CREATE FUNCTION public.refresh_jwt_token(p_refresh_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_jwt_secret TEXT;
    v_access_expiry INTEGER;
    v_refresh_expiry INTEGER;
    v_token_result RECORD;
    v_user_id UUID;
    v_user_profile RECORD;
    v_iat INTEGER;
    v_access_exp INTEGER;
    v_refresh_exp INTEGER;
    v_access_token_payload TEXT;
    v_refresh_token_payload TEXT;
    v_access_token TEXT;
    v_refresh_token TEXT;
BEGIN
    -- Validate input
    IF p_refresh_token IS NULL OR p_refresh_token = '' THEN
        RETURN utils.error_response('INVALID_TOKEN', 'Refresh token is required');
    END IF;

    -- Get JWT secret from config
    SELECT secret_value INTO v_jwt_secret
    FROM jwt_config
    WHERE secret_name = 'supabase_jwt_secret' AND is_active = TRUE;

    IF v_jwt_secret IS NULL THEN
        RETURN utils.error_response('CONFIG_ERROR', 'JWT secret not configured');
    END IF;

    -- Verify the refresh token
    SELECT * INTO v_token_result
    FROM extensions.verify(p_refresh_token, v_jwt_secret, 'HS256');

    -- Check if token is valid (signature + not expired)
    IF NOT v_token_result.valid THEN
        RETURN utils.error_response('INVALID_TOKEN', 'Refresh token is invalid or expired');
    END IF;

    -- Verify it's a refresh token (has type = 'refresh')
    IF v_token_result.payload->>'type' IS NULL OR v_token_result.payload->>'type' != 'refresh' THEN
        RETURN utils.error_response('INVALID_TOKEN', 'Token is not a valid refresh token');
    END IF;

    -- Extract user ID from token
    v_user_id := (v_token_result.payload->>'sub')::UUID;

    IF v_user_id IS NULL THEN
        RETURN utils.error_response('INVALID_TOKEN', 'Token missing user identifier');
    END IF;

    -- Get user profile
    SELECT * INTO v_user_profile
    FROM user_profiles
    WHERE auth_user_id = v_user_id;

    IF v_user_profile IS NULL THEN
        RETURN utils.error_response('USER_NOT_FOUND', 'User not found');
    END IF;

    -- Check if user is active
    IF NOT v_user_profile.active THEN
        RETURN utils.error_response('USER_INACTIVE', 'User account is inactive');
    END IF;

    -- Get token expiry config
    SELECT COALESCE(secret_value::INTEGER, 63072000) INTO v_access_expiry
    FROM jwt_config
    WHERE secret_name = 'jwt_access_token_expiry' AND is_active = TRUE;

    SELECT COALESCE(secret_value::INTEGER, 63072000) INTO v_refresh_expiry
    FROM jwt_config
    WHERE secret_name = 'jwt_refresh_token_expiry' AND is_active = TRUE;

    -- Use defaults if not found
    v_access_expiry := COALESCE(v_access_expiry, 63072000);
    v_refresh_expiry := COALESCE(v_refresh_expiry, 63072000);

    -- Generate new tokens
    v_iat := EXTRACT(EPOCH FROM NOW())::INTEGER;
    v_access_exp := v_iat + v_access_expiry;
    v_refresh_exp := v_iat + v_refresh_expiry;

    -- Build access token payload (same format as verify_otp_or_register)
    v_access_token_payload := format(
        '{"aud":"authenticated","exp":%s,"iat":%s,"iss":"supabase","sub":"%s","phone":"%s","app_metadata":{"provider":"phone","providers":["phone"]},"user_metadata":{"name":"%s","display_name":"%s","role":"%s"},"role":"authenticated"}',
        v_access_exp, v_iat,
        v_user_profile.auth_user_id::TEXT,
        v_user_profile.mobile,
        COALESCE(v_user_profile.name, ''),
        COALESCE(v_user_profile.display_name, ''),
        v_user_profile.role::TEXT
    );

    -- Build refresh token payload
    v_refresh_token_payload := format(
        '{"aud":"authenticated","exp":%s,"iat":%s,"iss":"supabase","sub":"%s","type":"refresh"}',
        v_refresh_exp, v_iat,
        v_user_profile.auth_user_id::TEXT
    );

    -- Sign the tokens
    v_access_token := extensions.sign(v_access_token_payload::json, v_jwt_secret);
    v_refresh_token := extensions.sign(v_refresh_token_payload::json, v_jwt_secret);

    -- Return success response
    RETURN jsonb_build_object(
        'success', TRUE,
        'access_token', v_access_token,
        'refresh_token', v_refresh_token,
        'expires_at', to_timestamp(v_access_exp)::TEXT
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN utils.error_response('REFRESH_ERROR', 'Failed to refresh token: ' || SQLERRM);
END;
$$;


