    RETURN jsonb_build_object('success', TRUE, 'message', format('GRN "%s" restored', v_grn_no));
END;
$$;


CREATE FUNCTION public.restore_invoice(p_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_inv_no VARCHAR(50);
BEGIN
