    IF v_inv_no IS NULL THEN RETURN jsonb_build_object('success', FALSE, 'message', 'Invoice not found or not deleted'); END IF;
    UPDATE invoice SET deleted_at = NULL, deleted_by = NULL WHERE id = p_invoice_id;
