CREATE FUNCTION public.restore_stock_on_dispatch_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    -- Restore stock for all items in this dispatch (capped at qty)
    UPDATE goodsreceived_trl gt
    SET stock = LEAST(gt.qty, gt.stock + dt.disp_qty)  -- Cap at qty
    FROM dispatch_trl dt
    WHERE dt.disp_id = OLD.id
    AND gt.id = dt.gr_trl_id;

    -- Record stock movements for the reversal
    INSERT INTO stock_movements (
        gr_trl_id, movement_type, quantity,
        reference_id, reference_type,
        balance_before, balance_after, notes
    )
    SELECT
        dt.gr_trl_id,
        'dispatch_deleted',
        dt.disp_qty,
        OLD.id,
        'dispatch',
        gt.stock - LEAST(dt.disp_qty, gt.qty - gt.stock + dt.disp_qty),
        gt.stock,
        'Stock restored due to dispatch deletion'
    FROM dispatch_trl dt
    JOIN goodsreceived_trl gt ON gt.id = dt.gr_trl_id
    WHERE dt.disp_id = OLD.id;

    -- Delete dispatch_trl records
    DELETE FROM dispatch_trl WHERE disp_id = OLD.id;

    -- Restore source order if exists
    IF OLD.source_order_id IS NOT NULL THEN
        UPDATE orders
        SET
            status = 'OPEN',
            updated_at = NOW()
        WHERE id = OLD.source_order_id;

        -- Reset order items to pending
        UPDATE order_items
        SET
            fulfilled_quantity = 0,
            item_status = 'pending',
            updated_at = NOW()
        WHERE order_id = OLD.source_order_id;
    END IF;

    RETURN OLD;
END;
$$;


CREATE FUNCTION public.resume_tally_sync(p_entity_type text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_resumed  INT;
    v_sentinel TIMESTAMPTZ := '2099-01-01 00:00:00+00'::timestamptz;
BEGIN
    -- Only un-defer rows that were paused by pause_tally_sync (next_retry_at
    -- at or past the sentinel). This leaves normally-retrying rows alone.
    UPDATE public.tally_sync_queue
    SET status        = 'pending',
        next_retry_at = NULL,
        error_message = NULL,
        updated_at    = now()
    WHERE status = 'retry'
      AND next_retry_at >= v_sentinel
      AND (p_entity_type IS NULL OR entity_type = p_entity_type);

    GET DIAGNOSTICS v_resumed = ROW_COUNT;

    RETURN jsonb_build_object(
        'success',      true,
        'resumed_rows', v_resumed,
        'entity_type',  COALESCE(p_entity_type, 'all'),
        'resumed_at',   now()
    );
END;
$$;


CREATE FUNCTION public.resync_tally_receipt(p_line_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_line             public.bank_statement_lines;
    v_voucher_number   text;
    v_tally_voucher_id text;
    v_queue_id         uuid;
    v_config           public.bank_reco_company_config;
BEGIN
    SELECT * INTO v_line FROM public.bank_statement_lines WHERE id = p_line_id FOR UPDATE;
    IF v_line.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Receipt not found');
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM public.bank_statements bs
        WHERE bs.id = v_line.statement_id AND bs.account_number = 'MANUAL'
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Not a manual receipt');
    END IF;

    IF v_line.status != 'reconciled' THEN
        RETURN jsonb_build_object('success', false, 'error',
            format('Resync only valid for reconciled receipts, current status: "%s"', v_line.status));
    END IF;

    SELECT voucher_number, tally_voucher_id
    INTO v_voucher_number, v_tally_voucher_id
    FROM public.tally_receipt_vouchers WHERE bank_line_id = p_line_id;

    IF v_voucher_number IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'No voucher record found for this receipt');
    END IF;

    SELECT * INTO v_config FROM public.bank_reco_company_config LIMIT 1;
    IF v_config.id IS NULL THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'MISSING_COMPANY_CONFIG',
            'error', 'No company config found');
    END IF;

    -- NOTE: tally_voucher_id is intentionally LEFT IN PLACE. Middleware uses
    -- it as a hint when re-POSTing with the same REMOTEID.

    INSERT INTO public.tally_sync_queue (entity_type, entity_id, operation, payload)
    VALUES (
        'receipt', p_line_id, 'resync',
        jsonb_build_object(
            'line_id',             p_line_id,
            'customer_id',         v_line.matched_customer_id,
            'voucher_number',      v_voucher_number,
            'existing_tally_voucher_id', v_tally_voucher_id,
            'bank_account_ledger', v_config.bank_account_ledger,
            'tds_ledger',          v_config.tds_194c_ledger,
            'allocations',         v_line.matched_allocations,
            'tds_amount',          v_line.tds_amount,
            'credit_amount',       v_line.credit,
            'tally_company',       v_config.tally_company
        )
    ) RETURNING id INTO v_queue_id;

    UPDATE public.bank_statement_lines SET
        status              = 'queued',
        tally_sync_queue_id = v_queue_id,
        review_note         = format('resynced at %s', now()::text)
    WHERE id = p_line_id;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'queue_id',       v_queue_id,
            'voucher_number', v_voucher_number,
            'operation',      'resync'
        )
    );
END;
$$;


CREATE FUNCTION public.retry_auto_invoice_generation(p_gr_id uuid, p_force_retry boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_error_record RECORD;
      v_retry_result JSONB;
      v_max_retries INTEGER := 3;
      v_dispatch_id UUID;
  BEGIN
      -- Get latest unresolved error for this GRN
      SELECT * INTO v_error_record
      FROM auto_invoice_errors
      WHERE gr_id = p_gr_id
      AND resolved_at IS NULL
      ORDER BY created_at DESC
      LIMIT 1;

      -- If no unresolved errors found, return early
      IF NOT FOUND THEN
          RETURN jsonb_build_object(
              'success', false,
              'error', 'No unresolved auto-invoice errors found for this GRN',
              'gr_id', p_gr_id
          );
      END IF;

      -- Check retry limits
      IF v_error_record.retry_count >= v_max_retries AND NOT p_force_retry THEN
          RETURN jsonb_build_object(
              'success', false,
              'error', 'Maximum retry attempts exceeded',
              'retry_count', v_error_record.retry_count,
              'max_retries', v_max_retries,
              'gr_id', p_gr_id
          );
      END IF;

      -- Find a dispatch that references this GRN to trigger auto-invoice generation
      SELECT dt.disp_id INTO v_dispatch_id
      FROM dispatch_trl dt
      WHERE dt.gr_id = p_gr_id
      LIMIT 1;

      -- If no dispatch found, cannot retry
      IF v_dispatch_id IS NULL THEN
          RETURN jsonb_build_object(
              'success', false,
              'error', 'No dispatch found for this GRN to retry auto-invoice generation',
              'gr_id', p_gr_id
          );
      END IF;

      -- Increment retry count
      UPDATE auto_invoice_errors
      SET retry_count = retry_count + 1
      WHERE id = v_error_record.id;

      -- Attempt auto-invoice generation using dispatch
      SELECT auto_generate_invoice_for_dispatch(v_dispatch_id) INTO v_retry_result;

      -- If successful, the auto_generate_invoice_for_dispatch function will handle resolution
      IF v_retry_result->>'success' = 'true' THEN
          RETURN jsonb_build_object(
              'success', true,
              'invoice_id', v_retry_result->>'invoice_id',
              'invoice_number', v_retry_result->>'invoice_number',
              'gr_id', p_gr_id,
              'retry_count', v_error_record.retry_count + 1,
              'message', 'Invoice generated successfully after retry'
          );
      ELSE
          -- Log new error details in existing error record
          UPDATE auto_invoice_errors
          SET error_details = COALESCE(error_details, '{}')::jsonb ||
                             jsonb_build_object(
                                 'retry_attempt', v_error_record.retry_count + 1,
                                 'retry_error', v_retry_result->>'error',
                                 'retry_timestamp', NOW(),
                                 'dispatch_used_for_retry', v_dispatch_id
                             )
          WHERE id = v_error_record.id;

          RETURN jsonb_build_object(
              'success', false,
              'error', 'Retry failed: ' || (v_retry_result->>'error'),
              'retry_count', v_error_record.retry_count + 1,
              'original_error', v_error_record.error_message,
              'gr_id', p_gr_id
          );
      END IF;
  END;
  $$;


CREATE FUNCTION public.retry_failed_receipt(p_line_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_line       public.bank_statement_lines;
    v_queue_id   uuid;
BEGIN
    SELECT * INTO v_line FROM public.bank_statement_lines WHERE id = p_line_id FOR UPDATE;
    IF v_line.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Receipt not found');
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM public.bank_statements bs
        WHERE bs.id = v_line.statement_id AND bs.account_number = 'MANUAL'
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Not a manual receipt');
    END IF;

    IF v_line.status != 'failed' THEN
        RETURN jsonb_build_object('success', false, 'error',
            format('Cannot retry receipt with status "%s" (only "failed" can be retried)', v_line.status));
    END IF;

    v_queue_id := v_line.tally_sync_queue_id;
    IF v_queue_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'No queue item to retry');
    END IF;

    UPDATE public.tally_sync_queue
    SET status        = 'pending',
        retry_count   = 0,
        error_message = NULL,
        next_retry_at = NULL,
        locked_by     = NULL,
        locked_at     = NULL
    WHERE id = v_queue_id;

    UPDATE public.bank_statement_lines
    SET status      = 'queued',
        review_note = CASE
            WHEN review_note IS NULL OR review_note = ''
                THEN format('retried at %s', now()::text)
            ELSE review_note || format(' | retried at %s', now()::text)
        END
    WHERE id = p_line_id;

    RETURN jsonb_build_object('success', true, 'data', jsonb_build_object('queue_id', v_queue_id));
END;
$$;


CREATE FUNCTION public.safe_delete_customer(p_customer_id uuid, p_permanent boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_customer_name VARCHAR(100);
    v_grn_count INTEGER;
    v_dispatch_count INTEGER;
    v_invoice_count INTEGER;
    v_active_stock_count INTEGER;
    v_current_user_id UUID;
    v_user_profile_id UUID;
BEGIN
    -- Get current auth user
    SELECT auth.uid() INTO v_current_user_id;

    IF v_current_user_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', 'Authentication required'
        );
    END IF;

    -- Look up user_profiles.id from auth_user_id (for FK constraint)
    SELECT id INTO v_user_profile_id
    FROM user_profiles
    WHERE auth_user_id = v_current_user_id;

    -- Check if customer exists and is not already deleted
    SELECT name INTO v_customer_name
    FROM customers
    WHERE id = p_customer_id AND deleted_at IS NULL;

    IF v_customer_name IS NULL THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', 'Customer not found or already deleted'
        );
    END IF;

    -- Check for active stock (items with stock > 0)
    SELECT COUNT(*) INTO v_active_stock_count
    FROM goodsreceived_trl grt
    JOIN goodsreceived gr ON gr.id = grt.gr_id
    WHERE gr.customer_id = p_customer_id
      AND gr.deleted_at IS NULL
      AND grt.stock > 0;

    IF v_active_stock_count > 0 THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', format('Cannot deactivate customer "%s". Customer has %s item(s) with active stock. Please dispatch all stock first.',
                v_customer_name, v_active_stock_count),
            'active_stock_count', v_active_stock_count
        );
    END IF;

    -- Check for related records
    SELECT
        COUNT(DISTINCT gr.id),
        COUNT(DISTINCT d.id),
        COUNT(DISTINCT i.id)
    INTO v_grn_count, v_dispatch_count, v_invoice_count
    FROM customers c
    LEFT JOIN goodsreceived gr ON gr.customer_id = c.id AND gr.deleted_at IS NULL
    LEFT JOIN dispatch d ON d.customer_id = c.id AND d.deleted_at IS NULL
    LEFT JOIN invoice i ON i.customer_id = c.id AND i.deleted_at IS NULL
    WHERE c.id = p_customer_id;

    -- If permanent delete requested and has relationships, block it
    IF p_permanent AND (v_grn_count > 0 OR v_dispatch_count > 0 OR v_invoice_count > 0) THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', format('Cannot permanently delete customer "%s". Has %s GRNs, %s dispatches, %s invoices. Use soft delete instead.',
                v_customer_name, v_grn_count, v_dispatch_count, v_invoice_count),
            'related_records', jsonb_build_object(
                'grn_count', v_grn_count,
                'dispatch_count', v_dispatch_count,
                'invoice_count', v_invoice_count
            )
        );
    END IF;

    -- Perform soft delete
    IF NOT p_permanent THEN
        UPDATE customers
        SET
            deleted_at = NOW(),
            deleted_by = v_user_profile_id,
            active = FALSE
        WHERE id = p_customer_id;

        RETURN jsonb_build_object(
            'success', TRUE,
            'message', format('Customer "%s" soft deleted successfully', v_customer_name),
            'delete_type', 'soft',
            'deleted_at', NOW(),
            'related_records', jsonb_build_object(
                'grn_count', v_grn_count,
                'dispatch_count', v_dispatch_count,
                'invoice_count', v_invoice_count
            )
        );
    ELSE
        -- Permanent delete (only if no relationships)
        DELETE FROM customers WHERE id = p_customer_id;

        RETURN jsonb_build_object(
            'success', TRUE,
            'message', format('Customer "%s" permanently deleted', v_customer_name),
            'delete_type', 'permanent'
        );
    END IF;
END;
$$;


CREATE FUNCTION public.safe_delete_dispatch(p_dispatch_id uuid, p_permanent boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_disp_no VARCHAR(50);
    v_invoice_count INTEGER;
    v_items_count INTEGER;
    v_current_user_id UUID;
BEGIN
    SELECT auth.uid() INTO v_current_user_id;

    IF v_current_user_id IS NULL THEN
        RETURN jsonb_build_object('success', FALSE, 'message', 'Authentication required');
    END IF;

    SELECT disp_no INTO v_disp_no
    FROM dispatch
    WHERE id = p_dispatch_id AND deleted_at IS NULL;

    IF v_disp_no IS NULL THEN
        RETURN jsonb_build_object('success', FALSE, 'message', 'Dispatch not found or already deleted');
    END IF;

    -- Check for invoices
    SELECT
        COUNT(DISTINCT it.invoice_id),
        COUNT(DISTINCT dt.id)
    INTO v_invoice_count, v_items_count
    FROM dispatch d
    LEFT JOIN dispatch_trl dt ON dt.disp_id = d.id
    LEFT JOIN invoice_trl it ON it.disp_trl_id = dt.id
    WHERE d.id = p_dispatch_id;

    IF v_invoice_count > 0 THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', format('Cannot delete dispatch "%s". Has %s invoices. Delete invoices first.', v_disp_no, v_invoice_count)
        );
    END IF;

    IF NOT p_permanent THEN
        UPDATE dispatch SET deleted_at = NOW(), deleted_by = v_current_user_id WHERE id = p_dispatch_id;
        RETURN jsonb_build_object('success', TRUE, 'message', format('Dispatch "%s" soft deleted', v_disp_no), 'delete_type', 'soft');
    ELSE
        DELETE FROM dispatch WHERE id = p_dispatch_id;
        RETURN jsonb_build_object('success', TRUE, 'message', format('Dispatch "%s" permanently deleted', v_disp_no), 'delete_type', 'permanent');
    END IF;
END;
$$;


CREATE FUNCTION public.safe_delete_grn(p_grn_id uuid, p_permanent boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_grn_no VARCHAR(50);
    v_dispatch_count INTEGER;
    v_invoice_count INTEGER;
    v_items_count INTEGER;
    v_current_user_id UUID;
BEGIN
    -- Get current user
    SELECT auth.uid() INTO v_current_user_id;

    IF v_current_user_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', 'Authentication required'
        );
    END IF;

    -- Check if GRN exists and is not already deleted
    SELECT gr_no INTO v_grn_no
    FROM goodsreceived
    WHERE id = p_grn_id AND deleted_at IS NULL;

    IF v_grn_no IS NULL THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', 'GRN not found or already deleted'
        );
    END IF;

    -- Check for related records
    SELECT
        COUNT(DISTINCT dt.disp_id),
        COUNT(DISTINCT it.invoice_id),
        COUNT(DISTINCT grt.id)
    INTO v_dispatch_count, v_invoice_count, v_items_count
    FROM goodsreceived gr
    LEFT JOIN goodsreceived_trl grt ON grt.gr_id = gr.id
    LEFT JOIN dispatch_trl dt ON dt.gr_id = gr.id
    LEFT JOIN invoice_trl it ON it.grn_item_id = grt.id
    WHERE gr.id = p_grn_id;

    -- If has dispatches or invoices, cannot delete
    IF v_dispatch_count > 0 OR v_invoice_count > 0 THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', format('Cannot delete GRN "%s". Has %s dispatches and %s invoices. These must be deleted first.',
                v_grn_no, v_dispatch_count, v_invoice_count),
            'related_records', jsonb_build_object(
                'dispatch_count', v_dispatch_count,
                'invoice_count', v_invoice_count,
                'items_count', v_items_count
            )
        );
    END IF;

    -- Perform soft delete
    IF NOT p_permanent THEN
        UPDATE goodsreceived
        SET
            deleted_at = NOW(),
            deleted_by = v_current_user_id
        WHERE id = p_grn_id;

        RETURN jsonb_build_object(
            'success', TRUE,
            'message', format('GRN "%s" soft deleted successfully', v_grn_no),
            'delete_type', 'soft',
            'deleted_at', NOW(),
            'items_count', v_items_count
        );
    ELSE
        -- Permanent delete (CASCADE will handle goodsreceived_trl and grn_images)
        DELETE FROM goodsreceived WHERE id = p_grn_id;

        RETURN jsonb_build_object(
            'success', TRUE,
            'message', format('GRN "%s" permanently deleted (including %s items)', v_grn_no, v_items_count),
            'delete_type', 'permanent'
        );
    END IF;
END;
$$;


CREATE FUNCTION public.safe_delete_invoice(p_invoice_id uuid, p_permanent boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_inv_no VARCHAR(50);
    v_payment_count INTEGER;
    v_items_count INTEGER;
    v_current_user_id UUID;
BEGIN
    SELECT auth.uid() INTO v_current_user_id;

    IF v_current_user_id IS NULL THEN
        RETURN jsonb_build_object('success', FALSE, 'message', 'Authentication required');
    END IF;

    SELECT inv_no INTO v_inv_no
    FROM invoice
    WHERE id = p_invoice_id AND deleted_at IS NULL;

    IF v_inv_no IS NULL THEN
        RETURN jsonb_build_object('success', FALSE, 'message', 'Invoice not found or already deleted');
    END IF;

    -- Check for payments
    SELECT
        COUNT(*),
        COUNT(DISTINCT it.id)
    INTO v_payment_count, v_items_count
    FROM invoice i
    LEFT JOIN payments p ON p.invoice_id = i.id
    LEFT JOIN invoice_trl it ON it.invoice_id = i.id
    WHERE i.id = p_invoice_id;

    IF v_payment_count > 0 THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', format('Cannot delete invoice "%s". Has %s payments. Delete payments first.', v_inv_no, v_payment_count)
        );
    END IF;

    IF NOT p_permanent THEN
        UPDATE invoice SET deleted_at = NOW(), deleted_by = v_current_user_id WHERE id = p_invoice_id;
        RETURN jsonb_build_object('success', TRUE, 'message', format('Invoice "%s" soft deleted', v_inv_no), 'delete_type', 'soft');
    ELSE
        DELETE FROM invoice WHERE id = p_invoice_id;
        RETURN jsonb_build_object('success', TRUE, 'message', format('Invoice "%s" permanently deleted', v_inv_no), 'delete_type', 'permanent');
    END IF;
END;
$$;


CREATE FUNCTION public.safe_disable_grn_trl_triggers() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    -- Only disable triggers that actually exist
    IF EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'trg_mark_stock_mvs_dirty_grn' AND tgrelid = 'goodsreceived_trl'::regclass) THEN
        ALTER TABLE goodsreceived_trl DISABLE TRIGGER trg_mark_stock_mvs_dirty_grn;
    END IF;
END;
$$;


CREATE FUNCTION public.safe_enable_grn_trl_triggers() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    -- Only enable triggers that actually exist
    IF EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'trg_mark_stock_mvs_dirty_grn' AND tgrelid = 'goodsreceived_trl'::regclass) THEN
        ALTER TABLE goodsreceived_trl ENABLE TRIGGER trg_mark_stock_mvs_dirty_grn;
    END IF;
END;
$$;


CREATE FUNCTION public.save_grn(p_gr_no character varying, p_date timestamp with time zone, p_customer_id uuid, p_customer_name character varying, p_sender_id uuid DEFAULT NULL::uuid, p_sender_name character varying DEFAULT NULL::character varying, p_supervisor_id uuid DEFAULT NULL::uuid, p_supervisor_name character varying DEFAULT NULL::character varying, p_registration character varying DEFAULT NULL::character varying, p_note character varying DEFAULT NULL::character varying, p_leon boolean DEFAULT false, p_pricing_mode character varying DEFAULT NULL::character varying, p_items jsonb DEFAULT '[]'::jsonb, p_images jsonb DEFAULT '[]'::jsonb, p_idempotency_key text DEFAULT NULL::text, p_duration_mode character varying DEFAULT 'legacy'::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET jit TO 'off'
    AS $$
  DECLARE
      v_user_id uuid;
      v_user_profile_id uuid;
      v_user_role text;
      v_grn_id uuid;
      v_item_id uuid;
      v_item jsonb;
      v_image jsonb;
      v_image_id uuid;
      v_item_ids uuid[] := '{}';
      v_image_ids uuid[] := '{}';
      v_items_created int := 0;
      v_images_saved int := 0;
      v_item_index int;
      v_item_mapping jsonb := '[]'::jsonb;
      v_cached_response jsonb;
      v_result jsonb;
  BEGIN
      -- IDEMPOTENCY CHECK: Return cached response if key exists
      IF p_idempotency_key IS NOT NULL THEN
          SELECT response INTO v_cached_response
          FROM idempotency_keys
          WHERE idempotency_key = p_idempotency_key
            AND rpc_function = 'save_grn'
            AND expires_at > now();

          IF v_cached_response IS NOT NULL THEN
              RETURN v_cached_response || jsonb_build_object('idempotent', true);
          END IF;
      END IF;

      v_user_id := auth.uid();

      IF v_user_id IS NULL THEN
          RETURN jsonb_build_object(
              'success', false,
              'message', 'Authentication required'
          );
      END IF;

      SELECT id, role INTO v_user_profile_id, v_user_role
      FROM user_profiles
      WHERE auth_user_id = v_user_id;

      IF v_user_profile_id IS NULL THEN
          RETURN jsonb_build_object(
              'success', false,
              'message', 'User profile not found'
          );
      END IF;

      IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
          RETURN jsonb_build_object(
              'success', false,
              'message', 'Insufficient permissions. Only admin and supervisor can create GRNs'
          );
      END IF;

      IF p_gr_no IS NULL OR p_date IS NULL OR p_customer_id IS NULL THEN
          RETURN jsonb_build_object(
              'success', false,
              'message', 'Missing required parameters: gr_no, date, and customer_id are required'
          );
      END IF;

      IF EXISTS (SELECT 1 FROM goodsreceived WHERE gr_no = p_gr_no) THEN
          RETURN jsonb_build_object(
              'success', false,
              'message', 'GRN number already exists: ' || p_gr_no
          );
      END IF;

      IF jsonb_array_length(p_items) = 0 THEN
          RETURN jsonb_build_object(
              'success', false,
              'message', 'At least one item is required'
          );
      END IF;

      BEGIN
          INSERT INTO goodsreceived (
              gr_no,
              date,
              customer_id,
              customer_name,
              sender_id,
              sender_name,
              supervisor_id,
              supervisor_name,
              registration,
              note,
              leon,
              pricing_mode,
              duration_mode,
              out_of_stock,
              invoiced,
              created_by,
              updated_by
          ) VALUES (
              p_gr_no,
              p_date,
              p_customer_id,
              p_customer_name,
              p_sender_id,
              p_sender_name,
              p_supervisor_id,
              p_supervisor_name,
              p_registration,
              p_note,
              COALESCE(p_leon, false),
              p_pricing_mode,
              COALESCE(p_duration_mode, 'legacy'),
              false,
              false,
              v_user_profile_id,
              v_user_profile_id
          ) RETURNING id INTO v_grn_id;

          v_item_index := 0;
          FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
          LOOP
              IF v_item->>'item_name' IS NULL OR (v_item->>'qty')::int IS NULL THEN
                  RAISE EXCEPTION 'Invalid item data: item_name and qty are required for item at index %', v_item_index;
              END IF;

              INSERT INTO goodsreceived_trl (
                  gr_id,
                  item_id,
                  item_name,
                  packaging,
                  qty,
                  stock,
                  weight,
                  rack,
                  package_mark
              ) VALUES (
                  v_grn_id,
                  (v_item->>'item_id')::uuid,
                  v_item->>'item_name',
                  v_item->>'packaging',
                  (v_item->>'qty')::int,
                  (v_item->>'qty')::int,
                  COALESCE((v_item->>'weight')::int, 0),
                  v_item->>'rack',
                  v_item->>'package_mark'
              ) RETURNING id INTO v_item_id;

              v_item_ids := array_append(v_item_ids, v_item_id);
              v_items_created := v_items_created + 1;

              v_item_mapping := v_item_mapping || jsonb_build_object(
                  'index', v_item_index,
                  'item_id', v_item_id,
                  'item_name', v_item->>'item_name'
              );

              v_item_index := v_item_index + 1;
          END LOOP;

          IF jsonb_array_length(p_images) > 0 THEN
              FOR v_image IN SELECT * FROM jsonb_array_elements(p_images)
              LOOP
                  IF v_image->>'storage_path' IS NULL OR v_image->>'image_type' IS NULL THEN
                      RAISE EXCEPTION 'Invalid image data: storage_path and image_type are required';
                  END IF;

                  v_image_id := gen_random_uuid();

                  IF v_image->>'image_type' = 'item' THEN
                      IF v_image->>'item_index' IS NOT NULL THEN
                          IF (v_image->>'item_index')::int < 0 OR
                             (v_image->>'item_index')::int >= jsonb_array_length(p_items) THEN
                              RAISE EXCEPTION 'Invalid item_index % for image. Must be between 0 and %',
                                  v_image->>'item_index', jsonb_array_length(p_items) - 1;
                          END IF;

                          v_item_id := v_item_ids[(v_image->>'item_index')::int + 1];

                          INSERT INTO grn_images (
                              id, grn_id, grn_item_id, image_type, storage_path,
                              original_filename, file_size, mime_type, uploaded_by
                          ) VALUES (
                              v_image_id, v_grn_id, v_item_id, v_image->>'image_type',
                              v_image->>'storage_path',
                              COALESCE(v_image->>'original_filename', 'unknown'),
                              COALESCE((v_image->>'file_size')::int, 0),
                              COALESCE(v_image->>'mime_type', 'image/jpeg'),
                              v_user_profile_id
                          );
                      ELSIF v_image->>'grn_item_id' IS NOT NULL THEN
                          INSERT INTO grn_images (
                              id, grn_id, grn_item_id, image_type, storage_path,
                              original_filename, file_size, mime_type, uploaded_by
                          ) VALUES (
                              v_image_id, v_grn_id, (v_image->>'grn_item_id')::uuid,
                              v_image->>'image_type', v_image->>'storage_path',
                              COALESCE(v_image->>'original_filename', 'unknown'),
                              COALESCE((v_image->>'file_size')::int, 0),
                              COALESCE(v_image->>'mime_type', 'image/jpeg'),
                              v_user_profile_id
                          );
                      ELSE
                          RAISE EXCEPTION 'Item images must have either item_index or grn_item_id';
                      END IF;
                  ELSE
                      INSERT INTO grn_images (
                          id, grn_id, grn_item_id, image_type, storage_path,
                          original_filename, file_size, mime_type, uploaded_by
                      ) VALUES (
                          v_image_id, v_grn_id, NULL, v_image->>'image_type',
                          v_image->>'storage_path',
                          COALESCE(v_image->>'original_filename', 'unknown'),
                          COALESCE((v_image->>'file_size')::int, 0),
                          COALESCE(v_image->>'mime_type', 'image/jpeg'),
                          v_user_profile_id
                      );
                  END IF;

                  v_image_ids := array_append(v_image_ids, v_image_id);
                  v_images_saved := v_images_saved + 1;
              END LOOP;
          END IF;

          v_result := jsonb_build_object(
              'success', true,
              'message', 'GRN created successfully',
              'data', jsonb_build_object(
                  'grn_id', v_grn_id,
                  'gr_no', p_gr_no,
                  'items_created', v_items_created,
                  'images_saved', v_images_saved,
                  'item_ids', v_item_ids,
                  'image_ids', v_image_ids,
                  'item_mapping', v_item_mapping
              )
          );

          IF p_idempotency_key IS NOT NULL THEN
              INSERT INTO idempotency_keys (idempotency_key, rpc_function, response, created_by)
              VALUES (p_idempotency_key, 'save_grn', v_result, v_user_profile_id)
              ON CONFLICT (idempotency_key) DO NOTHING;
          END IF;

          RETURN v_result;

      EXCEPTION
          WHEN foreign_key_violation THEN
              RETURN jsonb_build_object(
                  'success', false,
                  'message', 'Invalid reference: ' || SQLERRM
              );
          WHEN unique_violation THEN
              RETURN jsonb_build_object(
                  'success', false,
                  'message', 'Duplicate value: ' || SQLERRM
              );
          WHEN OTHERS THEN
              RETURN jsonb_build_object(
                  'success', false,
                  'message', 'Error creating GRN: ' || SQLERRM
              );
      END;
  END;
  $$;


CREATE FUNCTION public.save_invoice(p_invoice_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_invoice_id UUID;
    v_invoice_header JSONB;
    v_invoice_items JSONB;
    v_totals JSONB;
    v_user_id UUID;
    v_created_at TIMESTAMPTZ := NOW();
    v_is_auto_generated BOOLEAN;
    v_items_count INTEGER;
    v_duration_mode text;
    v_invoice_number_text text;
    v_invoice_number_int integer;
    v_fin_year integer;
BEGIN
    SELECT id INTO v_user_id FROM user_profiles WHERE auth_user_id = auth.uid();

    v_invoice_header := COALESCE(p_invoice_data->'data'->'header', p_invoice_data->'header', '{}'::jsonb);
    v_invoice_items := COALESCE(p_invoice_data->'data'->'items', p_invoice_data->'data'->'rows', p_invoice_data->'items', p_invoice_data->'rows', '[]'::jsonb);
    v_totals := COALESCE(p_invoice_data->'data'->'totals', p_invoice_data->'totals', '{}'::jsonb);
    v_duration_mode := public.validate_invoice_duration_mode(COALESCE(p_invoice_data->>'duration_mode', v_invoice_header->>'duration_mode'));

    v_invoice_number_text := COALESCE(v_invoice_header->>'invoice_number', p_invoice_data->>'inv_no');
    v_invoice_number_int := COALESCE(
        NULLIF(p_invoice_data->>'inv_no', '')::integer,
        NULLIF(REGEXP_REPLACE(COALESCE(v_invoice_number_text, ''), '^.*-([0-9]+)$', '\1'), '')::integer
    );
    v_fin_year := COALESCE(
        NULLIF(p_invoice_data->>'inv_fin_year', '')::integer,
        NULLIF(SPLIT_PART(COALESCE(v_invoice_header->>'financial_year', ''), '-', 1), '')::integer,
        CASE WHEN EXTRACT(MONTH FROM CURRENT_DATE) >= 4 THEN EXTRACT(YEAR FROM CURRENT_DATE)::integer ELSE EXTRACT(YEAR FROM CURRENT_DATE)::integer - 1 END
    );

    v_is_auto_generated := COALESCE(
        (p_invoice_data->>'is_auto_generated')::boolean,
        (v_invoice_header->>'is_auto_generated')::boolean,
        false
    );

    INSERT INTO invoice (
        inv_fin_year, inv_no, gr_id, gr_no,
        customer_id, customer_name, inv_date,
        labour, tax_amount, total, discount,
        one_time_charge, notes, created_by, is_auto_generated, duration_mode
    ) VALUES (
        v_fin_year,
        v_invoice_number_int,
        COALESCE(v_invoice_header->>'grn_id', p_invoice_data->>'gr_id')::UUID,
        COALESCE(v_invoice_header->>'grn_no', p_invoice_data->>'gr_no'),
        COALESCE(v_invoice_header->>'customer_id', p_invoice_data->>'customer_id')::UUID,
        COALESCE(v_invoice_header->>'customer_name', p_invoice_data->>'customer_name'),
        COALESCE((v_invoice_header->>'invoice_date')::TIMESTAMPTZ, (p_invoice_data->>'inv_date')::TIMESTAMPTZ, v_created_at),
        COALESCE(NULLIF(p_invoice_data->>'labour', '')::NUMERIC(12,2), 0),
        CEIL(COALESCE(NULLIF(v_totals->>'tax', '')::NUMERIC(12,2), NULLIF(v_totals->>'total_tax', '')::NUMERIC(12,2), NULLIF(p_invoice_data->>'tax_amount', '')::NUMERIC(12,2), 0)),
        CEIL(COALESCE(NULLIF(v_totals->>'grand_total', '')::NUMERIC(12,2), NULLIF(v_totals->>'total', '')::NUMERIC(12,2), NULLIF(p_invoice_data->>'total', '')::NUMERIC(12,2), 0)),
        COALESCE(NULLIF(p_invoice_data->>'discount', '')::NUMERIC(12,2), 0),
        COALESCE((p_invoice_data->>'one_time_charge')::boolean, false),
        CASE WHEN v_is_auto_generated THEN 'Auto-generated invoice' ELSE COALESCE(p_invoice_data->>'notes', 'Manual invoice') END,
        v_user_id,
        v_is_auto_generated,
        v_duration_mode
    ) RETURNING id INTO v_invoice_id;

    INSERT INTO invoice_trl (invoice_id, disp_trl_id, duration, no_of_days, charge, tax, labour_rate)
    SELECT
        v_invoice_id,
        COALESCE(item->>'disp_trl_id', item->>'dispatches_items_id', item->>'dispatch_item_id')::UUID,
        d.duration,
        d.no_of_days,
        COALESCE(NULLIF(item->>'charge', '')::NUMERIC(12,2), NULLIF(item->>'unit_price', '')::NUMERIC(12,2)),
        COALESCE(NULLIF(item->>'tax', '')::NUMERIC(12,2), NULLIF(item->>'tax_percent', '')::NUMERIC(12,2)),
        (item->>'labour_rate')::NUMERIC
    FROM jsonb_array_elements(v_invoice_items) AS item
    JOIN dispatch_trl dt ON dt.id = COALESCE(item->>'disp_trl_id', item->>'dispatches_items_id', item->>'dispatch_item_id')::UUID
    JOIN dispatch disp ON disp.id = dt.disp_id
    JOIN goodsreceived gr ON gr.id = dt.gr_id
    CROSS JOIN LATERAL public.calculate_invoice_duration(gr.date::date, disp.disp_date::date, v_duration_mode) d;

    GET DIAGNOSTICS v_items_count = ROW_COUNT;

    UPDATE goodsreceived
    SET invoiced = true
    WHERE id = COALESCE(v_invoice_header->>'grn_id', p_invoice_data->>'gr_id')::UUID;

    RETURN jsonb_build_object(
        'success', true,
        'invoice_id', v_invoice_id,
        'invoice_no', v_invoice_number_text,
        'duration_mode', v_duration_mode,
        'is_auto_generated', v_is_auto_generated,
        'items_count', v_items_count,
        'message', 'Invoice saved successfully'
    );
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Database error: ' || SQLERRM || ' (SQLState: ' || SQLSTATE || ')'
        );
END;
$_$;


CREATE FUNCTION public.save_invoice(p_invoice_id uuid, p_invoice_data jsonb, p_invoice_items jsonb[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_validation_result JSONB;
BEGIN
    -- Step 1: Validate invoice data
    v_validation_result := validate_invoice_input(p_invoice_data);
    IF NOT (v_validation_result->>'valid')::BOOLEAN THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'Invalid invoice data',
            'validation_errors', v_validation_result->'errors'
        );
    END IF;

    -- Step 2: Validate invoice items
    v_validation_result := validate_invoice_items(p_invoice_items);
    IF NOT (v_validation_result->>'valid')::BOOLEAN THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'Invalid invoice items',
            'validation_errors', v_validation_result->'errors'
        );
    END IF;

    -- Step 3: Call original function (now named _internal)
    RETURN save_invoice_internal(p_invoice_id, p_invoice_data, p_invoice_items);
END;
$$;


CREATE FUNCTION public.save_invoice_internal(p_invoice_id uuid, p_invoice_data jsonb, p_invoice_items jsonb[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_id UUID;
    v_new_gr_id UUID;
    v_invoice_number_for_resolution VARCHAR(20);
    v_invoice_creation_time TIMESTAMPTZ;
    v_invoice_date TIMESTAMPTZ;
    v_resolved_errors_count INTEGER := 0;
    v_new_items_count INTEGER := 0;
    v_final_invoice_id UUID;
    v_is_auto_generated BOOLEAN;
    v_duration_mode text;
    v_discount NUMERIC(12,2) := COALESCE(NULLIF(p_invoice_data->>'discount', '')::NUMERIC(12,2), 0::NUMERIC(12,2));
    v_function_version TEXT := 'save_invoice_v20260503_duration_mode';
BEGIN
    SELECT id INTO v_user_id FROM user_profiles WHERE auth_user_id = auth.uid();
    v_new_gr_id := (p_invoice_data->>'gr_id')::uuid;
    v_invoice_creation_time := NOW();
    v_invoice_date := COALESCE((p_invoice_data->>'inv_date')::TIMESTAMPTZ, NOW());
    v_invoice_number_for_resolution := (p_invoice_data->>'inv_no');
    v_is_auto_generated := COALESCE((p_invoice_data->>'is_auto_generated')::boolean, false);
    v_duration_mode := public.validate_invoice_duration_mode(p_invoice_data->>'duration_mode');

    IF p_invoice_id IS NOT NULL THEN
        INSERT INTO invoice (
            id, inv_fin_year, inv_no, gr_id, gr_no,
            customer_id, customer_name, inv_date,
            labour, tax_amount, total, discount,
            one_time_charge, notes, created_by, is_auto_generated, duration_mode
        ) VALUES (
            p_invoice_id,
            (p_invoice_data->>'inv_fin_year')::integer,
            (p_invoice_data->>'inv_no')::integer,
            v_new_gr_id,
            p_invoice_data->>'gr_no',
            (p_invoice_data->>'customer_id')::uuid,
            p_invoice_data->>'customer_name',
            v_invoice_date,
            (p_invoice_data->>'labour')::NUMERIC(12,2),
            CEIL((p_invoice_data->>'tax_amount')::NUMERIC(12,2)),
            CEIL((p_invoice_data->>'total')::NUMERIC(12,2)),
            v_discount,
            COALESCE((p_invoice_data->>'one_time_charge')::boolean, false),
            p_invoice_data->>'notes',
            v_user_id,
            v_is_auto_generated,
            v_duration_mode
        );
        v_final_invoice_id := p_invoice_id;
    ELSE
        INSERT INTO invoice (
            inv_fin_year, inv_no, gr_id, gr_no,
            customer_id, customer_name, inv_date,
            labour, tax_amount, total, discount,
            one_time_charge, notes, created_by, is_auto_generated, duration_mode
        ) VALUES (
            (p_invoice_data->>'inv_fin_year')::integer,
            (p_invoice_data->>'inv_no')::integer,
            v_new_gr_id,
            p_invoice_data->>'gr_no',
            (p_invoice_data->>'customer_id')::uuid,
            p_invoice_data->>'customer_name',
            v_invoice_date,
            (p_invoice_data->>'labour')::NUMERIC(12,2),
            CEIL((p_invoice_data->>'tax_amount')::NUMERIC(12,2)),
            CEIL((p_invoice_data->>'total')::NUMERIC(12,2)),
            v_discount,
            COALESCE((p_invoice_data->>'one_time_charge')::boolean, false),
            p_invoice_data->>'notes',
            v_user_id,
            v_is_auto_generated,
            v_duration_mode
        ) RETURNING id INTO v_final_invoice_id;
    END IF;

    INSERT INTO invoice_trl (invoice_id, disp_trl_id, duration, no_of_days, charge, tax, labour_rate)
    SELECT
        v_final_invoice_id,
        (item->>'disp_trl_id')::uuid,
        d.duration,
        d.no_of_days,
        COALESCE(NULLIF(item->>'charge', '')::NUMERIC(12,2), NULLIF(item->>'unit_price', '')::NUMERIC(12,2)),
        COALESCE(NULLIF(item->>'tax', '')::NUMERIC(12,2), NULLIF(item->>'tax_percent', '')::NUMERIC(12,2)),
        (item->>'labour_rate')::numeric
    FROM unnest(p_invoice_items) AS item
    JOIN dispatch_trl dt ON dt.id = (item->>'disp_trl_id')::uuid
    JOIN dispatch disp ON disp.id = dt.disp_id
    JOIN goodsreceived gr ON gr.id = dt.gr_id
    CROSS JOIN LATERAL public.calculate_invoice_duration(gr.date::date, disp.disp_date::date, v_duration_mode) d;

    GET DIAGNOSTICS v_new_items_count = ROW_COUNT;

    UPDATE goodsreceived SET invoiced = true WHERE id = v_new_gr_id;

    UPDATE auto_invoice_errors
    SET
        resolved_at = v_invoice_creation_time,
        resolved_invoice_id = v_final_invoice_id,
        error_details = COALESCE(error_details, '{}')::jsonb ||
                       jsonb_build_object(
                           'resolution_type', 'manual_invoice_created',
                           'resolution_notes', 'Invoice created manually through save_invoice',
                           'invoice_id', v_final_invoice_id,
                           'invoice_number', v_invoice_number_for_resolution,
                           'invoice_date', v_invoice_date,
                           'gr_id', v_new_gr_id
                       )
    WHERE gr_id = v_new_gr_id
    AND resolved_at IS NULL;

    GET DIAGNOSTICS v_resolved_errors_count = ROW_COUNT;

    RETURN jsonb_build_object(
        'success', true,
        'invoice_id', v_final_invoice_id,
        'invoice_number', v_invoice_number_for_resolution,
        'items_count', v_new_items_count,
        'resolved_errors_count', v_resolved_errors_count,
        'is_auto_generated', v_is_auto_generated,
        'duration_mode', v_duration_mode,
        'function_version', v_function_version
    );
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', SQLERRM,
        'error_code', SQLSTATE,
        'function_version', v_function_version
    );
END;
$$;


CREATE FUNCTION public.save_tally_contra_voucher(p_contra_id uuid, p_tally_voucher_id text, p_voucher_number text, p_voucher_date date, p_tally_company text DEFAULT public.get_tally_company()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_voucher       public.tally_contra_vouchers;
    v_existing_vid  TEXT;
BEGIN
    SELECT * INTO v_voucher
    FROM public.tally_contra_vouchers
    WHERE id = p_contra_id;

    IF v_voucher.id IS NULL THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'CONTRA_NOT_FOUND',
            'error', 'Contra voucher not found');
    END IF;

    -- Company mismatch: reject so a mis-routed callback can't overwrite a row
    -- belonging to a different Tally company.
    IF v_voucher.tally_company IS DISTINCT FROM p_tally_company THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'COMPANY_MISMATCH',
            'error', format(
                'Callback tally_company "%s" does not match contra row tally_company "%s"',
                p_tally_company, v_voucher.tally_company));
    END IF;

    -- Idempotency: if already reconciled with a Tally ID, the prior callback
    -- succeeded. Don't re-apply.
    IF v_voucher.status = 'reconciled' AND v_voucher.tally_voucher_id IS NOT NULL THEN
        RETURN jsonb_build_object(
            'success', true,
            'already_saved', true,
            'tally_voucher_id', v_voucher.tally_voucher_id
        );
    END IF;

    UPDATE public.tally_contra_vouchers SET
        tally_voucher_id = p_tally_voucher_id,
        voucher_number   = p_voucher_number,
        voucher_date     = p_voucher_date,
        status           = 'reconciled'
    WHERE id = p_contra_id;

    RETURN jsonb_build_object(
        'success', true,
        'tally_voucher_id', p_tally_voucher_id,
        'voucher_number', p_voucher_number
    );
END;
$$;


CREATE FUNCTION public.save_tally_receipt_voucher(p_line_id uuid, p_tally_voucher_id text, p_voucher_number text, p_voucher_date date, p_tally_company text DEFAULT public.get_tally_company()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_line          public.bank_statement_lines;
    v_existing_vid  TEXT;
    v_alloc         JSONB;
    v_inv_id        UUID;
    v_amount        NUMERIC(14,2);
    v_cust_name     TEXT;
    v_alloc_idx     INT := 0;
BEGIN
    SELECT * INTO v_line FROM public.bank_statement_lines WHERE id = p_line_id;

    IF v_line.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Line not found');
    END IF;

    -- Idempotency: if already reconciled AND we already stored a tally_voucher_id,
    -- the previous call succeeded. Return success without re-inserting payments.
    IF v_line.status = 'reconciled' THEN
        SELECT tally_voucher_id INTO v_existing_vid
        FROM public.tally_receipt_vouchers
        WHERE bank_line_id = p_line_id;

        IF v_existing_vid IS NOT NULL THEN
            RETURN jsonb_build_object(
                'success', true,
                'already_saved', true,
                'tally_voucher_id', v_existing_vid
            );
        END IF;
    END IF;

    -- Step 1: upsert the voucher record (carries the Tally ID + final state)
    INSERT INTO public.tally_receipt_vouchers (
        bank_line_id, voucher_number, voucher_date, customer_id,
        bank_account_ledger, amount_received, tds_amount,
        tally_voucher_id, tally_company, allocations
    )
    SELECT
        p_line_id,
        p_voucher_number,
        p_voucher_date,
        v_line.matched_customer_id,
        cfg.bank_account_ledger,
        v_line.credit,
        COALESCE(v_line.tds_amount, 0),
        p_tally_voucher_id,
        p_tally_company,
        COALESCE(v_line.matched_allocations, '[]'::JSONB)
    FROM public.bank_reco_company_config cfg
    WHERE cfg.tally_company = p_tally_company
    ON CONFLICT (bank_line_id)
    DO UPDATE SET
        tally_voucher_id = EXCLUDED.tally_voucher_id,
        voucher_number   = EXCLUDED.voucher_number,
        voucher_date     = EXCLUDED.voucher_date;

    -- Step 2: customer display name for payment rows
    SELECT COALESCE(c.name, c.contact_person) INTO v_cust_name
    FROM public.customers c WHERE c.id = v_line.matched_customer_id;

    -- Step 3: insert per-allocation payment rows (idempotent via payment_no UNIQUE)
    FOR v_alloc IN SELECT * FROM jsonb_array_elements(COALESCE(v_line.matched_allocations, '[]'::JSONB))
    LOOP
        v_alloc_idx := v_alloc_idx + 1;
        v_inv_id    := (v_alloc->>'invoice_id')::UUID;
        v_amount    := (v_alloc->>'amount')::NUMERIC(14,2);

        INSERT INTO public.payments (
            payment_no, payment_date, customer_id, customer_name,
            amount, payment_mode, online_ref, invoice_id, note
        ) VALUES (
            p_voucher_number || '-' || v_alloc_idx::TEXT,
            v_line.tran_date,
            v_line.matched_customer_id,
            v_cust_name,
            v_amount,
            'ONLINE',
            p_tally_voucher_id,
            v_inv_id,
            'Bank reconciliation receipt ' || p_voucher_number
        )
        ON CONFLICT (payment_no) DO NOTHING;
    END LOOP;

    -- Step 4 (LAST): flip status to 'reconciled' only after voucher + payments exist
    UPDATE public.bank_statement_lines SET status = 'reconciled' WHERE id = p_line_id;

    RETURN jsonb_build_object('success', true);
END;
$$;


CREATE FUNCTION public.save_tally_voucher(p_invoice_id uuid, p_tally_voucher_id character varying DEFAULT NULL::character varying, p_voucher_number character varying DEFAULT NULL::character varying, p_voucher_type character varying DEFAULT 'Sales'::character varying, p_voucher_date date DEFAULT NULL::date, p_tally_company character varying DEFAULT public.get_tally_company(), p_amount numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_inv public.invoice;
BEGIN
    SELECT * INTO v_inv FROM public.invoice WHERE id = p_invoice_id;
    IF v_inv.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invoice not found');
    END IF;

    INSERT INTO public.tally_vouchers (
        invoice_id, tally_voucher_id, voucher_number, voucher_type,
        voucher_date, tally_company, amount
    ) VALUES (
        p_invoice_id,
        p_tally_voucher_id,
        COALESCE(p_voucher_number, 'GCS/' || v_inv.inv_fin_year || '/' || v_inv.inv_no),
        p_voucher_type,
        COALESCE(p_voucher_date, v_inv.inv_date::date),
        p_tally_company,
        COALESCE(p_amount, v_inv.total)
    )
    ON CONFLICT (invoice_id, tally_company)
    DO UPDATE SET
        tally_voucher_id = EXCLUDED.tally_voucher_id,
        voucher_number   = EXCLUDED.voucher_number,
        voucher_date     = EXCLUDED.voucher_date,
        amount           = EXCLUDED.amount,
        synced_at        = now(),
        last_verified_at = now();

    RETURN jsonb_build_object('success', true);
END;
$$;


CREATE FUNCTION public.search_all_items_autocomplete(p_search_query text DEFAULT ''::text, p_search_type text DEFAULT 'auto'::text, p_stock_filter_min integer DEFAULT 1, p_page_size integer DEFAULT 50, p_offset integer DEFAULT 0, p_weight_min numeric DEFAULT NULL::numeric, p_weight_max numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_search_type_final TEXT;
    v_weight_min_final INTEGER;
    v_weight_max_final INTEGER;
    v_result JSONB;
BEGIN
    -- Determine search type and weight parameters
    IF p_search_type = 'weight_range' OR (p_weight_min IS NOT NULL AND p_weight_max IS NOT NULL) THEN
        v_search_type_final := 'weight_range';
        v_weight_min_final := COALESCE(p_weight_min, 0)::INTEGER;
        v_weight_max_final := COALESCE(p_weight_max, 999999)::INTEGER;
    ELSIF p_search_type = 'auto' AND p_search_query ~ '^[0-9]+\.?[0-9]*-[0-9]+\.?[0-9]*$' THEN
        v_search_type_final := 'weight_range';
        v_weight_min_final := split_part(p_search_query, '-', 1)::INTEGER;
        v_weight_max_final := split_part(p_search_query, '-', 2)::INTEGER;
    ELSIF p_search_type = 'weight' OR (p_search_type = 'auto' AND p_search_query ~ '^[0-9]+\.?[0-9]*$') THEN
        v_search_type_final := 'weight_exact';
        v_weight_min_final := COALESCE(p_weight_min, p_search_query::INTEGER);
        v_weight_max_final := v_weight_min_final;
    ELSIF p_search_query IS NULL OR trim(p_search_query) = '' THEN
        v_search_type_final := 'all';
    ELSE
        v_search_type_final := 'text';
    END IF;

    -- Build query based on search type
    SELECT jsonb_build_object(
        'items', COALESCE(
            (SELECT jsonb_agg(item_data)
            FROM (
                SELECT jsonb_build_object(
                    'id', grt.id,
                    'grn_id', grt.gr_id,
                    'item_id', grt.item_id,
                    'item_name', i.name,
                    'weight', grt.weight,
                    'stock', COALESCE(
                        grt.quantity - COALESCE(
                            (SELECT SUM(dt.quantity)
                             FROM dispatch_trl dt
                             WHERE dt.gr_id = grt.gr_id
                               AND dt.item_id = grt.item_id
                               AND dt.weight = grt.weight),
                            0
                        ),
                        0
                    ),
                    'gr_no', gr.gr_no,
                    'gr_date', gr.gr_date,
                    'storage_charge', grt.storage_charge,
                    'customer_id', gr.customer_id,
                    'customer_name', c.name
                ) AS item_data
                FROM goodsreceived_trl grt
                INNER JOIN goodsreceived gr ON grt.gr_id = gr.id
                INNER JOIN items i ON grt.item_id = i.id
                INNER JOIN customers c ON gr.customer_id = c.id
                WHERE gr.active = true
                  AND c.active = true
                  AND (
                      (v_search_type_final = 'all') OR
                      (v_search_type_final = 'weight_range'
                       AND grt.weight >= v_weight_min_final
                       AND grt.weight <= v_weight_max_final) OR
                      (v_search_type_final = 'weight_exact'
                       AND grt.weight = v_weight_min_final) OR
                      (v_search_type_final = 'text'
                       AND (
                           i.name ILIKE '%' || p_search_query || '%' OR
                           gr.gr_no ILIKE '%' || p_search_query || '%' OR
                           c.name ILIKE '%' || p_search_query || '%'
                       ))
                  )
                  AND (
                      p_stock_filter_min IS NULL OR
                      (grt.quantity - COALESCE(
                          (SELECT SUM(dt.quantity)
                           FROM dispatch_trl dt
                           WHERE dt.gr_id = grt.gr_id
                             AND dt.item_id = grt.item_id
                             AND dt.weight = grt.weight),
                          0
                      )) >= p_stock_filter_min
                  )
                ORDER BY
                    CASE
                        WHEN v_search_type_final = 'text' THEN
                            CASE
                                WHEN i.name ILIKE p_search_query || '%' THEN 1
                                WHEN i.name ILIKE '%' || p_search_query || '%' THEN 2
                                WHEN gr.gr_no ILIKE p_search_query || '%' THEN 3
                                ELSE 4
                            END
                        ELSE 1
                    END,
                    gr.gr_date DESC,
                    i.name ASC,
                    grt.weight ASC
                LIMIT p_page_size
                OFFSET p_offset
            ) AS items),
            '[]'::jsonb
        ),
        'total_count', (
            SELECT COUNT(*)::INTEGER
            FROM goodsreceived_trl grt
            INNER JOIN goodsreceived gr ON grt.gr_id = gr.id
            INNER JOIN items i ON grt.item_id = i.id
            INNER JOIN customers c ON gr.customer_id = c.id
            WHERE gr.active = true
              AND c.active = true
              AND (
                  (v_search_type_final = 'all') OR
                  (v_search_type_final = 'weight_range'
                   AND grt.weight >= v_weight_min_final
                   AND grt.weight <= v_weight_max_final) OR
                  (v_search_type_final = 'weight_exact'
                   AND grt.weight = v_weight_min_final) OR
                  (v_search_type_final = 'text'
                   AND (
                       i.name ILIKE '%' || p_search_query || '%' OR
                       gr.gr_no ILIKE '%' || p_search_query || '%' OR
                       c.name ILIKE '%' || p_search_query || '%'
                   ))
              )
              AND (
                  p_stock_filter_min IS NULL OR
                  (grt.quantity - COALESCE(
                      (SELECT SUM(dt.quantity)
                       FROM dispatch_trl dt
                       WHERE dt.gr_id = grt.gr_id
                         AND dt.item_id = grt.item_id
                         AND dt.weight = grt.weight),
                      0
                  )) >= p_stock_filter_min
              )
        ),
        'has_more', (p_offset + p_page_size) < (
            SELECT COUNT(*)
            FROM goodsreceived_trl grt
            INNER JOIN goodsreceived gr ON grt.gr_id = gr.id
            INNER JOIN items i ON grt.item_id = i.id
            INNER JOIN customers c ON gr.customer_id = c.id
            WHERE gr.active = true
              AND c.active = true
              AND (
                  (v_search_type_final = 'all') OR
                  (v_search_type_final = 'weight_range'
                   AND grt.weight >= v_weight_min_final
                   AND grt.weight <= v_weight_max_final) OR
                  (v_search_type_final = 'weight_exact'
                   AND grt.weight = v_weight_min_final) OR
                  (v_search_type_final = 'text'
                   AND (
                       i.name ILIKE '%' || p_search_query || '%' OR
                       gr.gr_no ILIKE '%' || p_search_query || '%' OR
                       c.name ILIKE '%' || p_search_query || '%'
                   ))
              )
              AND (
                  p_stock_filter_min IS NULL OR
                  (grt.quantity - COALESCE(
                      (SELECT SUM(dt.quantity)
                       FROM dispatch_trl dt
                       WHERE dt.gr_id = grt.gr_id
                         AND dt.item_id = grt.item_id
                         AND dt.weight = grt.weight),
                      0
                  )) >= p_stock_filter_min
              )
        ),
        'search_type', v_search_type_final,
        'page_size', p_page_size,
        'offset', p_offset
    ) INTO v_result;

    RETURN v_result;
END;
$_$;


CREATE FUNCTION public.search_customer_items_for_order(p_search_query text DEFAULT ''::text, p_customer_id uuid DEFAULT NULL::uuid, p_search_type text DEFAULT 'auto'::text, p_stock_filter_min integer DEFAULT 1, p_page_size integer DEFAULT 50, p_offset integer DEFAULT 0, p_catalog_id uuid DEFAULT NULL::uuid, p_weight_min numeric DEFAULT NULL::numeric, p_weight_max numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_search_type_final TEXT;
    v_weight_min_final INTEGER;
    v_weight_max_final INTEGER;
    v_accessible_customers UUID[];
    v_is_admin BOOLEAN;
    v_result JSONB;
BEGIN
    v_is_admin := is_admin_or_supervisor();

    IF v_is_admin THEN
        IF p_customer_id IS NOT NULL THEN
            v_accessible_customers := ARRAY[p_customer_id];
        ELSE
            SELECT ARRAY(SELECT id FROM customers WHERE active = true AND deleted_at IS NULL) INTO v_accessible_customers;
        END IF;
    ELSE
        SELECT user_accessible_customers() INTO v_accessible_customers;

        IF v_accessible_customers IS NULL OR array_length(v_accessible_customers, 1) IS NULL THEN
            RETURN jsonb_build_object('items', '[]'::jsonb, 'total_count', 0, 'error', 'No accessible customers');
        END IF;

        IF p_customer_id IS NOT NULL THEN
            IF NOT (p_customer_id = ANY(v_accessible_customers)) THEN
                RETURN jsonb_build_object('items', '[]'::jsonb, 'total_count', 0, 'error', 'Access denied to customer');
            END IF;
            v_accessible_customers := ARRAY[p_customer_id];
        END IF;
    END IF;

    IF p_search_type = 'weight_range' OR (p_weight_min IS NOT NULL AND p_weight_max IS NOT NULL) THEN
        v_search_type_final := 'weight_range';
        v_weight_min_final := COALESCE(p_weight_min, 0)::INTEGER;
        v_weight_max_final := COALESCE(p_weight_max, 999999)::INTEGER;
    ELSIF p_search_type = 'auto' AND p_search_query ~ '^[0-9]+\.?[0-9]*-[0-9]+\.?[0-9]*$' THEN
        v_search_type_final := 'weight_range';
        v_weight_min_final := split_part(p_search_query, '-', 1)::INTEGER;
        v_weight_max_final := split_part(p_search_query, '-', 2)::INTEGER;
    ELSIF p_search_type = 'weight' OR (p_search_type = 'auto' AND p_search_query ~ '^[0-9]+\.?[0-9]*$') THEN
        v_search_type_final := 'weight_exact';
        v_weight_min_final := COALESCE(p_weight_min, p_search_query::INTEGER);
        v_weight_max_final := v_weight_min_final;
    ELSIF p_search_query IS NULL OR trim(p_search_query) = '' THEN
        v_search_type_final := 'all';
    ELSE
        v_search_type_final := 'text';
    END IF;

    SELECT jsonb_build_object(
        'items', COALESCE(
            (SELECT jsonb_agg(item_data)
            FROM (
                SELECT jsonb_build_object(
                    'id', grt.id,
                    'grn_id', grt.gr_id,
                    'item_id', grt.item_id,
                    'item_name', grt.item_name,
                    'package_mark', grt.package_mark,
                    'packaging', grt.packaging,
                    'rack', grt.rack,
                    'qty', grt.qty,
                    'stock', grt.stock,
                    'weight', grt.weight,
                    'trl_img_url', grt.trl_img_url,
                    'grn_date', gr.date,
                    'gr_no', gr.gr_no,
                    'customer_id', gr.customer_id,
                    'customer_name', c.name,
                    'master_item_id', i.id,
                    'master_item_name', i.name,
                    'match_type', CASE
                        WHEN v_search_type_final = 'weight_exact' AND grt.weight = v_weight_min_final THEN 'weight_exact'
                        WHEN v_search_type_final = 'weight_range' AND grt.weight >= v_weight_min_final AND grt.weight <= v_weight_max_final THEN 'weight_range'
                        WHEN grt.item_name ILIKE '%' || p_search_query || '%' THEN 'item_name'
                        WHEN grt.package_mark ILIKE '%' || p_search_query || '%' THEN 'package_mark'
                        WHEN grt.packaging ILIKE '%' || p_search_query || '%' THEN 'packaging'
                        WHEN gr.gr_no ILIKE '%' || p_search_query || '%' THEN 'gr_no'
                        WHEN i.name IS NOT NULL AND i.name ILIKE '%' || p_search_query || '%' THEN 'master_item_name'
                        ELSE 'match'
                    END
                ) as item_data
                FROM goodsreceived_trl grt
                JOIN goodsreceived gr ON grt.gr_id = gr.id
                JOIN customers c ON gr.customer_id = c.id
                LEFT JOIN items i ON grt.item_id = i.id
                WHERE gr.customer_id = ANY(v_accessible_customers)
                AND gr.deleted_at IS NULL
                AND grt.stock >= p_stock_filter_min
                AND (p_customer_id IS NULL OR gr.customer_id = p_customer_id)
                AND (p_catalog_id IS NULL OR i.id = p_catalog_id)
                AND (
                    v_search_type_final = 'all'
                    OR (v_search_type_final = 'weight_exact' AND grt.weight = v_weight_min_final)
                    OR (v_search_type_final = 'weight_range' AND grt.weight >= v_weight_min_final AND grt.weight <= v_weight_max_final)
                    OR (v_search_type_final = 'text' AND (
                        grt.item_name ILIKE '%' || p_search_query || '%'
                        OR grt.package_mark ILIKE '%' || p_search_query || '%'
                        OR grt.packaging ILIKE '%' || p_search_query || '%'
                        OR gr.gr_no ILIKE '%' || p_search_query || '%'
                        OR c.name ILIKE '%' || p_search_query || '%'
                        OR (i.name IS NOT NULL AND i.name ILIKE '%' || p_search_query || '%')
                    ))
                )
                ORDER BY
                    CASE
                        WHEN v_search_type_final = 'weight_exact' AND grt.weight = v_weight_min_final THEN 1
                        WHEN v_search_type_final = 'weight_range' AND grt.weight >= v_weight_min_final AND grt.weight <= v_weight_max_final THEN 2
                        WHEN grt.item_name ILIKE '%' || p_search_query || '%' THEN 3
                        WHEN grt.package_mark ILIKE '%' || p_search_query || '%' THEN 4
                        WHEN grt.packaging ILIKE '%' || p_search_query || '%' THEN 5
                        WHEN gr.gr_no ILIKE '%' || p_search_query || '%' THEN 6
                        WHEN i.name IS NOT NULL AND i.name ILIKE '%' || p_search_query || '%' THEN 7
                        ELSE 8
                    END,
                    grt.weight,
                    grt.item_name
                LIMIT p_page_size
                OFFSET p_offset
            ) ordered_items),
            '[]'::jsonb
        ),
        'total_count', (
            SELECT COUNT(*)
            FROM goodsreceived_trl grt
            JOIN goodsreceived gr ON grt.gr_id = gr.id
            JOIN customers c ON gr.customer_id = c.id
            LEFT JOIN items i ON grt.item_id = i.id
            WHERE gr.customer_id = ANY(v_accessible_customers)
            AND gr.deleted_at IS NULL
            AND grt.stock >= p_stock_filter_min
            AND (p_customer_id IS NULL OR gr.customer_id = p_customer_id)
            AND (p_catalog_id IS NULL OR i.id = p_catalog_id)
            AND (
                v_search_type_final = 'all'
                OR (v_search_type_final = 'weight_exact' AND grt.weight = v_weight_min_final)
                OR (v_search_type_final = 'weight_range' AND grt.weight >= v_weight_min_final AND grt.weight <= v_weight_max_final)
                OR (v_search_type_final = 'text' AND (
                    grt.item_name ILIKE '%' || p_search_query || '%'
                    OR grt.package_mark ILIKE '%' || p_search_query || '%'
                    OR grt.packaging ILIKE '%' || p_search_query || '%'
                    OR gr.gr_no ILIKE '%' || p_search_query || '%'
                    OR c.name ILIKE '%' || p_search_query || '%'
                    OR (i.name IS NOT NULL AND i.name ILIKE '%' || p_search_query || '%')
                ))
            )
        )
    ) INTO v_result;

    RETURN v_result;
END;
$_$;


CREATE FUNCTION public.search_customers(p_search_query text, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    SELECT COALESCE(
        jsonb_agg(customer_row ORDER BY customer_row->>'name'),
        '[]'::jsonb
    ) INTO v_result
    FROM (
        SELECT jsonb_build_object(
            'id', c.id,
            'name', c.name,
            'mobile', c.mobile,
            'city', c.city,
            'email', c.email,
            'address', c.address
        ) as customer_row
        FROM customers c
        WHERE c.active = true
          AND c.deleted_at IS NULL
          AND c.id = ANY(user_accessible_customers())
          AND (
              p_search_query IS NULL
              OR p_search_query = ''
              OR c.name ILIKE p_search_query || '%'
              OR c.mobile ILIKE p_search_query || '%'
          )
        ORDER BY c.name
        LIMIT p_limit
    ) sub;

    RETURN utils.success_response(v_result);
END;
$$;


CREATE FUNCTION public.search_grns(p_search_query text DEFAULT ''::text, p_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_user_role text;
      v_user_customer_ids uuid[];
      v_grns jsonb;
      v_total_count integer;
      v_has_more boolean;
      v_result jsonb;
  BEGIN
      -- Get user role and customer access
      SELECT role INTO v_user_role FROM user_profiles
      WHERE auth_user_id = auth.uid();

      -- Get user's accessible customers (for non-admin users)
      IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
          SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
          FROM user_customers
          WHERE user_id = (SELECT id FROM user_profiles WHERE auth_user_id = auth.uid());
      END IF;

      -- Validate limit
      IF p_limit < 1 OR p_limit > 100 THEN
          p_limit := 10;
      END IF;

      -- Get total count first
      SELECT COUNT(*) INTO v_total_count
      FROM goodsreceived gr
      WHERE
          -- Apply customer access control
          (v_user_role IN ('admin', 'supervisor', 'staff') OR
           (v_user_customer_ids IS NOT NULL AND gr.customer_id = ANY(v_user_customer_ids)))
          AND
          -- Apply search filter
          (p_search_query = '' OR
           gr.gr_no ILIKE '%' || p_search_query || '%' OR
           gr.customer_name ILIKE '%' || p_search_query || '%' OR
           gr.supervisor_name ILIKE '%' || p_search_query || '%');

      -- Get paginated results
      SELECT jsonb_agg(
          jsonb_build_object(
              'id', gr.id,
              'gr_no', gr.gr_no,
              'date', gr.date,
              'customer_name', gr.customer_name,
              'registration', gr.registration,
              'supervisor_name', gr.supervisor_name,
              'sender_name', gr.sender_name,
              'invoiced', gr.invoiced,
              'leon', gr.leon,
              'out_of_stock', gr.out_of_stock,
              'note', gr.note
          )
      ) INTO v_grns
      FROM (
          SELECT gr.*
          FROM goodsreceived gr
          WHERE
              -- Apply customer access control
              (v_user_role IN ('admin', 'supervisor', 'staff') OR
               (v_user_customer_ids IS NOT NULL AND gr.customer_id = ANY(v_user_customer_ids)))
              AND
              -- Apply search filter
              (p_search_query = '' OR
               gr.gr_no ILIKE '%' || p_search_query || '%' OR
               gr.customer_name ILIKE '%' || p_search_query || '%' OR
               gr.supervisor_name ILIKE '%' || p_search_query || '%')
          ORDER BY gr.date DESC, gr.created_at DESC
          LIMIT p_limit
      ) gr;

      -- Check if there are more results
      v_has_more := v_total_count > p_limit;

      -- Build response
      v_result := jsonb_build_object(
          'success', true,
          'data', jsonb_build_object(
              'grns', COALESCE(v_grns, '[]'::jsonb),
              'pagination', jsonb_build_object(
                  'limit', p_limit,
                  'total', v_total_count,
                  'has_more', v_has_more
              )
          ),
          'message', 'GRNs retrieved successfully'
      );

      RETURN v_result;

  EXCEPTION
      WHEN OTHERS THEN
          RETURN jsonb_build_object(
              'success', false,
              'error', 'Failed to search GRNs: ' || SQLERRM,
              'code', 'DATABASE_ERROR'
          );
  END;
  $$;


CREATE FUNCTION public.search_items_autocomplete(p_search_query text DEFAULT ''::text, p_active_only boolean DEFAULT true, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    RETURN (
        SELECT jsonb_build_object(
            'items', COALESCE(
                jsonb_agg(
                    jsonb_build_object(
                        'id', id,
                        'name', name,
                        'packaging', packaging,
                        'description', description,
                        'active', active
                    )
                    ORDER BY
                        CASE
                            WHEN name ILIKE p_search_query || '%' THEN 1
                            WHEN name ILIKE '%' || p_search_query || '%' THEN 2
                            ELSE 3
                        END,
                        name ASC
                ),
                '[]'::jsonb
            ),
            'total_count', COUNT(*)::INTEGER
        )
        FROM items
        WHERE (p_active_only = false OR active = true)
          AND (
              p_search_query IS NULL
              OR p_search_query = ''
              OR name ILIKE '%' || p_search_query || '%'
              OR packaging ILIKE '%' || p_search_query || '%'
              OR description ILIKE '%' || p_search_query || '%'
          )
        LIMIT p_limit
    );
END;
$$;


CREATE FUNCTION public.send_otp(p_phone_number character varying, p_purpose character varying DEFAULT 'login'::character varying, p_user_agent text DEFAULT NULL::text, p_ip_address inet DEFAULT NULL::inet, p_captcha_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_otp_code VARCHAR(6);
    v_otp_hash TEXT;
    v_request_id TEXT;
    v_expires_at TIMESTAMP WITH TIME ZONE;
    v_phone_formatted VARCHAR(15);
    v_production_mode BOOLEAN;
    v_provider VARCHAR(20);
    v_account_sid TEXT;
    v_auth_token TEXT;
    v_from_phone TEXT;
    v_twilio_url TEXT;
    v_twilio_message_sid TEXT;
    v_msg91_auth_key TEXT;
    v_msg91_template_id TEXT;
    v_msg91_sender_id TEXT;
    v_msg91_pe_id TEXT;
    v_msg91_url TEXT;
    v_http_response http_response;
    v_response_body JSONB;
    v_request_headers http_header[];
    v_request_body TEXT;
    v_rate_check jsonb;
    v_ip_check jsonb;
    v_captcha_check JSONB;
    v_test_otp VARCHAR(6);
BEGIN
    -- Format phone number
    v_phone_formatted := REGEXP_REPLACE(p_phone_number, '[^0-9]', '', 'g');
    IF LENGTH(v_phone_formatted) <> 10 AND NOT (LENGTH(v_phone_formatted) = 12 AND LEFT(v_phone_formatted, 2) = '91') THEN
        RETURN utils.validation_error_response('phone_number', 'Invalid phone number format');
    END IF;
    IF LENGTH(v_phone_formatted) = 10 THEN
        v_phone_formatted := '91' || v_phone_formatted;
    END IF;

    -- Verify captcha
    v_captcha_check := verify_captcha(p_captcha_token);
    IF NOT (v_captcha_check->>'success')::boolean THEN
        RETURN utils.error_response('CAPTCHA_FAILED', v_captcha_check->>'message');
    END IF;

    -- Check IP rate limit
    v_ip_check := check_ip_rate_limit(p_ip_address);
    IF NOT (v_ip_check->>'success')::boolean THEN
        RETURN v_ip_check;
    END IF;

    -- Check OTP rate limit
    v_rate_check := check_otp_rate_limit(v_phone_formatted);
    IF NOT (v_rate_check->>'success')::boolean THEN
        RETURN v_rate_check;
    END IF;

    -- Get SMS config
    SELECT provider, production_mode, account_sid, auth_token, from_phone,
           msg91_auth_key, msg91_template_id, msg91_sender_id, msg91_pe_id
    INTO v_provider, v_production_mode, v_account_sid, v_auth_token, v_from_phone,
         v_msg91_auth_key, v_msg91_template_id, v_msg91_sender_id, v_msg91_pe_id
    FROM public.sms_config ORDER BY id DESC LIMIT 1;

    v_provider := COALESCE(v_provider, 'twilio');
    v_expires_at := NOW() + INTERVAL '5 minutes';
    v_request_id := 'OTP_' || EXTRACT(EPOCH FROM NOW())::BIGINT || '_' || FLOOR(RANDOM() * 10000)::TEXT;

    -- Invalidate previous OTPs
    UPDATE public.otp_verifications SET verified = TRUE, verified_at = NOW()
    WHERE phone_number = v_phone_formatted AND purpose = p_purpose AND verified = FALSE AND expires_at > NOW();

    -- CHECK TEST OTP RECORDS (works in both test and production mode for specific phone numbers)
    SELECT fixed_otp INTO v_test_otp
    FROM public.test_otp_records
    WHERE phone_number = v_phone_formatted;

    IF v_test_otp IS NOT NULL THEN
        v_otp_code := v_test_otp;
        v_otp_hash := encode(digest(v_test_otp, 'sha256'), 'hex');
        INSERT INTO public.otp_verifications (phone_number, otp_code, otp_code_hash, msg91_request_id, purpose, expires_at, user_agent, ip_address, msg91_status, delivery_status)
        VALUES (v_phone_formatted, NULL, v_otp_hash, v_request_id, p_purpose, v_expires_at, p_user_agent, p_ip_address, 'test_phone', 'test_phone');

        RETURN utils.success_response(
            jsonb_build_object('request_id', v_request_id, 'expires_at', v_expires_at),
            'OTP sent successfully (test phone)'
        );
    END IF;

    -- TEST MODE (when production_mode is false)
    IF NOT v_production_mode THEN
        v_otp_code := '123456';
        v_otp_hash := encode(digest('123456', 'sha256'), 'hex');
        INSERT INTO public.otp_verifications (phone_number, otp_code, otp_code_hash, msg91_request_id, purpose, expires_at, user_agent, ip_address, msg91_status, delivery_status)
        VALUES (v_phone_formatted, NULL, v_otp_hash, v_request_id, p_purpose, v_expires_at, p_user_agent, p_ip_address, 'test_mode', 'test_mode');

        RETURN utils.success_response(
            jsonb_build_object('request_id', v_request_id, 'expires_at', v_expires_at),
            'OTP sent successfully (test mode)'
        );
    END IF;

    -- PRODUCTION MODE
    CASE v_provider
    WHEN 'twilio' THEN
        IF v_account_sid IS NULL OR v_auth_token IS NULL OR v_from_phone IS NULL THEN
            v_otp_code := '123456';
            v_otp_hash := encode(digest('123456', 'sha256'), 'hex');
            INSERT INTO public.otp_verifications (phone_number, otp_code, otp_code_hash, msg91_request_id, purpose, expires_at, user_agent, ip_address, msg91_status, delivery_status)
            VALUES (v_phone_formatted, NULL, v_otp_hash, v_request_id, p_purpose, v_expires_at, p_user_agent, p_ip_address, 'config_missing', 'test_mode');

            RETURN utils.success_response(
                jsonb_build_object('request_id', v_request_id, 'expires_at', v_expires_at),
                'OTP sent (test mode - Twilio config missing)'
            );
        END IF;

        v_otp_code := generate_secure_otp();
        v_otp_hash := encode(digest(v_otp_code, 'sha256'), 'hex');

        BEGIN
            v_twilio_url := 'https://' || v_account_sid || ':' || v_auth_token || '@api.twilio.com/2010-04-01/Accounts/' || v_account_sid || '/Messages.json';
            v_request_headers := ARRAY[]::http_header[];
            v_request_body := 'To=' || replace('+' || v_phone_formatted, '+', '%2B') || '&From=' || replace(v_from_phone, '+', '%2B') || '&Body=Your%20OTP%20code%20is%3A%20' || v_otp_code || '.%20Valid%20for%2010%20minutes.';
            v_http_response := http(('POST', v_twilio_url, v_request_headers, 'application/x-www-form-urlencoded', v_request_body)::http_request);

            IF v_http_response.content IS NOT NULL AND v_http_response.content != '' THEN
                IF v_http_response.content LIKE '{%' THEN
                    v_response_body := v_http_response.content::JSONB;
                    v_twilio_message_sid := v_response_body->>'sid';
                ELSIF v_http_response.content LIKE '<%' THEN
                    IF v_http_response.content LIKE '%<Sid>%' THEN
                        v_twilio_message_sid := substring(v_http_response.content from '<Sid>(.*?)</Sid>');
                    END IF;
                END IF;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_twilio_message_sid := NULL;
        END;

        INSERT INTO public.otp_verifications (phone_number, otp_code, otp_code_hash, msg91_request_id, purpose, expires_at, user_agent, ip_address, msg91_status, delivery_status)
        VALUES (v_phone_formatted, NULL, v_otp_hash, COALESCE(v_twilio_message_sid, v_request_id), p_purpose, v_expires_at, p_user_agent, p_ip_address, 'twilio_sent', 'pending');

    WHEN 'msg91' THEN
        IF v_msg91_auth_key IS NULL OR v_msg91_template_id IS NULL THEN
            v_otp_code := '123456';
            v_otp_hash := encode(digest('123456', 'sha256'), 'hex');
            INSERT INTO public.otp_verifications (phone_number, otp_code, otp_code_hash, msg91_request_id, purpose, expires_at, user_agent, ip_address, msg91_status, delivery_status)
            VALUES (v_phone_formatted, NULL, v_otp_hash, v_request_id, p_purpose, v_expires_at, p_user_agent, p_ip_address, 'config_missing', 'test_mode');

            RETURN utils.success_response(
                jsonb_build_object('request_id', v_request_id, 'expires_at', v_expires_at),
                'OTP sent (test mode - MSG91 config missing)'
            );
        END IF;

        v_otp_code := generate_secure_otp();
        v_otp_hash := encode(digest(v_otp_code, 'sha256'), 'hex');

        BEGIN
            v_msg91_url := 'https://control.msg91.com/api/v5/flow/';
            v_request_headers := ARRAY[http_header('authkey', v_msg91_auth_key), http_header('Content-Type', 'application/json')]::http_header[];
            v_request_body := jsonb_build_object(
                'template_id', v_msg91_template_id,
                'short_url', '0',
                'realTimeResponse', '1',
                'recipients', jsonb_build_array(
                    jsonb_build_object('mobiles', v_phone_formatted, 'OTP', v_otp_code)
                )
            )::text;
            v_http_response := http(('POST', v_msg91_url, v_request_headers, 'application/json', v_request_body)::http_request);
        EXCEPTION WHEN OTHERS THEN
            NULL;
        END;

        INSERT INTO public.otp_verifications (phone_number, otp_code, otp_code_hash, msg91_request_id, purpose, expires_at, user_agent, ip_address, msg91_status, delivery_status)
        VALUES (v_phone_formatted, NULL, v_otp_hash, v_request_id, p_purpose, v_expires_at, p_user_agent, p_ip_address, 'msg91_sent', 'pending');
    ELSE
        RETURN utils.error_response('INVALID_PROVIDER', 'Invalid SMS provider configured: ' || v_provider);
    END CASE;

    RETURN utils.success_response(
        jsonb_build_object('request_id', v_request_id, 'expires_at', v_expires_at),
        'OTP sent successfully'
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN utils.database_error_response('Failed to send OTP', SQLERRM, SQLSTATE);
END;
$$;


CREATE FUNCTION public.send_otp_simple(p_phone_number character varying, p_purpose character varying DEFAULT 'login'::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    -- This is a simplified OTP sender for testing
    RETURN utils.success_response(
        jsonb_build_object(
            'phone', p_phone_number,
            'purpose', p_purpose,
            'test_mode', true
        ),
        'OTP sending simulated (test mode)'
    );
END;
