CREATE FUNCTION public.sync_customer_rename_to_ledger_map() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    -- NEW.name may be null (we still need to handle that gracefully)
    IF NEW.name IS NULL OR NEW.name = OLD.name THEN
        RETURN NEW;
    END IF;

    UPDATE public.tally_ledger_map
       SET tally_ledger_name = NEW.name,
           updated_at        = now()
     WHERE customer_id       = NEW.id
       AND auto_created      = true
       AND tally_ledger_name = OLD.name;

    RETURN NEW;
END;
$$;


CREATE FUNCTION public.track_user_activity(p_activity_type character varying DEFAULT 'api_call'::character varying, p_ip_address inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_id UUID;
    v_auth_session_id UUID;
    v_last_activity TIMESTAMPTZ;
    v_inactive_duration INTERVAL;
BEGIN
    SELECT id INTO v_user_id
    FROM user_profiles
    WHERE auth_user_id = auth.uid();

    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'User not found or not authenticated'
        );
    END IF;

    SELECT id INTO v_auth_session_id
    FROM auth.sessions
    WHERE user_id = auth.uid()
    AND updated_at > NOW() - INTERVAL '1 hour'
    ORDER BY updated_at DESC
    LIMIT 1;

    SELECT last_activity_at INTO v_last_activity
    FROM user_session_activity
    WHERE user_id = v_user_id
    ORDER BY last_activity_at DESC
    LIMIT 1;

    IF v_last_activity IS NOT NULL THEN
        v_inactive_duration := NOW() - v_last_activity;
    END IF;

    IF v_inactive_duration IS NOT NULL AND v_inactive_duration > INTERVAL '15 minutes' THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'Session expired due to inactivity',
            'inactive_duration_seconds', EXTRACT(EPOCH FROM v_inactive_duration)::INTEGER,
            'requires_reauth', TRUE
        );
    END IF;

    INSERT INTO user_session_activity (
        user_id, auth_session_id, last_activity_at, ip_address, user_agent, activity_type
    ) VALUES (
        v_user_id, v_auth_session_id, NOW(), p_ip_address, p_user_agent, p_activity_type
    );

    RETURN jsonb_build_object(
        'success', TRUE,
        'last_activity', v_last_activity,
        'inactive_duration_seconds', COALESCE(EXTRACT(EPOCH FROM v_inactive_duration)::INTEGER, 0)
    );
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'track_user_activity failed: ' || SQLERRM
        );
END;
$$;


