CREATE FUNCTION public.update_contra_voucher(p_voucher_id uuid, p_date date, p_amount numeric, p_from_ledger text, p_to_ledger text, p_particulars text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_voucher          public.tally_contra_vouchers;
    v_config           public.bank_reco_company_config;
    v_new_voucher_no   TEXT;
    v_old_voucher_no   TEXT;
    v_old_tvid         TEXT;
    v_fy_start         INT;
    v_fy_label         TEXT;
    v_seq              BIGINT;
    v_queue_id         UUID;
BEGIN
    IF p_amount IS NULL OR p_amount <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'Amount must be greater than zero');
    END IF;
    IF p_from_ledger IS NULL OR p_to_ledger IS NULL
       OR trim(p_from_ledger) = '' OR trim(p_to_ledger) = '' THEN
        RETURN jsonb_build_object('success', false, 'error', 'Both ledgers required');
    END IF;
    IF p_from_ledger = p_to_ledger THEN
        RETURN jsonb_build_object('success', false, 'error', 'from_ledger and to_ledger must differ');
    END IF;

    SELECT * INTO v_voucher FROM public.tally_contra_vouchers
    WHERE id = p_voucher_id FOR UPDATE;

    IF v_voucher.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Contra voucher not found');
    END IF;

    IF v_voucher.status NOT IN ('queued', 'reconciled') THEN
        RETURN jsonb_build_object('success', false,
            'error', format('Cannot edit contra with status "%s"', v_voucher.status));
    END IF;

    SELECT * INTO v_config FROM public.bank_reco_company_config LIMIT 1;
    IF v_config.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'No company config found');
    END IF;

    -- queued path: middleware hasn't pushed yet. Update voucher row + existing
    -- queue row's payload, keep voucher_number, keep queue row.
    IF v_voucher.status = 'queued' THEN
        UPDATE public.tally_contra_vouchers SET
            voucher_date = p_date,
            from_ledger  = p_from_ledger,
            to_ledger    = p_to_ledger,
            amount       = p_amount,
            particulars  = p_particulars,
            review_note  = format('edited at %s', now()::text)
        WHERE id = p_voucher_id;

        UPDATE public.tally_sync_queue SET
            payload = jsonb_build_object(
                'voucher_id',     p_voucher_id,
                'voucher_number', v_voucher.voucher_number,
                'voucher_date',   p_date,
                'from_ledger',    p_from_ledger,
                'to_ledger',      p_to_ledger,
                'amount',         p_amount,
                'particulars',    COALESCE(p_particulars, ''),
                'tally_company',  v_config.tally_company
            ),
            updated_at = now()
        WHERE id = v_voucher.tally_sync_queue_id;

        RETURN jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'voucher_id',         p_voucher_id,
                'new_voucher_number', v_voucher.voucher_number,
                'queue_id',           v_voucher.tally_sync_queue_id,
                'status',             'queued'
            )
        );
    END IF;

    -- reconciled path: already in Tally. New voucher number, queue 'update'
    -- so middleware cancels old + creates new.
    v_old_voucher_no := v_voucher.voucher_number;
    v_old_tvid       := v_voucher.tally_voucher_id;

    IF EXTRACT(MONTH FROM p_date) >= 4 THEN
        v_fy_start := EXTRACT(YEAR FROM p_date)::INT;
    ELSE
        v_fy_start := EXTRACT(YEAR FROM p_date)::INT - 1;
    END IF;
    v_fy_label := v_fy_start::TEXT || '-' || RIGHT((v_fy_start + 1)::TEXT, 2);

    INSERT INTO public.contra_voucher_counters (financial_year, next_seq)
    VALUES (v_fy_label, 2)
    ON CONFLICT (financial_year)
    DO UPDATE SET next_seq = contra_voucher_counters.next_seq + 1,
                  updated_at = now()
    RETURNING next_seq - 1 INTO v_seq;

    v_new_voucher_no := 'CTRA/' || v_fy_start::TEXT || '/' || lpad(v_seq::TEXT, 5, '0');

    INSERT INTO public.tally_sync_queue (entity_type, entity_id, operation, payload)
    VALUES (
        'contra', p_voucher_id, 'update',
        jsonb_build_object(
            'voucher_id',           p_voucher_id,
            'old_voucher_number',   v_old_voucher_no,
            'old_tally_voucher_id', v_old_tvid,
            'new_voucher_number',   v_new_voucher_no,
            'voucher_date',         p_date,
            'from_ledger',          p_from_ledger,
            'to_ledger',            p_to_ledger,
            'amount',               p_amount,
            'particulars',          COALESCE(p_particulars, ''),
            'tally_company',        v_config.tally_company
        )
    )
    RETURNING id INTO v_queue_id;

    UPDATE public.tally_contra_vouchers SET
        voucher_number      = v_new_voucher_no,
        voucher_date        = p_date,
        from_ledger         = p_from_ledger,
        to_ledger           = p_to_ledger,
        amount              = p_amount,
        particulars         = p_particulars,
        status              = 'queued',
        tally_voucher_id    = NULL,
        tally_sync_queue_id = v_queue_id,
        review_note         = format('edited at %s', now()::text)
    WHERE id = p_voucher_id;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'voucher_id',         p_voucher_id,
            'new_voucher_number', v_new_voucher_no,
            'queue_id',           v_queue_id,
            'status',             'queued'
        )
    );
END;
$$;


CREATE FUNCTION public.update_customer(p_customer_id uuid, p_name character varying DEFAULT NULL::character varying, p_mobile character varying DEFAULT NULL::character varying, p_email character varying DEFAULT NULL::character varying, p_address text DEFAULT NULL::text, p_city character varying DEFAULT NULL::character varying, p_state character varying DEFAULT NULL::character varying, p_pincode character varying DEFAULT NULL::character varying, p_gst character varying DEFAULT NULL::character varying, p_pan character varying DEFAULT NULL::character varying, p_active boolean DEFAULT NULL::boolean, p_contact_person character varying DEFAULT NULL::character varying, p_contact_mobile character varying DEFAULT NULL::character varying, p_contact_email character varying DEFAULT NULL::character varying, p_image_urls text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_existing RECORD;
BEGIN
    -- Check permission
    IF NOT is_admin_or_supervisor() THEN
        RETURN utils.permission_denied_response('admins and supervisors');
    END IF;

    -- Check if customer exists
    SELECT * INTO v_existing FROM customers WHERE id = p_customer_id;
    IF v_existing IS NULL THEN
        RETURN utils.not_found_response('Customer', p_customer_id::text);
    END IF;

    -- Validate mobile if provided
    IF p_mobile IS NOT NULL AND NOT p_mobile ~ '^[0-9]{10,15}$' THEN
        RETURN utils.validation_error_response('mobile', 'Mobile number must be 10-15 digits');
    END IF;

    -- Check for duplicate mobile
    IF p_mobile IS NOT NULL AND EXISTS(SELECT 1 FROM customers WHERE mobile = p_mobile AND id != p_customer_id AND active = true) THEN
        RETURN utils.error_response('DUPLICATE_MOBILE', 'A customer with this mobile number already exists');
    END IF;

    -- Update customer
    UPDATE customers SET
        name = COALESCE(p_name, name),
        mobile = COALESCE(p_mobile, mobile),
        email = COALESCE(p_email, email),
        address = COALESCE(p_address, address),
        city = COALESCE(p_city, city),
        state = COALESCE(p_state, state),
        pincode = COALESCE(p_pincode, pincode),
        gst = COALESCE(p_gst, gst),
        pan = COALESCE(p_pan, pan),
        active = COALESCE(p_active, active),
        contact_person = COALESCE(p_contact_person, contact_person),
        contact_mobile = COALESCE(p_contact_mobile, contact_mobile),
        contact_email = COALESCE(p_contact_email, contact_email),
        updated_at = NOW()
    WHERE id = p_customer_id;

    -- Handle images if provided
    IF p_image_urls IS NOT NULL THEN
        DELETE FROM customer_images WHERE customer_id = p_customer_id;
        IF array_length(p_image_urls, 1) > 0 THEN
            INSERT INTO customer_images (customer_id, storage_path)
            SELECT p_customer_id, unnest(p_image_urls);
        END IF;
    END IF;

    RETURN utils.success_response(
        jsonb_build_object('customer_id', p_customer_id),
        'Customer updated successfully'
    );

EXCEPTION
    WHEN unique_violation THEN
        RETURN utils.error_response('DUPLICATE_MOBILE', 'A customer with this mobile number already exists');
    WHEN OTHERS THEN
        RETURN utils.database_error_response('Failed to update customer', SQLERRM, SQLSTATE);
END;
$_$;


CREATE FUNCTION public.update_customer_contact_with_auth_phone() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    updated_count INTEGER := 0;
    customer_record RECORD;
    auth_phone TEXT;
    final_contact TEXT;
BEGIN
    -- Loop through all customers
    FOR customer_record IN
        SELECT id, mobile, telephone1, contact, created_by
        FROM customers
    LOOP
        auth_phone := NULL;
        final_contact := NULL;

        -- Priority 1: Try to get auth phone from creator (if created_by exists)
        IF customer_record.created_by IS NOT NULL THEN
            SELECT au.phone INTO auth_phone
            FROM user_profiles up
            JOIN auth.users au ON up.auth_user_id = au.id
            WHERE up.id = customer_record.created_by
            AND au.phone IS NOT NULL;
        END IF;

        -- Priority 2: Try to get auth phone from assigned user (if no creator phone)
        IF auth_phone IS NULL THEN
            SELECT au.phone INTO auth_phone
            FROM users_customers_new ucn
            JOIN user_profiles up ON ucn.user_profile_id = up.id
            JOIN auth.users au ON up.auth_user_id = au.id
            WHERE ucn.customer_id = customer_record.id
            AND ucn.active = true
            AND au.phone IS NOT NULL
            ORDER BY ucn.assigned_at DESC
            LIMIT 1;
        END IF;

        -- Determine final contact with priority
        final_contact := COALESCE(
            auth_phone,                    -- Priority 1: Auth phone
            customer_record.mobile,        -- Priority 2: Customer mobile
            customer_record.telephone1     -- Priority 3: Customer telephone1
        );

        -- Update only if contact is different or null
        IF final_contact IS NOT NULL AND (customer_record.contact IS NULL OR customer_record.contact != final_contact) THEN
            UPDATE customers
            SET contact = final_contact
            WHERE id = customer_record.id;

            updated_count := updated_count + 1;
        END IF;
    END LOOP;

    RETURN updated_count;
END;
$$;


CREATE FUNCTION public.update_customer_contact_with_priority(customer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    priority_contact TEXT;
    contact_source TEXT;
    result JSONB;
BEGIN
    -- Get the priority contact
    SELECT priority_contact, contact_source INTO priority_contact, contact_source
    FROM get_customer_with_priority_contact(customer_id);

    IF priority_contact IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'No contact information available'
        );
    END IF;

    -- Update the customer's contact field
    UPDATE customers
    SET contact = priority_contact
    WHERE id = customer_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Customer not found'
        );
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'customer_id', customer_id,
        'contact', priority_contact,
        'contact_source', contact_source
    );
END;
$$;


CREATE FUNCTION public.update_dispatch_smart(p_dispatch_id uuid, p_dispatch_data jsonb, p_dispatch_items jsonb[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_id uuid;
    v_invoiced_items text;
    v_insufficient_stock text;
    v_affected_gr_ids uuid[];
    v_dispatch_items_result jsonb[];
BEGIN
    -- Check if user is admin or supervisor
    IF NOT is_admin_or_supervisor() THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Only administrators and supervisors can update dispatches'
        );
    END IF;

    -- Get current user
    SELECT id INTO v_user_id FROM user_profiles WHERE auth_user_id = auth.uid();

    -- Update dispatch header if data provided (single statement - OK)
    IF p_dispatch_data IS NOT NULL THEN
        UPDATE dispatch SET
            disp_no = COALESCE(p_dispatch_data->>'disp_no', disp_no),
            disp_date = COALESCE((p_dispatch_data->>'disp_date')::date::timestamptz, disp_date),
            registration = COALESCE(p_dispatch_data->>'registration', registration),
            customer_id = COALESCE((p_dispatch_data->>'customer_id')::uuid, customer_id),
            customer_name = COALESCE(p_dispatch_data->>'customer_name', customer_name),
            supervisor_id = COALESCE((p_dispatch_data->>'supervisor_id')::uuid, supervisor_id),
            supervisor_name = COALESCE(p_dispatch_data->>'supervisor_name', supervisor_name),
            note = COALESCE(p_dispatch_data->>'note', note),
            updated_by = v_user_id,
            updated_at = NOW()
        WHERE id = p_dispatch_id;
    END IF;

    -- Handle items if provided
    IF p_dispatch_items IS NOT NULL THEN
        -- ========== STEP 1: VALIDATION - Check invoiced items ==========
        -- Check if any items being modified or deleted are invoiced
        SELECT string_agg(gt.item_name, ', ')
        INTO v_invoiced_items
        FROM dispatch_trl dt
        JOIN goodsreceived_trl gt ON gt.id = dt.gr_trl_id
        WHERE dt.disp_id = p_dispatch_id
        AND EXISTS (SELECT 1 FROM invoice_trl WHERE disp_trl_id = dt.id)
        AND (
            -- Item is being deleted (not in new list)
            NOT EXISTS (
                SELECT 1 FROM unnest(p_dispatch_items) AS new_item
                WHERE (new_item->>'gr_trl_id')::uuid = dt.gr_trl_id
            )
            OR
            -- Item qty is being changed
            EXISTS (
                SELECT 1 FROM unnest(p_dispatch_items) AS new_item
                WHERE (new_item->>'gr_trl_id')::uuid = dt.gr_trl_id
                AND (new_item->>'disp_qty')::integer != dt.disp_qty
            )
        );

        IF v_invoiced_items IS NOT NULL THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'Cannot modify invoiced items: ' || v_invoiced_items
            );
        END IF;

        -- ========== STEP 2: LOCK all affected GRN items ==========
        PERFORM gt.id
        FROM goodsreceived_trl gt
        WHERE gt.id IN (
            -- Existing items in dispatch
            SELECT dt.gr_trl_id FROM dispatch_trl dt WHERE dt.disp_id = p_dispatch_id
            UNION
            -- New items being added
            SELECT (new_item->>'gr_trl_id')::uuid FROM unnest(p_dispatch_items) AS new_item
        )
        FOR UPDATE OF gt;

        -- ========== STEP 3: VALIDATE stock for increases and new items ==========
        SELECT string_agg(
            gt.item_name || ' (Available: ' || gt.stock || ', Need: ' || needed.additional || ')',
            ', '
        )
        INTO v_insufficient_stock
        FROM (
            -- New items need full qty
            SELECT (new_item->>'gr_trl_id')::uuid AS gr_trl_id,
                   (new_item->>'disp_qty')::integer AS additional
            FROM unnest(p_dispatch_items) AS new_item
            WHERE NOT EXISTS (
                SELECT 1 FROM dispatch_trl dt
                WHERE dt.disp_id = p_dispatch_id
                AND dt.gr_trl_id = (new_item->>'gr_trl_id')::uuid
            )
            UNION ALL
            -- Existing items with qty increase need the difference
            SELECT dt.gr_trl_id,
                   (new_item->>'disp_qty')::integer - dt.disp_qty AS additional
            FROM dispatch_trl dt
            JOIN unnest(p_dispatch_items) AS new_item ON (new_item->>'gr_trl_id')::uuid = dt.gr_trl_id
            WHERE dt.disp_id = p_dispatch_id
            AND (new_item->>'disp_qty')::integer > dt.disp_qty
        ) AS needed
        JOIN goodsreceived_trl gt ON gt.id = needed.gr_trl_id
        WHERE gt.stock < needed.additional;

        IF v_insufficient_stock IS NOT NULL THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'Insufficient stock: ' || v_insufficient_stock
            );
        END IF;

        -- ========== STEP 4: Collect affected GR_IDs for out_of_stock update ==========
        SELECT ARRAY(
            SELECT DISTINCT gr_id FROM (
                SELECT dt.gr_id FROM dispatch_trl dt WHERE dt.disp_id = p_dispatch_id
                UNION
                SELECT gt.gr_id FROM unnest(p_dispatch_items) AS new_item
                JOIN goodsreceived_trl gt ON gt.id = (new_item->>'gr_trl_id')::uuid
            ) AS all_gr_ids
        ) INTO v_affected_gr_ids;

        -- ========== STEP 5: BULK restore stock for DELETED items ==========
        UPDATE goodsreceived_trl gt
        SET stock = gt.stock + dt.disp_qty
        FROM dispatch_trl dt
        WHERE dt.disp_id = p_dispatch_id
        AND gt.id = dt.gr_trl_id
        AND NOT EXISTS (
            SELECT 1 FROM unnest(p_dispatch_items) AS new_item
            WHERE (new_item->>'gr_trl_id')::uuid = dt.gr_trl_id
        );

        -- ========== STEP 6: BULK log movements for DELETED items ==========
        INSERT INTO stock_movements (gr_trl_id, movement_type, quantity, reference_id, reference_type, balance_before, balance_after, created_by, notes)
        SELECT
            dt.gr_trl_id,
            'return',
            dt.disp_qty,
            dt.id,
            'dispatch_item_delete',
            gt.stock - dt.disp_qty,  -- balance_before (stock was already restored)
            gt.stock,                 -- balance_after
            v_user_id,
            'Item removed from dispatch'
        FROM dispatch_trl dt
        JOIN goodsreceived_trl gt ON gt.id = dt.gr_trl_id
        WHERE dt.disp_id = p_dispatch_id
        AND NOT EXISTS (
            SELECT 1 FROM unnest(p_dispatch_items) AS new_item
            WHERE (new_item->>'gr_trl_id')::uuid = dt.gr_trl_id
        );

        -- ========== STEP 7: BULK delete removed items ==========
        DELETE FROM dispatch_trl dt
        WHERE dt.disp_id = p_dispatch_id
        AND NOT EXISTS (
            SELECT 1 FROM unnest(p_dispatch_items) AS new_item
            WHERE (new_item->>'gr_trl_id')::uuid = dt.gr_trl_id
        );

        -- ========== STEP 8: BULK update stock for QTY CHANGES ==========
        UPDATE goodsreceived_trl gt
        SET stock = gt.stock - ((new_item->>'disp_qty')::integer - dt.disp_qty)
        FROM dispatch_trl dt
        JOIN unnest(p_dispatch_items) AS new_item ON (new_item->>'gr_trl_id')::uuid = dt.gr_trl_id
        WHERE dt.disp_id = p_dispatch_id
        AND gt.id = dt.gr_trl_id
        AND (new_item->>'disp_qty')::integer != dt.disp_qty;

        -- ========== STEP 9: BULK log movements for QTY CHANGES ==========
        INSERT INTO stock_movements (gr_trl_id, movement_type, quantity, reference_id, reference_type, balance_before, balance_after, created_by, notes)
        SELECT
            dt.gr_trl_id,
            'dispatch',
            -((new_item->>'disp_qty')::integer - dt.disp_qty),
            dt.id,
            'dispatch_update',
            gt.stock + ((new_item->>'disp_qty')::integer - dt.disp_qty),  -- balance_before
            gt.stock,  -- balance_after (already updated)
            v_user_id,
            format('Qty changed from %s to %s', dt.disp_qty, (new_item->>'disp_qty')::integer)
        FROM dispatch_trl dt
        JOIN unnest(p_dispatch_items) AS new_item ON (new_item->>'gr_trl_id')::uuid = dt.gr_trl_id
        JOIN goodsreceived_trl gt ON gt.id = dt.gr_trl_id
        WHERE dt.disp_id = p_dispatch_id
        AND (new_item->>'disp_qty')::integer != dt.disp_qty;

        -- ========== STEP 10: BULK update dispatch_trl quantities ==========
        UPDATE dispatch_trl dt
        SET disp_qty = (new_item->>'disp_qty')::integer
        FROM unnest(p_dispatch_items) AS new_item
        WHERE dt.disp_id = p_dispatch_id
        AND dt.gr_trl_id = (new_item->>'gr_trl_id')::uuid
        AND dt.disp_qty != (new_item->>'disp_qty')::integer;

        -- ========== STEP 11: BULK deduct stock for NEW items ==========
        UPDATE goodsreceived_trl gt
        SET stock = gt.stock - (new_item->>'disp_qty')::integer
        FROM unnest(p_dispatch_items) AS new_item
        WHERE gt.id = (new_item->>'gr_trl_id')::uuid
        AND NOT EXISTS (
            SELECT 1 FROM dispatch_trl dt
            WHERE dt.disp_id = p_dispatch_id
            AND dt.gr_trl_id = (new_item->>'gr_trl_id')::uuid
        );

        -- ========== STEP 12: BULK insert NEW dispatch items ==========
        INSERT INTO dispatch_trl (disp_id, gr_trl_id, gr_id, disp_qty)
        SELECT
            p_dispatch_id,
            (new_item->>'gr_trl_id')::uuid,
            gt.gr_id,
            (new_item->>'disp_qty')::integer
        FROM unnest(p_dispatch_items) AS new_item
        JOIN goodsreceived_trl gt ON gt.id = (new_item->>'gr_trl_id')::uuid
        WHERE NOT EXISTS (
            SELECT 1 FROM dispatch_trl dt
            WHERE dt.disp_id = p_dispatch_id
            AND dt.gr_trl_id = (new_item->>'gr_trl_id')::uuid
        );

        -- ========== STEP 13: BULK log movements for NEW items ==========
        INSERT INTO stock_movements (gr_trl_id, movement_type, quantity, reference_id, reference_type, balance_before, balance_after, created_by)
        SELECT
            (new_item->>'gr_trl_id')::uuid,
            'dispatch',
            -(new_item->>'disp_qty')::integer,
            p_dispatch_id,
            'dispatch',
            gt.stock + (new_item->>'disp_qty')::integer,  -- balance_before
            gt.stock,  -- balance_after (already updated)
            v_user_id
        FROM unnest(p_dispatch_items) AS new_item
        JOIN goodsreceived_trl gt ON gt.id = (new_item->>'gr_trl_id')::uuid
        JOIN dispatch_trl dt ON dt.disp_id = p_dispatch_id AND dt.gr_trl_id = gt.id
        WHERE dt.id = (SELECT id FROM dispatch_trl WHERE disp_id = p_dispatch_id AND gr_trl_id = gt.id ORDER BY id DESC LIMIT 1);

        -- ========== STEP 14: BULK update out_of_stock status ==========
        UPDATE goodsreceived gr
        SET out_of_stock = NOT EXISTS (
            SELECT 1 FROM goodsreceived_trl grt
            WHERE grt.gr_id = gr.id AND grt.stock > 0
        )
        WHERE gr.id = ANY(v_affected_gr_ids);

    END IF;

    -- ========== Build response (single query) ==========
    SELECT ARRAY(
        SELECT jsonb_build_object(
            'id', dt.id,
            'gr_trl_id', dt.gr_trl_id,
            'gr_id', dt.gr_id,
            'disp_qty', dt.disp_qty,
            'item_id', grt.item_id,
            'item_name', grt.item_name,
            'packaging', grt.packaging,
            'weight', grt.weight,
            'rack', grt.rack
        )
        FROM dispatch_trl dt
        JOIN goodsreceived_trl grt ON grt.id = dt.gr_trl_id
        WHERE dt.disp_id = p_dispatch_id
    ) INTO v_dispatch_items_result;

    RETURN jsonb_build_object(
        'success', true,
        'dispatch_id', p_dispatch_id,
        'dispatch_items', v_dispatch_items_result
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', SQLERRM
        );
END;
$$;


CREATE FUNCTION public.update_grn(p_grn_id uuid, p_gr_no character varying DEFAULT NULL::character varying, p_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_customer_id uuid DEFAULT NULL::uuid, p_customer_name character varying DEFAULT NULL::character varying, p_sender_id uuid DEFAULT NULL::uuid, p_sender_name character varying DEFAULT NULL::character varying, p_supervisor_id uuid DEFAULT NULL::uuid, p_supervisor_name character varying DEFAULT NULL::character varying, p_registration character varying DEFAULT NULL::character varying, p_note character varying DEFAULT NULL::character varying, p_leon boolean DEFAULT NULL::boolean, p_pricing_mode character varying DEFAULT NULL::character varying, p_items jsonb DEFAULT '[]'::jsonb, p_images jsonb DEFAULT '[]'::jsonb, p_duration_mode character varying DEFAULT NULL::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET jit TO 'off'
    AS $$
DECLARE
    v_user_id uuid;
    v_user_profile_id uuid;
    v_user_role text;
    v_item jsonb;
    v_image jsonb;
    v_grn_trl_item_id uuid;
    v_image_id uuid;
    v_current_qty int;
    v_current_stock int;
    v_item_name_from_db varchar;
    v_dispatched_qty int;
    v_items_updated int := 0;
    v_items_added int := 0;
    v_items_deleted int := 0;
    v_images_updated int := 0;
    v_images_added int := 0;
    v_images_deleted int := 0;
    v_items_skipped_stock jsonb := '[]'::jsonb;
    v_existing_grn_item_ids uuid[];
    v_provided_grn_item_ids uuid[];
    v_items_to_delete uuid[];
    v_item_index int;
    v_item_mapping jsonb := '[]'::jsonb;
    v_resolved_item_id uuid;
    v_existing_image_ids uuid[];
    v_kept_image_ids uuid[];
    v_final_grn_data jsonb;
    v_grn_items jsonb := '[]'::jsonb;
    v_grn_images jsonb;
    v_temp_item jsonb;
    v_grn_header jsonb;
    v_item_master_id uuid;
    v_item_name varchar;
BEGIN
    v_user_id := auth.uid();

    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Authentication required'
        );
    END IF;

    SELECT id, role INTO v_user_profile_id, v_user_role
    FROM user_profiles
    WHERE auth_user_id = v_user_id;

    IF v_user_profile_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'User profile not found'
        );
    END IF;

    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Insufficient permissions. Only admin and supervisor can update GRNs'
        );
    END IF;

    IF NOT EXISTS (SELECT 1 FROM goodsreceived WHERE id = p_grn_id) THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'GRN not found'
        );
    END IF;

    IF p_gr_no IS NOT NULL AND EXISTS (
        SELECT 1 FROM goodsreceived
        WHERE gr_no = p_gr_no AND id != p_grn_id
    ) THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'GRN number already exists: ' || p_gr_no
        );
    END IF;

    BEGIN
        PERFORM safe_disable_grn_trl_triggers();

        UPDATE goodsreceived SET
            gr_no = COALESCE(p_gr_no, gr_no),
            date = COALESCE(p_date, date),
            customer_id = COALESCE(p_customer_id, customer_id),
            customer_name = COALESCE(p_customer_name, customer_name),
            sender_id = COALESCE(p_sender_id, sender_id),
            sender_name = COALESCE(p_sender_name, sender_name),
            supervisor_id = COALESCE(p_supervisor_id, supervisor_id),
            supervisor_name = COALESCE(p_supervisor_name, supervisor_name),
            registration = COALESCE(p_registration, registration),
            note = COALESCE(p_note, note),
            leon = COALESCE(p_leon, leon),
            pricing_mode = COALESCE(p_pricing_mode, pricing_mode),
            duration_mode = COALESCE(p_duration_mode, duration_mode),
            updated_by = v_user_profile_id,
            updated_at = now()
        WHERE id = p_grn_id;

        SELECT array_agg(id) INTO v_existing_grn_item_ids
        FROM goodsreceived_trl
        WHERE gr_id = p_grn_id;

        v_provided_grn_item_ids := ARRAY[]::uuid[];

        v_item_index := 0;
        FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
        LOOP
            v_item_master_id := (v_item->>'item_id')::uuid;
            v_item_name := v_item->>'item_name';

            IF v_item_master_id IS NULL THEN
                RAISE EXCEPTION 'itemId is required for all items';
            END IF;
            IF v_item_name IS NULL OR v_item_name = '' THEN
                RAISE EXCEPTION 'itemName is required for all items';
            END IF;

            IF v_item->>'id' IS NOT NULL THEN
                SELECT qty, stock, item_name
                INTO v_current_qty, v_current_stock, v_item_name_from_db
                FROM goodsreceived_trl
                WHERE id = (v_item->>'id')::uuid;

                SELECT COALESCE(SUM(disp_qty), 0)
                INTO v_dispatched_qty
                FROM dispatch_trl
                WHERE gr_trl_id = (v_item->>'id')::uuid;

                IF v_dispatched_qty = 0 THEN
                    UPDATE goodsreceived_trl SET
                        item_id = v_item_master_id,
                        item_name = v_item_name,
                        packaging = v_item->>'packaging',
                        qty = (v_item->>'qty')::int,
                        stock = (v_item->>'qty')::int,
                        weight = COALESCE((v_item->>'weight')::int, 0),
                        rack = v_item->>'rack',
                        package_mark = v_item->>'package_mark'
                    WHERE id = (v_item->>'id')::uuid;

                    v_items_updated := v_items_updated + 1;
                ELSE
                    UPDATE goodsreceived_trl SET
                        item_id = v_item_master_id,
                        item_name = v_item_name,
                        packaging = v_item->>'packaging',
                        weight = COALESCE((v_item->>'weight')::int, 0),
                        rack = v_item->>'rack',
                        package_mark = v_item->>'package_mark'
                    WHERE id = (v_item->>'id')::uuid;

                    v_items_updated := v_items_updated + 1;

                    v_items_skipped_stock := v_items_skipped_stock || jsonb_build_object(
                        'grn_trl_item_id', v_item->>'id',
                        'item_name', v_item_name_from_db,
                        'reason', format('Cannot update qty/stock - item has %s units dispatched', v_dispatched_qty),
                        'current_qty', v_current_qty,
                        'current_stock', v_current_stock,
                        'dispatched_qty', v_dispatched_qty
                    );
                END IF;

                v_provided_grn_item_ids := array_append(v_provided_grn_item_ids, (v_item->>'id')::uuid);
            ELSE
                INSERT INTO goodsreceived_trl (
                    gr_id, item_id, item_name, packaging, qty, stock, weight, rack, package_mark, pricing_mode
                ) VALUES (
                    p_grn_id, v_item_master_id, v_item_name, v_item->>'packaging',
                    (v_item->>'qty')::int, (v_item->>'qty')::int,
                    COALESCE((v_item->>'weight')::int, 0), v_item->>'rack', v_item->>'package_mark',
                    COALESCE(v_item->>'pricing_mode', 'MONTHLY')::pricing_mode
                ) RETURNING id INTO v_grn_trl_item_id;

                v_items_added := v_items_added + 1;

                v_item_mapping := v_item_mapping || jsonb_build_object(
                    'index', v_item_index,
                    'grn_trl_item_id', v_grn_trl_item_id,
                    'item_name', v_item_name
                );
            END IF;

            v_item_index := v_item_index + 1;
        END LOOP;

        IF v_existing_grn_item_ids IS NOT NULL THEN
            v_items_to_delete := ARRAY(
                SELECT unnest(v_existing_grn_item_ids)
                EXCEPT
                SELECT unnest(v_provided_grn_item_ids)
            );

            IF v_items_to_delete IS NOT NULL THEN
                FOR v_grn_trl_item_id IN SELECT unnest(v_items_to_delete)
                LOOP
                    SELECT COUNT(*) INTO v_dispatched_qty
                    FROM dispatch_trl
                    WHERE gr_trl_id = v_grn_trl_item_id;

                    IF v_dispatched_qty > 0 THEN
                        SELECT item_name INTO v_item_name_from_db
                        FROM goodsreceived_trl
                        WHERE id = v_grn_trl_item_id;

                        RAISE EXCEPTION 'Cannot delete item "%" - has % existing dispatches',
                            v_item_name_from_db, v_dispatched_qty;
                    END IF;

                    DELETE FROM goodsreceived_trl WHERE id = v_grn_trl_item_id;
                    v_items_deleted := v_items_deleted + 1;
                END LOOP;
            END IF;
        END IF;

        IF jsonb_array_length(p_images) > 0 THEN
            v_kept_image_ids := ARRAY[]::uuid[];

            FOR v_image IN SELECT * FROM jsonb_array_elements(p_images)
            LOOP
                IF v_image->>'storage_path' IS NULL OR v_image->>'image_type' IS NULL THEN
                    RAISE EXCEPTION 'Invalid image data: storage_path and image_type are required';
                END IF;

                v_resolved_item_id := NULL;
                IF v_image->>'image_type' = 'item' THEN
                    IF v_image->>'grn_item_id' IS NOT NULL THEN
                        v_resolved_item_id := (v_image->>'grn_item_id')::uuid;
                    ELSIF v_image->>'item_index' IS NOT NULL THEN
                        SELECT (mapping->>'grn_trl_item_id')::uuid INTO v_resolved_item_id
                        FROM jsonb_array_elements(v_item_mapping) mapping
                        WHERE (mapping->>'index')::int = (v_image->>'item_index')::int;

                        IF v_resolved_item_id IS NULL THEN
                            RAISE EXCEPTION 'Invalid item_index % for image', v_image->>'item_index';
                        END IF;
                    ELSE
                        RAISE EXCEPTION 'Item images must have either grn_item_id or item_index';
                    END IF;
                END IF;

                IF v_image->>'id' IS NOT NULL
                    AND NOT (v_image->>'id' LIKE 'temp_%')
                    AND EXISTS (SELECT 1 FROM grn_images WHERE id = (v_image->>'id')::uuid) THEN
                    UPDATE grn_images SET
                        grn_item_id = v_resolved_item_id,
                        updated_at = now()
                    WHERE id = (v_image->>'id')::uuid;

                    v_images_updated := v_images_updated + 1;
                    v_kept_image_ids := array_append(v_kept_image_ids, (v_image->>'id')::uuid);
                ELSE
                    v_image_id := gen_random_uuid();

                    INSERT INTO grn_images (
                        id, grn_id, grn_item_id, image_type, storage_path,
                        original_filename, file_size, mime_type, uploaded_by
                    ) VALUES (
                        v_image_id, p_grn_id, v_resolved_item_id, v_image->>'image_type',
                        v_image->>'storage_path', COALESCE(v_image->>'original_filename', 'unknown'),
                        COALESCE((v_image->>'file_size')::int, 0),
                        COALESCE(v_image->>'mime_type', 'image/jpeg'), v_user_profile_id
                    );

                    v_images_added := v_images_added + 1;
                    v_kept_image_ids := array_append(v_kept_image_ids, v_image_id);
                END IF;
            END LOOP;

            DELETE FROM grn_images
            WHERE grn_id = p_grn_id
            AND id NOT IN (SELECT unnest(v_kept_image_ids));

            GET DIAGNOSTICS v_images_deleted = ROW_COUNT;
        ELSE
            v_images_deleted := 0;
        END IF;

        PERFORM safe_enable_grn_trl_triggers();

        INSERT INTO mv_refresh_status (mv_name, is_dirty, last_marked_dirty_at)
        VALUES
            ('mv_grn_list', true, now()),
            ('mv_dispatch_list', true, now()),
            ('mv_customer_stock_summary', true, now())
        ON CONFLICT (mv_name) DO UPDATE SET
            is_dirty = true,
            last_marked_dirty_at = now();

        SELECT jsonb_agg(
            jsonb_build_object(
                'id', t.id,
                'item_id', t.item_id,
                'item_name', t.item_name,
                'packaging', t.packaging,
                'qty', t.qty,
                'stock', t.stock,
                'weight', t.weight,
                'rack', t.rack,
                'package_mark', t.package_mark
            )
        ) INTO v_grn_items
        FROM goodsreceived_trl t
        WHERE t.gr_id = p_grn_id;

        SELECT jsonb_agg(
            jsonb_build_object(
                'id', i.id,
                'image_type', i.image_type,
                'storage_path', i.storage_path,
                'grn_item_id', i.grn_item_id,
                'original_filename', i.original_filename
            )
        ) INTO v_grn_images
        FROM grn_images i
        WHERE i.grn_id = p_grn_id;

        SELECT jsonb_build_object(
            'id', g.id,
            'gr_no', g.gr_no,
            'date', g.date,
            'customer_id', g.customer_id,
            'customer_name', g.customer_name,
            'sender_id', g.sender_id,
            'sender_name', g.sender_name,
            'supervisor_id', g.supervisor_id,
            'supervisor_name', g.supervisor_name,
            'registration', g.registration,
            'note', g.note,
            'leon', g.leon,
            'pricing_mode', g.pricing_mode,
            'duration_mode', g.duration_mode
        ) INTO v_grn_header
        FROM goodsreceived g
        WHERE g.id = p_grn_id;

        v_final_grn_data := v_grn_header || jsonb_build_object(
            'items', COALESCE(v_grn_items, '[]'::jsonb),
            'images', COALESCE(v_grn_images, '[]'::jsonb)
        );

        RETURN jsonb_build_object(
            'success', true,
            'message', 'GRN updated successfully',
            'grn', v_final_grn_data,
            'stats', jsonb_build_object(
                'items_updated', v_items_updated,
                'items_added', v_items_added,
                'items_deleted', v_items_deleted,
                'images_updated', v_images_updated,
                'images_added', v_images_added,
                'images_deleted', v_images_deleted,
                'items_skipped_stock', v_items_skipped_stock
            ),
            'item_mapping', v_item_mapping
        );

    EXCEPTION WHEN OTHERS THEN
        PERFORM safe_enable_grn_trl_triggers();
        RAISE;
    END;
END;
$$;


CREATE FUNCTION public.update_grn_out_of_stock_status(p_gr_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
  BEGIN
      -- Update out_of_stock flag based on whether any items have stock
      UPDATE goodsreceived
      SET out_of_stock = NOT EXISTS (
          SELECT 1
          FROM goodsreceived_trl
          WHERE gr_id = p_gr_id
          AND stock > 0
      )
      WHERE id = p_gr_id;
  END;
  $$;


CREATE FUNCTION public.update_invoice(p_invoice_id uuid, p_invoice_data jsonb, p_invoice_items jsonb[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_id UUID;
    v_new_gr_id UUID;
    v_old_gr_id UUID;
    v_discount NUMERIC(12,2);
    v_items_count INTEGER;
    v_duration_mode text;
    v_invoice_no integer;
BEGIN
    SELECT id INTO v_user_id FROM user_profiles WHERE auth_user_id = auth.uid();
    v_discount := COALESCE(NULLIF(p_invoice_data->>'discount', '')::NUMERIC(12,2), 0::NUMERIC(12,2));
    v_new_gr_id := (p_invoice_data->>'gr_id')::uuid;
    v_duration_mode := public.validate_invoice_duration_mode(p_invoice_data->>'duration_mode');

    SELECT gr_id INTO v_old_gr_id FROM invoice WHERE id = p_invoice_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invoice not found');
    END IF;

    IF v_old_gr_id IS DISTINCT FROM v_new_gr_id THEN
        IF v_old_gr_id IS NOT NULL THEN
            UPDATE goodsreceived SET invoiced = false WHERE id = v_old_gr_id;
        END IF;

        IF v_new_gr_id IS NOT NULL THEN
            UPDATE goodsreceived SET invoiced = true WHERE id = v_new_gr_id;
        END IF;
    END IF;

    UPDATE invoice SET
        inv_fin_year = (p_invoice_data->>'inv_fin_year')::integer,
        inv_no = (p_invoice_data->>'inv_no')::integer,
        gr_id = v_new_gr_id,
        gr_no = p_invoice_data->>'gr_no',
        customer_id = (p_invoice_data->>'customer_id')::uuid,
        customer_name = p_invoice_data->>'customer_name',
        inv_date = (p_invoice_data->>'inv_date')::TIMESTAMPTZ,
        labour = (p_invoice_data->>'labour')::NUMERIC(12,2),
        tax_amount = CEIL((p_invoice_data->>'tax_amount')::NUMERIC(12,2)),
        total = CEIL((p_invoice_data->>'total')::NUMERIC(12,2)),
        discount = v_discount,
        one_time_charge = COALESCE((p_invoice_data->>'one_time_charge')::boolean, false),
        notes = p_invoice_data->>'notes',
        duration_mode = v_duration_mode
    WHERE id = p_invoice_id
    RETURNING inv_no INTO v_invoice_no;

    DELETE FROM invoice_trl WHERE invoice_id = p_invoice_id;

    INSERT INTO invoice_trl (invoice_id, disp_trl_id, duration, no_of_days, charge, tax, labour_rate)
    SELECT
        p_invoice_id,
        (item->>'disp_trl_id')::uuid,
        d.duration,
        d.no_of_days,
        COALESCE(NULLIF(item->>'charge', '')::NUMERIC(12,2), NULLIF(item->>'unit_price', '')::NUMERIC(12,2)),
        COALESCE(NULLIF(item->>'tax', '')::NUMERIC(12,2), NULLIF(item->>'tax_percent', '')::NUMERIC(12,2)),
        (item->>'labour_rate')::numeric
    FROM unnest(p_invoice_items) AS item
    JOIN dispatch_trl dt ON dt.id = (item->>'disp_trl_id')::uuid
    JOIN dispatch disp ON disp.id = dt.disp_id
    JOIN goodsreceived gr ON gr.id = dt.gr_id
    CROSS JOIN LATERAL public.calculate_invoice_duration(gr.date::date, disp.disp_date::date, v_duration_mode) d;

    GET DIAGNOSTICS v_items_count = ROW_COUNT;

    RETURN jsonb_build_object(
        'success', true,
        'invoice_id', p_invoice_id,
        'invoice_no', v_invoice_no,
        'invoice_number', v_invoice_no,
        'items_count', v_items_count,
        'duration_mode', v_duration_mode,
        'message', 'Invoice updated successfully'
    );
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM, 'error_code', SQLSTATE);
END;
$$;


CREATE FUNCTION public.update_item(p_item_id uuid, p_name character varying, p_packaging character varying DEFAULT NULL::character varying, p_description character varying DEFAULT NULL::character varying, p_active boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    -- Security check
    IF NOT is_admin_or_supervisor() THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Access denied: Admin or supervisor role required'
        );
    END IF;

    -- Check if item exists
    IF NOT EXISTS (SELECT 1 FROM items WHERE id = p_item_id) THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Item not found'
        );
    END IF;

    -- Validate name
    IF p_name IS NULL OR TRIM(p_name) = '' THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Item name is required'
        );
    END IF;

    -- Check for duplicate name (excluding self)
    IF EXISTS (SELECT 1 FROM items WHERE LOWER(name) = LOWER(TRIM(p_name)) AND id != p_item_id) THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'An item with this name already exists'
        );
    END IF;

    -- Update item
    UPDATE items
    SET name = TRIM(p_name),
        packaging = NULLIF(TRIM(p_packaging), ''),
        description = NULLIF(TRIM(p_description), ''),
        active = p_active
    WHERE id = p_item_id;

    -- Return updated item
    SELECT jsonb_build_object(
        'id', id,
        'name', name,
        'packaging', packaging,
        'description', description,
        'active', active
    ) INTO v_result
    FROM items
    WHERE id = p_item_id;

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Item updated successfully',
        'data', v_result
    );
END;
$$;


CREATE FUNCTION public.update_item_storage_price(p_id uuid, p_unit_price numeric, p_weight_min numeric, p_weight_max numeric, p_labour_rate numeric, p_tax_percent numeric, p_effective_from date, p_effective_to date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_role TEXT;
    v_existing RECORD;
BEGIN
    -- Authorization: admin/supervisor only
    SELECT role INTO v_user_role FROM user_profiles WHERE auth_user_id = auth.uid();

    IF v_user_role IS NULL OR v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Permission denied');
    END IF;

    -- Get existing record (price_type cannot be changed)
    SELECT id, price_type INTO v_existing FROM item_storage_prices WHERE id = p_id;
    IF v_existing.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Price record not found');
    END IF;

    -- Validate weight range
    IF p_weight_max < p_weight_min THEN
        RETURN jsonb_build_object('success', false, 'error', 'weight_max must be >= weight_min');
    END IF;

    -- Validate unit_price
    IF p_unit_price IS NULL OR p_unit_price < 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'unit_price must be >= 0');
    END IF;

    -- Validate date range
    IF p_effective_to IS NOT NULL AND p_effective_to <= p_effective_from THEN
        RETURN jsonb_build_object('success', false, 'error', 'effective_to must be > effective_from');
    END IF;

    -- Update the record (price_type, item_id, customer_id cannot be changed)
    UPDATE item_storage_prices SET
        unit_price = p_unit_price,
        weight_min = p_weight_min,
        weight_max = p_weight_max,
        labour_rate = p_labour_rate,
        tax_percent = p_tax_percent,
        effective_from = p_effective_from,
        effective_to = p_effective_to,
        -- Keep old columns in sync for backward compat
        unit_price_one_time = CASE WHEN v_existing.price_type = 'one_time' THEN p_unit_price ELSE 0 END,
        unit_price_monthly = CASE WHEN v_existing.price_type = 'monthly' THEN p_unit_price ELSE 0 END
    WHERE id = p_id;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object('id', p_id),
        'message', 'Price updated successfully'
    );

EXCEPTION
    WHEN unique_violation THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'A price with the same item, customer, weight range, price type and effective dates already exists'
        );
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', SQLERRM,
            'error_code', SQLSTATE
        );
END;
$$;


CREATE FUNCTION public.update_item_storage_price(p_id uuid, p_weight_min numeric, p_weight_max numeric, p_unit_price_one_time numeric, p_unit_price_monthly numeric, p_labour_rate numeric, p_tax_percent numeric, p_effective_from date, p_effective_to date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_role TEXT;
    v_existing RECORD;
    v_validation JSONB;
    v_result RECORD;
    v_overlap_count INTEGER;
BEGIN
    -- Authorization: admin/supervisor only
    SELECT role INTO v_user_role FROM user_profiles WHERE auth_user_id = auth.uid();
    IF v_user_role IS NULL OR v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Permission denied');
    END IF;

    -- Get existing record (item_id and customer_id are immutable)
    SELECT * INTO v_existing FROM item_storage_prices WHERE id = p_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Price record not found');
    END IF;

    -- Validation 1: weight_max >= weight_min
    IF p_weight_max < p_weight_min THEN
        RETURN jsonb_build_object('success', false, 'error', 'weight_max must be >= weight_min');
    END IF;

    -- Validation 2: At least one price must be > 0
    IF COALESCE(p_unit_price_one_time, 0) <= 0 AND COALESCE(p_unit_price_monthly, 0) <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'At least one of unit_price_one_time or unit_price_monthly must be > 0');
    END IF;

    -- Validation 3: effective_to >= effective_from (if provided)
    IF p_effective_to IS NOT NULL AND p_effective_to < p_effective_from THEN
        RETURN jsonb_build_object('success', false, 'error', 'effective_to must be >= effective_from');
    END IF;

    -- Validation 4: Check for overlapping ranges (excluding current record)
    SELECT COUNT(*) INTO v_overlap_count
    FROM item_storage_prices
    WHERE id != p_id
      AND item_id = v_existing.item_id
      AND COALESCE(customer_id, '00000000-0000-0000-0000-000000000000'::uuid) = COALESCE(v_existing.customer_id, '00000000-0000-0000-0000-000000000000'::uuid)
      AND weight_min = p_weight_min::integer
      AND weight_max = p_weight_max::integer
      AND (
          (p_effective_from, COALESCE(p_effective_to, '9999-12-31'::date))
          OVERLAPS
          (effective_from, COALESCE(effective_to, '9999-12-31'::date))
      );

    IF v_overlap_count > 0 THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Overlapping price configuration exists for this item/customer/weight range'
        );
    END IF;

    -- Update the record
    UPDATE item_storage_prices SET
        weight_min = p_weight_min::integer,
        weight_max = p_weight_max::integer,
        unit_price_one_time = COALESCE(p_unit_price_one_time, 0),
        unit_price_monthly = COALESCE(p_unit_price_monthly, 0),
        labour_rate = p_labour_rate,
        tax_percent = p_tax_percent,
        effective_from = p_effective_from,
        effective_to = p_effective_to
    WHERE id = p_id;

    -- Fetch the updated record with joined data
    SELECT
        isp.id,
        isp.item_id,
        i.name as item_name,
        isp.customer_id,
        c.name as customer_name,
        isp.weight_min,
        isp.weight_max,
        isp.unit_price_one_time,
        isp.unit_price_monthly,
        isp.labour_rate,
        isp.tax_percent,
        isp.effective_from,
        isp.effective_to,
        isp.created_at,
        isp.created_by
    INTO v_result
    FROM item_storage_prices isp
    LEFT JOIN items i ON isp.item_id = i.id
    LEFT JOIN customers c ON isp.customer_id = c.id
    WHERE isp.id = p_id;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'id', v_result.id,
            'item_id', v_result.item_id,
            'item_name', v_result.item_name,
            'customer_id', v_result.customer_id,
            'customer_name', v_result.customer_name,
            'weight_min', v_result.weight_min,
            'weight_max', v_result.weight_max,
            'unit_price_one_time', v_result.unit_price_one_time,
            'unit_price_monthly', v_result.unit_price_monthly,
            'labour_rate', v_result.labour_rate,
            'tax_percent', v_result.tax_percent,
            'effective_from', v_result.effective_from,
            'effective_to', v_result.effective_to,
            'created_at', v_result.created_at,
            'created_by', v_result.created_by
        ),
        'message', 'Price updated successfully'
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', 'Update failed: ' || SQLERRM
    );
END;
$$;


CREATE FUNCTION public.update_manual_receipt(p_line_id uuid, p_date date, p_amount numeric, p_customer_id uuid, p_particulars text, p_tds_amount numeric DEFAULT 0, p_allocations jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_line                public.bank_statement_lines;
    v_old_voucher_number  text;
    v_old_tally_voucher_id text;
    v_new_voucher_number  text;
    v_queue_id            uuid;
    v_config              public.bank_reco_company_config;
    v_alloc_sum           numeric(14,2);
    v_expected            numeric(14,2);
    v_bill_ids            uuid[] := ARRAY[]::uuid[];
    v_inv_id              uuid;
    v_inv_customer        uuid;
    v_alloc               jsonb;
    v_fy_start            int;
    v_fy_label            text;
    v_seq                 bigint;
    v_enq                 jsonb;
    v_cust_active         BOOLEAN;
    v_cust_deleted        TIMESTAMPTZ;
    v_inv_synced          BOOLEAN;
    v_payments_deleted    integer := 0;
    v_existing_voucher    text;
BEGIN
    IF p_amount IS NULL OR p_amount <= 0 THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'INVALID_AMOUNT',
            'error', 'Amount must be greater than zero');
    END IF;
    IF p_customer_id IS NULL THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'CUSTOMER_REQUIRED',
            'error', 'Customer is required');
    END IF;

    SELECT active, deleted_at INTO v_cust_active, v_cust_deleted
    FROM public.customers WHERE id = p_customer_id;

    IF v_cust_active IS NULL THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'CUSTOMER_NOT_FOUND',
            'error', format('Customer %s not found', p_customer_id));
    END IF;
    IF v_cust_deleted IS NOT NULL OR v_cust_active = false THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'CUSTOMER_INACTIVE',
            'error', 'Customer is inactive or deleted — cannot edit receipt');
    END IF;

    SELECT * INTO v_line FROM public.bank_statement_lines WHERE id = p_line_id FOR UPDATE;
    IF v_line.id IS NULL THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'RECEIPT_NOT_FOUND',
            'error', 'Receipt not found');
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM public.bank_statements bs
        WHERE bs.id = v_line.statement_id AND bs.account_number = 'MANUAL'
    ) THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'NOT_MANUAL_RECEIPT',
            'error', 'Not a manual receipt');
    END IF;

    IF v_line.status NOT IN ('reconciled', 'matched', 'queued') THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'RECEIPT_STATE_INVALID',
            'error', format('Cannot edit receipt with status "%s"', v_line.status));
    END IF;

    IF p_allocations IS NOT NULL AND jsonb_array_length(p_allocations) > 0 THEN
        SELECT COALESCE(SUM((a->>'amount')::numeric(14,2)), 0)
        INTO v_alloc_sum FROM jsonb_array_elements(p_allocations) a;

        v_expected := p_amount + COALESCE(p_tds_amount, 0);
        IF ABS(v_alloc_sum - v_expected) > 1.00 THEN
            RETURN jsonb_build_object('success', false,
                'error_code', 'ALLOCATION_MISMATCH',
                'error', format(
                    'Allocation sum (%s) does not match amount (%s) + TDS (%s) = %s (tolerance ₹1.00)',
                    v_alloc_sum, p_amount, COALESCE(p_tds_amount, 0), v_expected
                ));
        END IF;

        FOR v_alloc IN SELECT * FROM jsonb_array_elements(p_allocations)
        LOOP
            v_inv_id := (v_alloc->>'invoice_id')::uuid;
            SELECT customer_id INTO v_inv_customer
            FROM public.invoice WHERE id = v_inv_id AND deleted_at IS NULL;

            IF v_inv_customer IS NULL THEN
                RETURN jsonb_build_object('success', false,
                    'error_code', 'INVOICE_NOT_FOUND',
                    'error', format('Invoice %s not found or deleted', v_inv_id));
            END IF;
            IF v_inv_customer != p_customer_id THEN
                RETURN jsonb_build_object('success', false,
                    'error_code', 'INVOICE_WRONG_CUSTOMER',
                    'error', format('Invoice %s does not belong to customer %s', v_inv_id, p_customer_id));
            END IF;

            SELECT (tally_voucher_id IS NOT NULL) INTO v_inv_synced
            FROM public.tally_vouchers WHERE invoice_id = v_inv_id LIMIT 1;

            IF v_inv_synced IS NULL OR v_inv_synced = false THEN
                RETURN jsonb_build_object('success', false,
                    'error_code', 'INVOICE_NOT_IN_TALLY',
                    'error', format('Invoice %s is not yet synced to Tally. Run the invoice backfill before allocating against this invoice.', v_inv_id));
            END IF;

            v_bill_ids := v_bill_ids || v_inv_id;
        END LOOP;
    END IF;

    SELECT * INTO v_config FROM public.bank_reco_company_config LIMIT 1;
    IF v_config.id IS NULL THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'MISSING_COMPANY_CONFIG',
            'error', 'No company config found');
    END IF;

    -- queued path: receipt already enqueued but middleware hasn't pushed yet.
    -- Update the line, voucher row, and the existing queue row's payload.
    -- Keep voucher_number and queue row intact — no Tally cancel needed.
    IF v_line.status = 'queued' THEN
        SELECT voucher_number INTO v_existing_voucher
        FROM public.tally_receipt_vouchers
        WHERE bank_line_id = p_line_id;

        UPDATE public.bank_statement_lines SET
            tran_date           = p_date,
            credit              = p_amount,
            tds_amount          = COALESCE(p_tds_amount, 0),
            particulars         = COALESCE(p_particulars, 'Manual receipt'),
            matched_customer_id = p_customer_id,
            matched_allocations = CASE WHEN jsonb_array_length(COALESCE(p_allocations,'[]'::jsonb)) > 0 THEN p_allocations ELSE NULL END,
            matched_bill_ids    = CASE WHEN array_length(v_bill_ids, 1) > 0 THEN v_bill_ids ELSE NULL END,
            review_note         = format('edited at %s', now()::text)
        WHERE id = p_line_id;

        UPDATE public.tally_receipt_vouchers SET
            voucher_date     = p_date,
            customer_id      = p_customer_id,
            amount_received  = p_amount,
            tds_amount       = COALESCE(p_tds_amount, 0),
            allocations      = COALESCE(p_allocations, '[]'::jsonb)
        WHERE bank_line_id = p_line_id;

        UPDATE public.tally_sync_queue SET
            payload = jsonb_build_object(
                'line_id',             p_line_id,
                'customer_id',         p_customer_id,
                'voucher_number',      v_existing_voucher,
                'voucher_date',        p_date,
                'bank_account_ledger', v_config.bank_account_ledger,
                'tds_ledger',          v_config.tds_194c_ledger,
                'amount_received',     p_amount,
                'tds_amount',          COALESCE(p_tds_amount, 0),
                'allocations',         COALESCE(p_allocations, '[]'::jsonb),
                'tally_company',       v_config.tally_company
            ),
            updated_at = now()
        WHERE id = v_line.tally_sync_queue_id;

        RETURN jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'line_id',            p_line_id,
                'new_voucher_number', v_existing_voucher,
                'queue_id',           v_line.tally_sync_queue_id,
                'status',             'queued'
            )
        );
    END IF;

    -- reconciled path: already pushed to Tally. Issue new voucher_number,
    -- queue 'update' op so middleware cancels old voucher and creates new.
    IF v_line.status = 'reconciled' THEN
        SELECT voucher_number, tally_voucher_id
        INTO v_old_voucher_number, v_old_tally_voucher_id
        FROM public.tally_receipt_vouchers WHERE bank_line_id = p_line_id;

        IF EXTRACT(MONTH FROM p_date) >= 4 THEN
            v_fy_start := EXTRACT(YEAR FROM p_date)::int;
        ELSE
            v_fy_start := EXTRACT(YEAR FROM p_date)::int - 1;
        END IF;
        v_fy_label := v_fy_start::text || '-' || RIGHT((v_fy_start + 1)::text, 2);

        INSERT INTO public.receipt_voucher_counters (financial_year, next_seq) VALUES (v_fy_label, 2)
        ON CONFLICT (financial_year)
        DO UPDATE SET next_seq = receipt_voucher_counters.next_seq + 1
        RETURNING next_seq - 1 INTO v_seq;

        v_new_voucher_number := 'RCP/' || v_fy_start::text || '/' || lpad(v_seq::text, 5, '0');

        INSERT INTO public.tally_sync_queue (entity_type, entity_id, operation, payload)
        VALUES (
            'receipt', p_line_id, 'update',
            jsonb_build_object(
                'line_id',              p_line_id,
                'old_voucher_number',   v_old_voucher_number,
                'old_tally_voucher_id', v_old_tally_voucher_id,
                'new_voucher_number',   v_new_voucher_number,
                'voucher_date',         p_date,
                'customer_id',          p_customer_id,
                'bank_account_ledger',  v_config.bank_account_ledger,
                'tds_ledger',           v_config.tds_194c_ledger,
                'amount_received',      p_amount,
                'tds_amount',           COALESCE(p_tds_amount, 0),
                'allocations',          COALESCE(p_allocations, '[]'::jsonb),
                'tally_company',        v_config.tally_company
            )
        ) RETURNING id INTO v_queue_id;

        UPDATE public.bank_statement_lines SET
            tran_date           = p_date,
            credit              = p_amount,
            tds_amount          = COALESCE(p_tds_amount, 0),
            particulars         = COALESCE(p_particulars, 'Manual receipt'),
            matched_customer_id = p_customer_id,
            matched_allocations = CASE WHEN jsonb_array_length(COALESCE(p_allocations,'[]'::jsonb)) > 0 THEN p_allocations ELSE NULL END,
            matched_bill_ids    = CASE WHEN array_length(v_bill_ids, 1) > 0 THEN v_bill_ids ELSE NULL END,
            status              = 'queued',
            tally_sync_queue_id = v_queue_id,
            review_note         = format('edited at %s', now()::text)
        WHERE id = p_line_id;

        UPDATE public.tally_receipt_vouchers SET
            voucher_number   = v_new_voucher_number,
            voucher_date     = p_date,
            customer_id      = p_customer_id,
            amount_received  = p_amount,
            tds_amount       = COALESCE(p_tds_amount, 0),
            allocations      = COALESCE(p_allocations, '[]'::jsonb),
            tally_voucher_id = NULL
        WHERE bank_line_id = p_line_id;

        IF v_old_voucher_number IS NOT NULL THEN
            DELETE FROM public.payments
             WHERE payment_no LIKE v_old_voucher_number || '-%';
            GET DIAGNOSTICS v_payments_deleted = ROW_COUNT;
        END IF;

        RETURN jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'line_id',            p_line_id,
                'new_voucher_number', v_new_voucher_number,
                'queue_id',           v_queue_id,
                'old_payments_deleted', v_payments_deleted
            )
        );
    END IF;

    -- matched path: not yet enqueued. Drop voucher row, update line, enqueue fresh.
    DELETE FROM public.tally_receipt_vouchers WHERE bank_line_id = p_line_id;

    UPDATE public.bank_statement_lines SET
        tran_date           = p_date,
        credit              = p_amount,
        tds_amount          = COALESCE(p_tds_amount, 0),
        particulars         = COALESCE(p_particulars, 'Manual receipt'),
        matched_customer_id = p_customer_id,
        matched_allocations = CASE WHEN jsonb_array_length(COALESCE(p_allocations,'[]'::jsonb)) > 0 THEN p_allocations ELSE NULL END,
        matched_bill_ids    = CASE WHEN array_length(v_bill_ids, 1) > 0 THEN v_bill_ids ELSE NULL END,
        status              = 'matched',
        tally_sync_queue_id = NULL,
        review_note         = format('edited at %s', now()::text)
    WHERE id = p_line_id;

    SELECT public.enqueue_receipt_voucher(p_line_id) INTO v_enq;
    IF (v_enq->>'success')::boolean != true THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'ENQUEUE_FAILED',
            'error', 'Failed to enqueue: ' || (v_enq->>'error'));
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'line_id',            p_line_id,
            'new_voucher_number', v_enq->'data'->>'voucher_number',
            'queue_id',           v_enq->'data'->>'queue_id'
        )
    );
END;
$$;


CREATE FUNCTION public.update_manual_receipt(p_line_id uuid, p_date date, p_amount numeric, p_customer_id uuid, p_particulars text, p_tds_amount numeric DEFAULT 0, p_allocations jsonb DEFAULT NULL::jsonb, p_receipt_method text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_line                public.bank_statement_lines;
    v_old_voucher_number  text;
    v_old_tally_voucher_id text;
    v_new_voucher_number  text;
    v_queue_id            uuid;
    v_config              public.bank_reco_company_config;
    v_alloc_sum           numeric(14,2);
    v_expected            numeric(14,2);
    v_bill_ids            uuid[] := ARRAY[]::uuid[];
    v_inv_id              uuid;
    v_inv_customer        uuid;
    v_alloc               jsonb;
    v_fy_start            int;
    v_fy_label            text;
    v_seq                 bigint;
    v_enq                 jsonb;
    v_cust_active         BOOLEAN;
    v_cust_deleted        TIMESTAMPTZ;
    v_inv_synced          BOOLEAN;
    v_payments_deleted    integer := 0;
    v_existing_voucher    text;
    v_method              text;
    v_ledger              text;
BEGIN
    IF p_amount IS NULL OR p_amount <= 0 THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'INVALID_AMOUNT',
            'error', 'Amount must be greater than zero');
    END IF;
    IF p_customer_id IS NULL THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'CUSTOMER_REQUIRED',
            'error', 'Customer is required');
    END IF;

    IF p_receipt_method IS NOT NULL AND p_receipt_method NOT IN ('bank', 'cash') THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'INVALID_RECEIPT_METHOD',
            'error', format('Invalid receipt_method "%s" — must be ''bank'' or ''cash''', p_receipt_method));
    END IF;

    SELECT active, deleted_at INTO v_cust_active, v_cust_deleted
    FROM public.customers WHERE id = p_customer_id;

    IF v_cust_active IS NULL THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'CUSTOMER_NOT_FOUND',
            'error', format('Customer %s not found', p_customer_id));
    END IF;
    IF v_cust_deleted IS NOT NULL OR v_cust_active = false THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'CUSTOMER_INACTIVE',
            'error', 'Customer is inactive or deleted — cannot edit receipt');
    END IF;

    SELECT * INTO v_line FROM public.bank_statement_lines WHERE id = p_line_id FOR UPDATE;
    IF v_line.id IS NULL THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'RECEIPT_NOT_FOUND',
            'error', 'Receipt not found');
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM public.bank_statements bs
        WHERE bs.id = v_line.statement_id AND bs.account_number = 'MANUAL'
    ) THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'NOT_MANUAL_RECEIPT',
            'error', 'Not a manual receipt');
    END IF;

    IF v_line.status NOT IN ('reconciled', 'matched', 'queued') THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'RECEIPT_STATE_INVALID',
            'error', format('Cannot edit receipt with status "%s"', v_line.status));
    END IF;

    -- Effective method: caller's choice or existing value.
    v_method := COALESCE(p_receipt_method, v_line.receipt_method);

    IF p_allocations IS NOT NULL AND jsonb_array_length(p_allocations) > 0 THEN
        SELECT COALESCE(SUM((a->>'amount')::numeric(14,2)), 0)
        INTO v_alloc_sum FROM jsonb_array_elements(p_allocations) a;

        v_expected := p_amount + COALESCE(p_tds_amount, 0);
        IF ABS(v_alloc_sum - v_expected) > 1.00 THEN
            RETURN jsonb_build_object('success', false,
                'error_code', 'ALLOCATION_MISMATCH',
                'error', format(
                    'Allocation sum (%s) does not match amount (%s) + TDS (%s) = %s (tolerance ₹1.00)',
                    v_alloc_sum, p_amount, COALESCE(p_tds_amount, 0), v_expected
                ));
        END IF;

        FOR v_alloc IN SELECT * FROM jsonb_array_elements(p_allocations)
        LOOP
            v_inv_id := (v_alloc->>'invoice_id')::uuid;
            SELECT customer_id INTO v_inv_customer
            FROM public.invoice WHERE id = v_inv_id AND deleted_at IS NULL;

            IF v_inv_customer IS NULL THEN
                RETURN jsonb_build_object('success', false,
                    'error_code', 'INVOICE_NOT_FOUND',
                    'error', format('Invoice %s not found or deleted', v_inv_id));
            END IF;
            IF v_inv_customer != p_customer_id THEN
                RETURN jsonb_build_object('success', false,
                    'error_code', 'INVOICE_WRONG_CUSTOMER',
                    'error', format('Invoice %s does not belong to customer %s', v_inv_id, p_customer_id));
            END IF;

            SELECT (tally_voucher_id IS NOT NULL) INTO v_inv_synced
            FROM public.tally_vouchers WHERE invoice_id = v_inv_id LIMIT 1;

            IF v_inv_synced IS NULL OR v_inv_synced = false THEN
                RETURN jsonb_build_object('success', false,
                    'error_code', 'INVOICE_NOT_IN_TALLY',
                    'error', format('Invoice %s is not yet synced to Tally. Run the invoice backfill before allocating against this invoice.', v_inv_id));
            END IF;

            v_bill_ids := v_bill_ids || v_inv_id;
        END LOOP;
    END IF;

    SELECT * INTO v_config FROM public.bank_reco_company_config LIMIT 1;
    IF v_config.id IS NULL THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'MISSING_COMPANY_CONFIG',
            'error', 'No company config found');
    END IF;

    v_ledger := CASE WHEN v_method = 'cash'
                     THEN v_config.cash_receipt_ledger
                     ELSE v_config.bank_account_ledger
                END;

    -- queued path: middleware hasn't pushed yet. Update line + voucher row +
    -- existing queue row's payload.
    IF v_line.status = 'queued' THEN
        SELECT voucher_number INTO v_existing_voucher
        FROM public.tally_receipt_vouchers
        WHERE bank_line_id = p_line_id;

        UPDATE public.bank_statement_lines SET
            tran_date           = p_date,
            credit              = p_amount,
            tds_amount          = COALESCE(p_tds_amount, 0),
            particulars         = COALESCE(p_particulars, 'Manual receipt'),
            matched_customer_id = p_customer_id,
            matched_allocations = CASE WHEN jsonb_array_length(COALESCE(p_allocations,'[]'::jsonb)) > 0 THEN p_allocations ELSE NULL END,
            matched_bill_ids    = CASE WHEN array_length(v_bill_ids, 1) > 0 THEN v_bill_ids ELSE NULL END,
            receipt_method      = v_method,
            review_note         = format('edited at %s', now()::text)
        WHERE id = p_line_id;

        UPDATE public.tally_receipt_vouchers SET
            voucher_date        = p_date,
            customer_id         = p_customer_id,
            amount_received     = p_amount,
            tds_amount          = COALESCE(p_tds_amount, 0),
            allocations         = COALESCE(p_allocations, '[]'::jsonb),
            bank_account_ledger = v_ledger
        WHERE bank_line_id = p_line_id;

        UPDATE public.tally_sync_queue SET
            payload = jsonb_build_object(
                'line_id',             p_line_id,
                'customer_id',         p_customer_id,
                'voucher_number',      v_existing_voucher,
                'voucher_date',        p_date,
                'bank_account_ledger', v_ledger,
                'tds_ledger',          v_config.tds_194c_ledger,
                'amount_received',     p_amount,
                'tds_amount',          COALESCE(p_tds_amount, 0),
                'allocations',         COALESCE(p_allocations, '[]'::jsonb),
                'tally_company',       v_config.tally_company,
                'receipt_method',      v_method
            ),
            updated_at = now()
        WHERE id = v_line.tally_sync_queue_id;

        RETURN jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'line_id',            p_line_id,
                'new_voucher_number', v_existing_voucher,
                'queue_id',           v_line.tally_sync_queue_id,
                'receipt_method',     v_method,
                'status',             'queued'
            )
        );
    END IF;

    -- reconciled path: already in Tally. New voucher number, queue 'update'
    -- op so middleware cancels old voucher and creates new.
    IF v_line.status = 'reconciled' THEN
        SELECT voucher_number, tally_voucher_id
        INTO v_old_voucher_number, v_old_tally_voucher_id
        FROM public.tally_receipt_vouchers WHERE bank_line_id = p_line_id;

        IF EXTRACT(MONTH FROM p_date) >= 4 THEN
            v_fy_start := EXTRACT(YEAR FROM p_date)::int;
        ELSE
            v_fy_start := EXTRACT(YEAR FROM p_date)::int - 1;
        END IF;
        v_fy_label := v_fy_start::text || '-' || RIGHT((v_fy_start + 1)::text, 2);

        INSERT INTO public.receipt_voucher_counters (financial_year, next_seq) VALUES (v_fy_label, 2)
        ON CONFLICT (financial_year)
        DO UPDATE SET next_seq = receipt_voucher_counters.next_seq + 1
        RETURNING next_seq - 1 INTO v_seq;

        v_new_voucher_number := 'RCP/' || v_fy_start::text || '/' || lpad(v_seq::text, 5, '0');

        INSERT INTO public.tally_sync_queue (entity_type, entity_id, operation, payload)
        VALUES (
            'receipt', p_line_id, 'update',
            jsonb_build_object(
                'line_id',              p_line_id,
                'old_voucher_number',   v_old_voucher_number,
                'old_tally_voucher_id', v_old_tally_voucher_id,
                'new_voucher_number',   v_new_voucher_number,
                'voucher_date',         p_date,
                'customer_id',          p_customer_id,
                'bank_account_ledger',  v_ledger,
                'tds_ledger',           v_config.tds_194c_ledger,
                'amount_received',      p_amount,
                'tds_amount',           COALESCE(p_tds_amount, 0),
                'allocations',          COALESCE(p_allocations, '[]'::jsonb),
                'tally_company',        v_config.tally_company,
                'receipt_method',       v_method
            )
        ) RETURNING id INTO v_queue_id;

        UPDATE public.bank_statement_lines SET
            tran_date           = p_date,
            credit              = p_amount,
            tds_amount          = COALESCE(p_tds_amount, 0),
            particulars         = COALESCE(p_particulars, 'Manual receipt'),
            matched_customer_id = p_customer_id,
            matched_allocations = CASE WHEN jsonb_array_length(COALESCE(p_allocations,'[]'::jsonb)) > 0 THEN p_allocations ELSE NULL END,
            matched_bill_ids    = CASE WHEN array_length(v_bill_ids, 1) > 0 THEN v_bill_ids ELSE NULL END,
            status              = 'queued',
            tally_sync_queue_id = v_queue_id,
            receipt_method      = v_method,
            review_note         = format('edited at %s', now()::text)
        WHERE id = p_line_id;

        UPDATE public.tally_receipt_vouchers SET
            voucher_number      = v_new_voucher_number,
            voucher_date        = p_date,
            customer_id         = p_customer_id,
            amount_received     = p_amount,
            tds_amount          = COALESCE(p_tds_amount, 0),
            allocations         = COALESCE(p_allocations, '[]'::jsonb),
            tally_voucher_id    = NULL,
            bank_account_ledger = v_ledger
        WHERE bank_line_id = p_line_id;

        IF v_old_voucher_number IS NOT NULL THEN
            DELETE FROM public.payments
             WHERE payment_no LIKE v_old_voucher_number || '-%';
            GET DIAGNOSTICS v_payments_deleted = ROW_COUNT;
        END IF;

        RETURN jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'line_id',              p_line_id,
                'new_voucher_number',   v_new_voucher_number,
                'queue_id',             v_queue_id,
                'receipt_method',       v_method,
                'old_payments_deleted', v_payments_deleted
            )
        );
    END IF;

    -- matched path: not enqueued yet. Drop voucher row, update line, re-enqueue.
    DELETE FROM public.tally_receipt_vouchers WHERE bank_line_id = p_line_id;

    UPDATE public.bank_statement_lines SET
        tran_date           = p_date,
        credit              = p_amount,
        tds_amount          = COALESCE(p_tds_amount, 0),
        particulars         = COALESCE(p_particulars, 'Manual receipt'),
        matched_customer_id = p_customer_id,
        matched_allocations = CASE WHEN jsonb_array_length(COALESCE(p_allocations,'[]'::jsonb)) > 0 THEN p_allocations ELSE NULL END,
        matched_bill_ids    = CASE WHEN array_length(v_bill_ids, 1) > 0 THEN v_bill_ids ELSE NULL END,
        status              = 'matched',
        tally_sync_queue_id = NULL,
        receipt_method      = v_method,
        review_note         = format('edited at %s', now()::text)
    WHERE id = p_line_id;

    SELECT public.enqueue_receipt_voucher(p_line_id) INTO v_enq;
    IF (v_enq->>'success')::boolean != true THEN
        RETURN jsonb_build_object('success', false,
            'error_code', 'ENQUEUE_FAILED',
            'error', 'Failed to enqueue: ' || (v_enq->>'error'));
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'line_id',            p_line_id,
            'new_voucher_number', v_enq->'data'->>'voucher_number',
            'queue_id',           v_enq->'data'->>'queue_id',
            'receipt_method',     v_method
        )
    );
END;
$$;


CREATE FUNCTION public.update_middleware_status(p_is_ready boolean, p_tally_reachable boolean, p_company_open boolean, p_company text, p_last_check timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    UPDATE public.tally_middleware_status SET
        is_ready        = p_is_ready,
        tally_reachable = p_tally_reachable,
        company_open    = p_company_open,
        company         = p_company,
        last_check      = p_last_check,
        updated_at      = now()
    WHERE id = 1;
    RETURN jsonb_build_object('success', true);
END;
$$;


CREATE FUNCTION public.update_order(p_order_id uuid, p_order_data jsonb, p_items jsonb, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM orders WHERE id = p_order_id) THEN
        RETURN utils.not_found_response('Order', p_order_id::text);
    END IF;

    -- Update order fields if provided
    UPDATE orders SET
        note = COALESCE(p_order_data->>'note', note),
        priority = COALESCE(p_order_data->>'priority', priority),
        requested_dispatch_date = COALESCE((p_order_data->>'requested_dispatch_date')::timestamp, requested_dispatch_date),
        updated_at = NOW(),
        updated_by = p_user_id
    WHERE id = p_order_id;

    RETURN utils.success_response(jsonb_build_object('order_id', p_order_id), 'Order updated successfully');
EXCEPTION
    WHEN OTHERS THEN
        RETURN utils.database_error_response('Failed to update order', SQLERRM, SQLSTATE);
END;
$$;


CREATE FUNCTION public.update_order_after_dispatch_creation(p_dispatch_id uuid, p_source_order_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_order RECORD;
    v_new_status text;
    v_fulfillment_pct numeric;
BEGIN
    SELECT * INTO v_order FROM orders WHERE id = p_source_order_id;
    IF v_order IS NULL THEN
        RETURN utils.not_found_response('Order', p_source_order_id::text);
    END IF;

    -- Calculate fulfillment percentage
    SELECT COALESCE(SUM(oi.fulfilled_quantity)::numeric / NULLIF(SUM(oi.requested_quantity), 0) * 100, 0)
    INTO v_fulfillment_pct
    FROM order_items oi WHERE oi.order_id = p_source_order_id;

    -- Determine new status
    IF v_fulfillment_pct >= 100 THEN
        v_new_status := 'fulfilled';
    ELSIF v_fulfillment_pct > 0 THEN
        v_new_status := 'partially_fulfilled';
    ELSE
        v_new_status := 'pending';
    END IF;

    UPDATE orders SET
        status = v_new_status,
        fulfillment_percentage = v_fulfillment_pct,
        fulfilled_at = CASE WHEN v_new_status = 'fulfilled' THEN NOW() ELSE NULL END,
        updated_at = NOW()
    WHERE id = p_source_order_id;

    RETURN utils.success_response(
        jsonb_build_object('order_status', v_new_status, 'fulfillment_percentage', v_fulfillment_pct),
        'Order status updated'
    );
EXCEPTION
    WHEN OTHERS THEN
        RETURN utils.database_error_response('Failed to update order after dispatch', SQLERRM, SQLSTATE);
END;
$$;


CREATE FUNCTION public.update_order_item_quantity(p_order_item_id uuid, p_new_quantity integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_order_id UUID;
      v_old_quantity INTEGER;
      v_cart_items JSONB;
      v_user_id UUID;
      v_item_details RECORD;
  BEGIN
      -- Get authenticated user
      SELECT id INTO v_user_id FROM user_profiles WHERE auth_user_id = auth.uid();
      IF v_user_id IS NULL THEN
          RETURN jsonb_build_object('success', false, 'message', 'User not authenticated');
      END IF;

      -- Get current item details and validate
      SELECT
          oi.order_id,
          oi.requested_quantity,
          oi.grn_items_item_name,
          oi.grns_gr_no,
          oi.grn_items_package_mark,
          o.customer_id
      INTO v_item_details
      FROM order_items oi
      JOIN orders o ON o.id = oi.order_id
      WHERE oi.id = p_order_item_id;

      IF NOT FOUND THEN
          RETURN jsonb_build_object('success', false, 'message', 'Order item not found');
      END IF;

      -- Check permissions
      IF NOT is_admin_or_supervisor() THEN
          IF v_item_details.customer_id != ANY(user_accessible_customers()) THEN
              RETURN jsonb_build_object('success', false, 'message', 'Access denied');
          END IF;
      END IF;

      v_order_id := v_item_details.order_id;
      v_old_quantity := v_item_details.requested_quantity;

      -- Update order_item
      UPDATE order_items
      SET
          requested_quantity = p_new_quantity,
          updated_at = NOW()
      WHERE id = p_order_item_id;

      -- Get all cart items after update
      SELECT jsonb_agg(
          jsonb_build_object(
              'item_id', grn_items_item_id,
              'item_name', grn_items_item_name,
              'quantity', requested_quantity,
              'grn_no', grns_gr_no,
              'package_mark', grn_items_package_mark
          ) ORDER BY sort_order
      ) INTO v_cart_items
      FROM order_items
      WHERE order_id = v_order_id;

      -- Update order with revision
      UPDATE orders
      SET
          revisions = revisions || jsonb_build_array(
              jsonb_build_object(
                  'at', NOW(),
                  'by', v_user_id,
                  'action', 'UPDATE',
                  'cart_items', COALESCE(v_cart_items, '[]'::jsonb),
                  'changes', jsonb_build_object(
                      'note', note,
                      'priority', priority,
                      'requested_dispatch_date', requested_dispatch_date
                  )
              )
          ),
          updated_at = NOW(),
          updated_by = v_user_id
      WHERE id = v_order_id;

      RETURN jsonb_build_object(
          'success', true,
          'message', 'Quantity updated successfully',
          'data', jsonb_build_object(
              'order_item_id', p_order_item_id,
              'old_quantity', v_old_quantity,
              'new_quantity', p_new_quantity,
              'item_name', v_item_details.grn_items_item_name
          )
      );
  EXCEPTION
      WHEN OTHERS THEN
          RETURN jsonb_build_object(
              'success', false,
              'message', 'Error updating quantity: ' || SQLERRM
          );
  END;
  $$;


CREATE FUNCTION public.update_order_items_batch(p_order_id uuid, p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_user_id UUID;
      v_order_record RECORD;
      v_cart_items JSONB;
      v_item JSONB;
      v_update_count INTEGER := 0;
  BEGIN
      -- Get authenticated user
      SELECT id INTO v_user_id FROM user_profiles WHERE auth_user_id = auth.uid();
      IF v_user_id IS NULL THEN
          RETURN jsonb_build_object('success', false, 'message', 'User not authenticated');
      END IF;

      -- Validate order and check permissions
      SELECT * INTO v_order_record
      FROM orders
      WHERE id = p_order_id;

      IF NOT FOUND THEN
          RETURN jsonb_build_object('success', false, 'message', 'Order not found');
      END IF;

      -- Check permissions
      IF NOT is_admin_or_supervisor() THEN
          IF v_order_record.customer_id != ANY(user_accessible_customers()) THEN
              RETURN jsonb_build_object('success', false, 'message', 'Access denied');
          END IF;
      END IF;

      -- Update each item
      FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
      LOOP
          UPDATE order_items
          SET
              requested_quantity = (v_item->>'quantity')::INTEGER,
              updated_at = NOW()
          WHERE id = (v_item->>'order_item_id')::UUID
          AND order_id = p_order_id;

          v_update_count := v_update_count + 1;
      END LOOP;

      -- Get updated cart items
      SELECT jsonb_agg(
          jsonb_build_object(
              'item_id', grn_items_item_id,
              'item_name', grn_items_item_name,
              'quantity', requested_quantity,
              'grn_no', grns_gr_no,
              'package_mark', grn_items_package_mark
          ) ORDER BY sort_order
      ) INTO v_cart_items
      FROM order_items
      WHERE order_id = p_order_id;

      -- Update order with revision
      UPDATE orders
      SET
          revisions = revisions || jsonb_build_array(
              jsonb_build_object(
                  'at', NOW(),
                  'by', v_user_id,
                  'action', 'UPDATE',
                  'cart_items', COALESCE(v_cart_items, '[]'::jsonb),
                  'changes', jsonb_build_object(
                      'note', note,
                      'priority', priority,
                      'requested_dispatch_date', requested_dispatch_date,
                      'batch_update', true,
                      'items_updated', v_update_count
                  )
              )
          ),
          updated_at = NOW(),
          updated_by = v_user_id
      WHERE id = p_order_id;

      RETURN jsonb_build_object(
          'success', true,
          'message', format('%s items updated successfully', v_update_count),
          'data', jsonb_build_object(
              'items_updated', v_update_count
          )
      );
  EXCEPTION
      WHEN OTHERS THEN
          RETURN jsonb_build_object(
              'success', false,
              'message', 'Error in batch update: ' || SQLERRM
          );
  END;
  $$;


CREATE FUNCTION public.update_order_metadata(p_order_id uuid, p_note text DEFAULT NULL::text, p_priority text DEFAULT NULL::text, p_requested_dispatch_date timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_user_id UUID;
      v_order_record RECORD;
      v_cart_items JSONB;
  BEGIN
      -- Get authenticated user
      SELECT id INTO v_user_id FROM user_profiles WHERE auth_user_id = auth.uid();
      IF v_user_id IS NULL THEN
          RETURN jsonb_build_object('success', false, 'message', 'User not authenticated');
      END IF;

      -- Validate order and check permissions
      SELECT * INTO v_order_record
      FROM orders
      WHERE id = p_order_id;

      IF NOT FOUND THEN
          RETURN jsonb_build_object('success', false, 'message', 'Order not found');
      END IF;

      -- Check permissions
      IF NOT is_admin_or_supervisor() THEN
          IF v_order_record.customer_id != ANY(user_accessible_customers()) THEN
              RETURN jsonb_build_object('success', false, 'message', 'Access denied');
          END IF;
      END IF;

      -- Get current cart items
      SELECT jsonb_agg(
          jsonb_build_object(
              'item_id', grn_items_item_id,
              'item_name', grn_items_item_name,
              'quantity', requested_quantity,
              'grn_no', grns_gr_no,
              'package_mark', grn_items_package_mark
          ) ORDER BY sort_order
      ) INTO v_cart_items
      FROM order_items
      WHERE order_id = p_order_id;

      -- Update order with revision
      UPDATE orders
      SET
          note = COALESCE(p_note, note),
          priority = COALESCE(p_priority, priority),
          requested_dispatch_date = COALESCE(p_requested_dispatch_date, requested_dispatch_date),
          revisions = revisions || jsonb_build_array(
              jsonb_build_object(
                  'at', NOW(),
                  'by', v_user_id,
                  'action', 'UPDATE',
                  'cart_items', COALESCE(v_cart_items, '[]'::jsonb),
                  'changes', jsonb_build_object(
                      'note', COALESCE(p_note, note),
                      'priority', COALESCE(p_priority, priority),
                      'requested_dispatch_date', COALESCE(p_requested_dispatch_date, requested_dispatch_date)
                  )
              )
          ),
          updated_at = NOW(),
          updated_by = v_user_id
      WHERE id = p_order_id;

      RETURN jsonb_build_object(
          'success', true,
          'message', 'Order metadata updated successfully'
      );
  EXCEPTION
      WHEN OTHERS THEN
          RETURN jsonb_build_object(
              'success', false,
              'message', 'Error updating order metadata: ' || SQLERRM
          );
  END;
  $$;


CREATE FUNCTION public.update_order_updated_at_on_item_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_order_id UUID;
BEGIN
    -- Get the order_id depending on operation
    IF TG_OP = 'DELETE' THEN
        v_order_id := OLD.order_id;
    ELSE
        v_order_id := NEW.order_id;
    END IF;

    -- Update the parent order's updated_at
    UPDATE orders
    SET updated_at = NOW()
    WHERE id = v_order_id;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    ELSE
        RETURN NEW;
    END IF;
END;
$$;


CREATE FUNCTION public.update_sensor(p_device_mac character varying, p_device_name text DEFAULT NULL::text, p_location text DEFAULT NULL::text, p_staleness_threshold_minutes integer DEFAULT NULL::integer, p_alert_config jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_sensor_id UUID;
    v_old_name TEXT;
    v_new_name TEXT;
BEGIN
    -- Get current device name
    SELECT id, device_name INTO v_sensor_id, v_old_name
    FROM sensor_devices
    WHERE mac_address = p_device_mac;

    IF v_sensor_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', null,
            'message', 'Sensor not found',
            'error', jsonb_build_object('code', 'SENSOR_NOT_FOUND')
        );
    END IF;

    -- Update sensor registry
    UPDATE sensor_devices
    SET
        device_name = COALESCE(p_device_name, device_name),
        location = COALESCE(p_location, location),
        staleness_threshold_minutes = COALESCE(p_staleness_threshold_minutes, staleness_threshold_minutes),
        alert_config = COALESCE(p_alert_config, alert_config),
        updated_at = NOW()
    WHERE mac_address = p_device_mac
    RETURNING device_name INTO v_new_name;

    -- Log update event if name changed
    IF p_device_name IS NOT NULL AND v_old_name != v_new_name THEN
        INSERT INTO sensor_health_events (
            device_id,
            device_mac,
            device_name,
            event_type,
            severity,
            event_message,
            old_value,
            new_value
        ) VALUES (
            v_sensor_id,
            p_device_mac,
            v_new_name,
            'SENSOR_UPDATED',
            'INFO',
            'Sensor metadata updated',
            v_old_name,
            v_new_name
        );
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object('sensor_id', v_sensor_id),
        'message', 'Sensor updated successfully'
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', null,
            'message', SQLERRM,
            'error', jsonb_build_object('code', 'DATABASE_ERROR')
        );
END;
$$;


CREATE FUNCTION public.update_service_credentials(p_service_name character varying, p_credentials jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result JSONB;
BEGIN
    -- Check if user is admin
    IF NOT EXISTS (
        SELECT 1 FROM user_profiles
        WHERE auth_user_id = auth.uid()
        AND role = 'admin'
    ) THEN
        RAISE EXCEPTION 'Only admins can update service credentials';
    END IF;

    -- Update or insert credentials
    INSERT INTO public.secrets_vault (service_name, credentials, is_active, updated_at)
    VALUES (p_service_name, p_credentials, true, NOW())
    ON CONFLICT (service_name) DO UPDATE SET
        credentials = EXCLUDED.credentials,
        updated_at = NOW()
    RETURNING jsonb_build_object(
        'success', true,
        'service_name', service_name,
        'updated_at', updated_at
    ) INTO v_result;

    RETURN v_result;
END;
$$;


CREATE FUNCTION public.update_tally_sync_status(p_queue_id uuid, p_status text, p_error_message text DEFAULT NULL::text, p_next_retry_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_request_xml text DEFAULT NULL::text, p_response_xml text DEFAULT NULL::text, p_duration_ms integer DEFAULT NULL::integer, p_error_details jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_item             public.tally_sync_queue;
    v_effective_status TEXT := p_status;
    v_error_class      TEXT;
BEGIN
    SELECT * INTO v_item FROM public.tally_sync_queue WHERE id = p_queue_id;

    IF v_item.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Queue item not found');
    END IF;

    -- Permanent errors short-circuit to dead_letter, no point burning retries
    v_error_class := COALESCE(p_error_details->>'error_class', '');
    IF v_error_class = 'permanent'
       AND p_status IN ('retry', 'failed') THEN
        v_effective_status := 'dead_letter';
    END IF;

    UPDATE public.tally_sync_queue
    SET status        = v_effective_status,
        error_message = COALESCE(p_error_message, error_message),
        retry_count   = CASE WHEN v_effective_status IN ('retry', 'failed', 'dead_letter') THEN retry_count + 1 ELSE retry_count END,
        next_retry_at = CASE WHEN v_effective_status = 'retry' THEN p_next_retry_at ELSE NULL END,
        completed_at  = CASE WHEN v_effective_status = 'confirmed' THEN now() ELSE completed_at END,
        locked_by     = CASE WHEN v_effective_status IN ('confirmed', 'failed', 'dead_letter') THEN NULL ELSE locked_by END,
        locked_at     = CASE WHEN v_effective_status IN ('confirmed', 'failed', 'dead_letter') THEN NULL ELSE locked_at END,
        request_xml   = COALESCE(p_request_xml,   request_xml),
        response_xml  = COALESCE(p_response_xml,  response_xml),
        error_details = COALESCE(p_error_details, error_details),
        updated_at    = now()
    WHERE id = p_queue_id;

    -- Log the attempt (immutable audit trail)
    INSERT INTO public.tally_sync_log (queue_id, attempt_number, status, request_xml, response_xml, error_details, duration_ms)
    VALUES (
        p_queue_id,
        v_item.retry_count + 1,
        CASE WHEN v_effective_status = 'confirmed' THEN 'success' ELSE 'error' END,
        p_request_xml,
        p_response_xml,
        p_error_details,
        p_duration_ms
    );

    RETURN jsonb_build_object(
        'success',          true,
        'effective_status', v_effective_status,
        'overridden',       v_effective_status <> p_status
    );
END;
$$;


CREATE FUNCTION public.update_updated_at_column() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$;


CREATE FUNCTION public.update_user_role(p_user_id uuid, p_new_role public.user_role) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_auth_uid UUID;
    v_caller_id UUID;
    v_caller_role user_role;
    v_target_id UUID;
    v_old_role user_role;
BEGIN
    -- Cache auth.uid()
    v_auth_uid := auth.uid();

    -- Get caller's profile
    SELECT id, role INTO v_caller_id, v_caller_role
    FROM user_profiles
    WHERE auth_user_id = v_auth_uid AND active = true;

    -- Authorization: must be admin or supervisor
    IF v_caller_role IS NULL OR v_caller_role NOT IN ('admin', 'supervisor') THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'PERMISSION_DENIED',
            'message', 'Only administrators and supervisors can change user roles'
        );
    END IF;

    -- Validate user_id
    IF p_user_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'INVALID_INPUT',
            'message', 'User ID is required'
        );
    END IF;

    -- Validate new_role
    IF p_new_role IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'INVALID_INPUT',
            'message', 'New role is required'
        );
    END IF;

    -- Get target user
    SELECT id, role INTO v_target_id, v_old_role
    FROM user_profiles
    WHERE id = p_user_id;

    IF v_target_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'NOT_FOUND',
            'message', 'User not found'
        );
    END IF;

    -- Users cannot change their own role
    IF v_caller_id = v_target_id THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'SELF_EDIT_FORBIDDEN',
            'message', 'You cannot change your own role'
        );
    END IF;

    -- Supervisors cannot modify admin users
    IF v_caller_role = 'supervisor' AND v_old_role = 'admin' THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'PERMISSION_DENIED',
            'message', 'Supervisors cannot modify admin users'
        );
    END IF;

    -- Supervisors cannot set role to admin
    IF v_caller_role = 'supervisor' AND p_new_role = 'admin' THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'CANNOT_PROMOTE_TO_ADMIN',
            'message', 'Supervisors cannot promote users to admin role'
        );
    END IF;

    -- No change needed
    IF v_old_role = p_new_role THEN
        RETURN jsonb_build_object(
            'success', true,
            'user_id', p_user_id,
            'old_role', v_old_role,
            'new_role', p_new_role,
            'message', 'Role unchanged'
        );
    END IF;

    -- Update the role
    UPDATE user_profiles
    SET role = p_new_role,
        updated_at = now()
    WHERE id = p_user_id;

    RETURN jsonb_build_object(
        'success', true,
        'user_id', p_user_id,
        'old_role', v_old_role,
        'new_role', p_new_role,
        'message', 'Role updated successfully'
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'INTERNAL_ERROR',
            'message', 'Failed to update user role: ' || SQLERRM
        );
END;
$$;


CREATE FUNCTION public.update_user_status(p_user_id uuid, p_active boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_auth_uid UUID;
    v_caller_id UUID;
    v_caller_role user_role;
    v_target_id UUID;
    v_target_role user_role;
    v_old_active BOOLEAN;
BEGIN
    -- Cache auth.uid()
    v_auth_uid := auth.uid();

    -- Get caller's profile
    SELECT id, role INTO v_caller_id, v_caller_role
    FROM user_profiles
    WHERE auth_user_id = v_auth_uid AND active = true;

    -- Authorization: must be admin or supervisor
    IF v_caller_role IS NULL OR v_caller_role NOT IN ('admin', 'supervisor') THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'PERMISSION_DENIED',
            'message', 'Only administrators and supervisors can change user status'
        );
    END IF;

    -- Validate user_id
    IF p_user_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'INVALID_INPUT',
            'message', 'User ID is required'
        );
    END IF;

    -- Validate p_active
    IF p_active IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'INVALID_INPUT',
            'message', 'Active status is required'
        );
    END IF;

    -- Get target user
    SELECT id, role, active INTO v_target_id, v_target_role, v_old_active
    FROM user_profiles
    WHERE id = p_user_id;

    IF v_target_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'NOT_FOUND',
            'message', 'User not found'
        );
    END IF;

    -- Users cannot deactivate themselves
    IF v_caller_id = v_target_id THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'SELF_EDIT_FORBIDDEN',
            'message', 'You cannot change your own status'
        );
    END IF;

    -- Supervisors cannot modify admin users
    IF v_caller_role = 'supervisor' AND v_target_role = 'admin' THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'CANNOT_MODIFY_ADMIN',
            'message', 'Supervisors cannot modify admin users'
        );
    END IF;

    -- No change needed
    IF v_old_active = p_active THEN
        RETURN jsonb_build_object(
            'success', true,
            'user_id', p_user_id,
            'active', p_active,
            'message', 'Status unchanged'
        );
    END IF;

    -- Update the status
    UPDATE user_profiles
    SET active = p_active,
        updated_at = now()
    WHERE id = p_user_id;

    RETURN jsonb_build_object(
        'success', true,
        'user_id', p_user_id,
        'active', p_active,
        'message', CASE WHEN p_active THEN 'User activated successfully' ELSE 'User deactivated successfully' END
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'INTERNAL_ERROR',
            'message', 'Failed to update user status: ' || SQLERRM
        );
END;
$$;


CREATE FUNCTION public.upload_dispatch_image(p_dispatch_id uuid, p_storage_path text, p_original_filename text, p_file_size integer, p_mime_type character varying, p_image_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_image_id UUID;
    v_user_id UUID;
    v_user_profile_id UUID;
BEGIN
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN RETURN utils.not_authenticated_response(); END IF;

    SELECT id INTO v_user_profile_id FROM user_profiles WHERE auth_user_id = v_user_id;
    IF v_user_profile_id IS NULL THEN RETURN utils.error_response('USER_PROFILE_NOT_FOUND', 'User profile not found.'); END IF;

    IF p_dispatch_id IS NULL OR p_storage_path IS NULL THEN
        RETURN utils.validation_error_response('parameters', 'Missing required parameters');
    END IF;

    v_image_id := COALESCE(p_image_id, gen_random_uuid());

    INSERT INTO dispatch_images (id, dispatch_id, storage_path, original_filename, file_size, mime_type, uploaded_by)
    VALUES (v_image_id, p_dispatch_id, p_storage_path, p_original_filename, p_file_size, p_mime_type, v_user_profile_id);

    RETURN utils.success_response(
        jsonb_build_object('image_id', v_image_id, 'dispatch_id', p_dispatch_id, 'storage_path', p_storage_path, 'uploaded_by', v_user_profile_id),
        'Image uploaded successfully'
    );
EXCEPTION
    WHEN foreign_key_violation THEN RETURN utils.error_response('FOREIGN_KEY_ERROR', 'Database constraint error.');
    WHEN unique_violation THEN RETURN utils.error_response('DUPLICATE_IMAGE_ID', 'Image ID already exists.');
    WHEN OTHERS THEN RETURN utils.database_error_response('Failed to upload image', SQLERRM, SQLSTATE);
END;
$$;


CREATE FUNCTION public.upload_grn_image(p_grn_id uuid, p_image_type character varying, p_storage_path text, p_original_filename text, p_file_size integer, p_mime_type character varying, p_grn_item_id uuid DEFAULT NULL::uuid, p_image_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_image_id UUID;
    v_user_id UUID;
    v_user_profile_id UUID;
BEGIN
    v_user_id := auth.uid();

    IF v_user_id IS NULL THEN
        RETURN utils.not_authenticated_response();
    END IF;

    SELECT id INTO v_user_profile_id FROM user_profiles WHERE auth_user_id = v_user_id;

    IF v_user_profile_id IS NULL THEN
        RETURN utils.error_response('USER_PROFILE_NOT_FOUND', 'User profile not found. Please contact support.');
    END IF;

    IF p_grn_id IS NULL OR p_image_type IS NULL OR p_storage_path IS NULL THEN
        RETURN utils.validation_error_response('parameters', 'Missing required parameters');
    END IF;

    v_image_id := COALESCE(p_image_id, gen_random_uuid());

    INSERT INTO grn_images (id, grn_id, grn_item_id, image_type, storage_path, original_filename, file_size, mime_type, uploaded_by)
    VALUES (v_image_id, p_grn_id, p_grn_item_id, p_image_type, p_storage_path, p_original_filename, p_file_size, p_mime_type, v_user_profile_id);

    RETURN utils.success_response(
        jsonb_build_object('image_id', v_image_id, 'grn_id', p_grn_id, 'storage_path', p_storage_path, 'uploaded_by', v_user_profile_id),
        'Image uploaded successfully'
    );
EXCEPTION
    WHEN foreign_key_violation THEN
        RETURN utils.error_response('FOREIGN_KEY_ERROR', 'Database constraint error. Please check your data.');
    WHEN unique_violation THEN
        RETURN utils.error_response('DUPLICATE_IMAGE_ID', 'Image ID already exists. Please try again.');
    WHEN OTHERS THEN
        RETURN utils.database_error_response('Failed to upload image', SQLERRM, SQLSTATE);
END;
$$;


CREATE FUNCTION public.upsert_tally_ledger_map(p_customer_id uuid, p_tally_ledger_name character varying, p_tally_company character varying DEFAULT public.get_tally_company(), p_ledger_group character varying DEFAULT 'Sundry Debtors'::character varying, p_gst_number character varying DEFAULT NULL::character varying, p_auto_created boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    INSERT INTO public.tally_ledger_map (
        customer_id, tally_ledger_name, tally_company, ledger_group, gst_number, auto_created
    ) VALUES (
        p_customer_id, p_tally_ledger_name, p_tally_company, p_ledger_group, p_gst_number, p_auto_created
    )
    ON CONFLICT (customer_id, tally_company)
    DO UPDATE SET
        gst_number = COALESCE(EXCLUDED.gst_number, tally_ledger_map.gst_number),
        updated_at = now();

    RETURN jsonb_build_object('success', true);
END;
$$;


CREATE FUNCTION public.user_accessible_customers() RETURNS uuid[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_auth_uid uuid;
    v_user_profile_id uuid;
    v_role user_role;
BEGIN
    -- Cache auth.uid() ONCE at the start
    v_auth_uid := (SELECT auth.uid());

    -- Get the user profile ID and role for the current authenticated user
    SELECT id, role INTO v_user_profile_id, v_role
    FROM user_profiles
    WHERE auth_user_id = v_auth_uid AND active = true;

    -- If user not found, return empty array
    IF v_user_profile_id IS NULL THEN
        RETURN ARRAY[]::uuid[];
    END IF;

    -- If admin, supervisor, or staff, return all active customers (inline check, no function call)
    IF v_role IN ('admin', 'supervisor', 'staff') THEN
        RETURN ARRAY(
            SELECT id FROM customers WHERE active = true
        );
    END IF;

    -- Otherwise return only assigned customers (using new table structure)
    RETURN ARRAY(
        SELECT uc.customer_id
        FROM users_customers_new uc
        WHERE uc.user_profile_id = v_user_profile_id AND uc.active = true
    );
END;
$$;


CREATE FUNCTION public.validate_date_range(p_value timestamp with time zone, p_field_name text, p_min_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_max_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_allow_null boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
    -- Check null
    IF p_value IS NULL THEN
        IF NOT p_allow_null THEN
            RETURN jsonb_build_object(
                'valid', FALSE,
                'field', p_field_name,
                'error', format('%s is required (cannot be null)', p_field_name)
            );
        ELSE
            RETURN jsonb_build_object('valid', TRUE, 'field', p_field_name);
        END IF;
    END IF;

    -- Check minimum date
    IF p_min_date IS NOT NULL AND p_value < p_min_date THEN
        RETURN jsonb_build_object(
            'valid', FALSE,
            'field', p_field_name,
            'error', format('%s must be after %s. Got: %s',
                p_field_name, p_min_date, p_value)
        );
    END IF;

    -- Check maximum date
    IF p_max_date IS NOT NULL AND p_value > p_max_date THEN
        RETURN jsonb_build_object(
            'valid', FALSE,
            'field', p_field_name,
            'error', format('%s must be before %s. Got: %s',
                p_field_name, p_max_date, p_value)
        );
    END IF;

    RETURN jsonb_build_object('valid', TRUE, 'field', p_field_name);
END;
$$;


CREATE FUNCTION public.validate_dispatch_input(p_dispatch_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_errors JSONB := '[]'::JSONB;
    v_result JSONB;
    v_customer_id TEXT;
    v_disp_date TEXT;
    v_customer_name TEXT;
    v_supervisor_id TEXT;
    v_disp_no TEXT;
BEGIN
    -- Extract values using EXACT field names that INSERT uses
    v_disp_no := p_dispatch_data->>'disp_no';
    v_customer_id := p_dispatch_data->>'customer_id';
    v_disp_date := p_dispatch_data->>'disp_date';
    v_customer_name := p_dispatch_data->>'customer_name';
    v_supervisor_id := p_dispatch_data->>'supervisor_id';

    -- Validate disp_no - REQUIRED (used by INSERT)
    IF v_disp_no IS NULL OR v_disp_no = '' THEN
        v_errors := v_errors || jsonb_build_object(
            'field', 'disp_no',
            'error', 'disp_no is required'
        );
    END IF;

    -- Validate customer_id (UUID) - REQUIRED
    IF v_customer_id IS NULL OR v_customer_id = '' THEN
        v_errors := v_errors || jsonb_build_object(
            'field', 'customer_id',
            'error', 'customer_id is required'
        );
    ELSE
        v_result := validate_uuid(v_customer_id, 'customer_id');
        IF NOT (v_result->>'valid')::BOOLEAN THEN
            v_errors := v_errors || v_result;
        END IF;
    END IF;

    -- Validate disp_date - REQUIRED (must be exactly 'disp_date')
    IF v_disp_date IS NULL OR v_disp_date = '' THEN
        v_errors := v_errors || jsonb_build_object(
            'field', 'disp_date',
            'error', 'disp_date is required (must use field name "disp_date")'
        );
    END IF;

    -- Validate customer_name - REQUIRED
    IF v_customer_name IS NULL OR v_customer_name = '' THEN
        v_errors := v_errors || jsonb_build_object(
            'field', 'customer_name',
            'error', 'customer_name is required'
        );
    END IF;

    -- Validate supervisor_id (UUID) - REQUIRED
    IF v_supervisor_id IS NULL OR v_supervisor_id = '' THEN
        v_errors := v_errors || jsonb_build_object(
            'field', 'supervisor_id',
            'error', 'supervisor_id is required'
        );
    ELSE
        v_result := validate_uuid(v_supervisor_id, 'supervisor_id');
        IF NOT (v_result->>'valid')::BOOLEAN THEN
            v_errors := v_errors || v_result;
        END IF;
    END IF;

    -- Return result
    IF jsonb_array_length(v_errors) > 0 THEN
        RETURN jsonb_build_object('valid', FALSE, 'errors', v_errors);
    ELSE
        RETURN jsonb_build_object('valid', TRUE);
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'valid', FALSE,
            'errors', jsonb_build_array(jsonb_build_object(
                'field', 'dispatch_data',
                'error', format('Invalid dispatch data format: %s', SQLERRM)
            ))
        );
END;
$$;


CREATE FUNCTION public.validate_dispatch_items(p_dispatch_items jsonb[]) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_errors JSONB := '[]'::JSONB;
    v_result JSONB;
    v_item JSONB;
    v_idx INTEGER := 0;
    v_gr_trl_id TEXT;
    v_disp_qty TEXT;
    v_disp_qty_num NUMERIC;
    v_missing_ids TEXT[];
    v_provided_ids UUID[];
BEGIN
    -- Check if items array is empty or null
    IF p_dispatch_items IS NULL OR array_length(p_dispatch_items, 1) IS NULL OR array_length(p_dispatch_items, 1) = 0 THEN
        RETURN jsonb_build_object(
            'valid', FALSE,
            'errors', jsonb_build_array(jsonb_build_object(
                'field', 'p_dispatch_items',
                'error', 'At least one dispatch item is required'
            ))
        );
    END IF;

    -- First pass: validate format and collect UUIDs
    FOREACH v_item IN ARRAY p_dispatch_items LOOP
        v_idx := v_idx + 1;
        v_gr_trl_id := v_item->>'gr_trl_id';
        v_disp_qty := v_item->>'disp_qty';

        -- Validate gr_trl_id is provided
        IF v_gr_trl_id IS NULL OR v_gr_trl_id = '' THEN
            v_errors := v_errors || jsonb_build_object(
                'field', format('p_dispatch_items[%s].gr_trl_id', v_idx),
                'error', 'gr_trl_id is required'
            );
        ELSE
            -- Validate gr_trl_id is valid UUID
            v_result := validate_uuid(v_gr_trl_id, format('p_dispatch_items[%s].gr_trl_id', v_idx));
            IF NOT (v_result->>'valid')::BOOLEAN THEN
                v_errors := v_errors || v_result;
            ELSE
                -- Collect valid UUID for bulk existence check
                v_provided_ids := array_append(v_provided_ids, v_gr_trl_id::uuid);
            END IF;
        END IF;

        -- Validate disp_qty
        IF v_disp_qty IS NULL OR v_disp_qty = '' THEN
            v_errors := v_errors || jsonb_build_object(
                'field', format('p_dispatch_items[%s].disp_qty', v_idx),
                'error', 'disp_qty is required'
            );
        ELSE
            BEGIN
                v_disp_qty_num := v_disp_qty::NUMERIC;
                IF v_disp_qty_num <= 0 THEN
                    v_errors := v_errors || jsonb_build_object(
                        'field', format('p_dispatch_items[%s].disp_qty', v_idx),
                        'error', 'disp_qty must be greater than 0'
                    );
                ELSIF v_disp_qty_num != FLOOR(v_disp_qty_num) THEN
                    v_errors := v_errors || jsonb_build_object(
                        'field', format('p_dispatch_items[%s].disp_qty', v_idx),
                        'error', format('disp_qty must be an integer, got: %s', v_disp_qty)
                    );
                ELSIF v_disp_qty_num > 999999 THEN
                    v_errors := v_errors || jsonb_build_object(
                        'field', format('p_dispatch_items[%s].disp_qty', v_idx),
                        'error', 'disp_qty cannot exceed 999999'
                    );
                END IF;
            EXCEPTION
                WHEN OTHERS THEN
                    v_errors := v_errors || jsonb_build_object(
                        'field', format('p_dispatch_items[%s].disp_qty', v_idx),
                        'error', format('disp_qty must be a valid number, got: %s', v_disp_qty)
                    );
            END;
        END IF;
    END LOOP;

    -- BULK existence check - single query instead of N queries
    IF v_provided_ids IS NOT NULL AND array_length(v_provided_ids, 1) > 0 THEN
        SELECT ARRAY(
            SELECT uid::text
            FROM unnest(v_provided_ids) AS uid
            WHERE NOT EXISTS (SELECT 1 FROM goodsreceived_trl WHERE id = uid)
        ) INTO v_missing_ids;

        IF v_missing_ids IS NOT NULL AND array_length(v_missing_ids, 1) > 0 THEN
            FOR v_idx IN 1..array_length(v_missing_ids, 1) LOOP
                v_errors := v_errors || jsonb_build_object(
                    'field', 'gr_trl_id',
                    'error', format('gr_trl_id %s does not exist in inventory', v_missing_ids[v_idx])
                );
            END LOOP;
        END IF;
    END IF;

    -- Return result
    IF jsonb_array_length(v_errors) > 0 THEN
        RETURN jsonb_build_object('valid', FALSE, 'errors', v_errors);
    ELSE
        RETURN jsonb_build_object('valid', TRUE);
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'valid', FALSE,
            'errors', jsonb_build_array(jsonb_build_object(
                'field', 'p_dispatch_items',
                'error', format('Invalid dispatch items format: %s', SQLERRM)
            ))
        );
END;
$$;


CREATE FUNCTION public.validate_invoice_data_structure(p_invoice_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
  DECLARE
      v_header JSONB;
      v_items JSONB;
      v_item JSONB;
      v_errors TEXT[] := '{}';
  BEGIN
      -- Check if main structure exists
      IF p_invoice_data IS NULL THEN
          RETURN jsonb_build_object(
              'valid', false,
              'error', 'Invoice data is null or missing'
          );
      END IF;

      -- Check if data section exists
      IF NOT p_invoice_data ? 'data' THEN
          RETURN jsonb_build_object(
              'valid', false,
              'error', 'Missing "data" section in invoice structure'
          );
      END IF;

      -- Check if header exists
      IF NOT (p_invoice_data->'data') ? 'header' THEN
          v_errors := v_errors || 'Missing "header" section in invoice data';
      ELSE
          v_header := p_invoice_data->'data'->'header';

          -- Check required header fields
          IF NOT v_header ? 'customer_id' THEN
              v_errors := v_errors || 'Missing "customer_id" in header';
          END IF;

          IF NOT v_header ? 'customer_name' THEN
              v_errors := v_errors || 'Missing "customer_name" in header';
          END IF;

          IF NOT v_header ? 'grn_id' THEN
              v_errors := v_errors || 'Missing "grn_id" in header';
          END IF;

          IF NOT v_header ? 'grn_no' THEN
              v_errors := v_errors || 'Missing "grn_no" in header';
          END IF;

          IF NOT v_header ? 'invoice_number' THEN
              v_errors := v_errors || 'Missing "invoiceNumber" in header';
          END IF;

          IF NOT v_header ? 'invoice_date' THEN
              v_errors := v_errors || 'Missing "invoiceDate" in header';
          END IF;

          IF NOT v_header ? 'subtotal' THEN
              v_errors := v_errors || 'Missing "subtotal" in header';
          END IF;

          IF NOT v_header ? 'total_tax' THEN
              v_errors := v_errors || 'Missing "total_tax" in header';
          END IF;

          IF NOT v_header ? 'grand_total' THEN
              v_errors := v_errors || 'Missing "grand_total" in header';
          END IF;
      END IF;

      -- Check if items array exists
      IF NOT (p_invoice_data->'data') ? 'items' THEN
          v_errors := v_errors || 'Missing "items" array in invoice data';
      ELSE
          v_items := p_invoice_data->'data'->'items';

          IF jsonb_array_length(v_items) = 0 THEN
              v_errors := v_errors || 'Items array is empty';
          ELSE
              -- Check each item structure
              FOR i IN 0..jsonb_array_length(v_items)-1 LOOP
                  v_item := v_items->i;

                  IF NOT v_item ? 'item_name' THEN
                      v_errors := v_errors || format('Item %s missing "item_name"', i+1);
                  END IF;

                  IF NOT v_item ? 'dispatch_qty' THEN
                      v_errors := v_errors || format('Item %s missing "dispatch_qty"', i+1);
                  END IF;

                  IF NOT v_item ? 'unit_price' THEN
                      v_errors := v_errors || format('Item %s missing "unit_price"', i+1);
                  END IF;

                  IF NOT v_item ? 'base_amount' THEN
                      v_errors := v_errors || format('Item %s missing "base_amount"', i+1);
                  END IF;

                  IF NOT v_item ? 'tax_amount' THEN
                      v_errors := v_errors || format('Item %s missing "tax_amount"', i+1);
                  END IF;

                  IF NOT v_item ? 'total' THEN
                      v_errors := v_errors || format('Item %s missing "total"', i+1);
                  END IF;
              END LOOP;
          END IF;
      END IF;

      -- Return validation result
      IF array_length(v_errors, 1) > 0 THEN
          RETURN jsonb_build_object(
              'valid', false,
              'error', array_to_string(v_errors, '; '),
              'errors', array_to_json(v_errors)
          );
      ELSE
          RETURN jsonb_build_object(
              'valid', true,
              'message', 'Invoice data structure is valid'
          );
      END IF;
  END;
  $$;


CREATE FUNCTION public.validate_invoice_duration_mode(p_duration_mode text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    v_duration_mode text := COALESCE(NULLIF(LOWER(TRIM(p_duration_mode)), ''), 'legacy');
BEGIN
    IF v_duration_mode NOT IN ('legacy', 'standard') THEN
        RAISE EXCEPTION 'Invalid duration_mode: %. Expected legacy or standard', p_duration_mode
            USING ERRCODE = '22023';
    END IF;

    RETURN v_duration_mode;
END;
$$;


CREATE FUNCTION public.validate_invoice_input(p_invoice_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_errors JSONB := '[]'::JSONB;
    v_result JSONB;
    v_customer_id TEXT;
    v_total NUMERIC;
    v_labour NUMERIC;
    v_tax_amount NUMERIC;
    v_discount NUMERIC;
BEGIN
    -- Extract values
    v_customer_id := p_invoice_data->>'customer_id';
    v_total := (p_invoice_data->>'total')::NUMERIC;
    v_labour := (p_invoice_data->>'labour')::NUMERIC;
    v_tax_amount := (p_invoice_data->>'tax_amount')::NUMERIC;
    v_discount := (p_invoice_data->>'discount')::NUMERIC;

    -- Validate customer_id (UUID)
    v_result := validate_uuid(v_customer_id, 'customer_id');
    IF NOT (v_result->>'valid')::BOOLEAN THEN
        v_errors := v_errors || v_result;
    END IF;

    -- Validate total (must be >= 0)
    v_result := validate_numeric_range(v_total, 'total', 0, 99999999);
    IF NOT (v_result->>'valid')::BOOLEAN THEN
        v_errors := v_errors || v_result;
    END IF;

    -- Validate labour (must be >= 0)
    v_result := validate_numeric_range(v_labour, 'labour', 0, 99999999, TRUE);
    IF NOT (v_result->>'valid')::BOOLEAN THEN
        v_errors := v_errors || v_result;
    END IF;

    -- Validate tax_amount (must be >= 0)
    v_result := validate_numeric_range(v_tax_amount, 'tax_amount', 0, 99999999, TRUE);
    IF NOT (v_result->>'valid')::BOOLEAN THEN
        v_errors := v_errors || v_result;
    END IF;

    -- Validate discount (allow negative values for surcharges)
    -- Changed from min=0 to min=-99999999 on 2026-01-03
    v_result := validate_numeric_range(v_discount, 'discount', -99999999, 99999999, TRUE);
    IF NOT (v_result->>'valid')::BOOLEAN THEN
        v_errors := v_errors || v_result;
    END IF;

    -- Return result
    IF jsonb_array_length(v_errors) > 0 THEN
        RETURN jsonb_build_object(
            'valid', FALSE,
            'errors', v_errors
        );
    ELSE
        RETURN jsonb_build_object('valid', TRUE);
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'valid', FALSE,
            'errors', jsonb_build_array(jsonb_build_object(
                'field', 'invoice_data',
                'error', format('Invalid invoice data format: %s', SQLERRM)
            ))
        );
END;
$$;


CREATE FUNCTION public.validate_invoice_items(p_invoice_items jsonb[]) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_errors JSONB := '[]'::JSONB;
    v_result JSONB;
    v_item JSONB;
    v_idx INTEGER := 0;
    v_grn_item_id TEXT;
    v_duration NUMERIC;
    v_charge NUMERIC;
BEGIN
    -- Check if items array is empty
    IF p_invoice_items IS NULL OR array_length(p_invoice_items, 1) IS NULL THEN
        RETURN jsonb_build_object(
            'valid', FALSE,
            'errors', jsonb_build_array(jsonb_build_object(
                'field', 'invoice_items',
                'error', 'Invoice must have at least one item'
            ))
        );
    END IF;

    -- Validate each item
    FOREACH v_item IN ARRAY p_invoice_items LOOP
        v_idx := v_idx + 1;

        -- Extract item values
        v_grn_item_id := v_item->>'grn_item_id';
        v_duration := (v_item->>'duration')::NUMERIC;
        v_charge := (v_item->>'charge')::NUMERIC;

        -- Validate grn_item_id
        v_result := validate_uuid(v_grn_item_id, format('invoice_items[%s].grn_item_id', v_idx));
        IF NOT (v_result->>'valid')::BOOLEAN THEN
            v_errors := v_errors || v_result;
        END IF;

        -- Validate duration (must be > 0)
        v_result := validate_numeric_range(v_duration, format('invoice_items[%s].duration', v_idx), 0.01, 999);
        IF NOT (v_result->>'valid')::BOOLEAN THEN
            v_errors := v_errors || v_result;
        END IF;

        -- Validate charge (must be >= 0)
        v_result := validate_numeric_range(v_charge, format('invoice_items[%s].charge', v_idx), 0, 999999);
        IF NOT (v_result->>'valid')::BOOLEAN THEN
            v_errors := v_errors || v_result;
        END IF;
    END LOOP;

    -- Return result
    IF jsonb_array_length(v_errors) > 0 THEN
        RETURN jsonb_build_object('valid', FALSE, 'errors', v_errors);
    ELSE
        RETURN jsonb_build_object('valid', TRUE);
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'valid', FALSE,
            'errors', jsonb_build_array(jsonb_build_object(
                'field', 'invoice_items',
                'error', format('Invalid invoice items format: %s', SQLERRM)
            ))
        );
END;
$$;


CREATE FUNCTION public.validate_numeric_range(p_value numeric, p_field_name text, p_min numeric DEFAULT NULL::numeric, p_max numeric DEFAULT NULL::numeric, p_allow_null boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
    -- Check null
    IF p_value IS NULL THEN
        IF NOT p_allow_null THEN
            RETURN jsonb_build_object(
                'valid', FALSE,
                'field', p_field_name,
                'error', format('%s is required (cannot be null)', p_field_name)
            );
        ELSE
            RETURN jsonb_build_object('valid', TRUE, 'field', p_field_name);
        END IF;
    END IF;

    -- Check minimum
    IF p_min IS NOT NULL AND p_value < p_min THEN
        RETURN jsonb_build_object(
            'valid', FALSE,
            'field', p_field_name,
            'error', format('%s must be >= %s. Got: %s', p_field_name, p_min, p_value)
        );
    END IF;

    -- Check maximum
    IF p_max IS NOT NULL AND p_value > p_max THEN
        RETURN jsonb_build_object(
            'valid', FALSE,
            'field', p_field_name,
            'error', format('%s must be <= %s. Got: %s', p_field_name, p_max, p_value)
        );
    END IF;

    RETURN jsonb_build_object('valid', TRUE, 'field', p_field_name);
END;
$$;


CREATE FUNCTION public.validate_price_configuration(p_item_id uuid, p_weight_min integer, p_weight_max integer, p_effective_from date, p_customer_id uuid DEFAULT NULL::uuid, p_effective_to date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    overlap_count INTEGER;
    validation_result JSONB;
BEGIN
    -- Check for overlapping weight ranges
    SELECT COUNT(*) INTO overlap_count
    FROM item_storage_prices
    WHERE item_id = p_item_id
      AND (customer_id = p_customer_id OR (customer_id IS NULL AND p_customer_id IS NULL))
      AND (
        (p_weight_min >= weight_min AND p_weight_min < weight_max) OR
        (p_weight_max > weight_min AND p_weight_max <= weight_max) OR
        (p_weight_min <= weight_min AND p_weight_max >= weight_max)
      )
      AND (
        (p_effective_from <= effective_from AND (p_effective_to IS NULL OR p_effective_to > effective_from)) OR
        (p_effective_from < COALESCE(effective_to, '9999-12-31'::date) AND (p_effective_to IS NULL OR p_effective_to > effective_from))
      );

    IF overlap_count > 0 THEN
        validation_result := jsonb_build_object(
            'valid', false,
            'error', 'Overlapping weight range detected',
            'overlap_count', overlap_count
        );
    ELSE
        validation_result := jsonb_build_object(
            'valid', true,
            'message', 'Price configuration is valid'
        );
    END IF;

    RETURN validation_result;
END;
$$;


CREATE FUNCTION public.validate_string_length(p_value text, p_field_name text, p_min_length integer DEFAULT 1, p_max_length integer DEFAULT NULL::integer, p_allow_null boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
    -- Check null
    IF p_value IS NULL THEN
        IF NOT p_allow_null THEN
            RETURN jsonb_build_object(
                'valid', FALSE,
                'field', p_field_name,
                'error', format('%s is required (cannot be null)', p_field_name)
            );
        ELSE
            RETURN jsonb_build_object('valid', TRUE, 'field', p_field_name);
        END IF;
    END IF;

    -- Check minimum length
    IF p_min_length IS NOT NULL AND LENGTH(p_value) < p_min_length THEN
        RETURN jsonb_build_object(
            'valid', FALSE,
            'field', p_field_name,
            'error', format('%s must be at least %s characters. Got: %s chars',
                p_field_name, p_min_length, LENGTH(p_value))
        );
    END IF;

    -- Check maximum length
    IF p_max_length IS NOT NULL AND LENGTH(p_value) > p_max_length THEN
        RETURN jsonb_build_object(
            'valid', FALSE,
            'field', p_field_name,
            'error', format('%s must be at most %s characters. Got: %s chars',
                p_field_name, p_max_length, LENGTH(p_value))
        );
    END IF;

    RETURN jsonb_build_object('valid', TRUE, 'field', p_field_name);
END;
$$;


CREATE FUNCTION public.validate_uuid(p_value text, p_field_name text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
    IF p_value IS NULL THEN
        RETURN jsonb_build_object(
            'valid', FALSE,
            'field', p_field_name,
            'error', format('%s is required (cannot be null)', p_field_name)
        );
    END IF;

    -- Try to cast to UUID
    BEGIN
        PERFORM p_value::UUID;
        RETURN jsonb_build_object('valid', TRUE, 'field', p_field_name);
    EXCEPTION
        WHEN invalid_text_representation THEN
            RETURN jsonb_build_object(
                'valid', FALSE,
                'field', p_field_name,
                'error', format('%s must be a valid UUID format. Got: %s', p_field_name, p_value)
            );
    END;
END;
$$;


CREATE FUNCTION public.verify_captcha(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    -- Captcha is optional - if no token, pass
    IF p_token IS NULL OR p_token = '' THEN
        RETURN utils.success_response(jsonb_build_object('verified', true), 'Captcha verification skipped');
    END IF;
    -- TODO: Implement actual captcha verification
    RETURN utils.success_response(jsonb_build_object('verified', true), 'Captcha verified');
END;
$$;


CREATE FUNCTION public.verify_otp(p_phone_number character varying, p_otp_code character varying, p_purpose character varying DEFAULT 'login'::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_phone_formatted VARCHAR(15);
    v_otp_record RECORD;
    v_otp_hash TEXT;
    v_user_id UUID;
    v_existing_user_id UUID;
    v_customer_exists BOOLEAN;
    v_production_mode BOOLEAN;
    v_provider VARCHAR(20);
    v_test_otp VARCHAR(6);
BEGIN
    -- Format phone number
    v_phone_formatted := REGEXP_REPLACE(p_phone_number, '[^0-9]', '', 'g');
    IF LENGTH(v_phone_formatted) = 10 THEN
        v_phone_formatted := '91' || v_phone_formatted;
    END IF;

    -- Get SMS config
    SELECT production_mode, provider INTO v_production_mode, v_provider
    FROM public.sms_config ORDER BY id DESC LIMIT 1;
    v_provider := COALESCE(v_provider, 'twilio');

    -- Check test OTP for non-production mode
    SELECT fixed_otp INTO v_test_otp FROM public.test_otp_records WHERE phone_number = v_phone_formatted;

    -- TEST MODE: Accept fixed test OTP
    IF NOT v_production_mode AND v_test_otp IS NOT NULL AND p_otp_code = v_test_otp THEN
        SELECT auth_user_id INTO v_existing_user_id FROM public.user_profiles WHERE mobile = v_phone_formatted LIMIT 1;
        IF v_existing_user_id IS NULL THEN
            SELECT id INTO v_existing_user_id FROM auth.users WHERE phone = v_phone_formatted LIMIT 1;
        END IF;
        SELECT EXISTS(SELECT 1 FROM public.customers WHERE mobile = v_phone_formatted OR mobile = RIGHT(v_phone_formatted, 10)) INTO v_customer_exists;
        UPDATE public.otp_verifications SET verified = TRUE, verified_at = NOW() WHERE phone_number = v_phone_formatted AND NOT verified;

        RETURN utils.success_response(
            jsonb_build_object('user_id', v_existing_user_id, 'phone_verified', v_customer_exists),
            'Test OTP verified successfully'
        );
    END IF;

    -- Find the most recent unverified OTP
    SELECT * INTO v_otp_record FROM public.otp_verifications
    WHERE phone_number = v_phone_formatted AND purpose = p_purpose AND verified = FALSE AND expires_at > NOW()
    ORDER BY created_at DESC LIMIT 1;

    IF v_otp_record IS NULL THEN
        RETURN utils.error_response('OTP_EXPIRED', 'No valid OTP found or OTP expired');
    END IF;

    -- Increment attempt counter
    UPDATE public.otp_verifications SET attempts = attempts + 1 WHERE id = v_otp_record.id;

    -- Check if max attempts exceeded
    IF v_otp_record.attempts >= v_otp_record.max_attempts THEN
        UPDATE public.otp_verifications SET verified = TRUE, verified_at = NOW() WHERE id = v_otp_record.id;
        RETURN utils.error_response('OTP_MAX_ATTEMPTS', 'Maximum OTP attempts exceeded');
    END IF;

    -- Verify OTP using hash
    v_otp_hash := encode(digest(p_otp_code, 'sha256'), 'hex');
    IF v_otp_record.otp_code_hash IS NULL OR v_otp_record.otp_code_hash != v_otp_hash THEN
        IF v_otp_record.otp_code IS NULL OR v_otp_record.otp_code != p_otp_code THEN
            RETURN utils.error_response('OTP_INVALID', 'Invalid OTP code');
        END IF;
    END IF;

    -- Mark OTP as verified
    UPDATE public.otp_verifications SET verified = TRUE, verified_at = NOW() WHERE id = v_otp_record.id;

    -- Check if user exists
    SELECT auth_user_id INTO v_existing_user_id FROM public.user_profiles WHERE mobile = v_phone_formatted LIMIT 1;
    IF v_existing_user_id IS NULL THEN
        SELECT id INTO v_existing_user_id FROM auth.users WHERE phone = v_phone_formatted LIMIT 1;
    END IF;

    -- Check if customer exists
    SELECT EXISTS(SELECT 1 FROM public.customers WHERE mobile = v_phone_formatted OR mobile = RIGHT(v_phone_formatted, 10)) INTO v_customer_exists;

    RETURN utils.success_response(
        jsonb_build_object('user_id', v_existing_user_id, 'phone_verified', v_customer_exists),
        'OTP verified successfully'
    );
END;
$$;


CREATE FUNCTION public.verify_otp_or_register(p_phone_number character varying, p_otp_code character varying, p_name character varying DEFAULT NULL::character varying, p_display_name character varying DEFAULT NULL::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_phone_formatted VARCHAR(15);
    v_otp_record RECORD;
    v_otp_hash TEXT;
    v_user_profile RECORD;
    v_action_taken TEXT;
    v_jwt_secret TEXT;
    v_access_token_expiry INTEGER;
    v_refresh_token_expiry INTEGER;
    v_access_token TEXT;
    v_refresh_token TEXT;
    v_access_token_payload TEXT;
    v_refresh_token_payload TEXT;
    v_token_expires_at TIMESTAMP WITH TIME ZONE;
    v_access_exp BIGINT;
    v_refresh_exp BIGINT;
    v_iat BIGINT;
    v_test_otp VARCHAR(6);
    v_is_test_phone BOOLEAN := FALSE;
BEGIN
    v_phone_formatted := REGEXP_REPLACE(p_phone_number, '[^0-9]', '', 'g');
    IF LENGTH(v_phone_formatted) = 10 THEN
        v_phone_formatted := '91' || v_phone_formatted;
    END IF;

    -- Check if this is a test phone number
    SELECT fixed_otp INTO v_test_otp
    FROM public.test_otp_records
    WHERE phone_number = v_phone_formatted;

    IF v_test_otp IS NOT NULL AND p_otp_code = v_test_otp THEN
        -- Test phone number with correct OTP - bypass normal verification
        v_is_test_phone := TRUE;
    ELSE
        -- Normal OTP verification flow
        v_otp_hash := encode(digest(p_otp_code, 'sha256'), 'hex');

        SELECT * INTO v_otp_record
        FROM public.otp_verifications ov
        WHERE ov.phone_number = v_phone_formatted
            AND ov.otp_code_hash = v_otp_hash
            AND ov.verified = FALSE
            AND ov.expires_at > NOW()
        ORDER BY ov.created_at DESC
        LIMIT 1;

        IF NOT FOUND THEN
            RETURN jsonb_build_object(
                'success', false,
                'message', 'Invalid or expired OTP',
                'data', null
            );
        END IF;

        UPDATE public.otp_verifications
        SET verified = TRUE, verified_at = NOW()
        WHERE id = v_otp_record.id;
    END IF;

    SELECT * INTO v_user_profile
    FROM public.user_profiles
    WHERE mobile = v_phone_formatted;

    IF NOT FOUND THEN
        INSERT INTO public.user_profiles (auth_user_id, mobile, name, display_name, role, mobile_verified, active)
        VALUES (
            gen_random_uuid(),
            v_phone_formatted,
            COALESCE(p_name, 'User_' || RIGHT(v_phone_formatted, 4)),
            COALESCE(p_display_name, p_name, 'User_' || RIGHT(v_phone_formatted, 4)),
            'customer',
            TRUE,
            TRUE
        )
        RETURNING * INTO v_user_profile;
        v_action_taken := 'register';
    ELSE
        UPDATE public.user_profiles
        SET mobile_verified = TRUE,
            updated_at = NOW(),
            name = COALESCE(p_name, name),
            display_name = COALESCE(p_display_name, display_name)
        WHERE id = v_user_profile.id
        RETURNING * INTO v_user_profile;
        v_action_taken := 'login';
    END IF;

    SELECT secret_value INTO v_jwt_secret
    FROM public.jwt_config
    WHERE secret_name = 'supabase_jwt_secret' AND is_active = TRUE
    LIMIT 1;

    SELECT secret_value::INTEGER INTO v_access_token_expiry
    FROM public.jwt_config
    WHERE secret_name = 'jwt_access_token_expiry' AND is_active = TRUE
    LIMIT 1;

    SELECT secret_value::INTEGER INTO v_refresh_token_expiry
    FROM public.jwt_config
    WHERE secret_name = 'jwt_refresh_token_expiry' AND is_active = TRUE
    LIMIT 1;

    v_access_token_expiry := COALESCE(v_access_token_expiry, 63072000);
    v_refresh_token_expiry := COALESCE(v_refresh_token_expiry, 63072000);
    v_token_expires_at := NOW() + (v_access_token_expiry || ' seconds')::INTERVAL;

    v_iat := EXTRACT(EPOCH FROM NOW())::BIGINT;
    v_access_exp := EXTRACT(EPOCH FROM v_token_expires_at)::BIGINT;
    v_refresh_exp := EXTRACT(EPOCH FROM NOW() + (v_refresh_token_expiry || ' seconds')::INTERVAL)::BIGINT;

    v_access_token_payload := format(
        '{"aud":"authenticated","exp":%s,"iat":%s,"iss":"supabase","sub":"%s","phone":"%s","app_metadata":{"provider":"phone","providers":["phone"]},"user_metadata":{"name":"%s","display_name":"%s","role":"%s"},"role":"authenticated"}',
        v_access_exp, v_iat,
        v_user_profile.auth_user_id::TEXT,
        v_user_profile.mobile,
        COALESCE(v_user_profile.name, ''),
        COALESCE(v_user_profile.display_name, ''),
        v_user_profile.role::TEXT
    );

    v_refresh_token_payload := format(
        '{"aud":"authenticated","exp":%s,"iat":%s,"iss":"supabase","sub":"%s","type":"refresh"}',
        v_refresh_exp, v_iat,
        v_user_profile.auth_user_id::TEXT
    );

    v_access_token := extensions.sign(v_access_token_payload::json, v_jwt_secret, 'HS256');
    v_refresh_token := extensions.sign(v_refresh_token_payload::json, v_jwt_secret, 'HS256');

    RETURN jsonb_build_object(
        'success', true,
        'message', CASE WHEN v_action_taken = 'register' THEN 'Registration successful' ELSE 'Login successful' END,
        'data', jsonb_build_object(
            'user', jsonb_build_object(
                'id', v_user_profile.id,
                'auth_user_id', v_user_profile.auth_user_id,
                'name', v_user_profile.name,
                'display_name', v_user_profile.display_name,
                'mobile', v_user_profile.mobile,
                'role', v_user_profile.role,
                'active', v_user_profile.active,
                'mobile_verified', v_user_profile.mobile_verified
            ),
            'session', jsonb_build_object(
                'access_token', v_access_token,
                'refresh_token', v_refresh_token,
                'expires_at', v_token_expires_at,
                'expires_in', v_access_token_expiry,
                'token_type', 'bearer'
            ),
            'action', v_action_taken
        )
    );
END;
$$;


CREATE FUNCTION public.verify_otp_secure(p_phone_number character varying, p_otp_code character varying, p_ip_address inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result jsonb;
    v_user_id uuid;
BEGIN
    -- Call verify_otp
    v_result := verify_otp(p_phone_number, p_otp_code, 'login');

    -- Log the authentication attempt
    IF (v_result->>'success')::boolean THEN
        v_user_id := (v_result->'data'->>'user_id')::uuid;
    END IF;

    PERFORM log_authentication_attempt(
        p_phone_number,
        v_user_id,
        (v_result->>'success')::boolean,
        p_ip_address::text,
        p_user_agent,
        jsonb_build_object('method', 'otp_secure')
    );

    RETURN v_result;
END;
$$;


CREATE FUNCTION utils.database_error_response(p_context text, p_sqlerrm text, p_sqlstate text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT jsonb_build_object(
        'success', false,
        'data', NULL,
        'message', p_context || ': ' || p_sqlerrm,
        'error', jsonb_strip_nulls(jsonb_build_object(
            'code', 'DATABASE_ERROR',
            'details', p_sqlstate
        ))
    );
$$;


CREATE FUNCTION utils.error_response(p_code text, p_message text, p_details text DEFAULT NULL::text, p_field text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT jsonb_build_object(
        'success', false,
        'data', NULL,
        'message', p_message,
        'error', jsonb_strip_nulls(jsonb_build_object(
            'code', p_code,
            'details', p_details,
            'field', p_field
        ))
    );
$$;


CREATE FUNCTION utils.not_authenticated_response() RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT jsonb_build_object(
        'success', false,
        'data', NULL,
        'message', 'Authentication required',
        'error', jsonb_build_object(
            'code', 'NOT_AUTHENTICATED'
        )
    );
$$;


CREATE FUNCTION utils.not_found_response(p_resource_type text, p_identifier text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT jsonb_build_object(
        'success', false,
        'data', NULL,
        'message',
            CASE
                WHEN p_identifier IS NOT NULL THEN
                    p_resource_type || ' with ID ' || p_identifier || ' not found'
                ELSE
                    p_resource_type || ' not found'
            END,
        'error', jsonb_build_object(
            'code', UPPER(REPLACE(p_resource_type, ' ', '_')) || '_NOT_FOUND'
        )
    );
$$;


CREATE FUNCTION utils.permission_denied_response(p_required_role text DEFAULT 'admin or supervisor'::text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT jsonb_build_object(
        'success', false,
        'data', NULL,
        'message', 'Only ' || p_required_role || ' can perform this action',
        'error', jsonb_build_object(
            'code', 'PERMISSION_DENIED'
        )
    );
$$;


CREATE FUNCTION utils.success_response(p_data jsonb DEFAULT NULL::jsonb, p_message text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT jsonb_build_object(
        'success', true,
        'data', p_data,
        'message', p_message
    );
$$;


CREATE FUNCTION utils.success_response_paginated(p_data jsonb, p_total_count bigint, p_limit integer, p_offset integer, p_message text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT jsonb_build_object(
        'success', true,
        'data', COALESCE(p_data, '[]'::jsonb),
        'pagination', jsonb_build_object(
            'total_count', p_total_count,
            'limit', p_limit,
            'offset', p_offset,
            'has_more', (p_offset + p_limit) < p_total_count
        ),
        'message', p_message
    );
$$;


CREATE FUNCTION utils.validation_error_response(p_field text, p_message text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT jsonb_build_object(
        'success', false,
        'data', NULL,
        'message', p_message,
        'error', jsonb_build_object(
            'code', 'VALIDATION_FAILED',
            'field', p_field
        )
    );
$$;


