    phone_number character varying(15),
    user_id uuid,
    success boolean NOT NULL,
    details jsonb,
    ip_address inet,
    user_agent text,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


CREATE MATERIALIZED VIEW public.auth_geographic_anomalies AS
 SELECT auth_logs.user_id,
    auth_logs.phone_number,
    auth_logs.ip_address,
    auth_logs.created_at,
        CASE
            WHEN (host(auth_logs.ip_address) ~ '^(10\.|172\.(1[6-9]|2[0-9]|3[0-1])\.|192\.168\.)'::text) THEN 'Local'::text
            ELSE 'External'::text
        END AS ip_type,
    lag(auth_logs.created_at) OVER (PARTITION BY auth_logs.user_id ORDER BY auth_logs.created_at) AS prev_login_time,
    lag(auth_logs.ip_address) OVER (PARTITION BY auth_logs.user_id ORDER BY auth_logs.created_at) AS prev_ip
   FROM public.auth_logs
  WHERE (auth_logs.success = true)
  ORDER BY auth_logs.created_at DESC
  WITH NO DATA;


