    value_date date,
    instr_no text,
    particulars text NOT NULL,
    debit numeric(14,2) DEFAULT 0 NOT NULL,
    credit numeric(14,2) DEFAULT 0 NOT NULL,
    balance numeric(14,2),
    matched_customer_id uuid,
    matched_bill_ids uuid[],
    matched_allocations jsonb,
    match_kind text,
    tds_amount numeric(14,2),
    status text DEFAULT 'new'::text NOT NULL,
    review_note text,
    tally_sync_queue_id uuid,
    confirmed_by uuid,
    confirmed_at timestamp with time zone,
    editing boolean DEFAULT false NOT NULL,
    receipt_method text DEFAULT 'bank'::text NOT NULL,
    CONSTRAINT bank_statement_lines_match_kind_check CHECK (((match_kind = ANY (ARRAY['exact'::text, 'tds_2pct'::text, 'tds_10pct'::text, 'manual'::text])) OR (match_kind IS NULL))),
    CONSTRAINT bank_statement_lines_one_sided_amount CHECK (((debit >= (0)::numeric) AND (credit >= (0)::numeric) AND (NOT ((debit > (0)::numeric) AND (credit > (0)::numeric))))),
    CONSTRAINT bank_statement_lines_receipt_method_check CHECK ((receipt_method = ANY (ARRAY['bank'::text, 'cash'::text]))),
    CONSTRAINT bank_statement_lines_status_check CHECK ((status = ANY (ARRAY['new'::text, 'matched'::text, 'queued'::text, 'reconciled'::text, 'skipped'::text, 'failed'::text])))
);


