CREATE VIEW public.foreign_key_status AS
 SELECT tc.table_name,
    kcu.column_name,
    ccu.table_name AS references_table,
    ccu.column_name AS references_column,
    tc.constraint_name,
        CASE
            WHEN ((ccu.table_name)::name = 'users'::name) THEN 'NEEDS UPDATE'::text
            WHEN ((ccu.table_name)::name = 'user_profiles'::name) THEN 'UPDATED'::text
            ELSE 'OTHER'::text
        END AS status
   FROM ((information_schema.table_constraints tc
     JOIN information_schema.key_column_usage kcu ON ((((tc.constraint_name)::name = (kcu.constraint_name)::name) AND ((tc.table_schema)::name = (kcu.table_schema)::name))))
     JOIN information_schema.constraint_column_usage ccu ON ((((ccu.constraint_name)::name = (tc.constraint_name)::name) AND ((ccu.table_schema)::name = (tc.table_schema)::name))))
  WHERE (((tc.constraint_type)::text = 'FOREIGN KEY'::text) AND ((tc.table_schema)::name = 'public'::name) AND (((ccu.table_name)::name = ANY (ARRAY['users'::name, 'user_profiles'::name])) OR ((tc.table_name)::name ~~ '%user%'::text)))
  ORDER BY tc.table_name, kcu.column_name;


