CREATE VIEW public.stock_summary AS
SELECT
    NULL::uuid AS gr_trl_id,
    NULL::uuid AS gr_id,
    NULL::character varying(8) AS gr_no,
    NULL::timestamp with time zone AS gr_date,
    NULL::uuid AS customer_id,
    NULL::character varying(80) AS customer_name,
    NULL::uuid AS item_id,
    NULL::character varying(30) AS item_name,
    NULL::character varying(20) AS packaging,
    NULL::integer AS original_qty,
    NULL::bigint AS total_dispatched,
    NULL::integer AS current_stock,
    NULL::character varying(30) AS rack,
    NULL::character varying(60) AS package_mark;


CREATE VIEW public.low_stock_alerts AS
 SELECT ss.gr_trl_id,
    ss.gr_id,
    ss.gr_no,
    ss.gr_date,
    ss.customer_id,
    ss.customer_name,
    ss.item_id,
    ss.item_name,
    ss.packaging,
    ss.original_qty,
    ss.total_dispatched,
    ss.current_stock,
    ss.rack,
    ss.package_mark,
        CASE
            WHEN (ss.current_stock = 0) THEN 'OUT_OF_STOCK'::text
            WHEN ((ss.current_stock)::numeric < ((ss.original_qty)::numeric * 0.2)) THEN 'CRITICAL'::text
            WHEN ((ss.current_stock)::numeric < ((ss.original_qty)::numeric * 0.5)) THEN 'LOW'::text
            ELSE 'NORMAL'::text
        END AS stock_status
   FROM public.stock_summary ss
  WHERE ((ss.current_stock)::numeric < ((ss.original_qty)::numeric * 0.5))
  ORDER BY ss.current_stock;


