CREATE MATERIALIZED VIEW public.mv_customer_stock_summary AS
 WITH grn_totals AS (
         SELECT gr.customer_id,
            grt.item_id,
            sum(grt.qty) AS total_grn_qty
           FROM (public.goodsreceived_trl grt
             JOIN public.goodsreceived gr ON ((grt.gr_id = gr.id)))
          GROUP BY gr.customer_id, grt.item_id
        ), dispatch_totals AS (
         SELECT gr.customer_id,
            grt.item_id,
            sum(dt.disp_qty) AS total_dispatch_qty
           FROM ((public.dispatch_trl dt
             JOIN public.goodsreceived_trl grt ON ((dt.gr_trl_id = grt.id)))
             JOIN public.goodsreceived gr ON ((grt.gr_id = gr.id)))
          GROUP BY gr.customer_id, grt.item_id
        )
 SELECT c.id AS customer_id,
    c.name AS customer_name,
    i.id AS item_id,
    i.name AS item_name,
    i.packaging,
    COALESCE(g.total_grn_qty, (0)::bigint) AS grn_qty,
    COALESCE(d.total_dispatch_qty, (0)::bigint) AS dispatch_qty,
    (COALESCE(g.total_grn_qty, (0)::bigint) - COALESCE(d.total_dispatch_qty, (0)::bigint)) AS current_stock,
    now() AS last_refreshed
   FROM (((public.customers c
     CROSS JOIN public.items i)
     LEFT JOIN grn_totals g ON (((g.customer_id = c.id) AND (g.item_id = i.id))))
     LEFT JOIN dispatch_totals d ON (((d.customer_id = c.id) AND (d.item_id = i.id))))
  WHERE ((i.active = true) AND ((g.total_grn_qty IS NOT NULL) OR (d.total_dispatch_qty IS NOT NULL)))
  WITH NO DATA;


CREATE MATERIALIZED VIEW public.mv_dispatch_daily_summary AS
 SELECT date_trunc('day'::text, d.disp_date) AS dispatch_day,
    gr.customer_id,
    c.name AS customer_name,
    count(DISTINCT d.id) AS dispatch_count,
    count(dt.id) AS line_count,
    sum(dt.disp_qty) AS total_qty
   FROM ((((public.dispatch d
     JOIN public.dispatch_trl dt ON ((dt.disp_id = d.id)))
     JOIN public.goodsreceived_trl grt ON ((dt.gr_trl_id = grt.id)))
     JOIN public.goodsreceived gr ON ((grt.gr_id = gr.id)))
     JOIN public.customers c ON ((c.id = gr.customer_id)))
  GROUP BY (date_trunc('day'::text, d.disp_date)), gr.customer_id, c.name
  WITH NO DATA;


CREATE MATERIALIZED VIEW public.mv_dispatch_list AS
 WITH dispatch_aggregates AS (
         SELECT dt.disp_id,
            count(DISTINCT dt.gr_trl_id) AS total_items,
            sum(dt.disp_qty) AS total_qty,
            sum((COALESCE(grt.weight, 0) * dt.disp_qty)) AS total_weight,
            count(DISTINCT gr.id) AS unique_grns,
            array_agg(DISTINCT gr.gr_no ORDER BY gr.gr_no) FILTER (WHERE (gr.id IS NOT NULL)) AS grn_numbers,
            jsonb_agg(jsonb_build_object('id', grt.id, 'itemName', grt.item_name, 'grNo', gr.gr_no, 'qty', dt.disp_qty, 'weight', grt.weight, 'packageMark', grt.package_mark) ORDER BY grt.item_name) AS items_jsonb
           FROM ((public.dispatch_trl dt
             JOIN public.goodsreceived_trl grt ON ((dt.gr_trl_id = grt.id)))
             JOIN public.goodsreceived gr ON ((grt.gr_id = gr.id)))
          GROUP BY dt.disp_id
        )
 SELECT d.id AS dispatch_id,
    d.disp_no,
    d.disp_date,
    d.customer_id,
    d.customer_name,
    d.supervisor_id,
    d.supervisor_name,
    d.registration,
    d.note,
    d.source_order_id,
    d.source_order_no,
    d.created_at,
    d.updated_at,
    d.created_by,
    (COALESCE(da.total_items, (0)::bigint))::integer AS total_items,
    (COALESCE(da.total_qty, (0)::bigint))::numeric AS total_qty,
    (COALESCE(da.total_weight, (0)::bigint))::numeric AS total_weight,
    (COALESCE(da.unique_grns, (0)::bigint))::integer AS unique_grns,
    COALESCE(da.grn_numbers, (ARRAY[]::text[])::character varying[]) AS grn_numbers,
    COALESCE(da.items_jsonb, '[]'::jsonb) AS items_jsonb
   FROM (public.dispatch d
     LEFT JOIN dispatch_aggregates da ON ((da.disp_id = d.id)))
  WHERE (d.deleted_at IS NULL)
  WITH NO DATA;


CREATE MATERIALIZED VIEW public.mv_grn_daily_summary AS
 SELECT date_trunc('day'::text, gr.date) AS grn_day,
    gr.customer_id,
    c.name AS customer_name,
    count(DISTINCT gr.id) AS grn_count,
    count(grt.id) AS line_count,
    sum(grt.qty) AS total_qty,
    sum(grt.weight) AS total_weight
   FROM ((public.goodsreceived gr
     JOIN public.customers c ON ((c.id = gr.customer_id)))
     JOIN public.goodsreceived_trl grt ON ((grt.gr_id = gr.id)))
  GROUP BY (date_trunc('day'::text, gr.date)), gr.customer_id, c.name
  WITH NO DATA;


CREATE MATERIALIZED VIEW public.mv_grn_list AS
 SELECT grt.id AS grn_item_id,
    grt.gr_id AS grn_id,
    grt.item_id,
    grt.item_name,
    grt.packaging,
    grt.qty,
    grt.stock,
    grt.weight,
    grt.rack,
    grt.package_mark,
    grt.trl_img_url AS image_url,
    gr.gr_no,
    gr.date AS grn_date,
    gr.registration,
    gr.supervisor_name,
    gr.supervisor_id,
    gr.customer_id,
    gr.customer_name,
    gr.out_of_stock,
    gr.invoiced,
    gr.note AS grn_note,
    gr.created_at,
    gr.updated_at,
    c.name AS customer_name_detail,
    c.city AS customer_city,
    c.mobile AS customer_mobile,
    c.email AS customer_email,
    i.name AS item_name_detail,
    i.description AS item_description,
    i.active AS item_active
   FROM (((public.goodsreceived_trl grt
     JOIN public.goodsreceived gr ON (((gr.id = grt.gr_id) AND (gr.deleted_at IS NULL))))
     JOIN public.customers c ON ((c.id = gr.customer_id)))
     JOIN public.items i ON ((i.id = grt.item_id)))
  WITH NO DATA;


CREATE MATERIALIZED VIEW public.mv_invoice_list AS
 WITH invoice_qty_agg AS (
         SELECT it.invoice_id,
            COALESCE(sum(DISTINCT grt.qty), (0)::bigint) AS total_qty
           FROM ((public.invoice_trl it
             JOIN public.dispatch_trl dt ON ((dt.id = it.disp_trl_id)))
             JOIN public.goodsreceived_trl grt ON ((grt.id = dt.gr_trl_id)))
          GROUP BY it.invoice_id
        )
 SELECT i.id AS invoice_id,
    i.inv_no,
    i.inv_fin_year,
    i.inv_date,
    i.inv_name,
    i.pricing_mode,
    i.notes,
    i.is_auto_generated,
    i.total,
    i.discount,
    i.labour,
    i.tax_amount,
    i.one_time_charge,
    i.created_by,
    (COALESCE(iqa.total_qty, (0)::bigint))::numeric AS total_qty,
    c.id AS customer_id,
    c.name AS customer_name,
    c.city AS customer_city,
    c.address AS customer_address,
    c.mobile AS customer_phone,
    c.email AS customer_email,
    c.gst AS customer_gst,
    c.active AS customer_active,
    gr.id AS grn_id,
    gr.gr_no,
    gr.registration AS grn_registration,
    gr.date AS grn_date,
    gr.sender_id AS grn_sender_id,
    gr.sender_name AS grn_sender_name,
    gr.supervisor_id AS grn_supervisor_id,
    gr.supervisor_name AS grn_supervisor_name,
    gr.customer_id AS grn_customer_id,
    gr.customer_name AS grn_customer_name,
    ((i.inv_fin_year || '-'::text) || (i.inv_fin_year + 1)) AS financial_year_display
   FROM (((public.invoice i
     JOIN public.customers c ON ((c.id = i.customer_id)))
     JOIN public.goodsreceived gr ON ((gr.id = i.gr_id)))
     LEFT JOIN invoice_qty_agg iqa ON ((iqa.invoice_id = i.id)))
  WHERE (i.deleted_at IS NULL)
  WITH NO DATA;


CREATE TABLE public.order_items (
    id uuid DEFAULT extensions.uuid_generate_v1() NOT NULL,
    order_id uuid NOT NULL,
    order_no text,
    requested_quantity integer NOT NULL,
    fulfilled_quantity integer DEFAULT 0 NOT NULL,
    grn_items_id uuid NOT NULL,
    grn_items_item_id uuid NOT NULL,
    grn_items_item_name text NOT NULL,
    grn_items_package_mark text NOT NULL,
    grn_items_packaging text NOT NULL,
    grn_items_rack text NOT NULL,
    grn_items_weight numeric NOT NULL,
    grn_items_image_url text,
    grns_id uuid NOT NULL,
    grns_gr_no text NOT NULL,
    grns_date timestamp with time zone NOT NULL,
    grns_customer_id uuid NOT NULL,
    grns_customer_name text NOT NULL,
    available_stock_at_order integer DEFAULT 0 NOT NULL,
    current_stock integer,
    item_status text NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    revisions jsonb DEFAULT '[]'::jsonb,
    CONSTRAINT check_fulfilled_quantity CHECK (((fulfilled_quantity >= 0) AND (fulfilled_quantity <= requested_quantity))),
    CONSTRAINT check_requested_quantity CHECK ((requested_quantity > 0)),
    CONSTRAINT chk_order_fulfilled_qty_nonneg CHECK ((fulfilled_quantity >= 0)),
    CONSTRAINT chk_order_requested_qty_positive CHECK ((requested_quantity > 0)),
    CONSTRAINT order_items_item_status_check CHECK ((item_status = ANY (ARRAY['pending'::text, 'partially_fulfilled'::text, 'fulfilled'::text, 'out_of_stock'::text, 'cancelled'::text])))
);


CREATE TABLE public.orders (
    id uuid DEFAULT extensions.uuid_generate_v1() NOT NULL,
    order_no text,
    order_date timestamp with time zone NOT NULL,
    requested_dispatch_date timestamp with time zone NOT NULL,
    status text NOT NULL,
    priority text NOT NULL,
    customer_id uuid NOT NULL,
    customer_name text NOT NULL,
    customer_email text,
    customer_phone text,
    note text,
    is_ignored boolean DEFAULT false NOT NULL,
    ignored_at timestamp with time zone,
    ignored_by uuid,
    ignored_reason text,
    cancelled_at timestamp with time zone,
    cancelled_by uuid,
    cancellation_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    updated_by uuid,
    revisions jsonb DEFAULT '[]'::jsonb,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    CONSTRAINT check_cancelled_reason CHECK (((status <> 'cancelled'::text) OR ((status = 'cancelled'::text) AND (cancellation_reason IS NOT NULL) AND (cancelled_by IS NOT NULL)))),
    CONSTRAINT check_ignored_reason CHECK (((NOT is_ignored) OR (is_ignored AND (ignored_reason IS NOT NULL) AND (ignored_by IS NOT NULL)))),
    CONSTRAINT orders_priority_check CHECK ((priority = ANY (ARRAY['low'::text, 'normal'::text]))),
    CONSTRAINT orders_status_check CHECK ((status = ANY (ARRAY['OPEN'::text, 'DISPATCHED'::text])))
);


CREATE TABLE public.user_profiles (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    auth_user_id uuid NOT NULL,
    name character varying(30),
    display_name character varying(30),
    role public.user_role DEFAULT 'user'::public.user_role NOT NULL,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now(),
    mobile character varying(15) NOT NULL,
    mobile_verified boolean DEFAULT false NOT NULL,
    mobile_verified_at timestamp with time zone,
    CONSTRAINT check_mobile_no_plus_prefix CHECK (((mobile)::text !~~ '+%'::text))
);


CREATE MATERIALIZED VIEW public.mv_orders_list AS
 WITH order_items_data AS (
         SELECT oi.order_id,
            count(*) FILTER (WHERE (oi.item_status = 'pending'::text)) AS total_items,
            COALESCE(sum(oi.requested_quantity) FILTER (WHERE (oi.item_status = 'pending'::text)), (0)::bigint) AS total_quantity,
            jsonb_agg(jsonb_build_object('id', oi.id, 'order_id', oi.order_id, 'requested_quantity', oi.requested_quantity, 'fulfilled_quantity', oi.fulfilled_quantity, 'grn_items_id', oi.grn_items_id, 'grn_items_item_id', oi.grn_items_item_id, 'grn_items_item_name', oi.grn_items_item_name, 'grn_items_package_mark', oi.grn_items_package_mark, 'grn_items_packaging', oi.grn_items_packaging, 'grn_items_rack', oi.grn_items_rack, 'grn_items_weight', oi.grn_items_weight, 'grn_items_image_url', oi.grn_items_image_url, 'grns_id', oi.grns_id, 'grns_gr_no', oi.grns_gr_no, 'grns_date', oi.grns_date, 'grns_customer_id', oi.grns_customer_id, 'grns_customer_name', oi.grns_customer_name, 'available_stock_at_order', oi.available_stock_at_order, 'current_stock', oi.current_stock, 'item_status', oi.item_status, 'sort_order', oi.sort_order, 'created_at', oi.created_at, 'updated_at', oi.updated_at) ORDER BY oi.sort_order, oi.created_at) AS items_jsonb
           FROM public.order_items oi
          GROUP BY oi.order_id
        ), latest_dispatch AS (
         SELECT DISTINCT ON (dispatch.source_order_id) dispatch.source_order_id,
            dispatch.id AS dispatch_id,
            dispatch.disp_no AS dispatch_no,
            dispatch.created_at AS dispatch_created_at
           FROM public.dispatch
          WHERE (dispatch.source_order_id IS NOT NULL)
          ORDER BY dispatch.source_order_id, dispatch.created_at DESC
        )
 SELECT o.id AS order_id,
    o.order_no,
    o.status,
    o.priority,
    o.customer_id,
    o.customer_name,
    o.customer_email,
    o.customer_phone,
    o.is_ignored,
    o.ignored_at,
    o.ignored_by,
    o.ignored_reason,
    o.cancelled_at,
    o.cancelled_by,
    o.cancellation_reason,
    o.created_at,
    o.updated_at,
    o.created_by,
    o.updated_by,
    c.name AS customer_name_detail,
    c.city AS customer_city,
    c.mobile AS customer_mobile,
    c.address AS customer_address,
    up.name AS updated_by_name,
    up.display_name AS updated_by_display_name,
    (COALESCE(oid.total_items, (0)::bigint))::integer AS total_items,
    (COALESCE(oid.total_quantity, (0)::bigint))::numeric AS total_quantity,
    COALESCE(oid.items_jsonb, '[]'::jsonb) AS items_jsonb,
    ld.dispatch_id,
    ld.dispatch_no,
    ld.dispatch_created_at
   FROM ((((public.orders o
     JOIN public.customers c ON ((c.id = o.customer_id)))
     LEFT JOIN order_items_data oid ON ((oid.order_id = o.id)))
     LEFT JOIN public.user_profiles up ON ((up.id = o.updated_by)))
     LEFT JOIN latest_dispatch ld ON ((ld.source_order_id = o.id)))
  WHERE (o.deleted_at IS NULL)
  WITH NO DATA;


CREATE TABLE public.mv_refresh_queue (
    mv_name text NOT NULL,
    needs_refresh boolean DEFAULT false,
    last_refresh timestamp with time zone,
    last_marked_dirty timestamp with time zone
);


CREATE TABLE public.mv_refresh_status (
    mv_name text NOT NULL,
    is_dirty boolean DEFAULT false,
    last_marked_dirty_at timestamp with time zone,
    last_refreshed_at timestamp with time zone
);


CREATE TABLE public.order_number_counter (
    id text DEFAULT 'orderNumber'::text NOT NULL,
    value integer DEFAULT 0 NOT NULL
);


CREATE TABLE public.otp_rate_limits (
    phone_number character varying(15) NOT NULL,
    hourly_count integer DEFAULT 0,
    daily_count integer DEFAULT 0,
    last_reset_hour timestamp with time zone DEFAULT now(),
    last_reset_day timestamp with time zone DEFAULT now(),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now()
);


CREATE TABLE public.otp_verifications (
    id uuid DEFAULT extensions.uuid_generate_v1() NOT NULL,
    phone_number character varying(15) NOT NULL,
    otp_code character varying(6),
    otp_hash character varying(255),
    msg91_request_id character varying(255),
    purpose character varying(50) NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 3 NOT NULL,
    verified boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone DEFAULT (now() + '00:10:00'::interval) NOT NULL,
    verified_at timestamp with time zone,
    user_agent text,
    ip_address inet,
    msg91_status text,
    msg91_response jsonb,
    delivery_status text DEFAULT 'pending'::text,
    otp_code_hash text,
    failed_attempts integer DEFAULT 0,
    locked_until timestamp with time zone,
    CONSTRAINT otp_verifications_purpose_check CHECK (((purpose)::text = ANY (ARRAY[('login'::character varying)::text, ('registration'::character varying)::text, ('phone_verification'::character varying)::text, ('password_reset'::character varying)::text])))
);


CREATE TABLE public.payments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    payment_no character varying(30) NOT NULL,
    payment_date timestamp with time zone NOT NULL,
    customer_id uuid,
    customer_name character varying(200) DEFAULT NULL::character varying,
    supervisor_id uuid,
    supervisor_name character varying(30) DEFAULT NULL::character varying,
    note character varying(800) DEFAULT NULL::character varying,
    payment_mode character varying(12) DEFAULT NULL::character varying,
    bank character varying(50) DEFAULT NULL::character varying,
    cheque_no character varying(12) DEFAULT NULL::character varying,
    online_ref character varying(50) DEFAULT NULL::character varying,
    amount numeric(12,2),
    invoice_id uuid
);


CREATE TABLE public.print_jobs (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    cups_job_id integer,
    job_type character varying(20) NOT NULL,
    document_range_start character varying(50) NOT NULL,
    document_range_end character varying(50) NOT NULL,
    document_count integer,
    user_id uuid NOT NULL,
    user_name character varying(100),
    status character varying(20) DEFAULT 'queued'::character varying NOT NULL,
    error_message text,
    content_size integer,
    printer_name character varying(100),
    submitted_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT print_jobs_job_type_check CHECK (((job_type)::text = ANY (ARRAY[('GRN'::character varying)::text, ('Invoice'::character varying)::text, ('Dispatch'::character varying)::text]))),
    CONSTRAINT print_jobs_status_check CHECK (((status)::text = ANY (ARRAY[('queued'::character varying)::text, ('printing'::character varying)::text, ('completed'::character varying)::text, ('cancelled'::character varying)::text, ('failed'::character varying)::text])))
);


CREATE TABLE public.printer_status (
    printer_name text NOT NULL,
    status text NOT NULL,
    message text,
    last_updated timestamp with time zone DEFAULT now(),
    last_job_id integer,
    last_error text,
    CONSTRAINT printer_status_status_check CHECK ((status = ANY (ARRAY['online'::text, 'offline'::text, 'error'::text, 'busy'::text])))
);


CREATE TABLE public.receipt_voucher_counters (
    financial_year text NOT NULL,
    next_seq bigint DEFAULT 1 NOT NULL,
    CONSTRAINT receipt_voucher_counters_next_seq_under_99999 CHECK ((next_seq <= 99999))
);


CREATE VIEW public.rls_policies_summary AS
 SELECT pg_policies.schemaname,
    pg_policies.tablename,
    pg_policies.policyname,
    pg_policies.permissive,
    pg_policies.roles,
    pg_policies.cmd,
    pg_policies.qual,
    pg_policies.with_check
   FROM pg_policies
  WHERE (pg_policies.schemaname = 'public'::name)
  ORDER BY pg_policies.tablename, pg_policies.policyname;


CREATE TABLE public.secrets_vault (
    id integer NOT NULL,
    service_name character varying(50) NOT NULL,
    credentials jsonb NOT NULL,
    is_active boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now(),
    created_by uuid,
    notes text
);


CREATE SEQUENCE public.secrets_vault_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE public.secrets_vault_id_seq OWNED BY public.secrets_vault.id;


CREATE TABLE public.user_session_activity (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    user_id uuid NOT NULL,
    auth_session_id uuid,
    last_activity_at timestamp with time zone DEFAULT now() NOT NULL,
    ip_address inet,
    user_agent text,
    activity_type character varying(50),
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


CREATE VIEW public.security_metrics AS
 SELECT 'failed_otp_1h'::text AS metric,
    (( SELECT count(*) AS count
           FROM public.otp_verifications
          WHERE ((otp_verifications.verified = false) AND (otp_verifications.created_at > (now() - '01:00:00'::interval)))))::integer AS value
UNION ALL
 SELECT 'failed_otp_24h'::text AS metric,
    (( SELECT count(*) AS count
           FROM public.otp_verifications
          WHERE ((otp_verifications.verified = false) AND (otp_verifications.created_at > (now() - '24:00:00'::interval)))))::integer AS value
UNION ALL
 SELECT 'successful_otp_1h'::text AS metric,
    (( SELECT count(*) AS count
           FROM public.otp_verifications
          WHERE ((otp_verifications.verified = true) AND (otp_verifications.created_at > (now() - '01:00:00'::interval)))))::integer AS value
UNION ALL
 SELECT 'active_sessions'::text AS metric,
    (( SELECT count(*) AS count
           FROM public.user_session_activity
          WHERE (user_session_activity.last_activity_at > (now() - '00:15:00'::interval))))::integer AS value
UNION ALL
 SELECT 'locked_accounts'::text AS metric,
    (( SELECT count(*) AS count
           FROM public.otp_verifications
          WHERE (otp_verifications.locked_until > now())))::integer AS value
UNION ALL
 SELECT 'unique_ips_today'::text AS metric,
    (( SELECT count(DISTINCT otp_verifications.ip_address) AS count
           FROM public.otp_verifications
          WHERE (otp_verifications.created_at > CURRENT_DATE)))::integer AS value;


CREATE TABLE public.sensor_devices (
    id uuid DEFAULT extensions.uuid_generate_v1() NOT NULL,
    device_name character varying(100) NOT NULL,
    mac_address character varying(17),
    location character varying(200),
    active boolean DEFAULT true NOT NULL,
    last_reading_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now(),
    health_status character varying(20) DEFAULT 'unknown'::character varying,
    battery_status character varying(20) DEFAULT 'UNKNOWN'::character varying,
    connectivity_status character varying(20) DEFAULT 'UNKNOWN'::character varying,
    is_stale boolean DEFAULT false,
    alert_config jsonb DEFAULT '{}'::jsonb,
    staleness_threshold_minutes integer DEFAULT 30,
    last_alert_at timestamp with time zone,
    consecutive_failures integer DEFAULT 0,
    deactivated_at timestamp with time zone,
    deactivation_reason text,
    CONSTRAINT chk_battery_status CHECK (((battery_status)::text = ANY (ARRAY[('OK'::character varying)::text, ('LOW'::character varying)::text, ('CRITICAL'::character varying)::text, ('UNKNOWN'::character varying)::text]))),
    CONSTRAINT chk_connectivity_status CHECK (((connectivity_status)::text = ANY (ARRAY[('ONLINE'::character varying)::text, ('OFFLINE'::character varying)::text, ('STALE'::character varying)::text, ('UNKNOWN'::character varying)::text]))),
    CONSTRAINT chk_health_status CHECK (((health_status)::text = ANY (ARRAY[('healthy'::character varying)::text, ('warning'::character varying)::text, ('critical'::character varying)::text, ('offline'::character varying)::text, ('unknown'::character varying)::text])))
);


CREATE VIEW public.sensor_health_dashboard AS
 SELECT ( SELECT count(*) AS count
           FROM public.sensor_devices
          WHERE (sensor_devices.active = true)) AS total_active_sensors,
    ( SELECT count(*) AS count
           FROM public.sensor_devices
          WHERE (((sensor_devices.connectivity_status)::text = 'ONLINE'::text) AND (sensor_devices.active = true))) AS online_sensors,
    ( SELECT count(*) AS count
           FROM public.sensor_devices
          WHERE (((sensor_devices.connectivity_status)::text = 'OFFLINE'::text) AND (sensor_devices.active = true))) AS offline_sensors,
    ( SELECT count(*) AS count
           FROM public.sensor_devices
          WHERE (((sensor_devices.connectivity_status)::text = 'STALE'::text) AND (sensor_devices.active = true))) AS stale_sensors,
    ( SELECT count(*) AS count
           FROM public.sensor_devices
          WHERE (((sensor_devices.battery_status)::text = 'LOW'::text) AND (sensor_devices.active = true))) AS low_battery_count,
    ( SELECT count(*) AS count
           FROM public.sensor_devices
          WHERE (((sensor_devices.battery_status)::text = 'CRITICAL'::text) AND (sensor_devices.active = true))) AS critical_battery_count,
    ( SELECT count(*) AS count
           FROM public.sensor_devices
          WHERE ((sensor_devices.consecutive_failures > 0) AND (sensor_devices.active = true))) AS sensors_with_failures,
    ( SELECT count(*) AS count
           FROM public.sensor_devices
          WHERE (sensor_devices.active = false)) AS inactive_sensors,
    ( SELECT max(sensor_devices.last_reading_at) AS max
           FROM public.sensor_devices
          WHERE (sensor_devices.active = true)) AS most_recent_sync,
    ( SELECT min(sensor_devices.last_reading_at) AS min
           FROM public.sensor_devices
          WHERE ((sensor_devices.active = true) AND (sensor_devices.last_reading_at IS NOT NULL))) AS oldest_sensor_update,
    ( SELECT count(*) AS count
           FROM public.sensor_devices) AS total_sensors_ever_registered;


CREATE TABLE public.sensor_health_events (
    id uuid DEFAULT extensions.uuid_generate_v1() NOT NULL,
    device_id uuid NOT NULL,
    device_mac character varying(17) NOT NULL,
    device_name text NOT NULL,
    event_type text NOT NULL,
    severity text NOT NULL,
    event_message text NOT NULL,
    old_value text,
    new_value text,
    metadata jsonb DEFAULT '{}'::jsonb,
    event_timestamp timestamp with time zone DEFAULT now(),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_event_severity CHECK ((severity = ANY (ARRAY['INFO'::text, 'WARNING'::text, 'ERROR'::text, 'CRITICAL'::text]))),
    CONSTRAINT chk_event_type CHECK ((event_type = ANY (ARRAY['SYNC_OK'::text, 'SYNC_FAILED'::text, 'SENSOR_STALE'::text, 'SENSOR_RECOVERED'::text, 'SENSOR_OFFLINE'::text, 'SENSOR_ONLINE'::text, 'BATTERY_LOW'::text, 'BATTERY_OK'::text, 'BATTERY_CRITICAL'::text, 'SENSOR_REGISTERED'::text, 'SENSOR_DEACTIVATED'::text, 'SENSOR_UPDATED'::text, 'HEALTH_STATUS_CHANGE'::text])))
);


CREATE TABLE public.sensor_readings (
    id uuid DEFAULT extensions.uuid_generate_v1() NOT NULL,
    device_id uuid NOT NULL,
    temperature numeric(5,2) NOT NULL,
    humidity numeric(5,2) NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL
)
WITH (autovacuum_vacuum_threshold='5000', autovacuum_vacuum_scale_factor='0.05', autovacuum_analyze_threshold='1000', autovacuum_analyze_scale_factor='0.02');


CREATE TABLE public.stock_movements (
    id uuid DEFAULT extensions.uuid_generate_v1() NOT NULL,
    gr_trl_id uuid NOT NULL,
    movement_type character varying(20) NOT NULL,
    quantity integer NOT NULL,
    reference_id uuid,
    reference_type character varying(20),
    balance_before integer NOT NULL,
    balance_after integer NOT NULL,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT stock_movements_movement_type_check CHECK (((movement_type)::text = ANY (ARRAY[('dispatch'::character varying)::text, ('return'::character varying)::text, ('adjustment'::character varying)::text])))
);


CREATE TABLE public.system_settings (
    key character varying(100) NOT NULL,
    value text NOT NULL,
    description text,
    updated_at timestamp with time zone DEFAULT now()
);


CREATE TABLE public.tally_contra_vouchers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    voucher_number text NOT NULL,
    voucher_date date NOT NULL,
    from_ledger text NOT NULL,
    to_ledger text NOT NULL,
    amount numeric(14,2) NOT NULL,
    particulars text,
    tally_voucher_id text,
    tally_company text NOT NULL,
    tally_sync_queue_id uuid,
    status text DEFAULT 'queued'::text NOT NULL,
    review_note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT tally_contra_vouchers_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT tally_contra_vouchers_distinct_ledgers CHECK ((from_ledger <> to_ledger)),
    CONSTRAINT tally_contra_vouchers_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'reconciled'::text, 'failed'::text])))
);


CREATE TABLE public.tally_drift_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    entity_type text NOT NULL,
    entity_id uuid NOT NULL,
    voucher_table_id uuid NOT NULL,
    tally_voucher_id text,
    voucher_number text,
    outcome text NOT NULL,
    expected jsonb,
    actual jsonb,
    detected_at timestamp with time zone DEFAULT now() NOT NULL,
    acknowledged_at timestamp with time zone,
    acknowledged_by text,
    notes text
);


CREATE TABLE public.tally_ledger_map (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    customer_id uuid NOT NULL,
    tally_ledger_name character varying(200) NOT NULL,
    tally_company character varying(200) NOT NULL,
    ledger_group character varying(100) DEFAULT 'Sundry Debtors'::character varying NOT NULL,
    gst_number character varying(30),
    auto_created boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


CREATE TABLE public.tally_middleware_status (
    id smallint DEFAULT 1 NOT NULL,
    is_ready boolean DEFAULT false NOT NULL,
    tally_reachable boolean DEFAULT false NOT NULL,
    company_open boolean DEFAULT false NOT NULL,
    company text,
    last_check timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tally_middleware_status_id_check CHECK ((id = 1))
);


CREATE TABLE public.tally_receipt_vouchers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    bank_line_id uuid NOT NULL,
    voucher_number text NOT NULL,
    voucher_date date NOT NULL,
    customer_id uuid NOT NULL,
    bank_account_ledger text NOT NULL,
    amount_received numeric(14,2) NOT NULL,
    tds_amount numeric(14,2) DEFAULT 0 NOT NULL,
    tally_voucher_id text,
    tally_company text NOT NULL,
    allocations jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    last_verified_at timestamp with time zone
);


CREATE TABLE public.tally_sync_attempts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    queue_id uuid NOT NULL,
    entity_type text NOT NULL,
    entity_id uuid NOT NULL,
    voucher_number text,
    remote_id text,
    instance_id text NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    outcome text,
    response_xml text,
    notes text
);


CREATE TABLE public.tally_sync_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    queue_id uuid NOT NULL,
    attempt_number integer NOT NULL,
    status character varying(20) NOT NULL,
    request_xml text,
    response_xml text,
    error_details jsonb,
    duration_ms integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


CREATE TABLE public.tally_sync_queue (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    entity_type character varying(30) NOT NULL,
    entity_id uuid NOT NULL,
    operation character varying(20) NOT NULL,
    status character varying(20) DEFAULT 'pending'::character varying NOT NULL,
    priority integer DEFAULT 5 NOT NULL,
    payload jsonb,
    error_message text,
    retry_count integer DEFAULT 0 NOT NULL,
    max_retries integer DEFAULT 5 NOT NULL,
    next_retry_at timestamp with time zone,
    locked_by character varying(100),
    locked_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    request_xml text,
    response_xml text,
    error_details jsonb,
    CONSTRAINT chk_entity_type CHECK (((entity_type)::text = ANY ((ARRAY['invoice'::character varying, 'payment'::character varying, 'credit_note'::character varying, 'receipt'::character varying, 'contra'::character varying])::text[]))),
    CONSTRAINT chk_operation CHECK (((operation)::text = ANY (ARRAY['create'::text, 'update'::text, 'delete'::text, 'resync'::text]))),
    CONSTRAINT chk_status CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'processing'::character varying, 'confirmed'::character varying, 'failed'::character varying, 'retry'::character varying, 'dead_letter'::character varying])::text[])))
);


CREATE TABLE public.tally_vouchers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    invoice_id uuid NOT NULL,
    tally_voucher_id character varying(100),
    voucher_number character varying(50) NOT NULL,
    voucher_type character varying(50) DEFAULT 'Sales'::character varying NOT NULL,
    voucher_date date NOT NULL,
    tally_company character varying(200) NOT NULL,
    amount numeric(12,2) NOT NULL,
    synced_at timestamp with time zone DEFAULT now() NOT NULL,
    last_verified_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


CREATE TABLE public.test_otp_records (
    phone_number character varying(15) NOT NULL,
    fixed_otp character varying(6),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now()
);


CREATE TABLE public.users_customers_new (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_profile_id uuid NOT NULL,
    customer_id uuid NOT NULL,
    customer_name character varying(80),
    assigned_at timestamp with time zone DEFAULT now(),
    assigned_by uuid,
    active boolean DEFAULT true
);


CREATE VIEW public.user_customer_assignments AS
 SELECT uc.id,
    up.auth_user_id,
    up.mobile AS user_mobile,
    up.name AS user_name,
    up.role AS user_role,
    c.id AS customer_id,
    c.name AS customer_name,
    c.city AS customer_city,
    uc.assigned_at,
    assigner.name AS assigned_by_name,
    uc.active
   FROM (((public.users_customers_new uc
     JOIN public.user_profiles up ON ((uc.user_profile_id = up.id)))
     JOIN public.customers c ON ((uc.customer_id = c.id)))
     LEFT JOIN public.user_profiles assigner ON ((uc.assigned_by = assigner.id)))
  WHERE ((uc.active = true) AND (up.active = true) AND (c.active = true));


