CREATE OR REPLACE VIEW public.stock_summary AS
 SELECT gt.id AS gr_trl_id,
    gt.gr_id,
    g.gr_no,
    g.date AS gr_date,
    g.customer_id,
    c.name AS customer_name,
    gt.item_id,
    gt.item_name,
    gt.packaging,
    gt.qty AS original_qty,
    COALESCE(sum(dt.disp_qty), (0)::bigint) AS total_dispatched,
    gt.stock AS current_stock,
    gt.rack,
    gt.package_mark
   FROM (((public.goodsreceived_trl gt
     JOIN public.goodsreceived g ON ((g.id = gt.gr_id)))
     JOIN public.customers c ON ((c.id = g.customer_id)))
     LEFT JOIN public.dispatch_trl dt ON ((dt.gr_trl_id = gt.id)))
  WHERE (g.customer_id = ANY (
        CASE
            WHEN public.is_admin_or_supervisor() THEN ( SELECT array_agg(customers.id) AS array_agg
               FROM public.customers)
            ELSE public.user_accessible_customers()
        END))
  GROUP BY gt.id, g.id, c.id;


