CREATE POLICY "Admin can update contact submissions" ON public.contact_submissions FOR UPDATE USING ((public.get_current_user_role() = ANY (ARRAY['admin'::public.user_role, 'supervisor'::public.user_role])));


CREATE POLICY "Admin can view contact submissions" ON public.contact_submissions FOR SELECT USING ((public.get_current_user_role() = ANY (ARRAY['admin'::public.user_role, 'supervisor'::public.user_role])));


CREATE POLICY "Admin supervisor counter access" ON public.order_number_counter USING (public.is_admin_or_supervisor());


CREATE POLICY "Admins and supervisors can delete customers" ON public.customers FOR DELETE USING (public.is_admin_or_supervisor());


CREATE POLICY "Admins and supervisors can delete dispatch" ON public.dispatch FOR DELETE USING ((public.is_admin_or_supervisor() OR (customer_id = ANY (public.user_accessible_customers()))));


CREATE POLICY "Admins and supervisors can delete dispatch transactions" ON public.dispatch_trl FOR DELETE USING ((public.is_admin_or_supervisor() OR (EXISTS ( SELECT 1
   FROM public.dispatch d
  WHERE ((d.id = dispatch_trl.disp_id) AND (d.customer_id = ANY (public.user_accessible_customers())))))));


CREATE POLICY "Admins and supervisors can delete goods received transactions" ON public.goodsreceived_trl FOR DELETE USING ((public.is_admin_or_supervisor() OR (EXISTS ( SELECT 1
   FROM public.goodsreceived gr
  WHERE ((gr.id = goodsreceived_trl.gr_id) AND (gr.customer_id = ANY (public.user_accessible_customers())))))));


CREATE POLICY "Admins and supervisors can delete invoice" ON public.invoice FOR DELETE USING ((public.is_admin_or_supervisor() OR (customer_id = ANY (public.user_accessible_customers()))));


