CREATE POLICY users_own_otp_func ON public.otp_verifications FOR SELECT TO authenticated USING (((phone_number)::text = (( SELECT user_profiles.mobile
   FROM public.user_profiles
  WHERE (user_profiles.auth_user_id = ( SELECT auth.uid() AS uid))))::text));


CREATE POLICY users_view_own_assignments_func ON public.users_customers_new FOR SELECT TO authenticated USING ((user_profile_id = ( SELECT user_profiles.id
   FROM public.user_profiles
  WHERE (user_profiles.auth_user_id = ( SELECT auth.uid() AS uid)))));


